// Hyperreal Underground Platform — Step-Printed Commuters & Woman in Mustard Raincoat
// p5.js 2.x + p5.brush (WEBGL)

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Custom brushes for hyperreal details and step-printed pastel/charcoal motion trails
  brush.add("pastel_smudge", {
    type: "default",
    weight: 14,
    scatter: 1.4,
    sharpness: 0.18,
    grain: 14,
    opacity: 42,
    spacing: 0.22,
    pressure: [0.3, 1.2, 0.2],
    rotate: "natural",
    noise: 0.6
  });

  brush.add("motion_chisel", {
    type: "marker",
    weight: 10,
    scatter: 0.35,
    opacity: 32,
    spacing: 0.18,
    pressure: [0.2, 1.0, 0.1],
    rotate: "none",
    markerTip: false,
    noise: 0.25
  });

  brush.add("fine_lash", {
    type: "default",
    weight: 0.85,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 2,
    opacity: 210,
    spacing: 0.08,
    pressure: [1.1, 0.65, 0.05],
    rotate: "natural",
    noise: 0.15
  });

  brush.add("skin_shader", {
    type: "default",
    weight: 4.5,
    scatter: 0.45,
    sharpness: 0.28,
    grain: 9,
    opacity: 36,
    spacing: 0.18,
    pressure: [0.3, 1.0, 0.3],
    rotate: "natural",
    noise: 0.4
  });

  brush.add("custom_field_flow", {
    type: "default",
    weight: 2.2,
    scatter: 0.2,
    sharpness: 0.6,
    grain: 8,
    opacity: 95,
    spacing: 0.15,
    pressure: [0.2, 1.1, 0.1],
    rotate: "natural",
    noise: 0.5
  });

  brush.addField("lateral_rush", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let ny = row / field[0].length;
        let wave = sin(col * 8 + row * 12) * 3.5;
        field[col][row] = wave + (ny - 0.5) * 4;
      }
    }
    return field;
  });
}

// ---------------------------------------------------------------------------
// Polygon & Drawing Helpers
// ---------------------------------------------------------------------------
function polyWash(pts, col, alpha) {
  let p = new brush.Polygon(pts);
  p.wash(col, alpha);
  return p;
}

function polyFill(pts, col, alpha, bleed = 0.12, tex = 0.35) {
  let p = new brush.Polygon(pts);
  p.fill(col, alpha, bleed, tex);
  return p;
}

function polyMass(pts, brushName, col, opts) {
  let p = new brush.Polygon(pts);
  brush.mass(brushName, col, opts);
  p.mass();
  brush.noMass();
  return p;
}

function polyHatch(pts, brushName, col, weight, dist, ang, opts) {
  let p = new brush.Polygon(pts);
  brush.hatchStyle(brushName, col, weight);
  p.hatch(dist, ang, opts);
  brush.noHatch();
  return p;
}

function strokeLine(bName, col, weight, x1, y1, x2, y2) {
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function strokeSpline(bName, col, weight, pts, curv = 0.5) {
  if (pts.length < 2) return;
  brush.set(bName, col, weight);
  brush.spline(pts, curv);
}

// ---------------------------------------------------------------------------
// Main Draw
// ---------------------------------------------------------------------------
function draw() {
  translate(-width / 2, -height / 2);
  background("#0e1715");

  // 1. Subterranean Ceiling, Fluorescent Light Banks & Tiled Station Wall
  drawStationArchitecture();

  // 2. Arriving Train in Mid-Background (Kinetic Metallic & Window Blur)
  drawArrivingTrain();

  // 3. Background Crowd Echoes & Mid-Ground Atmospheric Smudge
  drawBackgroundCrowdEchoes();

  // 4. Hyperreal Step-Printed Commuters (Stuttering Staggered Echoes)
  drawAllStepPrintedCommuters();

  // 5. Lateral Motion Streaks & Charcoal/Pastel Smears Behind Central Subject
  drawMidgroundMotionTrails();

  // 6. Central Focus: Woman in Mustard Raincoat (Razor-Sharp Hyperrealism)
  drawCentralWomanMustardCoat();
  drawCentralWomanHeadAndFace();

  // 7. Foreground Kinetic Streaks & Step-Print Edge Artifacts (Framing the Subject)
  drawForegroundMotionFraming();

  noLoop();
}

// ---------------------------------------------------------------------------
// 1. Station Architecture: Ceiling, Greenish-White Fluorescents, Cream & Ox-Blood Tiles
// ---------------------------------------------------------------------------
function drawStationArchitecture() {
  // Base atmospheric washes
  polyWash([[0, 0], [1200, 0], [1200, 190], [0, 190]], "#0c1b18", 255);
  polyWash([[0, 175], [1200, 175], [1200, 620], [0, 620]], "#efe5ce", 255);
  polyWash([[0, 600], [1200, 600], [1200, 1200], [0, 1200]], "#141216", 255);

  // Ceiling concrete ribs & greenish-emerald ambient glow
  for (let i = 0; i < 16; i++) {
    let y1 = i * 11;
    let col = i % 2 === 0 ? "#112923" : "#183b32";
    polyWash([[0, y1], [1200, y1], [1200, y1 + 14], [0, y1 + 14]], col, 160);
  }

  // Greenish-white fluorescent light wash across ceiling and upper tiles
  polyFill([[0, 10], [1200, 10], [1200, 210], [0, 210]], "#4ade80", 42, 0.35, 0.5);
  polyFill([[80, 20], [1120, 20], [1180, 165], [20, 165]], "#a7f3d0", 65, 0.4, 0.4);

  // Two perspective/horizontal rows of fluorescent light fixtures
  let fixtureRows = [
    { y: 46, h: 18, glowH: 52 },
    { y: 108, h: 24, glowH: 68 }
  ];

  for (let row of fixtureRows) {
    // Dark metal housing
    polyWash([[0, row.y - 10], [1200, row.y - 10], [1200, row.y + row.h + 8], [0, row.y + row.h + 8]], "#0f241f", 210);
    // Emerald-mint outer aura
    polyWash([[0, row.y - row.glowH * 0.5], [1200, row.y - row.glowH * 0.5], [1200, row.y + row.h + row.glowH * 0.5], [0, row.y + row.h + row.glowH * 0.5]], "#34d399", 55);
    polyWash([[0, row.y - 12], [1200, row.y - 12], [1200, row.y + row.h + 12], [0, row.y + row.h + 12]], "#6ee7b7", 95);

    // Individual fluorescent tube segments with step-printed horizontal overlap
    for (let x = -20; x < 1220; x += 155) {
      let w = 132;
      polyWash([[x, row.y], [x + w, row.y], [x + w, row.y + row.h], [x, row.y + row.h]], "#d1fae5", 220);
      polyWash([[x + 6, row.y + 3], [x + w - 6, row.y + 3], [x + w - 6, row.y + row.h - 3], [x + 6, row.y + row.h - 3]], "#f0fdf4", 245);
      // Stuttered step-print light echo
      polyWash([[x + 24, row.y + 2], [x + w + 24, row.y + 2], [x + w + 24, row.y + row.h - 2], [x + 24, row.y + row.h - 2]], "#a7f3d0", 120);

      // Fixture bracket dividers
      polyWash([[x - 14, row.y - 8], [x + 2, row.y - 8], [x + 2, row.y + row.h + 6], [x - 14, row.y + row.h + 6]], "#091714", 230);
    }

    // Crisp core tube streaks
    strokeLine("motion_chisel", "#ffffff", 1.2, 0, row.y + row.h * 0.4, 1200, row.y + row.h * 0.4);
    strokeLine("pastel_smudge", "#6ee7b7", 1.5, 0, row.y + row.h * 0.7, 1200, row.y + row.h * 0.7);
  }

  // --- OX-BLOOD UPPER CORNICE TRIM (y: 166 to 216) ---
  drawOxBloodTrimBand(166, 50, true);

  // --- CREAM SUBWAY TILED WALL (y: 216 to 456) ---
  let tileW = 60;
  let tileH = 26;
  let creamPalette = ["#fbf6e9", "#f4ebd4", "#efe2c4", "#e6d6b5", "#e2f2e8", "#f7f0dd", "#dfd1b4"];

  for (let r = 0; r < 10; r++) {
    let ty = 216 + r * tileH;
    let offset = (r % 2) * (tileW * 0.5);

    // Row 3 & 4 form a decorative ox-blood & cream station border band
    let isTrimRow = (r === 3);

    for (let c = -1; c < 22; c++) {
      let tx = c * tileW + offset;
      if (isTrimRow) {
        let trimCol = (c % 3 === 0) ? "#6e0b19" : "#8f1424";
        polyWash([[tx + 1, ty + 1], [tx + tileW - 1, ty + 1], [tx + tileW - 1, ty + tileH - 1], [tx + 1, ty + tileH - 1]], trimCol, 235);
        // Glazed tile specular highlight
        strokeLine("HB", "#a7f3d0", 0.6, tx + 4, ty + 5, tx + tileW - 6, ty + 5);
      } else {
        let baseCol = random(creamPalette);
        polyWash([[tx + 1, ty + 1], [tx + tileW - 1, ty + 1], [tx + tileW - 1, ty + tileH - 1], [tx + 1, ty + tileH - 1]], baseCol, 225);

        // Subtle greenish-white fluorescent reflection on upper tiles
        if (r < 3 || random() < 0.35) {
          polyWash([[tx + 3, ty + 2], [tx + tileW - 3, ty + 2], [tx + tileW - 3, ty + 9], [tx + 3, ty + 9]], "#d1fae5", random(50, 110));
        }
        // Warm shadow along bottom bevel of ceramic tile
        polyWash([[tx + 2, ty + tileH - 6], [tx + tileW - 2, ty + tileH - 6], [tx + tileW - 2, ty + tileH - 1], [tx + 2, ty + tileH - 1]], "#cbb997", 120);
      }

      // Vertical mortar joint
      strokeLine("2H", "#7c6f5b", 0.55, tx, ty, tx, ty + tileH);
    }
    // Horizontal mortar joint
    strokeLine("HB", "#6b5d4d", 0.65, 0, ty, 1200, ty);
  }

  // --- OX-BLOOD LOWER WAINSCOT BAND (y: 462 to 522) ---
  drawOxBloodTrimBand(462, 60, false);

  // Lower dark cream & soot-stained tiles below wainscot (y: 522 to 640)
  for (let r = 0; r < 4; r++) {
    let ty = 522 + r * 28;
    let offset = (r % 2) * 30;
    for (let c = -1; c < 21; c++) {
      let tx = c * 60 + offset;
      let col = r < 2 ? "#cfc2a9" : "#9c8e78";
      polyWash([[tx + 1, ty + 1], [tx + 59, ty + 1], [tx + 59, ty + 27], [tx + 1, ty + 27]], col, 200);
      strokeLine("2H", "#4a4035", 0.5, tx, ty, tx, ty + 28);
    }
    strokeLine("HB", "#3d332a", 0.6, 0, ty, 1200, ty);
  }

  // Aged station grime & water seepage streaks down the tiles
  for (let i = 0; i < 38; i++) {
    let gx = random(20, 1180);
    let gy1 = random(170, 320);
    let gy2 = gy1 + random(50, 180);
    strokeLine("2B", "#574c3f", random(0.3, 0.7), gx, gy1, gx + random(-4, 4), gy2);
  }
}

function drawOxBloodTrimBand(yStart, h, isUpper) {
  // Rich ox-blood ceramic base
  polyWash([[0, yStart], [1200, yStart], [1200, yStart + h], [0, yStart + h]], "#590711", 250);
  polyWash([[0, yStart + 4], [1200, yStart + 4], [1200, yStart + h - 4], [0, yStart + h - 4]], "#800e1d", 235);
  polyFill([[0, yStart + 6], [1200, yStart + 6], [1200, yStart + h * 0.65], [0, yStart + h * 0.65]], "#a61729", 140, 0.15, 0.4);

  // Tile divisions within the ox-blood band
  let tw = 48;
  for (let x = 0; x < 1200; x += tw) {
    let shade = (int(x / tw) % 2 === 0) ? "#961425" : "#700a17";
    polyWash([[x + 2, yStart + 5], [x + tw - 2, yStart + 5], [x + tw - 2, yStart + h - 5], [x + 2, yStart + h - 5]], shade, 150);
    strokeLine("HB", "#2b0206", 0.65, x, yStart, x, yStart + h);
  }

  // Moulded architectural relief lines & glossy greenish-white fluorescent highlights
  strokeLine("rotring", "#2b0206", 1.2, 0, yStart, 1200, yStart);
  strokeLine("rotring", "#2b0206", 1.2, 0, yStart + h, 1200, yStart + h);
  strokeLine("motion_chisel", "#b91c1c", 0.9, 0, yStart + h * 0.35, 1200, yStart + h * 0.35);

  // Specular green-mint reflections on the curved ox-blood glaze
  for (let i = 0; i < 24; i++) {
    let rx = random(0, 1120);
    let rw = random(35, 130);
    let ry = yStart + (isUpper ? 11 : 14);
    polyWash([[rx, ry], [rx + rw, ry], [rx + rw, ry + 5], [rx, ry + 5]], "#a7f3d0", random(90, 170));
    strokeLine("pen", "#ecfdf5", 0.7, rx + 4, ry + 2, rx + rw - 4, ry + 2);
  }
}

// ---------------------------------------------------------------------------
// 2. Arriving Train (Kinetic Blur & Glowing Windows/Headlights)
// ---------------------------------------------------------------------------
function drawArrivingTrain() {
  // The train barrels across the mid-background (strongest on left & right behind the commuters)
  // Metallic carriage body blur (y: 235 to 495)
  polyWash([[0, 240], [520, 250], [540, 465], [0, 475]], "#1e293b", 165);
  polyWash([[660, 252], [1200, 244], [1200, 472], [650, 465]], "#1e293b", 130);

  // Brushed steel & teal-slate kinetic bands
  let bands = [
    { y: 245, h: 24, col: "#334155", a: 180 },
    { y: 270, h: 115, col: "#0f172a", a: 195 }, // Window band
    { y: 388, h: 26, col: "#991b1b", a: 215 },  // Vivid ox-blood/crimson train livery stripe
    { y: 414, h: 12, col: "#f59e0b", a: 190 },  // Hazard amber-gold trim stripe
    { y: 426, h: 48, col: "#1e293b", a: 190 }
  ];

  for (let b of bands) {
    polyWash([[0, b.y], [545, b.y + 4], [545, b.y + b.h + 4], [0, b.y + b.h]], b.col, b.a);
    polyWash([[655, b.y + 4], [1200, b.y], [1200, b.y + b.h], [655, b.y + b.h + 4]], b.col, b.a * 0.8);
  }

  // Step-printed glowing train windows streaking horizontally
  let winPositions = [-10, 95, 210, 315, 410, 690, 815, 940, 1065];
  for (let wx of winPositions) {
    let ww = random(78, 108);
    let wy = 280;
    let wh = 92;
    // Stuttered window echoes
    for (let s = 0; s < 4; s++) {
      let sx = wx + s * 24;
      let alpha = map(s, 0, 3, 155, 45);
      let wCol = s % 2 === 0 ? "#a7f3d0" : "#fde68a";
      polyWash([[sx, wy], [sx + ww, wy], [sx + ww - 4, wy + wh], [sx - 4, wy + wh]], wCol, alpha);
    }
    // Bright fluorescent interior core of train window
    polyWash([[wx + 12, wy + 8], [wx + ww - 8, wy + 8], [wx + ww - 10, wy + 34], [wx + 10, wy + 34]], "#ecfdf5", 190);
    // Window frame mullions blurred
    strokeLine("charcoal", "#0f172a", 1.4, wx, wy, wx + ww + 40, wy);
    strokeLine("charcoal", "#0f172a", 1.4, wx, wy + wh, wx + ww + 40, wy + wh);
  }

  // Blazing train headlights & destination indicator smearing around x = 440..545 and x = 670..780
  let headlights = [
    { x: 430, y: 392, w: 95, h: 28, c1: "#fef08a", c2: "#ffffff" },
    { x: 350, y: 396, w: 80, h: 22, c1: "#fdba74", c2: "#fef9c3" },
    { x: 685, y: 392, w: 110, h: 24, c1: "#6ee7b7", c2: "#ecfdf5" }
  ];
  for (let hl of headlights) {
    polyFill([[hl.x - 30, hl.y - 12], [hl.x + hl.w + 40, hl.y - 12], [hl.x + hl.w + 40, hl.y + hl.h + 12], [hl.x - 30, hl.y + hl.h + 12]], hl.c1, 110, 0.35, 0.3);
    polyWash([[hl.x, hl.y], [hl.x + hl.w, hl.y], [hl.x + hl.w, hl.y + hl.h], [hl.x, hl.y + hl.h]], hl.c2, 235);
    strokeLine("pastel_smudge", hl.c1, 1.8, hl.x - 80, hl.y + hl.h * 0.5, hl.x + hl.w + 90, hl.y + hl.h * 0.5);
  }
}

// ---------------------------------------------------------------------------
// 3. Background Crowd Silhouettes & Echoes
// ---------------------------------------------------------------------------
function drawBackgroundCrowdEchoes() {
  // Distant commuters along the platform edge (y: 350 to 560)
  let bgFigures = [
    { x: 85, y: 405, r: 38, coat: "#1e1b4b", skin: "#f4a28c", dir: -1 },
    { x: 215, y: 390, r: 35, coat: "#3b0764", skin: "#e89980", dir: 1 },
    { x: 435, y: 395, r: 34, coat: "#111827", skin: "#eab69f", dir: -1 },
    { x: 755, y: 392, r: 35, coat: "#450a0a", skin: "#f2a68d", dir: 1 },
    { x: 965, y: 385, r: 38, coat: "#0f2926", skin: "#e5987f", dir: 1 },
    { x: 1115, y: 400, r: 40, coat: "#1e1b4b", skin: "#f3b096", dir: 1 }
  ];

  for (let f of bgFigures) {
    for (let s = 3; s >= 0; s--) {
      let sx = f.x + s * f.dir * 26;
      let sy = f.y + (s % 2 === 0 ? -3 : 3);
      let alpha = map(s, 0, 3, 190, 60);

      // Shoulders
      polyWash([
        [sx - f.r * 1.8, sy + f.r * 0.8],
        [sx + f.r * 1.8, sy + f.r * 0.8],
        [sx + f.r * 2.2, sy + f.r * 3.8],
        [sx - f.r * 2.2, sy + f.r * 3.8]
      ], f.coat, alpha);

      // Head oval
      polyWash([
        [sx - f.r * 0.7, sy - f.r * 0.8],
        [sx + f.r * 0.7, sy - f.r * 0.8],
        [sx + f.r * 0.8, sy + f.r * 0.5],
        [sx - f.r * 0.6, sy + f.r * 0.9],
        [sx - f.r * 0.8, sy + f.r * 0.5]
      ], f.skin, alpha);

      // Hair & fluorescent rim highlight
      polyWash([
        [sx - f.r * 0.75, sy - f.r * 0.95],
        [sx + f.r * 0.75, sy - f.r * 0.95],
        [sx + f.r * 0.8, sy - f.r * 0.2],
        [sx - f.r * 0.8, sy - f.r * 0.2]
      ], "#17131a", alpha + 20);
      strokeLine("HB", "#a7f3d0", 0.9, sx - f.r * 0.6, sy - f.r * 0.95, sx + f.r * 0.6, sy - f.r * 0.95);
    }
  }
}

// ---------------------------------------------------------------------------
// 4. Hyperreal Step-Printed Commuters (Stuttering Staggered Echoes)
// ---------------------------------------------------------------------------
