    skinBase: "#f5b89c", skinMid: "#d46a56", skinShadow: "#4a151e",
    skinGhost: "#2dd4bf", lipCol: "#9f1239", irisCol: "#78350f",
    hairCol: "#0f0e13", coatCol: "#1c1917", scarfCol: "#b91c1c"
  });

  // Commuter 6: Lower-Right Foreground Rush
  drawStepPrintedCommuter({
    cx: 1035, cy: 855, scale: 1.06,
    turn: 0.36,
    steps: 5, dx: 35, dy: 4,
    skinBase: "#f7c4ad", skinMid: "#de7563", skinShadow: "#541924",
    skinGhost: "#6ee7b7", lipCol: "#e11d48", irisCol: "#0284c7",
