function drawStepPrintedCommuter(cfg) {
  let { cx, cy, scale: sc, turn, steps, dx, dy } = cfg;

  // First: draw trailing pastel & charcoal smudge ribbons connecting the entire path of motion
  let totalSpanX = (steps - 1) * dx;
  let totalSpanY = (steps - 1) * dy;

  // Coat & shoulder motion mass
  polyMass([
    [cx - 110 * sc, cy + 95 * sc],
    [cx + totalSpanX + 110 * sc, cy + totalSpanY + 95 * sc],
    [cx + totalSpanX + 145 * sc, cy + totalSpanY + 340 * sc],
    [cx - 145 * sc, cy + 340 * sc]
  ], "pastel_smudge", cfg.coatCol, { precision: 0.25, strength: 0.65, gradient: 0.5, outline: false });

  // Horizontal skin & shadow smudge wake
  polyWash([
    [cx, cy - 82 * sc],
    [cx + totalSpanX, cy + totalSpanY - 82 * sc],
    [cx + totalSpanX, cy + totalSpanY + 105 * sc],
    [cx, cy + 105 * sc]
  ], cfg.skinMid, 85);

  polyWash([
    [cx, cy - 35 * sc],
    [cx + totalSpanX, cy + totalSpanY - 35 * sc],
    [cx + totalSpanX, cy + totalSpanY + 55 * sc],
    [cx, cy + 55 * sc]
  ], cfg.skinGhost, 48);

  // Draw from furthest fading echo (s = steps - 1) to sharpest anchor frame (s = 0)
  for (let s = steps - 1; s >= 0; s--) {
    let jitterY = (s % 2 === 0 ? -1 : 1) * (s * 1.4);
    let sx = cx + s * dx;
    let sy = cy + s * dy + jitterY;
    let t = s / Math.max(1, steps - 1); // 0 = sharpest, 1 = most faded

    let alphaBase = map(t, 0, 1, 235, 38);
    let shiftX = turn * 26 * sc; // Three-quarter perspective offset of facial centerline

    // 1. Coat & Scarf Echo
    if (s % 2 === 0 || s <= 2) {
      polyWash([
        [sx - 125 * sc, sy + 115 * sc],
        [sx + 125 * sc, sy + 115 * sc],
        [sx + 160 * sc, sy + 330 * sc],
        [sx - 160 * sc, sy + 330 * sc]
      ], cfg.coatCol, alphaBase * 0.85);

      // Scarf / Collar fold
      polyWash([
        [sx - 68 * sc, sy + 92 * sc],
        [sx + 68 * sc, sy + 92 * sc],
        [sx + 82 * sc, sy + 155 * sc],
        [sx - 82 * sc, sy + 155 * sc]
      ], cfg.scarfCol, alphaBase * 0.8);
    }

    // 2. Cranium & Jaw Silhouette
    let headPts = [
      [sx - 68 * sc, sy - 65 * sc],
      [sx - 35 * sc, sy - 98 * sc],
      [sx + 35 * sc, sy - 98 * sc],
      [sx + 68 * sc, sy - 65 * sc],
      [sx + 72 * sc, sy - 10 * sc],
      [sx + 58 * sc, sy + 52 * sc],
      [sx + 28 * sc + shiftX * 0.4, sy + 95 * sc],
      [sx + shiftX * 0.5, sy + 108 * sc], // Chin
      [sx - 28 * sc + shiftX * 0.4, sy + 95 * sc],
      [sx - 58 * sc, sy + 52 * sc],
      [sx - 72 * sc, sy - 10 * sc]
    ];

    // Alternate echoes between warm flesh, saturated coral midtones, and fluorescent mint/cyan afterimage
    let faceCol = s === 0 ? cfg.skinBase : (s % 2 === 1 ? cfg.skinMid : cfg.skinGhost);
    polyWash(headPts, faceCol, alphaBase * (s === 0 ? 0.95 : 0.58));

    // Cheekbone & temple shadow plane
    let shadowSide = turn < 0 ? 1 : -1;
    polyWash([
      [sx + shiftX, sy - 50 * sc],
      [sx + shadowSide * 68 * sc, sy - 45 * sc],
      [sx + shadowSide * 56 * sc, sy + 55 * sc],
      [sx + shiftX * 0.5, sy + 105 * sc],
      [sx + shiftX * 0.6, sy + 35 * sc]
    ], cfg.skinShadow, alphaBase * 0.55);

    // Fluorescent forehead & cheekbone highlight
    if (s <= 3) {
      polyWash([
        [sx + shiftX - 32 * sc, sy - 62 * sc],
        [sx + shiftX + 32 * sc, sy - 62 * sc],
        [sx + shiftX + 26 * sc, sy - 30 * sc],
        [sx + shiftX - 26 * sc, sy - 30 * sc]
      ], "#d1fae5", alphaBase * 0.48);
    }

    // 3. Hair Mass
    polyWash([
      [sx - 74 * sc, sy - 25 * sc],
      [sx - 68 * sc, sy - 85 * sc],
      [sx - 25 * sc, sy - 115 * sc],
      [sx + 35 * sc, sy - 115 * sc],
      [sx + 72 * sc, sy - 82 * sc],
      [sx + 76 * sc, sy - 20 * sc],
      [sx + 52 * sc, sy - 58 * sc],
      [sx + shiftX, sy - 68 * sc],
      [sx - 52 * sc, sy - 58 * sc]
    ], cfg.hairCol, alphaBase * 0.92);

    // 4. Stuttering Eyes, Eyebrows, Nose & Mouth (This creates the unmistakable step-printed face effect)
    let eyeY = sy - 14 * sc;
    let eyeLX = sx + shiftX - 30 * sc;
    let eyeRX = sx + shiftX + 30 * sc;
    let eyeW = 17 * sc;
    let eyeH = 7.5 * sc;

    // Eye socket hollows
    polyWash([
      [eyeLX - eyeW, eyeY - eyeH * 1.6],
      [eyeLX + eyeW, eyeY - eyeH * 1.6],
      [eyeLX + eyeW, eyeY + eyeH * 1.4],
      [eyeLX - eyeW, eyeY + eyeH * 1.4]
    ], cfg.skinShadow, alphaBase * 0.65);

    polyWash([
      [eyeRX - eyeW, eyeY - eyeH * 1.6],
      [eyeRX + eyeW, eyeY - eyeH * 1.6],
      [eyeRX + eyeW, eyeY + eyeH * 1.4],
      [eyeRX - eyeW, eyeY + eyeH * 1.4]
    ], cfg.skinShadow, alphaBase * 0.65);

    // Sclera & Iris for both eyes in every step echo
    for (let ex of [eyeLX, eyeRX]) {
      polyWash([
        [ex - eyeW * 0.85, eyeY],
        [ex - eyeW * 0.3, eyeY - eyeH * 0.8],
        [ex + eyeW * 0.3, eyeY - eyeH * 0.8],
        [ex + eyeW * 0.85, eyeY],
        [ex + eyeW * 0.3, eyeY + eyeH * 0.7],
        [ex - eyeW * 0.3, eyeY + eyeH * 0.7]
      ], "#e2f1ec", alphaBase * 0.85);

      // Iris & Pupil
      let ix = ex + turn * 4 * sc;
      polyWash([
        [ix - eyeH * 0.75, eyeY - eyeH * 0.7],
        [ix + eyeH * 0.75, eyeY - eyeH * 0.7],
        [ix + eyeH * 0.75, eyeY + eyeH * 0.7],
        [ix - eyeH * 0.75, eyeY + eyeH * 0.7]
      ], s <= 1 ? cfg.irisCol : "#1e1b24", alphaBase * 0.95);

      // Upper lid & eyebrow line
      let lidWeight = map(t, 0, 1, 1.15, 0.45) * sc;
      strokeSpline("2B", "#0f0a0e", lidWeight, [
        [ex - eyeW * 0.95, eyeY + 1 * sc],
        [ex, eyeY - eyeH * 0.95],
        [ex + eyeW * 0.95, eyeY + 1 * sc]
      ], 0.5);

      strokeSpline("charcoal", cfg.hairCol, lidWeight * 1.2, [
        [ex - eyeW * 1.05, eyeY - eyeH * 1.8],
        [ex, eyeY - eyeH * 2.3],
        [ex + eyeW * 1.1, eyeY - eyeH * 1.6]
      ], 0.4);

      // Catchlight dot on sharpest echoes
      if (s <= 2) {
        strokeLine("rotring", "#ffffff", 1.1 * sc, ix - 2 * sc, eyeY - 2 * sc, ix + 1 * sc, eyeY - 2 * sc);
      }
    }

    // Nose Bridge, Tip & Nostrils
    let noseTopX = sx + shiftX;
    let noseTipX = sx + shiftX * 1.38;
    let noseTipY = sy + 32 * sc;

    // Nasal shadow plane
    polyWash([
      [noseTopX, eyeY - 4 * sc],
      [noseTipX, noseTipY],
      [noseTipX - Math.sign(turn || 1) * 18 * sc, noseTipY + 6 * sc],
      [noseTopX - Math.sign(turn || 1) * 12 * sc, eyeY + 4 * sc]
    ], cfg.skinShadow, alphaBase * 0.65);

    // Nasal bridge highlight
    strokeLine("HB", "#ecfdf5", 0.9 * sc, noseTopX + 2 * sc, eyeY, noseTipX + 2 * sc, noseTipY - 2 * sc);
    // Nostril dark accents
    strokeLine("2B", "#1f080d", 1.1 * sc, noseTipX - 11 * sc, noseTipY + 4 * sc, noseTipX - 3 * sc, noseTipY + 5 * sc);
    strokeLine("2B", "#1f080d", 1.1 * sc, noseTipX + 3 * sc, noseTipY + 5 * sc, noseTipX + 11 * sc, noseTipY + 4 * sc);

    // Lips (Upper & Lower Vermilion repeating in stuttered echoes)
    let mouthX = sx + shiftX * 1.15;
    let mouthY = sy + 64 * sc;
    let mouthW = 24 * sc;

    polyWash([
      [mouthX - mouthW, mouthY],
      [mouthX - mouthW * 0.35, mouthY - 8 * sc],
      [mouthX, mouthY - 5 * sc],
      [mouthX + mouthW * 0.35, mouthY - 8 * sc],
      [mouthX + mouthW, mouthY],
      [mouthX, mouthY + 2 * sc]
    ], cfg.lipCol, alphaBase * 0.88);

    polyWash([
      [mouthX - mouthW * 0.85, mouthY + 1 * sc],
      [mouthX + mouthW * 0.85, mouthY + 1 * sc],
      [mouthX + mouthW * 0.45, mouthY + 11 * sc],
      [mouthX - mouthW * 0.45, mouthY + 11 * sc]
    ], "#fb7185", alphaBase * 0.78);

    strokeSpline("2B", "#2a0810", map(t, 0, 1, 1.0, 0.4) * sc, [
      [mouthX - mouthW, mouthY],
      [mouthX, mouthY + 1.5 * sc],
      [mouthX + mouthW, mouthY]
    ], 0.4);

    // 5. Horizontal Charcoal & Pastel Dissolve Trails connecting this echo to the next
    if (s > 0) {
      let prevX = cx + (s - 1) * dx;
      let prevY = cy + (s - 1) * dy;
      strokeLine("charcoal", "#18131a", 0.75 * sc, eyeLX, eyeY, prevX + shiftX - 30 * sc, prevY - 14 * sc);
      strokeLine("charcoal", "#18131a", 0.75 * sc, eyeRX, eyeY, prevX + shiftX + 30 * sc, prevY - 14 * sc);
      strokeLine("cpencil", cfg.lipCol, 0.85 * sc, mouthX, mouthY, prevX + shiftX * 1.15, prevY + 64 * sc);
      strokeLine("pastel_smudge", cfg.skinMid, 0.9 * sc, sx, sy + 12 * sc, prevX, prevY + 12 * sc);
    }

    // Fine anatomical cross-hatching on the primary anchor face (s === 0 and s === 1)
    if (s <= 1) {
      polyHatch([
        [sx - 55 * sc, sy - 20 * sc],
        [sx + 55 * sc, sy - 20 * sc],
        [sx + 45 * sc, sy + 85 * sc],
        [sx - 45 * sc, sy + 85 * sc]
      ], "2H", cfg.skinShadow, 0.45, 7, 15, { rand: 0.08 });
    }
  }

  // Final horizontal charcoal & spray dissolution streaks flying off the trailing echo
  let tailX = cx + (steps - 1) * dx;
  let tailY = cy + (steps - 1) * dy;
  let trailDir = Math.sign(dx);
  for (let i = 0; i < 28; i++) {
    let ly = tailY + random(-95 * sc, 210 * sc);
    let lx1 = cx + random(-30 * sc, 30 * sc);
    let lx2 = tailX + trailDir * random(40, 175) * sc;
    let bType = i % 3 === 0 ? "charcoal" : (i % 3 === 1 ? "cpencil" : "HB");
    let bCol = i % 4 === 0 ? cfg.skinGhost : (i % 4 === 1 ? cfg.lipCol : (i % 4 === 2 ? "#141117" : cfg.skinMid));
    strokeLine(bType, bCol, random(0.4, 1.3), lx1, ly, lx2, ly + random(-6, 6));
  }
}

// ---------------------------------------------------------------------------
// 5. Lateral Motion Streaks & Vector Field Flows Behind Central Subject
// ---------------------------------------------------------------------------
function drawMidgroundMotionTrails() {
  // Vector-field driven charcoal & pastel motion currents across the platform
  brush.field("lateral_rush");
  let streakColors = ["#6ee7b7", "#a7f3d0", "#991b1b", "#f59e0b", "#111827", "#f43f5e", "#e2e8f0", "#0f172a"];

  for (let i = 0; i < 95; i++) {
    let sy = random(185, 1120);
    // Keep the immediate center face zone cleaner so the central woman pops with razor sharpness
    let sx = random(0, 1200);
    if (sx > 440 && sx < 760 && sy > 280 && sy < 610) {
      sx = sx < 600 ? random(20, 430) : random(770, 1180);
    }
    let len = random(90, 280);
    let col = random(streakColors);
    let bName = i % 4 === 0 ? "pastel_smudge" : (i % 3 === 0 ? "charcoal" : "custom_field_flow");
    let wt = bName === "pastel_smudge" ? random(0.5, 1.2) : random(0.4, 1.1);
    brush.set(bName, col, wt);
    brush.flowLine(sx, sy, len, random() < 0.5 ? 0 : 180);
  }
  brush.noField();

  // Crisp step-printed horizontal light bars & charcoal smears across left and right flanks
  for (let i = 0; i < 65; i++) {
    let y = random(210, 1150);
    let isLeft = i % 2 === 0;
    let x1 = isLeft ? random(0, 380) : random(760, 1050);
    let x2 = x1 + (isLeft ? random(80, 260) : random(90, 280));
    let col = i % 5 === 0 ? "#a7f3d0" : (i % 5 === 1 ? "#881337" : (i % 5 === 2 ? "#eab308" : "#18181b"));
    strokeLine(i % 3 === 0 ? "motion_chisel" : "charcoal", col, random(0.4, 1.3), x1, y, x2, y);
  }
}

