function drawStitchedSeam(x1, y1, x2, y2, step, darkCol, lightCol) {
  let d = dist(x1, y1, x2, y2);
  let n = Math.floor(d / step);
  for (let i = 0; i < n; i++) {
    let t1 = i / n;
    let t2 = (i + 0.58) / n;
    let sx1 = lerp(x1, x2, t1);
    let sy1 = lerp(y1, y2, t1);
    let sx2 = lerp(x1, x2, t2);
    let sy2 = lerp(y1, y2, t2);
    strokeLine("rotring", darkCol, 0.85, sx1, sy1, sx2, sy2);
    strokeLine("fine_lash", lightCol, 0.6, sx1 + 0.8, sy1, sx2 + 0.8, sy2);
  }
}

function drawHyperrealButton(cx, cy, r, threadAngle, hasButtonhole) {
  // 1. Stitched Horizontal Buttonhole Slit & Bar-Tack
  if (hasButtonhole) {
    let bhW = r * 1.55;
    polyWash([[cx - bhW, cy - 3.5], [cx + bhW * 0.75, cy - 3.5], [cx + bhW * 0.75, cy + 3.5], [cx - bhW, cy + 3.5]], "#3b1502", 225);
    // Buttonhole purl stitches
    for (let bx = cx - bhW; bx <= cx + bhW * 0.75; bx += 2.8) {
      strokeLine("fine_lash", "#92400e", 0.75, bx, cy - 4.5, bx, cy - 1.5);
      strokeLine("fine_lash", "#92400e", 0.75, bx, cy + 1.5, bx, cy + 4.5);
      strokeLine("fine_lash", "#fde047", 0.5, bx + 0.6, cy - 4.2, bx + 0.6, cy - 2.0);
    }
  }

  // 2. Cast Drop Shadow on Mustard Fabric
  let shadowPts = [];
  for (let a = 0; a < 360; a += 20) {
    shadowPts.push([cx + 3 + cos(a) * (r + 2.5), cy + 5.5 + sin(a) * (r + 2.5)]);
  }
  polyWash(shadowPts, "#290f02", 225);

  // 3. Outer Tortoiseshell / Horn Button Rim
  let outerPts = [];
  for (let a = 0; a < 360; a += 15) {
    outerPts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  polyWash(outerPts, "#271004", 252);

  // Marbled amber horn highlights on outer rim
  let amberArc1 = [];
  for (let a = -50; a <= 70; a += 15) {
    amberArc1.push([cx + cos(a) * (r * 0.94), cy + sin(a) * (r * 0.94)]);
  }
  for (let a = 70; a >= -50; a -= 15) {
    amberArc1.push([cx + cos(a) * (r * 0.68), cy + sin(a) * (r * 0.68)]);
  }
  polyWash(amberArc1, "#b45309", 215);

  // 4. Recessed Inner Dish of Button
  let innerR = r * 0.68;
  let innerPts = [];
  for (let a = 0; a < 360; a += 18) {
    innerPts.push([cx + cos(a) * innerR, cy + sin(a) * innerR]);
  }
  polyWash(innerPts, "#170902", 248);

  // Inner dish lower-right warm reflection
  let dishHighlight = [];
  for (let a = 15; a <= 135; a += 20) {
    dishHighlight.push([cx + cos(a) * (innerR * 0.92), cy + sin(a) * (innerR * 0.92)]);
  }
  for (let a = 135; a >= 15; a -= 20) {
    dishHighlight.push([cx + cos(a) * (innerR * 0.58), cy + sin(a) * (innerR * 0.58)]);
  }
  polyWash(dishHighlight, "#d97706", 190);

  // Crisp outer & inner rim outlines
  brush.set("rotring", "#0f0501", 0.95);
  brush.arc(cx, cy, r, 0, 360);
  brush.set("rotring", "#451a03", 0.8);
  brush.arc(cx, cy, innerR, 0, 360);

  // Specular greenish-white fluorescent catchlight on upper-left rim
  brush.set("rotring", "#ecfdf5", 1.15);
  brush.arc(cx, cy, r * 0.86, 200, 265);
  brush.set("fine_lash", "#fef08a", 0.95);
  brush.arc(cx, cy, innerR * 0.95, 25, 115);

  // 5. Four Thread Holes & Cross-Stitched Threads
  let holeDist = r * 0.30;
  let holes = [];
  for (let i = 0; i < 4; i++) {
    let ang = threadAngle + 45 + i * 90;
    let hx = cx + cos(ang) * holeDist;
    let hy = cy + sin(ang) * holeDist;
    holes.push([hx, hy]);

    // Dark hole cavity
    let hPts = [];
    for (let a = 0; a < 360; a += 45) {
      hPts.push([hx + cos(a) * (r * 0.13), hy + sin(a) * (r * 0.13)]);
    }
    polyWash(hPts, "#050200", 255);
  }

  // Criss-crossed sewing threads binding the button
  let pairs = [[0, 2], [1, 3]];
  for (let [i1, i2] of pairs) {
    let [x1, y1] = holes[i1];
    let [x2, y2] = holes[i2];
    strokeLine("rotring", "#78350f", 1.5, x1, y1, x2, y2);
    strokeLine("fine_lash", "#facc15", 1.05, x1 - 0.5, y1 - 0.5, x2 - 0.5, y2 - 0.5);
    strokeLine("fine_lash", "#fef9c3", 0.65, x1 + 0.5, y1 - 0.5, x2 + 0.5, y2 - 0.5);
  }
}

