// Hyperrealist Desert Highway & Fata Morgana Tanker
// Rendered with p5.js v2 & p5.brush

const X0 = 40;
const X1 = 1160;
const Y0 = 150;
const Y1 = 1050;
const PW = X1 - X0;
const PH = Y1 - Y0;
const HY = 735; // Horizon pushed into the lower third
const VPX = 600;
const VPY = 735;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(88103);

  // Scale built-in brushes first
  brush.scaleBrushes(3);

  // Custom airbrush & hyperrealist detailing brushes
  brush.add("airbrush", {
    type: "spray",
    weight: 22,
    scatter: 4.2,
    opacity: 16,
    spacing: 0.35,
    pressure: [0.3, 1.0, 0.3]
  });

  brush.add("fineSpray", {
    type: "spray",
    weight: 9,
    scatter: 2.2,
    opacity: 22,
    spacing: 0.3,
    pressure: [0.4, 1.0, 0.4]
  });

  brush.add("hazeBand", {
    type: "default",
    weight: 3.2,
    scatter: 0.45,
    sharpness: 0.12,
    grain: 7,
    opacity: 42,
    spacing: 0.22,
    pressure: [0.15, 1.0, 0.15],
    noise: 0.35
  });

  brush.add("chromeBar", {
    type: "marker",
    weight: 2.2,
    scatter: 0.02,
    opacity: 145,
    spacing: 0.15,
    pressure: [0.85, 1.0, 0.85],
    markerTip: false,
    noise: 0.05
  });

  brush.add("microPen", {
    type: "default",
    weight: 0.24,
    scatter: 0.01,
    sharpness: 0.96,
    grain: 2,
    opacity: 220,
    spacing: 0.1,
    pressure: [0.8, 1.0, 0.8],
    noise: 0.1
  });

  // Custom heat-wobble vector field for mirage and distant shimmer
  brush.addField("heatWave", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col / field.length;
        let ny = row / field[0].length;
        let wob = Math.sin(nx * 24 + ny * 45) * 4.5 + (noise(nx * 6, ny * 18) - 0.5) * 8;
        field[col][row] = wob;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#efe8da"); // Warm museum rag paper ground

  // Subtle paper Undertone inside plate
  washRect(X0, Y0, PW, PH, "#e9dfcf", 255);

  // Clip all painting and spray operations cleanly to the panoramic plate
  brush.clip([X0, Y0, X1, Y1]);

  // 1. BLEACHED CERULEAN-TO-BONE DUSKY TWILIGHT SKY
  renderSkyGradient();

  // 2. DISTANT DESERT MESAS & SHEARED HORIZON MIRAGE BANDS
  renderDistantDesertAndHorizonMirage();

  // 3. HIGHWAY PERSPECTIVE, INFERIOR ROAD MIRAGE & FOREGROUND ASPHALT CRACKS
  renderHighwayAndForeground();

  // 4. SUPERIOR MIRAGE: INVERTED, STRETCHED, HORIZONTALLY SHEARED DOUBLE
  renderSuperiorMirageTanker();

  // 5. THE CHROME FUEL TANKER (HYPERREAL GRILLE, RIVETS, CYLINDER & HEADLIGHTS)
  renderRealChromeTanker();

  // 6. FOREGROUND MICRO-CRACKS, RIVET SPECULARS & SHIMMER OVERLAY
  renderForegroundHyperDetails();

  brush.noClip();

  // 7. ARCHIVAL PLATE BORDER & REGISTRATION TICKS
  renderPlateBorder();

  noLoop();
}

// =============================================================================
// GEOMETRY & WASH HELPERS
// =============================================================================

function washRect(x, y, w, h, col, alpha = 200) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, alpha);
  brush.rect(x, y, w, h, "corner");
  brush.noWash();
}

function washQuad(x1, y1, x2, y2, x3, y3, x4, y4, col, alpha = 200) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, alpha);
  brush.beginShape(0);
  brush.vertex(x1, y1);
  brush.vertex(x2, y2);
  brush.vertex(x3, y3);
  brush.vertex(x4, y4);
  brush.endShape(true);
  brush.noWash();
}

function washPoly(pts, col, alpha = 200, curvature = 0) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, alpha);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function roadLeftEdge(y) {
  let t = constrain((y - VPY) / (Y1 - VPY), 0, 1);
  return lerp(VPX - 18, 95, pow(t, 1.04));
}

function roadRightEdge(y) {
  let t = constrain((y - VPY) / (Y1 - VPY), 0, 1);
  return lerp(VPX + 18, 1105, pow(t, 1.04));
}

function roadCenterX(y) {
  let t = constrain((y - VPY) / (Y1 - VPY), 0, 1);
  // Slight heat wobble near the horizon that stabilizes toward the viewer
  let heatWobble = (1 - t) * (1 - t) * sin(y * 4.5) * 6;
  return lerp(VPX - 2, 575, t) + heatWobble;
}

// =============================================================================
// 1. SKY GRADIENT (BLEACHED CERULEAN TO BONE WITH DUSKY TWILIGHT OVERTONES)
// =============================================================================

function renderSkyGradient() {
  const skyStops = [
    { y: 150, col: "#1f3247" }, // Deep dusky twilight cerulean
    { y: 205, col: "#294159" },
    { y: 265, col: "#36536d" },
    { y: 330, col: "#476881" },
    { y: 395, col: "#5d7e95" },
    { y: 460, col: "#7695a8" }, // Bleached cerulean
    { y: 520, col: "#92acb9" },
    { y: 575, col: "#aebfc5" },
    { y: 625, col: "#c7cecc" }, // Cool bone-ash transition
    { y: 665, col: "#dcd7c9" }, // Bleached desert bone
    { y: 700, col: "#eadfcd" }, // Luminous bone heat band
    { y: 722, col: "#dfc7b3" }, // Dusky twilight peach-bone
    { y: 742, col: "#c4a598" }  // Mauve-ochre horizon inversion
  ];

  // Layered solid wash strips for seamless gradient base
  let numBands = 75;
  for (let i = 0; i < numBands; i++) {
    let t0 = i / numBands;
    let t1 = (i + 1.6) / numBands;
    let yA = lerp(Y0, HY + 12, t0);
    let yB = lerp(Y0, HY + 12, t1);
    let ym = (yA + yB) * 0.5;

    let c = sampleColorStops(skyStops, ym);
    washRect(X0, yA, PW, yB - yA + 2, c, 155);
  }

  // Soft watercolor bleed passes in key atmospheric zones
  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.32, 0.12);

  brush.fill("#233950", 65);
  brush.rect(X0, Y0, PW, 140, "corner");

  brush.fill("#68899e", 55);
  brush.rect(X0, 340, PW, 180, "corner");

  brush.fill("#ede2cf", 75);
  brush.rect(X0, 620, PW, 115, "corner");

  brush.fill("#c9a696", 55);
  brush.rect(X0, 695, PW, 55, "corner");
  brush.noFill();

  // Airbrushed spray passes building powdery grain and shimmering heat bands
  for (let i = 0; i < 160; i++) {
    let t = i / 160;
    let y = lerp(Y0 + 5, HY + 5, pow(t, 1.15));
    let c = sampleColorStops(skyStops, y + random(-18, 18));
    brush.set("airbrush", c, random(0.8, 1.6));
    let xStart = X0 - 20 + random(-15, 15);
    let xEnd = X1 + 20 + random(-15, 15);
    brush.line(xStart, y, xEnd, y + random(-3, 3));
  }

  // Horizontal shimmering haze striations in the lower half of the sky
  for (let i = 0; i < 95; i++) {
    let y = random(310, HY + 8);
    let bandCol = y < 560
      ? (random() < 0.5 ? "#acc0c8" : "#7e9cae")
      : (random() < 0.6 ? "#efe6d5" : "#d8bfae");
    brush.set("hazeBand", bandCol, random(0.4, 1.15));
    let x1 = random(X0, X0 + 350);
    let x2 = random(X1 - 350, X1);
    brush.line(x1, y, x2, y + random(-1.5, 1.5));
  }
}

function sampleColorStops(stops, y) {
  if (y <= stops[0].y) return color(stops[0].col);
  if (y >= stops[stops.length - 1].y) return color(stops[stops.length - 1].col);
  for (let i = 0; i < stops.length - 1; i++) {
    if (y >= stops[i].y && y <= stops[i + 1].y) {
      let amt = (y - stops[i].y) / (stops[i + 1].y - stops[i].y);
      return lerpColor(color(stops[i].col), color(stops[i + 1].col), amt);
    }
  }
  return color(stops[0].col);
}

// =============================================================================
// 2. DISTANT DESERT MESAS & SHEARED HORIZON MIRAGE
// =============================================================================

function renderDistantDesertAndHorizonMirage() {
  // Base desert floor wash below horizon
  washRect(X0, HY, PW, Y1 - HY, "#8e7b70", 255);

  // Distant twilight mountain ridges & flat-topped desert mesas
  // Left horizon range (sheared at base by mirage)
  const leftMesaPts = [
    [X0, HY + 2],
    [X0, HY - 24],
    [110, HY - 28],
    [145, HY - 42],
    [255, HY - 44],
    [285, HY - 26],
    [360, HY - 29],
    [395, HY - 16],
    [485, HY - 14],
    [535, HY - 4],
    [565, HY + 2]
  ];
  washPoly(leftMesaPts, "#594854", 190);

  // Right horizon range
  const rightMesaPts = [
    [640, HY + 2],
    [680, HY - 8],
    [735, HY - 22],
    [830, HY - 24],
    [865, HY - 38],
    [985, HY - 36],
    [1020, HY - 19],
    [1095, HY - 21],
    [X1, HY - 14],
    [X1, HY + 2]
  ];
  washPoly(rightMesaPts, "#52424e", 195);

  // Secondary pale violet-taupe ridge behind
  const farRidgePts = [
    [180, HY - 20],
    [220, HY - 52],
    [330, HY - 48],
    [410, HY - 25],
    [470, HY - 10]
  ];
  washPoly(farRidgePts, "#7c6b75", 135);

  // FATA MORGANA HORIZONTAL SLICING ON THE HORIZON MESAS:
  // Slice the mesas and horizon with floating inverted strips and bone-sky refraction wedges
  for (let y = HY - 48; y <= HY + 22; y += 2.8) {
    let shift = sin(y * 5.2) * 14 + (noise(y * 0.15, 3.7) - 0.5) * 26;
    let isSkyWedge = sin(y * 3.8 + noise(y * 0.1) * 5) > 0.22;

    if (isSkyWedge && y > HY - 28) {
      // Bright bone/sky refraction slice undercutting the mesas
      brush.set("chromeBar", "#eadfcd", random(0.45, 0.9));
      brush.line(X0, y, VPX - 55 + shift, y);
      brush.line(VPX + 55 + shift, y, X1, y);
    } else {
      // Sheared mesa / twilight desert band
      let col = y < HY - 15 ? "#66535f" : (random() < 0.5 ? "#7d686d" : "#4b3b46");
      brush.set("hazeBand", col, random(0.35, 0.75));
      if (y < HY - 12) {
        brush.line(X0 + max(0, (HY - 12 - y) * 3), y, 500 + shift, y);
        brush.line(690 + shift, y, X1 - max(0, (HY - 12 - y) * 2), y);
      } else {
        brush.line(X0, y, X1, y);
      }
    }
  }

  // Distant sheared utility poles / desert markers on left and right of highway
  // Each pole is broken into vertically stacked, horizontally displaced mirage segments
  for (let i = 0; i < 9; i++) {
    let side = i % 2 === 0 ? -1 : 1;
    let depth = pow(i / 9, 1.3);
    let px = VPX + side * lerp(58, 360, depth);
    let pyBase = lerp(HY + 2, HY + 48, depth);
    let poleH = lerp(26, 75, depth);

    // Draw real + inverted mirage segments of each pole
    let slices = 12;
    for (let s = 0; s < slices; s++) {
      let sy0 = pyBase - poleH * 1.35 + (s / slices) * poleH * 1.65;
      let sy1 = sy0 + (poleH * 1.65) / slices;
      let heatFactor = constrain(1 - depth * 1.1, 0.15, 1.0);
      let dx = (sin(sy0 * 6.5 + i * 40) * 6 + (noise(sy0 * 0.2, i) - 0.5) * 14) * heatFactor;
      brush.set("2H", "#4a3c44", lerp(0.25, 0.55, depth));
      brush.line(px + dx, sy0, px + dx * 0.8, sy1);
    }
  }

  // Desert Flats & Shoulders from HY down to Y1 (Left & Right of Highway)
  const desertStops = [
    { y: HY,      col: "#d8c6b4" }, // Shimmering alkali mirage edge
    { y: HY + 28, col: "#b59e90" },
    { y: HY + 70, col: "#947d73" }, // Dusky mauve-ochre desert
    { y: HY + 140, col: "#78635c" },
    { y: HY + 220, col: "#5e4c49" },
    { y: Y1,      col: "#463839" }  // Deep twilight desert foreground
  ];

  let shoulderBands = 55;
  for (let i = 0; i < shoulderBands; i++) {
    let t0 = i / shoulderBands;
    let t1 = (i + 1.4) / shoulderBands;
    let y0 = lerp(HY, Y1, t0);
    let y1 = lerp(HY, Y1, t1);
    let ym = (y0 + y1) * 0.5;
    let c = sampleColorStops(desertStops, ym);

    let lx0 = roadLeftEdge(y0) - 8;
    let lx1 = roadLeftEdge(y1) - 8;
    let rx0 = roadRightEdge(y0) + 8;
    let rx1 = roadRightEdge(y1) + 8;

    washQuad(X0, y0, lx0, y0, lx1, y1, X0, y1, c, 210);
    washQuad(rx0, y0, X1, y0, X1, y1, rx1, y1, c, 210);
  }

  // Horizontal smeared bands in distant desert transitions into sharper gravel in foreground
  for (let i = 0; i < 220; i++) {
    let t = pow(random(), 1.3);
    let y = lerp(HY + 2, Y1, t);
    let isLeft = random() < 0.5;
    let rEdge = isLeft ? roadLeftEdge(y) : roadRightEdge(y);
    let x = isLeft ? random(X0, rEdge - 4) : random(rEdge + 4, X1);
    let span = lerp(110, 14, t);

    if (t < 0.35) {
      // Distant smeared mirage streaks on alkali flats
      let col = random() < 0.5 ? "#e5d8c7" : "#8f7972";
      brush.set("hazeBand", col, random(0.3, 0.8));
      brush.line(x - span * 0.5, y, x + span * 0.5, y);
    } else {
      // Mid-to-near desert scrub shadows and gravel ridges
      let col = random() < 0.5 ? "#382c2e" : "#a89586";
      brush.set("HB", col, lerp(0.3, 0.85, t));
      brush.line(x, y, x + random(-span, span), y + random(-2, 2));
    }
  }
}

// =============================================================================
// 3. HIGHWAY SURFACE, INFERIOR MIRAGE & FOREGROUND ASPHALT CRACKS
// =============================================================================

function renderHighwayAndForeground() {
  // Base highway trapezoid layers from horizon (HY) to bottom (Y1)
  const roadStops = [
    { y: HY,       col: "#e6dbc9" }, // Pure sky-reflecting mirage sheet at horizon
    { y: HY + 22,  col: "#c2cbd0" }, // Cerulean-bone shimmering mirror
    { y: HY + 48,  col: "#8d8a92" }, // Dissolving asphalt in heat
    { y: HY + 80,  col: "#55525c" }, // Twilight slate transition
    { y: HY + 125, col: "#383842" }, // Mid-ground asphalt
    { y: HY + 190, col: "#272830" }, // Near asphalt
    { y: Y1,       col: "#1a1b22" }  // Crisp dark foreground asphalt
  ];

  let strips = 80;
  for (let i = 0; i < strips; i++) {
    let t0 = i / strips;
    let t1 = (i + 1.3) / strips;
    let y0 = lerp(HY, Y1, t0);
    let y1 = lerp(HY, Y1, t1);
    let ym = (y0 + y1) * 0.5;
    let c = sampleColorStops(roadStops, ym);

    let l0 = roadLeftEdge(y0);
    let r0 = roadRightEdge(y0);
    let l1 = roadLeftEdge(y1);
    let r1 = roadRightEdge(y1);

    washQuad(l0, y0, r0, y0, r1, y1, l1, y1, c, 235);
  }

  // Graded gravel shoulder transition along left & right highway margins
  for (let i = 0; i < 65; i++) {
    let t = i / 65;
    let y = lerp(HY + 15, Y1, t);
    let lEdge = roadLeftEdge(y);
    let rEdge = roadRightEdge(y);
    let sw = lerp(2, 42, t);
    brush.set("2B", "#6c5d57", lerp(0.25, 1.1, t));
    brush.line(lEdge - sw, y, lEdge + sw * 0.35, y + 2);
    brush.line(rEdge - sw * 0.35, y, rEdge + sw, y + 2);
  }

  // Longitudinal tire wear ruts (polished dark tracks & lighter crown aggregate)
  for (let i = 0; i < 140; i++) {
    let laneU = random([-0.58, -0.22, 0.22, 0.58]) + random(-0.12, 0.12);
    let yStart = random(HY + 55, Y1 - 40);
    let yEnd = min(Y1, yStart + random(35, 120));
    let tS = (yStart - HY) / (Y1 - HY);
    let tE = (yEnd - HY) / (Y1 - HY);

    let xS = lerp(roadLeftEdge(yStart), roadRightEdge(yStart), 0.5 + laneU * 0.45);
    let xE = lerp(roadLeftEdge(yEnd), roadRightEdge(yEnd), 0.5 + laneU * 0.45);

    let col = random() < 0.65 ? "#14151b" : "#43444f";
    brush.set("2H", col, lerp(0.25, 0.85, tS));
    brush.line(xS, yStart, xE, yEnd);
  }

  // INFERIOR ROAD MIRAGE ZONE (y = HY to HY + 105):
  // Liquid sky-reflection bands and inverted ghost of the approaching tanker on the road surface
  for (let y = HY; y < HY + 108; y += 2.2) {
    let t = (y - HY) / 108;
    let lx = roadLeftEdge(y);
    let rx = roadRightEdge(y);
    let wob = sin(y * 6.2) * 10 * (1 - t) + (noise(y * 0.18, 9.1) - 0.5) * 18 * (1 - t);

    // Sky reflection ribbons cutting across the hot asphalt
    if (random() < (1 - t * 0.75)) {
      let skyRefCol = t < 0.45 ? "#ece1cf" : (random() < 0.5 ? "#b4c3cb" : "#d8c6b6");
      brush.set("chromeBar", skyRefCol, lerp(0.85, 0.25, t));
      let segL = lerp(lx - 15, lx + (rx - lx) * random(0.05, 0.25), t);
      let segR = lerp(rx + 15, rx - (rx - lx) * random(0.05, 0.25), t);
      brush.line(segL + wob, y, segR + wob, y);
    }

    // Inverted reflection of the tanker's dark tires, chrome bumper & headlight pools in the road shimmer
    if (y > HY + 42 && y < HY + 105) {
      let mt = (y - (HY + 42)) / 63; // 0 at truck tires, 1 further down road
      let cx = 582 + wob * 0.7;
      let halfW = lerp(96, 52, mt);

      // Dark undercarriage/tire reflection slice
      brush.set("chromeBar", "#1c1a22", lerp(0.8, 0.2, mt));
      brush.line(cx - halfW, y, cx + halfW, y);

      // Shimmering chrome bumper reflection slice
      if (sin(y * 9.5) > -0.2) {
        brush.set("chromeBar", "#efe6d5", lerp(0.75, 0.2, mt));
        brush.line(cx - halfW * 0.85 + wob * 0.4, y, cx + halfW * 0.85 + wob * 0.4, y);
      }

      // Stretched halogen headlight reflection pillars on the shimmering road
      let hlLeft = cx - halfW * 0.72;
      let hlRight = cx + halfW * 0.72;
      brush.set("chromeBar", "#f7cc7c", lerp(0.9, 0.25, mt));
      brush.line(hlLeft - 12, y, hlLeft + 12, y);
      brush.line(hlRight - 12, y, hlRight + 12, y);
    }
  }

  // WHITE SHOULDER FOG LINES (wobbling in distance, sharp in foreground)
  drawHighwayFogLines();

  // DOUBLE YELLOW CENTER LINES (wavering in mirage, weathered & cracked in foreground)
  drawCenterYellowLines();

  // HYPERREAL FOREGROUND ASPHALT AGGREGATE & CRACK NETWORK
  renderAsphaltCracks();
}

function drawHighwayFogLines() {
  let steps = 55;
  for (let i = 0; i < steps; i++) {
    let t0 = i / steps;
    let t1 = (i + 1) / steps;
    let y0 = lerp(HY + 28, Y1, t0);
    let y1 = lerp(HY + 28, Y1, t1);

    let wob0 = (1 - t0) * (1 - t0) * sin(y0 * 7) * 5;
    let wob1 = (1 - t1) * (1 - t1) * sin(y1 * 7) * 5;

    let l0 = lerp(roadLeftEdge(y0), roadRightEdge(y0), 0.055) + wob0;
    let l1 = lerp(roadLeftEdge(y1), roadRightEdge(y1), 0.055) + wob1;
    let r0 = lerp(roadLeftEdge(y0), roadRightEdge(y0), 0.945) - wob0;
    let r1 = lerp(roadLeftEdge(y1), roadRightEdge(y1), 0.945) - wob1;

    let w = lerp(0.2, 2.4, pow(t0, 1.4));
    let col = t0 < 0.3 ? "#dfd6c7" : "#c7bfb0";

    brush.set("chromeBar", col, w);
    brush.line(l0, y0, l1, y1);
    brush.line(r0, y0, r1, y1);

    // Chipped paint edge & dark asphalt wear on foreground fog lines
    if (t0 > 0.55) {
      brush.set("rotring", "#23242c", 0.35);
      brush.line(l0 + random(-2, 2), y0, l1 + random(-2, 2), y1);
      brush.line(r0 + random(-2, 2), y0, r1 + random(-2, 2), y1);
    }
  }
}

function drawCenterYellowLines() {
  // Double yellow line (one solid, one broken/dashed) rushing from underneath the truck to bottom
  let steps = 65;
  for (let i = 0; i < steps; i++) {
    let t0 = i / steps;
    let t1 = (i + 1) / steps;
    let y0 = lerp(HY + 45, Y1, pow(t0, 1.15));
    let y1 = lerp(HY + 45, Y1, pow(t1, 1.15));

    let cx0 = roadCenterX(y0);
    let cx1 = roadCenterX(y1);

    let sep0 = lerp(0.8, 11.5, pow(t0, 1.25));
    let sep1 = lerp(0.8, 11.5, pow(t1, 1.25));
    let ribbonW0 = lerp(0.4, 7.5, pow(t0, 1.3));
    let ribbonW1 = lerp(0.4, 7.5, pow(t1, 1.3));

    // Left yellow stripe (solid)
    washQuad(
      cx0 - sep0 - ribbonW0, y0,
      cx0 - sep0, y0,
      cx1 - sep1, y1,
      cx1 - sep1 - ribbonW1, y1,
      t0 < 0.25 ? "#e2c383" : "#d49b3b",
      225
    );

    // Right yellow stripe (dashed in perspective)
    let dashPhase = (i % 7) < 4;
    if (dashPhase) {
      washQuad(
        cx0 + sep0, y0,
        cx0 + sep0 + ribbonW0, y0,
        cx1 + sep1 + ribbonW1, y1,
        cx1 + sep1, y1,
        t0 < 0.25 ? "#e2c383" : "#c88d32",
        220
      );
    }

    // Crisp hyperreal edge highlight & paint wear in the near foreground
    if (t0 > 0.45) {
      brush.set("microPen", "#f2cf7e", 0.55);
      brush.line(cx0 - sep0 - ribbonW0, y0, cx1 - sep1 - ribbonW1, y1);
      brush.set("microPen", "#593d14", 0.45);
      brush.line(cx0 - sep0, y0, cx1 - sep1, y1);

      if (dashPhase) {
        brush.set("microPen", "#f2cf7e", 0.55);
        brush.line(cx0 + sep0, y0, cx1 + sep1, y1);
        brush.set("microPen", "#593d14", 0.45);
        brush.line(cx0 + sep0 + ribbonW0, y0, cx1 + sep1 + ribbonW1, y1);
      }
    }
  }
}

function renderAsphaltCracks() {
  // Fine graphite cross-hatching & spray stipple for aggregate texture in near road
  brush.set("fineSpray", "#3e404a", 0.9);
  for (let i = 0; i < 85; i++) {
    let y = random(HY + 120, Y1 - 5);
    let lx = roadLeftEdge(y) + 20;
    let rx = roadRightEdge(y) - 20;
    brush.line(lx, y, rx, y + random(-2, 2));
  }

  brush.set("fineSpray", "#121318", 0.85);
  for (let i = 0; i < 75; i++) {
    let y = random(HY + 140, Y1 - 5);
    let lx = roadLeftEdge(y) + 20;
    let rx = roadRightEdge(y) - 20;
    brush.line(lx, y, rx, y + random(-2, 2));
  }

  // Primary transverse & longitudinal tar-sealed cracks in the mid-to-near foreground
  const numPrimaryCracks = 34;
  for (let c = 0; c < numPrimaryCracks; c++) {
    let depth = pow((c + 0.5) / numPrimaryCracks, 1.35); // Concentrated toward foreground
    let yBase = lerp(HY + 115, Y1 - 8, depth);
    let lx = roadLeftEdge(yBase);
    let rx = roadRightEdge(yBase);

    let xStart = random(lx + 15, rx - 180);
    let xEnd = min(rx - 15, xStart + random(140, 580) * (0.4 + 0.6 * depth));

    let segs = floor(lerp(8, 24, depth));
    let pts = [];
    let curY = yBase;
    for (let s = 0; s <= segs; s++) {
      let u = s / segs;
      let px = lerp(xStart, xEnd, u);
      curY += (noise(c * 10 + u * 6, yBase * 0.02) - 0.48) * lerp(3, 14, depth);
      pts.push([px, constrain(curY, HY + 105, Y1 - 3)]);
    }

    // 1. Matte black tar-snake seal band around crack
    if (depth > 0.3) {
      brush.set("2B", "#111217", lerp(0.4, 1.35, depth));
      for (let s = 0; s < pts.length - 1; s++) {
        brush.line(pts[s][0], pts[s][1], pts[s + 1][0], pts[s + 1][1]);
      }
    }

    // 2. Razor-sharp fissure core with rotring / microPen
    brush.set("microPen", "#07080b", lerp(0.35, 1.15, depth));
    for (let s = 0; s < pts.length - 1; s++) {
      brush.line(pts[s][0], pts[s][1], pts[s + 1][0], pts[s + 1][1]);
    }

    // 3. Trompe-l'oeil sunlit/sky-lit bottom lip highlight on foreground cracks
    if (depth > 0.42) {
      let lipOffset = lerp(0.8, 2.2, depth);
      brush.set("microPen", "#787a84", lerp(0.25, 0.7, depth));
      for (let s = 0; s < pts.length - 1; s++) {
        if (random() < 0.8) {
          brush.line(
            pts[s][0], pts[s][1] + lipOffset,
            pts[s + 1][0], pts[s + 1][1] + lipOffset
          );
        }
      }
    }

    // 4. Secondary alligator branching fractures off main crack
    if (depth > 0.35) {
      let branches = floor(lerp(1, 5, depth));
      for (let b = 0; b < branches; b++) {
        let idx = floor(random(1, pts.length - 1));
        let bx = pts[idx][0];
        let by = pts[idx][1];
        let bSteps = floor(random(3, 7));
        for (let k = 0; k < bSteps; k++) {
          let nx = bx + random(-22, 22) * depth;
          let ny = by + random(5, 22) * depth;
          ny = min(Y1 - 3, ny);
          brush.set("microPen", "#0a0b0f", lerp(0.25, 0.8, depth));
          brush.line(bx, by, nx, ny);
          if (depth > 0.6) {
            brush.set("microPen", "#686a73", 0.35);
            brush.line(bx + 1, by + 1.2, nx + 1, ny + 1.2);
          }
          bx = nx;
          by = ny;
        }
      }
    }
  }
}

// =============================================================================
// 4. SUPERIOR MIRAGE: INVERTED, STRETCHED, HORIZONTALLY SHEARED DOUBLE
// =============================================================================

function getTruckCrossSection(u) {
  // u in [0, 1] maps from top of real truck (u=0, y=536) to bottom of tires (u=1, y=796)
  // Returns array of horizontal slices { x0, x1, col, type } for the Fata Morgana slicer
  const segs = [];
  const cx = 582; // Tractor center X

  // 1. Elliptical Chrome Fuel Tank Dome & Barrel rising behind/right of cab (u in [0.02, 0.80])
  if (u >= 0.02 && u <= 0.80) {
    let tu = (u - 0.02) / 0.78; // 0 at tank top, 1 at tank bottom
    let profile = sin(constrain(tu, 0, 1) * 180);
    let tankCx = 606;
    let halfW = 94 * pow(profile, 0.72);

    // Base chrome reflection color according to vertical angle on cylinder
    let tankCol = "#d8d4cb";
    if (tu < 0.18) tankCol = "#3c5d76";      // Deep cerulean sky reflection at crown
    else if (tu < 0.32) tankCol = "#fbf6ea"; // Blazing bone-white specular highlight
    else if (tu < 0.48) tankCol = "#9eb5c2"; // Pale cerulean sky
    else if (tu < 0.58) tankCol = "#ebe0ce"; // Horizon bone glow
    else if (tu < 0.70) tankCol = "#3b2e37"; // Dark desert horizon band wrapped on chrome
    else tankCol = "#5c535b";                // Warm asphalt reflection on lower tank

    segs.push({ x0: tankCx - halfW, x1: tankCx + halfW, col: tankCol, type: "chromeTank" });

    // Specular highlight core along upper-right barrel
    if (tu > 0.12 && tu < 0.55) {
      segs.push({ x0: tankCx + halfW * 0.15, x1: tankCx + halfW * 0.78, col: "#fffdf7", type: "specular" });
    }
  }

  // 2. Top vapor-recovery rail on tank crown (u in [0.0, 0.05])
  if (u <= 0.05) {
    segs.push({ x0: 562, x1: 642, col: "#607788", type: "rail" });
  }

  // 3. Dual tall vertical Chrome Exhaust Stacks (u in [0.02, 0.56])
  if (u >= 0.02 && u <= 0.56) {
    // Left stack (x ~ 504) & Right stack (x ~ 658)
    segs.push({ x0: 498, x1: 510, col: "#252932", type: "stackDark" });
    segs.push({ x0: 502, x1: 507, col: "#f7f1e6", type: "stackBright" });
    segs.push({ x0: 652, x1: 664, col: "#252932", type: "stackDark" });
    segs.push({ x0: 656, x1: 661, col: "#f7f1e6", type: "stackBright" });
  }

  // 4. Cab Roof & Amber Clearance Lights (u in [0.14, 0.22])
  if (u >= 0.14 && u <= 0.22) {
    let kw = map(u, 0.14, 0.22, 46, 62);
    segs.push({ x0: cx - kw, x1: cx + kw, col: "#7a8f9e", type: "cabRoof" });
    if (u >= 0.15 && u <= 0.185) {
      // 5 amber torpedo roof lights
      const lxs = [cx - 42, cx - 18, cx, cx + 18, cx + 42];
      for (let lx of lxs) {
        segs.push({ x0: lx - 4, x1: lx + 4, col: "#f5a83d", type: "amberLight" });
      }
    }
  }

  // 5. Deep Stainless Sun Visor (u in [0.20, 0.25])
  if (u >= 0.20 && u <= 0.25) {
    segs.push({ x0: cx - 66, x1: cx + 66, col: "#e8e2d5", type: "visor" });
    segs.push({ x0: cx - 64, x1: cx + 64, col: "#1d222b", type: "visorShadow" });
  }

  // 6. Split Windshield & West-Coast Side Mirrors (u in [0.24, 0.37])
  if (u >= 0.24 && u <= 0.37) {
    segs.push({ x0: cx - 63, x1: cx + 63, col: "#2c3844", type: "cabFrame" });
    segs.push({ x0: cx - 58, x1: cx - 3, col: "#18222c", type: "windshield" });
    segs.push({ x0: cx + 3, x1: cx + 58, col: "#1d2833", type: "windshield" });
    // Sky glare slash on glass
    let gx = map(u, 0.24, 0.37, cx - 45, cx - 15);
    segs.push({ x0: gx, x1: gx + 18, col: "#9bb3c2", type: "glare" });
    segs.push({ x0: gx + 58, x1: gx + 74, col: "#b8c9d1", type: "glare" });

    // West-Coast rectangular side mirrors & brackets
    segs.push({ x0: 472, x1: 486, col: "#d9d4c8", type: "mirror" });
    segs.push({ x0: 676, x1: 690, col: "#d9d4c8", type: "mirror" });
  }

  // 7. Chrome Air Cleaners & Tapered Hood Top (u in [0.37, 0.49])
  if (u >= 0.37 && u <= 0.49) {
    // Air cleaner canisters
    segs.push({ x0: 496, x1: 516, col: "#354452", type: "airCleaner" });
    segs.push({ x0: 501, x1: 511, col: "#f2ece0", type: "airCleanerHi" });
    segs.push({ x0: 646, x1: 666, col: "#354452", type: "airCleaner" });
    segs.push({ x0: 651, x1: 661, col: "#f2ece0", type: "airCleanerHi" });

    // Hood cowling reflecting bone sky
    let hw = map(u, 0.37, 0.49, 58, 52);
    segs.push({ x0: cx - hw, x1: cx + hw, col: "#9ab0be", type: "hood" });
    segs.push({ x0: cx - hw * 0.7, x1: cx + hw * 0.7, col: "#e9e0cf", type: "hoodHi" });
  }

  // 8. Monumental Chrome Grille, Fenders & Headlight Pods (u in [0.48, 0.84])
  if (u >= 0.48 && u <= 0.84) {
    // Sculpted front fenders (left & right of grille)
    if (u >= 0.56) {
      let fw = map(u, 0.56, 0.84, 24, 44);
      let fCol = u < 0.70 ? "#8da3b2" : "#2f2c36";
      segs.push({ x0: cx - 52 - fw, x1: cx - 52, col: fCol, type: "fender" });
      segs.push({ x0: cx + 52, x1: cx + 52 + fw, col: fCol, type: "fender" });
    }

    // Dual Halogen Headlight Pods (u in [0.66, 0.76])
    if (u >= 0.66 && u <= 0.76) {
      segs.push({ x0: cx - 86, x1: cx - 58, col: "#e8e2d6", type: "hlPod" });
      segs.push({ x0: cx - 83, x1: cx - 61, col: "#fffcf2", type: "headlight" });
      segs.push({ x0: cx + 58, x1: cx + 86, col: "#e8e2d6", type: "hlPod" });
      segs.push({ x0: cx + 61, x1: cx + 83, col: "#fffcf2", type: "headlight" });
    }

    // Amber fender turn signals (u in [0.59, 0.63])
    if (u >= 0.59 && u <= 0.63) {
      segs.push({ x0: cx - 88, x1: cx - 78, col: "#f09c35", type: "amberLight" });
      segs.push({ x0: cx + 78, x1: cx + 88, col: "#f09c35", type: "amberLight" });
    }

    // Chrome Grille Surround & Vertical Louvers
    segs.push({ x0: cx - 52, x1: cx + 52, col: "#f0eae0", type: "grilleSurround" });
    if (u >= 0.52 && u <= 0.82) {
      segs.push({ x0: cx - 44, x1: cx + 44, col: "#181a22", type: "grilleCore" });
    }
    // Red oval emblem at top of grille crown
    if (u >= 0.485 && u <= 0.515) {
      segs.push({ x0: cx - 10, x1: cx + 10, col: "#9e2b2b", type: "emblem" });
    }
  }

  // 9. Heavy Texas Chrome Bumper (u in [0.84, 0.94])
  if (u >= 0.84 && u <= 0.94) {
    let bu = (u - 0.84) / 0.10;
    let bCol = bu < 0.28 ? "#fbf5e8" : (bu < 0.65 ? "#212029" : "#d8ccb9");
    segs.push({ x0: cx - 98, x1: cx + 98, col: bCol, type: "bumper" });
  }

  // 10. Front Steer Tires & Tandem Trailer Tires + Dark Undercarriage (u in [0.90, 1.0])
  if (u >= 0.90) {
    segs.push({ x0: cx - 96, x1: cx + 118, col: "#232129", type: "undercarriage" });
    segs.push({ x0: cx - 94, x1: cx - 64, col: "#14141a", type: "tire" });
    segs.push({ x0: cx + 64, x1: cx + 94, col: "#14141a", type: "tire" });
    segs.push({ x0: cx + 96, x1: cx + 124, col: "#1b1a22", type: "tire" });
  }

  return segs;
}

function renderSuperiorMirageTanker() {
  // Hang the inverted, vertically stretched double directly above the real truck:
  // Real truck top is around y = 536.
  // Superior mirage spans from y = 215 (inverted tires/bumper at top) down to y = 534 (inverted stacks/dome meeting real roof).
  const mirageTop = 215;
  const mirageBot = 534;
  const sliceStep = 3.0;

  // First, soft atmospheric halo behind the mirage where heat refracts sky light
  for (let y = mirageTop - 10; y <= mirageBot + 10; y += 5) {
    let env = sin(constrain(map(y, mirageTop - 10, mirageBot + 10, 0, 180), 0, 180));
    let wob = sin(y * 3.1) * 18 + (noise(y * 0.05, 4.2) - 0.5) * 32;
    let haloCol = y < 380 ? "#89a5b6" : "#e3d9c8";
    brush.set("airbrush", haloCol, 0.9 * env);
    brush.line(585 - 135 * env + wob, y, 585 + 150 * env + wob, y);
  }

  // Slice-by-slice Fata Morgana rendering
  for (let y = mirageTop; y <= mirageBot; y += sliceStep) {
    // Normalized position from bottom of mirage (0) to top of mirage (1)
    let tRaw = map(y, mirageBot, mirageTop, 0, 1);

    // Non-linear Fata Morgana vertical ducting warp (stretches middle & duplicates bands slightly)
    let ductWave = 0.042 * sin(y * 4.2) + 0.022 * cos(y * 9.5);
    let u = constrain(pow(tRaw, 0.88) + ductWave, 0, 1);

    // Horizontal shear offset: coherent S-waves + turbulent thermal shear
    let edgeFade = sin(constrain(tRaw * 180, 8, 172));
    let shearCoherent = sin(y * 2.6 + 15) * 17 + cos(y * 6.8 - 40) * 9.5;
    let shearTurbulent = (noise(y * 0.06, 77.2) - 0.5) * 44 + (noise(y * 0.22, 19.4) - 0.5) * 18;
    let dx = (shearCoherent + shearTurbulent) * (0.35 + 0.85 * edgeFade);

    // Occasional extreme optical tear / detached mirage ribbon
    if (sin(y * 5.7 + noise(y * 0.1) * 6) > 0.72) {
      dx += (y % 6 < 3 ? 1 : -1) * random(12, 26);
    }

    // Sample the truck's horizontal cross-section at u
    let segs = getTruckCrossSection(u);

    // Sky background color at this altitude for atmospheric blending
    let skyBg = y < 360 ? color("#54768d") : (y < 460 ? color("#86a2b2") : color("#bdcad0"));
    let blendAmt = map(tRaw, 0, 1, 0.14, 0.36);

    for (let s of segs) {
      let cBlended = lerpColor(color(s.col), skyBg, blendAmt);
      let sx0 = s.x0 + dx;
      let sx1 = s.x1 + dx;

      // Stretch horizontal slice width slightly in strong refraction zones
      let stretchX = 1.0 + 0.08 * sin(y * 4.5);
      let midX = (sx0 + sx1) * 0.5;
      sx0 = midX + (sx0 - midX) * stretchX;
      sx1 = midX + (sx1 - midX) * stretchX;

      washRect(sx0, y, max(1.5, sx1 - sx0), sliceStep + 0.7, cBlended, 205);

      // Inside sheared grille slices, draw the inverted vertical chrome louvers shifted by dx!
      if (s.type === "grilleCore") {
        brush.set("microPen", "#d9e0e4", 0.55);
        for (let lx = sx0 + 3; lx < sx1 - 2; lx += 3.4) {
          brush.line(lx, y, lx + random(-0.4, 0.4), y + sliceStep);
        }
      }

      // Inside sheared headlight slices, draw warm halogen bloom & horizontal refraction flare
      if (s.type === "headlight") {
        brush.set("chromeBar", "#ffeed1", 0.75);
        brush.line(sx0 - 6, y + sliceStep * 0.5, sx1 + 6, y + sliceStep * 0.5);
        brush.set("hazeBand", "#f2b652", 0.45);
        brush.line(sx0 - 16, y + sliceStep * 0.5, sx1 + 16, y + sliceStep * 0.5);
      }
    }

    // Horizontal sky-colored refraction incisions slicing through the mirage double
    if (sin(y * 7.8) > 0.48 || random() < 0.22) {
      let cutCol = y < 370 ? "#5f8197" : (y < 470 ? "#9bb2bf" : "#d4dad8");
      brush.set("hazeBand", cutCol, random(0.35, 0.75));
      brush.line(445 + dx * 0.6, y, 745 + dx * 1.1, y);
    }
  }
}

// =============================================================================
// 5. THE CHROME FUEL TANKER (HYPERREAL CENTERPIECE)
// =============================================================================

function renderRealChromeTanker() {
  const CX = 582; // Center of tractor cab & grille

  // ---------------------------------------------------------------------------
  // A. POLISHED CHROME ELLIPTICAL FUEL TANK BARREL & FRONT BULKHEAD DOME
  // Rising behind and slightly to the right of the tractor cab in perspective
  // ---------------------------------------------------------------------------
  const fCx = 607, fCy = 626, fRx = 89, fRy = 76; // Front elliptical dome of tank
  const rCx = 656, rCy = 668, rRx = 52, rRy = 44; // Rear elliptical bulkhead foreshortened toward VP

  // 1. Cylindrical chrome barrel side connecting front bulkhead to rear bulkhead
  let angSteps = 72;
  for (let i = 0; i < angSteps; i++) {
    let a0 = map(i, 0, angSteps, -165, 95);
    let a1 = map(i + 1.4, 0, angSteps, -165, 95);

    let x0f = fCx + fRx * cos(a0);
    let y0f = fCy + fRy * sin(a0);
    let x1f = fCx + fRx * cos(a1);
    let y1f = fCy + fRy * sin(a1);

    let x0r = rCx + rRx * cos(a0);
    let y0r = rCy + rRy * sin(a0);
    let x1r = rCx + rRx * cos(a1);
    let y1r = rCy + rRy * sin(a1);

    // Chrome environmental reflection mapped by surface normal angle a0
    let col = sampleChromeReflection(a0);
    washQuad(x0f, y0f, x1f, y1f, x1r, y1r, x0r, y0r, col, 240);
  }

  // Circumferential stiffening rings & rivet seams wrapping the tank barrel
  const ringFracs = [0.06, 0.34, 0.64, 0.90];
  for (let rf of ringFracs) {
    let mCx = lerp(fCx, rCx, rf);
    let mCy = lerp(fCy, rCy, rf);
    let mRx = lerp(fRx, rRx, rf);
    let mRy = lerp(fRy, rRy, rf);

    for (let a = -125; a <= 75; a += 6) {
      let px0 = mCx + mRx * cos(a);
      let py0 = mCy + mRy * sin(a);
      let px1 = mCx + mRx * cos(a + 6);
      let py1 = mCy + mRy * sin(a + 6);

      brush.set("microPen", "#23252e", 0.55);
      brush.line(px0, py0, px1, py1);
      brush.set("microPen", "#fbf6ec", 0.45);
      brush.line(px0 + 1.2, py0 + 0.5, px1 + 1.2, py1 + 0.5);

      // Tiny hyperreal rivets along each circumferential tank ring
      drawMicroRivet(px0 + 0.6, py0, 0.55);
    }
  }

  // 2. Front Elliptical Chrome Bulkhead (Convex Mirror Dome)
  let domeRings = 28;
  for (let r = domeRings; r >= 1; r--) {
    let frac = r / domeRings;
    let rx = fRx * frac;
    let ry = fRy * frac;
    // Slight upward offset of inner rings creates convex 3D dome curvature
    let dCx = fCx - (1 - frac) * 8;
    let dCy = fCy - (1 - frac) * 6;

    // Draw upper and lower reflection bands inside the convex dome
    let pts = [];
    for (let a = 0; a < 360; a += 10) {
      pts.push([dCx + rx * cos(a), dCy + ry * sin(a)]);
    }
    let domeBaseCol = frac > 0.85 ? "#8ea6b5" : (frac > 0.5 ? "#dcd6c9" : "#b8c7cf");
    washPoly(pts, domeBaseCol, 190);
  }

  // Horizontal environmental reflection bands warped across the convex front bulkhead dome
  let domeBands = 46;
  for (let b = 0; b < domeBands; b++) {
    let v = map(b, 0, domeBands - 1, -0.96, 0.96);
    let nextV = map(b + 1.2, 0, domeBands - 1, -0.96, 0.96);
    let yTop = fCy + v * fRy;
    let yBot = fCy + nextV * fRy;
    let halfChord = fRx * sqrt(max(0, 1 - v * v));

    // Convex curvature bows horizontal horizon reflections inside the dome
    let bow = (1 - v * v) * 9 * v;
    let angleEquiv = v * 90;
    let bandCol = sampleChromeReflection(angleEquiv);

    washQuad(
      fCx - halfChord, yTop,
      fCx + halfChord, yTop,
      fCx + halfChord * 0.98, yBot + bow,
      fCx - halfChord * 0.98, yBot + bow,
      bandCol,
      230
    );
  }

  // Blazing white-bone specular crescent on upper-right of chrome tank dome
  brush.set("chromeBar", "#fffef9", 1.35);
  for (let a = -78; a <= -18; a += 4) {
    let xA = fCx + (fRx - 5) * cos(a);
    let yA = fCy + (fRy - 5) * sin(a);
    let xB = fCx + (fRx - 5) * cos(a + 4);
    let yB = fCy + (fRy - 5) * sin(a + 4);
    brush.line(xA, yA, xB, yB);
  }

  // Perimeter weld seam & rivet ring around the front elliptical tank bulkhead
  for (let a = -150; a <= 85; a += 5.5) {
    let rx = fCx + fRx * cos(a);
    let ry = fCy + fRy * sin(a);
    drawMicroRivet(rx, ry, 0.65);
  }

  // Top Vapor-Recovery Catwalk / Rollover Guard Rail on Crown of Tank
  washQuad(560, 540, 646, 544, 672, 620, 595, 548, "#455a6b", 210);
  brush.set("microPen", "#f5efe2", 0.75);
  brush.line(558, 540, 646, 544);
  brush.line(562, 546, 650, 549);
  for (let x = 564; x <= 642; x += 9) {
    brush.set("microPen", "#232a34", 0.55);
    brush.line(x, 540, x + 2, 551);
  }

  // ---------------------------------------------------------------------------
  // B. TALL DUAL VERTICAL CHROME EXHAUST STACKS & PERFORATED MUFFLER SHIELDS
  // ---------------------------------------------------------------------------
  drawExhaustStack(504, 542, 688, 12, -1);
  drawExhaustStack(660, 542, 688, 12, 1);

  // ---------------------------------------------------------------------------
  // C. TRACTOR CAB ROOF, CLEARANCE LIGHTS, SUN VISOR & SPLIT WINDSHIELD
  // ---------------------------------------------------------------------------
  // Cab roof crown
  const cabRoofPts = [
    [CX - 56, 592],
    [CX - 46, 576],
    [CX + 46, 576],
    [CX + 56, 592]
  ];
  washPoly(cabRoofPts, "#6a8395", 240);
  washQuad(CX - 42, 578, CX + 42, 578, CX + 48, 586, CX - 48, 586, "#d9d4c7", 210);

  // 5 Glowing Amber Torpedo Clearance Lights on Cab Roof
  const roofLightXs = [CX - 40, CX - 20, CX, CX + 20, CX + 40];
  for (let lx of roofLightXs) {
    // Chrome base
    washRect(lx - 3.5, 571, 7, 6, "#d8d4c8", 240);
    // Glowing amber lens + halation
    washRect(lx - 2.8, 572, 5.6, 4, "#ff9d2e", 250);
    brush.set("microPen", "#fff9e6", 0.65);
    brush.line(lx - 1.2, 573.5, lx + 1.2, 573.5);
    brush.set("hazeBand", "#f5a638", 0.35);
    brush.line(lx - 9, 574, lx + 9, 574);
  }

  // Deep Riveted Stainless Sun Visor (x = CX-65..CX+65, y = 588..603)
  const visorPts = [
    [CX - 62, 587],
    [CX + 62, 587],
    [CX + 66, 601],
    [CX, 604],
    [CX - 66, 601]
  ];
  washPoly(visorPts, "#e6dfd2", 250);
  // Dark reflection band across visor middle
  washQuad(CX - 64, 593, CX + 64, 593, CX + 65, 598, CX - 65, 598, "#353945", 220);
  // Bright lower visor lip
  brush.set("chromeBar", "#fffdf7", 0.7);
  brush.line(CX - 65, 600, CX, 603);
  brush.line(CX, 603, CX + 65, 600);
  // Row of 18 micro-rivets along the top flange of the sun visor
  for (let rx = CX - 58; rx <= CX + 58; rx += 6.8) {
    drawMicroRivet(rx, 589.5, 0.6);
  }

  // Cab Windshield Frame & Split Two-Piece Glass (y = 601..635)
  washQuad(CX - 63, 601, CX + 63, 601, CX + 66, 636, CX - 66, 636, "#465564", 245);

  // Left & Right Windshield Panes
  washQuad(CX - 58, 604, CX - 3, 604, CX - 3, 632, CX - 60, 632, "#141c26", 250);
  washQuad(CX + 3, 604, CX + 58, 604, CX + 60, 632, CX + 3, 632, "#161f29", 250);

  // Under-visor cast shadow on top of glass
  washQuad(CX - 58, 604, CX + 58, 604, CX + 58, 612, CX - 58, 612, "#0b0f15", 230);

  // Diagonal cerulean & bone sky glare slashes across split windshield panes
  washQuad(CX - 48, 612, CX - 24, 612, CX - 34, 631, CX - 56, 631, "#7b97a8", 185);
  washQuad(CX - 30, 612, CX - 18, 612, CX - 26, 631, CX - 36, 631, "#e5dccb", 195);
  washQuad(CX + 14, 612, CX + 38, 612, CX + 28, 631, CX + 6, 631, "#7b97a8", 175);
  washQuad(CX + 32, 612, CX + 44, 612, CX + 34, 631, CX + 24, 631, "#e5dccb", 185);

  // Center division bar, rubber gasket seal & dual windshield wipers
  brush.set("microPen", "#0a0c10", 0.9);
  brush.line(CX - 58, 604, CX - 60, 632);
  brush.line(CX + 58, 604, CX + 60, 632);
  brush.line(CX - 60, 632, CX + 60, 632);
  brush.set("chromeBar", "#d8d4c8", 0.65);
  brush.line(CX, 603, CX, 633);
  // Wiper blades
  brush.set("microPen", "#111318", 0.75);
  brush.line(CX - 32, 633, CX - 8, 626);
  brush.line(CX + 32, 633, CX + 8, 626);
  brush.set("microPen", "#cfd5da", 0.4);
  brush.line(CX - 32, 632.3, CX - 8, 625.3);
  brush.line(CX + 32, 632.3, CX + 8, 625.3);

  // ---------------------------------------------------------------------------
  // D. WEST-COAST SIDE MIRRORS & CYLINDRICAL CHROME AIR CLEANERS
  // ---------------------------------------------------------------------------
  drawWestCoastMirror(CX - 63, 600, 634, -1);
  drawWestCoastMirror(CX + 63, 600, 634, 1);

  drawChromeAirCleaner(CX - 73, 638, 20, 44);
  drawChromeAirCleaner(CX + 53, 638, 20, 44);

  // ---------------------------------------------------------------------------
  // E. RIVETED LONG HOOD & SCULPTED FRONT FENDERS
  // ---------------------------------------------------------------------------
  // Hood top plane receding from grille crown (y=660) back to cowl (y=634)
  washQuad(CX - 60, 635, CX + 60, 635, CX + 52, 661, CX - 52, 661, "#829dad", 245);
  // Bright bone horizon reflection along the top of the hood
  washQuad(CX - 46, 636, CX + 46, 636, CX + 42, 660, CX - 42, 660, "#e8dfd0", 220);
  // Subtle dark reflection strips along hood shoulders
  washQuad(CX - 59, 636, CX - 45, 636, CX - 42, 660, CX - 51, 660, "#374654", 215);
  washQuad(CX + 45, 636, CX + 59, 636, CX + 51, 660, CX + 42, 660, "#374654", 215);

  // Center chrome hood hinge strip & hood ornament crest
  brush.set("chromeBar", "#fffdf8", 0.85);
  brush.line(CX, 634, CX, 660);
  brush.set("microPen", "#242832", 0.6);
  brush.line(CX - 1.2, 634, CX - 1.2, 660);
  brush.line(CX + 1.2, 634, CX + 1.2, 660);

  // Perspective rows of rivets along the hood seams & cowl
  for (let i = 0; i < 14; i++) {
    let t = i / 13;
    let ry = lerp(636, 659, t);
    let lx = lerp(CX - 57, CX - 49, t);
    let rx = lerp(CX + 57, CX + 49, t);
    drawMicroRivet(lx, ry, 0.65);
    drawMicroRivet(rx, ry, 0.65);
  }
  for (let rx = CX - 56; rx <= CX + 56; rx += 6.5) {
    drawMicroRivet(rx, 636, 0.6);
  }

  // Sculpted Front Fenders (flanking the radiator grille)
  drawFrontFender(CX - 52, 686, 756, -1);
  drawFrontFender(CX + 52, 686, 756, 1);

  // ---------------------------------------------------------------------------
  // F. MONUMENTAL HYPERREAL CHROME RADIATOR GRILLE & RIVETS
  // ---------------------------------------------------------------------------
  renderHyperrealGrille(CX, 659, 104, 97);

  // ---------------------------------------------------------------------------
  // G. TWIN HALOGEN HEADLIGHT PODS & AMBER FENDER INDICATORS
  // ---------------------------------------------------------------------------
  drawHeadlightPod(CX - 72, 725, -1);
  drawHeadlightPod(CX + 72, 725, 1);

  // ---------------------------------------------------------------------------
  // H. HEAVY TEXAS CHROME BUMPER, BOLTS, TOW PINS & STEER TIRES
  // ---------------------------------------------------------------------------
  renderChromeBumperAndTires(CX, 756);
}

function sampleChromeReflection(deg) {
  // Maps cylinder surface normal angle (-165..95) to hyperreal sky/horizon/asphalt reflection color
  if (deg < -115) return color("#24394d");      // Deep twilight upper sky
  if (deg < -75)  return color("#4d6e85");      // Cerulean sky
  if (deg < -42)  return color("#fbf6eb");      // Blazing white-bone specular core
  if (deg < -18)  return color("#9cb4c2");      // Bleached cerulean
  if (deg < -4)   return color("#efe5d4");      // Luminous horizon bone
  if (deg < 8)    return color("#2c2229");      // Crisp dark desert horizon line wrapped on cylinder
  if (deg < 22)   return color("#6e5859");      // Mauve-ochre desert reflection
  if (deg < 48)   return color("#262730");      // Dark highway asphalt reflection
  return color("#49444c");                      // Lower road bounce light
}

function drawExhaustStack(x, yTop, yBot, w, dir) {
  let hw = w * 0.5;
  // Curved turnout tip at the top
  washQuad(x - hw, yTop + 10, x + hw, yTop + 10, x + hw + dir * 6, yTop, x - hw + dir * 4, yTop + 2, "#35495c", 240);
  brush.set("microPen", "#12151c", 0.7);
  brush.line(x + dir * 5, yTop, x + hw + dir * 6, yTop + 3);

  // Vertical cylindrical chrome slices
  washRect(x - hw, yTop + 10, w, yBot - yTop - 10, "#242730", 245);
  washRect(x - hw + 1.5, yTop + 10, w * 0.35, yBot - yTop - 10, "#7594a8", 235);
  washRect(x - 1.2, yTop + 10, 3.2, yBot - yTop - 10, "#fffdf8", 250);
  washRect(x + 2.2, yTop + 10, w * 0.25, yBot - yTop - 10, "#c8beb0", 220);

  // Perforated muffler heat shield (lower half of stack: y = 602..682)
  let shTop = 602, shBot = 682;
  brush.set("microPen", "#181a22", 0.65);
  brush.line(x - hw - 1, shTop, x + hw + 1, shTop);
  brush.line(x - hw - 1, shBot, x + hw + 1, shBot);

  // Chrome mounting clamps with rivets
  for (let cy of [shTop + 2, (shTop + shBot) * 0.5, shBot - 2]) {
    washRect(x - hw - 1.5, cy - 2, w + 3, 4, "#f0eae0", 245);
    drawMicroRivet(x - hw, cy, 0.55);
    drawMicroRivet(x + hw, cy, 0.55);
  }

  // Grid of tiny cooling perforations on muffler guard
  brush.set("microPen", "#14161d", 0.45);
  for (let py = shTop + 8; py < shBot - 6; py += 5.5) {
    for (let px = x - hw + 2.5; px <= x + hw - 2; px += 3.2) {
      brush.line(px, py, px + 0.6, py + 1.2);
    }
  }
}

function drawWestCoastMirror(anchorX, yTop, yBot, dir) {
  let mx = anchorX + dir * 20;
  let mw = 11;
  let mh = yBot - yTop;

  // Stainless tubular mounting struts (upper & lower triangles)
  brush.set("microPen", "#232730", 0.75);
  brush.line(anchorX, yTop + 3, mx, yTop + 2);
  brush.line(anchorX, yTop + 10, mx, yTop + 2);
  brush.line(anchorX, yBot - 3, mx, yBot - 2);
  brush.line(anchorX, yBot - 10, mx, yBot - 2);

  brush.set("microPen", "#f7f2e7", 0.55);
  brush.line(anchorX, yTop + 2.3, mx, yTop + 1.3);
  brush.line(anchorX, yBot - 3.7, mx, yBot - 2.7);

  // Vertical mirror spindle rod
  brush.set("microPen", "#d8d3c8", 0.65);
  brush.line(mx, yTop - 3, mx, yBot + 14);

  // Rectangular stainless mirror housing
  let xLeft = mx - mw * 0.5;
  washRect(xLeft, yTop, mw, mh, "#e6dfd2", 245);
  washRect(xLeft + 1.5, yTop + 3, mw - 3, mh * 0.45, "#6c899c", 220);
  washRect(xLeft + 1.5, yTop + 3 + mh * 0.45, mw - 3, mh * 0.42, "#2a2730", 230);

  // Crisp frame & vertical antenna whip rising from mirror bracket
  brush.set("microPen", "#1a1d24", 0.6);
  brush.rect(xLeft, yTop, mw, mh, "corner");
  brush.set("microPen", "#fffdf8", 0.55);
  brush.line(xLeft + 1, yTop + 1, xLeft + 1, yBot - 1);

  // Thin stainless CB antenna whip extending upward
  brush.set("microPen", "#d4dce0", 0.35);
  brush.line(mx + dir * 3, yTop, mx + dir * 4, yTop - 48);

  // Round convex spot mirror below main West-Coast mirror
  washRect(mx - 4.5, yBot + 4, 9, 7, "#252932", 235);
  brush.set("microPen", "#f2ece0", 0.55);
  brush.circle(mx, yBot + 7.5, 4.2);
}

function drawChromeAirCleaner(x, y, w, h) {
  // Cylindrical stainless canister mounted beside cab cowl
  // Conical rain cap on top
  washQuad(x - 2, y + 5, x + w + 2, y + 5, x + w - 2, y, x + 2, y, "#42586b", 240);
  brush.set("chromeBar", "#fbf5e9", 0.6);
  brush.line(x - 1, y + 5, x + w + 1, y + 5);

  // Main cylinder body with vertical chrome bands
  washRect(x, y + 5, w, h - 5, "#23252e", 245);
  washRect(x + 2, y + 5, w * 0.35, h - 5, "#829eb0", 230);
  washRect(x + w * 0.38, y + 5, w * 0.24, h - 5, "#fffcf5", 250);
  washRect(x + w * 0.65, y + 5, w * 0.22, h - 5, "#cfc5b6", 225);

  // Two horizontal mounting straps with rivets
  for (let sy of [y + 15, y + h - 10]) {
    washRect(x - 1, sy, w + 2, 3.2, "#e8e1d3", 245);
    brush.set("microPen", "#171920", 0.55);
    brush.line(x - 1, sy, x + w + 1, sy);
    brush.line(x - 1, sy + 3.2, x + w + 1, sy + 3.2);
    drawMicroRivet(x + 3, sy + 1.6, 0.55);
    drawMicroRivet(x + w - 3, sy + 1.6, 0.55);
  }
}

function drawFrontFender(innerX, yTop, yBot, dir) {
  // Curved front wheel arch fender flanking the radiator grille
  let topW = 24;
  let botW = 44;

  // Upper fender crown (reflects cerulean & bone sky)
  let yMid = lerp(yTop, yBot, 0.42);
  washQuad(
    innerX, yTop,
    innerX + dir * topW, yTop + 6,
    innerX + dir * (botW - 4), yMid,
    innerX, yMid,
    "#829cad",
    245
  );
  // Bright horizon specular ridge across fender arch
  washQuad(
    innerX + dir * 3, yMid - 5,
    innerX + dir * (botW - 5), yMid - 2,
    innerX + dir * botW, yMid + 6,
    innerX + dir * 2, yMid + 4,
    "#f2ead9",
    240
  );
  // Lower fender skirt (reflects dark foreground asphalt)
  washQuad(
    innerX, yMid + 4,
    innerX + dir * botW, yMid + 6,
    innerX + dir * (botW + 2), yBot,
    innerX, yBot,
    "#252630",
    245
  );

  // Crisp fender seam against hood/grille + row of rivets
  brush.set("microPen", "#12141b", 0.8);
  brush.line(innerX, yTop, innerX, yBot);
  for (let ry = yTop + 6; ry <= yBot - 6; ry += 7.5) {
    drawMicroRivet(innerX + dir * 3.2, ry, 0.55);
  }

  // Amber fender-tip turn signal indicator mounted at top outer corner
  let sigX = innerX + dir * (topW + 4);
  let sigY = yTop + 8;
  washRect(sigX - 4, sigY - 3, 8, 6, "#d9d4c7", 240);
  washRect(sigX - 3, sigY - 2, 6, 4, "#f5982e", 250);
  brush.set("microPen", "#fff8e6", 0.6);
  brush.line(sigX - 1.5, sigY, sigX + 1.5, sigY);
}

function renderHyperrealGrille(cx, yTop, gw, gh) {
  let xLeft = cx - gw * 0.5;
  let xRight = cx + gw * 0.5;
  let yBot = yTop + gh;

  // 1. Outer Polished Chrome Grille Surround
  // Top crown header (15px tall, slightly arched)
  const crownPts = [
    [xLeft, yTop + 3],
    [cx, yTop - 2],
    [xRight, yTop + 3],
    [xRight, yTop + 16],
    [xLeft, yTop + 16]
  ];
  washPoly(crownPts, "#ede6d8", 255);
  // Dark horizon reflection band inside the chrome crown
  washQuad(xLeft + 3, yTop + 7, xRight - 3, yTop + 7, xRight - 3, yTop + 12, xLeft + 3, yTop + 12, "#2d2a35", 225);
  // Blazing top bevel highlight
  brush.set("chromeBar", "#ffffff", 0.9);
  brush.line(xLeft + 2, yTop + 2.5, cx, yTop - 1.5);
  brush.line(cx, yTop - 1.5, xRight - 2, yTop + 2.5);

  // Left, Right & Bottom Chrome Grille Pillars
  let pillarW = 9;
  washRect(xLeft, yTop + 15, pillarW, gh - 15, "#e6dfd2", 250);
  washRect(xRight - pillarW, yTop + 15, pillarW, gh - 15, "#e6dfd2", 250);
  washRect(xLeft, yBot - 7, gw, 7, "#dcd5c7", 250);

  // Chrome reflection shading on side pillars
  washRect(xLeft + 2, yTop + 16, 3, gh - 22, "#2b2c36", 215);
  washRect(xRight - pillarW + 4, yTop + 16, 3, gh - 22, "#2b2c36", 215);
  brush.set("microPen", "#ffffff", 0.75);
  brush.line(xLeft + 6.5, yTop + 16, xLeft + 6.5, yBot - 7);
  brush.line(xRight - 6.5, yTop + 16, xRight - 6.5, yBot - 7);

  // 2. Recessed Dark Radiator Core Interior
  let inL = xLeft + pillarW;
  let inR = xRight - pillarW;
  let inT = yTop + 16;
  let inB = yBot - 7;
  let inW = inR - inL;
  let inH = inB - inT;

  washRect(inL, inT, inW, inH, "#0e1016", 255);

  // Subtle internal radiator core diagonal cross-member & fan shroud shadow behind louvers
  brush.set("2B", "#1c202b", 0.85);
  brush.line(inL + 4, inT + 4, cx, inB - 4);
  brush.line(inR - 4, inT + 4, cx, inB - 4);

  // 3 horizontal structural tie-bars behind the vertical louvers
  for (let ty of [inT + inH * 0.26, inT + inH * 0.52, inT + inH * 0.78]) {
    washRect(inL, ty - 1.2, inW, 2.4, "#2c313d", 230);
    brush.set("microPen", "#8a96a3", 0.45);
    brush.line(inL, ty - 0.8, inR, ty - 0.8);
  }

  // 3. 27 Razor-Sharp Vertical Stainless Grille Louvers
  let numLouvers = 27;
  for (let i = 1; i < numLouvers; i++) {
    let u = i / numLouvers;
    let lx = lerp(inL, inR, u);

    // Dark slot shadow beside louver
    brush.set("microPen", "#06070a", 0.7);
    brush.line(lx - 0.9, inT, lx - 0.9, inB);

    // Upper louver half (reflects bright bone/cerulean sky)
    brush.set("microPen", "#eef2f5", 0.62);
    brush.line(lx, inT + 1, lx, inT + inH * 0.56);

    // Lower louver half (reflects darker twilight horizon & road with metallic sheen)
    brush.set("microPen", "#96a3b0", 0.55);
    brush.line(lx, inT + inH * 0.56, lx, inB - 1);

    // Hot specular glint where horizon reflection crosses each louver
    let glintY = inT + inH * 0.44 + sin(i * 18) * 1.5;
    brush.set("microPen", "#ffffff", 0.85);
    brush.line(lx, glintY - 3, lx, glintY + 3);
  }

  // Central thick vertical Chrome Divider Bar
  washRect(cx - 2.2, inT, 4.4, inH, "#e8e1d4", 250);
  brush.set("microPen", "#23252e", 0.65);
  brush.line(cx - 2.2, inT, cx - 2.2, inB);
  brush.line(cx + 2.2, inT, cx + 2.2, inB);
  brush.set("microPen", "#ffffff", 0.75);
  brush.line(cx, inT, cx, inB);

  // Crisp inner and outer bezel outlines around grille
  brush.set("microPen", "#0a0c10", 0.85);
  brush.rect(inL, inT, inW, inH, "corner");
  brush.line(xLeft, yTop + 3, xLeft, yBot);
  brush.line(xRight, yTop + 3, xRight, yBot);

  // 4. Iconic Red & Chrome Oval Truck Emblem on Grille Crown
  washRect(cx - 12, yTop + 3.5, 24, 9, "#ffffff", 245);
  washRect(cx - 10, yTop + 4.8, 20, 6.4, "#9e2424", 250);
  brush.set("microPen", "#181a22", 0.6);
  brush.rect(cx - 12, yTop + 3.5, 24, 9, "corner");
  // Tiny chrome script flourish inside oval badge
  brush.set("microPen", "#fffdf9", 0.55);
  brush.line(cx - 7, yTop + 8, cx + 7, yTop + 7.5);

  // 5. Perimeter Rivets around the Chrome Grille Surround
  for (let ry = inT + 4; ry <= inB - 4; ry += 8.5) {
    drawMicroRivet(xLeft + 4.5, ry, 0.62);
    drawMicroRivet(xRight - 4.5, ry, 0.62);
  }
  for (let rx = xLeft + 8; rx <= xRight - 8; rx += 11) {
    if (abs(rx - cx) > 15) {
      drawMicroRivet(rx, yTop + 13.5, 0.58);
    }
    drawMicroRivet(rx, yBot - 3.5, 0.58);
  }
}

function drawHeadlightPod(podCx, podCy, dir) {
