  let y0 = podCy - podH * 0.5;

  // Support bracket arm connecting pod to grille side pillar
  let bracketInnerX = dir < 0 ? podCx + podW * 0.5 : podCx - podW * 0.5;
  let grilleEdgeX = 582 + dir * 52;
  washRect(min(bracketInnerX, grilleEdgeX), podCy - 3.5, abs(grilleEdgeX - bracketInnerX), 7, "#313440", 245);
  brush.set("microPen", "#e8e1d4", 0.65);
  brush.line(bracketInnerX, podCy - 2.5, grilleEdgeX, podCy - 2.5);

  // Outer chrome bezel housing
  washRect(x0 - 2, y0 - 2, podW + 4, podH + 4, "#242630", 245);
