  brush.set("microPen", "#12141b", 0.75);
  brush.rect(x0, y0, podW, podH, "corner");
  brush.set("microPen", "#ffffff", 0.75);
  brush.line(x0 + 1, y0 + 1, x0 + podW - 1, y0 + 1);

  // Two round sealed-beam halogen lamps inside pod
  const lampXs = [podCx - 7.5, podCx + 7.5];
  for (let lx of lampXs) {
    // Dark reflector ring
    washRect(lx - 6, podCy - 6, 12, 12, "#2f333e", 245);
    // Warm golden halogen reflector bowl
