function renderChromeBumperAndTires(cx, yTop) {
  let bw = 198;
  let bh = 31;
  let xL = cx - bw * 0.5;
  let xR = cx + bw * 0.5;
  let yBot = yTop + bh;

  // ---------------------------------------------------------------------------
  // 1. FRONT STEER TIRES, TANDEM TRAILER AXLES & UNDERCARRIAGE SHADOW
  // ---------------------------------------------------------------------------
  // Deep shadow under truck chassis melting into road shimmer
  washQuad(xL - 8, yBot - 4, xR + 36, yBot - 4, xR + 42, yBot + 24, xL - 14, yBot + 24, "#12131a", 245);

  // Left & Right wide front steer tires + right-side trailer duals in perspective
  const tires = [
    { x: xL + 4,  w: 30, y0: yBot - 6, y1: yBot + 22 },
    { x: xR - 34, w: 30, y0: yBot - 6, y1: yBot + 22 },
    { x: xR + 2,  w: 22, y0: yBot - 12, y1: yBot + 14 },
    { x: xR + 25, w: 18, y0: yBot - 16, y1: yBot + 8 }
  ];

  for (let tr of tires) {
    washRect(tr.x, tr.y0, tr.w, tr.y1 - tr.y0, "#171820", 250);
    // Vertical tire tread ribs in crisp graphite/pen
    brush.set("microPen", "#08090d", 0.75);
    for (let tx = tr.x + 3; tx < tr.x + tr.w - 2; tx += 4.2) {
      brush.line(tx, tr.y0, tx, tr.y1);
      brush.set("microPen", "#3c3e4a", 0.4);
      brush.line(tx + 1.2, tr.y0 + 2, tx + 1.2, tr.y1 - 2);
      brush.set("microPen", "#08090d", 0.75);
    }
  }

  // ---------------------------------------------------------------------------
  // 2. MONUMENTAL TEXAS-STYLE FLAT POLISHED CHROME BUMPER
  // ---------------------------------------------------------------------------
  // Top sky-reflecting bevel lip
  washQuad(xL + 2, yTop, xR - 2, yTop, xR, yTop + 5, xL, yTop + 5, "#fbf6eb", 255);

  // Upper face reflecting bleached bone & cerulean sky
  washRect(xL, yTop + 5, bw, 7, "#9bb3c2", 245);
  washRect(xL, yTop + 9, bw, 4, "#efe5d3", 250);

  // Sharp horizon transition & warped dark asphalt reflection across main bumper face
  washRect(xL, yTop + 13, bw, 13, "#1b1c24", 250);
  // Reflection of the yellow highway center line inside the chrome bumper!
  washQuad(cx - 18, yTop + 14, cx - 8, yTop + 14, cx - 14, yBot - 2, cx - 24, yBot - 2, "#d49b3b", 215);

  // Lower bumper reflection strip catching warm road bounce light
  washRect(xL, yBot - 5, bw, 5, "#8c7f78", 235);

  // Crisp outer perimeter & bevel lines
  brush.set("chromeBar", "#ffffff", 0.95);
  brush.line(xL + 1, yTop + 4.5, xR - 1, yTop + 4.5);
  brush.set("microPen", "#0d0e14", 0.85);
  brush.rect(xL, yTop + 4, bw, bh - 4, "corner");

  // Rectangular tow-pin cutouts & central license plate recess
  washRect(cx - 46, yTop + 12, 16, 8, "#0b0c11", 250);
  washRect(cx + 30, yTop + 12, 16, 8, "#0b0c11", 250);
  brush.set("microPen", "#f2ece0", 0.55);
  brush.rect(cx - 46, yTop + 12, 16, 8, "corner");
  brush.rect(cx + 30, yTop + 12, 16, 8, "corner");

  // License plate mounted center-left on bumper
  washRect(cx - 11, yTop + 10, 22, 12, "#dfd8c8", 245);
  brush.set("microPen", "#1e2430", 0.65);
  brush.rect(cx - 11, yTop + 10, 22, 12, "corner");
  brush.line(cx - 8, yTop + 16, cx + 8, yTop + 16);

  // Chrome carriage bolts / rivets across bumper face
  const boltXs = [xL + 10, xL + 26, cx - 62, cx - 24, cx + 24, cx + 62, xR - 26, xR - 10];
  for (let bx of boltXs) {
    drawMicroRivet(bx, yTop + 9, 0.78);
    drawMicroRivet(bx, yTop + 22, 0.78);
  }

  // Row of 9 glowing amber LED marker lights along bottom lip of bumper
  for (let i = -4; i <= 4; i++) {
    let lx = cx + i * 21;
    washRect(lx - 3, yBot - 3.8, 6, 2.8, "#ff9d2e", 250);
    brush.set("microPen", "#fff9e6", 0.6);
    brush.line(lx - 1.2, yBot - 2.4, lx + 1.2, yBot - 2.4);
  }

  // ---------------------------------------------------------------------------
  // 3. HEAT-SHEARED DISSOLUTION AT THE BOTTOM OF THE TIRES (y = yBot..yBot+26)
  // Where the real truck meets the shimmering inferior road mirage
  // ---------------------------------------------------------------------------
  for (let y = yBot - 2; y <= yBot + 26; y += 2.4) {
    let wob = sin(y * 7.5) * 9 + (noise(y * 0.25, 5.5) - 0.5) * 16;
    let col = (floor(y / 2.4) % 2 === 0) ? "#16171f" : "#d8cab8";
    brush.set("chromeBar", col, 0.55);
    brush.line(xL - 8 + wob, y, xR + 28 + wob, y);
  }
}

function drawMicroRivet(x, y, scale = 0.65) {
  // Hyperrealist rivet: dark cast shadow crescent below/left + bright bone specular dot above/right
  brush.set("microPen", "#14161e", 0.75 * scale);
  brush.line(x - 0.9 * scale, y + 0.5 * scale, x + 0.7 * scale, y + 0.8 * scale);
  brush.set("microPen", "#ffffff", 0.85 * scale);
  brush.line(x - 0.5 * scale, y - 0.4 * scale, x + 0.6 * scale, y - 0.4 * scale);
}

