// =========================================================================
// GEOMETRY & RENDERING HELPERS
// =========================================================================

function washPoly(pts, col, alpha) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, alpha);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function washQuad(p1, p2, p3, p4, col, alpha) {
  washPoly([p1, p2, p3, p4], col, alpha);
}

// Flat, dense marker fill across a quad by interpolating scanlines
function markerQuad(p1, p2, p3, p4, col, weight, steps, wobble = 0) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("marker", col, weight);
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let xA = lerp(p1[0], p4[0], t) + random(-wobble, wobble);
    let yA = lerp(p1[1], p4[1], t) + random(-wobble, wobble);
    let xB = lerp(p2[0], p3[0], t) + random(-wobble, wobble);
    let yB = lerp(p2[1], p3[1], t) + random(-wobble, wobble);
    brush.line(xA, yA, xB, yB);
  }
}

// Curved marker strokes across a ribbon defined by two point arrays
function markerRibbon(railA, railB, col, weight, steps) {
  brush.noFill();
  brush.noWash();
  brush.set("marker", col, weight);
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let pts = [];
    for (let j = 0; j < railA.length; j++) {
      let x = lerp(railA[j][0], railB[j][0], t);
      let y = lerp(railA[j][1], railB[j][1], t);
      pts.push([x, y, 1]);
    }
    brush.spline(pts, 0.4);
  }
}

// Stitch seam helper (industrial double or single stitch)
function drawStitchLine(x1, y1, x2, y2, col, shadowCol, spacing = 11) {
  let d = dist(x1, y1, x2, y2);
  let n = floor(d / spacing);
  for (let i = 0; i < n; i++) {
    let t1 = (i + 0.15) / n;
    let t2 = (i + 0.72) / n;
    let sx1 = lerp(x1, x2, t1);
    let sy1 = lerp(y1, y2, t1);
    let sx2 = lerp(x1, x2, t2);
    let sy2 = lerp(y1, y2, t2);
    brush.set("rotring", shadowCol, 0.45);
    brush.line(sx1 + 1, sy1 + 1.2, sx2 + 1, sy2 + 1.2);
    brush.set("rotring", col, 0.55);
    brush.line(sx1, sy1, sx2, sy2);
  }
}

// Sweat droplet helper with overcast highlight + chartreuse vest bounce light
function drawSweatBead(x, y, rx, ry, angle = 0, hasTrail = false, trailLen = 0) {
  if (hasTrail) {
    // Moist trail above the droplet
    brush.set("marker", "#9c563b", 0.35);
    brush.line(x + random(-2, 2), y - trailLen, x, y);
    brush.set("pen", "#f7d5b5", 0.3);
    brush.line(x - rx * 0.25, y - trailLen * 0.85, x - rx * 0.2, y - ry * 0.5);
  }

  // Drop shadow below bead
  brush.set("cpencil", "#3d1e12", 0.55);
  brush.arc(x + 1, y + 2, rx * 1.05, 15, 165);

  // Dark upper interior refraction
  brush.set("marker", "#6e3522", 0.4);
  brush.line(x - rx * 0.5, y - ry * 0.3, x + rx * 0.5, y - ry * 0.3);

  // Warm flesh core
  brush.set("cpencil", "#e09872", 0.5);
  brush.line(x - rx * 0.4, y + ry * 0.15, x + rx * 0.4, y + ry * 0.15);

  // Fluorescent yellow-green bounce reflection at bottom rim of droplet
  brush.set("pen", "#d9f542", 0.45);
  brush.arc(x, y + 0.5, rx * 0.85, 25, 155);

  // Razor-sharp white overcast sky specular highlight on top
  brush.set("pen", "#ffffff", 0.65);
  brush.line(x - rx * 0.35, y - ry * 0.45, x + rx * 0.15, y - ry * 0.5);
  brush.set("rotring", "#ffffff", 0.8);
  brush.line(x - rx * 0.15, y - ry * 0.48, x + 0.5, y - ry * 0.48);
}

