  markerQuad([600, 668], [805, 625], [770, 880], [600, 910], "#1e1f1d", 1.8, 28, 1);

  // Sweat-darkened collar band (ribbed knit collar around y=620..695)
  for (let i = 0; i <= 110; i++) {
