    brush.set("rotring", ribCol, 0.65);
    brush.line(cx, cy, nx, ny);
  }

  // Shirt fabric horizontal folds & scuffed cotton grain
  for (let y = 695; y < 895; y += 3.5) {
    let halfW = map(y, 695, 895, 185, 25);
    let col = y % 7 < 3.5 ? "#333431" : "#1d1e1c";
    brush.set("cpencil", col, 0.55);
    brush.line(600 - halfW, y + random(-2, 2), 600 + halfW, y + random(-2, 2));
