  // Scuffed lint & road dust specks on dark grey shirt
  for (let i = 0; i < 140; i++) {
    let ry = random(645, 880);
    let maxW = map(ry, 640, 890, 170, 15);
    let rx = 600 + random(-maxW, maxW);
    brush.set("pen", random(["#595a54", "#78776e", "#949689"]), 0.35);
    brush.line(rx, ry, rx + random(1, 3), ry + random(-1, 2));
  }
}

