    brush.line(x1, y1 - random(2, 16), x1 + random(-8, 8), y1);
  }

  // 4. Cross-contour hyperreal skin modeling (pores & sun-weathered flesh grain)
  for (let i = 0; i < 420; i++) {
    let rx = random(370, 830);
    let ry = random(310, 545);
    // Keep inside jaw contour
    let maxJawY = 556 - pow(abs(rx - 600) / 235, 1.85) * 115;
    if (ry < maxJawY) {
      let distCenter = abs(rx - 600);
      let col;
      if (ry < 340) {
        col = random(["#7d351e", "#944227", "#ad5436"]); // Warm orange-tinted brim shadow
      } else if (distCenter < 95 && ry > 468 && ry < 532) {
        col = random(["#e8a884", "#f0ba99", "#cf835f"]); // Chin highlight
      } else if (distCenter > 135) {
        col = random(["#7a3b24", "#8f4930", "#69301c"]); // Jaw sides
      } else {
        col = random(["#b56947", "#c97b58", "#d68b67", "#9e5538"]);
