    [506, 421], [548, 409], [578, 402], [600, 407],
    [622, 402], [652, 409], [694, 421],
    [645, 420], [600, 423], [555, 420]
  ];
  washPoly(upperLip, "#783227", 235);

  // Cupid's bow bright skin rim right above upper lip
  brush.set("pen", "#f2ba96", 0.55);
  brush.spline([[530, 412, 0.4], [578, 401, 1], [600, 406, 1], [622, 401, 1], [670, 412, 0.4]], 0.4);

  // Lower lip (catching overcast light on top & chartreuse bounce underneath)
  let lowerLip = [
    [514, 421], [555, 420], [600, 423], [645, 420], [686, 421],
    [668, 440], [634, 448], [600, 450], [566, 448], [532, 440]
  ];
  washPoly(lowerLip, "#b85d4d", 230);

  // Vertical chapped lip ridges & dry skin fissures
  for (let lx = 520; lx <= 680; lx += 3.2) {
    let t = (lx - 520) / 160;
    let curve = sin(t * 180);
    let yTop = 421 + (1 - curve) * 1.5;
    let yBot = 422 + curve * 27;

    // Upper lip vertical shading
    brush.set("cpencil", random(["#5e2219", "#8c3d30", "#4a1912"]), 0.45);
    brush.line(lx, yTop - curve * 17, lx + random(-1, 1), yTop);

    // Lower lip vertical contour strokes
    let lowCol = random(["#d67b69", "#a34839", "#e89887", "#8f3b2e"]);
    brush.set("cpencil", lowCol, 0.5);
    brush.line(lx, yTop + 1, lx + (lx - 600) * 0.04, yBot);

    // Occasional deep chapped fissure & bright specular glint
    if (random(1) < 0.25) {
      brush.set("rotring", "#4d1710", 0.4);
      brush.line(lx, yTop + 2, lx + (lx - 600) * 0.03, yBot - 3);
    }
    if (curve > 0.45 && random(1) < 0.55) {
      brush.set("pen", "#ffdfd4", 0.45);
      brush.line(lx, yTop + 5, lx, yTop + 12);
    }
  }

  // Blunt resolute lip parting line & mouth corners
  brush.set("rotring", "#240a06", 0.9);
  brush.spline([
    [504, 422, 0.7], [552, 419, 1.0], [600, 423, 1.2], [648, 419, 1.0], [696, 422, 0.7]
  ], 0.4);
  // Mouth corner creases
  brush.set("2B", "#471910", 0.7);
  brush.line(496, 426, 512, 419);
  brush.line(688, 419, 704, 426);

  // Deep labiomental crease below lower lip (y = 452..468)
  washPoly([[530, 448], [600, 452], [670, 448], [650, 468], [600, 472], [550, 468]], "#632718", 190);
