  // -----------------------------------------------------------------------
  for (let i = 0; i < 3650; i++) {
    let sx = random(362, 838);
    let sy = random(335, 618);

    // Anatomical mask: where stubble grows
    let dx = sx - 600;
    let absDx = abs(dx);

    // Exclude nose above y=362
    if (sy < 363 && absDx < 66) continue;
    // Exclude lips (y=402..449, absDx < 94)
    if (sy > 401 && sy < 449 && absDx < 93) continue;
    // Exclude upper cheek bones above beard line
    let beardTopY = map(absDx, 65, 240, 385, 315, true);
    if (sy < beardTopY && !(sy >= 363 && sy <= 402 && absDx < 98)) continue;

    // Exclude outside jaw / neck silhouette
    let jawEdgeY = 558 - pow(absDx / 236, 1.85) * 118;
    if (sy < 520 && absDx > 236) continue;
    if (sy > jawEdgeY && absDx > 188) continue;

    // Compute natural follicle growth angle (in degrees)
    let ang = 90 + (dx / 230) * 38 + (noise(sx * 0.015, sy * 0.015) - 0.5) * 22;
    let len = random(3.2, 7.5);
    if (sy >= 363 && sy <= 403 && absDx < 95) {
      // Moustache bristles: thicker, denser, angled down toward lip edge
      ang = 90 + (dx / 95) * 28;
      len = random(4.5, 8.5);
    } else if (sy > 548) {
      // Under-chin & neck bristles fan outward
      ang = 90 + (dx / 185) * 52;
      len = random(3.5, 6.5);
    }

    let x2 = sx + cos(ang) * len;
    let y2 = sy + sin(ang) * len;

    // Determine hair color: dark root/shaft, salt-and-pepper silver, or chartreuse-lit tip!
    let r = random(1);
    let isUnderJaw = sy > jawEdgeY - 26 && sy < 565;
    let isHighlightZone =
      (absDx < 75 && sy > 475 && sy < 535) ||
      (absDx > 85 && absDx < 155 && sy > 410 && sy < 495) ||
      (absDx < 85 && sy > 368 && sy < 398);

    if (r < 0.56) {
      // Coarse dark iron/espresso bristle
      brush.set("rotring", random(["#1f1410", "#2e201a", "#3b2c25"]), random(0.32, 0.55));
      brush.line(sx, sy, x2, y2);
    } else if (r < 0.78) {
      // Medium warm brown / grey-ash bristle
      brush.set("2B", random(["#59473e", "#6e6259", "#4f4640"]), random(0.35, 0.55));
      brush.line(sx, sy, x2, y2);
    } else if (isUnderJaw && r < 0.92) {
      // Whiskers catching the fluorescent yellow-green bounce from the vest!
      brush.set("pen", random(["#d9f054", "#e8f77e", "#c9d64b"]), random(0.35, 0.52));
      brush.line(sx, sy, x2, y2);
    } else if (isHighlightZone || r > 0.88) {
      // Salt-and-pepper silver-white hair glinting in overcast daylight
      brush.set("pen", random(["#e8edea", "#ffffff", "#f5e3c6"]), random(0.35, 0.55));
      brush.line(sx, sy, x2, y2);
    }
  }

  // Pore stippling on nose and cheeks
  for (let i = 0; i < 320; i++) {
    let px = random(420, 780);
    let py = random(320, 415);
    if (abs(px - 600) < 60 || py < 375) {
