  // -----------------------------------------------------------------------
  // 9. INDUSTRIAL NYLON HARD-HAT CHIN STRAP & BUCKLE
  // -----------------------------------------------------------------------
  // Descends from inside helmet temples (x=352, y=285 & x=848, y=285),
  // hugs the jawline and clips under the chin (y=535..568)
  let strapLeft = [
    [346, 280], [368, 280],
