  washPoly(strapLeft, "#1d1e1f", 245);
  washPoly(strapRight, "#191a1b", 245);
  washPoly(strapCenter, "#161718", 245);

  // Woven nylon webbing ribs along the strap
  for (let i = 0; i < 65; i++) {
