    brush.line(lx - 9, ly + 4, lx + 9, ly - 4);

    // Right strap ribs
    let rx = lerp(844, 670, t) + sin(t * 180) * 32;
    let ry = lerp(285, 565, t) + sin(t * 180) * 18;
    brush.set("rotring", i % 2 === 0 ? "#343738" : "#0b0c0d", 0.55);
    brush.line(rx - 9, ry - 4, rx + 9, ry + 4);
  }

  // Molded black plastic quick-release buckle on left-lower jaw (x=420..465, y=490..538)
  washPoly([[414, 492], [442, 480], [472, 516], [444, 532]], "#262829", 250);
  brush.set("rotring", "#5c6166", 0.7);
  brush.line(416, 493, 441, 482);
  brush.line(441, 482, 469, 515);
  brush.set("pen", "#9da5ab", 0.45);
  brush.line(426, 498, 448, 522);

  // -----------------------------------------------------------------------
  // 10. HYPERREAL SWEAT DROPLETS & RIVULETS
  // -----------------------------------------------------------------------
  let sweatDrops = [
    // Temple & cheek droplets
    [408, 356, 4.5, 6.2, 8, true, 24],
    [432, 398, 3.8, 5.0, 10, true, 18],
    [418, 434, 5.2, 7.2, 12, true, 32],
    [784, 368, 4.2, 5.8, -8, true, 22],
    [762, 415, 5.0, 6.8, -10, true, 28],
    [742, 462, 3.6, 4.8, -12, false, 0],
    // Nose & upper lip sweat beads
    [594, 344, 3.2, 3.8, 0, false, 0],
    [612, 332, 2.6, 3.2, 0, false, 0],
    [548, 344, 2.8, 3.5, 0, false, 0],
    [568, 384, 3.0, 4.2, 0, true, 12],
    [628, 390, 2.8, 3.8, 0, false, 0],
    // Chin & jaw droplets
    [556, 492, 4.6, 6.0, 4, true, 20],
    [632, 508, 5.2, 6.8, -4, true, 25],
    [586, 534, 4.2, 5.5, 0, false, 0],
    [614, 544, 4.8, 6.2, 0, true, 16],
    [488, 496, 4.4, 5.8, 15, true, 22],
    [705, 502, 4.0, 5.2, -15, false, 0],
    // Neck sweat trickles
    [518, 608, 4.8, 7.2, 6, true, 38],
    [662, 598, 4.5, 6.8, -6, true, 34],
    [578, 632, 3.8, 5.5, 2, true, 28],
    [618, 648, 4.2, 6.0, -2, true, 30],
    [462, 588, 3.6, 5.0, 8, false, 0]
