  // Major diagonal drapery folds pulling from the shoulders toward the chest/armpits
  let folds = [
    // Left side folds
    [[370, 540], [285, 690], [160, 880], "#8aa600", "#eaff47"],
    [[445, 635], [365, 795], [275, 930], "#7b9600", "#e4ff2e"],
