    // Crisp crease core line
    brush.set("cpencil", "#4f6100", 0.75);
    brush.spline([[pA[0], pA[1], 0.4], [pB[0], pB[1], 1.0], [pC[0], pC[1], 0.4]], 0.45);
  }

  // -----------------------------------------------------------------------
  // HYPERREAL POLYESTER MESH PORES & DIAGONAL TWILL TEXTURE
  // -----------------------------------------------------------------------
  // Breathable hi-vis mesh dimples across chest & shoulders
  for (let y = 528; y < 1190; y += 11) {
    let rowShift = (floor(y / 11) % 2) * 5.5;
    for (let x = 15; x < 1185; x += 11) {
      let mx = x + rowShift;
      // Check if inside vest (outside V-neck cut)
      let vNeckEdgeX = map(y, 508, 892, 208, 0, true);
      if (abs(mx - 600) < vNeckEdgeX + 18) continue;
      // Skip under shoulder slope
      let shoulderY = map(abs(mx - 600), 208, 640, 508, 622, true);
      if (y < shoulderY + 12) continue;

      // Skip areas that will be covered by the reflective stripes to save budget
      if (y > 915 && y < 1060) continue;
      if (mx > 185 && mx < 345) continue;
      if (mx > 855 && mx < 1015) continue;

      let poreCol = (mx + y) % 22 < 11 ? "#8aa600" : "#748c00";
      brush.set("rotring", poreCol, 0.55);
      brush.line(mx, y, mx + 2.2, y + 1.2);
      if (random(1) < 0.35) {
        brush.set("pen", "#f2ff80", 0.35);
        brush.line(mx + 0.5, y + 1.8, mx + 2.5, y + 2.2);
      }
    }
  }
}

// =========================================================================
// 5. SIGNAL ORANGE TRIM & RETROREFLECTIVE SILVER GLASS-BEAD TAPE
// =========================================================================

function renderReflectiveBand(x1, y1, x2, y2, x3, y3, x4, y4, isVertical) {
  // ANSI Class 3 Two-Tone Tape:
  // Outer 22% on each side = Signal Orange contrast trim
  // Inner 56% = Retroreflective Silver glass-bead tape

  // 1. Full Signal Orange Contrast Base
  washQuad([x1, y1], [x2, y2], [x3, y3], [x4, y4], "#ff4400", 252);
  markerQuad([x1, y1], [x2, y2], [x3, y3], [x4, y4], "#ff4d00", 2.0, 26, 0.8);

  // Add fold shading to the orange trim
  if (isVertical) {
    markerQuad(
      [lerp(x1, x4, 0.35), lerp(y1, y4, 0.35)],
      [lerp(x2, x3, 0.35), lerp(y2, y3, 0.35)],
      [lerp(x2, x3, 0.52), lerp(y2, y3, 0.52)],
      [lerp(x1, x4, 0.52), lerp(y1, y4, 0.52)],
      "#cc2900", 1.6, 10, 0.5
    );
    markerQuad(
      [lerp(x1, x4, 0.05), lerp(y1, y4, 0.05)],
      [lerp(x2, x3, 0.05), lerp(y2, y3, 0.05)],
      [lerp(x2, x3, 0.22), lerp(y2, y3, 0.22)],
      [lerp(x1, x4, 0.22), lerp(y1, y4, 0.22)],
      "#ff7733", 1.5, 10, 0.5
    );
  } else {
    markerQuad(
      [lerp(x1, x2, 0.3), lerp(y1, y2, 0.3)],
      [lerp(x1, x2, 0.46), lerp(y1, y2, 0.46)],
      [lerp(x4, x3, 0.46), lerp(y4, y3, 0.46)],
      [lerp(x4, x3, 0.3), lerp(y4, y3, 0.3)],
      "#d12b00", 1.6, 10, 0.5
    );
  }

  // 2. Inner Silver Glass-Bead Tape Coordinates (inset by 21% on each side)
  let s1, s2, s3, s4;
  if (isVertical) {
    s1 = [lerp(x1, x2, 0.21), lerp(y1, y2, 0.21)];
    s2 = [lerp(x1, x2, 0.79), lerp(y1, y2, 0.79)];
    s3 = [lerp(x4, x3, 0.79), lerp(y4, y3, 0.79)];
    s4 = [lerp(x4, x3, 0.21), lerp(y4, y3, 0.21)];
  } else {
    s1 = [lerp(x1, x4, 0.21), lerp(y1, y4, 0.21)];
    s2 = [lerp(x2, x3, 0.21), lerp(y2, y3, 0.21)];
    s3 = [lerp(x2, x3, 0.79), lerp(y2, y3, 0.79)];
    s4 = [lerp(x1, x4, 0.79), lerp(y1, y4, 0.79)];
  }

  // Base metallic grey-silver wash & marker passes
  washQuad(s1, s2, s3, s4, "#929a9e", 252);
  markerQuad(s1, s2, s3, s4, "#9ea6ab", 1.8, 22, 0.5);

  // Specular metallic gradient zones (dark slate-silver in folds, blinding silver-white on ridges)
  let numSegs = 40;
  for (let i = 0; i < numSegs; i++) {
    let tA = i / numSegs;
    let tB = (i + 1) / numSegs;
    let wave = sin(tA * 540 + (isVertical ? 30 : 110)) * 0.5 + 0.5;
    let bandCol;
    if (wave > 0.78) bandCol = "#e6eef2";
    else if (wave > 0.55) bandCol = "#c2cbd0";
    else if (wave > 0.3) bandCol = "#8a9296";
    else bandCol = "#676e73";

    let pA, pB, pC, pD;
    if (isVertical) {
      pA = [lerp(s1[0], s4[0], tA), lerp(s1[1], s4[1], tA)];
      pB = [lerp(s2[0], s3[0], tA), lerp(s2[1], s3[1], tA)];
      pC = [lerp(s2[0], s3[0], tB), lerp(s2[1], s3[1], tB)];
      pD = [lerp(s1[0], s4[0], tB), lerp(s1[1], s4[1], tB)];
    } else {
      pA = [lerp(s1[0], s2[0], tA), lerp(s1[1], s2[1], tA)];
      pB = [lerp(s1[0], s2[0], tB), lerp(s1[1], s2[1], tB)];
      pC = [lerp(s4[0], s3[0], tB), lerp(s4[1], s3[1], tB)];
      pD = [lerp(s4[0], s3[0], tA), lerp(s4[1], s3[1], tA)];
    }
    markerQuad(pA, pB, pC, pD, bandCol, 1.5, 4, 0);
  }

  // 3. 3M Scotchlite Prismatic Honeycomb / Diamond Grid Pattern
  let gridSteps = isVertical ? 28 : 22;
  for (let i = 0; i <= gridSteps; i++) {
    let u = i / gridSteps;
    let uNext = min(1, (i + 3.5) / gridSteps);
    let uPrev = max(0, (i - 3.5) / gridSteps);

    if (isVertical) {
      let lx1 = lerp(s1[0], s4[0], u), ly1 = lerp(s1[1], s4[1], u);
      let rx2 = lerp(s2[0], s3[0], uNext), ry2 = lerp(s2[1], s3[1], uNext);
      let rx3 = lerp(s2[0], s3[0], uPrev), ry3 = lerp(s2[1], s3[1], uPrev);
      brush.set("2H", "#5d6469", 0.5);
      brush.line(lx1, ly1, rx2, ry2);
      brush.line(lx1, ly1, rx3, ry3);
      brush.set("pen", "#dce4e8", 0.35);
      brush.line(lx1, ly1 + 1.5, rx2, ry2 + 1.5);
    } else {
      let tx1 = lerp(s1[0], s2[0], u), ty1 = lerp(s1[1], s2[1], u);
      let bx2 = lerp(s4[0], s3[0], uNext), by2 = lerp(s4[1], s3[1], uNext);
      let bx3 = lerp(s4[0], s3[0], uPrev), by3 = lerp(s4[1], s3[1], uPrev);
      brush.set("2H", "#5d6469", 0.5);
      brush.line(tx1, ty1, bx2, by2);
      brush.line(tx1, ty1, bx3, by3);
      brush.set("pen", "#dce4e8", 0.35);
      brush.line(tx1 + 1.5, ty1, bx2 + 1.5, by2);
    }
  }

  // 4. FINE SPRAYED SPARKLE & PEN DOTS (Glittering like a sign caught in headlights!)
  // A) Fine Spray sparkle clouds across the tape
  let sprayCount = isVertical ? 55 : 42;
  for (let i = 0; i < sprayCount; i++) {
    let u = random(0.04, 0.96);
    let v = random(0.08, 0.92);
    let gx = lerp(lerp(s1[0], s2[0], u), lerp(s4[0], s3[0], u), v);
    let gy = lerp(lerp(s1[1], s2[1], u), lerp(s4[1], s3[1], u), v);

    let wave = sin((isVertical ? v : u) * 540 + (isVertical ? 30 : 110)) * 0.5 + 0.5;
    let spCol = wave > 0.55 ? "#ffffff" : random(["#e3edf2", "#f5ffbd", "#d0dce3"]);
    let spWeight = wave > 0.65 ? random(0.9, 1.6) : random(0.5, 1.0);
    brush.set("spray", spCol, spWeight);
    brush.line(gx - 8, gy - 4, gx + 8, gy + 4);
  }

  // B) Hundreds of crisp Pen & Rotring glass-bead micro-dots and star glints
  let dotCount = isVertical ? 480 : 380;
  for (let i = 0; i < dotCount; i++) {
    let u = random(0.02, 0.98);
    let v = random(0.02, 0.98);
    let gx = lerp(lerp(s1[0], s2[0], u), lerp(s4[0], s3[0], u), v);
    let gy = lerp(lerp(s1[1], s2[1], u), lerp(s4[1], s3[1], u), v);

    let wave = sin((isVertical ? v : u) * 540 + (isVertical ? 30 : 110)) * 0.5 + 0.5;

    if (wave > 0.62 || random(1) < 0.35) {
      // Bright headlight retroreflective bead glint
      let glintCol = random(["#ffffff", "#ffffff", "#f5ffd6", "#e6f7ff"]);
      brush.set("pen", glintCol, random(0.45, 0.85));
      brush.line(gx, gy, gx + random(0.8, 2.2), gy + random(-0.5, 0.5));

      // Micro star-burst on the brightest glass beads
      if (wave > 0.78 && random(1) < 0.16) {
        let r = random(3.5, 7.5);
        brush.set("rotring", "#ffffff", 0.55);
        brush.line(gx - r, gy, gx + r, gy);
        brush.line(gx, gy - r, gx, gy + r);
        brush.set("pen", "#f2ff80", 0.4);
        brush.line(gx - r * 0.5, gy - r * 0.5, gx + r * 0.5, gy + r * 0.5);
      }
    } else {
      // Darker glass bead shadow grain for hyperreal gritty micro-texture
      brush.set("rotring", random(["#4d5459", "#697175", "#adb6bd"]), random(0.35, 0.6));
      brush.line(gx, gy, gx + 1.2, gy + 0.8);
    }
  }

  // 5. Industrial Stitch Seams along both Signal Orange & Silver edges
  drawStitchLine(x1, y1, x4, y4, "#ff9966", "#801b00", 12);
  drawStitchLine(x2, y2, x3, y3, "#ff9966", "#801b00", 12);
  drawStitchLine(s1[0], s1[1], s4[0], s4[1], "#eef5f7", "#4f5659", 10);
  drawStitchLine(s2[0], s2[1], s3[0], s3[1], "#eef5f7", "#4f5659", 10);
}

function drawVestTrimAndTape() {
  // 1. Horizontal Retroreflective Band across the lower chest (y = 925..1062)
  // Left horizontal band (x = -20 to 580)
  renderReflectiveBand(-20, 922, 582, 932, 582, 1068, -20, 1058, false);
  // Right horizontal band (x = 618 to 1220)
  renderReflectiveBand(618, 932, 1220, 922, 1220, 1058, 618, 1068, false);

  // 2. Left Vertical Shoulder-to-Waist Retroreflective Band
  renderReflectiveBand(195, 538, 338, 518, 318, 1200, 172, 1200, true);

  // 3. Right Vertical Shoulder-to-Waist Retroreflective Band
  renderReflectiveBand(862, 518, 1005, 538, 1028, 1200, 882, 1200, true);

  // -----------------------------------------------------------------------
  // 4. SIGNAL ORANGE V-NECK COLLAR BINDING & CENTRAL ZIPPER
  // -----------------------------------------------------------------------
  // Left V-neck Signal Orange binding (from x=385, y=506 down to x=592, y=892)
  let leftCollar = [
    [380, 512], [404, 504],
    [600, 888], [580, 896]
  ];
  let rightCollar = [
    [796, 504], [820, 512],
    [620, 896], [600, 888]
  ];
  washPoly(leftCollar, "#ff4400", 252);
  washPoly(rightCollar, "#ff3b00", 252);
  markerQuad(leftCollar[0], leftCollar[1], leftCollar[2], leftCollar[3], "#ff5100", 1.5, 10, 0.5);
  markerQuad(rightCollar[0], rightCollar[1], rightCollar[2], rightCollar[3], "#e63600", 1.5, 10, 0.5);

  drawStitchLine(385, 510, 584, 892, "#ffaa80", "#7a1c00", 11);
  drawStitchLine(400, 506, 596, 888, "#ffaa80", "#7a1c00", 11);
  drawStitchLine(800, 506, 604, 888, "#ffaa80", "#7a1c00", 11);
  drawStitchLine(815, 510, 616, 892, "#ffaa80", "#7a1c00", 11);

  // Central Heavy-Duty Black/Asphalt Zipper (x = 582..618, y = 886..1200)
  washQuad([580, 886], [620, 886], [620, 1200], [580, 1200], "#1c1d1e", 252);
  markerQuad([582, 888], [618, 888], [618, 1200], [582, 1200], "#262829", 1.5, 12, 0.5);

  // Molded zipper teeth
  for (let zy = 894; zy < 1200; zy += 7.5) {
    brush.set("rotring", "#0d0e0f", 0.7);
    brush.line(592, zy, 608, zy);
    brush.set("pen", "#8c9499", 0.55);
    brush.line(594, zy + 2.5, 599, zy + 2.5);
    brush.line(601, zy + 5.0, 606, zy + 5.0);
  }

  // Heavy metal zipper pull tab at top of zipper (y = 892..942)
  washPoly([[588, 892], [612, 892], [615, 938], [585, 938]], "#383b3d", 250);
  brush.set("rotring", "#111213", 0.8);
  brush.rect(600, 915, 24, 42, "center");
  brush.set("pen", "#d9e2e8", 0.6);
  brush.line(591, 895, 609, 895);
  brush.line(590, 934, 610, 934);

  // -----------------------------------------------------------------------
  // 5. BLACK WEBBING MIC-LOOP / RADIO TAB & SCUFFED FABRIC / ROAD GRIME
  // -----------------------------------------------------------------------
  // Radio mic loop on left chest (x = 362..435, y = 695..728)
  washQuad([362, 695], [438, 704], [435, 732], [359, 723], "#1e2021", 250);
  for (let rx = 365; rx < 435; rx += 4) {
    brush.set("rotring", rx % 8 === 0 ? "#3d4142" : "#111213", 0.6);
    brush.line(rx, 696 + (rx - 362) * 0.12, rx - 2, 722 + (rx - 362) * 0.12);
  }
  // Box-X industrial reinforcement stitch on the mic loop
  brush.set("rotring", "#575c5e", 0.5);
  brush.line(365, 698, 385, 722);
  brush.line(385, 700, 365, 720);

  // Scuffed fabric: asphalt tar splatters, grease smudges, and frayed threads
  let grimeSpots = [
    [255, 815, 38, 18], [312, 1085, 45, 22], [485, 845, 32, 16],
    [545, 975, 28, 20], [665, 985, 36, 18], [895, 765, 42, 24],
    [945, 1110, 52, 26], [140, 995, 40, 20], [740, 865, 30, 15],
    [225, 645, 34, 14], [960, 660, 35, 16], [510, 1120, 44, 22]
  ];
  for (let g of grimeSpots) {
    brush.set("charcoal", "#333629", random(0.8, 1.4));
    brush.line(g[0] - g[2] * 0.5, g[1], g[0] + g[2] * 0.5, g[1] + random(-8, 8));
    brush.set("spray", "#24261e", random(0.6, 1.1));
    brush.line(g[0] - 10, g[1] - 5, g[0] + 10, g[1] + 5);
    // Tiny tar flecks around smudge
    for (let k = 0; k < 14; k++) {
      let tx = g[0] + random(-g[2], g[2]);
      let ty = g[1] + random(-g[3], g[3]);
      brush.set("rotring", random(["#181a16", "#2b2e24", "#45473b"]), random(0.35, 0.7));
      brush.line(tx, ty, tx + random(1, 4), ty + random(-2, 2));
    }
  }

  // Frayed nylon threads along V-neck and tape edges
  for (let i = 0; i < 45; i++) {
    let t = random(0.1, 0.95);
    let isLeft = random(1) < 0.5;
    let fx = isLeft ? lerp(390, 585, t) : lerp(810, 615, t);
    let fy = lerp(510, 890, t);
    brush.set("pen", random(["#ff7733", "#e6ff4d", "#d9e0e3"]), 0.35);
    brush.spline([
      [fx, fy, 0.8],
      [fx + random(-10, 10), fy + random(4, 12), 0.6],
      [fx + random(-16, 16), fy + random(8, 18), 0.2]
    ], 0.5);
  }
}

// =========================================================================
// 6. SIGNAL ORANGE HARD HAT (DOMINATING UPPER FRAME)
// =========================================================================

function drawSignalOrangeHardHat() {
  // 1. Dark Underside of the Jutting Front Brim (y = 250..324)
  // Frames the top of the nose and cheeks in deep crimson-umber shadow
  let underBrim = [
    [206, 298], [350, 268], [600, 254], [850, 268], [994, 298],
    [965, 322], [835, 308], [600, 302], [365, 308], [235, 322]
  ];
  washPoly(underBrim, "#380d03", 252);

  // Molded structural ribs & warm orange bounce glow under the visor
  for (let i = 0; i <= 60; i++) {
    let t = i / 60;
    let ux1 = lerp(218, 982, t);
    let uy1 = 296 - sin(t * 180) * 40;
    let ux2 = lerp(245, 955, t);
    let uy2 = 318 - sin(t * 180) * 16;
    let uCol = abs(t - 0.5) < 0.28 ? "#691b06" : "#290902";
    brush.set("marker", uCol, 1.4);
    brush.line(ux1, uy1, ux2, uy2);
  }

  // Internal black suspension headband peeking out at left/right under-brim temples
  washPoly([[265, 308], [365, 298], [362, 315], [272, 320]], "#161718", 250);
  washPoly([[835, 298], [935, 308], [928, 320], [838, 315]], "#161718", 250);

  // -----------------------------------------------------------------------
  // 2. MAIN DOME OF THE SIGNAL ORANGE HARD HAT (y = 24..255, x = 245..955)
  // -----------------------------------------------------------------------
  let domePts = [];
  for (let i = 0; i <= 40; i++) {
    let t = i / 40;
    let ang = lerp(180, 0, t);
    let rx = 352;
    let ry = 205;
    let x = 600 + cos(ang) * rx;
    // Slightly squared-off top crown for authentic industrial hard-hat profile
    let y = 242 - pow(sin(ang), 0.82) * ry;
    domePts.push([x, y]);
  }
  domePts.push([956, 255], [600, 235], [244, 255]);
  washPoly(domePts, "#ff3b00", 254);

  // Dense Signal Orange Marker Modeling across the curved helmet shell
  for (let i = 0; i < 68; i++) {
    let t = i / 68;
    let yLeft = lerp(58, 245, t);
    let yMid = lerp(34, 212, t);
    let yRight = lerp(58, 245, t);
    let halfW = map( sqrt(max(0.02, t)), 0, 1, 145, 354 );

    // Lighting across the dome: overcast daylight from top-left-center
    let col;
    if (t < 0.22) col = "#ff7b33";
    else if (t < 0.48) col = "#ff5500";
    else if (t < 0.78) col = "#f23800";
    else col = "#cc2400";

    brush.set("marker", col, 2.4);
    brush.spline([
      [600 - halfW, yLeft, 0.7],
      [600 - halfW * 0.45, lerp(yLeft, yMid, 0.72), 1.0],
      [600, yMid, 1.0],
      [600 + halfW * 0.45, lerp(yRight, yMid, 0.72), 1.0],
      [600 + halfW, yRight, 0.7]
    ], 0.45);
  }

  // Deep side shadow on right and left flanks of dome
  for (let i = 0; i < 28; i++) {
    let t = i / 28;
    let rx = lerp(810, 948, t);
    let ryTop = lerp(65, 195, t);
    brush.set("marker", "#b81d00", 2.0);
    brush.line(rx, ryTop, rx + 8, 245);

    let lx = lerp(390, 252, t);
    let lyTop = lerp(65, 195, t);
    brush.set("marker", "#d42800", 1.8);
    brush.line(lx, lyTop, lx - 8, 245);
  }

  // -----------------------------------------------------------------------
  // 3. CENTRAL REINFORCEMENT RIB & SECONDARY CROWN RIDGES
  // -----------------------------------------------------------------------
  // Raised central crest (x = 556..644, y = 26..212)
  let ribPoly = [
    [562, 32], [600, 24], [638, 32],
    [648, 212], [600, 206], [552, 212]
  ];
  washPoly(ribPoly, "#ff6214", 240);

  // Left highlight face & right shadow wall of the central rib
  markerQuad([562, 32], [602, 25], [602, 206], [552, 212], "#ff8542", 1.6, 18, 0.5);
  markerQuad([602, 25], [638, 32], [648, 212], [602, 206], "#d12600", 1.6, 18, 0.5);
  // Dark groove flanking the central rib
  brush.set("2B", "#8f1500", 1.1);
  brush.line(550, 38, 548, 212);
  brush.line(650, 38, 652, 212);

  // Secondary flanking ribs on helmet shell
  brush.set("marker", "#ff8847", 1.5);
  brush.spline([[445, 62, 0.5], [422, 135, 1], [412, 218, 0.7]], 0.4);
  brush.set("2B", "#9e1900", 0.9);
  brush.spline([[436, 65, 0.5], [413, 135, 1], [403, 218, 0.7]], 0.4);

  brush.set("marker", "#b01c00", 1.5);
  brush.spline([[755, 62, 0.5], [778, 135, 1], [788, 218, 0.7]], 0.4);
  brush.set("cpencil", "#ff8c4d", 0.9);
  brush.spline([[747, 65, 0.5], [770, 135, 1], [780, 218, 0.7]], 0.4);

  // Broad Overcast Sky Specular Sheen on the upper helmet dome
  for (let i = 0; i < 24; i++) {
    let t = i / 24;
    let hy = lerp(46, 118, t);
    let w = sin(t * 180) * 145;
    brush.set("cpencil", t > 0.3 && t < 0.7 ? "#ffd1b3" : "#ff9c66", 1.1);
    brush.spline([
      [540 - w, hy + 18, 0.4],
      [560, hy, 1.0],
      [635 + w * 0.6, hy + 12, 0.4]
    ], 0.45);
  }

  // -----------------------------------------------------------------------
  // 4. RETROREFLECTIVE SILVER & SAFETY-YELLOW FOREHEAD WARNING STRIPE
  // -----------------------------------------------------------------------
  // Curved reflective decal band across the front of the hard hat (y = 138..192)
  let railTop = [], railMid1 = [], railMid2 = [], railBot = [];
  for (let i = 0; i <= 24; i++) {
    let t = i / 24;
    let x = lerp(295, 905, t);
    let curve = sin(t * 180) * 26;
    railTop.push([x, 168 - curve]);
    railMid1.push([x, 178 - curve]);
    railMid2.push([x, 204 - curve]);
    railBot.push([x, 214 - curve]);
  }

  // Top & Bottom fluorescent safety-yellow pin-stripes on helmet decal
  markerRibbon(railTop, railMid1, "#d9ff00", 1.4, 5);
  markerRibbon(railMid2, railBot, "#c8ed00", 1.4, 5);
  // Center retroreflective silver band on helmet
