    brush.spline([
      headPt(ex - side * 26, ey - 4),
      headPt(ex, ey - 14),
      headPt(ex + side * 27, ey - 2)
    ], 0.5);

    // Exhausted lower eyelid bags & tear trough creases
    for (let bag = 1; bag <= 3; bag++) {
      let offY = bag * 5.5;
      brush.set(bag === 1 ? "rotring" : "HB", bag === 1 ? PALETTE.skinDarkUmber : PALETTE.skinUmber, 0.55 - bag * 0.1);
      brush.spline([
