}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.creamWarm);

  // 1. Paper Tooth & Warm Cream Ground
  drawPaperGrain();

  // 2. Dusky Early-Morning Kitchen Wall & Backsplash
  drawWallAndBacksplash();

  // 3. Generous Sweep of Speckled Laminate Countertop & Morning Cast Shadows
  drawCountertopBase();
  drawSpeckledLaminate();

  // 4. Braided Mid-Century Power Cord at Left Rear
  drawPowerCord();

  // 5. Toaster Shadow Anchor & Bakelite Base Plinth
  drawToasterBase();

  // 6. Chrome Body with Warped Stylised Kitchen Window Reflection
  drawChromeBodyAndReflections();

  // 7. Top Crown Toast Slots & Two Slices Popped Halfway Up
  drawTopSlotsAndToast();

  // 8. Front Control End-Panel: Bakelite Crest, Dial, and Half-Up Carriage Lever
  drawFrontControls();

  // 9. Every Crumb on the Speckled Laminate Described Individually
  drawIndividualCrumbs();

  noLoop();
}

