function drawSpeckledLaminate() {
  // Mid-century speckled laminate (Formica confetti/boomerang flecks embedded flat in the surface)
  // Rendered in perspective across the counter plane so flecks foreshorten naturally with depth
  const speckleColors = [
    PAL.mustardMid,
    PAL.mustardLight,
    PAL.avocadoMid,
    PAL.tealMid,
    PAL.tomatoMid,
    PAL.creamBright,
    PAL.avocadoDeep
  ];

  for (let i = 0; i < 1350; i++) {
    // Sample in screen space below the counter horizon
    const sx = random(8, 1192);
    const horizonY = lerp(588, 416, sx / 1200);
    const sy = random(horizonY + 6, 1194);

    // Skip interior of the toaster footprint
    if (sx > 52 && sx < 555 && sy > 510 && sy < 915) {
      if (sx < 395 && sy < 910 && sy > 480) continue;
    }

    // Perspective scale factor based on vertical distance from horizon
    const depthFactor = map(sy, 420, 1200, 0.42, 1.35, true);
    const col = random(speckleColors);
    const w = random(0.45, 0.95) * depthFactor;

    brush.set("crumb_crayon", col, w);
    const len = random(1.8, 5.2) * depthFactor;
    const ang = random(-35, 35);
    const dx = cos(ang) * len;
    const dy = sin(ang) * len * 0.48; // foreshortened vertically
    brush.line(sx, sy, sx + dx, sy + dy);

    // Occasional tiny mid-century boomerang/terrazzo chevron fleck
    if (i % 11 === 0) {
      const ang2 = ang + random(45, 85);
      brush.line(sx, sy, sx + cos(ang2) * len * 0.8, sy + sin(ang2) * len * 0.4);
    }
  }
}

