// ============================================================================
// 6. CHROME BODY & WARPED STYLISED KITCHEN WINDOW REFLECTION
// ============================================================================
// Determines the exact color & secondary hatch of the warped reflection at (uFrac, p)
function getChromeReflectionStyle(uFrac, p) {
  // Longitudinal curvature warps the reflection bands downward near the front and back corners
  const endCurve = Math.pow(Math.abs(uFrac - 0.5) * 2, 2.2) * 0.095;
  const pW = p + endCurve;

  // Vertical window mullions warp as they climb the curved chrome flank
  const mullionShift = (p + 0.65) * 0.14 * (uFrac - 0.5);
  const uW = uFrac + mullionShift;
  const nearMullion =
    Math.abs(uW - 0.14) < 0.032 ||
    Math.abs(uW - 0.43) < 0.028 ||
    Math.abs(uW - 0.72) < 0.028 ||
    Math.abs(uW - 0.91) < 0.032;

  // 1. Bottom rim reflecting bakelite & dark counter crevice
  if (pW < -0.91) {
    return {
      wash: PAL.tealNight,
      washOp: 215,
      hatch: PAL.tomatoDark,
      hatch2: PAL.tealDeep,
      weight: 0.85
    };
  }
  // 2. Lower belly reflecting the sunlit speckled laminate counter
  if (pW < -0.80) {
    return {
      wash: PAL.mustardMid,
      washOp: 165,
      hatch: PAL.creamWarm,
      hatch2: PAL.tomatoMid,
      weight: 0.85
    };
  }
  // 3. Reflection of dark teal kitchen wall below the window sill
  if (pW < -0.71) {
    return {
      wash: PAL.tealDeep,
      washOp: 195,
      hatch: PAL.avocadoDeep,
      hatch2: PAL.tealNight,
      weight: 0.9
    };
  }
  // 4. Warped Window Sill Band (Tomato Red & Mustard)
  if (pW < -0.66) {
    return {
      wash: PAL.tomatoMid,
      washOp: 185,
      hatch: PAL.mustardLight,
      hatch2: PAL.tomatoDeep,
      weight: 0.85
    };
  }
  // 5. Lower Window Pane Row: Stylised Avocado Morning Foliage & Mustard Horizon
  if (pW < -0.52) {
    if (nearMullion) {
      return {
        wash: PAL.tealDeep,
        washOp: 190,
        hatch: PAL.tealMid,
        hatch2: PAL.avocadoDark,
        weight: 0.85
      };
    }
    if (pW < -0.59) {
      // Stylised avocado foliage band in lower window
      return {
        wash: PAL.avocadoMid,
        washOp: 175,
        hatch: PAL.avocadoLight,
        hatch2: PAL.mustardMid,
        weight: 0.85
      };
    } else {
      // Golden mustard early-morning sky band
      return {
        wash: PAL.mustardLight,
        washOp: 175,
        hatch: PAL.mustardBright,
        hatch2: PAL.creamWarm,
        weight: 0.85
      };
    }
  }
  // 6. Horizontal Window Sash Bar (Dusty Teal)
  if (pW < -0.47) {
    return {
      wash: PAL.tealMid,
      washOp: 185,
      hatch: PAL.tealDeep,
      hatch2: PAL.creamMid,
      weight: 0.85
    };
  }
  // 7. Upper Window Pane Row: Luminous Warm Cream Sky & Tomato Red Curtain Valance
  if (pW < -0.34) {
    if (nearMullion) {
      return {
        wash: PAL.tealMid,
        washOp: 175,
        hatch: PAL.tealDeep,
        hatch2: PAL.mustardMid,
        weight: 0.8
      };
    }
    // Scalloped wave of the mid-century tomato-red café curtain valance
    const scallop = Math.sin(uW * 360 * 3.5) * 0.018;
    if (pW > -0.39 + scallop) {
      return {
        wash: PAL.tomatoBright,
        washOp: 185,
        hatch: PAL.tomatoMid,
        hatch2: PAL.mustardLight,
        weight: 0.85
      };
    }
    return {
      wash: PAL.creamBright,
      washOp: 195,
      hatch: PAL.mustardBright,
      hatch2: PAL.creamWarm,
      weight: 0.9
    };
  }
  // 8. Tight Shoulder Turn: Razor-bright Cream Specular Band & Deep Teal Ceiling Contrast
  if (pW < -0.28) {
    return {
      wash: PAL.creamBright,
      washOp: 220,
      hatch: PAL.creamBright,
      hatch2: PAL.mustardBright,
      weight: 0.95
    };
  }
  if (pW < -0.19) {
    return {
      wash: PAL.tealDeep,
      washOp: 205,
      hatch: PAL.tealNight,
      hatch2: PAL.tealMid,
      weight: 0.9
    };
  }
  // 9. Top Crown Deck (reflecting dusky ceiling + warm glow near toast slots)
  if (p < 0.25) {
    const nearSlots = Math.abs(p) < 0.22 && uFrac > 0.14 && uFrac < 0.86;
    if (nearSlots) {
      return {
        wash: PAL.mustardMid,
        washOp: 165,
        hatch: PAL.tomatoBright,
        hatch2: PAL.creamWarm,
        weight: 0.85
      };
    }
    return {
      wash: PAL.tealLight,
      washOp: 165,
      hatch: PAL.creamWarm,
      hatch2: PAL.tealMid,
      weight: 0.8
    };
  }
  // 10. Far-right shoulder turn
  return {
    wash: PAL.avocadoMid,
    washOp: 175,
    hatch: PAL.tealDeep,
    hatch2: PAL.mustardMid,
    weight: 0.85
  };
}

function drawChromeBodyAndReflections() {
  // Rear bakelite handle nub peeking out at back-left end (uFrac = 1)
  const rearHandlePts = [
    proj(TOASTER_L + 2, TOASTER_W * 0.36, 175),
    proj(TOASTER_L + 26, TOASTER_W * 0.42, 185),
    proj(TOASTER_L + 24, TOASTER_W * 0.42, 235),
    proj(TOASTER_L - 2, TOASTER_W * 0.38, 255)
  ];
  drawPoly(rearHandlePts, {
    wash: PAL.tealNight,
    washOpacity: 230,
    hatchBrush: "fine_crayon",
    hatchColor: PAL.tomatoDark,
    hatchWeight: 0.9,
    hatchDist: 4,
    hatchAngle: 20,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.mustardMid,
    strokeWeight: 0.8
  });

  // A. Render the Main Curved Chrome Shell (uFrac from 0 to 1, p from -1.0 to +0.34)
  const uSteps = 18;
  const pValues = [
    -1.0, -0.91, -0.80, -0.71, -0.66, -0.59, -0.52, -0.47,
    -0.39, -0.34, -0.28, -0.19, -0.08, 0.08, 0.22, 0.34
  ];

  for (let ip = 0; ip < pValues.length - 1; ip++) {
    const p0 = pValues[ip];
    const p1 = pValues[ip + 1];
    const pMid = 0.5 * (p0 + p1);

    for (let iu = 0; iu < uSteps; iu++) {
      const u0 = iu / uSteps;
      const u1 = (iu + 1) / uSteps;
      const uMid = 0.5 * (u0 + u1);

      const quad = [
        toasterShellPt(u0, p0),
        toasterShellPt(u1, p0),
        toasterShellPt(u1, p1),
        toasterShellPt(u0, p1)
      ];

      const st = getChromeReflectionStyle(uMid, pMid);
      drawPoly(quad, {
        wash: st.wash,
        washOpacity: st.washOp,
        fill: st.wash,
        fillOpacity: 65,
        bleed: 0.12,
        texture: 0.78,
        hatchBrush: "dry_crayon",
        hatchColor: st.hatch,
        hatchWeight: st.weight,
        hatchDist: 6,
        hatchAngle: 21,
        hatch2Brush: "fine_crayon",
        hatch2Color: st.hatch2,
        hatch2Weight: st.weight * 0.72,
        hatch2Dist: 9,
        hatch2Angle: -68
      });
    }
  }

  // B. Render the Front Control Chrome End-Cap (uFrac = 0, wrapping across p in [-1, +1])
  // We divide the front end-panel vertically by height zNorm and horizontally across width s
  const zBands = [
    { z0: 0.00, z1: 0.12, wash: PAL.tealNight, hatch: PAL.tomatoDark, hatch2: PAL.tealDeep },
    { z0: 0.12, z1: 0.28, wash: PAL.mustardMid, hatch: PAL.creamWarm, hatch2: PAL.avocadoMid },
    { z0: 0.28, z1: 0.42, wash: PAL.tealDeep, hatch: PAL.tealMid, hatch2: PAL.avocadoDark },
    { z0: 0.42, z1: 0.50, wash: PAL.tomatoMid, hatch: PAL.mustardLight, hatch2: PAL.tomatoDeep },
    { z0: 0.50, z1: 0.67, wash: PAL.avocadoMid, hatch: PAL.mustardLight, hatch2: PAL.tealMid },
    { z0: 0.67, z1: 0.84, wash: PAL.mustardLight, hatch: PAL.creamBright, hatch2: PAL.mustardMid },
    { z0: 0.84, z1: 0.93, wash: PAL.creamBright, hatch: PAL.creamBright, hatch2: PAL.mustardBright },
    { z0: 0.93, z1: 1.00, wash: PAL.tealMid, hatch: PAL.creamWarm, hatch2: PAL.tealDeep }
  ];

  function frontCapPt(sFrac, zNorm) {
    // Profile width narrows along the upper shoulder
    let halfW = 1.0;
    if (zNorm > 0.70) {
      const t = (zNorm - 0.70) / 0.30;
      halfW = Math.cos(t * Math.PI * 0.48) * 0.96 + 0.04;
    } else {
      halfW = 1.0 + 0.04 * Math.sin((zNorm / 0.70) * Math.PI);
    }
    const s = sFrac * halfW;
    const v = (0.5 + 0.5 * s) * TOASTER_W;
    const z = 48 + zNorm * (TOASTER_H - 48);
    const uBulge = -19 * Math.sin(Math.PI * zNorm * 0.9) * Math.cos(s * Math.PI * 0.42);
    return proj(uBulge, v, z);
  }

  const sSlices = 10;
  for (const b of zBands) {
    for (let is = 0; is < sSlices; is++) {
      const s0 = -1 + (2 * is) / sSlices;
      const s1 = -1 + (2 * (is + 1)) / sSlices;
      const sMid = 0.5 * (s0 + s1);
      const quad = [
        frontCapPt(s0, b.z0),
        frontCapPt(s1, b.z0),
        frontCapPt(s1, b.z1),
        frontCapPt(s0, b.z1)
      ];
      // Right side of front cap falls into slightly deeper dusky teal shade
      const isRightSide = sMid > 0.25;
      drawPoly(quad, {
        wash: isRightSide ? PAL.tealDeep : b.wash,
        washOpacity: 185,
        fill: b.wash,
        fillOpacity: 75,
        bleed: 0.1,
        hatchBrush: "dry_crayon",
        hatchColor: b.hatch,
        hatchWeight: 0.85,
        hatchDist: 6,
        hatchAngle: -22,
        hatch2Brush: "fine_crayon",
        hatch2Color: b.hatch2,
        hatch2Weight: 0.65,
        hatch2Dist: 9,
        hatch2Angle: 68
      });
    }
  }

  // C. Sweeping Soft-Band Crayon Overlays to Emphasize the Warped Window Reflection
  // Long continuous crayon splines following the toaster's curved flank
  const splinePBands = [
    { p: -0.84, col: PAL.creamWarm, w: 1.4 },
    { p: -0.68, col: PAL.tomatoBright, w: 1.8 },
    { p: -0.56, col: PAL.mustardBright, w: 1.7 },
    { p: -0.42, col: PAL.creamBright, w: 2.2 },
    { p: -0.37, col: PAL.tomatoBright, w: 1.6 },
    { p: -0.31, col: PAL.creamBright, w: 2.6 },
    { p: -0.24, col: PAL.tealNight, w: 1.9 }
  ];

  for (const sb of splinePBands) {
    const pts = [];
    for (let iu = 0; iu <= 14; iu++) {
      const uF = iu / 14;
      const endCurve = Math.pow(Math.abs(uF - 0.5) * 2, 2.2) * 0.085;
      const pt = toasterShellPt(uF, sb.p - endCurve);
      pts.push([pt[0], pt[1], 0.85 + 0.3 * Math.sin((iu / 14) * Math.PI)]);
    }
    brush.set("dry_crayon", sb.col, sb.w);
    brush.spline(pts, 0.5);
  }

  // Warped Vertical Window Mullions bending over the chrome shoulder
  const mullionUs = [0.15, 0.43, 0.72, 0.90];
  for (const mu of mullionUs) {
    const mPts = [];
    const hlPts = [];
    for (let ip = 0; ip <= 10; ip++) {
      const pVal = lerp(-0.74, -0.30, ip / 10);
      const uShift = mu - (pVal + 0.65) * 0.14 * (mu - 0.5);
      const pt = toasterShellPt(constrain(uShift, 0.03, 0.97), pVal);
      mPts.push([pt[0], pt[1], 1.0]);
      hlPts.push([pt[0] + 4, pt[1] + 2, 0.8]);
    }
    brush.set("dry_crayon", PAL.tealDeep, 1.5);
    brush.spline(mPts, 0.55);
    brush.set("fine_crayon", PAL.creamBright, 1.0);
    brush.spline(hlPts, 0.55);
  }

  // Brilliant specular ridge along the front-left rounded vertical corner (uFrac = 0.02)
  const cornerHl = [];
  for (let ip = 0; ip <= 12; ip++) {
    const pVal = lerp(-0.92, -0.15, ip / 12);
    const pt = toasterShellPt(0.025, pVal);
    cornerHl.push([pt[0], pt[1], 1.1]);
  }
  brush.set("dry_crayon", PAL.creamBright, 1.9);
  brush.spline(cornerHl, 0.5);
  brush.set("fine_crayon", PAL.mustardBright, 1.1);
  brush.spline(cornerHl.map(pt => [pt[0] - 3, pt[1], pt[2]]), 0.5);

  // Crisp exterior silhouette contour lines of the chrome shell
  const leftContour = [];
  for (let ip = 0; ip <= 12; ip++) {
    const pt = toasterShellPt(0.99, lerp(-0.98, 0.0, ip / 12));
    leftContour.push([pt[0], pt[1], 1.0]);
  }
  brush.set("fine_crayon", PAL.tealNight, 1.15);
  brush.spline(leftContour, 0.5);

  const rightContour = [];
  for (let iz = 0; iz <= 12; iz++) {
    const pt = frontCapPt(1.0, iz / 12);
    rightContour.push([pt[0], pt[1], 1.0]);
  }
  brush.set("fine_crayon", PAL.tealNight, 1.2);
  brush.spline(rightContour, 0.5);
}

// ============================================================================
// 7. TOP SLOTS & TWO SLICES OF TOAST POPPED HALFWAY UP
// ============================================================================
function drawTopSlotsAndToast() {
  // Two slots on top deck:
  // Back/Right slot (further from viewer): p in [0.04, 0.21]
  // Front/Left slot (closer to viewer): p in [-0.21, -0.04]
  // Draw back slot & back toast first, then front slot & front toast (Painter's order)
  drawSingleSlotAndToast(0.045, 0.215, 1);  // Far slot + slice
  drawSingleSlotAndToast(-0.215, -0.045, 0); // Near slot + slice
}

function drawSingleSlotAndToast(pMin, pMax, index) {
  const uStart = 0.13;
  const uEnd = 0.87;

  // 1. Rolled Chrome Slot Bezel Rim
  const bezelOuter = [
    toasterShellPt(uStart - 0.02, pMin - 0.025, 2),
    toasterShellPt(uEnd + 0.02, pMin - 0.025, 2),
    toasterShellPt(uEnd + 0.02, pMax + 0.025, 2),
    toasterShellPt(uStart - 0.02, pMax + 0.025, 2)
  ];
  drawPoly(bezelOuter, {
    wash: PAL.creamBright,
    washOpacity: 210,
    hatchBrush: "fine_crayon",
    hatchColor: PAL.mustardLight,
    hatchWeight: 0.85,
    hatchDist: 4,
    hatchAngle: 20,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.tealDeep,
    strokeWeight: 0.9
  });

  // 2. Dark Slot Interior with Residual Red-Orange Nichrome Heating Element Glow
  const slotInner = [
    toasterShellPt(uStart, pMin, 0),
    toasterShellPt(uEnd, pMin, 0),
    toasterShellPt(uEnd, pMax, 0),
    toasterShellPt(uStart, pMax, 0)
  ];
  drawPoly(slotInner, {
    wash: PAL.tomatoDark,
    washOpacity: 240,
    fill: PAL.tomatoBright,
    fillOpacity: 130,
    bleed: 0.06,
    hatchBrush: "fine_crayon",
    hatchColor: PAL.tomatoMid,
    hatchWeight: 1.0,
    hatchDist: 4,
    hatchAngle: 20,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.tealNight,
    strokeWeight: 1.1
  });

  // Glowing mustard/tomato nichrome wire glint at the ends of the slot
  const glowA0 = toasterShellPt(uStart + 0.01, (pMin + pMax) * 0.5, 0);
  const glowA1 = toasterShellPt(uStart + 0.06, (pMin + pMax) * 0.5, 0);
  brush.set("fine_crayon", PAL.mustardBright, 1.3);
  brush.line(glowA0[0], glowA0[1], glowA1[0], glowA1[1]);

  // 3. Toast Slice Popped Halfway Up!
  // Slice spans uFrac in [0.17, 0.83], thickness across v from vFront to vBack
  const uToast0 = 0.175 + index * 0.01;
  const uToast1 = 0.825 + index * 0.01;
  const u0 = uToast0 * TOASTER_L;
  const u1 = uToast1 * TOASTER_L;

  const pMid = 0.5 * (pMin + pMax);
  const vCenter = (0.5 + 0.5 * (pMid / 0.32) * 0.66) * TOASTER_W;
  const sliceThick = 28; // thick slice of mid-century sandwich bread
  const vFront = vCenter - sliceThick * 0.5;
  const vBack = vCenter + sliceThick * 0.5;

  const zSlot = TOASTER_H - 6;
  const zShoulder = zSlot + 74; // side crust indentation where top loaf crown begins
  const zPeak = zSlot + 118 + (index === 0 ? 4 : -2); // popped halfway up!

  // Helper to compute point on the slice profile
  // side = 0 (front-left face at vFront) or 1 (back-right face at vBack)
  function sliceTopArchPts(vPlane, steps = 16) {
    const pts = [];
    for (let i = 0; i <= steps; i++) {
      const t = i / steps; // 0 = front end (u0), 1 = back end (u1)
      const u = lerp(u0, u1, t);
      // Classic pullman/country loaf top crown with slight center dip or double swell
      const arch = Math.sin(t * Math.PI);
      const doubleSwell = Math.sin(t * 2 * Math.PI) * 0.06 + Math.pow(Math.sin(t * Math.PI), 0.65);
      const z = zShoulder + (zPeak - zShoulder) * doubleSwell;
      pts.push(proj(u, vPlane, z));
    }
    return pts;
  }

  const frontArch = sliceTopArchPts(vFront, 16);
  const backArch = sliceTopArchPts(vBack, 16);

  // A. Top & Right Crust Arch Band (between frontArch and backArch, plus right vertical crust edge)
  const crustStrip = [
    proj(u0, vFront, zSlot),
    proj(u0, vBack, zSlot),
    proj(u0 - 5, vBack, zShoulder - 12),
    ...backArch,
    ...frontArch.slice().reverse(),
    proj(u0 - 5, vFront, zShoulder - 12)
  ];

  drawPoly(crustStrip, {
    wash: PAL.tomatoDeep,
    washOpacity: 230,
    fill: PAL.tomatoDark,
    fillOpacity: 145,
    bleed: 0.04,
    texture: 0.85,
    hatchBrush: "dry_crayon",
    hatchColor: PAL.mustardDeep,
    hatchWeight: 1.0,
    hatchDist: 5,
    hatchAngle: -32,
    hatch2Brush: "fine_crayon",
    hatch2Color: PAL.tomatoDark,
    hatch2Weight: 0.9,
    hatch2Dist: 6,
    hatch2Angle: 45,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.tealNight,
    strokeWeight: 0.95
  });

  // Golden baked highlight along the top crown of the crust
  for (let i = 3; i < frontArch.length - 2; i++) {
    brush.set("fine_crayon", PAL.mustardLight, 1.35);
    brush.line(
      lerp(frontArch[i][0], backArch[i][0], 0.35),
      lerp(frontArch[i][1], backArch[i][1], 0.35),
      lerp(frontArch[i + 1][0], backArch[i + 1][0], 0.35),
      lerp(frontArch[i + 1][1], backArch[i + 1][1], 0.35)
    );
  }

  // B. Broad Front-Left Toasted Bread Face (at v = vFront)
  const breadFacePts = [
    proj(u0, vFront, zSlot),
    proj(u0 - 5, vFront, zShoulder - 12),
    ...frontArch,
    proj(u1 + 5, vFront, zShoulder - 12),
    proj(u1, vFront, zSlot)
  ];

  // Outer pale-golden toasted rim (Warm Cream & Light Mustard)
  drawPoly(breadFacePts, {
    wash: PAL.creamWarm,
    washOpacity: 225,
    fill: PAL.mustardLight,
    fillOpacity: 145,
    bleed: 0.05,
    texture: 0.88,
    hatchBrush: "dry_crayon",
    hatchColor: PAL.mustardBright,
    hatchWeight: 1.0,
    hatchDist: 6,
    hatchAngle: 22,
    hatch2Brush: "dry_crayon",
    hatch2Color: PAL.creamBright,
    hatch2Weight: 0.85,
    hatch2Dist: 7,
    hatch2Angle: -68,
    strokeBrush: "fine_crayon",
    strokeColor: PAL.tomatoDeep,
    strokeWeight: 1.15
  });

  // Inner richly browned toasted center patch (Mustard Deep & Tomato Mid)
  const innerArch = [];
  for (let i = 1; i <= 15; i++) {
    const t = i / 16;
    const u = lerp(u0 + 22, u1 - 22, t);
    const swell = Math.pow(Math.sin(t * Math.PI), 0.7);
    const z = (zShoulder - 10) + (zPeak - 22 - (zShoulder - 10)) * swell;
    innerArch.push(proj(u, vFront - 0.5, z));
  }
  const toastedCenterPts = [
    proj(u0 + 20, vFront - 0.5, zSlot + 3),
    ...innerArch,
    proj(u1 - 20, vFront - 0.5, zSlot + 3)
  ];

  drawPoly(toastedCenterPts, {
    fill: PAL.mustardMid,
    fillOpacity: 175,
    bleed: 0.14,
    texture: 0.9,
    hatchBrush: "dry_crayon",
    hatchColor: PAL.tomatoMid,
    hatchWeight: 0.95,
    hatchDist: 6,
    hatchAngle: 22,
    hatch2Brush: "dry_crayon",
    hatch2Color: PAL.mustardDeep,
    hatch2Weight: 0.9,
    hatch2Dist: 7,
    hatch2Angle: -68
  });

  // Deeper caramelized center toast blush & vertical wire-guard grill stripes
  const charCenterPts = [
    proj(u0 + 48, vFront - 1, zSlot + 8),
    proj(u0 + 55, vFront - 1, zPeak - 38),
    proj((u0 + u1) * 0.5, vFront - 1, zPeak - 28),
    proj(u1 - 55, vFront - 1, zPeak - 38),
    proj(u1 - 48, vFront - 1, zSlot + 8)
  ];
  drawPoly(charCenterPts, {
    fill: PAL.tomatoMid,
    fillOpacity: 115,
    bleed: 0.2,
    texture: 0.9,
    hatchBrush: "fine_crayon",
    hatchColor: PAL.tomatoDeep,
    hatchWeight: 0.85,
    hatchDist: 6,
    hatchAngle: -68
  });

  // Vertical paler stripes left by the toaster's internal wire rack guards
  for (const wf of [0.28, 0.50, 0.72]) {
    const uw = lerp(u0, u1, wf);
    const pBot = proj(uw, vFront - 1, zSlot + 4);
    const pTop = proj(uw, vFront - 1, zPeak - 22);
    brush.set("dry_crayon", PAL.mustardBright, 1.15);
    brush.line(pBot[0], pBot[1], pTop[0], pTop[1]);
    brush.set("fine_crayon", PAL.creamWarm, 0.8);
    brush.line(pBot[0] + 1, pBot[1], pTop[0] + 1, pTop[1]);
  }

  // Hyperrealistic porous bread-crumb cell texture across the toasted slice face
  for (let k = 0; k < 140; k++) {
    const tu = random(0.06, 0.94);
    const u = lerp(u0, u1, tu);
    const maxZ = zShoulder - 8 + (zPeak - 16 - (zShoulder - 8)) * Math.pow(Math.sin(tu * Math.PI), 0.7);
    const z = random(zSlot + 6, maxZ);
    const pt = proj(u, vFront - 1, z);

    // Pores are darker in the toasted center and golden near the rim
    const distCenter = Math.abs(tu - 0.5) * 2;
    const poreCol = distCenter < 0.55
      ? (random() < 0.55 ? PAL.tomatoDeep : PAL.mustardDeep)
      : (random() < 0.6 ? PAL.mustardMid : PAL.creamBright);

    brush.set("crumb_crayon", poreCol, random(0.55, 1.15));
    brush.line(pt[0], pt[1], pt[0] + random(-2.5, 2.5), pt[1] + random(-2.0, 2.0));
  }

  // Crisp dark toasted rim where the slice emerges from the slot
  const baseLine0 = proj(u0 - 2, vFront - 1, zSlot);
  const baseLine1 = proj(u1 + 2, vFront - 1, zSlot);
  brush.set("fine_crayon", PAL.tealNight, 1.3);
  brush.line(baseLine0[0], baseLine0[1], baseLine1[0], baseLine1[1]);
  brush.set("fine_crayon", PAL.tomatoBright, 0.95);
  brush.line(baseLine0[0], baseLine0[1] + 2, baseLine1[0], baseLine1[1] + 2);
}

// ============================================================================
// 8. FRONT CONTROL END-PANEL: BAKELITE CREST, DIAL & HALF-UP LEVER
// ============================================================================
function drawFrontControls() {
  // Helper for placing elements on the curved front end-cap (near u = -14)
