// ============================================================================
// 9. EVERY CRUMB ON THE SPECKLED LAMINATE DESCRIBED INDIVIDUALLY
// ============================================================================
function drawIndividualCrumbs() {
  // Collect ~115 distinct, individually sculpted crumbs across the countertop sweep:
  // 1) Near the front and right base of the toaster (where toast pops & is lifted)
  // 2) Trailing out across the generous sweep of counter to the right and foreground
  const crumbs = [];

  // Cluster A: Around front corner and right flank of toaster (38 crumbs)
  for (let i = 0; i < 38; i++) {
    const u = random(-135, 195);
    const v = random(-90, 390);
    // Keep outside toaster base footprint
    if (u > -14 && u < TOASTER_L + 12 && v > -12 && v < TOASTER_W + 14) continue;
    const pt = proj(u, v, 0);
    crumbs.push({
      x: pt[0],
      y: pt[1],
      size: random(3.2, 11.5),
      type: random() < 0.42 ? "crust" : (random() < 0.65 ? "toasted" : "crumb"),
      inShadow: u > -5 && u < 365 && v > 225,
      seed: i * 37
    });
  }

  // Cluster B: Generous sweep of counter to the right & lower-right foreground (78 crumbs)
  for (let i = 0; i < 78; i++) {
    // Spread across the wide counter expanse (x = 420..1150, y = 610..1165)
    const t = Math.pow(random(), 0.85);
    const sx = lerp(430, 1145, t) + random(-35, 35);
    const sy = lerp(630, 1155, random()) + (sx - 600) * 0.08;
    if (sx < 565 && sy < 885) continue;

    // Depth scale: crumbs closer to foreground (bottom) appear larger
    const persp = map(sy, 580, 1170, 0.58, 1.38, true);
    // Check if inside the toaster's morning cast shadow
    const inShadow = sy < 890 && sx > 520 && sx < 1030 && (sy - 690) < (sx - 520) * 0.24 && (sy - 840) > -(sx - 560) * 0.35;

    crumbs.push({
      x: constrain(sx, 80, 1165),
      y: constrain(sy, 600, 1170),
      size: random(2.8, 10.8) * persp,
      type: random() < 0.35 ? "crust" : (random() < 0.62 ? "toasted" : "crumb"),
      inShadow: inShadow,
      seed: 1000 + i * 53
    });
  }

  // Sort crumbs back-to-front by y coordinate for accurate occlusion
  crumbs.sort((a, b) => a.y - b.y);

  for (const c of crumbs) {
    drawSingleHyperrealCrumb(c);
  }
}

function drawSingleHyperrealCrumb(c) {
  const r = c.size;
  const x = c.x;
  const y = c.y;

  // Build an irregular, craggy 6-vertex 3D polyhedron silhouette for this specific crumb
  const nVerts = 6;
  const basePts = [];
  for (let i = 0; i < nVerts; i++) {
    const ang = (i / nVerts) * 360 + random(-18, 18);
    const radX = r * random(0.68, 1.25);
    const radY = r * random(0.45, 0.82); // foreshortened on counter plane
    basePts.push([
      x + cos(ang) * radX,
      y + sin(ang) * radY
    ]);
  }

  // Peak ridge point of the 3D crumb (shifted slightly up and left toward the light)
  const peakX = x + random(-r * 0.25, r * 0.15);
  const peakY = y - r * random(0.38, 0.72);

  // 1. Faint Semi-Gloss Laminate Reflection directly underneath the crumb
  const reflCol = c.type === "crust" ? PAL.tomatoDeep : PAL.mustardMid;
  brush.set("crumb_crayon", reflCol, 0.65);
  brush.line(x - r * 0.5, y + r * 0.55, x + r * 0.5, y + r * 0.55);

  // 2. Crisp Early-Morning Cast Shadow extending toward the right / upper-right (-18 deg)
  const shadowLen = r * (c.inShadow ? 0.75 : 1.65);
  const shDx = cos(-16) * shadowLen;
  const shDy = sin(-16) * shadowLen * 0.55;
  const shadowPts = [
    basePts[1],
    [basePts[0][0] + shDx, basePts[0][1] + shDy],
    [basePts[5][0] + shDx * 0.9, basePts[5][1] + shDy * 0.9],
    basePts[4],
    basePts[2]
  ];
  drawPoly(shadowPts, {
    wash: PAL.tealNight,
    washOpacity: c.inShadow ? 155 : 220
  });

  // 3. Determine Lit & Shaded Facet Colors based on Crumb Type (Crust, Toasted Golden, or Inner Crumb)
  let litCol, midCol, shadeCol, rimCol;
  if (c.type === "crust") {
    litCol = c.inShadow ? PAL.mustardDeep : PAL.tomatoBright;
    midCol = PAL.tomatoMid;
    shadeCol = PAL.tomatoDark;
    rimCol = PAL.mustardLight;
  } else if (c.type === "toasted") {
    litCol = c.inShadow ? PAL.mustardMid : PAL.mustardBright;
    midCol = c.inShadow ? PAL.mustardDeep : PAL.mustardLight;
    shadeCol = PAL.tomatoDeep;
    rimCol = PAL.creamBright;
  } else {
    // Pale warm cream interior bread crumb
    litCol = c.inShadow ? PAL.creamMid : PAL.creamBright;
    midCol = c.inShadow ? PAL.mustardMid : PAL.mustardLight;
    shadeCol = c.inShadow ? PAL.tealDeep : PAL.mustardDeep;
    rimCol = PAL.creamBright;
  }

  // 4. Shaded Right/Lower Facet of the 3D Crumb
  const shadeFacet = [
    peakY < basePts[4][1] ? [peakX, peakY] : basePts[4],
    basePts[5],
    basePts[0],
    basePts[1],
    basePts[2]
  ];
  drawPoly(shadeFacet, {
    wash: shadeCol,
    washOpacity: 235
  });

  // 5. Lit Left/Top Facet of the 3D Crumb (facing the early morning window light)
  const litFacet = [
    [peakX, peakY],
    basePts[1],
    basePts[2],
    basePts[3],
    basePts[4]
  ];
  drawPoly(litFacet, {
    wash: litCol,
    washOpacity: 240,
    hatchBrush: "crumb_crayon",
    hatchColor: midCol,
    hatchWeight: 0.7,
    hatchDist: 3,
    hatchAngle: 25
  });

  // 6. Crisp Craggy Crayon Contour, Dark Contact Crevice, and Specular Ridge Glint
  // Contact crevice at bottom edge
  brush.set("crumb_crayon", PAL.tealNight, 0.95);
  brush.line(basePts[0][0], basePts[0][1], basePts[1][0], basePts[1][1]);
  brush.line(basePts[1][0], basePts[1][1], basePts[2][0], basePts[2][1]);

  // Bright morning highlight glint on the top-left ridge of the crumb
  brush.set("crumb_crayon", rimCol, r > 5.5 ? 1.15 : 0.85);
  brush.line(basePts[3][0], basePts[3][1], peakX, peakY);
  if (r > 6.5) {
    // Internal bread pore speck on larger crumbs
    brush.set("crumb_crayon", shadeCol, 0.8);
    brush.line(peakX - 1.2, peakY + 1.5, peakX + 0.8, peakY + 2.2);
  }
}

// Hyperrealism in p5.brush: Fire Hydrant in a Driving Snow Squall

const WIND_ANGLE = 22; // Diagonal wind direction in degrees

// Hydrant anchor on 1200x1200 canvas (slightly off-center for quiet disorientation)
const HYD_CX = 668;
const HYD_CY = 605;

// Camera orientation (degrees)
const CAM_YAW = -27;
const CAM_PITCH = 18.5;
const CAM_ROLL = -3.8;

let cosYaw, sinYaw, cosPitch, sinPitch, cosRoll, sinRoll;

// 3D to 2D projection with subtle perspective foreshortening
function proj(x, y, z) {
  let x1 = x * cosYaw + z * sinYaw;
  let y1 = y;
  let z1 = -x * sinYaw + z * cosYaw;

  let x2 = x1;
  let y2 = y1 * cosPitch - z1 * sinPitch;
  let z2 = y1 * sinPitch + z1 * cosPitch;

  let x3 = x2 * cosRoll - y2 * sinRoll;
  let y3 = x2 * sinRoll + y2 * cosRoll;

  let persp = 1550 / (1550 - z2);
  return {
    x: HYD_CX + x3 * persp,
    y: HYD_CY - y3 * persp,
    z: z2
  };
}

// Rotate surface normal into view space for lighting
function rotNormal(nx, ny, nz) {
  let x1 = nx * cosYaw + nz * sinYaw;
  let y1 = ny;
  let z1 = -nx * sinYaw + nz * cosYaw;

  let x2 = x1;
  let y2 = y1 * cosPitch - z1 * sinPitch;
  let z2 = y1 * sinPitch + z1 * cosPitch;

  let len = Math.hypot(x2, y2, z2) || 1;
  return { x: x2 / len, y: y2 / len, z: z2 / len };
}

// Safe spline helper that avoids coincident points
function safeSpline(pts, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    if ( Math.hypot(pts[i][0] - prev[0], pts[i][1] - prev[1]) > 1.0 ) {
      clean.push(pts[i]);
    }
  }
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else if (clean.length >= 3) {
    brush.spline(clean, curv);
  }
}

// Wind-sculpted snowline across the hydrant's shoulders and nozzle
function getSnowLineY(screenX) {
  // Base diagonal drift rising from left to right with a wind-scoured hollow around the nozzle
  let base = 695 + (screenX - 600) * 0.14;
  // Windward pile-up on left shoulder (x ~ 520..565)
  let windwardMound = -26 * Math.exp(-Math.pow((screenX - 535) / 55, 2));
  // Wind-scoured scoop right beneath the protruding nozzle (x ~ 575..645)
  let nozzleScoop = 48 * Math.exp(-Math.pow((screenX - 605) / 48, 2));
  // Leeward drift rising over the right shoulder (x ~ 695..790)
  let rightDrift = -38 * Math.exp(-Math.pow((screenX - 745) / 70, 2));
  let micro = (noise(screenX * 0.015, 12.3) - 0.5) * 14;
  return base + windwardMound + nozzleScoop + rightDrift + micro;
}

// Compute cadmium red marker color from 3D surface normal and ambient occlusion
function getCadmiumColor(nx, ny, nz, ao = 1.0) {
  let n = rotNormal(nx, ny, nz);
  // Primary cold sky light from upper-left-front
  let l1 = Math.max(0, n.x * -0.58 + n.y * 0.68 + n.z * 0.45);
  // Specular rim from upper-left
  let spec = Math.pow(Math.max(0, n.x * -0.42 + n.y * 0.62 + n.z * 0.66), 7);
  // Snow bounce light from below-front
  let bounce = Math.max(0, n.x * -0.15 + n.y * -0.78 + n.z * 0.58) * 0.35;

  let lum = (l1 * 0.88 + bounce * 0.32 + 0.12) * ao;

  if (spec > 0.48 && ao > 0.85) return "#ff7863"; // Icy wet specular glaze
  if (lum > 0.78) return "#ff3621";               // Blazing Cadmium Red Light
  if (lum > 0.62) return "#eb2110";               // Pure Cadmium Scarlet
  if (lum > 0.48) return "#cf1509";               // Cadmium Red Medium
  if (lum > 0.35) return "#a80d07";               // Deep Cadmium Red
  if (lum > 0.24) return "#7d0806";               // Crimson Core Shadow
  if (lum > 0.15) return "#520607";               // Cast-iron Dark Crimson
  return "#290507";                               // Deep Crevice Iron-Black
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);

  randomSeed(8421);
  noiseSeed(8421);

  cosYaw = cos(CAM_YAW);
  sinYaw = sin(CAM_YAW);
  cosPitch = cos(CAM_PITCH);
  sinPitch = sin(CAM_PITCH);
  cosRoll = cos(CAM_ROLL);
  sinRoll = sin(CAM_ROLL);

  // Custom brushes tailored for 1200x1200 hyperrealism
  brush.add("cad_marker", {
    type: "marker",
    weight: 5.2,
    scatter: 0.04,
    opacity: 115,
    spacing: 0.16,
    pressure: [0.85, 1.0, 0.85],
    markerTip: false,
    noise: 0.18
  });

  brush.add("micro_marker", {
    type: "marker",
    weight: 2.2,
    scatter: 0.02,
    opacity: 165,
    spacing: 0.14,
    pressure: [0.75, 1.0, 0.75],
    markerTip: false,
    noise: 0.1
  });

  brush.add("rime_white", {
    type: "default",
    weight: 1.45,
    scatter: 0.32,
    sharpness: 0.84,
    grain: 15,
    opacity: 240,
    spacing: 0.11,
    pressure: [0.55, 1.3, 0.35],
    noise: 0.45
  });

  brush.add("frost_stipple", {
    type: "spray",
    weight: 6.5,
    scatter: 1.25,
    opacity: 165,
    spacing: 0.22,
    pressure: [0.5, 1.1, 0.5]
  });

  brush.add("squall_mist", {
    type: "spray",
    weight: 44,
    scatter: 3.4,
    opacity: 36,
    spacing: 0.42,
    pressure: [0.4, 1.0, 0.4]
  });

  // Custom vector field for the diagonal snow squall with a subtle eddy around the hydrant
  brush.addField("squall_flow", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let fx = (col / field.length) * 1200;
        let fy = (row / field[0].length) * 1200;
        let n = (noise(col * 0.08, row * 0.08) - 0.5) * 14;
        // Slight upward/leeward curl near the hydrant dome
        let dx = fx - HYD_CX;
        let dy = fy - HYD_CY;
        let d = Math.hypot(dx, dy);
        let eddy = d < 260 ? Math.sin((1 - d / 260) * Math.PI) * -10 * Math.sign(dy) : 0;
        field[col][row] = WIND_ANGLE + n + eddy;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // Stark, icy white ground
  background("#f7f9fc");

  // 1. Atmospheric snow squall washes & soft grey-white spray
  drawBackgroundSquall();

  // 2. Hydrant Upper Barrel (Shoulders) & Bonnet Flange
  drawHydrantShoulderAndFlange();

  // 3. Hydrant Dome (Cap), Cast Ribs, Flange Bolts & Top Pentagon Nut
  drawHydrantDomeAndNut();

  // 4. Protruding Bolted Nozzle, Wrench Lugs, Nozzle Nut & Dangling Chain
  drawBoltedNozzle();

  // 5. Clinging Ice Rime in crisp white pencil & granular frost
  drawClingingIceRime();

  // 6. Layered translucent snowdrift washes & white edge dissolution
  drawForegroundDriftsAndEdgeDissolve();

  // 7. Driving diagonal pencil flecks & snow streaks across the sheet
  drawWindblownPencilFlecks();

  noLoop();
}

// ============================================================================
// 1. BACKGROUND SQUALL (Soft grey-white spray & overcast translucent washes)
// ============================================================================
function drawBackgroundSquall() {
  brush.noStroke();

  // Batch 1: Soft slate-grey atmospheric squall washes in the central region
  // (provides the mid-high value ground so crisp white pencil rime & flecks pop)
  const squallLayers = [
    { col: "#dde4ed", alpha: 52, bleed: 0.42, count: 5, radX: 420, radY: 230 },
    { col: "#ced8e4", alpha: 46, bleed: 0.38, count: 5, radX: 340, radY: 185 },
    { col: "#bfcbe0", alpha: 38, bleed: 0.35, count: 4, radX: 260, radY: 145 }
  ];

  for (let layer of squallLayers) {
    brush.fill(layer.col, layer.alpha);
    brush.fillBleed(layer.bleed, "out");
    brush.fillTexture(0.45, 0.12);

    for (let i = 0; i < layer.count; i++) {
      let cx = 580 + random(-210, 210);
      let cy = 560 + random(-190, 170) + (cx - 600) * 0.25;
      drawTiltedCloudPoly(cx, cy, layer.radX * random(0.8, 1.25), layer.radY * random(0.8, 1.2), WIND_ANGLE, 12);
    }
  }
  brush.noFill();

  // Soft grey-white spray sheets driving diagonally
  const sprayPasses = [
    { col: "#c5d0de", wt: 1.2, count: 65, spread: 430 },
    { col: "#d8e1ec", wt: 1.4, count: 80, spread: 500 },
    { col: "#e9eff6", wt: 1.6, count: 70, spread: 540 }
  ];

  for (let sp of sprayPasses) {
    brush.set("squall_mist", sp.col, sp.wt);
    for (let i = 0; i < sp.count; i++) {
      let a = random(360);
      let r = Math.pow(random(), 0.75) * sp.spread;
      let cx = 630 + cos(a) * r * 1.15;
      let cy = 590 + sin(a) * r * 0.95;
      let len = random(140, 340);
      let x1 = cx - cos(WIND_ANGLE) * len * 0.5;
      let y1 = cy - sin(WIND_ANGLE) * len * 0.5;
      let x2 = cx + cos(WIND_ANGLE) * len * 0.5;
      let y2 = cy + sin(WIND_ANGLE) * len * 0.5;
      brush.line(x1, y1, x2, y2);
    }
  }
}

function drawTiltedCloudPoly(cx, cy, rx, ry, angleDeg, steps) {
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);
  brush.beginShape(0.45);
  for (let i = 0; i < steps; i++) {
    let th = (i / steps) * 360;
    let nr = 0.72 + noise(cx * 0.01 + cos(th) * 1.3, cy * 0.01 + sin(th) * 1.3) * 0.55;
    let lx = cos(th) * rx * nr;
    let ly = sin(th) * ry * nr;
    let gx = cx + lx * ca - ly * sa;
    let gy = cy + lx * sa + ly * ca;
    brush.vertex(gx, gy);
  }
  brush.endShape(true);
}

// ============================================================================
// 2. HYDRANT SHOULDER (UPPER BARREL) & BONNET FLANGE
// ============================================================================
function drawHydrantShoulderAndFlange() {
  const R_BARREL = 106;

  // --- 2A. Upper Barrel Cylindrical Marker Shading ---
  // Sweep meridian strips from left (-115°) to right (+115°)
  const aSteps = 72;
  for (let i = 0; i <= aSteps; i++) {
    let deg = map(i, 0, aSteps, -112, 112);
    let nx = sin(deg);
    let nz = cos(deg);

    // Determine radius profile along Y (from -160 up to 0)
    let topP = proj(nx * R_BARREL, 0, nz * R_BARREL);
    let snowY = getSnowLineY(topP.x);

    // Subdivide vertically so we can vary ambient occlusion under the flange and near the nozzle shadow
    let ySegs = 14;
    for (let j = 0; j < ySegs; j++) {
      let y0 = map(j, 0, ySegs, -155, 0);
      let y1 = map(j + 1, 0, ySegs, -155, 0);

      // Slight flare right under the flange (y > -14)
      let r0 = R_BARREL + (y0 > -14 ? map(y0, -14, 0, 0, 7) : 0);
      let r1 = R_BARREL + (y1 > -14 ? map(y1, -14, 0, 0, 7) : 0);

      let p0 = proj(nx * r0, y0, nz * r0);
      let p1 = proj(nx * r1, y1, nz * r1);

      // Stop stroke softly inside the snowbank
      let limitY = snowY + (noise(i * 0.3, j * 0.3) - 0.3) * 16;
      if (p0.y > limitY && p1.y > limitY) continue;
      if (p0.y > limitY) {
        p0.y = limitY;
      }

      // Compute AO: dark undercut right below flange (y > -16) and cast shadow from nozzle (deg in -15..45, y < -65)
      let ao = 1.0;
      if (y1 > -18) ao *= map(y1, -18, 0, 1.0, 0.32);
      // Cast shadow from the protruding nozzle onto the lower-right barrel
      let dNoz = Math.hypot(deg - 18, (y0 + 82) * 0.75);
      if (dNoz < 48) ao *= map(dNoz, 0, 48, 0.35, 1.0);
      // Dissolve right/leeward bottom edge slightly
      if (deg > 78 && y0 < -65) ao *= 0.75;

      let col = getCadmiumColor(nx, -0.05, nz, ao);
      brush.set("cad_marker", col, random(0.65, 0.95));
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // Cross-contour latitude marker strokes on the shoulder to lock in cylindrical volume
  for (let y = -125; y <= -4; y += 7) {
    let r = R_BARREL + (y > -14 ? map(y, -14, 0, 0, 7) : 0);
    // Raised cast-iron molding seam at y = -34
    if (Math.abs(y - -34) < 4) r += 3.5;

    let segStart = -108;
    let stepDeg = 18;
    for (let deg = segStart; deg < 105; deg += stepDeg) {
      let midDeg = deg + stepDeg * 0.5;
      let nx = sin(midDeg);
      let nz = cos(midDeg);
      let ny = (y === -31) ? 0.45 : (y === -37 ? -0.55 : 0);

      let pA = proj(sin(deg) * r, y, cos(deg) * r);
      let pB = proj(sin(deg + stepDeg) * r, y, cos(deg + stepDeg) * r);
      let snowY = getSnowLineY((pA.x + pB.x) * 0.5);
      if (pA.y > snowY + 8 || pB.y > snowY + 8) continue;

      let ao = y > -16 ? map(y, -16, 0, 0.95, 0.28) : 1.0;
      let col = getCadmiumColor(nx, ny, nz, ao);
      brush.set("micro_marker", col, 0.85);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }
  }

  // Crisp cast-iron crevice lines under the shoulder molding & flange undercut
  drawCylinderArc(R_BARREL + 2, -37, -100, 102, "rotring", "#2b0506", 0.55);
  drawCylinderArc(R_BARREL + 7, -2, -108, 108, "rotring", "#1a0405", 0.85);

  // --- 2B. Bonnet Flange Rim (Y = 0 to 16, R = 125) ---
  const R_FLANGE = 125;
  const R_DOME_BASE = 103;

  // Underside bevel of flange
  for (let deg = -115; deg < 115; deg += 8) {
    let p0 = proj(sin(deg) * (R_BARREL + 6), -2, cos(deg) * (R_BARREL + 6));
    let p1 = proj(sin(deg + 8) * R_FLANGE, 3, cos(deg + 8) * R_FLANGE);
    brush.set("micro_marker", "#280506", 0.9);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // Vertical outer edge of the flange (Y = 2 to 15)
  for (let deg = -112; deg <= 112; deg += 3) {
    let nx = sin(deg);
    let nz = cos(deg);
    let p0 = proj(nx * R_FLANGE, 2, nz * R_FLANGE);
    let p1 = proj(nx * R_FLANGE, 15, nz * R_FLANGE);
    let col = getCadmiumColor(nx, 0.05, nz, 0.95);
    brush.set("micro_marker", col, 0.95);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }

  // Flat top deck of the flange (Y = 15, radial ring from R_DOME_BASE to R_FLANGE)
  for (let r = R_DOME_BASE - 2; r <= R_FLANGE; r += 2.8) {
    for (let deg = -155; deg < 155; deg += 12) {
      let mid = deg + 6;
      let nx = sin(mid) * 0.25;
      let nz = cos(mid) * 0.25;
      let ny = 0.94;
      let ao = r < R_DOME_BASE + 6 ? 0.55 : 1.0;
      let col = getCadmiumColor(nx, ny, nz, ao);
      let pA = proj(sin(deg) * r, 15, cos(deg) * r);
      let pB = proj(sin(deg + 12) * r, 15, cos(deg + 12) * r);
      brush.set("micro_marker", col, 0.8);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }
  }

  // Crisp upper & lower rim contours of the bonnet flange
  drawCylinderArc(R_FLANGE, 2, -110, 110, "rotring", "#240405", 0.65);
  drawCylinderArc(R_FLANGE, 15, -115, 115, "rotring", "#4a0707", 0.5);
}

// ============================================================================
// 3. HYDRANT DOME (BONNET), RIBS, FLANGE BOLTS & PENTAGON NUT
// ============================================================================
function drawHydrantDomeAndNut() {
  const R_DOME_BASE = 102;
  const Y_FLANGE_TOP = 15;
  const Y_DOME_TOP = 114;

  // Helper for dome radius & surface slope at height y (from 15 to 114)
  function getDomeProfile(y) {
    let t = constrain((y - Y_FLANGE_TOP) / (Y_DOME_TOP - Y_FLANGE_TOP), 0, 1);
    // Classic fire hydrant bonnet: slightly tapered lower skirt up to t=0.28, then hemispherical dome
    let r;
    let ny;
    if (t < 0.28) {
      r = map(t, 0, 0.28, R_DOME_BASE, 95);
      ny = 0.14;
      // Raised cast band around t = 0.26..0.31
      if (Math.abs(t - 0.28) < 0.035) {
        r += 3.8 * Math.cos(((t - 0.28) / 0.035) * (Math.PI / 2));
        ny += (t > 0.28) ? 0.45 : -0.45;
      }
    } else {
      let u = map(t, 0.28, 1.0, 0, 1);
      r = 33 + 62 * Math.cos(u * (Math.PI * 0.48));
      ny = Math.sin(u * (Math.PI * 0.48)) * 0.85;
    }
    return { r, ny };
  }

  // Draw rear flange bolts first (those behind the dome profile)
  const boltAngles = [-135, -90, -45, 0, 45, 90, 135, 180];
  for (let bDeg of boltAngles) {
    let viewZ = -sin(bDeg) * sinYaw + cos(bDeg) * cosYaw;
    if (viewZ < 0) {
      drawHexBoltVertical(sin(bDeg) * 114, 15, cos(bDeg) * 114, 8.5, 7.5);
    }
  }

  // --- 3A. Bonnet Dome Surface Marker Rendering ---
  const ySteps = 34;
  for (let j = 0; j < ySteps; j++) {
    let y0 = map(j, 0, ySteps, Y_FLANGE_TOP, Y_DOME_TOP);
    let y1 = map(j + 1, 0, ySteps, Y_FLANGE_TOP, Y_DOME_TOP);
    let prof0 = getDomeProfile(y0);
    let prof1 = getDomeProfile(y1);

    for (let deg = -114; deg <= 114; deg += 4) {
      let nx = sin(deg) * Math.sqrt(Math.max(0, 1 - prof0.ny * prof0.ny));
      let nz = cos(deg) * Math.sqrt(Math.max(0, 1 - prof0.ny * prof0.ny));
      let ny = prof0.ny;

      // 8 raised meridional cast ribs at boltAngles
      let ribBoost = 0;
      let ribNxShift = 0;
      for (let bDeg of boltAngles) {
        let dA = ((deg - bDeg + 540) % 360) - 180;
        if (Math.abs(dA) < 5.5) {
          ribBoost = 3.2 * Math.cos((dA / 5.5) * (Math.PI / 2));
          ribNxShift = (dA / 5.5) * 0.35;
        }
      }

      let r0 = prof0.r + ribBoost;
      let r1 = prof1.r + ribBoost;
      let p0 = proj(sin(deg) * r0, y0, cos(deg) * r0);
      let p1 = proj(sin(deg) * r1, y1, cos(deg) * r1);

      let ao = j < 2 ? 0.65 : (j > ySteps - 3 ? 0.72 : 1.0);
      let col = getCadmiumColor(nx + ribNxShift * cos(deg), ny, nz - ribNxShift * sin(deg), ao);
      brush.set("cad_marker", col, 0.72);
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  // Crisp latitude contour strokes & rib edge definitions on the dome
  for (let y = Y_FLANGE_TOP + 4; y <= Y_DOME_TOP - 2; y += 6.5) {
    let prof = getDomeProfile(y);
    for (let deg = -108; deg < 108; deg += 12) {
      let mid = deg + 6;
      let s = Math.sqrt(Math.max(0, 1 - prof.ny * prof.ny));
      let col = getCadmiumColor(sin(mid) * s, prof.ny, cos(mid) * s, 1.0);
      let pA = proj(sin(deg) * prof.r, y, cos(deg) * prof.r);
      let pB = proj(sin(deg + 12) * prof.r, y, cos(deg + 12) * prof.r);
      brush.set("micro_marker", col, 0.7);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }
  }

  // Emphasize the 8 raised meridional ribs on the dome with fine marker & pencil shadow lines
  for (let bDeg of boltAngles) {
    let viewZ = -sin(bDeg) * sinYaw + cos(bDeg) * cosYaw;
    if (viewZ < -0.25) continue;
    let ptsCenter = [];
    let ptsShadow = [];
    for (let y = Y_FLANGE_TOP + 3; y <= Y_DOME_TOP - 3; y += 6) {
      let prof = getDomeProfile(y);
      let rRib = prof.r + 3.4;
      ptsCenter.push(proj(sin(bDeg) * rRib, y, cos(bDeg) * rRib));
      ptsShadow.push(proj(sin(bDeg + 4.8) * (prof.r + 0.6), y, cos(bDeg + 4.8) * (prof.r + 0.6)));
    }
    let s = 0.75;
    let ribCol = getCadmiumColor(sin(bDeg - 8) * s, 0.45, cos(bDeg - 8) * s, 1.05);
    brush.set("micro_marker", ribCol, 0.85);
    safeSpline(ptsCenter.map(p => [p.x, p.y]), 0.4);

    brush.set("rotring", "#3d0606", 0.45);
    safeSpline(ptsShadow.map(p => [p.x, p.y]), 0.4);
  }

  // Draw front flange bolts sitting on the flange deck (Y = 15, R = 114)
  for (let bDeg of boltAngles) {
    let viewZ = -sin(bDeg) * sinYaw + cos(bDeg) * cosYaw;
    if (viewZ >= 0) {
      drawHexBoltVertical(sin(bDeg) * 114, 15, cos(bDeg) * 114, 8.8, 8.0);
    }
  }

  // --- 3B. Top Collar (Y = 114 to 125, R = 36) & 5-Sided Pentagon Operating Nut (Y = 125 to 150) ---
  const R_COLLAR = 36;
  for (let deg = -125; deg <= 125; deg += 6) {
    let nx = sin(deg);
    let nz = cos(deg);
    let p0 = proj(nx * R_COLLAR, 114, nz * R_COLLAR);
    let p1 = proj(nx * (R_COLLAR - 2), 125, nz * (R_COLLAR - 2));
    let col = getCadmiumColor(nx, 0.1, nz, 0.85);
    brush.set("micro_marker", col, 0.85);
    brush.line(p0.x, p0.y, p1.x, p1.y);
  }
  // Collar top deck
  for (let r = 24; r <= 34; r += 2.5) {
    drawCylinderArc(r, 125, -170, 170, "micro_marker", "#eb2413", 0.7);
  }
  drawCylinderArc(R_COLLAR, 114, -115, 115, "rotring", "#2b0506", 0.6);

  // 5-Sided Pentagonal Operating Nut (Y = 125 to 150, R = 25)
  const R_PENT = 25;
  const Y_PENT_BOT = 125;
  const Y_PENT_TOP = 150;
  const pentAngles = [-142, -70, 2, 74, 146];

  // Collect faces and sort back-to-front
  let faces = [];
  for (let k = 0; k < 5; k++) {
    let a1 = pentAngles[k];
    let a2 = pentAngles[(k + 1) % 5];
    let midA = a1 + (((a2 - a1 + 540) % 360) - 180) * 0.5;
    let nx = sin(midA);
    let nz = cos(midA);
    let viewNormal = rotNormal(nx, 0, nz);
    faces.push({ a1, a2, midA, nx, nz, zOrder: viewNormal.z });
  }
  faces.sort((a, b) => a.zOrder - b.zOrder);

  for (let f of faces) {
    if (f.zOrder < -0.15) continue; // Back-facing facet
    let col = getCadmiumColor(f.nx, 0.05, f.nz, 0.95);
    let steps = 12;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      let x = lerp(sin(f.a1) * R_PENT, sin(f.a2) * R_PENT, t);
      let z = lerp(cos(f.a1) * R_PENT, cos(f.a2) * R_PENT, t);
      let pBot = proj(x, Y_PENT_BOT, z);
      let pTop = proj(x, Y_PENT_TOP, z);
      brush.set("micro_marker", col, 0.85);
      brush.line(pBot.x, pBot.y, pTop.x, pTop.y);
    }
    // Chipped dark cast-iron/bronze wear along the sharp vertical edges of the wrench nut
    let eBot = proj(sin(f.a1) * R_PENT, Y_PENT_BOT, cos(f.a1) * R_PENT);
    let eTop = proj(sin(f.a1) * R_PENT, Y_PENT_TOP, cos(f.a1) * R_PENT);
    brush.set("rotring", "#1f191b", 0.65);
    brush.line(eBot.x, eBot.y, eTop.x, eTop.y);
  }

  // Pentagon Nut Top Face (Y = 150) with slight central dome
  for (let k = 0; k < 5; k++) {
    let a1 = pentAngles[k];
    let a2 = pentAngles[(k + 1) % 5];
    for (let s = 0; s <= 8; s++) {
      let t = s / 8;
      let vx = lerp(sin(a1) * R_PENT, sin(a2) * R_PENT, t);
      let vz = lerp(cos(a1) * R_PENT, cos(a2) * R_PENT, t);
      let pOut = proj(vx, Y_PENT_TOP, vz);
      let pIn = proj(0, Y_PENT_TOP + 3.5, 0);
      let col = getCadmiumColor(vx * 0.01, 0.96, vz * 0.01, 1.0);
      brush.set("micro_marker", col, 0.75);
      brush.line(pOut.x, pOut.y, pIn.x, pIn.y);
    }
    // Top pentagon bevel edge in dark worn iron
    let p1 = proj(sin(a1) * R_PENT, Y_PENT_TOP, cos(a1) * R_PENT);
    let p2 = proj(sin(a2) * R_PENT, Y_PENT_TOP, cos(a2) * R_PENT);
    brush.set("rotring", "#241b1d", 0.6);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }
}

// Helper to draw a vertical 3D hex bolt sitting on a horizontal flange
function drawHexBoltVertical(bx, by, bz, rad, ht) {
  const hexA = [0, 60, 120, 180, 240, 300];
  // Dark cast-iron washer shadow at base
  for (let a = 0; a < 360; a += 30) {
    let p1 = proj(bx + sin(a) * (rad + 2), by + 0.5, bz + cos(a) * (rad + 2));
    let p2 = proj(bx + sin(a + 30) * (rad + 2), by + 0.5, bz + cos(a + 30) * (rad + 2));
    brush.set("rotring", "#1c0506", 0.65);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Vertical facets of hex head
  for (let k = 0; k < 6; k++) {
    let a1 = hexA[k];
    let a2 = hexA[(k + 1) % 6];
    let mid = a1 + 30;
    let vn = rotNormal(sin(mid), 0, cos(mid));
    if (vn.z < -0.1) continue;
    let col = getCadmiumColor(sin(mid), 0.1, cos(mid), 0.9);
    for (let s = 0; s <= 4; s++) {
      let t = s / 4;
      let vx = bx + lerp(sin(a1) * rad, sin(a2) * rad, t);
      let vz = bz + lerp(cos(a1) * rad, cos(a2) * rad, t);
      let p0 = proj(vx, by + 1, vz);
      let p1 = proj(vx, by + ht, vz);
      brush.set("micro_marker", col, 0.7);
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
    let e0 = proj(bx + sin(a1) * rad, by + 1, bz + cos(a1) * rad);
    let e1 = proj(bx + sin(a1) * rad, by + ht, bz + cos(a1) * rad);
    brush.set("rotring", "#240708", 0.45);
    brush.line(e0.x, e0.y, e1.x, e1.y);
  }

  // Top hexagonal face
  for (let k = 0; k < 6; k++) {
    let a1 = hexA[k];
    let a2 = hexA[(k + 1) % 6];
    let pC = proj(bx, by + ht + 1, bz);
    let p1 = proj(bx + sin(a1) * rad, by + ht, bz + cos(a1) * rad);
    let p2 = proj(bx + sin(a2) * rad, by + ht, bz + cos(a2) * rad);
    brush.set("micro_marker", "#ff3b26", 0.65);
    brush.line(p1.x, p1.y, pC.x, pC.y);
    brush.line(p2.x, p2.y, pC.x, pC.y);
    brush.set("rotring", "#330808", 0.4);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }
}

// Helper to draw a horizontal 3D arc on the main hydrant axis
function drawCylinderArc(r, y, degStart, degEnd, brushName, col, wt) {
  let pts = [];
  for (let deg = degStart; deg <= degEnd; deg += 5) {
    let p = proj(sin(deg) * r, y, cos(deg) * r);
    pts.push([p.x, p.y]);
  }
  brush.set(brushName, col, wt);
  safeSpline(pts, 0.4);
}

// ============================================================================
// 4. PROTRUDING BOLTED NOZZLE, WRENCH LUGS, PENTAGON NUT & CHAIN
// ============================================================================
function drawBoltedNozzle() {
  const Y_NOZ = -68; // Nozzle center height on the hydrant shoulder

  // Helper to project a point in Nozzle cylindrical coords (r, th, z)
  // th = 0 is top (+Y), th = 90 is right (+X), th = -90 is left (-X), th = 180 is bottom (-Y)
  function projNoz(r, th, z) {
    let x = sin(th) * r;
    let y = Y_NOZ + cos(th) * r;
    return proj(x, y, z);
  }

  // Helper to draw a cylindrical band along the nozzle (+Z axis)
  function drawNozzleCylinder(z0, z1, r0, r1, zSteps, aoMult = 1.0) {
    for (let s = 0; s < zSteps; s++) {
      let za = map(s, 0, zSteps, z0, z1);
      let zb = map(s + 1, 0, zSteps, z0, z1);
      let ra = map(s, 0, zSteps, r0, r1);
      let rb = map(s + 1, 0, zSteps, r0, r1);

      for (let th = -165; th <= 165; th += 4) {
        let nx = sin(th);
        let ny = cos(th);
        let vn = rotNormal(nx, ny, 0.15);
        if (vn.z < -0.22) continue;

        let p0 = projNoz(ra, th, za);
        let p1 = projNoz(rb, th, zb);

        // Clip bottom of nozzle softly where snowdrift laps up against it
        let snowY = getSnowLineY(p0.x) + 6;
        if (p0.y > snowY && p1.y > snowY) continue;

        let col = getCadmiumColor(nx, ny, 0.12, aoMult);
        brush.set("cad_marker", col, 0.72);
        brush.line(p0.x, p0.y, p1.x, p1.y);
      }
    }

    // Ring contour strokes around the nozzle cylinder
    for (let z = z0; z <= z1; z += 5) {
      let r = map(z, z0, z1, r0, r1);
      for (let th = -150; th < 150; th += 15) {
        let mid = th + 7.5;
        let vn = rotNormal(sin(mid), cos(mid), 0.15);
        if (vn.z < -0.15) continue;
        let pA = projNoz(r, th, z);
        let pB = projNoz(r, th + 15, z);
        if (pA.y > getSnowLineY(pA.x) + 6) continue;
        let col = getCadmiumColor(sin(mid), cos(mid), 0.15, aoMult);
        brush.set("micro_marker", col, 0.75);
        brush.line(pA.x, pA.y, pB.x, pB.y);
      }
    }
  }

  // --- 4A. Nozzle Mounting Flange on Barrel (Z = 92 to 114, R = 64) ---
  const R_MOUNT = 64;
  drawNozzleCylinder(92, 114, R_MOUNT + 2, R_MOUNT, 5, 0.88);

  // Flat front face of the mounting flange (Z = 114, R from 46 to 64)
  for (let r = 46; r <= R_MOUNT; r += 2.5) {
    for (let th = -165; th < 165; th += 14) {
      let pA = projNoz(r, th, 114);
      let pB = projNoz(r, th + 14, 114);
      if (pA.y > getSnowLineY(pA.x) + 6) continue;
      let col = getCadmiumColor(sin(th) * 0.25, cos(th) * 0.25, 0.94, r < 51 ? 0.55 : 0.95);
      brush.set("micro_marker", col, 0.8);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }
  }
  drawNozzleRingArc(R_MOUNT, 114, -155, 145, "rotring", "#2b0506", 0.6);

  // 6 Hex Bolts around the nozzle mounting flange (R = 55, Z = 114..121)
  const nozBoltAngles = [-145, -85, -25, 35, 95, 155];
  for (let bTh of nozBoltAngles) {
    let bx = sin(bTh) * 55;
    let by = Y_NOZ + cos(bTh) * 55;
    let pTest = proj(bx, by, 116);
    if (pTest.y < getSnowLineY(pTest.x) + 4) {
      drawHexBoltForward(bx, by, 114, 5.8, 6.5);
    }
  }

  // --- 4B. Nozzle Thread Neck (Z = 114 to 140, R = 46) ---
  drawNozzleCylinder(114, 134, 46, 46, 5, 0.82);
  // Dark thread undercut groove at Z = 134..140
  drawNozzleCylinder(134, 140, 43, 43, 2, 0.35);
  drawNozzleRingArc(46, 134, -150, 145, "rotring", "#1e0405", 0.75);

  // --- 4C. Rear Wrench Lugs on Nozzle Cap (angles 60° and 140° on right/bottom-right) ---
  const lugAngles = [-130, -42, 48, 138];
  for (let lTh of lugAngles) {
    if (lTh > 0) {
      drawNozzleLug(lTh, 145, 169, 53, 69);
    }
  }

  // --- 4D. Heavy Cast Nozzle Cap Cylinder (Z = 140 to 175, R = 54) ---
  drawNozzleCylinder(140, 172, 54, 54, 7, 1.0);
  // Front bevel of nozzle cap (Z = 172 to 176, R = 54 down to 50)
  drawNozzleCylinder(172, 176, 54, 50, 2, 1.05);
  drawNozzleRingArc(54, 140, -150, 145, "rotring", "#240405", 0.7);
  drawNozzleRingArc(54, 172, -155, 150, "rotring", "#420607", 0.55);

  // --- 4E. Front/Windward Wrench Lugs on Nozzle Cap (angles -130° and -42°) ---
  for (let lTh of lugAngles) {
    if (lTh <= 0) {
      drawNozzleLug(lTh, 145, 169, 53, 69);
    }
  }

  // --- 4F. Recessed Front Face of Nozzle Cap (Z = 174..176, R = 0 to 50) ---
  for (let r = 18; r <= 50; r += 2.2) {
    // Deep recessed groove between R = 36 and R = 43
    let zFace = (r > 35 && r < 44) ? 172 : 176;
    let ao = (r > 35 && r < 44) ? 0.42 : (r < 23 ? 0.58 : 0.96);
    for (let th = -180; th < 180; th += 14) {
      let mid = th + 7;
      // Top inner lip of recess is in shadow, bottom inner lip catches sky light
      let ny = (r > 42 && r < 46) ? -cos(mid) * 0.6 : cos(mid) * 0.18;
      let nx = (r > 42 && r < 46) ? -sin(mid) * 0.6 : sin(mid) * 0.18;
      let pA = projNoz(r, th, zFace);
      let pB = projNoz(r, th + 14, zFace);
      let col = getCadmiumColor(nx, ny, 0.92, ao);
      brush.set("micro_marker", col, 0.78);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }
  }
  drawNozzleRingArc(44, 175, -180, 180, "rotring", "#260405", 0.65);
  drawNozzleRingArc(35, 175, -180, 180, "rotring", "#3b0607", 0.5);

  // --- 4G. Heavy Iron Security Chain Dangling from Bottom of Nozzle Cap ---
  drawNozzleChain();

  // --- 4H. Central 5-Sided Pentagonal Nozzle Nut (Z = 176 to 196, R = 20) ---
  const R_NOZ_PENT = 20;
  const Z_NP_BASE = 175;
  const Z_NP_TOP = 195;
  const npAngles = [-144, -72, 0, 72, 144];

  let npFaces = [];
  for (let k = 0; k < 5; k++) {
    let a1 = npAngles[k];
    let a2 = npAngles[(k + 1) % 5];
    let mid = a1 + (((a2 - a1 + 540) % 360) - 180) * 0.5;
    let vn = rotNormal(sin(mid), cos(mid), 0.1);
    npFaces.push({ a1, a2, mid, zOrder: vn.z });
  }
  npFaces.sort((a, b) => a.zOrder - b.zOrder);

  // Side walls of nozzle pentagon nut
  for (let f of npFaces) {
    if (f.zOrder < -0.2) continue;
    let col = getCadmiumColor(sin(f.mid), cos(f.mid), 0.15, 0.95);
    for (let s = 0; s <= 9; s++) {
      let t = s / 9;
      let vx = lerp(sin(f.a1) * R_NOZ_PENT, sin(f.a2) * R_NOZ_PENT, t);
      let vy = Y_NOZ + lerp(cos(f.a1) * R_NOZ_PENT, cos(f.a2) * R_NOZ_PENT, t);
      let p0 = proj(vx, vy, Z_NP_BASE);
      let p1 = proj(vx * 0.92, Y_NOZ + (vy - Y_NOZ) * 0.92, Z_NP_TOP);
      brush.set("micro_marker", col, 0.8);
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
    let e0 = proj(sin(f.a1) * R_NOZ_PENT, Y_NOZ + cos(f.a1) * R_NOZ_PENT, Z_NP_BASE);
    let e1 = proj(sin(f.a1) * R_NOZ_PENT * 0.92, Y_NOZ + cos(f.a1) * R_NOZ_PENT * 0.92, Z_NP_TOP);
    brush.set("rotring", "#1d181a", 0.6);
    brush.line(e0.x, e0.y, e1.x, e1.y);
  }

  // Front pentagonal face of nozzle nut (Z = 195)
  const R_TOP_NP = R_NOZ_PENT * 0.92;
  for (let k = 0; k < 5; k++) {
    let a1 = npAngles[k];
    let a2 = npAngles[(k + 1) % 5];
    for (let s = 0; s <= 7; s++) {
      let t = s / 7;
      let vx = lerp(sin(a1) * R_TOP_NP, sin(a2) * R_TOP_NP, t);
      let vy = Y_NOZ + lerp(cos(a1) * R_TOP_NP, cos(a2) * R_TOP_NP, t);
      let pEdge = proj(vx, vy, Z_NP_TOP);
      let pCtr = proj(0, Y_NOZ, Z_NP_TOP + 2.5);
      let col = getCadmiumColor(vx * 0.02, (vy - Y_NOZ) * 0.02, 0.98, 1.0);
      brush.set("micro_marker", col, 0.75);
      brush.line(pEdge.x, pEdge.y, pCtr.x, pCtr.y);
    }
    let p1 = proj(sin(a1) * R_TOP_NP, Y_NOZ + cos(a1) * R_TOP_NP, Z_NP_TOP);
    let p2 = proj(sin(a2) * R_TOP_NP, Y_NOZ + cos(a2) * R_TOP_NP, Z_NP_TOP);
    brush.set("rotring", "#21191b", 0.65);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Helper to draw a chunky radial wrench lug on the nozzle cap
  function drawNozzleLug(thCenter, zBack, zFront, rBase, rTip) {
    const halfAng = 9.5;
    let a1 = thCenter - halfAng;
    let a2 = thCenter + halfAng;

    // 1. Side walls (a1 and a2)
    for (let side of [-1, 1]) {
      let ang = side < 0 ? a1 : a2;
      let nx = sin(ang + side * 90);
      let ny = cos(ang + side * 90);
      let vn = rotNormal(nx, ny, 0.1);
      if (vn.z < -0.15) continue;
      let col = getCadmiumColor(nx, ny, 0.1, 0.88);
      for (let r = rBase; r <= rTip; r += 2.2) {
        let p0 = projNoz(r, ang, zBack);
        let p1 = projNoz(r, ang, zFront);
        brush.set("micro_marker", col, 0.78);
        brush.line(p0.x, p0.y, p1.x, p1.y);
      }
    }

    // 2. Outer tip face (at rTip)
    let vnTip = rotNormal(sin(thCenter), cos(thCenter), 0.1);
    if (vnTip.z > -0.25) {
      let colTip = getCadmiumColor(sin(thCenter), cos(thCenter), 0.15, 1.0);
      for (let th = a1; th <= a2; th += 2.5) {
        let p0 = projNoz(rTip, th, zBack + 1.5);
        let p1 = projNoz(rTip, th, zFront - 1.5);
        brush.set("micro_marker", colTip, 0.82);
        brush.line(p0.x, p0.y, p1.x, p1.y);
      }
    }

    // 3. Front face of lug (at zFront)
    let colFront = getCadmiumColor(sin(thCenter) * 0.25, cos(thCenter) * 0.25, 0.95, 0.96);
    for (let r = rBase; r <= rTip; r += 2.2) {
      let pA = projNoz(r, a1, zFront);
      let pB = projNoz(r, a2, zFront);
      brush.set("micro_marker", colFront, 0.8);
      brush.line(pA.x, pA.y, pB.x, pB.y);
    }

    // Crisp dark iron bevel edges on lug
    let c1 = projNoz(rTip, a1, zFront);
    let c2 = projNoz(rTip, a2, zFront);
    let c3 = projNoz(rTip, a1, zBack);
    let c4 = projNoz(rTip, a2, zBack);
    let b1 = projNoz(rBase, a1, zFront);
    let b2 = projNoz(rBase, a2, zFront);
    brush.set("rotring", "#241819", 0.55);
    brush.line(c1.x, c1.y, c2.x, c2.y);
    brush.line(b1.x, b1.y, c1.x, c1.y);
    brush.line(b2.x, b2.y, c2.x, c2.y);
    brush.line(c1.x, c1.y, c3.x, c3.y);
    brush.line(c2.x, c2.y, c4.x, c4.y);
  }

  function drawNozzleRingArc(r, z, thStart, thEnd, brushName, col, wt) {
    let pts = [];
    for (let th = thStart; th <= thEnd; th += 6) {
      let p = projNoz(r, th, z);
      if (p.y <= getSnowLineY(p.x) + 8) {
        pts.push([p.x, p.y]);
      }
    }
    brush.set(brushName, col, wt);
    safeSpline(pts, 0.4);
  }
}

// Helper for forward-facing hex bolts on the nozzle mounting flange
function drawHexBoltForward(bx, by, bz, rad, ht) {
  const hexA = [15, 75, 135, 195, 255, 315];
  for (let k = 0; k < 6; k++) {
    let a1 = hexA[k];
    let a2 = hexA[(k + 1) % 6];
    let mid = a1 + 30;
    let vn = rotNormal(sin(mid), cos(mid), 0.15);
    if (vn.z < -0.15) continue;
    let col = getCadmiumColor(sin(mid), cos(mid), 0.2, 0.9);
    for (let s = 0; s <= 3; s++) {
      let t = s / 3;
      let vx = bx + lerp(sin(a1) * rad, sin(a2) * rad, t);
      let vy = by + lerp(cos(a1) * rad, cos(a2) * rad, t);
      let p0 = proj(vx, vy, bz);
      let p1 = proj(vx, vy, bz + ht);
      brush.set("micro_marker", col, 0.68);
      brush.line(p0.x, p0.y, p1.x, p1.y);
    }
  }
  for (let k = 0; k < 6; k++) {
    let a1 = hexA[k];
    let a2 = hexA[(k + 1) % 6];
    let pC = proj(bx, by, bz + ht + 0.8);
    let p1 = proj(bx + sin(a1) * rad, by + cos(a1) * rad, bz + ht);
    let p2 = proj(bx + sin(a2) * rad, by + cos(a2) * rad, bz + ht);
    brush.set("micro_marker", "#e82212", 0.65);
    brush.line(p1.x, p1.y, pC.x, pC.y);
    brush.set("rotring", "#2b0607", 0.45);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }
}

// Heavy iron chain links dangling from bottom of nozzle cap into the snowbank
function drawNozzleChain() {
  const links = [
    { x: -2, y: -96, z: 182, rx: 6, ry: 10, rz: 3, twist: 15 },
    { x: 3, y: -110, z: 178, rx: 4, ry: 11, rz: 6, twist: -35 },
    { x: 10, y: -124, z: 172, rx: 7, ry: 10, rz: 3, twist: 20 },
    { x: 19, y: -136, z: 165, rx: 5, ry: 9, rz: 5, twist: -25 }
  ];

  for (let lk of links) {
    let ptsOuter = [];
    let ptsInner = [];
    let ptsHi = [];
    for (let a = 0; a <= 360; a += 20) {
      let lx = cos(a) * lk.rx;
      let ly = sin(a) * lk.ry;
      let lz = cos(a + lk.twist) * lk.rz;
      let p = proj(lk.x + lx, lk.y + ly, lk.z + lz);
      if (p.y < getSnowLineY(p.x) + 8) {
        ptsOuter.push([p.x, p.y]);
        let pIn = proj(lk.x + lx * 0.65, lk.y + ly * 0.65, lk.z + lz);
        ptsInner.push([pIn.x, pIn.y]);
        if (a > 100 && a < 250) ptsHi.push([p.x - 1.2, p.y - 1.2]);
      }
    }
    brush.set("micro_marker", "#630808", 0.95);
    safeSpline(ptsOuter, 0.5);
    brush.set("rotring", "#1d1416", 0.65);
    safeSpline(ptsInner, 0.5);
    brush.set("micro_marker", "#e02414", 0.65);
    safeSpline(ptsHi, 0.5);
  }
}

// ============================================================================
// 5. CLINGING ICE RIME IN CRISP WHITE PENCIL
// ============================================================================
function drawClingingIceRime() {
  const R_BARREL = 106;
  const R_FLANGE = 125;

  // Helper to draw a cluster of crystalline rime needles pointing into the wind (-158°)
  function drawRimeTuft(sx, sy, lengthScale = 1.0, density = 5) {
    // Subtle icy blue-grey base crust
    brush.set("cpencil", "#b8cbe0", 0.75);
    brush.line(sx, sy, sx - cos(WIND_ANGLE) * 6 * lengthScale, sy - sin(WIND_ANGLE) * 6 * lengthScale);

    // Crisp white pencil crystalline needles
    for (let i = 0; i < density; i++) {
      let ang = (WIND_ANGLE + 180) + random(-24, 24);
      let len = random(4, 15) * lengthScale;
      let ox = random(-2.5, 2.5);
      let oy = random(-2.5, 2.5);
      brush.set("rime_white", i % 3 === 0 ? "#eef6ff" : "#ffffff", random(0.65, 1.15));
      brush.line(sx + ox, sy + oy, sx + ox + cos(ang) * len, sy + oy + sin(ang) * len);
    }
  }

  // --- 5A. Windward Ice Rime on Dome (Cap) & Raised Ribs ---
  // Thickest on left/windward contour (deg from -112° to -25°)
  for (let y = 16; y <= 112; y += 3.2) {
    let t = (y - 15) / (114 - 15);
    let r = t < 0.28 ? map(t, 0, 0.28, 102, 95) : 33 + 62 * Math.cos(map(t, 0.28, 1, 0, 1) * (Math.PI * 0.48));
    if (Math.abs(t - 0.28) < 0.035) r += 3.8;

    // Windward edge crust
    for (let deg = -112; deg <= -18; deg += 5.5) {
      let chance = map(deg, -112, -18, 0.95, 0.2);
      if (random() < chance) {
        let p = proj(sin(deg) * (r + 1.2), y, cos(deg) * (r + 1.2));
        let scale = map(deg, -112, -18, 1.15, 0.45);
        drawRimeTuft(p.x, p.y, scale, deg < -75 ? 4 : 2);
      }
    }

    // Extra snow/ice packed onto the horizontal dome molding band (y ~ 41..47)
    if (y > 41 && y < 48) {
      for (let deg = -105; deg <= 42; deg += 4) {
        let p = proj(sin(deg) * (r + 3.5), y + 1.5, cos(deg) * (r + 3.5));
        drawRimeTuft(p.x, p.y, map(deg, -105, 42, 0.95, 0.35), 3);
      }
    }
  }

  // Rime clinging along the windward edges of the dome's raised cast ribs
  const ribAngles = [-90, -45, 0, 45];
  for (let bDeg of ribAngles) {
    for (let y = 18; y <= 110; y += 4.5) {
      let t = (y - 15) / (114 - 15);
      let r = (t < 0.28 ? map(t, 0, 0.28, 102, 95) : 33 + 62 * Math.cos(map(t, 0.28, 1, 0, 1) * (Math.PI * 0.48))) + 3.6;
      let p = proj(sin(bDeg - 3) * r, y, cos(bDeg - 3) * r);
      drawRimeTuft(p.x, p.y, bDeg < 0 ? 0.85 : 0.45, 3);
    }
  }

  // --- 5B. Packed Ice Rime on Bonnet Flange Deck & Flange Bolts ---
  for (let deg = -118; deg <= 68; deg += 2.8) {
    let r = random(101, R_FLANGE + 1.5);
    let p = proj(sin(deg) * r, 15.5, cos(deg) * r);
    let scale = map(deg, -118, 68, 1.2, 0.35);
    if (random() < map(deg, -118, 68, 0.95, 0.35)) {
      drawRimeTuft(p.x, p.y, scale, 3);
    }
  }
  // Rime hoods on the windward flange bolts
  for (let bDeg of [-90, -45, 0, 45]) {
    let p = proj(sin(bDeg) * 114, 23.5, cos(bDeg) * 114);
    drawRimeTuft(p.x, p.y, bDeg <= 0 ? 1.1 : 0.65, 6);
  }

  // --- 5C. Rime on Top Collar & Pentagonal Operating Nut ---
  for (let y = 114; y <= 151; y += 3.5) {
    for (let deg = -125; deg <= 25; deg += 9) {
      let r = y < 125 ? 36 : 25.5;
      let p = proj(sin(deg) * r, y, cos(deg) * r);
      if (random() < map(deg, -125, 25, 0.9, 0.25)) {
        drawRimeTuft(p.x, p.y, map(deg, -125, 25, 1.0, 0.4), 3);
      }
    }
  }
  // Frost cap on top of the operating nut
  for (let i = 0; i < 18; i++) {
    let a = random(-150, 60);
    let r = random(2, 24);
    let p = proj(sin(a) * r, 151.5, cos(a) * r);
    drawRimeTuft(p.x, p.y, 0.75, 3);
  }

  // --- 5D. Windward Shoulder Rime & Snow-Line Crust ---
  for (let y = -115; y <= -3; y += 4.5) {
    for (let deg = -112; deg <= -42; deg += 6) {
      let p = proj(sin(deg) * (R_BARREL + 1.5), y, cos(deg) * (R_BARREL + 1.5));
      if (p.y < getSnowLineY(p.x) && random() < map(deg, -112, -42, 0.9, 0.15)) {
        drawRimeTuft(p.x, p.y, map(deg, -112, -42, 1.1, 0.4), 3);
      }
    }
  }

  // --- 5E. Clinging Ice Rime on the Bolted Nozzle, Lugs, Nozzle Nut & Chain ---
  const Y_NOZ = -68;
  // Upper-left windward arc of nozzle mounting flange & cap
  for (let z = 96; z <= 176; z += 3.5) {
    let r = z < 115 ? 64.5 : (z < 140 ? 46.5 : 54.5);
    for (let th = -135; th <= 28; th += 7) {
      let p = proj(sin(th) * r, Y_NOZ + cos(th) * r, z);
      if (p.y < getSnowLineY(p.x) && random() < map(th, -135, 28, 0.9, 0.25)) {
        drawRimeTuft(p.x, p.y, map(th, -135, 28, 1.05, 0.4), 3);
      }
    }
  }

  // Heavy rime on the two windward nozzle wrench lugs (-130° and -42°) and top-right lug (48°)
  for (let lTh of [-130, -42, 48]) {
    for (let r = 54; r <= 70; r += 3) {
      for (let z = 145; z <= 170; z += 4) {
        let p = proj(sin(lTh - 5) * r, Y_NOZ + cos(lTh - 5) * r, z);
        drawRimeTuft(p.x, p.y, lTh < 0 ? 0.95 : 0.5, 3);
      }
    }
  }

  // Crisp frost ring inside the recessed nozzle cap face & around the central pentagon nut
  for (let th = -165; th <= 45; th += 8) {
    let pRim = proj(sin(th) * 44, Y_NOZ + cos(th) * 44, 176);
    drawRimeTuft(pRim.x, pRim.y, 0.65, 2);

    let pNut = proj(sin(th) * 20.5, Y_NOZ + cos(th) * 20.5, random(177, 195));
    drawRimeTuft(pNut.x, pNut.y, 0.75, 3);
  }

  // Rime clinging to the dangling chain links
  for (let y = -94; y >= -134; y -= 5) {
    let p = proj(map(y, -94, -134, -4, 16), y, map(y, -94, -134, 183, 166));
    if (p.y < getSnowLineY(p.x) + 4) {
      drawRimeTuft(p.x, p.y, 0.65, 3);
    }
  }

  // Fine granular frost stipple over windward cast iron
  brush.set("frost_stipple", "#ffffff", 0.85);
  for (let i = 0; i < 45; i++) {
    let y = random(-85, 135);
    let p = proj(random(-115, -15), y, random(30, 175));
    if (p.y < getSnowLineY(p.x)) {
      brush.line(p.x, p.y, p.x + cos(WIND_ANGLE) * 8, p.y + sin(WIND_ANGLE) * 8);
    }
  }
}

// ============================================================================
// 6. FOREGROUND SNOW DRIFTS & EDGE DISSOLUTION (Layered Translucent Washes)
// ============================================================================
function drawForegroundDriftsAndEdgeDissolve() {
  brush.noStroke();

  // --- 6A. Subtle Warm Cadmium Reflected Glow in the Snow Hollow Under the Nozzle ---
  brush.fill("#e05a47", 24);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.4, 0.1);
  drawTiltedCloudPoly(602, 752, 68, 24, 14, 10);
  drawTiltedCloudPoly(695, 718, 56, 20, 18, 10);

  // --- 6B. Cool Blue-Grey Snow-Drift Shadow Washes in the Wind-Scoured Hollow ---
  const shadowDrifts = [
    { cx: 615, cy: 772, rx: 115, ry: 34, ang: 16, col: "#9fb0c4", alpha: 52 },
    { cx: 745, cy: 748, rx: 135, ry: 38, ang: 22, col: "#b0bfd1", alpha: 48 },
    { cx: 510, cy: 715, rx: 110, ry: 30, ang: 20, col: "#c2cfde", alpha: 44 },
    { cx: 660, cy: 825, rx: 220, ry: 55, ang: 19, col: "#cbd6e4", alpha: 42 }
  ];

  for (let sd of shadowDrifts) {
    brush.fill(sd.col, sd.alpha);
    brush.fillBleed(0.32, "out");
    brush.fillTexture(0.45, 0.14);
    drawTiltedCloudPoly(sd.cx, sd.cy, sd.rx, sd.ry, sd.ang, 12);
  }

  // --- 6C. Main Layered Translucent Snow Drift Lapping Over the Hydrant Shoulders ---
  for (let pass = 0; pass < 3; pass++) {
    brush.fill(pass === 0 ? "#eef3f8" : "#ffffff", pass === 0 ? 115 : 155);
    brush.fillBleed(0.26, "out");
    brush.fillTexture(0.32, 0.1);

    brush.beginShape(0.35);
    for (let x = 140; x <= 1060; x += 28) {
      let sy = getSnowLineY(x) + pass * 11 + (noise(x * 0.02, pass * 5) - 0.5) * 10;
      brush.vertex(x, sy);
    }
    brush.vertex(1060, 1080);
    brush.vertex(140, 1080);
    brush.endShape(true);
  }

  // --- 6D. Outer Perimeter Whiteout Washes (Dissolving Every Detail Toward the Edges) ---
  brush.fill("#ffffff", 175);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.2, 0.05);

  const edgeClouds = [
    { cx: 600, cy: 95, rx: 580, ry: 155, ang: 4 },
    { cx: 600, cy: 1105, rx: 580, ry: 165, ang: -3 },
    { cx: 105, cy: 600, rx: 165, ry: 560, ang: 6 },
    { cx: 1095, cy: 600, rx: 175, ry: 560, ang: -5 },
    { cx: 210, cy: 210, rx: 260, ry: 210, ang: -25 },
    { cx: 990, cy: 220, rx: 260, ry: 210, ang: 25 },
    { cx: 210, cy: 990, rx: 270, ry: 220, ang: 25 },
    { cx: 990, cy: 980, rx: 280, ry: 220, ang: -25 }
  ];
  for (let ec of edgeClouds) {
    drawTiltedCloudPoly(ec.cx, ec.cy, ec.rx, ec.ry, ec.ang, 12);
  }
  brush.noFill();

  // Crisp snow-crust lip & packed snow granules right where the hydrant meets the snowbank
  for (let x = 495; x <= 785; x += 3.5) {
    let sy = getSnowLineY(x);
    let nextY = getSnowLineY(x + 10);
    // Crisp white pencil crest along the drift ridge
    brush.set("rime_white", "#ffffff", random(0.85, 1.35));
    brush.line(x, sy, x + 12, nextY + random(-2, 2));

    // Delicate blue-grey shadow line just beneath the snow lip in the nozzle hollow
    if (x > 555 && x < 655) {
      brush.set("2H", "#8596ab", 0.55);
      brush.line(x, sy + 3, x + 9, nextY + 4);
    }
  }

  // Sweeping snow-drift contour lines across the lower foreground
  brush.field("squall_flow");
  for (let i = 0; i < 95; i++) {
    let sx = random(240, 960);
    let sy = getSnowLineY(sx) + random(4, 240);
    let dEdge = Math.min(sx, 1200 - sx, 1200 - sy);
    if (dEdge < 140) continue;
    let col = random() < 0.65 ? "#ffffff" : (random() < 0.5 ? "#c5d1df" : "#a8b7c9");
    brush.set(col === "#ffffff" ? "rime_white" : "2H", col, random(0.45, 0.9));
    brush.flowLine(sx, sy, random(35, 130), WIND_ANGLE + random(-6, 6));
  }
  brush.noField();
}

// ============================================================================
// 7. WINDBLOWN PENCIL FLECKS & DRIVING SNOW STREAKS
// ============================================================================
function drawWindblownPencilFlecks() {
  brush.field("squall_flow");

  // --- 7A. Graphite & Slate Pencil Flecks Driving Diagonally Across the Squall ---
  const graphiteFlecks = [
    { br: "2H", col: "#b4c1d0", count: 420, minL: 8, maxL: 48, wt: 0.55 },
    { br: "HB", col: "#93a3b5", count: 260, minL: 5, maxL: 28, wt: 0.5 },
    { br: "cpencil", col: "#7a8b9e", count: 140, minL: 3, maxL: 16, wt: 0.45 }
  ];

  for (let gf of graphiteFlecks) {
    brush.set(gf.br, gf.col, gf.wt);
    for (let i = 0; i < gf.count; i++) {
      // Concentrate flecks toward the middle of the sheet, fading out at the margins
      let angle = random(360);
      let rad = Math.pow(random(), 0.72) * 520;
      let x = 635 + cos(angle) * rad * 1.08;
      let y = 595 + sin(angle) * rad * 0.96;

      // Avoid heavy dark graphite flecks directly over the brightest red focal highlights
      let dHyd = Math.hypot(x - (HYD_CX - 10), y - (HYD_CY - 15));
      if (dHyd < 135 && gf.col === "#7a8b9e" && random() < 0.75) continue;

      let len = random(gf.minL, gf.maxL) * map(rad, 0, 520, 1.0, 0.45);
      brush.flowLine(x, y, len, WIND_ANGLE + random(-5, 5));
    }
  }

  // --- 7B. Crisp White Pencil Snow Flecks & Driving Streaks (Especially Over & Around the Hydrant) ---
  for (let i = 0; i < 520; i++) {
    let nearHydrant = i < 210;
    let x, y;
    if (nearHydrant) {
      x = HYD_CX + random(-210, 190);
      y = HYD_CY + random(-210, 185);
    } else {
      let angle = random(360);
      let rad = Math.pow(random(), 0.8) * 510;
      x = 635 + cos(angle) * rad;
      y = 595 + sin(angle) * rad;
    }

    let len = random(3, nearHydrant ? 26 : 42);
    let wt = random(0.45, nearHydrant ? 1.05 : 0.85);
    brush.set("rime_white", i % 4 === 0 ? "#e8f2fc" : "#ffffff", wt);

    if (len < 9) {
      // Short windblown snow pellet / fleck
      let a = WIND_ANGLE + random(-8, 8);
      brush.line(x, y, x + cos(a) * len, y + sin(a) * len);
    } else {
      brush.flowLine(x, y, len, WIND_ANGLE + random(-4, 4));
    }
  }

  brush.noField();

  // --- 7C. Final Soft White Spray Veil to Dissolve the Lower/Right Shoulder & Outer Margins ---
  brush.set("squall_mist", "#ffffff", 1.55);
  // Veil overlapping the buried right shoulder & lower drift edge
  for (let i = 0; i < 28; i++) {
    let sx = random(685, 860);
    let sy = getSnowLineY(sx) + random(-35, 35);
    brush.line(sx - 45, sy - 18, sx + 45, sy + 18);
  }

  // Soft white spray around the outer border so every detail dissolves into pure white
  brush.set("squall_mist", "#ffffff", 2.1);
  for (let i = 0; i < 90; i++) {
    let a = random(360);
    let r = random(430, 620);
    let x = 600 + cos(a) * r;
    let y = 600 + sin(a) * r;
    brush.line(x - 60, y - 24, x + 60, y + 24);
  }
}

// Hyperrealistic Architectural Study: Corner of a Concrete Parking Garage
// Razor-edged marker fields, fine grit spray, pencil hairline cracks, oil-stain mottling,
// chrome yellow stall stripe, and a single safety-orange traffic cone with a reflective glint.

function lineIntersect(p1, p2, p3, p4) {
  const x1 = p1[0], y1 = p1[1], x2 = p2[0], y2 = p2[1];
  const x3 = p3[0], y3 = p3[1], x4 = p4[0], y4 = p4[1];
  const denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
  if (Math.abs(denom) < 1e-9) return [(x1 + x2) * 0.5, (y1 + y2) * 0.5];
  const t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / denom;
  return [x1 + t * (x2 - x1), y1 + t * (y2 - y1)];
}

function pointInPoly(pt, vs) {
  const x = pt[0], y = pt[1];
  let inside = false;
  for (let i = 0, j = vs.length - 1; i < vs.length; j = i++) {
    const xi = vs[i][0], yi = vs[i][1];
    const xj = vs[j][0], yj = vs[j][1];
    const intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / ((yj - yi) || 1e-9) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function lerpPt(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

function polyBounds(pts) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (let i = 0; i < pts.length; i++) {
    if (pts[i][0] < minX) minX = pts[i][0];
    if (pts[i][1] < minY) minY = pts[i][1];
    if (pts[i][0] > maxX) maxX = pts[i][0];
    if (pts[i][1] > maxY) maxY = pts[i][1];
  }
  return { minX, minY, maxX, maxY };
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Chisel-edge architectural marker with zero soft tip bleed
  brush.add("flat_marker", {
    type: "marker",
    weight: 10,
    scatter: 0.01,
    opacity: 38,
    spacing: 0.35,
    pressure: [1, 1],
    rotate: "natural",
    markerTip: false,
    noise: 0.04
  });

  // Fine mineral grit spray for poured concrete & traffic paint
  brush.add("fine_grit", {
    type: "spray",
    weight: 1.4,
    scatter: 4.2,
    opacity: 48,
    spacing: 0.9,
    pressure: [0.7, 1.2, 0.7],
    rotate: "random",
    noise: 0.25
  });

  // Razor-sharp technical pen for architectural plane seams
  brush.add("razor_pen", {
    type: "default",
    weight: 0.55,
    scatter: 0.005,
    sharpness: 0.96,
    grain: 0.12,
    opacity: 210,
    spacing: 0.12,
    pressure: [1, 1],
    noise: 0.05
  });

  // Ultra-fine graphite tip for hairline concrete fractures
  brush.add("crack_graphite", {
    type: "default",
    weight: 0.42,
    scatter: 0.02,
    sharpness: 0.88,
    grain: 0.45,
    opacity: 185,
    spacing: 0.15,
    pressure: [0.6, 1.1, 0.5],
    noise: 0.25
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#262D3B");
  brush.noField();

  // =========================================================================
  // 1. ARCHITECTURAL GEOMETRY & LIGHT/SHADOW PARTITION
  // =========================================================================
  const V_top = [370, 0];
  const V_corner = [370, 410];
  const V_leftBase = [0, 545];
  const V_rightBase = [1200, 485];

  // Main diagonal shadow edge L1 on floor & climbing up the back wall
  const S_floorLeft = [0, 910];
  const S_wallBase = lerpPt(V_corner, V_rightBase, 555 / 830); // [925, 460.15]
  const S_wallTop = [1030, 0];

  // Lower-right diagonal shadow edge L2 framing the slab of sunlight
  const S_botLeft = [790, 1200];
  const S_botRight = [1200, 995];

  // Primary Razor-Edged Architectural Polygons
  const polyLeftWall = [
    [0, 0], V_top, V_corner, V_leftBase
  ];
  const polyBackWallShadow = [
    V_top, S_wallTop, S_wallBase, V_corner
  ];
  const polyBackWallSun = [
    S_wallTop, [1200, 0], V_rightBase, S_wallBase
  ];
  const polyFloorShadowUpper = [
    V_leftBase, V_corner, S_wallBase, S_floorLeft
  ];
  const polyFloorSun = [
    S_floorLeft, S_wallBase, V_rightBase, S_botRight, S_botLeft, [0, 1200]
  ];
  const polyFloorShadowLower = [
    S_botLeft, S_botRight, [1200, 1200]
  ];

  // Cone Cast Shadow Polygon stretching across the sunlit floor and yellow stripe
  const CS_originTop = lerpPt(S_floorLeft, S_wallBase, 468 / 925); // [468, 682.4]
  const CS_baseStep1 = [538, 702];
  const CS_shaftTopStart = [516, 690];
  const CS_tipTop = [982, 728];
  const CS_tipBot = [975, 756];
  const CS_shaftBotStart = [520, 747];
  const CS_baseCornerTip = [506, 768];
  const CS_baseFront = [438, 762];
  const CS_originBot = lineIntersect([332, 718], [438, 762], S_floorLeft, S_wallBase);

  const polyConeShadow = [
    CS_originTop,
    CS_baseStep1,
    CS_shaftTopStart,
    CS_tipTop,
    CS_tipBot,
    CS_shaftBotStart,
    CS_baseCornerTip,
    CS_baseFront,
    CS_originBot
  ];

  // Chrome Yellow Parking Stall Stripe & exact shadow intersections
  const Y_topL = [764, 514];
  const Y_topR = [798, 516.8];
  const Y_botR = [606, 1200];
  const Y_botL = [554, 1200];

  const Y_L1_L = lineIntersect(Y_topL, Y_botL, S_floorLeft, S_wallBase);
  const Y_L1_R = lineIntersect(Y_topR, Y_botR, S_floorLeft, S_wallBase);

  const Y_CS_topL = lineIntersect(Y_topL, Y_botL, CS_shaftTopStart, CS_tipTop);
  const Y_CS_topR = lineIntersect(Y_topR, Y_botR, CS_shaftTopStart, CS_tipTop);

  const Y_CS_botL = lineIntersect(Y_topL, Y_botL, CS_shaftBotStart, CS_tipBot);
  const Y_CS_botR = lineIntersect(Y_topR, Y_botR, CS_shaftBotStart, CS_tipBot);

  const polyYellowShadowUpper = [Y_topL, Y_topR, Y_L1_R, Y_L1_L];
  const polyYellowSunUpper = [Y_L1_L, Y_L1_R, Y_CS_topR, Y_CS_topL];
  const polyYellowConeShadow = [Y_CS_topL, Y_CS_topR, Y_CS_botR, Y_CS_botL];
  const polyYellowSunLower = [Y_CS_botL, Y_CS_botR, Y_botR, Y_botL];
  const polyYellowFull = [Y_topL, Y_topR, Y_botR, Y_botL];

  // Helper to classify any point on the floor for lighting-accurate textures & cracks
  function getFloorZone(x, y) {
    const pt = [x, y];
    const inYellow = pointInPoly(pt, polyYellowFull);
    // Above L1?
    const yL1 = S_floorLeft[1] + (x / S_wallBase[0]) * (S_wallBase[1] - S_floorLeft[1]);
    if (y < yL1) {
      return inYellow ? "yellow_shadow" : "floor_shadow_upper";
    }
    // Below L2?
    if (x >= S_botLeft[0]) {
      const yL2 = S_botLeft[1] + ((x - S_botLeft[0]) / (S_botRight[0] - S_botLeft[0])) * (S_botRight[1] - S_botLeft[1]);
      if (y > yL2) return "floor_shadow_lower";
    }
    // Inside Cone Cast Shadow?
    if (pointInPoly(pt, polyConeShadow)) {
      return inYellow ? "yellow_shadow" : "cone_shadow";
    }
    return inYellow ? "yellow_sun" : "floor_sun";
  }

  // Helper to render a razor-edged flat marker field
  function drawMarkerField(pts, baseHex, streakHex1, streakHex2, angle, spacing) {
    const p = new brush.Polygon(pts);
    p.wash(baseHex, 255);
    brush.noWash();

    brush.hatchStyle("flat_marker", streakHex1, 1.0);
    p.hatch(spacing, angle, { rand: 0.01, continuous: true });
    brush.noHatch();

    if (streakHex2) {
      brush.hatchStyle("flat_marker", streakHex2, 0.75);
      p.hatch(spacing * 1.7, angle, { rand: 0.015, continuous: false });
      brush.noHatch();
    }
  }

  // =========================================================================
  // 2. RENDER RAZOR-EDGED FLAT MARKER FIELDS
  // =========================================================================
  // Left Wall: Deep dusky twilight slate
  drawMarkerField(polyLeftWall, "#262D3B", "#222836", "#2B3343", 90, 13);

  // Back Wall Shadow: Cool slate shadow
  drawMarkerField(polyBackWallShadow, "#343D4F", "#2F3849", "#394356", 90, 13);

  // Back Wall Sun: Warm putty grey in raking afternoon sun
  drawMarkerField(polyBackWallSun, "#C2B8AA", "#B9AFA1", "#CAC0B2", 90, 12);

  // Floor Upper Shadow: Cool slate shadow
  drawMarkerField(polyFloorShadowUpper, "#3F495C", "#3A4456", "#455064", 5.2, 12);

  // Floor Slab of Sunlight: Luminous warm putty grey
  drawMarkerField(polyFloorSun, "#D0C6B8", "#C8BEB0", "#D7CEC0", 5.2, 12);

  // Floor Lower-Right Shadow: Deep dusky twilight slate
  drawMarkerField(polyFloorShadowLower, "#303848", "#2B3342", "#353E50", 5.2, 12);

  // Cone Cast Shadow on Floor: Cool slate shadow matching the ambient light
  drawMarkerField(polyConeShadow, "#384254", "#333D4E", "#3D475A", -25.9, 9);

  // Chrome Yellow Parking Stall Line (4 razor-sharp tonal segments)
  drawMarkerField(polyYellowShadowUpper, "#7A6124", "#70581F", "#846A29", -73.4, 7);
  drawMarkerField(polyYellowSunUpper, "#EBB014", "#E0A50E", "#F4BC22", -73.4, 7);
  drawMarkerField(polyYellowConeShadow, "#715920", "#68511B", "#7B6225", -73.4, 7);
  drawMarkerField(polyYellowSunLower, "#EBB014", "#E0A50E", "#F4BC22", -73.4, 7);

  // =========================================================================
  // 3. OIL-STAIN MOTTLING, TIRE SCUFFS & CONCRETE BROOM TEXTURE
  // =========================================================================
  // Helper to build organic oil-stain mottling polygons that shift color across shadow edges
  function drawOilMottle(cx, cy, rx, ry, lobes, intensity) {
    for (let layer = 0; layer < 3; layer++) {
      const scale = 1 - layer * 0.26;
      const pts = [];
      const steps = 18;
      for (let i = 0; i < steps; i++) {
        const a = (i / steps) * 360;
        const n = noise(cx * 0.01 + cos(a) * 0.9, cy * 0.01 + sin(a) * 0.9, layer * 3.1);
        const rMod = 0.65 + 0.55 * n + 0.15 * sin(a * lobes);
        const px = cx + cos(a) * rx * scale * rMod;
        const py = cy + sin(a) * ry * scale * rMod;
        pts.push([px, py]);
      }
      const zone = getFloorZone(cx, cy);
      const isSun = (zone === "floor_sun" || zone === "yellow_sun");
      const stainHex = isSun
        ? (layer === 0 ? "#B5AA9B" : layer === 1 ? "#9C9081" : "#7D7264")
        : (layer === 0 ? "#323A4A" : layer === 1 ? "#29303E" : "#1F2531");
      const alpha = Math.round((28 + layer * 18) * intensity);

      const p = new brush.Polygon(pts);
      p.wash(stainHex, alpha);
      brush.noWash();
    }

    // Micro-stippled oil ring and dark carbon specks inside the mottle
    const dotCount = Math.floor(rx * ry * 0.055 * intensity);
    for (let i = 0; i < dotCount; i++) {
      const a = random(360);
      const d = pow(random(), 0.65);
      const px = cx + cos(a) * rx * d;
      const py = cy + sin(a) * ry * d;
      const zone = getFloorZone(px, py);
      const isSun = (zone === "floor_sun" || zone === "yellow_sun");
      const speckCol = isSun
        ? (random() < 0.5 ? "#6E6356" : "#8F8374")
        : (random() < 0.5 ? "#1A202B" : "#283040");
      brush.set("2B", speckCol, random(0.3, 0.7));
      const len = random(1.5, 4.5);
      brush.line(px, py, px + len, py + len * 0.15);
    }
  }

  // Oil-stain clusters in the parking bay (some straddling the shadow line!)
  drawOilMottle(875, 835, 115, 42, 3, 1.0);   // Main crankcase drip in sunlit stall
  drawOilMottle(955, 875, 58, 22, 4, 0.9);    // Secondary oil spot
  drawOilMottle(795, 790, 44, 17, 2, 0.75);   // Smaller drip near cone shadow tip
  drawOilMottle(612, 616, 72, 26, 3, 0.85);   // Oil patch straddling L1 shadow boundary
  drawOilMottle(585, 602, 45, 16, 3, 0.85);   // Upper lobe of straddling oil patch in shadow
  drawOilMottle(265, 975, 85, 30, 3, 0.7);    // Older weathered stain in left foreground sun
  drawOilMottle(310, 625, 68, 24, 2, 0.65);   // Weathered stain in upper floor shadow
  drawOilMottle(995, 575, 62, 20, 3, 0.7);    // Stain near upper right sunlit floor

  // Faint rubber tire-scuff tracks curving into the parking stall across light & shadow
  for (let track = 0; track < 2; track++) {
    const baseX = track === 0 ? 410 : 920;
    for (let s = 0; s < 38; s++) {
      const t = s / 38;
      const y = 520 + t * 650;
      const x = baseX - t * 145 + sin(t * 95) * 18 + random(-9, 9);
      const zone = getFloorZone(x, y);
      if (zone === "yellow_sun" || zone === "yellow_shadow") continue;
      const isSun = (zone === "floor_sun");
      const scuffCol = isSun ? "#B8AEA0" : "#343D4E";
      brush.set("HB", scuffCol, random(0.35, 0.65));
      brush.line(x, y, x - 5, y + 18);
    }
  }

  // Subtle horizontal broom-finish striations on the concrete floor slab
  for (let i = 0; i < 240; i++) {
    const x1 = random(15, 1160);
    const y1 = random(440, 1190);
    const len = random(28, 95);
    const dx = cos(5.2) * len;
    const dy = sin(5.2) * len;
    const x2 = x1 + dx;
    const y2 = y1 + dy;

    const z1 = getFloorZone(x1, y1);
    const z2 = getFloorZone(x2, y2);
    if (z1 !== z2) continue; // Keep broom strokes strictly inside their razor-edged field

    let col;
    if (z1 === "floor_sun") col = random() < 0.5 ? "#C2B8AA" : "#DCD3C6";
    else if (z1 === "floor_shadow_upper") col = random() < 0.5 ? "#363F50" : "#495469";
    else if (z1 === "floor_shadow_lower") col = random() < 0.5 ? "#28303E" : "#394355";
    else if (z1 === "cone_shadow") col = random() < 0.5 ? "#303949" : "#424D61";
    else if (z1 === "yellow_sun") col = random() < 0.5 ? "#D99E0B" : "#F7C636";
    else col = random() < 0.5 ? "#69521C" : "#8A6F2C";

    brush.set("2H", col, random(0.28, 0.52));
    brush.line(x1, y1, x2, y2);
  }

  // =========================================================================
  // 4. FAINT FINE SPRAY OF GRIT INSIDE EACH FIELD
  // =========================================================================
  function sprayFieldGrit(pts, darkHex, lightHex, density, angle) {
    const b = polyBounds(pts);
    const area = (b.maxX - b.minX) * (b.maxY - b.minY);
    const count = Math.floor((area / 2200) * density);

    for (let i = 0; i < count; i++) {
      const px = random(b.minX + 6, b.maxX - 6);
      const py = random(b.minY + 6, b.maxY - 6);
      const len = random(14, 42);
      const ex = px + cos(angle) * len;
      const ey = py + sin(angle) * len;
      if (!pointInPoly([px, py], pts) || !pointInPoly([ex, ey], pts)) continue;

      const col = random() < 0.58 ? darkHex : lightHex;
      brush.set("fine_grit", col, random(0.45, 0.95));
      brush.line(px, py, ex, ey);
    }

    // Crisp mineral aggregate specks (quartz & basalt flecks)
    const speckCount = Math.floor((area / 1400) * density);
    for (let i = 0; i < speckCount; i++) {
      const px = random(b.minX + 3, b.maxX - 3);
      const py = random(b.minY + 3, b.maxY - 3);
      if (!pointInPoly([px, py], pts)) continue;
      const col = random() < 0.62 ? darkHex : lightHex;
      brush.set("2H", col, random(0.25, 0.58));
      const sl = random(1.0, 2.8);
      brush.line(px, py, px + sl, py + sl * 0.3);
    }
  }

  sprayFieldGrit(polyLeftWall, "#1B212C", "#353E52", 1.1, -20);
  sprayFieldGrit(polyBackWallShadow, "#262E3D", "#444F65", 1.1, 5);
  sprayFieldGrit(polyBackWallSun, "#9E9486", "#DED6C9", 1.3, 5);
  sprayFieldGrit(polyFloorShadowUpper, "#2E3646", "#505C73", 1.2, 5);
  sprayFieldGrit(polyFloorSun, "#A89E90", "#EAE2D6", 1.35, 5);
  sprayFieldGrit(polyFloorShadowLower, "#222836", "#404A5E", 1.1, 5);
  sprayFieldGrit(polyConeShadow, "#293140", "#4A556B", 1.5, -25);
  sprayFieldGrit(polyYellowShadowUpper, "#594617", "#967932", 1.6, -73);
  sprayFieldGrit(polyYellowSunUpper, "#C48A06", "#FFE066", 1.8, -73);
  sprayFieldGrit(polyYellowConeShadow, "#524014", "#8C702C", 1.6, -73);
  sprayFieldGrit(polyYellowSunLower, "#C48A06", "#FFE066", 1.8, -73);

  // =========================================================================
  // 5. ARCHITECTURAL FORMWORK SEAMS, TIE-HOLES & SAW-CUT JOINTS
  // =========================================================================
  // Left Wall horizontal formwork seams
  const lwSeam1 = [[0, 365], [370, 230]];
  const lwSeam2 = [[0, 185], [370, 50]];
  for (const seam of [lwSeam1, lwSeam2]) {
    brush.set("crack_graphite", "#1A202B", 0.7);
    brush.line(seam[0][0], seam[0][1], seam[1][0], seam[1][1]);
    brush.set("2H", "#333C4E", 0.35);
    brush.line(seam[0][0], seam[0][1] + 1.5, seam[1][0], seam[1][1] + 1.5);
  }
  // Left Wall vertical formwork seam
  brush.set("crack_graphite", "#1A202B", 0.65);
  brush.line(150, 0, 150, 490.3);

  // Back Wall horizontal formwork seams (splitting at the shadow boundary!)
  const bwSeam1End = [1200, 305];
  const bwSeam2End = [1200, 125];
  const bwSeam1Split = lineIntersect([370, 230], bwSeam1End, S_wallBase, S_wallTop);
  const bwSeam2Split = lineIntersect([370, 50], bwSeam2End, S_wallBase, S_wallTop);

  for (const [start, split, end] of [
    [[370, 230], bwSeam1Split, bwSeam1End],
    [[370, 50], bwSeam2Split, bwSeam2End]
  ]) {
    // Shadow portion
    brush.set("crack_graphite", "#232A38", 0.7);
    brush.line(start[0], start[1], split[0], split[1]);
    brush.set("2H", "#434E63", 0.35);
    brush.line(start[0], start[1] + 1.5, split[0], split[1] + 1.5);
    // Sunlit portion
    brush.set("crack_graphite", "#8C8275", 0.75);
    brush.line(split[0], split[1], end[0], end[1]);
    brush.set("2H", "#E3DBD0", 0.45);
    brush.line(split[0], split[1] + 1.5, end[0], end[1] + 1.5);
  }

  // Back Wall vertical formwork seams at x = 650 and x = 930
  brush.set("crack_graphite", "#232A38", 0.65);
  brush.line(650, 0, 650, 435.3);

  // At x = 960, the vertical seam crosses from shadow into sun!
  const vSeamSplitY = 460.15 + ((960 - 925) / (1030 - 925)) * (0 - 460.15);
  const vSeamBaseY = 410 + ((960 - 370) / 830) * 75;
  brush.set("crack_graphite", "#232A38", 0.65);
  brush.line(960, 0, 960, vSeamSplitY);
  brush.set("crack_graphite", "#8C8275", 0.65);
  brush.line(960, vSeamSplitY, 960, vSeamBaseY);

  // Concrete formwork snap-tie holes on the walls
  function drawTieHole(x, y, inSun) {
    const holeCol = inSun ? "#6E655A" : "#181E28";
    const rimCol = inSun ? "#E3DBD0" : "#444F65";
    brush.set("razor_pen", holeCol, 0.9);
    brush.circle(x, y, 2.8, 0.15);
    brush.set("2H", rimCol, 0.4);
    brush.arc(x, y, 3.6, -40, 140);
  }

  // Left Wall tie holes
  for (const [tx, ty] of [
    [120, 165], [180, 143], [340, 85],
    [120, 345], [180, 323], [340, 265],
    [120, 468], [180, 446], [340, 388]
  ]) {
    drawTieHole(tx, ty, false);
  }

  // Back Wall tie holes
  for (const [tx, ty] of [
    [400, 82], [620, 102], [680, 107], [930, 130], [990, 135], [1165, 151],
    [400, 202], [620, 222], [680, 227], [930, 250], [990, 255], [1165, 271],
    [400, 262], [620, 282], [680, 287], [930, 310], [990, 315], [1165, 331],
    [400, 382], [620, 402], [680, 407], [930, 430], [990, 435], [1165, 451]
  ]) {
    const wallSplitX = S_wallBase[0] + (ty / S_wallBase[1]) * (S_wallTop[0] - S_wallBase[0]);
    const inSun = tx > (S_wallTop[0] + (ty / S_wallBase[1]) * (S_wallBase[0] - S_wallTop[0]));
    drawTieHole(tx, ty, inSun);
  }

  // Saw-cut control joints on the concrete floor slab (segmented by light zone!)
  function drawFloorSawJoint(pA, pB, steps) {
    for (let i = 0; i < steps; i++) {
      const t1 = i / steps;
      const t2 = (i + 1) / steps;
      const a = lerpPt(pA, pB, t1);
      const b = lerpPt(pA, pB, t2);
      const mid = lerpPt(a, b, 0.5);
      const zone = getFloorZone(mid[0], mid[1]);

      let darkCol, lightCol;
      if (zone === "floor_sun") {
        darkCol = "#595046";
        lightCol = "#EBE3D7";
      } else if (zone === "yellow_sun") {
        darkCol = "#8F6505";
        lightCol = "#FFF0A6";
      } else if (zone === "yellow_shadow") {
        darkCol = "#3E2F0B";
        lightCol = "#947833";
      } else {
        darkCol = "#1C2330";
        lightCol = "#4F5B72";
      }

      brush.set("razor_pen", darkCol, 0.85);
      brush.line(a[0], a[1], b[0], b[1]);
      brush.set("2H", lightCol, 0.45);
      brush.line(a[0] + 1.2, a[1] + 1.2, b[0] + 1.2, b[1] + 1.2);
    }
  }

  // Control Joint 1: From the re-entrant wall corner [370, 410] out to [105, 1200]
  drawFloorSawJoint(V_corner, [105, 1200], 90);
  // Control Joint 2: Transverse joint on right side of bay [1095, 475.5] to [955, 1200]
  drawFloorSawJoint([1095, 475.5], [955, 1200], 80);
  // Control Joint 3: Longitudinal joint parallel to back wall across the slab & yellow line
  const cjLongStart = lerpPt(V_corner, [105, 1200], 0.48); // [242.8, 789.2]
  const cjLongEnd = [1200, 882];
  drawFloorSawJoint(cjLongStart, cjLongEnd, 110);

  // =========================================================================
  // 6. PENCIL-DRAWN HAIRLINE CRACKS
  // =========================================================================
  function drawConcreteCrack(startPt, initAngle, totalSteps, stepLen, forkChance, isWall) {
    let cx = startPt[0];
    let cy = startPt[1];
    let ang = initAngle;

    for (let i = 0; i < totalSteps; i++) {
      const n = noise(cx * 0.018, cy * 0.018, i * 0.07);
      ang += map(n, 0, 1, -16, 16) + random(-7, 7);
      const nx = cx + cos(ang) * stepLen;
      const ny = cy + sin(ang) * stepLen;

      if (nx < 2 || nx > 1198 || ny < 2 || ny > 1198) break;

      let darkCol, edgeCol, weightMod;
      if (isWall) {
        if (ny > 410 + ((nx - 370) / 830) * 75 && nx >= 370) break;
        if (nx < 370 && ny > 545 - (nx / 370) * 135) break;
        const wallSplitX = S_wallTop[0] + (ny / S_wallBase[1]) * (S_wallBase[0] - S_wallTop[0]);
        const inSun = nx > wallSplitX && nx > 370;
        darkCol = inSun ? "#5C5349" : "#181E2A";
        edgeCol = inSun ? "#E8E0D4" : "#465268";
      } else {
        if (nx <= 370 && ny < 545 - (nx / 370) * 135) break;
        if (nx > 370 && ny < 410 + ((nx - 370) / 830) * 75) break;
        const zone = getFloorZone((cx + nx) * 0.5, (cy + ny) * 0.5);
        if (zone === "floor_sun") {
          darkCol = "#4A4239";
          edgeCol = "#EFE7DC";
        } else if (zone === "yellow_sun") {
          darkCol = "#6B4B04";
          edgeCol = "#FFF2B2";
        } else if (zone === "yellow_shadow") {
          darkCol = "#332608";
          edgeCol = "#967A34";
        } else {
          darkCol = "#181E2B";
          edgeCol = "#4F5C73";
        }
      }

      const taper = 1 - (i / totalSteps) * 0.65;
      weightMod = random(0.45, 0.95) * taper;

      // Primary pencil fracture line
      brush.set("crack_graphite", darkCol, weightMod);
      brush.line(cx, cy, nx, ny);

      // Sun-catching micro-lip along one side of the crack
      if (random() < 0.78) {
        brush.set("2H", edgeCol, weightMod * 0.55);
        brush.line(cx + 1.1, cy + 0.9, nx + 1.1, ny + 0.9);
      }

      // Tiny spalled concrete crumb at sharp crack inflections
      if (random() < 0.14) {
        brush.set("2B", darkCol, weightMod * 1.1);
        brush.line(cx - 1.2, cy + 0.8, cx + 1.2, cy - 0.8);
      }

      // Secondary branching hairline fracture
      if (forkChance > 0 && i > 6 && i < totalSteps - 8 && random() < forkChance) {
        const branchAngle = ang + (random() < 0.5 ? random(24, 48) : random(-48, -24));
        drawConcreteCrack([nx, ny], branchAngle, Math.floor((totalSteps - i) * 0.52), stepLen * 0.82, 0, isWall);
      }

      cx = nx;
      cy = ny;
    }
  }

  // Floor Crack 1: Originating near the re-entrant wall corner, crossing L1 into sun
  drawConcreteCrack([370, 412], 82, 72, 6.2, 0.07, false);
  // Floor Crack 2: Branching from the longitudinal saw-cut joint across the yellow stripe & cone shadow
  drawConcreteCrack([715, 835], -68, 52, 5.8, 0.08, false);
  drawConcreteCrack([715, 835], 112, 48, 5.8, 0.07, false);
  // Floor Crack 3: Crossing the main diagonal shadow edge L1 on the right side
  drawConcreteCrack([830, 506], 124, 58, 5.5, 0.07, false);
  // Floor Crack 4: Foreground left sunlit slab crack
  drawConcreteCrack([196, 945], 22, 46, 5.5, 0.06, false);
  // Floor Crack 5: Crossing lower-right shadow edge L2
  drawConcreteCrack([895, 1085], 58, 34, 5.2, 0.06, false);
  // Wall Crack 1: Descending the shadowed Back Wall
  drawConcreteCrack([535, 185], 93, 42, 5.4, 0.06, true);
  // Wall Crack 2: Crossing the Back Wall shadow edge into the sunlit wall!
  drawConcreteCrack([940, 145], 38, 38, 5.2, 0.06, true);
  // Wall Crack 3: Left Wall settling crack near base corner
  drawConcreteCrack([368, 315], 158, 36, 5.2, 0.05, true);

  // =========================================================================
  // 7. RAZOR-SHARP ARCHITECTURAL EDGE REINFORCEMENT
  // =========================================================================
  // Ensure every single plane junction is surgical and un-softened
  // Vertical wall corner
  brush.set("razor_pen", "#1B212D", 1.15);
  brush.line(V_top[0], V_top[1], V_corner[0], V_corner[1]);

  // Left wall base joint
  brush.set("razor_pen", "#1A202C", 1.25);
  brush.line(V_leftBase[0], V_leftBase[1], V_corner[0], V_corner[1]);

  // Back wall base joint (shadow segment & sunlit segment)
  brush.set("razor_pen", "#212836", 1.2);
  brush.line(V_corner[0], V_corner[1], S_wallBase[0], S_wallBase[1]);
  brush.set("razor_pen", "#786E62", 1.15);
  brush.line(S_wallBase[0], S_wallBase[1], V_rightBase[0], V_rightBase[1]);

  // Main diagonal shadow edge L1 on floor & Back Wall
  brush.set("razor_pen", "#353E50", 0.95);
  brush.line(S_floorLeft[0], S_floorLeft[1], S_wallBase[0], S_wallBase[1]);
  brush.set("razor_pen", "#2E3647", 0.9);
  brush.line(S_wallBase[0], S_wallBase[1], S_wallTop[0], S_wallTop[1]);

  // Lower-right shadow edge L2
  brush.set("razor_pen", "#2D3545", 0.95);
  brush.line(S_botLeft[0], S_botLeft[1], S_botRight[0], S_botRight[1]);

  // Cone cast shadow razor-sharp perimeter
  brush.set("razor_pen", "#333D4E", 0.85);
  for (let i = 0; i < polyConeShadow.length; i++) {
    const a = polyConeShadow[i];
    const b = polyConeShadow[(i + 1) % polyConeShadow.length];
    brush.line(a[0], a[1], b[0], b[1]);
  }

  // Chrome yellow paint stripe crisp edges & subtle chipped concrete flecks
  function outlinePoly(pts, hex, w) {
    brush.set("razor_pen", hex, w);
    for (let i = 0; i < pts.length; i++) {
      const a = pts[i];
      const b = pts[(i + 1) % pts.length];
      brush.line(a[0], a[1], b[0], b[1]);
    }
  }
  outlinePoly(polyYellowShadowUpper, "#634E1B", 0.8);
  outlinePoly(polyYellowSunUpper, "#C99208", 0.85);
  outlinePoly(polyYellowConeShadow, "#5C4818", 0.85);
  outlinePoly(polyYellowSunLower, "#C99208", 0.85);

  // Subtle sunlit paint thickness catch-edge along the left edge of the yellow stripe
  brush.set("2H", "#FFE680", 0.55);
  brush.line(Y_L1_L[0] - 0.8, Y_L1_L[1], Y_CS_topL[0] - 0.8, Y_CS_topL[1]);
  brush.line(Y_CS_botL[0] - 0.8, Y_CS_botL[1], Y_botL[0] - 0.8, Y_botL[1]);

  // =========================================================================
  // 8. THE SINGLE SAFETY-ORANGE TRAFFIC CONE & REFLECTIVE COLLAR GLINT
  // =========================================================================
  // Cone stands at [435, 700] where the slab of sunlight meets the hard diagonal shadow L1.

  // --- 8A. Square Weighted Base (Split across the diagonal shadow L1!) ---
  const B_L = [332, 718]; // Left corner (in shadow)
  const B_B = [432, 662]; // Back corner (in shadow)
  const B_R = [538, 702]; // Right corner (in sunlight)
  const B_F = [438, 762]; // Front corner (in sunlight)

  const B_splitFront = lineIntersect(B_L, B_F, S_floorLeft, S_wallBase);
  const B_splitBack = lineIntersect(B_B, B_R, S_floorLeft, S_wallBase);

  const baseThickness = 13;
  const B_L_bot = [B_L[0], B_L[1] + baseThickness];
  const B_F_bot = [B_F[0], B_F[1] + baseThickness];
  const B_R_bot = [B_R[0], B_R[1] + baseThickness];
  const B_splitFront_bot = [B_splitFront[0], B_splitFront[1] + baseThickness];

  // Contact occlusion crease beneath the rubber base
  brush.set("razor_pen", "#141821", 1.6);
  brush.line(B_L_bot[0], B_L_bot[1] + 1, B_F_bot[0], B_F_bot[1] + 1);
  brush.line(B_F_bot[0], B_F_bot[1] + 1, B_R_bot[0], B_R_bot[1] + 1);

  // Base vertical skirt: Left-Front face (Shadow segment & Sunlit segment)
  const polyBaseSkirtLeftShadow = [B_L, B_splitFront, B_splitFront_bot, B_L_bot];
  const polyBaseSkirtLeftSun = [B_splitFront, B_F, B_F_bot, B_splitFront_bot];
  const polyBaseSkirtRight = [B_F, B_R, B_R_bot, B_F_bot];

  drawMarkerField(polyBaseSkirtLeftShadow, "#5E2118", "#521C14", "#6B261C", 23, 4);
  drawMarkerField(polyBaseSkirtLeftSun, "#E64610", "#D63E0B", "#F2521B", 23, 4);
  drawMarkerField(polyBaseSkirtRight, "#7D261C", "#6E2017", "#8A2B20", -30, 4);

  // Base top deck: Split razor-sharply along L1 between cool shadow & warm sun
  const polyBaseTopShadow = [B_L, B_B, B_splitBack, B_splitFront];
  const polyBaseTopSun = [B_splitFront, B_splitBack, B_R, B_F];

  drawMarkerField(polyBaseTopShadow, "#6E261B", "#612016", "#7A2B1F", -28, 5);
  drawMarkerField(polyBaseTopSun, "#F24E13", "#E3440C", "#FC5B1F", -28, 5);

  // Molded octagonal inner base collar (stepped up 7px under the cone frustum)
  const octPtsTop = [];
  const octPtsBot = [];
  const octCx = 435, octCy = 702;
  for (let i = 0; i < 8; i++) {
    const a = i * 45 + 22.5;
    const ox = octCx + cos(a) * 76;
    const oy = octCy + sin(a) * 28;
    octPtsBot.push([ox, oy]);
    octPtsTop.push([ox, oy - 7]);
  }
  // Draw front visible facets of the octagonal flange
  for (let i = 0; i < 4; i++) {
    const fPoly = [octPtsTop[i], octPtsTop[i + 1], octPtsBot[i + 1], octPtsBot[i]];
    const col = i === 0 ? "#85291E" : i === 1 ? "#B83412" : i === 2 ? "#F24D13" : "#FF6226";
    drawMarkerField(fPoly, col, col, null, 0, 3.5);
  }
  drawMarkerField(octPtsTop, "#DF420D", "#D13B09", "#EB4B14", 0, 4);

  // Fine concrete dust & grit on the cone base
  sprayFieldGrit(polyBaseTopShadow, "#4A1810", "#8C3B2B", 1.8, -25);
  sprayFieldGrit(polyBaseTopSun, "#B83509", "#FF8852", 1.8, -25);

  // Crisp bevel highlights & edges on the cone base
  outlinePoly(polyBaseTopShadow, "#4D1A12", 0.8);
  outlinePoly(polyBaseTopSun, "#B83509", 0.8);
  outlinePoly(polyBaseSkirtLeftShadow, "#3D140E", 0.8);
  outlinePoly(polyBaseSkirtLeftSun, "#B03208", 0.8);
  outlinePoly(polyBaseSkirtRight, "#4F1710", 0.8);

  // Sunlit top bevel highlight on the front-left base edge
  brush.set("razor_pen", "#FF9159", 0.9);
  brush.line(B_splitFront[0], B_splitFront[1], B_F[0], B_F[1]);
  brush.set("razor_pen", "#8C3527", 0.75);
  brush.line(B_L[0], B_L[1], B_splitFront[0], B_splitFront[1]);

  // --- 8B. Conical Body & Reflective Collar Parametric Geometry ---
  const coneCx = 435;
  const coneBotY = 695, coneRxBot = 66, coneRyBot = 21.5;
  const coneTopY = 345, coneRxTop = 18.5, coneRyTop = 5.2;

  // Parametric point on the front face of the cone:
  // v in [0, 1] from top (0) to bottom (1)
  // u in [0, 1] from left silhouette (0) to right silhouette (1)
  function conePt(u, v) {
    const cy = coneTopY + v * (coneBotY - coneTopY);
    const rx = coneRxTop + v * (coneRxBot - coneRxTop);
    const ry = coneRyTop + v * (coneRyBot - coneRyTop);
    const theta = 180 - u * 180; // 180 deg (left) -> 90 deg (front) -> 0 deg (right)
    const x = coneCx + cos(theta) * rx;
    const y = cy + sin(theta) * ry;
    return [x, y];
  }

  function buildConeBandPoly(u1, u2, v1, v2) {
    const pts = [];
    const uSteps = 7;
    for (let i = 0; i <= uSteps; i++) {
      const u = u1 + (i / uSteps) * (u2 - u1);
      pts.push(conePt(u, v1));
    }
    for (let i = uSteps; i >= 0; i--) {
      const u = u1 + (i / uSteps) * (u2 - u1);
      pts.push(conePt(u, v2));
    }
    return pts;
  }

  // Collar vertical span (single wide 3M reflective collar)
  const vCollarTop = 0.165;
  const vCollarBot = 0.425;

  // 5 Razor-Edged Longitudinal Marker Bands for the Vivid Safety-Orange Body
  const orangeBands = [
    { u1: 0.00, u2: 0.13, base: "#FF6B2B", s1: "#F55E1E", s2: "#FF7B40" }, // Grazing sunlit left rim
    { u1: 0.13, u2: 0.45, base: "#F74F12", s1: "#EB450B", s2: "#FF5C21" }, // Primary vivid safety orange
    { u1: 0.45, u2: 0.64, base: "#D6380A", s1: "#C73106", s2: "#E34112" }, // Core transition tangelo
    { u1: 0.64, u2: 0.88, base: "#87271D", s1: "#7A2219", s2: "#942D22" }, // Dusky twilight shadow facet
    { u1: 0.88, u2: 1.00, base: "#A63822", s1: "#96311D", s2: "#B54028" }  // Reflected putty bounce rim
  ];

  // Render Upper & Lower Safety-Orange Sections
  for (const band of orangeBands) {
    const uMid = (band.u1 + band.u2) * 0.5;
    const pTop = conePt(uMid, 0);
    const pBot = conePt(uMid, 1);
    const genAngle = atan2(pBot[1] - pTop[1], pBot[0] - pTop[0]);

    // Upper orange cone body (above collar)
    const polyUpper = buildConeBandPoly(band.u1, band.u2, 0.0, vCollarTop);
    drawMarkerField(polyUpper, band.base, band.s1, band.s2, genAngle, 4.2);
    sprayFieldGrit(polyUpper, band.s1, band.s2, 1.5, genAngle);

    // Lower orange cone body (below collar)
    const polyLower = buildConeBandPoly(band.u1, band.u2, vCollarBot, 1.0);
    drawMarkerField(polyLower, band.base, band.s1, band.s2, genAngle, 5.0);
    sprayFieldGrit(polyLower, band.s1, band.s2, 1.6, genAngle);
  }

  // Lower-left diagonal shadow clip on the cone's bottom-left hip where L1 touches the skirt
  const clipP1 = conePt(0.0, 0.82);
  const clipP2 = conePt(0.0, 1.0);
  const clipP3 = conePt(0.13, 1.0);
  const clipP4 = conePt(0.27, 1.0);
  const polyConeHipShadow1 = [clipP1, conePt(0.13, 0.88), clipP3, clipP2];
  const polyConeHipShadow2 = [conePt(0.13, 0.88), clipP4, clipP3];
  drawMarkerField(polyConeHipShadow1, "#7A241A", "#6B1F16", null, 80, 3.5);
  drawMarkerField(polyConeHipShadow2, "#691E16", "#5C1912", null, 80, 3.5);
  brush.set("razor_pen", "#591A12", 0.75);
  brush.line(clipP1[0], clipP1[1], clipP4[0], clipP4[1]);

  // --- 8C. The Reflective Collar (The Only Glint!) ---
  const collarBands = [
    { u1: 0.00, u2: 0.11, base: "#CFD7E3", s1: "#C2CBD9", s2: "#DCE3EE" }, // Left edge silver
    { u1: 0.11, u2: 0.21, base: "#ECF1F8", s1: "#E1E8F2", s2: "#F5F8FC" }, // Pre-glint pearl
    { u1: 0.21, u2: 0.36, base: "#FFFFFF", s1: "#FFFFFF", s2: "#F7FAFF" }, // THE BLINDING GLINT
    { u1: 0.36, u2: 0.50, base: "#C7D0DE", s1: "#BAC4D4", s2: "#D4DCE8" }, // Mid cool silver
    { u1: 0.50, u2: 0.64, base: "#939FB2", s1: "#8793A6", s2: "#A0ACBF" }, // Terminator silver-slate
    { u1: 0.64, u2: 0.88, base: "#6E7A8F", s1: "#636E82", s2: "#79869C" }, // Twilight shadow slate-silver
    { u1: 0.88, u2: 1.00, base: "#8C898B", s1: "#807D7F", s2: "#999597" }  // Warm putty bounce on right rim
  ];

  for (const band of collarBands) {
    const uMid = (band.u1 + band.u2) * 0.5;
    const pTop = conePt(uMid, vCollarTop);
    const pBot = conePt(uMid, vCollarBot);
    const genAngle = atan2(pBot[1] - pTop[1], pBot[0] - pTop[0]);

    const polyCollar = buildConeBandPoly(band.u1, band.u2, vCollarTop, vCollarBot);
    drawMarkerField(polyCollar, band.base, band.s1, band.s2, genAngle, 3.6);
  }

  // Extra pure white optical glint core inside the reflective collar
  const polyGlintCore = buildConeBandPoly(0.235, 0.325, vCollarTop + 0.004, vCollarBot - 0.004);
  const pGlint = new brush.Polygon(polyGlintCore);
  pGlint.wash("#FFFFFF", 255);
  brush.noWash();

  // Retroreflective 3M diamond-grade micro-prismatic lattice inside the collar
  for (let i = 0; i <= 16; i++) {
    const t = i / 16;
    const uA = t * 0.82;
    const uB = Math.min(1.0, uA + 0.18);
    const p1 = conePt(uA, vCollarTop);
    const p2 = conePt(uB, vCollarBot);
    const inGlint = (uA > 0.18 && uA < 0.36);
    const latticeCol = inGlint ? "#E3ECF7" : (uA < 0.5 ? "#B0BCCC" : "#5B667A");
    brush.set("2H", latticeCol, 0.32);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    const p3 = conePt(uB, vCollarTop);
    const p4 = conePt(uA, vCollarBot);
    brush.line(p3[0], p3[1], p4[0], p4[1]);
  }

  // Incandescent white vertical glint strokes & specular rim on the collar
  for (let i = 0; i < 9; i++) {
    const u = map(i, 0, 8, 0.22, 0.34);
    const p1 = conePt(u, vCollarTop + 0.005);
    const p2 = conePt(u, vCollarBot - 0.005);
    brush.set("razor_pen", "#FFFFFF", 0.95);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Crisp top & bottom sleeve edges of the reflective collar
  const collarSteps = 28;
  for (let i = 0; i < collarSteps; i++) {
    const u1 = i / collarSteps;
    const u2 = (i + 1) / collarSteps;
    const topA = conePt(u1, vCollarTop);
    const topB = conePt(u2, vCollarTop);
    const botA = conePt(u1, vCollarBot);
    const botB = conePt(u2, vCollarBot);

    const isGlint = u1 >= 0.15 && u1 <= 0.42;
    const isShadow = u1 >= 0.55;
    const topEdgeCol = isGlint ? "#FFFFFF" : isShadow ? "#4D5769" : "#9BA6B8";
    const botEdgeCol = isGlint ? "#BDC8D9" : isShadow ? "#421B18" : "#8F2D0B";

    brush.set("razor_pen", topEdgeCol, isGlint ? 1.0 : 0.75);
    brush.line(topA[0], topA[1], topB[0], topB[1]);

    brush.set("razor_pen", botEdgeCol, 0.8);
    brush.line(botA[0], botA[1], botB[0], botB[1]);
  }

  // Subtle industrial wear on the cone: vertical PVC mold seam & tiny dark scuffs
  for (let s = 0; s < 22; s++) {
    const u = random(0.08, 0.92);
    const v = random(0.05, 0.95);
    if (v > vCollarTop - 0.02 && v < vCollarBot + 0.02) {
      // Tiny scuff on reflective collar
      if (u > 0.20 && u < 0.37) continue; // Keep the main glint pristine
      const pt = conePt(u, v);
      brush.set("2H", u < 0.5 ? "#8C96A6" : "#4E5768", 0.4);
      brush.line(pt[0], pt[1], pt[0] + random(-4, 4), pt[1] + random(-1.5, 1.5));
    } else {
      // Tiny rubber/asphalt scuff mark on the orange PVC body
      const pt = conePt(u, v);
      const scuffCol = u < 0.5 ? "#B8340A" : "#591A14";
      brush.set("HB", scuffCol, random(0.35, 0.6));
      brush.line(pt[0], pt[1], pt[0] + random(-5, 5), pt[1] + random(-2, 2));
    }
  }

  // --- 8D. Top Elliptical Lip & Hollow Inner Ring of the Cone ---
  const topLipOuter = [];
  const topLipInner = [];
  for (let i = 0; i < 24; i++) {
    const a = (i / 24) * 360;
    topLipOuter.push([coneCx + cos(a) * coneRxTop, coneTopY + sin(a) * coneRyTop]);
    topLipInner.push([coneCx + cos(a) * (coneRxTop * 0.64), coneTopY + sin(a) * (coneRyTop * 0.64)]);
  }
  drawMarkerField(topLipOuter, "#FF6624", "#EB5617", null, 0, 2.5);

  // Split inner hollow opening: left inner wall in shadow, right inner wall catching sun
  const innerLeftShadow = [];
  const innerRightSun = [];
  for (let i = 0; i <= 12; i++) {
    const a = 90 + (i / 12) * 180;
    innerLeftShadow.push([coneCx + cos(a) * (coneRxTop * 0.64), coneTopY + sin(a) * (coneRyTop * 0.64)]);
  }
  for (let i = 0; i <= 12; i++) {
    const a = -90 + (i / 12) * 180;
    innerRightSun.push([coneCx + cos(a) * (coneRxTop * 0.64), coneTopY + sin(a) * (coneRyTop * 0.64)]);
  }
  drawMarkerField(innerLeftShadow, "#4D1712", "#3D110D", null, 0, 2);
  drawMarkerField(innerRightSun, "#D43A0D", "#C23208", null, 0, 2);

  // --- 8E. Surgical Outer Contours of the Traffic Cone ---
  const leftContourTop = conePt(0, 0);
  const leftContourBot = conePt(0, 1);
  const rightContourTop = conePt(1, 0);
  const rightContourBot = conePt(1, 1);

  // Left sunlit contour (razor-sharp edge against the dark slate wall & floor)
  brush.set("razor_pen", "#FF7A3D", 0.9);
  brush.line(leftContourTop[0], leftContourTop[1], conePt(0, vCollarTop)[0], conePt(0, vCollarTop)[1]);
  brush.set("razor_pen", "#E8EEF7", 0.95);
  brush.line(conePt(0, vCollarTop)[0], conePt(0, vCollarTop)[1], conePt(0, vCollarBot)[0], conePt(0, vCollarBot)[1]);
  brush.set("razor_pen", "#FF7A3D", 0.9);
  brush.line(conePt(0, vCollarBot)[0], conePt(0, vCollarBot)[1], clipP1[0], clipP1[1]);
  brush.set("razor_pen", "#5E1C14", 0.9);
  brush.line(clipP1[0], clipP1[1], leftContourBot[0], leftContourBot[1]);

  // Right shadowed contour
  brush.set("razor_pen", "#6E2219", 0.9);
  brush.line(rightContourTop[0], rightContourTop[1], conePt(1, vCollarTop)[0], conePt(1, vCollarTop)[1]);
  brush.set("razor_pen", "#5C6575", 0.9);
  brush.line(conePt(1, vCollarTop)[0], conePt(1, vCollarTop)[1], conePt(1, vCollarBot)[0], conePt(1, vCollarBot)[1]);
  brush.set("razor_pen", "#6E2219", 0.9);
  brush.line(conePt(1, vCollarBot)[0], conePt(1, vCollarBot)[1], rightContourBot[0], rightContourBot[1]);

  // Bottom elliptical seam where the cone frustum meets the octagonal base
  for (let i = 0; i < 24; i++) {
    const u1 = i / 24;
    const u2 = (i + 1) / 24;
    const pA = conePt(u1, 1.0);
    const pB = conePt(u2, 1.0);
    const seamCol = u1 < 0.25 ? "#4F1710" : u1 < 0.6 ? "#A82E08" : "#591A13";
    brush.set("razor_pen", seamCol, 0.85);
    brush.line(pA[0], pA[1], pB[0], pB[1]);
  }

  // Top rim contour
  outlinePoly(topLipOuter, "#C93B0C", 0.75);
  outlinePoly(topLipInner, "#38100C", 0.7);

  noLoop();
}

// ============================================================================
// BARBIZON PLEIN-AIR STUDY: OBSESSION AT THE WOODPILE'S HEART
// Hyperreal graphite, ink, coloured pencil & charcoal over wet watercolour
// ============================================================================

const PITH_X = 532;
const PITH_Y = 648;
const LOG_DX = 228;
const LOG_DY = -122;
const LOG_TAPER = 0.77;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm archival cotton rag watercolor paper ground
  background("#f4ede0");
  brush.set("HB", "#3a281c", 1);

  // 1. Subtle paper grain & warm peripheral toning washes
  drawPaperAtmosphere();

  // 2. Broad, wet puddled plein-air washes (raw umber, sap green, grey-violet, ochre)
  drawPleinAirWashes();

  // 3. Charcoal-like scrubbed shadows & gnarled oak tree base
  drawOakBaseAndCharcoalShadows();

  // 4. Dissolving peripheral sketch logs & meadow scribbles
  drawPeripheralSketchLogs();

  // 5. Supporting stacked logs (medium-high detail transitioning outward)
  drawSupportingLogs();

  // 6. THE HERO LOG: Multi-layered watercolor underpainting
  drawHeroLogUnderpainting();

  // 7. THE HERO LOG: Split heartwood plane, swirled knot, medullary flecks & splinters
  drawHeroLogSplitPlane();

  // 8. THE HERO LOG: Deeply furrowed oak bark & crustose/foliose lichens
  drawHeroLogBarkAndLichen();

  // 9. THE HERO LOG: Microscopic cross-section end-grain (rings, pores, rays, checks)
  drawHeroLogEndGrain();

  // 10. Dappled afternoon ochre light splashes, wood chips & plein-air marginalia
  drawDappledLightAndForeground();

  noLoop();
}

// ============================================================================
// GEOMETRY HELPERS FOR THE HERO SPLIT LOG
// ============================================================================

function getNaturalTrunkRadius(deg) {
  let d = ((deg % 360) + 360) % 360;
  return (
    118 +
    7.5 * sin(d * 3 + 25) +
    4.5 * cos(d * 5 - 35) +
    3.0 * sin(d * 8 + 70) +
    2.0 * cos(d * 13)
  );
}

function rayChordDist(deg, r1, deg1, r2, deg2) {
  let x1 = r1 * cos(deg1);
  let y1 = r1 * sin(deg1);
  let x2 = r2 * cos(deg2);
  let y2 = r2 * sin(deg2);
  let nx = y2 - y1;
  let ny = -(x2 - x1);
  let denom = cos(deg) * nx + sin(deg) * ny;
  if (abs(denom) < 0.0001) return 999;
  return (x1 * nx + y1 * ny) / denom;
}

// Exact outer boundary of the Hero Log cross-section (bark rim + two split cleft planes)
function getHeroMaxRadius(deg, includeBark = false) {
  let d = ((deg % 360) + 360) % 360;
  let rWood = getNaturalTrunkRadius(d);

  // Bark thickness along the unsplit outer curve (118 deg to 318 deg)
  let barkExtra = 0;
  if (includeBark && d >= 116 && d <= 320) {
    let plateWave = abs(sin(d * 9.5 + 12)) * 11 + 4 * cos(d * 19);
    barkExtra = 8 + plateWave;
  }

  let r1 = getNaturalTrunkRadius(318);
  let rMid = 84;
  let r2 = getNaturalTrunkRadius(118);

  // Upper-right main split plane: from 318 deg through 0 deg to 50 deg
  if (d >= 318 || d <= 50) {
    let cDist = rayChordDist(d, r1, 318, rMid, 50);
    let jag = 1.8 * sin(d * 14 + 10) + 1.1 * cos(d * 27);
    return min(rWood, cDist + jag);
  }

  // Lower-right secondary cleft plane: from 50 deg to 118 deg
  if (d > 50 && d < 118) {
    let cDist = rayChordDist(d, rMid, 50, r2, 118);
    let jag = 1.6 * sin(d * 12 - 20) + 0.9 * sin(d * 29);
    return min(rWood, cDist + jag);
  }

  return rWood + barkExtra;
}

function getHeroPoint(deg, rScale = 1.0, includeBark = false, zT = 0.0) {
  let r = getHeroMaxRadius(deg, includeBark) * rScale;
  let taper = lerp(1.0, LOG_TAPER, zT);
  let cx = PITH_X + LOG_DX * zT;
  let cy = PITH_Y + LOG_DY * zT + 12 * sin(zT * 180);
  return [cx + r * taper * cos(deg), cy + r * taper * sin(deg)];
}

function fillPolygon(pts, curvature = 0.25) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function makeBlob(cx, cy, rx, ry, nPts = 14, wobble = 0.25, rotDeg = 0) {
  let pts = [];
  for (let i = 0; i < nPts; i++) {
    let a = (i / nPts) * 360;
    let nv = noise(cx * 0.01 + cos(a) * 1.3, cy * 0.01 + sin(a) * 1.3);
    let rMod = 1 + (nv - 0.5) * 2 * wobble;
    let lx = rx * rMod * cos(a);
    let ly = ry * rMod * sin(a);
    let gx = cx + lx * cos(rotDeg) - ly * sin(rotDeg);
    let gy = cy + lx * sin(rotDeg) + ly * cos(rotDeg);
    pts.push([gx, gy]);
  }
  return pts;
}

