      [1035, 565],
      [845, 665],
    ],
    0.2
  );
  brush.noWash();

  // Unfinished plein-air pencil rings & perspective construction lines on right
  brush.set("2B", "#4a382b", 0.9);
  for (let r = 18; r <= 68; r += 12) {
    brush.arc(832, 615, r, 20, 310);
