function drawAuxiliaryLog(cfg) {
  let {
    cx,
    cy,
    r,
    dx,
    dy,
    splitStart,
    splitEnd,
    woodCol,
    heartCol,
    barkCol,
    sunCol,
    shadowCol,
    rings,
    detail,
  } = cfg;

  // Helper for auxiliary log face radius
  function auxR(deg) {
    let d = ((deg % 360) + 360) % 360;
    let base = r * (1 + 0.05 * sin(d * 3 + cx) + 0.03 * cos(d * 5 + cy));
    let inSplit =
      splitStart < splitEnd
        ? d >= splitStart && d <= splitEnd
        : d >= splitStart || d <= splitEnd;
    if (inSplit) {
      let c = rayChordDist(d, base, splitStart, base * 0.92, splitEnd);
      return min(base, max(r * 0.35, c));
    }
    return base;
  }

  // 1. 3D Cylinder / Split Body Polygon
  let bodyPts = [];
  for (let a = 195; a <= 345; a += 15) {
    let rad = auxR(a);
    bodyPts.push([cx + rad * cos(a), cy + rad * sin(a)]);
  }
  for (let a = 345; a >= 195; a -= 15) {
    let rad = auxR(a) * 0.78;
    bodyPts.push([cx + dx + rad * cos(a), cy + dy + rad * sin(a)]);
  }

  brush.noStroke();
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.55, 0.45);
  brush.fill(barkCol, 175);
  fillPolygon(bodyPts, 0.15);

  // Sunlit ochre highlight wash on upper surface of log
  brush.fill(sunCol, 95);
  let sunPts = [
    [cx + r * 0.2, cy - r * 0.85],
    [cx + dx * 0.75, cy + dy * 0.75 - r * 0.65],
    [cx + dx * 0.75 + r * 0.45, cy + dy * 0.75 - r * 0.15],
    [cx + r * 0.65, cy - r * 0.25],
  ];
  fillPolygon(sunPts, 0.25);

  // 2. End-grain face base fill
  let facePts = [];
  for (let a = 0; a < 360; a += 10) {
    let rad = auxR(a);
    facePts.push([cx + rad * cos(a), cy + rad * sin(a)]);
  }
  brush.fillBleed(0.15, "in");
  brush.fill(woodCol, 200);
  fillPolygon(facePts, 0.15);

  // Heartwood warm wash
  let heartPts = [];
  for (let a = 0; a < 360; a += 15) {
    let rad = auxR(a) * 0.58;
    heartPts.push([cx + rad * cos(a), cy + rad * sin(a)]);
  }
  brush.fill(heartCol, 145);
  fillPolygon(heartPts, 0.2);

  // Half-shadow wash across lower portion of face
  let shadPts = [];
  for (let a = 20; a <= 200; a += 15) {
    let rad = auxR(a);
    shadPts.push([cx + rad * cos(a), cy + rad * sin(a)]);
  }
  brush.fill(shadowCol, 110);
  fillPolygon(shadPts, 0.2);
  brush.noFill();

  // 3. Longitudinal bark / split wood texture lines along cylinder body
  for (let i = 0; i < 42 * detail; i++) {
    let a = random(195, 355);
    let rad = auxR(a);
    let x1 = cx + rad * cos(a);
    let y1 = cy + rad * sin(a);
    let lenT = random(0.45, 1.05);
    let x2 = cx + dx * lenT + rad * 0.78 * cos(a);
    let y2 = cy + dy * lenT + rad * 0.78 * sin(a);
    let isSun = a > 250 && a < 325;
    brush.set(
      i % 3 === 0 ? "2B" : "HB",
      isSun ? "#5c3b1e" : "#241b18",
      random(0.45, 1.05)
    );
    brush.spline(
      [
        [x1, y1, 0.8],
        [
          lerp(x1, x2, 0.5) + random(-4, 4),
          lerp(y1, y2, 0.5) + random(-4, 4),
          1.0,
        ],
        [x2, y2, 0.3],
      ],
      0.35
    );
  }

  // 4. Growth rings on auxiliary log end-grain
  for (let ri = 1; ri <= rings; ri++) {
    let t = ri / rings;
    let ringRad = r * 0.94 * pow(t, 0.88);
    brush.set(
      ri % 4 === 0 ? "rotring" : "2H",
      ri % 3 === 0 ? "#4a2511" : "#784221",
      ri % 5 === 0 ? 0.65 : 0.38
    );
    let segPts = [];
    for (let a = 0; a <= 360; a += 8) {
      let maxR = auxR(a) * 0.94;
      let wob = 1.5 * sin(a * 6 + ri * 17) + 1.0 * cos(a * 3 - ri * 9);
      let currR = ringRad + wob;
      if (currR <= maxR) {
        segPts.push([cx + currR * cos(a), cy + currR * sin(a)]);
      } else {
        if (segPts.length >= 2) brush.spline(segPts, 0.25);
        segPts = [];
      }
    }
    if (segPts.length >= 2) brush.spline(segPts, 0.25);
  }

  // 5. Radial checks (cracks) & bark rim accents on auxiliary log
  for (let k = 0; k < 4; k++) {
    let ca = k * 88 + 35 + random(-15, 15);
    let cLen = auxR(ca) * random(0.55, 0.92);
    brush.set("rotring", "#1f120b", random(0.8, 1.4));
    brush.line(cx, cy, cx + cLen * cos(ca), cy + cLen * sin(ca));
  }

  // Outer bark rim plates
  for (let a = 140; a <= 340; a += 6) {
    let inSplit =
      splitStart < splitEnd
        ? a >= splitStart && a <= splitEnd
        : a >= splitStart || a <= splitEnd;
    if (inSplit) continue;
    let rIn = auxR(a) * 0.93;
    let rOut = auxR(a) * 1.06;
    brush.set("2B", "#261c17", 0.95);
    brush.line(
      cx + rIn * cos(a),
      cy + rIn * sin(a),
      cx + rOut * cos(a + 2),
      cy + rOut * sin(a + 2)
    );
  }
}

