// ============================================================================
// 7. THE HERO LOG: SPLIT HEARTWOOD PLANE, KNOT, MEDULLARY FLECKS & SPLINTERS
// ============================================================================

function drawHeroLogSplitPlane() {
  // Position of the dark swirled timber knot on the split face
  let pTopFront = getHeroPoint(318, 1.0, false, 0.0);
  let pMidFront = getHeroPoint(50, 1.0, false, 0.0);
  let pBotFront = getHeroPoint(118, 1.0, false, 0.0);

  let knotS = 0.44; // position across width of split face
  let knotZ = 0.48; // depth along log length
  let kFrontX = lerp(pTopFront[0], pMidFront[0], knotS);
  let kFrontY = lerp(pTopFront[1], pMidFront[1], knotS);
  let pTopBack = getHeroPoint(318, 1.0, false, 1.0);
  let pMidBack = getHeroPoint(50, 1.0, false, 1.0);
  let kBackX = lerp(pTopBack[0], pMidBack[0], knotS);
  let kBackY = lerp(pTopBack[1], pMidBack[1], knotS);
  let knotX = lerp(kFrontX, kBackX, knotZ);
  let knotY = lerp(kFrontY, kBackY, knotZ) + 12 * sin(knotZ * 180);

  // --- A. Quarter-Sawn Oak Medullary Ray Shimmer (Silky Ribbon Flecks) ---
  for (let i = 0; i < 95; i++) {
    let s = random(0.06, 0.94);
    let z = random(0.04, 0.92);
    let fx = lerp(
      lerp(pTopFront[0], pMidFront[0], s),
      lerp(pTopBack[0], pMidBack[0], s),
      z
    );
    let fy =
      lerp(
        lerp(pTopFront[1], pMidFront[1], s),
        lerp(pTopBack[1], pMidBack[1], s),
        z
      ) +
      12 * sin(z * 180);
    if (dist(fx, fy, knotX, knotY) < 26) continue;

    let inShadow = z > 0.62;
    brush.set(
      "cpencil",
      inShadow ? "#b39c86" : i % 2 === 0 ? "#fff2d6" : "#f7c768",
      random(0.65, 1.35)
    );
    let fLen = random(10, 26);
    let fAng = random(28, 52);
    brush.line(fx, fy, fx + fLen * cos(fAng), fy + fLen * sin(fAng));
  }

  // --- B. 260+ Microscopic Longitudinal Wood Grain Fibers Deflecting Around Knot ---
  let numFibers = 175;
  for (let i = 0; i <= numFibers; i++) {
    let s = i / numFibers;
    let startX = lerp(pTopFront[0], pMidFront[0], s);
    let startY = lerp(pTopFront[1], pMidFront[1], s);
    let endX = lerp(pTopBack[0], pMidBack[0], s);
    let endY = lerp(pTopBack[1], pMidBack[1], s);

    // Distance from the pith line determines heartwood vs sapwood color
    let distFromCenter = abs(s - 0.52);
    let isDarkRing = sin(s * 1850 + 15 * noise(s * 8)) > 0.15;

    let col;
    let w;
    let bName;
    if (distFromCenter < 0.28) {
      // Rich sienna/umber heartwood grain
      col = isDarkRing ? "#6b2e11" : "#9e4d1e";
      w = isDarkRing ? random(0.42, 0.78) : random(0.28, 0.5);
      bName = i % 5 === 0 ? "rotring" : "2H";
    } else {
      // Golden-amber outer wood & sapwood grain
      col = isDarkRing ? "#8f4e22" : "#c78342";
      w = isDarkRing ? random(0.35, 0.65) : random(0.25, 0.45);
      bName = i % 6 === 0 ? "HB" : "2H";
    }

    let pts = [];
    let steps = 14;
    for (let st = 0; st <= steps; st++) {
      let z = st / steps;
      let px = lerp(startX, endX, z);
      let py = lerp(startY, endY, z) + 12 * sin(z * 180);

      // Smooth potential-flow deflection around the timber knot at (knotX, knotY)
      let dxK = px - knotX;
      let dyK = py - knotY;
      let dK = sqrt(dxK * dxK + dyK * dyK);
      if (dK < 68) {
        let push = pow(1 - dK / 68, 2) * 24;
        let sign = s < knotS ? -1 : 1;
        // Normal to log direction (~ 62 deg)
        px += sign * push * cos(62);
        py += sign * push * sin(62);
      }

      // Fine organic grain ripple
      let ripple = (noise(s * 12, z * 6) - 0.5) * 6;
      px += ripple * cos(62);
      py += ripple * sin(62);

      let press = z > 0.85 ? map(z, 0.85, 1.0, 0.9, 0.3) : random(0.7, 1.15);
      pts.push([px, py, press]);
    }

    brush.set(bName, col, w);
    brush.spline(pts, 0.35);
  }

  // --- C. Lower Split Underside Plane Grain & Shadow Hatching (50 deg to 118 deg) ---
  let pBotBack = getHeroPoint(118, 1.0, false, 1.0);
  for (let i = 0; i <= 75; i++) {
    let s = i / 75;
    let x1 = lerp(pMidFront[0], pBotFront[0], s);
    let y1 = lerp(pMidFront[1], pBotFront[1], s);
    let x2 = lerp(pMidBack[0], pBotBack[0], s);
    let y2 = lerp(pMidBack[1], pBotBack[1], s);

    brush.set(
      i % 3 === 0 ? "rotring" : "2B",
      i % 2 === 0 ? "#24150e" : "#3d2417",
      random(0.45, 0.95)
    );
    brush.spline(
      [
        [x1, y1, 0.9],
        [
          lerp(x1, x2, 0.5),
          lerp(y1, y2, 0.5) + 10 + random(-3, 3),
          1.0,
        ],
        [x2, y2, 0.4],
      ],
      0.3
    );
  }

  // --- D. Hyper-Detailed Swirled Timber Knot at (knotX, knotY) ---
  brush.noStroke();
  brush.wash("#3b1909", 210);
  fillPolygon(makeBlob(knotX, knotY, 22, 14, 14, 0.18, -28), 0.25);
  brush.wash("#170903", 230);
  fillPolygon(makeBlob(knotX, knotY, 12, 8, 12, 0.15, -28), 0.25);
  brush.noWash();

  for (let r = 3; r <= 24; r += 2.2) {
    let kPts = [];
    for (let a = 0; a <= 360; a += 20) {
      let rx = r * 1.35 + 1.5 * sin(a * 3 + r * 10);
      let ry = r * 0.85 + 1.2 * cos(a * 4);
      let gx = knotX + rx * cos(a) * cos(-28) - ry * sin(a) * sin(-28);
      let gy = knotY + rx * cos(a) * sin(-28) + ry * sin(a) * cos(-28);
      kPts.push([gx, gy]);
    }
    brush.set(
      r < 12 ? "rotring" : "2H",
      r < 10 ? "#120702" : "#4a200b",
      r < 12 ? 0.55 : 0.4
    );
    brush.spline(kPts, 0.35);
  }
  // Tiny star-checks inside the knot core
  brush.set("rotring", "#0d0502", 0.75);
  for (let k = 0; k < 5; k++) {
    let ka = k * 72 + 15;
    brush.line(knotX, knotY, knotX + 11 * cos(ka), knotY + 7 * sin(ka));
  }

  // --- E. Longitudinal Split Checks (Deep Fissures Along the Split Face) ---
  for (let c = 0; c < 4; c++) {
    let cs = 0.22 + c * 0.19 + random(-0.03, 0.03);
    let cz1 = c % 2 === 0 ? 0.0 : random(0.15, 0.35);
    let cz2 = cz1 + random(0.32, 0.55);
    let cx1 = lerp(
      lerp(pTopFront[0], pMidFront[0], cs),
      lerp(pTopBack[0], pMidBack[0], cs),
      cz1
    );
    let cy1 =
      lerp(
        lerp(pTopFront[1], pMidFront[1], cs),
        lerp(pTopBack[1], pMidBack[1], cs),
        cz1
      ) +
      12 * sin(cz1 * 180);
    let cx2 = lerp(
      lerp(pTopFront[0], pMidFront[0], cs),
      lerp(pTopBack[0], pMidBack[0], cs),
      cz2
    );
    let cy2 =
      lerp(
        lerp(pTopFront[1], pMidFront[1], cs),
        lerp(pTopBack[1], pMidBack[1], cs),
        cz2
      ) +
      12 * sin(cz2 * 180);

    // Dark shadow inside crack
    brush.set("rotring", "#1c0d06", 1.15);
    brush.spline(
      [
        [cx1, cy1, 0.9],
        [lerp(cx1, cx2, 0.5) + random(-3, 3), lerp(cy1, cy2, 0.5) + 2, 1.2],
        [cx2, cy2, 0.2],
      ],
      0.3
    );
    // Bright sunlit lower lip of crack
    brush.set("cpencil", "#fff0cf", 0.75);
    brush.line(cx1 + 1, cy1 + 2.2, cx2 + 1, cy2 + 2.2);
  }

  // --- F. Razor-Sharp Lifted Wood Splinters & Cast Micro-Shadows ---
  // 1. Splinters peeling off the ridge between Split Plane 1 and Split Plane 2 (deg = 50)
  for (let i = 0; i < 18; i++) {
    let z = map(i, 0, 17, 0.03, 0.88) + random(-0.02, 0.02);
    let bx = lerp(pMidFront[0], pMidBack[0], z);
    let by = lerp(pMidFront[1], pMidBack[1], z) + 12 * sin(z * 180);
    let sLen = random(24, 62);
    let sAng = -28 + random(-14, 18); // peeling slightly away from the ridge
    let tipX = bx + sLen * cos(sAng);
    let tipY = by + sLen * sin(sAng);

    // Crisp dark cast shadow underneath the lifted splinter
    brush.set("rotring", "#1a0e08", random(0.75, 1.3));
    brush.line(bx + 2, by + 4, tipX + 3, tipY + 6);

    // Warm golden wood splinter body
    brush.set("cpencil", i % 2 === 0 ? "#fae2b4" : "#e8b064", random(0.9, 1.5));
    brush.line(bx, by, tipX, tipY);

    // Ultra-fine sunlit top edge & dark fiber contour
    brush.set("rotring", "#542811", 0.38);
    brush.line(bx, by - 1, tipX, tipY - 1);
    brush.set("cpencil", "#fff8e6", 0.55);
    brush.line(bx, by - 0.5, lerp(bx, tipX, 0.8), lerp(by, tipY, 0.8) - 0.5);
  }

  // 2. Splinters & torn fibers along the front cleft edge (deg = 318 to 50)
  for (let i = 0; i < 14; i++) {
    let s = random(0.08, 0.92);
    let bx = lerp(pTopFront[0], pMidFront[0], s);
    let by = lerp(pTopFront[1], pMidFront[1], s);
    let sLen = random(16, 42);
    let sAng = -26 + random(-18, 12);
    let tx = bx + sLen * cos(sAng);
    let ty = by + sLen * sin(sAng);

    brush.set("rotring", "#241107", 0.75);
    brush.line(bx + 1.5, by + 3, tx + 2.5, ty + 4);
    brush.set("cpencil", "#fff1d0", random(0.75, 1.25));
    brush.line(bx, by, tx, ty);
    brush.set("2H", "#6e3818", 0.35);
    brush.line(bx, by + 1, tx, ty + 1);
  }
}

// ============================================================================
// 8. THE HERO LOG: DEEPLY FURROWED OAK BARK & LICHEN CRUSTS
// ============================================================================

function drawHeroLogBarkAndLichen() {
  // --- A. Deeply Furrowed Longitudinal Oak Bark Plates (deg = 195 to 318) ---
  let numBarkStrips = 36;
  for (let i = 0; i <= numBarkStrips; i++) {
    let t = i / numBarkStrips;
    let deg = lerp(195, 318, t);

    let pFront = getHeroPoint(deg, 1.0, true, 0.0);
    let pBack = getHeroPoint(deg, 1.0, true, 1.0);

    // Every ~3rd strip is a deep V-shaped bark fissure
    let isFissure = i % 3 === 0;
    let isRidgeHighlight = i % 3 === 1;

    let pts = [];
    let steps = 12;
    for (let st = 0; st <= steps; st++) {
      let z = st / steps;
      let p = getHeroPoint(
        deg + 2.2 * sin(z * 360 + i * 25),
        1.0,
        true,
        z
      );
      pts.push([p[0], p[1], random(0.7, 1.3)]);
    }

    if (isFissure) {
      brush.set("charcoal", "#171110", random(1.1, 1.75));
      brush.spline(pts, 0.35);
      brush.set("rotring", "#0f0a09", 0.65);
      brush.spline(pts, 0.35);
    } else if (isRidgeHighlight) {
      let col = deg > 245 && deg < 312 ? "#8c7b6e" : "#5e4e44";
      brush.set("2B", col, random(0.85, 1.4));
      brush.spline(pts, 0.3);
      if (deg > 255 && deg < 310) {
        brush.set("cpencil", "#bfb0a2", 0.65);
        brush.line(
          pFront[0],
          pFront[1],
          lerp(pFront[0], pBack[0], 0.6),
          lerp(pFront[1], pBack[1], 0.6)
        );
      }
    } else {
      brush.set("HB", "#40322b", random(0.65, 1.15));
      brush.spline(pts, 0.35);
    }

    // Transverse bark plate cracks (creating rugged rectangular oak bark scales)
    if (i < numBarkStrips && i % 2 === 0) {
      for (let c = 1; c <= 5; c++) {
        let zc = c / 6 + random(-0.04, 0.04);
        let pA = getHeroPoint(deg, 1.0, true, zc);
        let pB = getHeroPoint(deg + 7, 1.0, true, zc + 0.02);
        brush.set("rotring", "#1a1310", 0.75);
        brush.line(pA[0], pA[1], pB[0], pB[1]);
        brush.set("cpencil", "#9e8e80", 0.55);
        brush.line(pA[0] + 1.5, pA[1] - 1, pB[0] + 1.5, pB[1] - 1);
      }
    }
  }

  // --- B. Thick Cross-Section Bark Plates Around the Front Rim (118 to 318 deg) ---
  for (let deg = 118; deg <= 318; deg += 2.2) {
    let pIn = getHeroPoint(deg, 0.99, false, 0.0);
    let pOut = getHeroPoint(deg, 1.0, true, 0.0);

    let isCleft = abs(sin(deg * 9.5 + 12)) < 0.25;
    if (isCleft) {
      brush.set("rotring", "#140d0a", 0.95);
      brush.line(pIn[0], pIn[1], pOut[0], pOut[1]);
    } else {
      let isTopLit = deg > 225 && deg < 318;
      brush.set(
        "2B",
        isTopLit ? "#6e5a4d" : "#332620",
        random(0.65, 1.15)
      );
      brush.line(pIn[0], pIn[1], pOut[0], pOut[1]);

      // Layered corky striations inside each bark plate
      for (let l = 0.25; l <= 0.85; l += 0.3) {
        let pL1 = getHeroPoint(deg - 1.2, 1.0 - l * 0.05, true, 0.0);
        let pL2 = getHeroPoint(deg + 1.2, 1.0 - l * 0.05, true, 0.0);
        brush.set("2H", isTopLit ? "#9c8879" : "#4d3b31", 0.45);
        brush.line(pL1[0], pL1[1], pL2[0], pL2[1]);
      }
    }
  }
  // Dark cambium boundary line separating wood from bark
  let cambiumPts = [];
  for (let deg = 118; deg <= 318; deg += 4) {
    cambiumPts.push(getHeroPoint(deg, 0.99, false, 0.0));
  }
  brush.set("rotring", "#1f1008", 0.95);
  brush.spline(cambiumPts, 0.3);

  // --- C. Hyperreal Lichen Colonies (Parmelia Turquoise-Sage & Xanthoria Sunburst Gold) ---
  let lichenClusters = [
    // Turquoise-sage foliose Parmelia colonies
    { deg: 288, z: 0.22, rx: 32, ry: 18, type: "parmelia" },
    { deg: 262, z: 0.42, rx: 38, ry: 22, type: "parmelia" },
    { deg: 305, z: 0.52, rx: 28, ry: 15, type: "parmelia" },
    { deg: 235, z: 0.18, rx: 25, ry: 16, type: "parmelia" },
    { deg: 312, z: 0.03, rx: 22, ry: 14, type: "parmelia" }, // spilling over front rim!
    // Electric orange-gold crustose Xanthoria parietina colonies
    { deg: 274, z: 0.14, rx: 26, ry: 15, type: "xanthoria" },
    { deg: 296, z: 0.35, rx: 30, ry: 17, type: "xanthoria" },
    { deg: 248, z: 0.3, rx: 24, ry: 14, type: "xanthoria" },
    { deg: 282, z: 0.65, rx: 22, ry: 13, type: "xanthoria" },
    { deg: 215, z: 0.04, rx: 20, ry: 13, type: "xanthoria" }, // on front-left bark rim
  ];

  for (let cl of lichenClusters) {
    let center = getHeroPoint(cl.deg, 1.0, true, cl.z);
    drawLichenColony(center[0], center[1], cl.rx, cl.ry, cl.type);
  }
}

function drawLichenColony(cx, cy, rx, ry, type) {
  let isParmelia = type === "parmelia";
  let baseCol = isParmelia ? "#5da388" : "#f28b18";
  let midCol = isParmelia ? "#88ccb0" : "#ffba26";
  let rimCol = isParmelia ? "#d7f2e4" : "#fff099";
  let cupCol = isParmelia ? "#3d5e4e" : "#cc4e08";

  // 1. Soft watercolor wash base for the thallus
  brush.noStroke();
  brush.wash(baseCol, 155);
  fillPolygon(makeBlob(cx, cy, rx, ry, 14, 0.32, -24), 0.3);
  brush.noWash();

  // 2. Individual overlapping foliose lobes & dark micro-shadows
  let numLobes = floor(map(rx, 18, 40, 22, 46));
  for (let i = 0; i < numLobes; i++) {
    let a = random(0, 360);
    let distR = pow(random(0, 1), 0.65);
    let lx = cx + distR * rx * cos(a) * cos(-24) - distR * ry * sin(a) * sin(-24);
    let ly = cy + distR * rx * cos(a) * sin(-24) + distR * ry * sin(a) * cos(-24);
    let lobeR = random(3.5, 7.5);

    // Crisp black-umber rhizine micro-shadow under the lower edge of the lobe
    brush.set("rotring", "#17120e", 0.55);
    brush.arc(lx + 0.8, ly + 1.4, lobeR, 15, 175);

    // Lobe body in colored pencil / marker
    brush.set("cpencil", i % 2 === 0 ? midCol : baseCol, random(0.85, 1.35));
    brush.circle(lx, ly, lobeR * 0.75, 0.25);

    // Crisp pale crinkled upper margin
    brush.set("cpencil", rimCol, 0.65);
    brush.arc(lx, ly, lobeR * 0.92, 185, 355);
  }

  // 3. Tiny cup-like apothecia (fruiting bodies) near the center of the colony
  let numCups = floor(numLobes * 0.32);
  for (let c = 0; c < numCups; c++) {
    let ca = random(0, 360);
    let cr = random(0, 0.55);
    let ux = cx + cr * rx * cos(ca);
    let uy = cy + cr * ry * sin(ca);
    let cupRad = random(1.8, 3.6);

    brush.set("rotring", cupCol, 0.65);
    brush.circle(ux, uy, cupRad, 0.15);
    brush.set("cpencil", rimCol, 0.5);
    brush.arc(ux, uy, cupRad + 0.8, 0, 360);
  }
}

// ============================================================================
// 9. THE HERO LOG: MICROSCOPIC CROSS-SECTION END-GRAIN
// ============================================================================

function drawHeroLogEndGrain() {
  // --- A. 66 Concentric Annual Growth Rings (Springwood Pores + Summerwood Bands) ---
  let totalRings = 66;
  for (let ri = 1; ri <= totalRings; ri++) {
    let t = ri / totalRings;
    // Non-linear ring spacing (tighter near outer sapwood and inner pith)
    let nominalScale = 0.025 + 0.965 * pow(t, 0.92);
    let isMajorRing = ri % 4 === 0 || ri % 7 === 0;
    let isHeartwood = t < 0.78;

    // Draw the continuous ring segments (clipped accurately against the two split planes!)
    let segPts = [];
    let stepDeg = ri < 12 ? 6 : 3;

    for (let deg = 0; deg <= 360; deg += stepDeg) {
      let d = deg % 360;
      let rNatural = getNaturalTrunkRadius(d);
      let rMaxWood = getHeroMaxRadius(d, false);

      // Organic ring undulation + slight inward pinch along major radial checks
      let ringWobble =
        1.8 * sin(d * 4 + ri * 7) +
        1.1 * cos(d * 9 - ri * 13) +
        0.7 * sin(d * 17 + ri * 5);
      let rCurr = rNatural * nominalScale + ringWobble;

      if (rCurr <= rMaxWood - 1.2) {
        let px = PITH_X + rCurr * cos(d);
        let py = PITH_Y + rCurr * sin(d);
        segPts.push([px, py, random(0.75, 1.15)]);
      } else {
        if (segPts.length >= 2) {
          styleAndDrawRingSegment(segPts, ri, isMajorRing, isHeartwood);
        }
        segPts = [];
      }
    }
    if (segPts.length >= 2) {
      styleAndDrawRingSegment(segPts, ri, isMajorRing, isHeartwood);
    }

    // Ring-porous oak earlywood vessel pores (microscopic dots along every 2nd ring)
    if (ri > 8 && ri % 2 === 0) {
      for (let deg = 0; deg < 360; deg += 7) {
        let rNat = getNaturalTrunkRadius(deg);
        let rMax = getHeroMaxRadius(deg, false);
        let rPore = rNat * (nominalScale - 0.006);
        if (rPore < rMax - 3) {
          let px = PITH_X + rPore * cos(deg);
          let py = PITH_Y + rPore * sin(deg);
          let isLit = deg > 210 || deg < 25;
          brush.set(
            "2H",
            isLit ? "#8c4a20" : "#4a2410",
            random(0.28, 0.48)
          );
          brush.line(px, py, px + 1.1 * cos(deg + 90), py + 1.1 * sin(deg + 90));
        }
      }
    }
  }

  // --- B. 145 Fine Radial Medullary Rays Radiating from the Pith ---
  for (let i = 0; i < 145; i++) {
    let deg = (i / 145) * 360 + random(-1.2, 1.2);
    let rMax = getHeroMaxRadius(deg, false) - 2;
    let rStart = random(4, 38);
    let rEnd = rMax * random(0.65, 0.99);
    if (rEnd <= rStart + 8) continue;

    // Slight natural S-curve to each medullary ray
    let curveMid = random(-3.5, 3.5);
    let p1 = [PITH_X + rStart * cos(deg), PITH_Y + rStart * sin(deg), 0.4];
    let rM = (rStart + rEnd) * 0.5;
    let p2 = [
      PITH_X + rM * cos(deg + curveMid),
      PITH_Y + rM * sin(deg + curveMid),
      0.95,
    ];
    let p3 = [
      PITH_X + rEnd * cos(deg + curveMid * 0.6),
      PITH_Y + rEnd * sin(deg + curveMid * 0.6),
      0.4,
    ];

    // Alternate between luminous golden-cream rays and fine sepia rays
    if (i % 3 === 0) {
      let isSunZone = deg > 205 || deg < 35;
      brush.set(
        "cpencil",
        isSunZone ? "#fff3d6" : "#dfc298",
        random(0.45, 0.85)
      );
      brush.spline([p1, p2, p3], 0.3);
    } else {
      brush.set(
        "2H",
        i % 2 === 0 ? "#633014" : "#874823",
        random(0.25, 0.48)
      );
      brush.spline([p1, p2, p3], 0.3);
    }
  }

  // --- C. Deep Radial Drying Checks (Heartwood Wedge Cracks) ---
  let mainChecks = [
    { deg: 15, lenScale: 0.96, width: 6.2 }, // splitting toward right cleft
    { deg: 82, lenScale: 0.92, width: 5.0 }, // splitting toward bottom cleft
    { deg: 158, lenScale: 0.86, width: 5.5 }, // lower-left major check
    { deg: 222, lenScale: 0.9, width: 6.8 }, // upper-left major check
    { deg: 286, lenScale: 0.84, width: 4.8 }, // top check
    { deg: 334, lenScale: 0.78, width: 3.8 }, // upper-right check
  ];

  for (let chk of mainChecks) {
    drawRadialCheck(chk.deg, chk.lenScale, chk.width);
  }

  // 14 Smaller Secondary Peripheral & Mid-Ring Checks
  for (let sc = 0; sc < 14; sc++) {
    let sDeg = sc * 25.7 + 11;
    let rMax = getHeroMaxRadius(sDeg, false);
    let r1 = rMax * random(0.22, 0.52);
    let r2 = rMax * random(0.68, 0.95);
    let x1 = PITH_X + r1 * cos(sDeg);
    let y1 = PITH_Y + r1 * sin(sDeg);
    let x2 = PITH_X + r2 * cos(sDeg + random(-3, 3));
    let y2 = PITH_Y + r2 * sin(sDeg + random(-3, 3));

    brush.set("rotring", "#1a0b05", random(0.65, 1.1));
    brush.spline(
      [
        [x1, y1, 0.4],
        [
          lerp(x1, x2, 0.5) + random(-2, 2),
          lerp(y1, y2, 0.5) + random(-2, 2),
          1.1,
        ],
        [x2, y2, 0.3],
      ],
      0.3
    );
    brush.set("cpencil", "#fce6be", 0.5);
    brush.line(x1 + 1, y1 + 1, x2 + 1, y2 + 1);
  }

  // --- D. Dark Crushed Pith Core & Crisp Cleft Ridge Highlights ---
  brush.set("rotring", "#120703", 1.1);
  for (let i = 0; i < 8; i++) {
    let a = i * 45 + random(-10, 10);
    brush.line(
      PITH_X,
      PITH_Y,
      PITH_X + random(5, 11) * cos(a),
      PITH_Y + random(5, 11) * sin(a)
    );
  }

  // Sharp, luminous edge highlight where the front cross-section meets the split plane
  let cleftEdgePts = [];
  for (let d = 318; d <= 410; d += 5) {
    cleftEdgePts.push(getHeroPoint(d % 360, 1.0, false, 0.0));
  }
  brush.set("cpencil", "#fff6de", 0.95);
  brush.spline(cleftEdgePts, 0.25);
  brush.set("rotring", "#47200c", 0.42);
  brush.spline(cleftEdgePts, 0.25);
}

function styleAndDrawRingSegment(segPts, ri, isMajorRing, isHeartwood) {
  let col;
  let w;
  let bName;

  if (isMajorRing) {
    col = isHeartwood ? "#451e0b" : "#6b3719";
    w = random(0.5, 0.78);
    bName = ri % 8 === 0 ? "rotring" : "HB";
  } else {
    col = isHeartwood
      ? ri % 2 === 0
        ? "#6e3315"
        : "#8f4922"
      : ri % 2 === 0
      ? "#8a4d24"
      : "#b06e3b";
    w = random(0.28, 0.48);
    bName = "2H";
  }

  brush.set(bName, col, w);
  brush.spline(segPts, 0.25);
}

function drawRadialCheck(deg, lenScale, maxW) {
  let rMax = getHeroMaxRadius(deg, false) * lenScale;
  let steps = 10;
  let leftLip = [];
  let rightLip = [];
  let centerSpine = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let r = t * rMax;
    // Crack is widest near the pith/inner heartwood and tapers to a hairline tip
    let halfW = maxW * 0.5 * pow(1 - t, 0.75) * (0.35 + 0.65 * sin(t * 140));
    let jag = (noise(deg * 0.2, i * 0.6) - 0.5) * 5.5 * t;
    let currDeg = deg + jag;

    let cx = PITH_X + r * cos(currDeg);
    let cy = PITH_Y + r * sin(currDeg);
    let nx = -sin(currDeg);
    let ny = cos(currDeg);

    centerSpine.push([cx, cy, 1.2 * (1 - t * 0.6)]);
    leftLip.push([cx + nx * halfW, cy + ny * halfW]);
    rightLip.push([cx - nx * halfW, cy - ny * halfW]);
  }

  // 1. Fill the wedge-shaped crack interior with pitch-black umber
  let crackPoly = leftLip.concat(rightLip.slice().reverse());
  brush.noStroke();
  brush.wash("#120703", 235);
  fillPolygon(crackPoly, 0.12);
  brush.noWash();

  // 2. Deep ink spine & dark ragged edges
  brush.set("rotring", "#0d0401", 1.15);
  brush.spline(centerSpine, 0.25);
  brush.set("rotring", "#2b1207", 0.6);
  brush.spline(leftLip, 0.25);
  brush.spline(rightLip, 0.25);

  // 3. Crisp sunlit wood highlight on the light-catching lip of the crack
  let litLip = sin(deg - 45) > 0 ? leftLip : rightLip;
  brush.set("cpencil", "#fff2d4", 0.75);
  brush.spline(litLip, 0.25);

  // 4. Tiny stretched wood splinters bridging across the crack cavity
  for (let b = 2; b < steps - 2; b += 2) {
    brush.set("2H", "#c48852", 0.35);
    brush.line(
      leftLip[b][0],
      leftLip[b][1],
      rightLip[b + 1][0],
      rightLip[b + 1][1]
    );
  }
}

// ============================================================================
// 10. DAPPLED AFTERNOON LIGHT, FOREGROUND WOOD CHIPS & PLEIN-AIR MARGINALIA
// ============================================================================

function drawDappledLightAndForeground() {
  // --- A. Luminous Dappled Afternoon Sunlight Patches (Warm Ochre & Gold) ---
  brush.noStroke();
  brush.wash("#f7b825", 52);
  fillPolygon(makeBlob(635, 575, 85, 48, 12, 0.3, -26), 0.35);
  fillPolygon(makeBlob(485, 610, 62, 38, 12, 0.3, -20), 0.35);
  fillPolygon(makeBlob(685, 765, 95, 45, 12, 0.32, -15), 0.35);
  fillPolygon(makeBlob(415, 705, 68, 36, 12, 0.3, -18), 0.35);

  brush.wash("#ffe266", 45);
  fillPolygon(makeBlob(650, 565, 48, 28, 10, 0.28, -26), 0.35);
