}

function drawFallenOakLeaf(lx, ly, rot) {
  let lobeOffsets = [
    [-22, 0],
    [-16, -7],
    [-8, -4],
    [-2, -11],
    [6, -5],
    [14, -9],
    [22, 0],
    [14, 8],
    [6, 4],
    [-2, 10],
    [-8, 4],
    [-16, 6],
  ];
  let pts = [];
  let shadowPts = [];
  for (let p of lobeOffsets) {
    let gx = lx + p[0] * cos(rot) - p[1] * sin(rot);
    let gy = ly + p[0] * sin(rot) + p[1] * cos(rot);
    pts.push([gx, gy]);
    shadowPts.push([gx + 2.5, gy + 4]);
  }

  brush.noStroke();
  brush.wash("#1c131f", 160);
  fillPolygon(shadowPts, 0.35);
  brush.wash("#d98229", 215);
  fillPolygon(pts, 0.35);
  brush.noWash();

  // Leaf midrib & veins
  brush.set("rotring", "#4a200a", 0.5);
  brush.spline(pts.concat([pts[0]]), 0.35);
  brush.line(
    lx - 26 * cos(rot),
    ly - 26 * sin(rot),
    lx + 21 * cos(rot),
    ly + 21 * sin(rot)
  );
  brush.set("cpencil", "#ffdf80", 0.55);
  brush.line(
    lx - 14 * cos(rot),
    ly - 14 * sin(rot) - 1,
    lx + 16 * cos(rot),
    ly + 16 * sin(rot) - 1
  );
}

