// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  const clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    const dx = pts[i][0] - clean[clean.length - 1][0];
    const dy = pts[i][1] - clean[clean.length - 1][1];
    if (dx * dx + dy * dy > 1.0) {
      clean.push(pts[i]);
    }
  }
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else if (clean.length >= 3) {
    brush.spline(clean, curvature);
  }
}

function evalCubicBezier(p0, p1, p2, p3, t) {
  const u = 1 - t;
  const tt = t * t;
  const uu = u * u;
  const uuu = uu * u;
  const ttt = tt * t;
  return [
    uuu * p0[0] + 3 * uu * t * p1[0] + 3 * u * tt * p2[0] + ttt * p3[0],
    uuu * p0[1] + 3 * uu * t * p1[1] + 3 * u * tt * p2[1] + ttt * p3[1]
  ];
}

function sampleBezierSpine(p0, p1, p2, p3, steps = 20) {
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    pts.push(evalCubicBezier(p0, p1, p2, p3, i / steps));
  }
  return pts;
}

function computeSpineNormals(pts) {
  const normals = [];
  for (let i = 0; i < pts.length; i++) {
    let dx, dy;
    if (i === 0) {
      dx = pts[1][0] - pts[0][0];
      dy = pts[1][1] - pts[0][1];
    } else if (i === pts.length - 1) {
      dx = pts[i][0] - pts[i - 1][0];
      dy = pts[i][1] - pts[i - 1][1];
    } else {
      dx = pts[i + 1][0] - pts[i - 1][0];
      dy = pts[i + 1][1] - pts[i - 1][1];
    }
    const len = sqrt(dx * dx + dy * dy) || 1;
    // Normal pointing generally "downward/outward" (+y for left-to-right curves)
    let nx = -dy / len;
    let ny = dx / len;
    normals.push([nx, ny]);
  }
  return normals;
}

function offsetSpine(pts, normals, widths, sFactor, shiftX = 0, shiftY = 0) {
  const out = [];
  for (let i = 0; i < pts.length; i++) {
    const w = Array.isArray(widths) ? widths[i] : widths;
    const p = pts[i][2] !== undefined ? pts[i][2] : 1.0;
    out.push([
      pts[i][0] + normals[i][0] * w * sFactor + shiftX,
      pts[i][1] + normals[i][1] * w * sFactor + shiftY,
      p
    ]);
  }
  return out;
}

function getStripePalette(type) {
  if (type === "mint") return PALETTE.mint;
  if (type === "pink") return PALETTE.pink;
  return PALETTE.white;
}

// Renders a single 3D raised, ridged line of opaque marker with rounded bead edges & shadow
function drawRaisedMarkerRidge(pts, widths, colorType, opts = {}) {
  const pal = getStripePalette(colorType);
  const normals = computeSpineNormals(pts);
  const avgW = Array.isArray(widths)
    ? widths.reduce((a, b) => a + b, 0) / widths.length
    : widths;
  const wScale = constrain(avgW / 12.0, 0.35, 2.2);

  // 1. Soft cast shadow beneath the ridge
  if (opts.castShadow) {
    const sx = opts.shadowDX !== undefined ? opts.shadowDX : 4;
    const sy = opts.shadowDY !== undefined ? opts.shadowDY : 9;
    brush.set("soft_shadow", PALETTE.shadow.castMid, 0.9 * wScale);
    safeSpline(offsetSpine(pts, normals, widths, 0.35, sx, sy), 0.5);
    brush.set("soft_shadow", PALETTE.shadow.castDark, 0.55 * wScale);
    safeSpline(offsetSpine(pts, normals, widths, 0.15, sx * 0.6, sy * 0.6), 0.5);
  }

  // 2. Base opaque marker underpainting across the ridge cylinder
  brush.set("piping_body", pal.mid, 0.85 * wScale);
  safeSpline(offsetSpine(pts, normals, widths, 0.25), 0.5);

  brush.set("piping_body", pal.main, 0.95 * wScale);
  safeSpline(offsetSpine(pts, normals, widths, -0.08), 0.5);

  // 3. Reflected cool light along the lower belly of the ridge
  brush.set("sugar_glaze", opts.bottomBounce || pal.rim, 0.65 * wScale);
  safeSpline(offsetSpine(pts, normals, widths, 0.68), 0.5);

  // 4. Core shadow along the lower-mid flank
  brush.set("opaque_marker", pal.core, 0.55 * wScale);
  safeSpline(offsetSpine(pts, normals, widths, 0.42), 0.5);

  // 5. Dense opaque marker body passes (mint, pearl white, or candy pink)
  brush.set("opaque_marker", pal.main, 0.78 * wScale);
  safeSpline(offsetSpine(pts, normals, widths, 0.08), 0.5);

  brush.set("opaque_marker", pal.bright, 0.72 * wScale);
  safeSpline(offsetSpine(pts, normals, widths, -0.18), 0.5);

  // 6. Upper lit crown of the ridge
  brush.set("piping_ridge", pal.light, 0.7 * wScale);
  safeSpline(offsetSpine(pts, normals, widths, -0.38), 0.5);

  // 7. Fine nozzle extrusion striations (icing/toothpaste texture)
  brush.set("cpencil", pal.core, 0.32);
  safeSpline(offsetSpine(pts, normals, widths, 0.52), 0.5);
  brush.set("cpencil", pal.light, 0.35);
  safeSpline(offsetSpine(pts, normals, widths, -0.25), 0.5);

  // 8. Sharp crevice flute line on the bottom & top edges of the ridge
  brush.set("pen", pal.shadow, 0.38);
  safeSpline(offsetSpine(pts, normals, widths, 0.88), 0.5);
  brush.set("2H", pal.core, 0.32);
  safeSpline(offsetSpine(pts, normals, widths, -0.82), 0.5);

  // 9. Glossy wet-sugar specular highlight along the upper crown
  if (opts.specular !== false) {
    brush.set("sugar_glaze", "#ffffff", 0.55 * wScale);
    safeSpline(offsetSpine(pts, normals, widths, -0.36), 0.5);

    // Crisp center glint along the middle 65% of the ridge
    if (pts.length >= 5) {
      const subPts = pts.slice(1, pts.length - 1);
      const subNorms = normals.slice(1, pts.length - 1);
      const subW = Array.isArray(widths) ? widths.slice(1, pts.length - 1) : widths;
      brush.set("pen", "#ffffff", 0.45 * wScale);
      safeSpline(offsetSpine(subPts, subNorms, subW, -0.35), 0.5);
    }
  }

  // 10. Rounded bead edges at the start and/or end of the ridge
  if (opts.beadStart) {
    const w0 = Array.isArray(widths) ? widths[0] : widths;
    drawRoundedBead(pts[0][0], pts[0][1], w0 * 0.92, colorType, opts.beadShadow !== false);
  }
  if (opts.beadEnd) {
    const w1 = Array.isArray(widths) ? widths[widths.length - 1] : widths;
    const last = pts[pts.length - 1];
    drawRoundedBead(last[0], last[1], w1 * 0.92, colorType, opts.beadShadow !== false);
  }
}

// Draws a plump 3D rounded bead (sugar pearl / piped ridge bead termination)
function drawRoundedBead(cx, cy, radius, colorType, withShadow = true) {
  const pal = getStripePalette(colorType);
  const r = max(3.5, radius);

  // Soft cast shadow under the bead
  if (withShadow) {
    brush.set("soft_shadow", PALETTE.shadow.castDark, constrain(r / 10, 0.35, 1.3));
    brush.circle(cx + r * 0.28, cy + r * 0.45, r * 0.9, 0.15);
  }

  // Opaque wash base for solid pearl fullness
  brush.noStroke();
  brush.wash(pal.main, 230);
  brush.circle(cx, cy, r * 0.95);
  brush.noWash();

  // Shaded crescent on lower-right
  brush.set("opaque_marker", pal.core, constrain(r / 9, 0.35, 1.2));
  brush.arc(cx, cy, r * 0.72, 15, 165);

  // Reflected cool rim on very bottom
  brush.set("pen", pal.rim, 0.4);
  brush.arc(cx, cy, r * 0.85, 35, 145);

  // Opaque marker dome fill
  brush.set("opaque_marker", pal.bright, constrain(r / 7.5, 0.4, 1.4));
  brush.circle(cx - r * 0.08, cy - r * 0.08, r * 0.55, 0.1);

  // Lit upper-left crown
  brush.set("piping_ridge", pal.light, constrain(r / 8, 0.35, 1.1));
  brush.arc(cx - r * 0.06, cy - r * 0.06, r * 0.52, 195, 345);

  // Subtle contour rim
  brush.set("pen", pal.shadow, 0.32);
  brush.arc(cx, cy, r * 0.95, 10, 175);

  // Specular wet pinpoint glint
  brush.set("piping_ridge", "#ffffff", constrain(r / 9, 0.35, 1.0));
  brush.line(
    cx - r * 0.34,
    cy - r * 0.32,
    cx - r * 0.14,
    cy - r * 0.38
  );
  brush.set("rotring", "#ffffff", 0.65);
  brush.line(cx - r * 0.25, cy - r * 0.35, cx - r * 0.21, cy - r * 0.35);
}

// Draws a multi-ridged wedding-cake scallop coil segment along a spine
function drawScallopCoilSegment(p0, p1, p2, p3, wStart, wPeak, wEnd, stripeList, opts = {}) {
  const steps = opts.steps || 18;
  const centerSpine = sampleBezierSpine(p0, p1, p2, p3, steps);
  const centerNormals = computeSpineNormals(centerSpine);

  // Compute total half-width profile along the scallop (swells to a plump lobe, then tapers)
  const totalHalfWidths = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    // Swell curve: plump near t = 0.28 (the bead head), tapering toward t = 1.0
    const swell = sin(t * 180);
    const w = lerp(wStart, wEnd, t) + (wPeak - max(wStart, wEnd)) * pow(swell, 0.75);
    totalHalfWidths.push(w);
  }

  // 1. Cast shadow of the entire scalloped lobe onto the layer beneath
  const sx = opts.shadowDX !== undefined ? opts.shadowDX : 7;
  const sy = opts.shadowDY !== undefined ? opts.shadowDY : 15;
  for (let s = -0.75; s <= 0.85; s += 0.32) {
    const shSpine = offsetSpine(centerSpine, centerNormals, totalHalfWidths, s, sx, sy);
    brush.set(
      "soft_shadow",
      s > 0.2 ? PALETTE.shadow.castDark : PALETTE.shadow.castMid,
      1.15
    );
    safeSpline(shSpine, 0.5);
  }

  // Also cast a rounded shadow at the bead head of the scallop
  const headPt = centerSpine[0];
  const headNorm = centerNormals[0];
  for (let s = -0.8; s <= 0.8; s += 0.25) {
    const bx = headPt[0] + headNorm[0] * totalHalfWidths[0] * s + sx * 0.9;
    const by = headPt[1] + headNorm[1] * totalHalfWidths[0] * s + sy * 0.9;
    brush.set("soft_shadow", PALETTE.shadow.deepAO, 0.85);
    brush.circle(bx, by, (totalHalfWidths[0] / stripeList.length) * 1.6, 0.2);
  }

  // 2. Render each raised stripe ridge from bottom-most to top-most (or vice versa)
  const nStripes = stripeList.length;
  // Draw outer ridges first and center/crown ridges last so overlapping crowns pop in 3D
  const order = [];
  for (let idx = nStripes - 1; idx >= 0; idx--) {
    order.push(idx);
  }

  for (let k = 0; k < order.length; k++) {
    const idx = order[k];
    const colorType = stripeList[idx];
    // Map stripe index to normalized cross-section [-0.88, +0.88]
    const sCenter = map(idx, 0, nStripes - 1, -0.86, 0.86);
    const ridgeHalfFactor = 1.05 / nStripes;

    const ridgePts = [];
    const ridgeWidths = [];
    for (let i = 0; i <= steps; i++) {
      const tw = totalHalfWidths[i];
      ridgePts.push([
        centerSpine[i][0] + centerNormals[i][0] * tw * sCenter,
        centerSpine[i][1] + centerNormals[i][1] * tw * sCenter
      ]);
      ridgeWidths.push(max(3.5, tw * ridgeHalfFactor));
    }

    const isBottomEdge = idx === nStripes - 1;
    drawRaisedMarkerRidge(ridgePts, ridgeWidths, colorType, {
      castShadow: idx >= nStripes - 2,
      shadowDX: 3,
      shadowDY: 7,
      bottomBounce: isBottomEdge ? "#6ee2ff" : undefined,
      beadStart: opts.beadHead !== false,
      beadEnd: opts.beadTail === true,
      beadShadow: true
    });
  }
}

