// ============================================================================
// 2. MACRO TOOTHBRUSH HEAD DECK & SOCKETS
// ============================================================================

function getDeckCenterY(x) {
  // Gentle upward macro tilt from left to right
  return map(x, 100, 1100, 935, 865);
}

function drawToothbrushHead() {
  // Deep out-of-focus shadow beneath the toothbrush head
  for (let i = 0; i < 8; i++) {
    brush.set("soft_shadow", PALETTE.handle.underShadow, 1.8 - i * 0.12);
    const yOff = 1045 + i * 10;
    safeSpline([
      [40, yOff + 40],
      [380, yOff + 15],
      [780, yOff - 15],
      [1130, yOff - 55]
    ], 0.5);
  }

  // Sculpted 3D body of the toothbrush head
  const topEdge = [];
  const midBevel = [];
  const botEdge = [];
  for (let i = 0; i <= 24; i++) {
    const t = i / 24;
    const x = lerp(40, 1145, t);
    const cy = getDeckCenterY(x);
    // Slight ergonomic curve at the neck (left) and rounded toe (right)
    const neckDip = t < 0.2 ? pow((0.2 - t) / 0.2, 2) * 35 : 0;
    const toeCurve = t > 0.85 ? pow((t - 0.85) / 0.15, 2) * 45 : 0;
    topEdge.push([x, cy - 48 + neckDip + toeCurve]);
    midBevel.push([x, cy + 28 + neckDip * 0.6 - toeCurve * 0.3]);
    botEdge.push([x, cy + 125 - neckDip * 0.3 - toeCurve * 1.1]);
  }

  // Solid wash passes for the glacier-white & ice-blue polymer body
  brush.noStroke();
  brush.wash(PALETTE.handle.shade, 235);
  brush.beginShape(0.3);
  for (const pt of topEdge) brush.vertex(pt[0], pt[1]);
  for (let i = botEdge.length - 1; i >= 0; i--) brush.vertex(botEdge[i][0], botEdge[i][1]);
  brush.endShape(true);

  // Upper deck plane (lit glacier white)
  brush.wash(PALETTE.handle.lit, 245);
  brush.beginShape(0.3);
  for (const pt of topEdge) brush.vertex(pt[0], pt[1]);
  for (let i = midBevel.length - 1; i >= 0; i--) brush.vertex(midBevel[i][0], midBevel[i][1]);
  brush.endShape(true);
  brush.noWash();

  // Opaque marker modeling across the ergonomic handle bevels
  for (let f = 0; f <= 1.0; f += 0.1) {
    const row = [];
    for (let i = 0; i < midBevel.length; i++) {
      row.push([
        lerp(midBevel[i][0], botEdge[i][0], f),
        lerp(midBevel[i][1], botEdge[i][1], f)
      ]);
    }
    const col = f < 0.35 ? PALETTE.handle.mid : f < 0.75 ? PALETTE.handle.shade : PALETTE.handle.deep;
    brush.set("piping_body", col, 1.15);
    safeSpline(row, 0.5);
  }

  // Top deck surface marker sheen
  for (let f = 0.08; f <= 0.92; f += 0.12) {
    const row = [];
    for (let i = 0; i < topEdge.length; i++) {
      row.push([
        lerp(topEdge[i][0], midBevel[i][0], f),
        lerp(topEdge[i][1], midBevel[i][1], f)
      ]);
    }
    brush.set("opaque_marker", f < 0.5 ? PALETTE.handle.lit : PALETTE.handle.highlight, 1.05);
    safeSpline(row, 0.5);
  }

  // Confectionery mint elastomer inlay strip along the side bevel
  const inlayTop = [];
  const inlayBot = [];
  for (let i = 2; i < midBevel.length - 2; i++) {
    inlayTop.push([
      lerp(midBevel[i][0], botEdge[i][0], 0.22),
      lerp(midBevel[i][1], botEdge[i][1], 0.22)
    ]);
    inlayBot.push([
      lerp(midBevel[i][0], botEdge[i][0], 0.48),
      lerp(midBevel[i][1], botEdge[i][1], 0.48)
    ]);
  }
  brush.set("opaque_marker", PALETTE.handle.mintInlayShade, 0.95);
  safeSpline(inlayBot, 0.5);
  brush.set("opaque_marker", PALETTE.handle.mintInlay, 1.1);
  safeSpline(inlayTop, 0.5);
  brush.set("piping_ridge", PALETTE.handle.mintInlayLit, 0.75);
  safeSpline(inlayTop, 0.5);

  // Specular white highlight along the upper bevel ridge of the toothbrush head
  brush.set("piping_ridge", "#ffffff", 1.1);
  safeSpline(midBevel.slice(1, midBevel.length - 1), 0.5);
  brush.set("pen", PALETTE.handle.deep, 0.55);
  safeSpline(botEdge.slice(1, botEdge.length - 1), 0.5);
}

// ============================================================================
// 3. TRANSLUCENT BLUE BRISTLES (FINE PARALLEL PEN STROKES & GLINTING TIPS)
// ============================================================================

function drawBristleForest(fgBristleQueue) {
  // 3 staggered rows of tuft bundles spanning the brush deck
  const rows = [
    { rowIdx: 0, count: 12, xStart: 185, xEnd: 1020, yOffset: -26, baseH: 285 },
    { rowIdx: 1, count: 13, xStart: 160, xEnd: 1045, yOffset: -4, baseH: 295 },
    { rowIdx: 2, count: 12, xStart: 180, xEnd: 1025, yOffset: 18, baseH: 290 }
  ];

  for (const r of rows) {
    for (let t = 0; t < r.count; t++) {
      const u = t / (r.count - 1);
      const cx = lerp(r.xStart, r.xEnd, u);
      const cy = getDeckCenterY(cx) + r.yOffset;

      // Draw embedded elliptical tuft socket in the toothbrush deck
      brush.set("opaque_marker", PALETTE.handle.socketDark, 0.55);
      brush.arc(cx, cy + 2, 26, 0, 180);
      brush.set("pen", PALETTE.handle.socketRim, 0.5);
      brush.arc(cx, cy + 4, 28, 15, 165);

      // Determine tuft splay & compression from the heavy toothpaste ribbon above
      const distFromCenter = (u - 0.5) * 2; // -1 to +1
      const underPaste = u >= 0.04 && u <= 0.96;
      const tuftLean = distFromCenter * 5.5 + (r.rowIdx - 1) * 1.2;

      // Number of fine parallel pen filaments per tuft
      const nFilaments = 46;
      for (let f = 0; f < nFilaments; f++) {
        const fu = (f / (nFilaments - 1)) * 2 - 1; // -1 to +1 across tuft width
        const xBase = cx + fu * 22 + random(-1.2, 1.2);
        const yBase = cy + abs(fu) * 3.5 + random(-1.5, 1.5);

        // Fanning angle: fine parallel strokes that gently fan outward toward the top
        const fanAngle = -90 + tuftLean + fu * 7.2 + random(-0.6, 0.6);
        // Crown profile at top of each tuft
        const domeProfile = cos(fu * 55) * 14;
        const waveMod = sin(u * 540 + r.rowIdx * 40) * 10;
        const h = r.baseH + domeProfile + waveMod + random(-4, 4);

        const rad = radians(fanAngle);
        let xTip = xBase + cos(rad) * h;
        let yTip = yBase + sin(rad) * h;

        // Slight elastic deflection near the top where paste presses down
        const xMid = lerp(xBase, xTip, 0.62) + random(-0.8, 0.8);
        const yMid = lerp(yBase, yTip, 0.62);
        if (underPaste) {
          xTip += (fu * 6.5 + distFromCenter * 5.0);
          yTip += 7.0;
        }

        // Translucent blue color selection based on depth & lateral position in tuft
        let baseCol, upperCol;
        if (r.rowIdx === 0) {
          baseCol = abs(fu) < 0.4 ? PALETTE.bristle.shadowMid : PALETTE.bristle.cobalt;
          upperCol = abs(fu) > 0.65 ? PALETTE.bristle.cyanBright : PALETTE.bristle.azure;
        } else if (r.rowIdx === 1) {
          baseCol = abs(fu) < 0.35 ? PALETTE.bristle.cobalt : PALETTE.bristle.azure;
          upperCol = abs(fu) > 0.55 ? PALETTE.bristle.aquaLight : PALETTE.bristle.cyanBright;
        } else {
          baseCol = abs(fu) < 0.3 ? PALETTE.bristle.azure : PALETTE.bristle.cyanMid;
          upperCol = abs(fu) > 0.45 ? PALETTE.bristle.iceRim : PALETTE.bristle.aquaLight;
        }

        // 1. Lower to upper bristle shaft (fine parallel pen stroke)
        const brushChoice = f % 3 === 0 ? "bristle_pen" : f % 2 === 0 ? "pen" : "rotring";
        const strokeW = r.rowIdx === 2 ? 0.58 : 0.48;
        brush.set(brushChoice, baseCol, strokeW);
        safeSpline([[xBase, yBase], [xMid, yMid], [xTip, yTip]], 0.35);

        // 2. Translucent refractive upper half of filament
        brush.set("pen", upperCol, strokeW * 0.85);
        safeSpline([[xMid, yMid], [lerp(xMid, xTip, 0.5), lerp(yMid, yTip, 0.5)], [xTip, yTip]], 0.3);

        // 3. Cast shadow darkening near the top of middle/back bristles under the paste
        if (underPaste && r.rowIdx <= 1 && abs(fu) < 0.75) {
          const sx1 = lerp(xMid, xTip, 0.35);
          const sy1 = lerp(yMid, yTip, 0.35);
          brush.set("pen", PALETTE.bristle.shadowCore, 0.52);
          brush.line(sx1, sy1, xTip, yTip);
        }

        // 4. Glinting tips on unoccluded & front-row bristles
        if (!underPaste || r.rowIdx === 2 || abs(fu) > 0.72) {
          drawBristleTipGlint(xTip, yTip, fanAngle, r.rowIdx === 2);
        }

        // Queue select front-row bristle tips to overlap in front of the lowest paste beads
        if (r.rowIdx === 2 && f % 2 === 0) {
          fgBristleQueue.push({
            x1: lerp(xMid, xTip, 0.45),
            y1: lerp(yMid, yTip, 0.45),
            x2: xTip,
            y2: yTip - random(4, 14),
            col: upperCol,
            angle: fanAngle
          });
        }
      }
    }
  }
}

function drawBristleTipGlint(x, y, angleDeg, isFront) {
  const rad = radians(angleDeg);
  const dx = cos(rad);
  const dy = sin(rad);

  // Translucent cyan-aqua halo at the rounded tip
  brush.set("pen", PALETTE.bristle.tipHalo, isFront ? 0.75 : 0.55);
  brush.line(x - dx * 7, y - dy * 7, x, y);

  // Crisp pure white optical glint at the hemispherical nylon tip
  brush.set("rotring", PALETTE.bristle.tipGlint, isFront ? 0.85 : 0.6);
  brush.line(x - dx * 3.2, y - dy * 3.2, x + dx * 0.8, y + dy * 0.8);
}

function drawPasteOnBristlesShadow() {
  // Deep cool sapphire cast shadow band where the wedding-cake paste sits on the bristles
  const shadowSpine = [];
  for (let i = 0; i <= 24; i++) {
    const t = i / 24;
    const x = lerp(165, 1025, t);
    const baseY = map(x, 165, 1025, 650, 580) + sin(t * 900) * 16;
    shadowSpine.push([x, baseY]);
  }

  for (let d = 0; d < 5; d++) {
    const col = d < 2 ? PALETTE.bristle.shadowCore : d < 4 ? PALETTE.bristle.shadowMid : PALETTE.bristle.shadowSoft;
    brush.set("soft_shadow", col, 1.35 - d * 0.15);
    const shifted = shadowSpine.map(p => [p[0], p[1] + d * 11]);
    safeSpline(shifted, 0.5);
  }
}

function drawForegroundBristleTips(fgBristleQueue) {
  // Fine translucent bristle tips peeking up in front of the lower paste cushion
  for (const b of fgBristleQueue) {
    brush.set("bristle_pen", b.col, 0.52);
    brush.line(b.x1, b.y1, b.x2, b.y2);

    brush.set("pen", PALETTE.bristle.iceRim, 0.45);
    brush.line(lerp(b.x1, b.x2, 0.55), lerp(b.y1, b.y2, 0.55), b.x2, b.y2);

    drawBristleTipGlint(b.x2, b.y2, b.angle, true);
  }
}

