function drawTier2MiddlePiping() {
  // 1. Deep cast shadow from Tier 2 onto the crown of Tier 1
  const t2ShadowSpine = [];
  for (let i = 0; i <= 24; i++) {
    const t = i / 24;
    const x = lerp(225, 965, t);
    const y = map(x, 225, 965, 515, 455) + sin(t * 720) * 18;
    t2ShadowSpine.push([x, y]);
  }
  for (let s = 0; s < 4; s++) {
    brush.set("soft_shadow", s < 2 ? PALETTE.shadow.castDark : PALETTE.shadow.castMid, 1.3 - s * 0.2);
    safeSpline(t2ShadowSpine.map(p => [p[0] + 4, p[1] + 10 + s * 6]), 0.5);
  }

  // 2. Ornamental sugar-pearl bead chain nestled in the valley between Tier 1 and Tier 2
  const pearlColors = ["white", "pink", "mint", "white", "mint", "pink"];
