  // Right shoulder ornamental piped rosette turn at (945, 445)
  drawPipedRosetteKnot(948, 446, 36, ["mint", "white", "pink", "white", "mint"]);
  // Left shoulder ornamental piped rosette turn at (218, 515)
  drawPipedRosetteKnot(218, 514, 34, ["pink", "white", "mint", "white", "pink"]);
}

function drawPipedRosetteKnot(cx, cy, radius, stripeTypes) {
  // Soft shadow under the rosette knot
  brush.set("soft_shadow", PALETTE.shadow.castDark, 1.1);
  brush.circle(cx + 5, cy + 10, radius * 1.1, 0.2);

  // Coiling spiral petals of raised marker
  const nPetals = 6;
  for (let i = 0; i < nPetals; i++) {
    const ang1 = i * (360 / nPetals);
    const ang2 = ang1 + 115;
    const col = stripeTypes[i % stripeTypes.length];
    const pts = [];
    const widths = [];
    for (let s = 0; s <= 10; s++) {
      const f = s / 10;
      const a = radians(lerp(ang1, ang2, f));
      const r = lerp(radius * 0.95, radius * 0.22, f);
      pts.push([cx + cos(a) * r, cy + sin(a) * r]);
      widths.push(lerp(11, 5, f));
    }
    drawRaisedMarkerRidge(pts, widths, col, {
      castShadow: true,
      shadowDX: 3,
      shadowDY: 6,
      beadStart: true
    });
  }
  // Center sugar pearl
  drawRoundedBead(cx, cy, 10.5, "white", true);
}

