// 8. TIER 3: UPPER CRESTING WAVE & ICONIC CURLED TOOTHPASTE PEAK ("NURDLE")
// ============================================================================

function drawTier3CrownSwirl() {
  // 1. Upper-tier pearl bead garland along the shoulder of Tier 2
  const garlandTypes = ["mint", "white", "pink"];
  for (let i = 0; i < 16; i++) {
    const u = i / 15;
    const gx = lerp(310, 860, u);
    const gy = map(gx, 310, 860, 432, 385) + sin(u * 720) * 8;
    drawRoundedBead(gx, gy, 8.2, garlandTypes[i % 3], true);
  }

  // 2. Two lush supporting scalloped coils forming the pedestal of Tier 3
  const t3SupportStripes = ["mint", "white", "pink", "white", "mint", "pink", "white"];
  drawScallopCoilSegment(
    [465, 382],
    [412, 352],
    [358, 362],
    [315, 412],
    44, 56, 30,
    t3SupportStripes,
    { shadowDX: 5, shadowDY: 12, beadHead: true }
  );

  drawScallopCoilSegment(
    [615, 365],
    [555, 332],
    [495, 340],
    [445, 386],
    48, 60, 36,
    t3SupportStripes,
    { shadowDX: 5, shadowDY: 12, beadHead: true }
  );

  // 3. The Grand Sweeping Toothpaste Wave & Curled Finial Peak ("The Nurdle")
  // Coils from (565, 368) up and right to (775, 295), then curls back and flicks up to a razor-sharp glossy peak at (848, 198)!
  const nurdleSpine = [];
  const nurdleWidths = [];
  const p0 = [555, 372];
  const p1 = [685, 365];
  const p2 = [795, 315];
  const p3 = [755, 255];

  const q0 = [755, 255];
  const q1 = [720, 205];
  const q2 = [790, 185];
  const q3 = [855, 212];

  const segSteps = 22;
  for (let i = 0; i <= segSteps; i++) {
    const t = i / segSteps;
    nurdleSpine.push(evalCubicBezier(p0, p1, p2, p3, t));
    // Swells at the belly of the wave, then begins tapering into the curl
    const w = lerp(54, 38, t) + sin(t * 180) * 12;
    nurdleWidths.push(w);
  }
  for (let i = 1; i <= segSteps; i++) {
    const t = i / segSteps;
    nurdleSpine.push(evalCubicBezier(q0, q1, q2, q3, t));
    // Smooth exponential taper to a delicate pointed tip at the end of the curl
    const w = lerp(38, 2.5, pow(t, 0.82));
    nurdleWidths.push(w);
  }

  const nurdleNormals = computeSpineNormals(nurdleSpine);

  // Cast shadow of the grand curl onto Tier 2 & the background glow
  for (let s = -0.6; s <= 0.8; s += 0.35) {
    const shPts = offsetSpine(nurdleSpine, nurdleNormals, nurdleWidths, s, 7, 16);
    brush.set("soft_shadow", PALETTE.shadow.castMid, 1.1);
    safeSpline(shPts, 0.5);
  }

  // Render the 9 raised tricolor toothpaste ridges along the entire curling finial
  const crownStripes = ["mint", "mint", "white", "white", "pink", "pink", "white", "mint", "pink"];
  const nCrown = crownStripes.length;
  for (let idx = nCrown - 1; idx >= 0; idx--) {
    const sCenter = map(idx, 0, nCrown - 1, -0.86, 0.86);
    const rFactor = 1.08 / nCrown;
    const rPts = [];
    const rWidths = [];
    for (let i = 0; i < nurdleSpine.length; i++) {
      const tw = nurdleWidths[i];
      rPts.push([
        nurdleSpine[i][0] + nurdleNormals[i][0] * tw * sCenter,
        nurdleSpine[i][1] + nurdleNormals[i][1] * tw * sCenter
      ]);
      rWidths.push(max(1.8, tw * rFactor));
    }

    drawRaisedMarkerRidge(rPts, rWidths, crownStripes[idx], {
      castShadow: idx >= nCrown - 2,
      shadowDX: 4,
      shadowDY: 9,
      beadStart: true,
      beadEnd: false
    });
  }

  // Plump rounded bead collar at the base of the grand nurdle wave
  for (let idx = 0; idx < nCrown; idx++) {
    const sCenter = map(idx, 0, nCrown - 1, -0.86, 0.86);
    const bx = nurdleSpine[0][0] + nurdleNormals[0][0] * nurdleWidths[0] * sCenter;
    const by = nurdleSpine[0][1] + nurdleNormals[0][1] * nurdleWidths[0] * sCenter;
    drawRoundedBead(bx, by, 7.5, crownStripes[idx], true);
  }
}

