}

// ============================================================================
// SCENE GEOMETRY & 3D OPTICAL MODEL
// ============================================================================
function buildSceneGeometry() {
  // 1. Five Pentaradial Coral-Orange Roe Lobes (Uni)
  const baseAngles = [-1.55, -0.30, 0.96, 2.20, 3.45]; // radians (~ -89, -17, 55, 126, 198 deg)
  const lobeLengths = [164, 168, 160, 165, 162];
  const lobeWidths = [43, 45, 42, 44, 43];
  const lobeCurves = [0.07, -0.05, 0.06, -0.06, 0.05];

  for (let i = 0; i < 5; i++) {
    roeLobes.push({
      id: i,
      angle: baseAngles[i],
      rMin: 17,
      rMax: lobeLengths[i],
      maxHalfWidth: lobeWidths[i],
      curve: lobeCurves[i],
      cosA: Math.cos(baseAngles[i]),
      sinA: Math.sin(baseAngles[i])
    });
  }

  // 2. Broken Shell Shard in lower-right crushed ice
  shard = {
    x: 875,
    y: 870,
    radius: 78,
    angle: 0.65,
    spines: []
  };
  for (let i = 0; i < 13; i++) {
    let a = -0.35 + (i / 12) * 2.05 + random(-0.04, 0.04);
    let r0 = 62 + random(-5, 5);
    let r1 = r0 + random(58, 105);
    shard.spines.push({
      x0: shard.x + Math.cos(a) * r0,
      y0: shard.y + Math.sin(a) * r0 * 0.85,
      x1: shard.x + Math.cos(a) * r1,
      y1: shard.y + Math.sin(a) * r1 * 0.85,
      angle: a,
      w0: random(11, 14),
      w1: random(3.5, 4.8)
    });
  }

  // 3. Loose detached spines resting on the crushed ice
  const looseData = [
    { x: 345, y: 895, a: 2.45, len: 125, w: 12 },
    { x: 455, y: 975, a: 1.95, len: 115, w: 11.5 },
    { x: 685, y: 965, a: 1.25, len: 130, w: 12.5 },
    { x: 275, y: 765, a: 2.85, len: 110, w: 11 },
    { x: 965, y: 720, a: 0.35, len: 118, w: 11.5 },
    { x: 770, y: 990, a: 0.88, len: 105, w: 10.5 }
  ];
  for (let ld of looseData) {
    looseSpines.push({
      x0: ld.x,
      y0: ld.y,
      x1: ld.x + Math.cos(ld.a) * ld.len,
      y1: ld.y + Math.sin(ld.a) * ld.len,
      angle: ld.a,
      w0: ld.w,
      w1: 3.8
    });
  }

  // 4. Radiating Sea Urchin Spines in 3 Overlapping Canopy Tiers
  // Tier 2 (Upper shorter foreshortened crown near rim)
  const nUpper = 28;
  for (let i = 0; i < nUpper; i++) {
    let a = (i / nUpper) * Math.PI * 2 + random(-0.035, 0.035);
    let r0 = getShellOuterRadius(a) - random(12, 22);
    let r1 = r0 + random(85, 125) * getPerspectiveYScale(a);
    let curve = random(-0.06, 0.06);
    spines.push({
      tier: 2,
      angle: a,
      r0: r0,
      r1: r1,
      curve: curve,
      w0: random(13.5, 16.5),
      w1: random(4.0, 5.2),
      litBias: random(-0.08, 0.08)
    });
  }

  // Tier 1 (Middle canopy)
  const nMid = 38;
  for (let i = 0; i < nMid; i++) {
    let a = ((i + 0.5) / nMid) * Math.PI * 2 + random(-0.03, 0.03);
    let r0 = getShellOuterRadius(a) - random(4, 12);
    let r1 = r0 + random(135, 185) * getPerspectiveYScale(a);
    let curve = random(-0.07, 0.07);
    spines.push({
      tier: 1,
      angle: a,
      r0: r0,
      r1: r1,
      curve: curve,
      w0: random(15, 18),
      w1: random(4.2, 5.5),
      litBias: random(-0.08, 0.08)
    });
  }

  // Tier 0 (Basal longest spines resting on ice)
  const nBase = 44;
  for (let i = 0; i < nBase; i++) {
    let a = (i / nBase) * Math.PI * 2 + random(-0.025, 0.025);
    let r0 = getShellOuterRadius(a) + random(0, 8);
    let r1 = r0 + random(175, 230) * getPerspectiveYScale(a);
    let curve = random(-0.08, 0.08);
    spines.push({
      tier: 0,
      angle: a,
      r0: r0,
      r1: r1,
      curve: curve,
      w0: random(16, 19.5),
      w1: random(4.5, 5.8),
      litBias: random(-0.08, 0.08)
    });
  }

  // 5. Voronoi Crushed Ice Chunks across the ice bed
  // Generate crystal centers in rings from the spine tips outward across the ice bed
  for (let r = 360; r <= 620; r += 52) {
    let count = Math.floor((2 * Math.PI * r) / 56);
    for (let i = 0; i < count; i++) {
      let a = (i / count) * Math.PI * 2 + random(-0.06, 0.06);
      let cx = UX + Math.cos(a) * r * 1.04 + random(-16, 16);
      let cy = UY + 55 + Math.sin(a) * r * 0.96 + random(-16, 16);
      if (isInsideIceBed(cx, cy)) {
        addIceChunk(cx, cy, r, a);
      }
    }
  }
  // Additional foreground ice chunks in lower corners/apron
  for (let i = 0; i < 36; i++) {
    let cx = random(90, CW - 90);
    let cy = random(640, CH - 65);
    if (isInsideIceBed(cx, cy)) {
      let dx = cx - UX;
      let dy = cy - UY;
      addIceChunk(cx, cy, Math.hypot(dx, dy), Math.atan2(dy, dx));
    }
  }
}

function addIceChunk(cx, cy, rFromUrchin, angleFromUrchin) {
  // Avoid placing too close to existing chunk centers
  for (let ch of iceChunks) {
    if (Math.hypot(cx - ch.x, cy - ch.y) < 34) return;
  }
  // Each chunk has a primary cleavage orientation & 3 crystal facet normals
  let baseAngle = angleFromUrchin + Math.PI * 0.5 + random(-0.65, 0.65);
  let tiltX = random(-0.75, 0.75);
  let tiltY = random(-0.75, 0.75);
  iceChunks.push({
    x: cx,
    y: cy,
    baseAngle: baseAngle,
    ridgeAngle: baseAngle + random(-0.35, 0.35),
    nx: tiltX,
    ny: tiltY,
    nz: Math.sqrt(Math.max(0.15, 1.0 - tiltX * tiltX * 0.4 - tiltY * tiltY * 0.4)),
    size: random(32, 62),
    sparkle: random(0, 1)
  });
}

// ============================================================================
// SHAPE & BOUNDARY HELPERS
// ============================================================================
function getPerspectiveYScale(angle) {
  // Slight foreshortening on upper half, slight expansion toward foreground
  return 0.94 + 0.09 * Math.sin(angle);
}

function getShellInnerRadius(angle) {
  // Brittle jagged fracture contour around the cracked-open top of the urchin test
  return (
    178 +
    11 * Math.sin(5 * angle + 0.35) +
    7.5 * Math.cos(11 * angle - 0.8) +
    5.5 * Math.sin(17 * angle + 1.2) +
    4.0 * Math.cos(23 * angle - 0.4)
  );
}

function getShellOuterRadius(angle) {
  return (
    236 +
    7 * Math.cos(5 * angle - 0.2) +
    4.5 * Math.sin(10 * angle + 0.6)
  ) * getPerspectiveYScale(angle);
}

function getSpineHaloEnvelope(angle) {
  // Scalloped contour hugging the tips of the radiating spines like a saint's halo
  let baseR = 415 * getPerspectiveYScale(angle);
  let scallop =
    18 * Math.cos(14 * angle + 0.2) +
    12 * Math.sin(22 * angle - 0.5) +
    9 * Math.cos(36 * angle + 0.9);
  return baseR + scallop;
}

function isInsideIceBed(x, y) {
  // The bed of crushed ice cradles the urchin, filling the middle and lower foreground
  // while leaving the upper arch and outer deep corners as the deep cobalt ground
  let dx = (x - 600) / 545;
  let dy = (y - 685) / 485;
  let warp =
    0.08 * Math.sin(Math.atan2(y - UY, x - UX) * 5 + 0.4) +
    0.05 * Math.cos(Math.atan2(y - UY, x - UX) * 9 - 0.7);
  let d2 = dx * dx + dy * dy;
  // Slightly tighter at the top so the deep cobalt halo ground frames the upper crown
  if (y < UY) {
    let dyTop = (y - 595) / 365;
    let dxTop = (x - 595) / 490;
    return dxTop * dxTop + dyTop * dyTop < 1.0 + warp;
  }
  return d2 < 1.06 + warp;
}

// ============================================================================
// OCCUPANCY GRID & TESSERA REGISTRATION
// ============================================================================
function canPlaceTessera(x, y, halfLen, halfW, angle, clearance = 1.6) {
  if (x < 14 || x > CW - 14 || y < 14 || y > CH - 14) return false;
  let cosA = Math.cos(angle);
  let sinA = Math.sin(angle);
  let ex = halfLen + clearance;
  let ey = halfW + clearance;

  // Sample 9 points across the oriented bounding box of the tessera
  for (let u = -1; u <= 1; u++) {
    for (let v = -1; v <= 1; v++) {
      let px = x + u * ex * cosA - v * ey * sinA;
      let py = y + u * ex * sinA + v * ey * cosA;
      let gx = Math.floor(px / GRID_SCALE);
      let gy = Math.floor(py / GRID_SCALE);
      if (gx < 0 || gx >= GW || gy < 0 || gy >= GH) return false;
      if (occGrid[gy * GW + gx] !== 0) return false;
    }
  }
  return true;
}

function markTesseraOccupied(x, y, halfLen, halfW, angle, pad = 1.1) {
  let cosA = Math.cos(angle);
  let sinA = Math.sin(angle);
  let ex = halfLen + pad;
  let ey = halfW + pad;
  let maxR = Math.ceil(Math.hypot(ex, ey) / GRID_SCALE);
  let cx = Math.floor(x / GRID_SCALE);
  let cy = Math.floor(y / GRID_SCALE);

  for (let dy = -maxR; dy <= maxR; dy++) {
    let gy = cy + dy;
    if (gy < 0 || gy >= GH) continue;
    let py = (gy + 0.5) * GRID_SCALE - y;
    for (let dx = -maxR; dx <= maxR; dx++) {
      let gx = cx + dx;
      if (gx < 0 || gx >= GW) continue;
      let px = (gx + 0.5) * GRID_SCALE - x;
      let lx = Math.abs(px * cosA + py * sinA);
      let ly = Math.abs(-px * sinA + py * cosA);
      if (lx <= ex && ly <= ey) {
        occGrid[gy * GW + gx] = 1;
      }
    }
  }
}

function addTessera(opts) {
  let {
    x,
    y,
    len,
    w,
    angle,
    color,
    glintColor = null,
    shadowColor = null,
    isWedge = false,
    isGold = false,
    groutColor = "#1b2230",
    askewMax = 0.11, // ~6.3 degrees
    clearance = 1.4,
    pad = 1.0
  } = opts;

  let halfLen = len * 0.5;
  let halfW = w * 0.5;
  if (!canPlaceTessera(x, y, halfLen, halfW, angle, clearance)) return false;

  markTesseraOccupied(x, y, halfLen, halfW, angle, pad);

  let askew = random(-askewMax, askewMax);
  tesserae.push({
    x,
    y,
    len,
    w,
    angle: angle + askew,
    courseAngle: angle,
    color,
    glintColor,
    shadowColor,
    isWedge,
    isGold,
    groutColor
  });
  return true;
}

// ============================================================================
// REGION 1: FIVE GLISTENING CORAL-ORANGE ROE LOBES (UNI)
// ============================================================================
function generateRoeTesserae() {
  // Key light from upper-left (-0.52, -0.58, 0.63)
  const lx = -0.52;
  const ly = -0.58;
  const lz = 0.63;

  for (let lobe of roeLobes) {
    // Lay concentric longitudinal courses from outer margin (ringFrac = 0.94) to central rachis (ringFrac = 0.0)
    const ringSteps = [0.92, 0.72, 0.52, 0.32, 0.12];

    for (let rIdx = 0; rIdx < ringSteps.length; rIdx++) {
      let ringFrac = ringSteps[rIdx];
      let sides = ringFrac < 0.18 ? [0] : [-1, 1];

      for (let side of sides) {
        let uFrac = side * ringFrac;
        let stepR = 7.4;
        let prevX = null;
        let prevY = null;

        for (let r = lobe.rMin + 4; r <= lobe.rMax - 4; r += stepR) {
          let t = (r - lobe.rMin) / (lobe.rMax - lobe.rMin);
          if (t <= 0.02 || t >= 0.98) continue;

          // Plump almond profile of sea urchin gonad lobe
          let env = 2.08 * Math.pow(t, 0.52) * Math.pow(1.0 - t, 0.46);
          let halfW = lobe.maxHalfWidth * env;
          let lateralOffset = uFrac * halfW;

          if (side !== 0 && Math.abs(lateralOffset) < 3.2) continue;

          // Slight organic S-curve along lobe axis
          let spineCurve = lobe.curve * r * Math.sin(t * Math.PI);
          let localX = r;
          let localY = lateralOffset + spineCurve;

          let wx = UX + localX * lobe.cosA - localY * lobe.sinA;
          let wy = UY + localX * lobe.sinA + localY * lobe.cosA;

          // Compute tangent direction along the contour loop
          let dt = 0.02;
          let t2 = Math.min(0.99, t + dt);
          let env2 = 2.08 * Math.pow(t2, 0.52) * Math.pow(1.0 - t2, 0.46);
          let dyLocal = uFrac * lobe.maxHalfWidth * (env2 - env) / (dt * (lobe.rMax - lobe.rMin));
          let tangentAngle = lobe.angle + Math.atan2(dyLocal, 1.0);

          // 3D surface normal of the plump roe lobe with central longitudinal groove
          let grooveDip = 0.22 * Math.exp(-(uFrac * uFrac) / 0.035);
          let dGrooveDu = -0.22 * (-2 * uFrac / 0.035) * Math.exp(-(uFrac * uFrac) / 0.035);
          let slopeU = -1.15 * uFrac + dGrooveDu * 0.18;
          let slopeT = (0.5 - t) * 1.1;

          // World normal
          let nxLocal = slopeT;
          let nyLocal = -slopeU;
          let nz = 0.78;
          let nx = nxLocal * lobe.cosA - nyLocal * lobe.sinA;
          let ny = nxLocal * lobe.sinA + nyLocal * lobe.cosA;
          let nLen = Math.hypot(nx, ny, nz);
          nx /= nLen;
          ny /= nLen;
          nz /= nLen;

          let diff = Math.max(0, nx * lx + ny * ly + nz * lz);
          // Half-vector for wet specular sheen on roe follicles
          let hx = lx;
          let hy = ly;
          let hz = lz + 1.0;
          let hLen = Math.hypot(hx, hy, hz);
          let spec = Math.pow(Math.max(0, (nx * hx + ny * hy + nz * hz) / hLen), 16);

          // Granular papillae variation
          let gran = noise(wx * 0.09, wy * 0.09) * 0.16 - 0.08;
          let lum = diff + gran - grooveDip * 0.55;

          let col, glintCol = null, shadCol = null, isGold = false;

          if (spec > 0.54 && ringFrac > 0.2 && ringFrac < 0.78) {
            // Wet glistening specular highlight ribbon along the plump ridge
            isGold = random() < 0.65;
            col = isGold
              ? random(["#ffd23f", "#ffe36e", "#ffbe26", "#fff1a8"])
              : random(["#fff6cf", "#ffebb3", "#fffdf2"]);
            glintCol = "#ffffff";
            shadCol = "#e07a14";
          } else if (lum > 0.66) {
            // Radiant lit tangerine-marigold smalti
            col = random(["#ff8c1a", "#ff9f1c", "#ffb224", "#ff7b14", "#ffa821"]);
            glintCol = random(["#ffd152", "#ffe380"]);
            shadCol = "#c9410c";
          } else if (lum > 0.44) {
            // Vivid coral-orange & persimmon body smalti
            col = random(["#ff6212", "#f5500e", "#ff7017", "#e6410b", "#fc5a12"]);
            glintCol = random() < 0.5 ? "#ff9b26" : null;
            shadCol = "#9e1f08";
          } else if (lum > 0.24) {
            // Rich vermilion, blood-orange & scarlet smalti
            col = random(["#cc2c0a", "#b52109", "#d9360b", "#9e190b", "#c2260c"]);
            shadCol = "#5c090c";
          } else {
            // Deep garnet-crimson tucked margin & central crease smalti
            col = random(["#7d1110", "#630b0e", "#4d060b", "#8c1612"]);
            shadCol = "#2b0206";
          }

          let tessW = map(ringFrac, 0, 1, 5.8, 6.8) + random(-0.4, 0.4);
          let tessL = stepR * 0.74 + random(-0.5, 0.5);
          let isWedge = t < 0.18 || t > 0.84 || random() < 0.25;

          if (
            addTessera({
              x: wx,
              y: wy,
              len: tessL,
              w: tessW,
              angle: tangentAngle,
              color: col,
              glintColor: glintCol,
              shadowColor: shadCol,
              isWedge: isWedge,
              isGold: isGold,
              groutColor: "#26080c",
              askewMax: 0.10,
              clearance: 1.05,
              pad: 0.85
            })
          ) {
            if (prevX !== null) {
              groutLines.push({ x1: prevX, y1: prevY, x2: wx, y2: wy, col: "#24090e", w: 0.55 });
            }
            prevX = wx;
            prevY = wy;
          }
        }
      }
    }
  }
}

// ============================================================================
// REGION 2: DARK COELOMIC CAVITY & AMBULACRAL PORE CHANNELS
// ============================================================================
function generateCavityTesserae() {
  // Concentric concave rings inside the cracked shell opening between the 5 roe lobes
  for (let r = 10; r <= 186; r += 8.2) {
    let circum = Math.max(18, Math.floor((2 * Math.PI * r) / 8.2));
    for (let i = 0; i < circum; i++) {
      let a = (i / circum) * Math.PI * 2 + random(-0.02, 0.02);
      let maxR = getShellInnerRadius(a) - 3;
      if (r > maxR) continue;

      let wx = UX + Math.cos(a) * r;
      let wy = UY + Math.sin(a) * r;
      let tangentAngle = a + Math.PI * 0.5;

      // Check angular proximity to the 5 inter-lobe ambulacral midlines
      // Lobe angles are [-1.55, -0.30, 0.96, 2.20, 3.45]; midlines are offset by +0.628 rad (36 deg)
      let ambDist = 999;
      for (let k = 0; k < 5; k++) {
        let midA = -1.55 + 0.628 + k * ((Math.PI * 2) / 5);
        let da = Math.abs( Math.atan2(Math.sin(a - midA), Math.cos(a - midA)) );
        if (da < ambDist) ambDist = da;
      }

      let col, glintCol = null, shadCol = "#0a0207", isGold = false;

      if (ambDist < 0.075 && r > 32 && r < maxR - 10 && i % 2 === 0) {
        // Delicate pale mauve/rose radial ambulacral pore-pair tesserae & wet meniscus glints
        col = random(["#7d3562", "#964678", "#63224c", "#ad588d"]);
        if (random() < 0.35) {
          glintCol = random(["#f0c4e0", "#ffe596"]);
        }
      } else {
        // Deep wet abyssal garnet-black & oxblood-aubergine cavity smalti
        let lightSide = Math.cos(a - 0.75); // upper-left illumination hitting lower-right inner bowl
        if (lightSide > 0.35 && r > 90) {
          col = random(["#380a22", "#4a0f2d", "#5c1438", "#2b071a"]);
          if (random() < 0.14) {
            // Wet coelomic fluid specular pinprick
            glintCol = random(["#ffd97d", "#f5c6e8"]);
          }
        } else {
          col = random(["#14030c", "#1f0513", "#29071a", "#1a040e", "#30091e"]);
        }
      }

      addTessera({
        x: wx,
        y: wy,
        len: 6.4 + random(-0.5, 0.5),
        w: 6.2 + random(-0.4, 0.4),
        angle: tangentAngle,
        color: col,
        glintColor: glintCol,
        shadowColor: shadCol,
        isWedge: random() < 0.3,
        isGold: isGold,
        groutColor: "#12030a",
        askewMax: 0.12,
        clearance: 1.0,
        pad: 0.85
      });
    }
  }
}

// ============================================================================
// REGION 3: CRACKED CALCAREOUS SHELL RIM & TEST DOME
// ============================================================================
function generateShellRimAndTestTesserae() {
  // 1. Two tight contour-following courses along the brittle fractured calcareous rim
  for (let course = 0; course < 2; course++) {
    let rOffset = course * 8.2;
    let steps = 148;
    let prevX = null, prevY = null;

    for (let i = 0; i < steps; i++) {
      let a = (i / steps) * Math.PI * 2;
      let r = getShellInnerRadius(a) + 2.5 + rOffset;
      let wx = UX + Math.cos(a) * r;
      let wy = UY + Math.sin(a) * r;

      // Numerical derivative for exact fracture-following tangent
      let da = 0.015;
      let rNext = getShellInnerRadius(a + da) + 2.5 + rOffset;
      let nx = UX + Math.cos(a + da) * rNext;
      let ny = UY + Math.sin(a + da) * rNext;
      let tangentAngle = Math.atan2(ny - wy, nx - wx);

      // Lighting on fractured calcareous shell wall
      let lightDir = Math.cos(a + 2.35); // upper-left key light
      let bevelLight = Math.cos(a - 0.78); // inner rim bevel catching light on lower-right
      let col, glintCol = null;

      if (course === 0) {
        // Inner broken nacreous edge: pale lilac-ivory, dusty rose, pearl violet
        if (lightDir > 0.15 || bevelLight > 0.35) {
          col = random(["#e3c8eb", "#d4b0de", "#edd8f2", "#c496d1", "#deb8e8"]);
          glintCol = "#fbf2ff";
        } else {
          col = random(["#9e6dad", "#835294", "#6b3c7d", "#b082bf"]);
          glintCol = "#d9b8e6";
        }
      } else {
        // Outer rim transition into purple tubercle dome
        if (lightDir > 0.1) {
          col = random(["#b545c7", "#c95dd9", "#9e30b0", "#d676e6"]);
          glintCol = "#f2b8ff";
        } else {
          col = random(["#681878", "#511061", "#7d228f", "#3d0a4a"]);
        }
      }

      if (
        addTessera({
          x: wx,
          y: wy,
          len: 6.8 + random(-0.4, 0.4),
          w: 6.4 + random(-0.4, 0.4),
          angle: tangentAngle,
          color: col,
          glintColor: glintCol,
          shadowColor: "#2b0736",
          isWedge: random() < 0.35,
          groutColor: "#1d0924",
          askewMax: 0.11,
          clearance: 1.0,
          pad: 0.85
        })
      ) {
        if (prevX !== null && Math.hypot(wx - prevX, wy - prevY) < 18) {
          groutLines.push({ x1: prevX, y1: prevY, x2: wx, y2: wy, col: "#1f0b26", w: 0.6 });
        }
        prevX = wx;
        prevY = wy;
      }
    }
  }

  // 2. Spherical shoulder of the purple test (between fractured rim and spine bases)
  for (let band = 0; band < 5; band++) {
    let frac = (band + 0.5) / 5;
    let steps = 160;
    for (let i = 0; i < steps; i++) {
      let a = (i / steps) * Math.PI * 2 + random(-0.01, 0.01);
      let rIn = getShellInnerRadius(a) + 18;
      let rOut = getShellOuterRadius(a) + 6;
      if (rOut <= rIn) continue;
      let r = lerp(rIn, rOut, frac);

      let wx = UX + Math.cos(a) * r;
      let wy = UY + Math.sin(a) * r;
      let tangentAngle = a + Math.PI * 0.5;

      let lightDot = Math.cos(a + 2.35);
      // Periodic calcareous tubercle boss highlights
      let isBoss = Math.sin(a * 25 + band * 1.7) > 0.68;

      let col, glintCol = null;
      if (lightDot > 0.25) {
        col = isBoss
          ? random(["#d96ce8", "#e685f2", "#c74fd9"])
          : random(["#9c27b0", "#ab35bf", "#871d9c", "#b83fc9"]);
        if (isBoss) glintCol = "#f9d6ff";
      } else if (lightDot > -0.3) {
        col = isBoss
          ? random(["#8f249e", "#a130b0", "#751885"])
          : random(["#5c116b", "#4a0c57", "#6e177d", "#3c0847"]);
      } else {
        col = isBoss
          ? random(["#4f0e5e", "#61136b"])
          : random(["#290533", "#1e0326", "#360842", "#16021c"]);
      }

      addTessera({
        x: wx,
        y: wy,
        len: 7.2 + random(-0.5, 0.5),
        w: 6.8 + random(-0.5, 0.5),
        angle: tangentAngle,
        color: col,
        glintColor: glintCol,
        shadowColor: "#14021c",
        isWedge: random() < 0.3,
        groutColor: "#17051f",
        askewMax: 0.11,
        clearance: 1.05,
        pad: 0.9
      });
    }
  }
}

// ============================================================================
// REGION 4: FOREGROUND BROKEN SHELL SHARD & LOOSE SPINES ON ICE
// ============================================================================
function generateShardAndLooseSpinesTesserae() {
  // 1. Broken crescent shard of purple shell resting concave-side up on the foreground ice
  for (let r = 8; r <= shard.radius; r += 8.2) {
    let steps = Math.max(8, Math.floor((2 * Math.PI * r) / 8.0));
    for (let i = 0; i < steps; i++) {
      let a = (i / steps) * Math.PI * 2;
      // Crescent cutout on upper-left of shard
      let cutDist = Math.hypot(
        Math.cos(a) * r + 26,
        Math.sin(a) * r * 0.85 + 22
      );
      if (cutDist < 42) continue;

      let wx = shard.x + Math.cos(a) * r;
      let wy = shard.y + Math.sin(a) * r * 0.85;
      let tangentAngle = a + Math.PI * 0.5;

      let isRim = r > shard.radius - 11 || cutDist < 51;
      let col, glintCol = null;
      if (isRim) {
        col = random(["#d9b2e3", "#c493d1", "#b076bf", "#e8ccf0"]);
        glintCol = "#faf0ff";
      } else if (r > shard.radius - 26) {
        col = random(["#751c85", "#5c126b", "#8a289c", "#470b54"]);
      } else {
        col = random(["#380824", "#4d0d30", "#260418", "#5e133b"]);
      }

      addTessera({
        x: wx,
        y: wy,
        len: 6.8,
        w: 6.4,
        angle: tangentAngle,
        color: col,
        glintColor: glintCol,
        shadowColor: "#1c0424",
        isWedge: true,
        groutColor: "#16071c",
        clearance: 1.0,
        pad: 0.85
      });
    }
  }

  // 2. Spines attached to the shard + loose detached spines on the ice
  let allExtraSpines = shard.spines.concat(looseSpines);
  for (let sp of allExtraSpines) {
    laySingleSpineTesserae(sp.x0, sp.y0, sp.x1, sp.y1, sp.w0, sp.w1, 0);
  }
}

// ============================================================================
// REGION 5: RADIATING SEA URCHIN SPINES (THREE CANOPY TIERS)
// ============================================================================
function generateSpineTesserae() {
  // Sort spines from top tier (2) down to basal tier (0) so foreground spines claim priority
  let sorted = spines.slice().sort((a, b) => b.tier - a.tier);

  for (let sp of sorted) {
    let x0 = UX + Math.cos(sp.angle) * sp.r0;
    let y0 = UY + Math.sin(sp.angle) * sp.r0;
    let tipAngle = sp.angle + sp.curve;
    let x1 = UX + Math.cos(tipAngle) * sp.r1;
    let y1 = UY + Math.sin(tipAngle) * sp.r1;

    laySingleSpineTesserae(x0, y0, x1, y1, sp.w0, sp.w1, sp.litBias, sp.tier);
  }

  // Fill deep inter-spine valleys (r = 225..390) with dark velvet aubergine & garnet contour arcs
  for (let r = 230; r <= 395; r += 9.5) {
    let steps = Math.floor((2 * Math.PI * r) / 9.2);
    for (let i = 0; i < steps; i++) {
      let a = (i / steps) * Math.PI * 2 + random(-0.01, 0.01);
      if (r > getSpineHaloEnvelope(a) - 10) continue;

      let wx = UX + Math.cos(a) * r;
      let wy = UY + Math.sin(a) * r;
      let lightDot = Math.cos(a + 2.35);

      let col =
        lightDot > 0.2
          ? random(["#2e073b", "#3d0a4d", "#470c3b", "#22042b"])
          : random(["#12021a", "#1b0424", "#24052e", "#2b061d", "#0e0114"]);

      addTessera({
        x: wx,
        y: wy,
        len: 7.6 + random(-0.5, 0.5),
        w: 7.0 + random(-0.5, 0.5),
        angle: a + Math.PI * 0.5,
        color: col,
        shadowColor: "#08010d",
        isWedge: random() < 0.4,
        groutColor: "#0e0214",
        askewMax: 0.12,
        clearance: 1.1,
        pad: 0.9
      });
    }
  }
}

function laySingleSpineTesserae(x0, y0, x1, y1, w0, w1, litBias = 0, tier = 1) {
  let dx = x1 - x0;
  let dy = y1 - y0;
  let totalLen = Math.hypot(dx, dy);
  let spineAngle = Math.atan2(dy, dx);
  let nx = -Math.sin(spineAngle);
  let ny = Math.cos(spineAngle);

  // Determine which side of the cylindrical spine faces the upper-left key light (-0.70, -0.71)
  let sideDot = nx * -0.70 + ny * -0.71;
  let axialDot = Math.cos(spineAngle + 2.35) + litBias;
  let litSign = sideDot >= 0 ? 1 : -1;

  let stepLen = 8.4;
  let nSteps = Math.floor(totalLen / stepLen);

  for (let s = 0; s <= nSteps; s++) {
    let t = s / Math.max(1, nSteps);
    let cx = lerp(x0, x1, t);
    let cy = lerp(y0, y1, t);
    let curW = lerp(w0, w1, Math.pow(t, 0.85));

    if (t > 0.76) {
      // Single tapering wedge row at the sharp tip of the spine
      let tipCol, glintCol = null;
      if (axialDot > 0.15) {
        tipCol = random(["#e29bf0", "#d47be6", "#f0bDF7", "#c95fd9"]);
        glintCol = "#ffffff";
      } else if (axialDot > -0.3) {
        tipCol = random(["#9e36b0", "#b34cc4", "#872499", "#ab3878"]);
        glintCol = "#e8a8f5";
      } else {
        // Backlit by cool lapis/cyan ice bounce on the shaded lower-right side
        tipCol = random(["#4a1561", "#3b2375", "#5c1b6e", "#2e3585"]);
        glintCol = "#7da8f0";
      }

      addTessera({
        x: cx,
        y: cy,
        len: 7.2,
        w: Math.max(4.5, curW),
        angle: spineAngle,
        color: tipCol,
        glintColor: glintCol,
        shadowColor: "#1a0424",
        isWedge: true,
        groutColor: "#14041c",
        askewMax: 0.07,
        clearance: 0.75,
        pad: 0.65
      });
    } else {
      // Paired lit row + shadow row along the cylindrical shaft of the spine
      let rowOffset = curW * 0.27;
      for (let side of [litSign, -litSign]) {
        let isLitSide = side === litSign;
        let px = cx + nx * side * rowOffset;
        let py = cy + ny * side * rowOffset;

        let col, glintCol = null, shadCol = "#12021a";

        if (isLitSide) {
          if (axialDot > 0.25) {
            // Vivid lit upper-left amethyst, orchid & magenta-garnet smalti
            col = random(["#c445de", "#d65ce8", "#b334cc", "#cf3882", "#e072f0"]);
            glintCol = random(["#f5c6ff", "#ffe3fa"]);
          } else if (axialDot > -0.25) {
            // Rich imperial purple, plum & ruby-garnet smalti
            col = random(["#8e24aa", "#a130bf", "#7b1fa2", "#9e1c58", "#b0286b"]);
            glintCol = "#d978eb";
          } else {
            // Shaded lower-right spines catching cool lapis-violet ice reflection
            col = random(["#4d1261", "#5e1973", "#382270", "#6b1548"]);
            glintCol = random() < 0.4 ? "#688ce8" : null;
          }
        } else {
          // Shadowed half of the spine shaft: deep aubergine, blackberry & dark garnet
          if (axialDot > 0.2) {
            col = random(["#540f66", "#420a52", "#631247", "#360745"]);
          } else {
            col = random(["#240530", "#190321", "#2e0726", "#14021c", "#33083d"]);
          }
        }

        addTessera({
          x: px,
          y: py,
          len: 7.4 + random(-0.4, 0.4),
          w: Math.max(4.6, curW * 0.52),
          angle: spineAngle,
          color: col,
          glintColor: glintCol,
          shadowColor: shadCol,
          isWedge: s === nSteps - 1 || random() < 0.25,
          groutColor: "#14041c",
          askewMax: 0.08,
          clearance: 0.75,
          pad: 0.65
        });
      }
    }
  }
}

// ============================================================================
// REGION 6: SAINTLY HALO COURSES HUGGING THE SPINE CONTOURS
// ============================================================================
function generateSaintlyHaloTesserae() {
  // "Rows follow the contours of the spines like the haloes of saints."
  // 8 undulating contour courses outside the spine tips that gradually relax into pure circles
  const numCourses = 8;

  for (let m = 0; m < numCourses; m++) {
    let damp = Math.pow(1.0 - m / numCourses, 1.35);
    let rAdd = 6 + m * 12.2;
    let steps = Math.floor((2 * Math.PI * (420 + rAdd)) / 11.2);
    let prevX = null, prevY = null;

    for (let i = 0; i < steps; i++) {
      let a = (i / steps) * Math.PI * 2;
      let rEnv = getSpineHaloEnvelope(a);
      let rSmooth = 415 * getPerspectiveYScale(a);
      let r = lerp(rSmooth, rEnv, damp) + rAdd;

      let wx = UX + Math.cos(a) * r;
      let wy = UY + Math.sin(a) * r;

      // Exact tangent along the undulating halo contour
      let da = 0.015;
      let rNext = lerp(
        415 * getPerspectiveYScale(a + da),
        getSpineHaloEnvelope(a + da),
        damp
      ) + rAdd;
      let nx = UX + Math.cos(a + da) * rNext;
      let ny = UY + Math.sin(a + da) * rNext;
      let tangentAngle = Math.atan2(ny - wy, nx - wx);

      let inIce = isInsideIceBed(wx, wy);
      let shade = evaluateIceOrCobaltColor(wx, wy, a, r, m, inIce, true);

      if (
        addTessera({
          x: wx,
          y: wy,
          len: 9.2 + random(-0.6, 0.6),
          w: 8.6 + random(-0.6, 0.6),
          angle: tangentAngle,
          color: shade.color,
          glintColor: shade.glintColor,
          shadowColor: shade.shadowColor,
          isWedge: random() < 0.35,
          isGold: shade.isGold,
          groutColor: shade.groutColor,
          askewMax: 0.11,
          clearance: 1.2,
          pad: 1.0
        })
      ) {
        if (prevX !== null && Math.hypot(wx - prevX, wy - prevY) < 22) {
          groutLines.push({
            x1: prevX,
            y1: prevY,
            x2: wx,
            y2: wy,
            col: shade.groutColor,
            w: 0.65
          });
        }
        prevX = wx;
        prevY = wy;
      } else {
        prevX = null;
      }
    }
  }
}

// ============================================================================
// REGION 7: BED OF CRUSHED ICE WITH FLECKS OF GOLD LEAF
// ============================================================================
function generateCrushedIceTesserae() {
  // For each 3D Voronoi ice crystal chunk, lay parallel mosaic courses along its crystal facets
  for (let cIdx = 0; cIdx < iceChunks.length; cIdx++) {
    let ch = iceChunks[cIdx];
    let stepAcross = 10.6;
    let stepAlong = 10.8;
    let maxR = ch.size * 1.15;

    for (let u = -maxR; u <= maxR; u += stepAcross) {
      // Above and below the crystal's sharp central ridge (u = 0), facet orientation shifts slightly
      let facetSide = u < -4 ? -1 : u > 4 ? 1 : 0;
      let facetAngle = ch.baseAngle + facetSide * 0.24;
      let cosF = Math.cos(facetAngle);
      let sinF = Math.sin(facetAngle);
      let prevX = null, prevY = null;

      for (let v = -maxR; v <= maxR; v += stepAlong) {
        let wx = ch.x + v * cosF - u * sinF;
        let wy = ch.y + v * sinF + u * cosF;

        if (!isInsideIceBed(wx, wy)) continue;

        // Verify this point belongs to the current Voronoi crystal chunk
        let dOwn = Math.hypot(wx - ch.x, wy - ch.y);
        let closerToOther = false;
        for (let j = 0; j < iceChunks.length; j++) {
          if (j === cIdx) continue;
          let o = iceChunks[j];
          if (Math.hypot(wx - o.x, wy - o.y) < dOwn - 2.5) {
            closerToOther = true;
            break;
          }
        }
        if (closerToOther) continue;

        let dxU = wx - UX;
        let dyU = wy - UY;
        let rU = Math.hypot(dxU, dyU);
        let aU = Math.atan2(dyU, dxU);

        let shade = evaluateIceFacetShader(wx, wy, aU, rU, ch, u, v, dOwn);

        if (
          addTessera({
            x: wx,
            y: wy,
            len: 9.0 + random(-0.7, 0.7),
            w: 8.4 + random(-0.6, 0.6),
            angle: facetAngle,
            color: shade.color,
            glintColor: shade.glintColor,
            shadowColor: shade.shadowColor,
            isWedge: facetSide === 0 || random() < 0.3,
            isGold: shade.isGold,
            groutColor: shade.groutColor,
            askewMax: 0.12,
            clearance: 1.2,
            pad: 1.0
          })
        ) {
          if (prevX !== null && Math.hypot(wx - prevX, wy - prevY) < 20) {
            groutLines.push({
              x1: prevX,
              y1: prevY,
              x2: wx,
              y2: wy,
              col: shade.groutColor,
              w: 0.65
            });
          }
          prevX = wx;
          prevY = wy;
        } else {
          prevX = null;
        }
      }
    }
  }
}

function evaluateIceFacetShader(wx, wy, aU, rU, ch, u, v, dOwn) {
  // Macro lighting on the ice bed:
  // 1. Cast shadow from the sea urchin crown toward lower-right (angle 0.15 .. 1.95 rad)
  let shadowAngDiff = Math.abs(Math.atan2(Math.sin(aU - 0.82), Math.cos(aU - 0.82)));
  let inUrchinCastShadow = shadowAngDiff < 0.82 && rU < 535;
  let shadowStrength = inUrchinCastShadow
    ? map(shadowAngDiff, 0, 0.82, 1.0, 0.0) * map(rU, 360, 535, 1.0, 0.1, true)
    : 0;

  // Also check cast shadow under foreground shard & loose spines
  let dShardShadow = Math.hypot(wx - (shard.x + 24), wy - (shard.y + 22));
  if (dShardShadow < 78) {
    shadowStrength = Math.max(shadowStrength, map(dShardShadow, 0, 78, 0.85, 0));
  }

  // 2. Warm purple/aubergine/tangerine bounce light near the urchin base
  let bounceStrength = map(rU, 350, 485, 1.0, 0.0, true);

  // 3. Facet-level 3D normal illumination
  let isRidge = Math.abs(u) < 6.5;
  let isCrevice = dOwn > ch.size * 0.68 || u > 12;
  let facetLight =
    ch.nx * -0.55 + ch.ny * -0.58 + ch.nz * 0.60 + (u < 0 ? 0.28 : -0.22);
  facetLight -= shadowStrength * 0.62;

  let color, glintColor = null, shadowColor = "#071433", isGold = false, groutColor = "#142038";

  if (isRidge && facetLight > 0.22 && shadowStrength < 0.55) {
    // Sharp crystalline ice ridge catching dazzling light + flecks of 24k gold leaf!
    if (random() < 0.44 || ch.sparkle > 0.65) {
      isGold = true;
      color = random(["#ffd438", "#ffbe1f", "#ffe46b", "#e89e15", "#fff09e"]);
      glintColor = "#ffffff";
      shadowColor = "#9e6308";
      groutColor = "#2b2214";
    } else {
      color = random(["#e6f5ff", "#f2faff", "#d4edff", "#ffffff"]);
      glintColor = "#ffffff";
      shadowColor = "#4b8fd6";
    }
  } else if (facetLight > 0.42 && !isCrevice) {
    // Bright upper glacial ice facet
    if (random() < 0.14) {
      // Scattered gold leaf fleck in bright ice
      isGold = true;
      color = random(["#ffcf33", "#ffe066", "#f2ad18"]);
      glintColor = "#fff9d6";
      shadowColor = "#8c5608";
    } else {
      color = random(["#8cd0ff", "#a6dcff", "#70befa", "#bfe6ff", "#d9f2ff"]);
      glintColor = "#f5fbff";
      shadowColor = "#1f5da8";
    }
  } else if (bounceStrength > 0.35 && random() < bounceStrength * 0.65) {
    // Subsurface refracted bounce from the purple urchin and coral roe
    if (random() < 0.32 && shadowStrength < 0.4) {
      // Warm tangerine-coral & rose-gold reflection in the wet ice
      color = random(["#e86f38", "#f28d4b", "#d14b62", "#c95b8a"]);
      glintColor = "#ffd480";
      shadowColor = "#421130";
    } else {
      // Vivid amethyst-lapis & violet-blue refraction
      color = random(["#5340b8", "#6d52cc", "#4352bf", "#7e5ce0", "#3a2e94"]);
      glintColor = "#a89cf5";
      shadowColor = "#140f42";
    }
  } else if (facetLight > 0.08 && !isCrevice && shadowStrength < 0.6) {
    // Mid-tone cerulean, sapphire & refractive cyan-blue smalti
    color = random(["#2469c9", "#3280e0", "#4596f2", "#1c56b0", "#5aa8fa"]);
    glintColor = random() < 0.45 ? "#9ed4ff" : null;
    shadowColor = "#0b2454";
  } else {
    // Deep translucent lapis lazuli & Prussian blue shadow crevice
    color = random(["#0a1f4d", "#0f2c6b", "#143b8a", "#194aa6", "#08173b"]);
    glintColor = random() < 0.2 ? "#3670c7" : null;
    shadowColor = "#040b1f";
    groutColor = "#0d1526";
  }

  return { color, glintColor, shadowColor, isGold, groutColor };
}

function evaluateIceOrCobaltColor(wx, wy, a, r, courseIdx, inIce, isHalo) {
  if (inIce) {
    // Find nearest ice chunk to inherit crystal lighting + saintly halo gold accents
    let nearest = iceChunks[0];
    let minD = 9999;
    for (let ch of iceChunks) {
      let d = Math.hypot(wx - ch.x, wy - ch.y);
      if (d < minD) {
        minD = d;
        nearest = ch;
      }
    }
    let cosF = Math.cos(nearest.baseAngle);
    let sinF = Math.sin(nearest.baseAngle);
    let dx = wx - nearest.x;
    let dy = wy - nearest.y;
    let u = -dx * sinF + dy * cosF;
    let v = dx * cosF + dy * sinF;
    let res = evaluateIceFacetShader(wx, wy, a, r, nearest, u, v, minD);

    // Extra devotional gold-leaf halo flecks in the first 3 halo courses around the spines
    if (isHalo && courseIdx <= 2 && random() < 0.14) {
      res.isGold = true;
      res.color = random(["#ffd438", "#f5b820", "#ffe678"]);
      res.glintColor = "#ffffff";
      res.shadowColor = "#8a5209";
    }
    return res;
  } else {
    // Deep Cobalt & Lapis Lazuli Halo Ground
    let lightBias = Math.cos(a + 2.35);
    let isHaloGoldRing = isHalo && (courseIdx === 1 || courseIdx === 4) && random() < 0.11;

    if (isHaloGoldRing) {
      return {
        color: random(["#d99b1a", "#f2b824", "#bd8013"]),
        glintColor: "#fff099",
        shadowColor: "#593805",
        isGold: true,
        groutColor: "#141824"
      };
    }

    let col, glintCol = null;
    if (lightBias > 0.2) {
      col = random(["#123485", "#17409e", "#1d4db8", "#0e296b", "#2257c9"]);
      glintCol = random() < 0.3 ? "#4b82eb" : null;
    } else if (lightBias > -0.3) {
      col = random(["#0c2259", "#102c70", "#153787", "#091a45", "#182366"]);
    } else {
      col = random(["#06112e", "#091840", "#0c2052", "#050c21", "#10163b"]);
    }

    return {
      color: col,
      glintColor: glintCol,
      shadowColor: "#030714",
      isGold: false,
      groutColor: "#0b101d"
    };
  }
}

// ============================================================================
// REGION 8: DEEP COBALT GROUND (SWEEPING BYZANTINE HALO COURSES)
// ============================================================================
function generateCobaltGroundTesserae() {
  // Concentric halo courses sweeping from the urchin & ice bed out to the corners of the 1200x1200 panel
  for (let r = 380; r <= 960; r += 12.8) {
    let steps = Math.floor((2 * Math.PI * r) / 12.2);
    let prevX = null, prevY = null;

    for (let i = 0; i < steps; i++) {
      let a = (i / steps) * Math.PI * 2 + random(-0.006, 0.006);
      let rScaled = r * (0.96 + 0.05 * Math.sin(a));
      let wx = UX + Math.cos(a) * rScaled;
      let wy = UY + Math.sin(a) * rScaled;

      if (wx < 14 || wx > CW - 14 || wy < 14 || wy > CH - 14) {
        prevX = null;
        continue;
      }

      let tangentAngle = a + Math.PI * 0.5;
      let inIce = isInsideIceBed(wx, wy);
      let shade = evaluateIceOrCobaltColor(wx, wy, a, rScaled, 99, inIce, false);

      if (
        addTessera({
          x: wx,
          y: wy,
          len: 10.2 + random(-0.7, 0.7),
          w: 9.4 + random(-0.6, 0.6),
          angle: tangentAngle,
          color: shade.color,
          glintColor: shade.glintColor,
          shadowColor: shade.shadowColor,
          isWedge: random() < 0.22,
          isGold: shade.isGold,
          groutColor: shade.groutColor,
          askewMax: 0.11,
          clearance: 1.25,
          pad: 1.05
        })
      ) {
        if (prevX !== null && Math.hypot(wx - prevX, wy - prevY) < 24) {
          groutLines.push({
            x1: prevX,
            y1: prevY,
            x2: wx,
            y2: wy,
            col: shade.groutColor,
            w: 0.65
          });
        }
        prevX = wx;
        prevY = wy;
      } else {
        prevX = null;
      }
    }
  }
}

// ============================================================================
// REGION 9: INTERSTITIAL WEDGE FILL PASS
// ============================================================================
function generateInterstitialWedges() {
  // Scan the occupancy grid for any small wedge-shaped pockets between converging courses
  for (let y = 18; y <= CH - 18; y += 7) {
    for (let x = 18; x <= CW - 18; x += 7) {
      let gx = Math.floor(x / GRID_SCALE);
      let gy = Math.floor(y / GRID_SCALE);
      if (occGrid[gy * GW + gx] !== 0) continue;

      let dx = x - UX;
      let dy = y - UY;
      let r = Math.hypot(dx, dy);
      let a = Math.atan2(dy, dx);
      let tangentAngle = a + Math.PI * 0.5;

      let col, glintCol = null, isGold = false, groutCol = "#141b29";
      if (r < getShellInnerRadius(a)) {
        col = random(["#240614", "#3b0920", "#591124"]);
        groutCol = "#14040c";
      } else if (r < getSpineHaloEnvelope(a)) {
        col = random(["#2a0636", "#420b52", "#59103d", "#1c0326"]);
        groutCol = "#12031a";
      } else {
        let inIce = isInsideIceBed(x, y);
        let sh = evaluateIceOrCobaltColor(x, y, a, r, 5, inIce, false);
        col = sh.color;
        glintCol = sh.glintColor;
        isGold = sh.isGold;
        groutCol = sh.groutColor;
      }

      addTessera({
        x: x,
        y: y,
        len: 6.6,
        w: 6.0,
        angle: tangentAngle + random(-0.3, 0.3),
        color: col,
        glintColor: glintCol,
        isWedge: true,
        isGold: isGold,
        groutColor: groutCol,
        askewMax: 0.15,
        clearance: 0.7,
        pad: 0.65
      });
    }
  }
}

// ============================================================================
// RENDERING PASSES (MARKER TESSERAE, GOLD LEAF & GRAPHITE GROUT)
// ============================================================================
function renderGraphiteGroutBase() {
  // Course-following thin graphite grout lines beneath and between the tesserae
  for (let g of groutLines) {
    brush.set("2B", g.col, g.w);
    brush.line(g.x1, g.y1, g.x2, g.y2);
  }
}

function renderSmaltiTesserae() {
  // Draw every tessera as a single dab of flat marker (square or wedge)
  for (let i = 0; i < tesserae.length; i++) {
    let t = tesserae[i];
    let cosA = Math.cos(t.angle);
    let sinA = Math.sin(t.angle);

    // Since our custom tip is a 2x2 square scaled by weight W, total length is strokeLen + 2*W
    // Keep strokeLen short so each tessera reads as a crisp square or wedge stone dab
    let weight = t.w * 0.46;
    let strokeHalf = Math.max(1.1, (t.len - t.w * 0.62) * 0.5);

    let x1 = t.x - cosA * strokeHalf;
    let y1 = t.y - sinA * strokeHalf;
    let x2 = t.x + cosA * strokeHalf;
    let y2 = t.y + sinA * strokeHalf;

    // Gold leaf tesserae first get an amber/red-bole under-dab just like authentic Byzantine smalti d'oro
    if (t.isGold) {
      brush.set("smalti_sq", "#8f4b0a", weight * 1.04);
      brush.line(x1, y1, x2, y2);
    }

    let bName = t.isWedge ? "smalti_wedge" : "smalti_sq";
    brush.set(bName, t.color, weight);
    brush.line(x1, y1, x2, y2);

    // Subtle built-in "marker" saturation dab on every 4th focal tessera for translucent glass depth
    if (i % 4 === 0 && (t.isGold || t.glintColor)) {
      brush.set("marker", t.color, weight * 0.24);
      brush.line(t.x - cosA * 0.8, t.y - sinA * 0.8, t.x + cosA * 0.8, t.y + sinA * 0.8);
    }
  }
}

function renderSmaltiGlintsAndGoldLeaf() {
  for (let i = 0; i < tesserae.length; i++) {
    let t = tesserae[i];
    let cosA = Math.cos(t.angle);
    let sinA = Math.sin(t.angle);
    let nx = -sinA;
    let ny = cosA;

    // 1. Conchoidal dark glass shadow bevel on the lower-right edge of selected tesserae
    if (t.shadowColor && i % 2 === 0) {
      let sx = t.x + (cosA * 0.15 + nx * 0.28) * t.w;
      let sy = t.y + (sinA * 0.15 + ny * 0.28) * t.w;
      brush.set("smalti_glint", t.shadowColor, t.w * 0.18);
      brush.line(sx - cosA * 1.2, sy - sinA * 1.2, sx + cosA * 1.2, sy + sinA * 1.2);
    }

    // 2. Crisp specular glass facet glint or 24k gold leaf metallic flash on the upper-left bevel
    if (t.glintColor || t.isGold) {
      let gx = t.x - (cosA * 0.12 + nx * 0.22) * t.w;
      let gy = t.y - (sinA * 0.12 + ny * 0.22) * t.w;
      let gCol = t.glintColor || "#fff3a6";
      let gWeight = t.isGold ? t.w * 0.28 : t.w * 0.21;

      brush.set("smalti_glint", gCol, gWeight);
      brush.line(gx - cosA * 1.3, gy - sinA * 1.3, gx + cosA * 1.3, gy + sinA * 1.3);

      // Extra pinpoint sparkle on gold leaf tesserae
      if (t.isGold) {
        brush.set("cpencil", "#ffffff", 0.55);
        brush.line(gx - 0.8, gy - 0.8, gx + 0.8, gy + 0.8);
      }
    }
  }
}

function renderGraphiteGroutJoints() {
  // Thin graphite pencil lines ("HB" and "2B") framing the slightly askew tesserae inside their mortar bed
  for (let i = 0; i < tesserae.length; i++) {
    let t = tesserae[i];
    let cosA = Math.cos(t.angle);
    let sinA = Math.sin(t.angle);
    let nx = -sinA;
    let ny = cosA;

    let hl = t.len * 0.52;
    let hw = t.w * 0.52;

    // Cross-joint graphite line between neighboring tesserae in the same row
    let jx1 = t.x + cosA * hl - nx * hw * 0.85;
    let jy1 = t.y + sinA * hl - ny * hw * 0.85;
    let jx2 = t.x + cosA * hl + nx * hw * 0.85;
    let jy2 = t.y + sinA * hl + ny * hw * 0.85;

    let graphiteTone = i % 3 === 0 ? "#2a3345" : i % 3 === 1 ? "#1b212e" : t.groutColor;
    brush.set("HB", graphiteTone, 0.36);
    brush.line(jx1, jy1, jx2, jy2);

    // Longitudinal graphite grout line along the side of the tessera
    if (i % 2 === 0) {
      let sx1 = t.x - cosA * hl * 0.9 + nx * hw;
      let sy1 = t.y - sinA * hl * 0.9 + ny * hw;
      let sx2 = t.x + cosA * hl * 0.9 + nx * hw;
      let sy2 = t.y + sinA * hl * 0.9 + ny * hw;
      brush.set("2B", "#181e2b", 0.34);
      brush.line(sx1, sy1, sx2, sy2);
    }
  }
}

// Hyperrealistic Drypoint Copperplate Print:
// Coiled Rusted Barbed Wire Strung Across a Pale Winter Sky

const SEED = 4091;

const PALETTE = {
  paper: "#f4efe4",
  paperBright: "#faf6ee",
  paperWarm: "#ede5d6",
  plateLight: "#e2d8c9",
  plateMid: "#ccbface", // fallback not used, see exact hexes below
  toneLight: "#dfd5c6",
  toneMid: "#c7baaa",
  toneDark: "#a69685",
  toneCorner: "#827263",
  toneDeepCorner: "#5e5044",
  foulBite: "#8c7c6c",
  scratchGhost: "#78695b",
  scratchFine: "#57493e",
  rustLight: "#634938",
  rustMid: "#473325",
  rustDark: "#302117",
  inkMid: "#362b23",
  inkDark: "#221a15",
  inkBurr: "#120e0b"
};

// Helper to interpolate hex colors
function lerpHex(hex1, hex2, t) {
  t = constrain(t, 0, 1);
  const c1 = [
    parseInt(hex1.slice(1, 3), 16),
    parseInt(hex1.slice(3, 5), 16),
    parseInt(hex1.slice(5, 7), 16)
  ];
  const c2 = [
    parseInt(hex2.slice(1, 3), 16),
    parseInt(hex2.slice(3, 5), 16),
    parseInt(hex2.slice(5, 7), 16)
  ];
  const r = Math.round(c1[0] + (c2[0] - c1[0]) * t);
  const g = Math.round(c1[1] + (c2[1] - c1[1]) * t);
  const b = Math.round(c1[2] + (c2[2] - c1[2]) * t);
  return (
    "#" +
    ((1 << 24) + (r << 16) + (g << 8) + b)
      .toString(16)
      .slice(1)
  );
}

// Computes the local wiped plate-tone color at (x, y) so opaque wire masks match the sky
function getSkyToneAt(x, y) {
  const nx = (x - 600) / 540;
  const ny = (y - 560) / 540;
  // Radial distance weighted heavier toward the four corners (rx^2 * ry^2 + r^2)
  const r2 = nx * nx * 0.65 + ny * ny * 0.75 + nx * nx * ny * ny * 0.85;
  const n = noise(x * 0.0025, y * 0.0025) * 0.18;
  const t = constrain(pow(constrain(r2, 0, 1.3), 1.15) * 0.78 + n - 0.06, 0, 1);
  if (t < 0.45) {
    return lerpHex(PALETTE.paper, PALETTE.toneLight, t / 0.45);
  } else if (t < 0.8) {
    return lerpHex(PALETTE.toneLight, PALETTE.toneMid, (t - 0.45) / 0.35);
  } else {
    return lerpHex(PALETTE.toneMid, PALETTE.toneDark, (t - 0.8) / 0.2);
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Register custom drypoint printmaking brushes
  // 1. Razor-sharp steel drypoint needle
  brush.add("needle", {
    type: "default",
    weight: 0.24,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 0.22,
    opacity: 215,
    spacing: 0.25,
    pressure: [0.65, 1.0, 0.6],
    noise: 0.25
  });

  // 2. Ultra-fine dry scratch (burr scraped away / light incision)
  brush.add("needle_hair", {
    type: "default",
    weight: 0.15,
    scatter: 0.01,
    sharpness: 0.96,
    grain: 0.18,
    opacity: 165,
    spacing: 0.28,
    pressure: [0.4, 0.95, 0.35],
    noise: 0.2
  });

  // 3. Heavy scored drypoint core line
  brush.add("burr_core", {
    type: "default",
    weight: 0.52,
    scatter: 0.18,
    sharpness: 0.5,
    grain: 0.55,
    opacity: 190,
    spacing: 0.22,
    pressure: [0.5, 1.15, 0.5],
    noise: 0.45
  });

  // 4. Soft, fuzzy velvety drypoint burr bloom along one side of deep cuts
  brush.add("burr_velvet", {
    type: "default",
    weight: 1.35,
    scatter: 0.75,
    sharpness: 0.08,
    grain: 0.72,
    opacity: 44,
    spacing: 0.24,
    pressure: [0.3, 1.1, 0.3],
    noise: 0.65
  });

  // 5. Wider smoky burr bleed for deep crevices in barb knots
  brush.add("burr_smoke", {
    type: "default",
    weight: 2.2,
    scatter: 1.15,
    sharpness: 0.04,
    grain: 0.68,
    opacity: 24,
    spacing: 0.35,
    pressure: [0.2, 1.0, 0.2],
    noise: 0.7
  });

  // 6. Rust pitting stipple & roulette tool
  brush.add("rust_pit", {
    type: "spray",
    weight: 0.65,
    scatter: 1.1,
    opacity: 165,
    spacing: 0.65,
    pressure: [0.7, 1.1, 0.7],
    noise: 0.5
  });

  // 7. Tarlatan cheesecloth plate-wiping brush for smudged charcoal haze
  brush.add("tarlatan", {
    type: "default",
    weight: 2.8,
    scatter: 1.9,
    sharpness: 0.05,
    grain: 0.42,
    opacity: 14,
    spacing: 0.55,
    pressure: [0.2, 1.0, 0.2],
    noise: 0.5
  });

  // 8. Solid cylindrical body mask (prevents back wire strands from showing through front strands)
  brush.add("wire_mask", {
    type: "marker",
    weight: 1.8,
    scatter: 0.0,
    opacity: 255,
    spacing: 0.18,
    pressure: [1.0, 1.0, 1.0],
    markerTip: false,
    noise: 0.0
  });

  // 9. Scraper / burnisher for reserved bare-paper frost crystals
  brush.add("frost_reserve", {
    type: "default",
    weight: 0.42,
    scatter: 0.05,
    sharpness: 0.9,
    grain: 0.12,
    opacity: 250,
    spacing: 0.2,
    pressure: [0.8, 1.1, 0.8],
    noise: 0.15
  });

  background(PALETTE.paper);
}

function draw() {
  translate(-width / 2, -height / 2);

  const PLATE = { x1: 62, y1: 62, x2: 1138, y2: 1138, w: 1076, h: 1076 };

