// =============================================================================
// 1. PAPER GRAIN, WIPED PLATE TONE & CORNER CHARCOAL HAZE
// =============================================================================
function renderPaperAndPlateTone(PLATE) {
  brush.noStroke();

  // Base warm paper wash inside the copperplate impression
  brush.wash(PALETTE.paperWarm, 85);
  brush.rect(PLATE.x1, PLATE.y1, PLATE.w, PLATE.h, "corner");
  brush.noWash();

  // Batched watercolor fills for the wiped plate tone ("retroussage"), heavier at corners
  const corners = [
    { cx: PLATE.x1, cy: PLATE.y1, dx: 1, dy: 1 },
    { cx: PLATE.x2, cy: PLATE.y1, dx: -1, dy: 1 },
    { cx: PLATE.x2, cy: PLATE.y2, dx: -1, dy: -1 },
    { cx: PLATE.x1, cy: PLATE.y2, dx: 1, dy: -1 }
  ];

  // Pass A: Broad soft corner & edge vignettes in pale warm earth tone
  brush.fill(PALETTE.toneLight, 52);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.55, 0.18);
  for (let c of corners) {
    drawCornerBlob(c.cx, c.cy, c.dx, c.dy, 560, 490);
  }
  // Upper and lower horizon plate veil
  brush.rect(PLATE.x1 + 20, PLATE.y1 + 15, PLATE.w - 40, 170, "corner");
  brush.rect(PLATE.x1 + 20, PLATE.y2 - 195, PLATE.w - 40, 180, "corner");

  // Pass B: Medium charcoal-sepia plate haze deeper into the corners
  brush.fill(PALETTE.toneMid, 58);
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.65, 0.22);
  for (let c of corners) {
    drawCornerBlob(c.cx, c.cy, c.dx, c.dy, 420, 380);
  }

  // Pass C: Heavy ink-trapped corner smudges
  brush.fill(PALETTE.toneCorner, 54);
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.72, 0.28);
  for (let c of corners) {
    drawCornerBlob(c.cx, c.cy, c.dx, c.dy, 270, 250);
  }

  // Pass D: Deepest corner bevel tone
  brush.fill(PALETTE.toneDeepCorner, 44);
  brush.fillBleed(0.3, "out");
  brush.fillTexture(0.75, 0.35);
  for (let c of corners) {
    drawCornerBlob(c.cx, c.cy, c.dx, c.dy, 150, 145);
  }
  brush.noFill();

  // Clipping to plate for wiping streaks, charcoal smudge haze, and copperplate scratches
  brush.clip([PLATE.x1, PLATE.y1, PLATE.x2, PLATE.y2]);

  // Tarlatan wiping sweeps (long directional cheesecloth smudges across the copperplate)
  for (let i = 0; i < 240; i++) {
    const px = random(PLATE.x1 - 40, PLATE.x2 + 40);
    const py = random(PLATE.y1 - 40, PLATE.y2 + 40);
    const nx = (px - 600) / 540;
    const ny = (py - 600) / 540;
    const distCorner = nx * nx + ny * ny;

    // Leave center winter sky paler and more open
    if (random() > distCorner * 0.85 + 0.12) continue;

    const ang = -14 + (noise(px * 0.003, py * 0.003) - 0.5) * 28;
    const len = random(110, 320);
    const col = distCorner > 0.9 ? PALETTE.toneCorner : PALETTE.toneMid;
    const w = map(distCorner, 0, 1.6, 0.6, 1.45, true);

    brush.set("tarlatan", col, w);
    const x2 = px + cos(ang) * len;
    const y2 = py + sin(ang) * len;
    brush.line(px, py, x2, y2);
  }

  // Secondary cross-wiping charcoal haze near the edges and corners
  for (let i = 0; i < 160; i++) {
    const cornerIdx = i % 4;
    const c = corners[cornerIdx];
    const rx = pow(random(), 1.35) * 460;
    const ry = pow(random(), 1.35) * 460;
    const px = c.cx + c.dx * rx;
    const py = c.cy + c.dy * ry;
    const ang = 25 * c.dx * c.dy + random(-35, 35);
    const len = random(45, 160);

    brush.set("charcoal", PALETTE.toneDark, random(0.18, 0.42));
    brush.line(
      px - cos(ang) * len * 0.5,
      py - sin(ang) * len * 0.5,
      px + cos(ang) * len * 0.5,
      py + sin(ang) * len * 0.5
    );
  }

  // Fine copperplate polishing scratches and foul-biting specks in the plate tone
  for (let i = 0; i < 220; i++) {
    const px = random(PLATE.x1, PLATE.x2);
    const py = random(PLATE.y1, PLATE.y2);
    const nx = (px - 600) / 540;
    const ny = (py - 600) / 540;
    const edgeFactor = nx * nx + ny * ny;
    if (random() > edgeFactor * 0.75 + 0.15) continue;

    const ang = random() < 0.75 ? -12 + random(-8, 8) : random(-85, 85);
    const len = random(18, 95);
    brush.set("needle_hair", PALETTE.foulBite, random(0.35, 0.75));
    brush.line(px, py, px + cos(ang) * len, py + sin(ang) * len);
  }

  // Stippled oxidation / foul biting pits in the corners of the copper plate
  for (let i = 0; i < 95; i++) {
    const c = corners[i % 4];
    const px = c.cx + c.dx * pow(random(), 1.6) * 340;
    const py = c.cy + c.dy * pow(random(), 1.6) * 340;
    brush.set("rust_pit", PALETTE.toneDeepCorner, random(0.4, 0.9));
    brush.line(px, py, px + random(-18, 18), py + random(-18, 18));
  }

  brush.noClip();
}

function drawCornerBlob(cx, cy, dx, dy, rx, ry) {
  brush.beginShape(0.35);
  brush.vertex(cx, cy);
  brush.vertex(cx + dx * rx * 0.95, cy);
  brush.vertex(cx + dx * rx * 0.78, cy + dy * ry * 0.42);
  brush.vertex(cx + dx * rx * 0.42, cy + dy * ry * 0.78);
  brush.vertex(cx, cy + dy * ry * 0.95);
  brush.endShape(true);
}

// =============================================================================
// 2. DISTANT / SECONDARY BARBED WIRE LOOP (WIRY DRYPOINT IN THE WINTER SKY)
// =============================================================================
function renderDistantWireLoop() {
  // A delicate, slightly out-of-focus or lightly-bitten drypoint wire coil in the background
  const bgPath = buildSplinePath(
    [
      [50, 420, -60],
      [240, 325, -60],
      [470, 345, -60],
      [690, 455, -60],
      [920, 495, -60],
      [1150, 370, -60]
    ],
    180,
    2.5
  );

  const R_helix = 2.6;
  const r_strand = 2.4;
  const twistFreq = 0.075;

  for (let s = 0; s < bgPath.length - 1; s++) {
    const p0 = bgPath[s];
    const p1 = bgPath[s + 1];
    const phase0 = p0.dist * twistFreq * 57.2958;
    const phase1 = p1.dist * twistFreq * 57.2958;

    for (let strand = 0; strand < 2; strand++) {
      const offsetAng = strand * 180;
      const off0 = sin(phase0 + offsetAng) * R_helix;
      const off1 = sin(phase1 + offsetAng) * R_helix;

      const x0 = p0.x + p0.nx * off0;
      const y0 = p0.y + p0.ny * off0;
      const x1 = p1.x + p1.nx * off1;
      const y1 = p1.y + p1.ny * off1;

      // Top wiry edge
      brush.set("needle_hair", PALETTE.scratchGhost, 0.65);
      brush.line(
        x0 - p0.nx * r_strand * 0.7,
        y0 - p0.ny * r_strand * 0.7,
        x1 - p1.nx * r_strand * 0.7,
        y1 - p1.ny * r_strand * 0.7
      );

      // Lower shadow edge with subtle burr
      brush.set("needle", PALETTE.scratchFine, 0.75);
      brush.line(
        x0 + p0.nx * r_strand * 0.7,
        y0 + p0.ny * r_strand * 0.7,
        x1 + p1.nx * r_strand * 0.7,
        y1 + p1.ny * r_strand * 0.7
      );

      if (s % 2 === strand) {
        brush.set("burr_velvet", PALETTE.toneDeepCorner, 0.42);
        brush.line(
          x0 + p0.nx * r_strand * 1.1,
          y0 + p0.ny * r_strand * 1.1,
          x1 + p1.nx * r_strand * 1.1,
          y1 + p1.ny * r_strand * 1.1
        );
      }
    }
  }

  // Distant barbs along the background wire
  const bgBarbFracs = [0.16, 0.36, 0.56, 0.76, 0.91];
  for (let b = 0; b < bgBarbFracs.length; b++) {
    const idx = floor(bgBarbFracs[b] * (bgPath.length - 1));
    const pt = bgPath[idx];
    const baseAng = atan2(pt.ty, pt.tx);

    // 4 small wrap lines
    for (let w = -1.5; w <= 1.5; w += 1) {
      const wx = pt.x + pt.tx * w * 3.2;
      const wy = pt.y + pt.ty * w * 3.2;
      brush.set("needle", PALETTE.scratchFine, 0.85);
      brush.line(
        wx - pt.nx * 5.2,
        wy - pt.ny * 5.2,
        wx + pt.nx * 5.2,
        wy + pt.ny * 5.2
      );
    }

    // 4 wiry spikes
    const spikeAngles = [baseAng + 68, baseAng - 64, baseAng + 118, baseAng - 115];
    for (let k = 0; k < 4; k++) {
      const sa = spikeAngles[k] + random(-6, 6);
      const slen = (k < 2 ? 19 : 13) * random(0.88, 1.12);
      const sx1 = pt.x + cos(sa) * slen;
      const sy1 = pt.y + sin(sa) * slen;

      brush.set("burr_velvet", PALETTE.toneDeepCorner, 0.45);
      brush.line(pt.x, pt.y + 1.2, sx1, sy1 + 1.2);

      brush.set("needle", PALETTE.scratchFine, 0.85);
      brush.line(pt.x, pt.y, sx1, sy1);
    }
  }
}

// =============================================================================
// 3. GEOMETRY ENGINE FOR 3D HELICAL BARBED WIRE & 4-POINT BARBS
// =============================================================================
function buildSplinePath(ctrlPts, numSamples, jitterAmt) {
  const rawPts = [];
  for (let i = 0; i <= numSamples; i++) {
    const t = i / numSamples;
    const p = evalCatmullRom3D(ctrlPts, t);
    // Subtle hand-strung tension waviness and metallic stiffness
    const n1 = (noise(i * 0.06, ctrlPts[0][1] * 0.01) - 0.5) * jitterAmt;
    const n2 = (noise(i * 0.06 + 50, ctrlPts[0][0] * 0.01) - 0.5) * jitterAmt;
    rawPts.push({
      x: p.x + n1,
      y: p.y + n2,
      z: p.z
    });
  }

  // Compute tangents, normals, and cumulative arc length
  let cumDist = 0;
  const path = [];
  for (let i = 0; i < rawPts.length; i++) {
    const prev = rawPts[max(0, i - 1)];
    const next = rawPts[min(rawPts.length - 1, i + 1)];
    let dx = next.x - prev.x;
    let dy = next.y - prev.y;
    const mag = sqrt(dx * dx + dy * dy) || 1;
    const tx = dx / mag;
    const ty = dy / mag;
    // Normal points generally downward-right so u = -1 is upper-left lit edge
    let nx = -ty;
    let ny = tx;
    if (ny < 0) {
      nx = -nx;
      ny = -ny;
    }

    if (i > 0) {
      const stepD = dist(rawPts[i].x, rawPts[i].y, rawPts[i - 1].x, rawPts[i - 1].y);
      cumDist += stepD;
    }

    path.push({
      x: rawPts[i].x,
      y: rawPts[i].y,
      z: rawPts[i].z,
      tx,
      ty,
      nx,
      ny,
      dist: cumDist
    });
  }
  return path;
}

function evalCatmullRom3D(pts, t) {
  const n = pts.length - 1;
  const scaled = t * n;
  const i = constrain(floor(scaled), 0, n - 1);
  const u = scaled - i;

  const p0 = pts[max(0, i - 1)];
  const p1 = pts[i];
  const p2 = pts[min(n, i + 1)];
  const p3 = pts[min(n, i + 2)];

  const u2 = u * u;
  const u3 = u2 * u;

  const f0 = -0.5 * u3 + u2 - 0.5 * u;
  const f1 = 1.5 * u3 - 2.5 * u2 + 1.0;
  const f2 = -1.5 * u3 + 2.0 * u2 + 0.5 * u;
  const f3 = 0.5 * u3 - 0.5 * u2;

  return {
    x: p0[0] * f0 + p1[0] * f1 + p2[0] * f2 + p3[0] * f3,
    y: p0[1] * f0 + p1[1] * f1 + p2[1] * f2 + p3[1] * f3,
    z: p0[2] * f0 + p1[2] * f1 + p2[2] * f2 + p3[2] * f3
  };
}

function generateBarbedWireAssembly(path, cfg, sceneItems) {
  const { strandRadius, helixRadius, twistFreq, barbPositions, barbScale, rustSeed } = cfg;

  // Precompute barb arc-length distances so we can boost rust & tension kinks near barbs
  const totalLen = path[path.length - 1].dist;
  const barbDists = barbPositions.map((f) => f * totalLen);

  // 1. Generate double-strand helical segments
  for (let i = 0; i < path.length - 1; i++) {
    const p0 = path[i];
    const p1 = path[i + 1];
    const dMid = 0.5 * (p0.dist + p1.dist);

    // Distance to nearest barb knot (moisture collects at knots -> heavier rust)
    let minBarbDist = 9999;
    for (let bd of barbDists) {
      minBarbDist = min(minBarbDist, abs(dMid - bd));
    }
    const knotProximity = exp(-minBarbDist / 38);

    for (let s = 0; s < 2; s++) {
      const phaseOffset = s * 180;
      const ang0 = p0.dist * twistFreq * 57.2958 + phaseOffset;
      const ang1 = p1.dist * twistFreq * 57.2958 + phaseOffset;
      const angMid = 0.5 * (ang0 + ang1);

      const off0 = sin(ang0) * helixRadius;
      const off1 = sin(ang1) * helixRadius;
      const zHelix = cos(angMid) * helixRadius;

      const x0 = p0.x + p0.nx * off0;
      const y0 = p0.y + p0.ny * off0;
      const x1 = p1.x + p1.nx * off1;
      const y1 = p1.y + p1.ny * off1;

      // Tangent & normal of this individual helical strand
      let dx = x1 - x0;
      let dy = y1 - y0;
      const segLen = sqrt(dx * dx + dy * dy) || 1;
      const tx = dx / segLen;
      const ty = dy / segLen;
      let nx = -ty;
      let ny = tx;
      if (ny < 0) {
        nx = -nx;
        ny = -ny;
      }

      // Coherent rust level along the strand
      const nRust = noise(dMid * 0.018 + s * 30, rustSeed);
      const rust = constrain(nRust * 0.95 + knotProximity * 0.48 - 0.12, 0, 1);

      // Crevice shadow intensity where the two strands pinch together
      const pinchShadow = pow(abs(cos(angMid)), 1.6);

      sceneItems.push({
        type: "strandSeg",
        x0,
        y0,
        x1,
        y1,
        tx,
        ty,
        nx,
        ny,
        segLen,
        r: strandRadius,
        z: 0.5 * (p0.z + p1.z) + zHelix,
        rust,
        pinchShadow,
        zHelix,
        helixRadius,
        knotProximity,
        seed: i * 13 + s * 7 + rustSeed
      });
    }
  }

  // 2. Generate 4-point barbs (collar wraps + 4 diagonal-bevel spikes)
  for (let b = 0; b < barbPositions.length; b++) {
    const frac = barbPositions[b];
    const idx = constrain(floor(frac * (path.length - 1)), 2, path.length - 3);
    const pt = path[idx];

    const knotRust = constrain(noise(b * 2.3, rustSeed + 99) * 0.6 + 0.45, 0.4, 1.0);
    const collarR = strandRadius * 1.48 + helixRadius * 0.55;
    const wrapRadius = strandRadius * 0.92;

    // 5 tightly wound helical collar wraps around the main strands
    const numWraps = 5;
    for (let w = 0; w < numWraps; w++) {
      const wOff = (w - (numWraps - 1) / 2) * (wrapRadius * 1.52);
      const wx = pt.x + pt.tx * wOff;
      const wy = pt.y + pt.ty * wOff;
      // Slight diagonal tilt of helical wrap
      const tilt = 0.24 * wrapRadius;

      sceneItems.push({
        type: "collarWrap",
        cx: wx,
        cy: wy,
        tx: pt.tx,
        ty: pt.ty,
        nx: pt.nx,
        ny: pt.ny,
        collarR: collarR * random(0.95, 1.05),
        wrapR: wrapRadius,
        tilt,
        z: pt.z + collarR * 0.65 + (w === 2 ? 1.5 : 0),
        rust: knotRust,
        isOuter: w === 0 || w === numWraps - 1,
        seed: rustSeed + b * 100 + w * 17
      });
    }

    // 4 sharp spikes jutting out in 3D cross configuration
    // Roll angle around the wire axis
    const baseRoll = (b * 67 + rustSeed * 1.3) % 360;
    for (let k = 0; k < 4; k++) {
      const roll = baseRoll + k * 90 + random(-8, 8);
      // Radial direction in the normal/depth plane perpendicular to wire
      const radNormal = sin(roll);
      const radDepth = cos(roll);

      // Axial splay: two spikes splay slightly left, two splay slightly right
      const axialSplay = (k % 2 === 0 ? 1 : -1) * random(0.32, 0.52);

      // Full length of the spike in 3D
      const fullLen3D = (36 + (k % 2) * 8) * barbScale * random(0.92, 1.12);

      // Project 3D spike vector onto 2D canvas
      const vx = pt.tx * axialSplay + pt.nx * radNormal;
      const vy = pt.ty * axialSplay + pt.ny * radNormal;
      const vMag2D = sqrt(vx * vx + vy * vy) || 0.25;

      // Foreshortened 2D length based on how much the spike points in depth vs canvas plane
      const projFactor = constrain(sqrt(axialSplay * axialSplay + radNormal * radNormal * 0.95), 0.42, 1.1);
      const spikeLen2D = fullLen3D * projFactor;

      const dirX = vx / vMag2D;
      const dirY = vy / vMag2D;

      // Start at the surface of the wrap collar
      const startOff = (wOffForSpike(k, wrapRadius)) * 0.8;
      const sx0 = pt.x + pt.tx * startOff + dirX * (collarR * 0.55);
      const sy0 = pt.y + pt.ty * startOff + dirY * (collarR * 0.55);

      // Slight bend near tip from manufacturing / wire handling
      const bendAmt = random(-3.2, 3.2) * barbScale;
      const perpX = -dirY;
      const perpY = dirX;

      const sx1 = sx0 + dirX * spikeLen2D + perpX * bendAmt;
      const sy1 = sy0 + dirY * spikeLen2D + perpY * bendAmt;

      const spikeZ = pt.z + radDepth * (collarR + fullLen3D * 0.42);

      sceneItems.push({
        type: "barbSpike",
        x0: sx0,
        y0: sy0,
        x1: sx1,
        y1: sy1,
        dirX,
        dirY,
        perpX,
        perpY,
        len: spikeLen2D,
        baseR: wrapRadius * 0.96,
        z: spikeZ,
        radDepth,
        rust: knotRust,
        bevelSide: k % 2 === 0 ? 1 : -1,
        seed: rustSeed + b * 200 + k * 31
      });
    }
  }
}

function wOffForSpike(k, wrapR) {
  return k < 2 ? -wrapR * 2.1 : wrapR * 2.1;
}

// =============================================================================
// 4. HYPERREALISTIC DRYPOINT RENDERERS FOR STRANDS, COLLARS & BARBS
// =============================================================================

function renderStrandSegment(seg) {
  const { x0, y0, x1, y1, tx, ty, nx, ny, r, rust, pinchShadow, zHelix, helixRadius, knotProximity } = seg;
  const xm = 0.5 * (x0 + x1);
  const ym = 0.5 * (y0 + y1);

  // Extend slightly along tangent so adjacent segments overlap without hairline gaps
  const pad = 1.6;
  const ax0 = x0 - tx * pad;
  const ay0 = y0 - ty * pad;
  const ax1 = x1 + tx * pad;
  const ay1 = y1 + ty * pad;

  // 1. Opaque local paper/sky-tone core mask so front strand cleanly occludes back strand
  const maskCol = getSkyToneAt(xm, ym);
  const maskWeight = max(0.4, (r * 0.36));
  brush.set("wire_mask", maskCol, maskWeight);
  brush.line(ax0 - nx * r * 0.25, ay0 - ny * r * 0.25, ax1 - nx * r * 0.25, ay1 - ny * r * 0.25);
  brush.line(ax0 + nx * r * 0.25, ay0 + ny * r * 0.25, ax1 + nx * r * 0.25, ay1 + ny * r * 0.25);

  // 2. Specular cold winter sky reserve along the upper-left lit rim (u in [-0.85, -0.35])
  if (rust < 0.72) {
    brush.set("frost_reserve", PALETTE.paperBright, 0.65);
    brush.line(
      ax0 - nx * r * 0.62,
      ay0 - ny * r * 0.62,
      ax1 - nx * r * 0.62,
      ay1 - ny * r * 0.62
    );
  }

  // 3. Upper contour (lit edge: wiry, sharp drypoint needle scratch, lightly pitted by rust)
  const topJitter = rust > 0.55 ? (noise(seg.seed * 0.3) - 0.5) * 1.4 : 0;
  const topCol = rust > 0.5 ? PALETTE.rustMid : PALETTE.scratchFine;
  brush.set(rust > 0.6 ? "needle" : "needle_hair", topCol, 0.8 + rust * 0.35);
  brush.line(
    ax0 - nx * (r + topJitter),
    ay0 - ny * (r + topJitter),
    ax1 - nx * (r - topJitter),
    ay1 - ny * (r - topJitter)
  );

  // 4. Longitudinal drawn-steel striae & cylindrical shading lines across [-0.35, +0.92]
  const uPositions = [-0.28, 0.02, 0.28, 0.50, 0.68, 0.82, 0.94];
  for (let idx = 0; idx < uPositions.length; idx++) {
    const u = uPositions[idx];
    // Skip some mid-lit lines where metal is smooth and unrusted
    if (u < 0.15 && rust < 0.38 && (seg.seed + idx) % 3 !== 0) continue;

    const lineCol =
      u > 0.65
        ? PALETTE.inkDark
        : rust > 0.45
        ? PALETTE.rustDark
        : PALETTE.inkMid;
    const lineW = map(u, -0.3, 0.95, 0.55, 1.15) * (r / 6.0);

    brush.set(u > 0.6 ? "burr_core" : "needle", lineCol, lineW);
    brush.line(
      ax0 + nx * r * u,
      ay0 + ny * r * u,
      ax1 + nx * r * u,
      ay1 + ny * r * u
    );
  }

  // 5. Curved Cross-Contour Hatching (wrapping around the 3D cylinder)
  const numCross = floor(map(r, 4.5, 7.5, 2.2, 4.2) + rust * 2.2);
  for (let c = 0; c < numCross; c++) {
    const tFrac = (c + 0.5) / numCross;
    const bx = lerp(x0, x1, tFrac);
    const by = lerp(y0, y1, tFrac);

    // Start higher on the cylinder if rusted, lower if clean steel
    const uStart = rust > 0.45 ? random(-0.75, -0.15) : random(-0.15, 0.25);
    const uEnd = random(0.88, 1.04);

    // Elliptical curvature along the tangent axis to convey cylindrical roundness
    const curveBow = r * 0.38;
    const pStart = [bx + nx * r * uStart - tx * curveBow * 0.4, by + ny * r * uStart - ty * curveBow * 0.4, 0.5];
    const pMid = [bx + nx * r * (0.5 * (uStart + uEnd)) + tx * curveBow * 0.5, by + ny * r * (0.5 * (uStart + uEnd)) + ty * curveBow * 0.5, 1.0];
    const pEnd = [bx + nx * r * uEnd - tx * curveBow * 0.2, by + ny * r * uEnd - ty * curveBow * 0.2, 0.8];

    const hCol = rust > 0.5 ? PALETTE.rustDark : PALETTE.inkDark;
    brush.set("needle", hCol, random(0.65, 1.05));
    brush.spline([pStart, pMid, pEnd], 0.45);
  }

  // 6. Rust Texture: Tight opposing diagonal cross-hatching & stippled corrosion pits
  if (rust > 0.32) {
    const numRustHatches = floor((rust - 0.25) * 6.5);
    for (let rh = 0; rh < numRustHatches; rh++) {
      const f = random(0.05, 0.95);
      const rx = lerp(x0, x1, f);
      const ry = lerp(y0, y1, f);
      const uMid = random(-0.55, 0.75);
      const cx = rx + nx * r * uMid;
      const cy = ry + ny * r * uMid;

      // Diagonal scratch opposing the cross-contour angle
      const dLen = r * random(0.45, 0.85);
      const diagSign = rh % 2 === 0 ? 1 : -1;
      const dxDiag = (tx * 0.72 + nx * 0.68 * diagSign) * dLen;
      const dyDiag = (ty * 0.72 + ny * 0.68 * diagSign) * dLen;

      brush.set("needle", rh % 2 === 0 ? PALETTE.rustDark : PALETTE.inkBurr, random(0.6, 0.95));
      brush.line(cx - dxDiag * 0.5, cy - dyDiag * 0.5, cx + dxDiag * 0.5, cy + dyDiag * 0.5);
    }

    // Stippled rust pits eating into the metal surface
    if (rust > 0.48 && random() < 0.75) {
      const px = xm + nx * r * random(-0.6, 0.65);
      const py = ym + ny * r * random(-0.6, 0.65);
      brush.set("rust_pit", PALETTE.rustDark, map(rust, 0.45, 1, 0.45, 1.05));
      brush.line(px - tx * 2, py - ty * 2, px + tx * 2, py + ty * 2);
    }
  }

  // 7. THE DRYPOINT BURR: Soft, fuzzy velvety bloom along the shadow side & strand crevice
  const burrStrength = map(r, 4.8, 7.5, 0.68, 1.15) * (0.8 + rust * 0.35 + knotProximity * 0.3);

  // Soft outer velvety ink bloom offset slightly outside/below the lower contour
  brush.set("burr_velvet", PALETTE.inkBurr, burrStrength);
  brush.line(
    ax0 + nx * (r * 0.98 + 1.1),
    ay0 + ny * (r * 0.98 + 1.1),
    ax1 + nx * (r * 0.98 + 1.1),
    ay1 + ny * (r * 0.98 + 1.1)
  );

  // Deep velvety core cut on the lower contour
  brush.set("burr_core", PALETTE.inkBurr, burrStrength * 0.95);
  brush.line(
    ax0 + nx * r * 0.92,
    ay0 + ny * r * 0.92,
    ax1 + nx * r * rRatio(r),
    ay1 + ny * r * rRatio(r)
  );

  // Extra dark crevice burr where the two twisted strands pinch against each other
  if (pinchShadow > 0.45 || zHelix < 0) {
    const innerSide = zHelix < 0 ? -0.82 : 0.85;
    brush.set("burr_velvet", PALETTE.inkBurr, burrStrength * 0.75);
    brush.line(
      ax0 + nx * r * innerSide,
      ay0 + ny * r * innerSide,
      ax1 + nx * r * innerSide,
      ay1 + ny * r * innerSide
    );
  }

  // 8. Occasional frost crystal specks reserved on the cold upper ridge of the wire
  if (zHelix > 0 && knotProximity > 0.25 && (seg.seed % 5 === 0)) {
    drawFrostCluster(
      xm - nx * r * 0.78,
      ym - ny * r * 0.78,
      nx,
      ny,
      r * 0.32,
      2
    );
  }
}

function rRatio(r) {
  return 0.92;
}

function renderCollarWrap(wrap) {
  const { cx, cy, tx, ty, nx, ny, collarR, wrapR, tilt, rust, isOuter, seed } = wrap;

  // Endpoints of this wrap coil across the wire bundle
  const topX = cx - nx * collarR - tx * tilt;
  const topY = cy - ny * collarR - ty * tilt;
  const botX = cx + nx * collarR + tx * tilt;
  const botY = cy + ny * collarR + ty * tilt;

  // Bowed midpoint so the wrap coil looks like a plump 3D torus ring hugging the wire
  const bow = wrapR * 0.65;
  const midX = cx + tx * bow;
  const midY = cy + ty * bow;

  // 1. Opaque mask for the wrap coil body
  const maskCol = getSkyToneAt(cx, cy);
  brush.set("wire_mask", maskCol, wrapR * 0.42);
  brush.spline(
    [
      [topX, topY, 0.9],
      [midX, midY, 1.0],
      [botX, botY, 0.9]
    ],
    0.45
  );

  // 2. Deep crevice burr between adjacent coils of the knot
  const shadowOff = wrapR * 0.78;
  brush.set("burr_smoke", PALETTE.inkBurr, 0.85);
  brush.line(topX + tx * shadowOff, topY + ty * shadowOff, botX + tx * shadowOff, botY + ty * shadowOff);

  brush.set("burr_velvet", PALETTE.inkBurr, 0.95);
  brush.spline(
    [
      [topX + tx * shadowOff * 0.85, topY + ty * shadowOff * 0.85, 0.7],
      [midX + tx * shadowOff * 0.95, midY + ty * shadowOff * 0.95, 1.1],
      [botX + tx * shadowOff * 0.85, botY + ty * shadowOff * 0.85, 0.9]
    ],
    0.45
  );

  // 3. Incised edges of the wrap wire
  brush.set("burr_core", PALETTE.inkDark, 0.9);
  brush.spline(
    [
      [topX - tx * wrapR * 0.65, topY - ty * wrapR * 0.65, 0.6],
      [midX - tx * wrapR * 0.65, midY - ty * wrapR * 0.65, 0.9],
      [botX - tx * wrapR * 0.65, botY - ty * wrapR * 0.65, 0.8]
    ],
    0.45
  );

  brush.set("burr_core", PALETTE.inkBurr, 1.05);
  brush.spline(
    [
      [topX + tx * wrapR * 0.68, topY + ty * wrapR * 0.68, 0.7],
      [midX + tx * wrapR * 0.68, midY + ty * wrapR * 0.68, 1.1],
      [botX + tx * wrapR * 0.68, botY + ty * wrapR * 0.68, 1.0]
    ],
    0.45
  );

  // 4. Longitudinal & cross-contour shading across the wrap ring (darker toward bottom)
  const steps = 7;
  for (let i = 0; i <= steps; i++) {
    const u = map(i, 0, steps, -0.92, 0.95);
    const px = lerp(topX, botX, (u + 1) * 0.5) + tx * bow * (1 - u * u);
    const py = lerp(topY, botY, (u + 1) * 0.5) + ty * bow * (1 - u * u);

    if (u > -0.25 || rust > 0.55) {
      const col = u > 0.35 ? PALETTE.inkBurr : PALETTE.rustDark;
      const w = map(u, -0.4, 1.0, 0.55, 1.15);
      brush.set(u > 0.45 ? "burr_core" : "needle", col, w);
      brush.line(
        px - tx * wrapR * 0.62,
        py - ty * wrapR * 0.62,
        px + tx * wrapR * 0.68,
        py + ty * wrapR * 0.68
      );
    }
  }

  // 5. Heavy velvety burr under the bottom knuckle of the collar wrap
  brush.set("burr_velvet", PALETTE.inkBurr, 1.25);
  brush.line(
    botX - tx * wrapR * 0.8,
    botY - ty * wrapR * 0.8 + 1.2,
    botX + tx * wrapR * 0.9,
    botY + ty * wrapR * 0.9 + 1.2
  );

  // 6. Stippled rust pits in the collar crevices
  brush.set("rust_pit", PALETTE.rustDark, 0.85);
  brush.line(midX - nx * collarR * 0.2, midY - ny * collarR * 0.2, botX, botY);

  // 7. Reserved bare-paper frost crystals on the upper knuckle of the wrap
  if (seed % 2 === 0 || isOuter) {
    drawFrostCluster(topX, topY, -nx, -ny, wrapR * 0.65, 3);
  }
}

function renderBarbSpike(spike) {
  const { x0, y0, x1, y1, dirX, dirY, perpX, perpY, len, baseR, radDepth, rust, bevelSide } = spike;

  // Ensureperp points toward the shadow side (downward-right) for consistent lighting
  let sx = perpX;
  let sy = perpY;
  if (sy < -0.15 || (abs(sy) <= 0.15 && sx < 0)) {
    sx = -sx;
    sy = -sy;
  }

  // Diagonal factory shear bevel starts at 68% of the spike length
  const bevelFrac = 0.68;
  const bx = lerp(x0, x1, bevelFrac);
  const by = lerp(y0, y1, bevelFrac);
  const bevelR = baseR * 0.72;

  // 1. Opaque mask along the tapered spike shaft
  const maskCol = getSkyToneAt(0.5 * (x0 + x1), 0.5 * (y0 + y1));
  brush.set("wire_mask", maskCol, baseR * 0.36);
  brush.line(x0, y0, bx, by);
  brush.set("wire_mask", maskCol, baseR * 0.18);
  brush.line(bx, by, lerp(bx, x1, 0.7), lerp(by, y1, 0.7));

  // 2. Shadow-side velvety drypoint burr (blooms softly along the dark underside of the barb)
  const burrW = map(baseR, 3.5, 6.5, 0.8, 1.35) * (radDepth > 0 ? 1.12 : 0.82);
  brush.set("burr_smoke", PALETTE.inkBurr, burrW * 0.85);
  brush.line(
    x0 + sx * (baseR * 1.08),
    y0 + sy * (baseR * 1.08),
    x1 + sx * 1.4,
    y1 + sy * 1.4
  );

  brush.set("burr_velvet", PALETTE.inkBurr, burrW);
  brush.line(
    x0 + sx * (baseR * 0.92),
    y0 + sy * (baseR * 0.92),
    x1 + sx * 0.8,
    y1 + sy * 0.8
  );

  // 3. Longitudinal tapered shading lines from collar to bevel
  const shaftLines = [-0.45, -0.1, 0.25, 0.55, 0.82];
  for (let u of shaftLines) {
    const col = u > 0.35 ? PALETTE.inkBurr : PALETTE.rustDark;
    const w = map(u, -0.5, 0.85, 0.55, 1.05);
    brush.set(u > 0.4 ? "burr_core" : "needle", col, w);
    brush.line(
      x0 + sx * baseR * u,
      y0 + sy * baseR * u,
      bx + sx * bevelR * u,
      by + sy * bevelR * u
    );
  }

  // 4. Cross-contour rings & rust cross-hatching along the spike shaft
  const numRings = floor(len / 5.5);
  for (let rIdx = 1; rIdx < numRings; rIdx++) {
    const f = (rIdx / numRings) * bevelFrac;
    const rx = lerp(x0, x1, f);
    const ry = lerp(y0, y1, f);
    const localR = lerp(baseR, bevelR, f / bevelFrac);

    brush.set("needle", PALETTE.inkDark, 0.75);
    brush.line(
      rx - sx * localR * 0.45,
      ry - sy * localR * 0.45,
      rx + sx * localR * 0.98,
      ry + sy * localR * 0.98
    );

    // Tight opposing diagonal rust hatch
    if (rIdx % 2 === 0 && rust > 0.4) {
      brush.set("needle", PALETTE.rustDark, 0.7);
      brush.line(
        rx - sx * localR * 0.6 - dirX * 2.5,
        ry - sy * localR * 0.6 - dirY * 2.5,
        rx + sx * localR * 0.8 + dirX * 2.5,
        ry + sy * localR * 0.8 + dirY * 2.5
      );
    }
  }

  // 5. Sharp Outer Contours & Chisel-Cut Diagonal Bevel Tip
  // Lit upper edge from base to bevel shoulder
  brush.set("needle", PALETTE.inkMid, 0.85);
  brush.line(
    x0 - sx * baseR * 0.88,
    y0 - sy * baseR * 0.88,
    bx - sx * bevelR * 0.85,
    by - sy * bevelR * 0.85
  );

  // Dark lower edge from base right out to the razor tip
  brush.set("burr_core", PALETTE.inkBurr, 1.1);
  brush.line(
    x0 + sx * baseR * 0.92,
    y0 + sy * baseR * 0.92,
    x1,
    y1
  );

  // Diagonal sheared bevel face at the tip (characteristic flat oval cut of real barbed wire)
  brush.set("burr_core", PALETTE.inkDark, 0.95);
  brush.line(
    bx - sx * bevelR * 0.85,
    by - sy * bevelR * 0.85,
    x1,
    y1
  );
  // Inner bevel rim creating the 3D chisel facet
  brush.set("needle", PALETTE.inkMid, 0.75);
  brush.spline(
    [
      [bx - sx * bevelR * 0.85, by - sy * bevelR * 0.85, 0.7],
      [lerp(bx, x1, 0.45) + sx * bevelR * 0.25, lerp(by, y1, 0.45) + sy * bevelR * 0.25, 1.0],
      [x1, y1, 0.9]
    ],
    0.4
  );

  // Needle-sharp final drypoint prick at the apex of the barb
  brush.set("needle", PALETTE.inkBurr, 0.9);
  brush.line(x1 - dirX * 2, y1 - dirY * 2, x1 + dirX * 2.2, y1 + dirY * 2.2);

  // 6. FROST CRYSTALS ON THE BARBS (Tiny reserved specks of bare paper!)
  // Clustered along the upper cold ridge, bevel shoulder, and sharp tip of the barb
  drawFrostCluster(
    bx - sx * bevelR * 0.85,
    by - sy * bevelR * 0.85,
    -sx,
    -sy,
    baseR * 0.58,
    4
  );
  drawFrostCluster(
    lerp(bx, x1, 0.65) - sx * 1.1,
    lerp(by, y1, 0.65) - sy * 1.1,
    dirX - sx * 0.6,
    dirY - sy * 0.6,
    baseR * 0.48,
    3
  );
  // Tiny frost glint right near the needle tip
  drawFrostCluster(
    x1 + dirX * 0.8 - sx * 0.6,
    y1 + dirY * 0.8 - sy * 0.6,
    dirX,
    dirY,
    baseR * 0.35,
    2
  );
}

// Renders tiny reserved specks of bare cream paper + microscopic crystalline hoarfrost needles
function drawFrostCluster(cx, cy, outX, outY, scaleR, count) {
  const tangX = -outY;
  const tangY = outX;

  for (let i = 0; i < count; i++) {
    const spreadT = (i - (count - 1) * 0.5) * scaleR * 0.95 + random(-1.2, 1.2);
    const spreadN = random(0.1, scaleR * 0.75);
    const fx = cx + tangX * spreadT + outX * spreadN;
    const fy = cy + tangY * spreadT + outY * spreadN;
    const speckLen = random(1.8, 3.8) * (scaleR / 2.8);
    const ang = atan2(outY, outX) + random(-55, 55);

    // Tiny shadow cradle scored under the frost speck so the bare paper pops with hyperreal contrast
    brush.set("needle_hair", PALETTE.inkDark, 0.55);
    brush.line(
      fx - cos(ang) * speckLen * 0.5,
      fy - sin(ang) * speckLen * 0.5 + 0.9,
      fx + cos(ang) * speckLen * 0.6,
      fy + sin(ang) * speckLen * 0.6 + 0.9
    );

    // Reserved bare-paper crystal speck (scraped clean on the copperplate)
    brush.set("frost_reserve", PALETTE.paperBright, random(0.85, 1.35));
    brush.line(
      fx - cos(ang) * speckLen * 0.5,
      fy - sin(ang) * speckLen * 0.5,
      fx + cos(ang) * speckLen * 0.5,
      fy + sin(ang) * speckLen * 0.5
    );
    // Cross-facet of the ice crystal speck
    brush.set("frost_reserve", PALETTE.paper, random(0.7, 1.1));
    brush.line(
      fx - sin(ang) * speckLen * 0.35,
      fy + cos(ang) * speckLen * 0.35,
      fx + sin(ang) * speckLen * 0.35,
      fy - cos(ang) * speckLen * 0.35
    );
  }
}

// =============================================================================
// 5. FOREGROUND ACCENTS: DRYPOINT SPLINTERS, CORROSION BURRS & HOARFROST SPECKS
// =============================================================================
function renderForegroundAccents(sceneItems) {
  for (let i = 0; i < sceneItems.length; i++) {
    const item = sceneItems[i];

    // Add tiny erratic drypoint needle splinters and corrosion flakes on foreground barbs
    if (item.type === "barbSpike" && item.z > 0) {
      // Wiry needle scratch extending slightly past the tip into the copperplate
      brush.set("needle_hair", PALETTE.scratchFine, 0.5);
      brush.line(
        item.x1,
        item.y1,
        item.x1 + item.dirX * random(3.5, 8.5),
        item.y1 + item.dirY * random(3.5, 8.5)
      );

      // Extra cluster of bare-paper frost specks along the upper shaft of hero barbs
      if (item.baseR > 4.8) {
        const mx = lerp(item.x0, item.x1, 0.38) - item.perpX * item.baseR * 0.75;
        const my = lerp(item.y0, item.y1, 0.38) - item.perpY * item.baseR * 0.75;
        drawFrostCluster(mx, my, -item.perpX, -item.perpY, item.baseR * 0.5, 3);
      }
    }

    // Add tiny pitted rust burrs & frost specks on the closest hero wire segments
    if (item.type === "strandSeg" && item.r > 6.5 && i % 4 === 0) {
      const xm = 0.5 * (item.x0 + item.x1);
      const ym = 0.5 * (item.y0 + item.y1);

      if (item.rust > 0.52) {
        // Tiny jagged rust scale flaking on the lower shadow edge
        brush.set("needle", PALETTE.inkBurr, 0.75);
        brush.line(
          xm + item.nx * item.r * 0.95,
          ym + item.ny * item.r * 0.95,
          xm + item.nx * (item.r * 1.18) + item.tx * 3.5,
          ym + item.ny * (item.r * 1.18) + item.ty * 3.5
        );
      }

      if (item.zHelix > 2.0 && i % 8 === 0) {
        drawFrostCluster(
          xm - item.nx * item.r * 0.85,
          ym - item.ny * item.r * 0.85,
          -item.nx,
          -item.ny,
          2.2,
          2
        );
      }
    }
  }
}

// =============================================================================
// 6. AUTHENTIC COPPERPLATE BEVEL IMPRESSION & CREAM RAG PAPER MARGINS
// =============================================================================
function renderPlateBevelAndMargins(PLATE) {
  const { x1, y1, x2, y2 } = PLATE;

  // Clean up any stray bleed in the outer rag paper margins while preserving deckle warmth
  brush.noStroke();
  brush.wash(PALETTE.paper, 195);
  brush.rect(0, 0, 1200, y1 - 2, "corner");
  brush.rect(0, y2 + 2, 1200, 1200 - (y2 + 2), "corner");
  brush.rect(0, y1 - 2, x1 - 2, y2 - y1 + 4, "corner");
  brush.rect(x2 + 2, y1 - 2, 1200 - (x2 + 2), y2 - y1 + 4, "corner");
  brush.noWash();

  // Outer debossed bevel shadow in the rag paper (7px outside plate edge)
  const bOff = 7;
  brush.set("2H", PALETTE.toneMid, 0.55);
  brush.line(x1 - bOff, y1 - bOff, x2 + bOff, y1 - bOff);
  brush.line(x1 - bOff, y1 - bOff, x1 - bOff, y2 + bOff);

  brush.set("frost_reserve", PALETTE.paperBright, 0.9);
  brush.line(x1 - bOff, y2 + bOff, x2 + bOff, y2 + bOff);
  brush.line(x2 + bOff, y1 - bOff, x2 + bOff, y2 + bOff);

  // Inner copperplate edge where residual ink catches along the bevelled metal rim
  brush.set("needle", PALETTE.toneCorner, 0.75);
  brush.line(x1, y1, x2, y1);
  brush.line(x2, y1, x2, y2);
  brush.line(x2, y2, x1, y2);
  brush.line(x1, y2, x1, y1);

  // Heavier ink pooling & burr smudge right in the four corners of the copper plate
  const cLen = 85;
  const corners = [
    [x1, y1, 1, 1],
    [x2, y1, -1, 1],
    [x2, y2, -1, -1],
    [x1, y2, 1, -1]
  ];
  for (let [cx, cy, dx, dy] of corners) {
    brush.set("burr_velvet", PALETTE.toneDeepCorner, 0.65);
    brush.line(cx, cy, cx + dx * cLen, cy);
    brush.line(cx, cy, cx, cy + dy * cLen);

    brush.set("burr_core", PALETTE.rustDark, 0.6);
    brush.line(cx, cy, cx + dx * (cLen * 0.45), cy);
    brush.line(cx, cy, cx, cy + dy * (cLen * 0.45));
  }
}

// Hyperrealism in p5.brush: Stand-Mixer Bowl & Spiralling Flour Vortex
// Palette: Cool Steel, Bone, Ivory, and Pale Wheat

const BCX = 555; // Bowl center X
const BCY = 635; // Bowl center Y
const VX = 585;  // Vortex high-altitude core X
const VY = 555;  // Vortex high-altitude core Y

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Custom brush for fine anisotropic brushed-steel grain & razor cracks
  brush.add("steel_grain", {
    type: "default",
    weight: 0.35,
    scatter: 0.08,
    sharpness: 0.85,
    grain: 0.65,
    opacity: 95,
    spacing: 0.25,
    pressure: [0.3, 1.0, 0.3],
    noise: 0.3
  });

  // Custom brush for velvety flour mist & soft airborne veils
  brush.add("flour_veil", {
    type: "spray",
    weight: 14,
    scatter: 4.5,
    opacity: 18,
    spacing: 0.6,
    pressure: [0.4, 1.2, 0.4],
    noise: 0.8
  });

  // Custom brush for crisp escaping flour particles & stippled specks
  brush.add("flour_speck", {
    type: "spray",
    weight: 2.2,
    scatter: 1.8,
    opacity: 165,
    spacing: 1.4,
    pressure: [0.8, 1.0, 0.5],
    noise: 0.5
  });

  // Custom spiral dust-devil vector field tightening toward (VX, VY)
  brush.addField("vortex_plume", (t, field) => {
    let cols = field.length;
    let rows = field[0].length;
    for (let col = 0; col < cols; col++) {
      for (let row = 0; row < rows; row++) {
        let x = (col / cols) * 1200;
        let y = (row / rows) * 1200;
        let dx = x - VX;
        let dy = y - VY;
        let d = sqrt(dx * dx + dy * dy);
        let baseAngle = atan2(dy, dx);
        // Spiral inward: tangent (90 deg) + inward pull (22 to 42 deg depending on radius)
        let inwardPull = map(constrain(d, 10, 520), 10, 520, 38, 18);
        let turb = (noise(col * 0.08, row * 0.08, t * 0.1) - 0.5) * map(constrain(d, 0, 400), 0, 400, 48, 12);
        field[col][row] = baseAngle + 90 + inwardPull + turb;
      }
    }
    return field;
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#181e24");

  // 1. Honed dark slate countertop & ambient cast shadows
  drawCountertop();

  // 2. Stainless steel bowl interior, anisotropic brushed metal & warped plume reflections
  drawBowlInterior();

  // 3. Bowl floor: raw flour bed, softened butter chunks, broken egg & starting mixer paddle
  drawBowlFloorAndPaddle();

  // 4. Stainless steel rim, bevels & mixer mounting lugs
  drawSteelRim();

  // 5. Still-life details at the rim: crinkled butter wrapper & cracked eggshells
  drawButterWrapper();
  drawCrackedEggshells();

  // 6. The spiralling flour plume (multi-layered pencil flow-field vortex + spray veils + stipple)
  drawFlourVortex();

  // 7. Final foreground escaping flour specks & specular highlights
  drawEscapingParticles();

  noLoop();
}

// ============================================================================
// HELPER: Draw smooth closed polygon with p5.brush
// ============================================================================
function drawClosedShape(pts, curv = 0.3) {
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function makeCirclePts(cx, cy, r, n = 36, wobble = 0, rxScale = 1, ryScale = 1) {
  let pts = [];
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    let rad = r + (wobble > 0 ? (noise(cos(a) * 1.5 + cx * 0.01, sin(a) * 1.5 + cy * 0.01) - 0.5) * wobble : 0);
    pts.push([cx + cos(a) * rad * rxScale, cy + sin(a) * rad * ryScale]);
  }
  return pts;
}

// ============================================================================
// 1. COUNTERTOP (Honed Cool Slate & Ambient Occlusion)
// ============================================================================
function drawCountertop() {
  brush.noField();
  brush.noStroke();

  // Atmospheric slate washes in the corners
  const slateZones = [
    { x: 180, y: 180, r: 340, col: "#232c36", op: 95 },
    { x: 1020, y: 200, r: 360, col: "#1f2730", op: 110 },
    { x: 160, y: 1020, r: 320, col: "#14191f", op: 130 },
    { x: 1040, y: 1020, r: 380, col: "#101419", op: 150 },
    // Deep cast shadow of the bowl (light coming from upper-left / top)
    { x: BCX + 35, y: BCY + 45, r: 505, col: "#0b0e12", op: 175 },
    { x: BCX + 18, y: BCY + 22, r: 485, col: "#0e1217", op: 160 }
  ];

  for (let z of slateZones) {
    brush.fill(z.col, z.op);
    brush.fillBleed(0.4, "out");
    brush.fillTexture(0.65, 0.25);
    drawClosedShape(makeCirclePts(z.x, z.y, z.r, 32, 18), 0.35);
  }
  brush.noFill();

  // Fine mineral grain & honed stone texture outside the bowl
  for (let i = 0; i < 320; i++) {
    let ang = random(360);
    let rad = random(465, 840);
    let x = BCX + cos(ang) * rad;
    let y = BCY + sin(ang) * rad;
    if (x < -20 || x > 1220 || y < -20 || y > 1220) continue;

    let col = random(["#2a333d", "#343f4b", "#14181e", "#43505e"]);
    brush.set("2H", col, random(0.4, 1.1));
    let len = random(18, 65);
    let dir = random(-25, 15);
    brush.line(x, y, x + cos(dir) * len, y + sin(dir) * len);
  }

  // Subtle stone stipple
  for (let i = 0; i < 180; i++) {
    let ang = random(360);
    let rad = random(470, 820);
    let x = BCX + cos(ang) * rad;
    let y = BCY + sin(ang) * rad;
    if (x < 0 || x > 1200 || y < 0 || y > 1200) continue;
    brush.set("spray", random(["#2e3842", "#12161b", "#4c5968"]), random(0.6, 1.4));
    brush.line(x, y, x + random(-12, 12), y + random(-12, 12));
  }
}

// ============================================================================
// 2. STAINLESS STEEL BOWL INTERIOR & WARPED PLUME REFLECTIONS
// ============================================================================
// Returns the center of the bowl cross-section at normalized depth t (0 = base, 1 = inner rim)
function bowlCenterAt(t) {
  // Slight perspective shift: bottom well is slightly up-left relative to rim
  return {
    x: lerp(BCX - 14, BCX, t),
    y: lerp(BCY + 16, BCY, t),
    r: lerp(235, 426, pow(t, 0.88))
  };
}

function drawBowlInterior() {
  brush.noField();
  brush.noStroke();

  // Base dark steel foundation for the bowl interior
  brush.wash("#1a222b", 245);
  drawClosedShape(makeCirclePts(BCX, BCY, 428, 48, 0), 0.25);
  brush.noWash();

  // Watercolor/wash metallic reflection lobes around the concave wall
  const lobeSpecs = [
    // Deep steel shadow lobes (top-left ~225 deg & bottom-right ~35 deg)
    { a1: 195, a2: 260, rIn: 220, rOut: 425, col: "#10151c", op: 170 },
    { a1: 210, a2: 245, rIn: 240, rOut: 420, col: "#0c1015", op: 160 },
    { a1: 10,  a2: 75,  rIn: 220, rOut: 425, col: "#141b24", op: 165 },
    // Cool slate midtone transitions
    { a1: 255, a2: 300, rIn: 230, rOut: 425, col: "#3c4b5c", op: 110 },
    { a1: 70,  a2: 125, rIn: 230, rOut: 425, col: "#364454", op: 110 },
    // Bright specular anisotropic bands (~145 deg & ~315 deg)
    { a1: 120, a2: 175, rIn: 230, rOut: 425, col: "#7a8ea3", op: 120 },
    { a1: 132, a2: 162, rIn: 240, rOut: 422, col: "#b3c4d6", op: 135 },
    { a1: 295, a2: 348, rIn: 230, rOut: 425, col: "#8599ad", op: 125 },
    { a1: 308, a2: 335, rIn: 245, rOut: 422, col: "#c7d7e6", op: 140 },
    // Warped cool-wheat & bone reflections of the central flour plume on the steel walls
    { a1: 155, a2: 205, rIn: 250, rOut: 410, col: "#9ea3a6", op: 95 },
    { a1: 335, a2: 380, rIn: 255, rOut: 405, col: "#b5b4ad", op: 90 },
    { a1: 245, a2: 295, rIn: 260, rOut: 395, col: "#8c9296", op: 85 }
  ];

  for (let s of lobeSpecs) {
    brush.fill(s.col, s.op);
    brush.fillBleed(0.28, "in");
    brush.fillTexture(0.45, 0.15);
    let pts = [];
    let steps = 14;
    for (let i = 0; i <= steps; i++) {
      let a = lerp(s.a1, s.a2, i / steps);
      pts.push([BCX + cos(a) * s.rOut, BCY + sin(a) * s.rOut]);
    }
    for (let i = steps; i >= 0; i--) {
      let a = lerp(s.a1, s.a2, i / steps);
      pts.push([BCX - 10 + cos(a) * s.rIn, BCY + 12 + sin(a) * s.rIn]);
    }
    drawClosedShape(pts, 0.25);
  }
  brush.noFill();

  // Concentric lathe-spun brushed steel lines (anisotropic metallic sheen)
  // We draw ~420 segmented arcs along the concave wall
  let numRings = 72;
  for (let ring = 0; ring < numRings; ring++) {
    let t = ring / (numRings - 1);
    let c = bowlCenterAt(t);

    // Break each ring into angular segments to vary color with specular reflection
    let segs = 12;
    for (let s = 0; s < segs; s++) {
      let aStart = s * (360 / segs) + random(-6, 6);
      let aEnd = aStart + (360 / segs) + random(-4, 8);
      let aMid = (aStart + aEnd) * 0.5;

      // Calculate anisotropic metallic reflectance + warped flour reflection
      let spec1 = pow(max(0, cos(aMid - 146)), 4);
      let spec2 = pow(max(0, cos(aMid - 322)), 4);
      let dark1 = pow(max(0, cos(aMid - 228)), 3);
      let dark2 = pow(max(0, cos(aMid - 42)), 3);

      // Warped spiral plume reflection wave on the concave wall
      let plumeWave = sin(aMid * 2 - t * 220 + noise(aMid * 0.03, t * 4) * 90);
      let isPlumeRefl = plumeWave > 0.25 && t > 0.12 && t < 0.92;

      let col;
      let w = random(0.35, 0.95);
      if (spec1 + spec2 > 0.55) {
        col = random(["#d6e3f0", "#eef6fc", "#ffffff", "#b8cadb"]);
        w = random(0.5, 1.2);
      } else if (isPlumeRefl && random() < 0.65) {
        // Cool grey and muted bone-wheat warped reflection streaks
        col = random(["#9aa1a6", "#b4b7b6", "#cbc9c1", "#858d94", "#dad6cb"]);
        w = random(0.55, 1.3);
      } else if (dark1 + dark2 > 0.45) {
        col = random(["#10151c", "#182029", "#222c38", "#2d3947"]);
      } else {
        col = random(["#3b4959", "#4f6073", "#64778c", "#7c90a6"]);
      }

      brush.set(random() < 0.7 ? "steel_grain" : "2H", col, w);
      let arcPts = [];
      let nPts = 5;
      for (let k = 0; k <= nPts; k++) {
        let ang = lerp(aStart, aEnd, k / nPts);
        let rad = c.r + (noise(ring * 0.3, k * 0.2) - 0.5) * 2.5;
        arcPts.push([c.x + cos(ang) * rad, c.y + sin(ang) * rad, random(0.5, 1.1)]);
      }
      brush.spline(arcPts, 0.4);
    }
  }

  // Explicit warped reflection streaks of the spiralling plume stretching along the steel wall
  for (let i = 0; i < 165; i++) {
    let tStart = random(0.08, 0.65);
    let tEnd = constrain(tStart + random(0.18, 0.38), 0.15, 0.96);
    let baseAng = random(360);
    // Concave mirror warps radial lines into S-curved tangential streaks
    let sweep = random(22, 58) * (random() < 0.8 ? 1 : -1);

    let pts = [];
    let steps = 6;
    for (let k = 0; k <= steps; k++) {
      let u = k / steps;
      let t = lerp(tStart, tEnd, u);
      let c = bowlCenterAt(t);
      let ang = baseAng + sweep * sin(u * 140) + (noise(i, u * 2) - 0.5) * 14;
      pts.push([c.x + cos(ang) * c.r, c.y + sin(ang) * c.r, sin(u * 180) * 1.1 + 0.2]);
    }

    let reflPalette = ["#8b9299", "#a3a8ac", "#babbbd", "#cfccc3", "#dfe0dd", "#6d7680"];
    brush.set(random(["HB", "2H", "cpencil"]), random(reflPalette), random(0.45, 1.25));
    brush.spline(pts, 0.5);
  }
}

// ============================================================================
// 3. BOWL FLOOR, RAW FLOUR MOUND, BUTTER & STARTING MIXER PADDLE
// ============================================================================
function drawBowlFloorAndPaddle() {
  brush.noField();
  let baseC = bowlCenterAt(0);

  // Dark metallic well at the bottom of the bowl
  brush.noStroke();
  brush.fill("#222b36", 180);
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.5, 0.2);
  drawClosedShape(makeCirclePts(baseC.x, baseC.y, baseC.r, 36, 6), 0.3);
  brush.noFill();

  // Concentric brushed steel rings on the bottom floor before the flour mound covers it
  for (let r = 40; r < baseC.r; r += 5.5) {
    for (let s = 0; s < 6; s++) {
      let a1 = s * 60 + random(-8, 8);
      let a2 = a1 + 52;
      let col = random(["#2d3947", "#465668", "#65788c", "#192029", "#8ea1b5"]);
      brush.set("steel_grain", col, random(0.35, 0.8));
      brush.arc(baseC.x, baseC.y, r, a1, a2);
    }
  }

  // Unmixed bed of wheat flour & pale butter at the bottom of the bowl
  const flourBedLayers = [
    { x: baseC.x + 10, y: baseC.y - 5, r: 210, col: "#8c8f91", op: 155, wob: 45 },
    { x: baseC.x + 15, y: baseC.y - 12, r: 185, col: "#b5b1a7", op: 175, wob: 40 },
    { x: baseC.x + 22, y: baseC.y - 18, r: 155, col: "#d1cbc0", op: 190, wob: 35 },
    { x: baseC.x + 8,  y: baseC.y + 15, r: 135, col: "#e4dfd4", op: 185, wob: 30 }
  ];

  brush.noStroke();
  for (let fl of flourBedLayers) {
    brush.fill(fl.col, fl.op);
    brush.fillBleed(0.35, "out");
    brush.fillTexture(0.65, 0.3);
    drawClosedShape(makeCirclePts(fl.x, fl.y, fl.r, 32, fl.wob), 0.4);
  }
  brush.noFill();

  // Softened pale butter chunks & a glossy egg yolk/albumen pocket being caught by the paddle
  const butterChunks = [
    { x: baseC.x - 65, y: baseC.y + 55, r: 34, col: "#dfd5b6" },
    { x: baseC.x - 45, y: baseC.y + 72, r: 24, col: "#eee6cc" },
    { x: baseC.x + 85, y: baseC.y + 48, r: 28, col: "#d9cfa8" }
  ];
  for (let b of butterChunks) {
    brush.noStroke();
    brush.mass("cpencil", b.col, { precision: 0.75, strength: 0.8, gradient: 0.25, outline: false });
    drawClosedShape(makeCirclePts(b.x, b.y, b.r, 14, 10), 0.25);
    brush.noMass();

    // Crisp flour-dusted creases on the butter cubes
    brush.set("2H", "#948c75", 0.65);
    brush.line(b.x - b.r * 0.6, b.y - b.r * 0.2, b.x + b.r * 0.5, b.y + b.r * 0.4);
    brush.set("cpencil", "#faf7ed", 0.8);
    brush.line(b.x - b.r * 0.5, b.y - b.r * 0.4, b.x + b.r * 0.3, b.y - b.r * 0.2);
  }

  // Glossy muted-wheat yolk & albumen swirl at bottom-left of the well
  let ykX = baseC.x - 25, ykY = baseC.y + 92;
  brush.noStroke();
  brush.fill("#bda05e", 190);
  brush.fillBleed(0.15, "in");
  drawClosedShape(makeCirclePts(ykX, ykY, 26, 20, 5), 0.35);
  brush.fill("#d9bf7e", 170);
  drawClosedShape(makeCirclePts(ykX - 5, ykY - 4, 16, 16, 3), 0.35);
  brush.noFill();
  brush.set("pen", "#ffffff", 1.1);
  brush.arc(ykX - 6, ykY - 6, 11, 200, 295);

  // --------------------------------------------------------------------------
  // THE STAND-MIXER FLAT BEATER (PADDLE) STARTING ITS ROTATION
  // Seen foreshortened from above: emerging from planetary shaft at upper-left
  // --------------------------------------------------------------------------
  push();
  // Paddle blade spans from (445, 535) through (545, 635) to (630, 710)
  const paddleShadowPts = [
    [455, 555], [515, 525], [645, 650], [635, 725], [565, 735], [445, 610]
  ];
  brush.noStroke();
  brush.fill("#182029", 185);
  brush.fillBleed(0.2, "out");
  drawClosedShape(paddleShadowPts, 0.25);
  brush.noFill();

  // Outer frame of the coated-steel flat beater paddle
  const paddleOuter = [
    [450, 540], [512, 515], [638, 638], [625, 712], [555, 720], [438, 598]
  ];
  brush.noStroke();
  brush.wash("#5c6d80", 235);
  drawClosedShape(paddleOuter, 0.2);
  brush.noWash();

  // Cutout windows of the flat beater (showing churned flour beneath)
  const window1 = [[475, 562], [510, 544], [565, 602], [532, 622]];
  const window2 = [[545, 638], [580, 615], [612, 668], [565, 695]];
  brush.noStroke();
  brush.wash("#c8c2b4", 225);
  drawClosedShape(window1, 0.15);
  drawClosedShape(window2, 0.15);
  brush.noWash();

  // Metallic specular highlights & structural ribs on the paddle
  brush.set("rotring", "#1d2630", 1.2);
  drawClosedShape(paddleOuter, 0.2);
  drawClosedShape(window1, 0.15);
  drawClosedShape(window2, 0.15);

  // Central spine of the beater
  brush.set("marker", "#8ea1b5", 2.2);
  brush.line(456, 548, 615, 698);
  brush.set("pen", "#eef5fc", 1.3);
  brush.line(458, 545, 618, 695);
  brush.set("pen", "#ffffff", 0.9);
  brush.line(512, 515, 636, 636);

  // Planetary mixer hub / stainless collar at upper-left (455, 540)
  brush.noStroke();
  brush.wash("#2b3642", 250);
  drawClosedShape(makeCirclePts(455, 540, 44, 28, 0), 0.2);
  brush.wash("#7c8fa3", 230);
  drawClosedShape(makeCirclePts(450, 535, 32, 24, 0), 0.2);
  brush.wash("#dae5f0", 240);
  drawClosedShape(makeCirclePts(444, 529, 16, 20, 0), 0.2);
  brush.noWash();

  brush.set("rotring", "#10151c", 1.1);
  brush.circle(455, 540, 44, 0.02);
  brush.circle(450, 535, 32, 0.02);
  pop();

  // Rotational shear furrows carved into the flour bed right behind the moving paddle
  for (let i = 0; i < 65; i++) {
    let r = random(45, 215);
    let a1 = random(0, 360);
    let a2 = a1 + random(25, 75);
    let col = random(["#6e747a", "#969897", "#ded9ce", "#f5f2ea", "#b3aea2"]);
    brush.set(random(["2B", "HB", "cpencil"]), col, random(0.5, 1.3));
    brush.arc(baseC.x + 10, baseC.y - 5, r, a1, a2);
  }
}

// ============================================================================
// 4. STAINLESS STEEL RIM, ROLLED LIP & MIXER BRACKET EARS
// ============================================================================
function drawSteelRim() {
  brush.noField();

  // Two side locking lugs / bowl handle ears at 195 deg (left) and 15 deg (right)
  const lugs = [
    { ang: 196, w: 24, radOut: 505 },
    { ang: 16,  w: 24, radOut: 498 }
  ];
  for (let lg of lugs) {
    let pts = [];
    for (let a = lg.ang - lg.w; a <= lg.ang + lg.w; a += 4) {
      pts.push([BCX + cos(a) * lg.radOut, BCY + sin(a) * lg.radOut]);
    }
    for (let a = lg.ang + lg.w; a >= lg.ang - lg.w; a -= 4) {
      pts.push([BCX + cos(a) * 455, BCY + sin(a) * 455]);
    }
    brush.noStroke();
    brush.wash("#3e4d5e", 245);
    drawClosedShape(pts, 0.2);
    brush.noWash();

    brush.set("rotring", "#11161d", 1.2);
    drawClosedShape(pts, 0.2);

    // Specular metallic highlight across the lug
    brush.set("pen", "#dce7f2", 1.1);
    let a1 = lg.ang - lg.w * 0.7;
    let a2 = lg.ang + lg.w * 0.7;
    brush.arc(BCX, BCY, lg.radOut - 6, a1, a2);
  }

  // Concentric brushed steel bands forming the wide flat rim (r = 426 to 466)
  for (let r = 426; r <= 466; r += 1.6) {
    let normR = (r - 426) / 40; // 0 = inner lip, 1 = outer lip
    let segs = 16;
    for (let s = 0; s < segs; s++) {
      let a1 = s * (360 / segs) + random(-3, 3);
      let a2 = a1 + (360 / segs) + 1;
      let aMid = (a1 + a2) * 0.5;

      // Rim catches bright overhead light on opposite quadrants from the concave wall
      let spec = pow(max(0, cos(aMid - 215)), 3) + pow(max(0, cos(aMid - 35)), 3);
      let dark = pow(max(0, cos(aMid - 125)), 3) + pow(max(0, cos(aMid - 305)), 3);

      let col;
      let w = 0.65;
      if (normR < 0.12) {
        // Sharp inner bevel edge
        col = spec > 0.35 ? "#ffffff" : "#141b24";
        w = 0.9;
      } else if (normR > 0.88) {
        // Sharp outer rolled edge
        col = spec > 0.3 ? "#eef5fc" : "#0e1319";
        w = 0.95;
      } else if (spec > 0.45) {
        col = random(["#d5e2ee", "#eef6fc", "#ffffff", "#b8c9da"]);
      } else if (dark > 0.45) {
        col = random(["#242e3b", "#313e4d", "#1b232e"]);
      } else {
        col = random(["#54667a", "#6d8094", "#8699ad", "#435363"]);
      }

      brush.set("steel_grain", col, w);
      brush.arc(BCX, BCY, r, a1, a2);
    }
  }

  // Crisp inner and outer rim boundary lines for hyperrealistic precision
  brush.set("rotring", "#0e131a", 1.1);
  brush.circle(BCX, BCY, 466, 0.008);
  brush.set("rotring", "#161d26", 0.9);
  brush.circle(BCX, BCY, 426, 0.008);

  // Razor-sharp specular highlight arcs along the rim bevels
  brush.set("pen", "#ffffff", 1.1);
  brush.arc(BCX, BCY, 428, 175, 265);
  brush.arc(BCX, BCY, 428, 355, 75);
  brush.arc(BCX, BCY, 463, 185, 255);
  brush.arc(BCX, BCY, 463, 5, 65);
}

