  // Jagged outer shell contour
  let shell1Outer = [];
  let n1 = 28;
  for (let i = 0; i < n1; i++) {
    let a = (i / n1) * 360;
    // Jagged saw-tooth fracture on the upper-right side (a between -60 and 120)
    let jag = (i % 2 === 0 ? 7 : -6) * (sin(a - 30) > -0.2 ? 1.3 : 0.4);
    let r = 64 + jag;
    shell1Outer.push([s1x + cos(a) * r * 1.08, s1y + sin(a) * r * 0.96]);
  }

  // Outer calcified bone wall visible around the bottom-left curve
  brush.noStroke();
  brush.wash("#e3ddd0", 245);
  drawClosedShape(shell1Outer, 0.08);
  brush.noWash();

  // Cool bluish-ivory inner membrane cavity
  let shell1Inner = [];
  for (let i = 0; i < n1; i++) {
    let a = (i / n1) * 360;
    let jag = (i % 2 === 0 ? 5 : -5);
