  let shell2Pts = [];
  let n2 = 26;
  for (let i = 0; i < n2; i++) {
    let a = (i / n2) * 360;
    let jag = (a > 20 && a < 175) ? (i % 2 === 0 ? 8 : -7) : (i % 2 === 0 ? 1.5 : -1.5);
    let r = 56 + jag;
