    [[s2x + 12, s2y + 48], [s2x + 4, s2y + 24], [s2x - 8, s2y + 10], [s2x - 6, s2y - 8]],
    [[s2x + 4, s2y + 24], [s2x + 22, s2y + 12], [s2x + 32, s2y + 4]],
