// ============================================================================
// 6. THE SPIRALLING FLOUR PLUME (Vortex Pencil Arcs + Beige/Ivory Spray Veils)
// ============================================================================
// Helper: 3D dust devil centerline as height z goes from 0 (bowl floor) to 1 (high near viewer)
function vortexSpine(z) {
  // Starts near the paddle's leading edge (530, 640) and spirals upward to (VX, VY) = (585, 555)
  let x = lerp(528, VX, pow(z, 0.75)) + sin(z * 260) * 18 * (1 - z * 0.5);
  let y = lerp(642, VY, pow(z, 0.75)) + cos(z * 260) * 14 * (1 - z * 0.5);
  return { x, y };
}

function drawFlourVortex() {
  // --------------------------------------------------------------------------
  // STAGE 6A: Deep Volumetric Flour Cloud Washes (Soft Beige, Wheat & Cool Grey-Bone)
  // --------------------------------------------------------------------------
  brush.noField();
  brush.noStroke();

  // Spiralling translucent cloud lobes rising from the bowl well
  for (let i = 0; i < 24; i++) {
    let u = i / 23;
    let spine = vortexSpine(u * 0.85);
    let ang = u * 520 + 40;
    let radDist = lerp(240, 28, pow(u, 0.65));
    let cx = spine.x + cos(ang) * radDist * 0.65;
    let cy = spine.y + sin(ang) * radDist * 0.65;
    let lobeR = lerp(125, 42, u);

    let col = u < 0.35
      ? random(["#8a8e91", "#a3a29c", "#b8b3a8"])
      : u < 0.7
      ? random(["#c9c3b6", "#d8d2c5", "#e3ddd0"])
      : random(["#ece7dc", "#f4f1e8", "#faf8f2"]);

    brush.fill(col, random(55, 95));
    brush.fillBleed(0.45, "out");
    brush.fillTexture(0.65, 0.2);
    drawClosedShape(makeCirclePts(cx, cy, lobeR, 24, lobeR * 0.35), 0.4);
  }
  brush.noFill();

  // First veil of soft beige & wheat spray along the outer spiral arms
  for (let arm = 0; arm < 4; arm++) {
    let armOffset = arm * 90;
    let pts = [];
    for (let s = 0; s <= 28; s++) {
      let u = s / 28;
      let sp = vortexSpine(u);
      let r = lerp(355, 22, pow(u, 0.72));
      let a = armOffset + u * 640;
      pts.push([sp.x + cos(a) * r, sp.y + sin(a) * r, sin(u * 180) * 1.2 + 0.3]);
    }
    brush.set("flour_veil", random(["#c7c0b2", "#d8d2c4", "#e6e0d3"]), random(1.1, 1.8));
    brush.spline(pts, 0.5);
  }

  // --------------------------------------------------------------------------
  // STAGE 6B: Outer & Mid Flow-Field Pencil Arcs (Serene at Edges -> Tightening Inward)
  // --------------------------------------------------------------------------
  brush.field("vortex_plume");
  brush.refreshField(0);

  // Outer sweeping flowLine pencil strokes (r = 160 to 410)
  for (let i = 0; i < 420; i++) {
    let u = random(0, 1);
    let r = lerp(150, 415, pow(u, 0.85));
    let a = random(360);
    let sp = vortexSpine(map(r, 415, 150, 0.1, 0.65));
    let x = sp.x + cos(a) * r;
    let y = sp.y + sin(a) * r;

    // Direction follows inward spiral tangent
    let dir = a + 112 + random(-10, 10);
    let len = map(r, 150, 415, 65, 155) * random(0.75, 1.25);

    let col = random([
      "#7d8388", "#999b99", "#b5b1a7", "#cbc5b9",
      "#dcd6ca", "#eae5da", "#f4f1e8"
    ]);
    let br = random(["2H", "HB", "cpencil"]);
    brush.set(br, col, random(0.45, 1.15));
    brush.flowLine(x, y, len, dir);
  }

  brush.noField();

  // Long continuous logarithmic-spiral pencil & graphite arcs tightening toward the core
  for (let i = 0; i < 260; i++) {
    let uStart = random(0.0, 0.55);
    let uEnd = constrain(uStart + random(0.22, 0.48), 0.15, 0.95);
    let startAng = random(360);
    let totalTwist = random(110, 240);

    let pts = [];
    let steps = 8;
    for (let k = 0; k <= steps; k++) {
      let f = k / steps;
      let u = lerp(uStart, uEnd, f);
      let sp = vortexSpine(u);
      // Radius tightens exponentially toward the vortex eye
      let r = lerp(370, 14, pow(u, 0.68)) * random(0.92, 1.08);
      let ang = startAng + f * totalTwist;
      let press = sin(f * 180) * 1.15 + 0.25;
      pts.push([sp.x + cos(ang) * r, sp.y + sin(ang) * r, press]);
    }

    let avgU = (uStart + uEnd) * 0.5;
    let col;
    if (avgU < 0.35) {
      col = random(["#7e848a", "#9c9e9d", "#bab5aa", "#d1cbc0", "#e2ddd2"]);
    } else if (avgU < 0.7) {
      col = random(["#969896", "#c4beb2", "#dad4c8", "#eae5da", "#f5f2ea"]);
    } else {
      col = random(["#d6d0c4", "#ebe6dc", "#f7f5ef", "#ffffff", "#636a70"]);
    }

    brush.set(random(["HB", "2B", "2H", "cpencil"]), col, random(0.45, 1.3));
    brush.spline(pts, 0.5);
  }

  // --------------------------------------------------------------------------
  // STAGE 6C: Mid-Altitude Beige & Ivory Spray Veils (Veiling the Pencil Arcs)
  // --------------------------------------------------------------------------
  for (let i = 0; i < 95; i++) {
    let u = random(0.1, 0.92);
    let sp = vortexSpine(u);
    let r = lerp(310, 18, pow(u, 0.75)) * random(0.6, 1.15);
    let a = random(360);
    let x1 = sp.x + cos(a) * r;
    let y1 = sp.y + sin(a) * r;
    let a2 = a + random(28, 65);
    let r2 = r * random(0.75, 0.95);
    let x2 = sp.x + cos(a2) * r2;
    let y2 = sp.y + sin(a2) * r2;

    let col = random(["#d5cfc1", "#e4dfd2", "#f0ece1", "#f8f6f0", "#c4bdb0"]);
    brush.set(random() < 0.65 ? "flour_veil" : "spray", col, random(0.9, 1.9));
    brush.line(x1, y1, x2, y2);
  }

  // Billowing sunlit ivory puffs along the upper spiral ridges
  brush.noStroke();
  for (let i = 0; i < 16; i++) {
    let u = map(i, 0, 15, 0.35, 0.96);
    let sp = vortexSpine(u);
    let a = i * 68 + 15;
    let r = lerp(175, 16, pow(u, 0.75));
    let px = sp.x + cos(a) * r;
    let py = sp.y + sin(a) * r;
    let rad = lerp(58, 20, u);

    brush.fill(random(["#ede8dd", "#f6f4ec", "#fcfbf7"]), random(65, 115));
    brush.fillBleed(0.35, "out");
    brush.fillTexture(0.55, 0.15);
    drawClosedShape(makeCirclePts(px, py, rad, 20, rad * 0.3), 0.4);
  }
  brush.noFill();

  // --------------------------------------------------------------------------
  // STAGE 6D: Chaotic Vortex Core (Tight High-Velocity Pencil Whirls & Eye Shadow)
  // --------------------------------------------------------------------------
  // Deep shadow inside the funnel eye (VX, VY) so the 3D dust-devil funnel pops
  brush.noStroke();
  brush.fill("#485058", 135);
  brush.fillBleed(0.3, "in");
  drawClosedShape(makeCirclePts(VX + 4, VY + 5, 42, 20, 10), 0.35);
  brush.fill("#2c333b", 125);
  drawClosedShape(makeCirclePts(VX + 2, VY + 3, 22, 16, 6), 0.35);
  brush.noFill();

  // Activate field again for dense inner core flowLines
  brush.field("vortex_plume");
  for (let i = 0; i < 240; i++) {
    let r = pow(random(), 1.5) * 165 + 6;
    let a = random(360);
    let x = VX + cos(a) * r;
    let y = VY + sin(a) * r;
    let dir = a + 122 + random(-18, 18);
    let len = map(r, 6, 170, 24, 85);

    let col = r < 32 && random() < 0.35
      ? random(["#3e464f", "#5c646d", "#7d8388"])
      : random(["#e2dcd0", "#f0ece2", "#f9f8f3", "#ffffff", "#cbc4b6"]);

    brush.set(random(["2B", "HB", "cpencil", "rotring"]), col, random(0.4, 1.25));
    brush.flowLine(x, y, len, dir);
  }
  brush.noField();

  // Chaotic multi-turn tight spiral eddies right around the eye (r = 5 to 125)
  for (let i = 0; i < 145; i++) {
    let rStart = random(28, 135);
    let rEnd = random(4, rStart * 0.65);
    let aStart = random(360);
    let turns = random(160, 340);

    // Slight eccentric wobble for chaotic core energy
    let ex = VX + random(-14, 14);
    let ey = VY + random(-14, 14);

    let pts = [];
    let steps = 9;
    for (let k = 0; k <= steps; k++) {
      let f = k / steps;
      let r = lerp(rStart, rEnd, pow(f, 0.85)) + (noise(i, k * 0.4) - 0.5) * 10;
      let a = aStart + f * turns;
      pts.push([ex + cos(a) * r, ey + sin(a) * r, sin(f * 180) * 1.3 + 0.2]);
    }

    let col = random([
      "#ffffff", "#fcfbf7", "#f3f0e6", "#e3ddd0",
      "#c5bfb2", "#555d66", "#ffffff"
    ]);
    brush.set(random(["HB", "2B", "cpencil", "pen"]), col, random(0.45, 1.35));
    brush.spline(pts, 0.55);
  }

  // Final luminous ivory spray veil over the chaotic core
  for (let i = 0; i < 40; i++) {
    let a = random(360);
    let r = random(8, 110);
    let x = VX + cos(a) * r;
    let y = VY + sin(a) * r;
    brush.set("spray", random(["#f7f5ef", "#ffffff", "#eae5da"]), random(0.8, 1.6));
    brush.line(x, y, x + cos(a + 110) * random(18, 45), y + sin(a + 110) * random(18, 45));
  }
}

