function drawEscapingParticles() {
  brush.noField();

  // 1. Tangential streams of stippled flour specks flung outward from the vortex arms
  for (let stream = 0; stream < 28; stream++) {
    let baseAng = (stream / 28) * 360 + random(-8, 8);
    let rStart = random(95, 290);
    let rEnd = rStart + random(110, 290);
    let sp = vortexSpine(random(0.25, 0.9));

    let steps = int(random(14, 28));
    for (let k = 0; k < steps; k++) {
      let f = k / steps;
      let r = lerp(rStart, rEnd, f) + random(-12, 12);
      // Particles drift outward along a loosening spiral
      let a = baseAng + f * random(35, 75) + random(-4, 4);
      let px = sp.x + cos(a) * r;
      let py = sp.y + sin(a) * r;

      let col = random(["#ffffff", "#f7f5ef", "#eae5da", "#d8d2c5", "#c2bcb0"]);
      if (random() < 0.45) {
        brush.set("flour_speck", col, random(0.6, 1.5));
        brush.line(px, py, px + cos(a + 90) * random(4, 14), py + sin(a + 90) * random(4, 14));
      } else {
        brush.set(random(["rotring", "pen", "cpencil"]), col, random(0.55, 1.4));
        brush.circle(px, py, random(0.6, 2.2), 0.25);
      }
    }
  }

  // 2. Thousands of fine stippled specks drifting across the steel bowl wall, rim & slate
  for (let i = 0; i < 620; i++) {
    // Concentrate density around the plume and taper off serenely toward the canvas edges
    let u = pow(random(), 0.75);
    let r = lerp(25, 580, u);
    let a = random(360);
    let cx = lerp(VX, BCX, u * 0.5);
    let cy = lerp(VY, BCY, u * 0.5);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r;
    if (x < 15 || x > 1185 || y < 15 || y > 1185) continue;

    let col = random(["#ffffff", "#f8f6f0", "#ebe6dc", "#d6d0c4", "#b8b3a8"]);
    if (random() < 0.35) {
      brush.set("spray", col, random(0.45, 1.15));
      brush.line(x, y, x + random(-6, 6), y + random(-6, 6));
    } else {
      brush.set(random(["pen", "rotring", "2H"]), col, random(0.45, 1.15));
      let len = random(0.8, 3.5);
      let tang = a + 100 + random(-20, 20);
      brush.line(x, y, x + cos(tang) * len, y + sin(tang) * len);
    }
  }

  // 3. Sharp foreground airborne flour clumps (caught high in the air close to the viewer)
  for (let i = 0; i < 55; i++) {
    let r = pow(random(), 0.9) * 340 + 12;
    let a = random(360);
    let x = VX + cos(a) * r;
    let y = VY + sin(a) * r;
    let sz = map(r, 12, 350, 4.8, 1.8) * random(0.7, 1.3);

    // Tiny irregular flour tuft
    let pts = makeCirclePts(x, y, sz, 8, sz * 0.6);
    brush.noStroke();
    brush.wash(random(["#ffffff", "#faf8f2", "#eeeae0"]), 235);
    drawClosedShape(pts, 0.3);
    brush.noWash();

    // Subtle underside shadow on larger airborne clumps for 3D hyperrealism
    if (sz > 2.8) {
      brush.set("2H", "#8c9094", 0.55);
      brush.arc(x + 1, y + 1, sz * 0.85, 20, 160);
    }
    brush.set("pen", "#ffffff", 0.75);
    brush.circle(x - sz * 0.2, y - sz * 0.2, sz * 0.45, 0.2);
  }

  // 4. Delicate dusting of settled flour across the steel rim, eggshells, and butter wrapper
  const settledZones = [
    { x: 215, y: 890, r: 95, count: 28 }, // Over the cracked eggshells
    { x: 825, y: 310, r: 90, count: 26 }, // Over the butter wrapper corner on the rim
    { x: 420, y: 225, r: 85, count: 22 }, // Upper-left steel rim
    { x: 760, y: 980, r: 95, count: 24 }  // Lower-right steel rim
  ];
  for (let sz of settledZones) {
    for (let k = 0; k < sz.count; k++) {
      let ang = random(360);
      let rad = random(sz.r);
      let px = sz.x + cos(ang) * rad;
      let py = sz.y + sin(ang) * rad;
      brush.set("flour_speck", random(["#f7f5ef", "#ffffff", "#e3ddd0"]), random(0.5, 1.2));
      brush.line(px, py, px + random(-8, 8), py + random(-8, 8));
    }
  }
}

// Chromed Steelpan — Carnival Metal as a Portal
// Hyperrealistic p5.brush rendering (1200x1200 WEBGL)

const DEG2RAD = Math.PI / 180;

// 3D Tilted Concave Steelpan Parameters
const PAN_CX = 635;
const PAN_CY = 590;
const R_INNER = 585;
const R_RIM_CREST = 638;
const R_RIM_OUTER = 674;
const BOWL_DEPTH = 195;
const PITCH_COS = Math.cos(38 * DEG2RAD);
const PITCH_SIN = Math.sin(38 * DEG2RAD);
const ROT_COS = Math.cos(-20 * DEG2RAD);
const ROT_SIN = Math.sin(-20 * DEG2RAD);

let notes = [];

// Palette: Magenta-to-indigo, ultramarine, deep teal, burnished bronze, molten gold, muted earth tones
const PAL = {
  voidIndigo: "#070612",
  deepIndigo: "#111229",
  ultramarine: "#1d3178",
  brightUltra: "#3252a8",
  abyssalTeal: "#09212c",
  deepTeal: "#12495c",
  midTeal: "#1f7a8c",
  electricTeal: "#43b5bd",
  paleTeal: "#8ee3e8",
  royalViolet: "#381452",
  electricViolet: "#6c1f87",
  lavenderGlow: "#a474eb",
  carnivalMagenta: "#a8227e",
  hotMagenta: "#db4ca8",
  darkEarth: "#1f1312",
  rawUmber: "#3d261c",
  mutedClay: "#694535",
  burnishedBronze: "#7d4920",
  copperGold: "#b06825",
  moltenGold: "#e09228",
  brightGold: "#f7c244",
  incandescent: "#ffea9f",
  chromeSilver: "#e3eef2",
  pureWhite: "#ffffff",
  woodShadow: "#2b1911",
  woodMid: "#7d5436",
  woodWarm: "#ad7e52",
  woodLight: "#debda0",
  rubberShadow: "#361816",
  rubberDark: "#692e27",
  rubberMid: "#9c4a3b",
  rubberWarm: "#bf6952",
  rubberScuff: "#d9a796",
  rubberDust: "#edd3c7"
};

function bowlZ(r) {
  if (r <= R_INNER) {
    let nr = Math.max(0, r / R_INNER);
    return -BOWL_DEPTH * Math.pow(1 - Math.pow(nr, 1.85), 0.92);
  } else if (r <= 620) {
    let t = (r - R_INNER) / (620 - R_INNER);
    return 36 * t;
  } else if (r <= R_RIM_OUTER) {
    let t = (r - 620) / (R_RIM_OUTER - 620);
    return 36 + 13 * Math.sin(t * Math.PI) - 24 * t * t;
  } else {
    return 25 - 1.85 * (r - R_RIM_OUTER);
  }
}

function panPoint(r, thetaDeg, extraZ = 0) {
  let rad = thetaDeg * DEG2RAD;
  let lx = r * Math.cos(rad);
  let ly = r * Math.sin(rad);
  let z = bowlZ(r) + extraZ;

  let tx = lx;
  let ty = ly * PITCH_COS - z * PITCH_SIN;

  let x = PAN_CX + tx * ROT_COS - ty * ROT_SIN;
  let y = PAN_CY + tx * ROT_SIN + ty * ROT_COS;
  return [x, y, z];
}

// Point inside a specific hammered note-dimple
// rho: 0..1 (center to groove), alphaDeg: 0..360 (local angle around dimple)
function notePoint(note, rho, alphaDeg, zMult = 1.0) {
  let rad = alphaDeg * DEG2RAD;
  let u = rho * Math.cos(rad);
  let v = rho * Math.sin(rad) * (1 + note.taper * u);

  let r = note.r0 + u * note.dr;
  let theta = note.theta0 + v * note.da;

  // Raised blister dome with recessed groove at rho = 1
  let dome = 0;
  if (rho <= 1.0) {
    dome = note.domeH * (1 - rho * rho) - 2.5 * Math.pow(rho, 6);
  } else {
    dome = -2.5 * Math.exp(-(rho - 1) * 4);
  }
  return panPoint(r, theta, dome * zMult);
}

function buildNotesList() {
  notes = [];
  // 1. Outer Ring: 12 large oval/teardrop notes
  for (let i = 0; i < 12; i++) {
    let th = i * 30 + 12 + random(-0.8, 0.8);
    notes.push({
      ring: 0,
      idx: i,
      r0: 462 + random(-3, 3),
      theta0: th,
      dr: 98 + random(-3, 3),
      da: 11.8 + random(-0.3, 0.3),
      taper: 0.16,
      domeH: 19,
      hueShift: random(-0.15, 0.15),
      tiltShift: random(-12, 12)
    });
  }
  // 2. Middle Ring: 12 medium oval notes (staggered)
  for (let i = 0; i < 12; i++) {
    let th = i * 30 + 27 + random(-0.8, 0.8);
    notes.push({
      ring: 1,
      idx: i,
      r0: 282 + random(-3, 3),
      theta0: th,
      dr: 62 + random(-2, 2),
      da: 12.2 + random(-0.3, 0.3),
      taper: 0.12,
      domeH: 15,
      hueShift: random(-0.15, 0.15),
      tiltShift: random(-12, 12)
    });
  }
  // 3. Inner Ring: 6 round-oval high notes
  for (let i = 0; i < 6; i++) {
    let th = i * 60 + 8 + random(-1, 1);
    notes.push({
      ring: 2,
      idx: i,
      r0: 146 + random(-2, 2),
      theta0: th,
      dr: 43 + random(-2, 2),
      da: 20.5 + random(-0.5, 0.5),
      taper: 0.06,
      domeH: 12,
      hueShift: random(-0.15, 0.15),
      tiltShift: random(-12, 12)
    });
  }
  // 4. Center Medallion Note
  notes.push({
    ring: 3,
    idx: 0,
    r0: 0,
    theta0: 0,
    dr: 66,
    da: 180,
    taper: 0,
    domeH: 14,
    isCenter: true,
    hueShift: 0,
    tiltShift: 0
  });
}

// Helper for center note since polar around r0=0 is direct
function getDimplePt(note, rho, alphaDeg, zMult = 1.0) {
  if (note.isCenter) {
    let r = rho * note.dr;
    let dome = note.domeH * (1 - rho * rho) - 2.2 * Math.pow(rho, 6);
    return panPoint(r, alphaDeg, dome * zMult);
  }
  return notePoint(note, rho, alphaDeg, zMult);
}

function drawShapePts(pts, curvature = 0.3) {
  if (pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4219);
  noiseSeed(4219);

  // Register custom hyperrealistic airbrush, velvet shader, and metallic pen tips
  brush.add("airbrush", {
    type: "spray",
    weight: 16,
    scatter: 3.4,
    opacity: 20,
    spacing: 0.35,
    pressure: [0.3, 1.0, 0.3]
  });

  brush.add("fineAir", {
    type: "spray",
    weight: 7,
    scatter: 1.45,
    opacity: 30,
    spacing: 0.25,
    pressure: [0.25, 1.0, 0.25]
  });

  brush.add("velvetShader", {
    type: "default",
    weight: 8.5,
    scatter: 0.3,
    sharpness: 0.14,
    grain: 0.38,
    opacity: 40,
    spacing: 0.16,
    pressure: [0.2, 1.0, 0.2],
    noise: 0.2
  });

  brush.add("chromePen", {
    type: "default",
    weight: 1.0,
    scatter: 0.02,
    sharpness: 0.9,
    grain: 0.8,
    opacity: 185,
    spacing: 0.1,
    pressure: [0.3, 1.0, 0.3],
    noise: 0.15
  });

  buildNotesList();
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.voidIndigo);

  // 1. Atmospheric Background & Exterior Barrel Skirt
  drawExteriorAndSkirt();

  // 2. Concave Steelpan Bowl Base & Global Chrome Sky Reflections
  drawBowlFoundation();

  // 3. Interstitial Hammer-Peen Facets & Radial Seams
  drawInterstitialMetalwork();

  // 4. All 31 Hammered Note-Dimples (Batched Washes + Fills + Iridescent Gradients + Seams)
  drawAllNoteDimples();

  // 5. Steep Inner Skirt Wall & Rolled Chrome Rim
  drawRolledChromeRim();

  // 6. Warped Chrome Reflections of the Drumsticks on the Bowl & Rim
  drawDrumstickReflections();

  // 7. Two Drumsticks with Worn Muted-Earth Rubber Tips Resting Across Rim
  drawDrumsticks();

  // 8. Tiny Bright Starburst Highlights on Rims & Specular Ridges
  drawStarburstHighlights();

  noLoop();
}

// =========================================================================
// STAGE 1: ATMOSPHERIC GROUND & EXTERIOR STEEL SKIRT
// =========================================================================
function drawExteriorAndSkirt() {
  brush.set("HB", PAL.voidIndigo, 1);
  brush.noStroke();

  // Muted earth & deep indigo ambient corner washes
  brush.wash(PAL.darkEarth, 150);
  drawShapePts([[0, 0], [1200, 0], [1200, 420], [0, 950]], 0);

  brush.wash(PAL.deepIndigo, 140);
  drawShapePts([[0, 450], [1200, 180], [1200, 1200], [0, 1200]], 0);

  // Exterior chrome barrel skirt below/outside the rim (visible on bottom-left, bottom-right, top-left)
  let skirtBands = [
    { a1: 20, a2: 195, col: PAL.voidIndigo, op: 220 },
    { a1: 35, a2: 85, col: PAL.rawUmber, op: 160 },
    { a1: 80, a2: 145, col: PAL.deepTeal, op: 150 },
    { a1: 135, a2: 185, col: PAL.royalViolet, op: 140 },
    { a1: 55, a2: 110, col: PAL.burnishedBronze, op: 130 }
  ];

  for (let b of skirtBands) {
    let pts = [];
    for (let a = b.a1; a <= b.a2; a += 6) {
      pts.push(panPoint(R_RIM_OUTER - 2, a));
    }
    for (let a = b.a2; a >= b.a1; a -= 6) {
      pts.push(panPoint(R_RIM_OUTER + 145, a));
    }
    brush.wash(b.col, b.op);
    drawShapePts(pts, 0.2);
  }

  // Vertical chrome reflections along exterior skirt
  for (let a = 15; a <= 195; a += 2.2) {
    let p1 = panPoint(R_RIM_OUTER, a);
    let p2 = panPoint(R_RIM_OUTER + 60, a);
    let p3 = panPoint(R_RIM_OUTER + 130, a);

    let n = noise(a * 0.08);
    let col = PAL.deepIndigo;
    let w = 1.4;
    if (n > 0.68) {
      col = PAL.moltenGold;
      w = 1.8;
    } else if (n > 0.54) {
      col = PAL.electricViolet;
      w = 1.6;
    } else if (n > 0.42) {
      col = PAL.midTeal;
      w = 1.5;
    } else if (n < 0.25) {
      col = PAL.rawUmber;
      w = 2.0;
    }
    brush.set("velvetShader", col, w);
    brush.spline([p1, p2, p3], 0.3);
  }

  // Soft airbrush atmospheric glow around upper-left rim
  for (let a = 195; a <= 355; a += 5) {
    let p1 = panPoint(R_RIM_OUTER + 10, a);
    let p2 = panPoint(R_RIM_OUTER + 95, a + 4);
    let p3 = panPoint(R_RIM_OUTER + 180, a + 8);
    let col = (a < 270) ? PAL.rawUmber : PAL.deepTeal;
    brush.set("airbrush", col, 2.2);
    brush.spline([p1, p2, p3], 0.4);
  }
}

// =========================================================================
// STAGE 2: CONCAVE STEELPAN BOWL FOUNDATION & GLOBAL SKY REFLECTIONS
// =========================================================================
function drawBowlFoundation() {
  brush.set("HB", PAL.voidIndigo, 1);
  brush.noStroke();

  // Base dark metallic bowl disk
  let bowlOutline = [];
  for (let a = 0; a < 360; a += 5) {
    bowlOutline.push(panPoint(R_RIM_CREST, a));
  }
  brush.wash(PAL.voidIndigo, 245);
  drawShapePts(bowlOutline, 0.3);

  // Macro sky reflection zones inside the concave bowl using fast washes
  // In a concave mirror, reflections sweep in vast curved crescents
  let macroZones = [
    // Deep teal & ultramarine sky across lower-right and upper-left quadrants
    { r1: 40, r2: 585, a1: -45, a2: 145, col: PAL.abyssalTeal, op: 190 },
    { r1: 90, r2: 575, a1: -20, a2: 115, col: PAL.deepTeal, op: 165 },
    { r1: 160, r2: 540, a1: 5, a2: 85, col: PAL.midTeal, op: 120 },
    // Ultramarine & electric violet cosmic band sweeping diagonally
    { r1: 20, r2: 585, a1: 125, a2: 265, col: PAL.deepIndigo, op: 200 },
    { r1: 70, r2: 560, a1: 140, a2: 245, col: PAL.ultramarine, op: 150 },
    { r1: 110, r2: 530, a1: 165, a2: 230, col: PAL.electricViolet, op: 140 },
    { r1: 160, r2: 490, a1: 180, a2: 220, col: PAL.carnivalMagenta, op: 110 },
    // Muted earth, burnished bronze & molten gold reflection across upper-right / center-top
    { r1: 30, r2: 585, a1: 235, a2: 345, col: PAL.rawUmber, op: 185 },
    { r1: 60, r2: 550, a1: 250, a2: 330, col: PAL.burnishedBronze, op: 165 },
    { r1: 100, r2: 500, a1: 265, a2: 318, col: PAL.copperGold, op: 145 },
    { r1: 140, r2: 430, a1: 278, a2: 308, col: PAL.moltenGold, op: 130 }
  ];

  for (let z of macroZones) {
    let pts = [];
    for (let a = z.a1; a <= z.a2; a += 6) pts.push(panPoint(z.r2, a));
    for (let a = z.a2; a >= z.a1; a -= 6) pts.push(panPoint(z.r1, a));
    brush.wash(z.col, z.op);
    drawShapePts(pts, 0.35);
  }

  // Sweeping airbrushed & velvetShader iridescent ribbons across the bowl matrix
  for (let r = 35; r <= 575; r += 14) {
    let stepA = 36;
    for (let a0 = 0; a0 < 360; a0 += stepA) {
      let aMid = a0 + stepA * 0.5;
      let aEnd = a0 + stepA + 6;
      let p1 = panPoint(r, a0);
      let p2 = panPoint(r + random(-4, 4), aMid);
      let p3 = panPoint(r, aEnd);

      // Determine iridescent color by angle + radius wave
      let wave = Math.sin((a0 * 1.5 + r * 0.35) * DEG2RAD);
      let col = PAL.deepTeal;
      let brName = "velvetShader";
      let w = 1.6;

      if (a0 >= 250 && a0 <= 330) {
        col = wave > 0.3 ? PAL.brightGold : (wave > -0.2 ? PAL.moltenGold : PAL.burnishedBronze);
        w = 1.9;
      } else if (a0 >= 155 && a0 < 250) {
        col = wave > 0.35 ? PAL.hotMagenta : (wave > -0.15 ? PAL.electricViolet : PAL.ultramarine);
        w = 1.7;
      } else if (a0 >= 330 || a0 < 65) {
        col = wave > 0.4 ? PAL.electricTeal : (wave > -0.1 ? PAL.midTeal : PAL.rawUmber);
        w = 1.6;
      } else {
        col = wave > 0.3 ? PAL.lavenderGlow : (wave > -0.2 ? PAL.deepTeal : PAL.deepIndigo);
        w = 1.5;
      }

      brush.set(brName, col, w);
      brush.spline([p1, p2, p3], 0.45);
    }
  }

  // Broad airbrush glow clouds to blend the macro metal transitions
  let glowClouds = [
    { r: 340, a: 295, spanA: 55, col: PAL.moltenGold, w: 3.2 },
    { r: 220, a: 285, spanA: 65, col: PAL.brightGold, w: 2.8 },
    { r: 380, a: 200, spanA: 60, col: PAL.carnivalMagenta, w: 3.0 },
    { r: 250, a: 190, spanA: 70, col: PAL.electricViolet, w: 2.8 },
    { r: 390, a: 45, spanA: 65, col: PAL.electricTeal, w: 2.8 },
    { r: 180, a: 75, spanA: 80, col: PAL.midTeal, w: 2.5 },
    { r: 420, a: 135, spanA: 50, col: PAL.mutedClay, w: 2.6 }
  ];

  for (let g of glowClouds) {
    for (let dr = -45; dr <= 45; dr += 18) {
      let p1 = panPoint(g.r + dr, g.a - g.spanA * 0.5);
      let p2 = panPoint(g.r + dr * 0.5, g.a);
      let p3 = panPoint(g.r + dr, g.a + g.spanA * 0.5);
      brush.set("airbrush", g.col, g.w);
      brush.spline([p1, p2, p3], 0.5);
    }
  }
}

// =========================================================================
// STAGE 3: INTERSTITIAL HAMMER-PEENING, LATHE RINGS & RADIAL SEAMS
// =========================================================================
function drawInterstitialMetalwork() {
  // Fine concentric spinning/lathe marks across the bowl
  for (let r = 55; r <= 575; r += 11) {
    for (let a = 0; a < 360; a += 45) {
      if (random() < 0.25) continue;
      let p1 = panPoint(r, a);
      let p2 = panPoint(r, a + 20);
      let p3 = panPoint(r, a + 40);
      let col = random([PAL.voidIndigo, PAL.deepTeal, PAL.royalViolet, PAL.burnishedBronze, PAL.lavenderGlow]);
      brush.set("chromePen", col, random(0.45, 0.85));
      brush.spline([p1, p2, p3], 0.4);
    }
  }

  // Hundreds of small hammered peen facets in the interstitial metal between note rings
  let interstitialRadii = [88, 102, 195, 212, 355, 372, 558, 572];
  for (let rBase of interstitialRadii) {
    let count = Math.floor(rBase * 0.32);
    for (let i = 0; i < count; i++) {
      let a = (i / count) * 360 + random(-2, 2);
      let r = rBase + random(-8, 8);
      let spanA = (14 / Math.max(80, r)) * 57.3;

      let p1 = panPoint(r - 4, a - spanA);
      let p2 = panPoint(r + 3, a);
      let p3 = panPoint(r - 4, a + spanA);

      // Dark hammer crescent + bright edge catch
      let isWarm = (a > 240 && a < 340) || random() < 0.3;
      let hiCol = isWarm ? PAL.brightGold : (a > 150 && a <= 240 ? PAL.lavenderGlow : PAL.paleTeal);
      brush.set("chromePen", PAL.voidIndigo, 0.75);
      brush.spline([p1, p2, p3], 0.5);

      let q1 = panPoint(r + 4, a - spanA * 0.8);
      let q2 = panPoint(r - 2, a);
      let q3 = panPoint(r + 4, a + spanA * 0.8);
      brush.set("chromePen", hiCol, 0.65);
      brush.spline([q1, q2, q3], 0.5);
    }
  }

  // Radial tuning/grooving seams connecting outer notes to the inner skirt wall
  for (let i = 0; i < 12; i++) {
    let note = notes[i];
    let seamAngles = [note.theta0 - note.da * 0.72, note.theta0 + note.da * 0.72];
    for (let sa of seamAngles) {
      let p1 = panPoint(note.r0 + note.dr * 0.82, sa);
      let p2 = panPoint(572, sa);
      let p3 = panPoint(602, sa);

      brush.set("chromePen", PAL.voidIndigo, 1.3);
      brush.spline([p1, p2, p3], 0.25);

      let p1Hi = panPoint(note.r0 + note.dr * 0.82, sa + 0.45);
      let p2Hi = panPoint(572, sa + 0.45);
      let p3Hi = panPoint(602, sa + 0.45);
      brush.set("chromePen", PAL.brightGold, 0.8);
      brush.spline([p1Hi, p2Hi, p3Hi], 0.25);
    }
  }
}

// =========================================================================
// STAGE 4: THE 31 HAMMERED NOTE-DIMPLES ("EACH ITS OWN GLOWING WORLD")
// =========================================================================
function drawAllNoteDimples() {
  brush.set("HB", PAL.voidIndigo, 1);
  brush.noStroke();

  // STEP 4A: Recessed dark indigo/umber groove halo around every dimple (fast wash)
  brush.wash(PAL.voidIndigo, 235);
  for (let note of notes) {
    let pts = [];
    for (let a = 0; a < 360; a += 15) {
      pts.push(getDimplePt(note, 1.04, a, 0.5));
    }
    drawShapePts(pts, 0.35);
  }

  // STEP 4B: BATCHED WATERCOLOR FILLS (grouped by color for high performance & lush bleed)
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.42, 0.25);

  // Batch 1: Deep Teal sky crescent in upper slope of each dimple
  brush.fill(PAL.deepTeal, 125);
  for (let note of notes) {
    let pts = [];
    let rot = note.tiltShift;
    for (let a = 155 + rot; a <= 385 + rot; a += 18) {
      pts.push(getDimplePt(note, 0.94, a));
    }
    for (let a = 385 + rot; a >= 155 + rot; a -= 22) {
      pts.push(getDimplePt(note, 0.25, a));
    }
    drawShapePts(pts, 0.35);
  }

  // Batch 2: Electric Violet & Ultramarine horizon band across middle of each dimple
  brush.fill(PAL.electricViolet, 115);
  for (let note of notes) {
    let pts = [];
    let rot = note.tiltShift;
    for (let a = 175 + rot; a <= 365 + rot; a += 20) {
      pts.push(getDimplePt(note, 0.62, a));
    }
    for (let a = -15 + rot; a <= 165 + rot; a += 20) {
      pts.push(getDimplePt(note, 0.88, a));
    }
    drawShapePts(pts, 0.4);
  }

  // Batch 3: Carnival Magenta glowing transition band
  brush.fill(PAL.carnivalMagenta, 105);
  for (let note of notes) {
    let pts = [];
    let rot = note.tiltShift;
    for (let a = -10 + rot; a <= 190 + rot; a += 20) {
      pts.push(getDimplePt(note, 0.76, a));
    }
    for (let a = 190 + rot; a >= -10 + rot; a -= 25) {
      pts.push(getDimplePt(note, 0.18, a + 180));
    }
    drawShapePts(pts, 0.4);
  }

  // Batch 4: Molten Gold & Burnished Bronze glowing lower-central pool
  brush.fill(PAL.moltenGold, 135);
  for (let note of notes) {
    let pts = [];
    let rot = note.tiltShift;
    for (let a = 15 + rot; a <= 165 + rot; a += 18) {
      pts.push(getDimplePt(note, 0.82, a));
    }
    for (let a = 165 + rot; a >= 15 + rot; a -= 22) {
      pts.push(getDimplePt(note, 0.12, a));
    }
    drawShapePts(pts, 0.4);
  }

  // Batch 5: Incandescent Gold core inside every note world
  brush.fill(PAL.brightGold, 145);
  for (let note of notes) {
    let pts = [];
    let rot = note.tiltShift;
    for (let a = 35 + rot; a <= 145 + rot; a += 20) {
      pts.push(getDimplePt(note, 0.62, a));
    }
    for (let a = 145 + rot; a >= 35 + rot; a -= 25) {
      pts.push(getDimplePt(note, 0.22, a));
    }
    drawShapePts(pts, 0.4);
  }

  brush.noFill();
  brush.noWash();

  // STEP 4C: Detailed Airbrushed Gradients, Chrome Horizon Ribbons, Hammer Facets & Grooved Seams
  for (let note of notes) {
    renderSingleNoteWorld(note);
  }
}

function renderSingleNoteWorld(note) {
  let rot = note.tiltShift;
  let scaleW = note.ring === 0 ? 1.0 : (note.ring === 1 ? 0.78 : 0.62);

  // 1. Internal curved horizon ribbons (velvetShader + fineAir) creating mini sky-to-gold dome reflections
  // Upper sky arcs: Abyssal Teal -> Electric Teal -> Ultramarine
  let upperArcs = [
    { rho: 0.86, a1: 185, a2: 355, col: PAL.abyssalTeal, br: "velvetShader", w: 1.8 * scaleW },
    { rho: 0.74, a1: 195, a2: 345, col: PAL.midTeal, br: "velvetShader", w: 1.7 * scaleW },
    { rho: 0.62, a1: 205, a2: 335, col: PAL.electricTeal, br: "fineAir", w: 1.5 * scaleW },
    { rho: 0.48, a1: 190, a2: 350, col: PAL.ultramarine, br: "velvetShader", w: 1.6 * scaleW }
  ];

  for (let arc of upperArcs) {
    let pts = [];
    for (let a = arc.a1 + rot; a <= arc.a2 + rot; a += 22) {
      pts.push(getDimplePt(note, arc.rho, a));
    }
    brush.set(arc.br, arc.col, arc.w);
    brush.spline(pts, 0.45);
  }

  // Horizon S-curve across center of the dimple: Electric Violet -> Magenta -> Dark Earth Chrome Snap
  let midBands = [
    { yOff: -0.22, col: PAL.electricViolet, br: "velvetShader", w: 1.9 * scaleW },
    { yOff: -0.06, col: PAL.hotMagenta, br: "fineAir", w: 1.6 * scaleW },
    { yOff: 0.08, col: PAL.rawUmber, br: "velvetShader", w: 1.5 * scaleW },
    { yOff: 0.22, col: PAL.burnishedBronze, br: "velvetShader", w: 1.8 * scaleW }
  ];

  for (let mb of midBands) {
    let pts = [];
    for (let x = -0.82; x <= 0.82; x += 0.26) {
      let y = mb.yOff + 0.14 * Math.sin(x * Math.PI * 1.2);
      let rho = Math.min(0.92, Math.hypot(x, y));
      let a = Math.atan2(y, x) / DEG2RAD + rot;
      pts.push(getDimplePt(note, rho, a));
    }
    brush.set(mb.br, mb.col, mb.w);
    brush.spline(pts, 0.45);
  }

  // Lower glowing crescent: Molten Gold -> Bright Gold -> Incandescent Core -> Dark Rim Bounce
  let lowerArcs = [
    { rho: 0.42, a1: 25, a2: 155, col: PAL.moltenGold, br: "velvetShader", w: 2.0 * scaleW },
    { rho: 0.56, a1: 30, a2: 150, col: PAL.brightGold, br: "fineAir", w: 1.8 * scaleW },
    { rho: 0.65, a1: 48, a2: 132, col: PAL.incandescent, br: "velvetShader", w: 1.5 * scaleW },
    { rho: 0.84, a1: 15, a2: 165, col: PAL.darkEarth, br: "velvetShader", w: 1.4 * scaleW },
    { rho: 0.93, a1: 30, a2: 150, col: PAL.lavenderGlow, br: "chromePen", w: 0.95 * scaleW }
  ];

  for (let arc of lowerArcs) {
    let pts = [];
    for (let a = arc.a1 + rot; a <= arc.a2 + rot; a += 18) {
      pts.push(getDimplePt(note, arc.rho, a));
    }
    brush.set(arc.br, arc.col, arc.w);
    brush.spline(pts, 0.45);
  }

  // 2. Micro Hammer-Peen Facets inside the Note Dome (gives authentic hand-tuned steel sheen)
  let facetCount = note.ring === 0 ? 22 : (note.ring === 1 ? 14 : 9);
  for (let f = 0; f < facetCount; f++) {
    let rho = random(0.18, 0.84);
    let a = random(0, 360);
    let span = random(18, 32);
    let p1 = getDimplePt(note, rho, a - span);
    let p2 = getDimplePt(note, rho + random(-0.06, 0.06), a);
    let p3 = getDimplePt(note, rho, a + span);

    let normA = ((a - rot) % 360 + 360) % 360;
    let fCol = PAL.paleTeal;
    if (normA > 20 && normA < 160) {
      fCol = random([PAL.brightGold, PAL.incandescent, PAL.copperGold]);
    } else if (normA >= 160 && normA < 230) {
      fCol = random([PAL.hotMagenta, PAL.lavenderGlow, PAL.electricViolet]);
    } else {
      fCol = random([PAL.electricTeal, PAL.paleTeal, PAL.brightUltra]);
    }
    brush.set("chromePen", fCol, random(0.45, 0.85) * scaleW);
    brush.spline([p1, p2, p3], 0.45);
  }

  // 3. Primary Liquid-Chrome Specular Hot-Spots inside each Dimple
  // Upper-left cool chrome sky specular crescent
  let specUpper = [];
  for (let a = 235 + rot; a <= 295 + rot; a += 15) {
    specUpper.push(getDimplePt(note, 0.58, a));
  }
  brush.set("velvetShader", PAL.chromeSilver, 1.2 * scaleW);
  brush.spline(specUpper, 0.45);
  brush.set("chromePen", PAL.pureWhite, 0.95 * scaleW);
  brush.spline(specUpper, 0.45);

  // Lower-right molten gold + pure white focal hot-spot
  let specLower = [];
  for (let a = 62 + rot; a <= 112 + rot; a += 14) {
    specLower.push(getDimplePt(note, 0.58, a));
  }
  brush.set("fineAir", PAL.incandescent, 1.5 * scaleW);
  brush.spline(specLower, 0.45);
  brush.set("chromePen", PAL.pureWhite, 1.15 * scaleW);
  brush.spline(specLower, 0.45);

  // 4. Fine Metallic Pen Seams & Chisel-Punch Grooving Marks around Note Perimeter
  // Dark etched groove seam (full loop in two halves)
  for (let half = 0; half < 2; half++) {
    let pts = [];
    let startA = half * 180;
    for (let a = startA; a <= startA + 185; a += 10) {
      pts.push(getDimplePt(note, 1.0, a));
    }
    brush.set("rotring", PAL.voidIndigo, 1.35 * scaleW);
    brush.spline(pts, 0.35);
  }

  // Bright metallic pen rim bevel catching light on opposite arcs of the groove
  let bevelArc1 = [];
  for (let a = -35; a <= 135; a += 12) {
    bevelArc1.push(getDimplePt(note, 1.02, a));
  }
  brush.set("chromePen", PAL.incandescent, 0.9 * scaleW);
  brush.spline(bevelArc1, 0.35);

  let bevelArc2 = [];
  for (let a = 155; a <= 310; a += 12) {
    bevelArc2.push(getDimplePt(note, 0.98, a));
  }
  brush.set("chromePen", PAL.paleTeal, 0.8 * scaleW);
  brush.spline(bevelArc2, 0.35);

  // Authentic steelpan chisel-punch dot/tick chain along the entire note seam
  let punchStep = note.ring === 0 ? 5.5 : (note.ring === 1 ? 7.5 : 10);
  for (let a = 0; a < 360; a += punchStep) {
    let pIn = getDimplePt(note, 0.975, a);
    let pOut = getDimplePt(note, 1.025, a + 1.2);
    let col = (a % (punchStep * 2) < punchStep) ? PAL.voidIndigo : ((a > 180) ? PAL.lavenderGlow : PAL.brightGold);
    brush.set("chromePen", col, 0.7 * scaleW);
    brush.line(pIn[0], pIn[1], pOut[0], pOut[1]);
  }
}

// =========================================================================
// STAGE 5: STEEP INNER SKIRT WALL & ROLLED CHROME RIM
// =========================================================================
function drawRolledChromeRim() {
  // 1. Steep inner skirt wall (r = 582..622) reflecting stretched vertical/circumferential bands
  let wallRings = [
    { r: 586, col: PAL.voidIndigo, br: "velvetShader", w: 2.2 },
    { r: 594, col: PAL.deepTeal, br: "velvetShader", w: 2.0 },
    { r: 602, col: PAL.electricViolet, br: "velvetShader", w: 2.0 },
    { r: 610, col: PAL.burnishedBronze, br: "velvetShader", w: 2.1 },
    { r: 617, col: PAL.moltenGold, br: "fineAir", w: 1.8 },
    { r: 623, col: PAL.voidIndigo, br: "velvetShader", w: 2.4 }
  ];

  for (let wr of wallRings) {
    for (let a0 = 0; a0 < 360; a0 += 45) {
      let pts = [];
      for (let a = a0; a <= a0 + 48; a += 9) {
        pts.push(panPoint(wr.r, a));
      }
      // Modulate color slightly around circumference for realism
      let col = wr.col;
      if (wr.r === 617 && a0 >= 135 && a0 <= 255) col = PAL.hotMagenta;
      if (wr.r === 602 && (a0 >= 270 || a0 <= 45)) col = PAL.electricTeal;
      brush.set(wr.br, col, wr.w);
      brush.spline(pts, 0.4);
    }
  }

  // 2. Tubular Rolled Chrome Rim (r = 624..674)
  // High-contrast compressed horizon bands along the torus of the rim
  let rimBands = [
    { r: 627, col: PAL.brightUltra, br: "velvetShader", w: 1.9 },
    { r: 632, col: PAL.lavenderGlow, br: "fineAir", w: 1.6 },
    { r: 636, col: PAL.chromeSilver, br: "velvetShader", w: 2.2 },
    { r: 639, col: PAL.pureWhite, br: "chromePen", w: 1.4 },
    { r: 644, col: PAL.incandescent, br: "velvetShader", w: 1.8 },
    { r: 649, col: PAL.moltenGold, br: "velvetShader", w: 2.0 },
    { r: 655, col: PAL.rawUmber, br: "velvetShader", w: 2.4 },
    { r: 661, col: PAL.voidIndigo, br: "velvetShader", w: 2.5 },
    { r: 666, col: PAL.electricViolet, br: "velvetShader", w: 1.8 },
    { r: 671, col: PAL.electricTeal, br: "chromePen", w: 1.1 },
    { r: 674, col: PAL.voidIndigo, br: "rotring", w: 1.5 }
  ];

  for (let rb of rimBands) {
    for (let a0 = 0; a0 < 360; a0 += 40) {
      let pts = [];
      for (let a = a0; a <= a0 + 43; a += 8) {
        pts.push(panPoint(rb.r, a));
      }
      brush.set(rb.br, rb.col, rb.w);
      brush.spline(pts, 0.4);
    }
  }

  // Extra razor-sharp specular white & gold highlights along the rim crest
  for (let a0 = 0; a0 < 360; a0 += 30) {
    if (a0 % 60 === 0) {
      let pts = [];
      for (let a = a0; a <= a0 + 24; a += 6) {
        pts.push(panPoint(638, a));
      }
      brush.set("chromePen", PAL.pureWhite, 1.6);
      brush.spline(pts, 0.35);
    }
  }

  // Fine metallic pen tool scratches & rolled seam marks across the rim
  for (let a = 0; a < 360; a += 4.5) {
    if (random() < 0.35) continue;
    let p1 = panPoint(624, a);
    let p2 = panPoint(648, a + 0.6);
    let p3 = panPoint(672, a + 1.0);
    let col = random([PAL.voidIndigo, PAL.chromeSilver, PAL.brightGold, PAL.lavenderGlow]);
    brush.set("chromePen", col, random(0.35, 0.7));
    brush.spline([p1, p2, p3], 0.3);
  }
}

// =========================================================================
// STAGE 6: WARPED CHROME REFLECTIONS OF THE TWO DRUMSTICKS
// =========================================================================
// Define the two drumsticks in polar/3D coordinates over the pan so we can
// both project their warped reflections onto the concave bowl below AND draw the physical sticks!
const STICKS = [
  {
    // Stick 1 (Upper-left of the pair, resting across left-lower rim into bowl)
    pButt: [-35, 895],
    pTip: [448, 632],
    rStart: 740, thStart: 171,
    rEnd: 235, thEnd: 166,
    shaftR: 13.5,
    tipLen: 0.24, // fraction of stick length covered by rubber tip
    tipR: 16.5
  },
  {
    // Stick 2 (Lower-right of the pair, resting across lower-left rim at slight converging angle)
    pButt: [65, 1055],
    pTip: [528, 706],
    rStart: 755, thStart: 146,
    rEnd: 165, thEnd: 132,
    shaftR: 13.5,
    tipLen: 0.24,
    tipR: 16.5
  }
];

function drawDrumstickReflections() {
  // For each stick, trace its path over the concave bowl (t = 0.16..1.0)
  // Because the bowl is sunken below the stick, the reflection shifts downward (+y)
  // and curves over the note domes!
  for (let st of STICKS) {
    let reflCenterPts = [];
    let reflUpperPts = [];
    let reflLowerPts = [];
    let tipReflPts = [];

    for (let t = 0.14; t <= 1.02; t += 0.04) {
      let r = lerp(st.rStart, st.rEnd, t);
      let th = lerp(st.thStart, st.thEnd, t);

      // Check if this (r, th) passes over a note dome to add local blister bump
      let bumpZ = 0;
      if (r < 570 && r > 370) bumpZ = 14 * Math.sin(((r - 370) / 200) * Math.PI);
      else if (r <= 340 && r > 215) bumpZ = 11 * Math.sin(((r - 215) / 125) * Math.PI);

      let pC = panPoint(r, th, bumpZ);
      let pU = panPoint(r, th + 2.2, bumpZ);
      let pL = panPoint(r, th - 2.2, bumpZ);

      reflCenterPts.push(pC);
      reflUpperPts.push(pU);
      reflLowerPts.push(pL);
      if (t >= 1.0 - st.tipLen) {
        tipReflPts.push(pC);
      }
    }

    // Airbrushed & velvetShader warped reflection of wooden shaft on the chrome bowl
    brush.set("airbrush", PAL.voidIndigo, 2.2);
    brush.spline(reflLowerPts, 0.45);

    brush.set("velvetShader", PAL.woodShadow, 2.4);
    brush.spline(reflCenterPts, 0.45);

    brush.set("velvetShader", PAL.woodWarm, 1.5);
    brush.spline(reflUpperPts, 0.45);

    // Warped reflection of the terracotta rubber tip in the metal
    if (tipReflPts.length >= 3) {
      brush.set("velvetShader", PAL.rubberDark, 2.8);
      brush.spline(tipReflPts, 0.45);
      brush.set("fineAir", PAL.rubberWarm, 1.8);
      brush.spline(tipReflPts, 0.45);
    }

    // Sharp mirror contact shadow right where the stick touches the rolled chrome rim
    let pRim1 = panPoint(634, st.thStart - 1.5, 2);
    let pRim2 = panPoint(648, st.thStart, 2);
    let pRim3 = panPoint(665, st.thStart + 1.5, 2);
    brush.set("velvetShader", PAL.voidIndigo, 2.8);
    brush.spline([pRim1, pRim2, pRim3], 0.3);
  }
}

// =========================================================================
// STAGE 7: TWO DRUMSTICKS WITH WORN RUBBER TIPS RESTING ACROSS THE RIM
// =========================================================================
function drawDrumsticks() {
  for (let sIdx = 0; sIdx < STICKS.length; sIdx++) {
    let st = STICKS[sIdx];
    let x1 = st.pButt[0], y1 = st.pButt[1];
    let x2 = st.pTip[0], y2 = st.pTip[1];

    let dx = x2 - x1;
    let dy = y2 - y1;
    let len = Math.hypot(dx, dy);
    let ux = dx / len;
    let uy = dy / len;
    // Perpendicular normal (pointing toward upper-left light source)
    let nx = uy;
    let ny = -ux;
    if (ny > 0) {
      nx = -nx;
      ny = -ny;
    }

    let tipStartT = 1.0 - st.tipLen;
    let neckX = lerp(x1, x2, tipStartT);
    let neckY = lerp(y1, y2, tipStartT);

    // 1. Soft cast shadow right on the chrome rim where the shaft rests
    let rimT = 0.23;
    let rx = lerp(x1, x2, rimT);
    let ry = lerp(y1, y2, rimT);
    brush.set("fineAir", PAL.voidIndigo, 2.6);
    brush.spline([
      [rx - ux * 35 + nx * -16, ry - uy * 35 + ny * -16],
      [rx + nx * -18, ry + ny * -18],
      [rx + ux * 45 + nx * -15, ry + uy * 45 + ny * -15]
    ], 0.3);

    // 2. Turned Wooden Shaft Base Wash
    brush.set("HB", PAL.woodShadow, 1);
    brush.noStroke();
    let shaftPoly = [
      [x1 + nx * st.shaftR, y1 + ny * st.shaftR],
      [neckX + nx * (st.shaftR * 0.86), neckY + ny * (st.shaftR * 0.86)],
      [neckX - nx * (st.shaftR * 0.86), neckY - ny * (st.shaftR * 0.86)],
      [x1 - nx * st.shaftR, y1 - ny * st.shaftR]
    ];
    brush.wash(PAL.woodMid, 245);
    drawShapePts(shaftPoly, 0.05);

    // 3. Cylindrical Shading along Wooden Shaft
    let shaftStrips = [
      { off: -0.82, col: PAL.voidIndigo, br: "velvetShader", w: 1.5 },
      { off: -0.58, col: PAL.woodShadow, br: "velvetShader", w: 1.9 },
      { off: -0.22, col: PAL.woodMid, br: "velvetShader", w: 2.0 },
      { off: 0.12, col: PAL.woodWarm, br: "velvetShader", w: 1.9 },
      { off: 0.46, col: PAL.woodLight, br: "velvetShader", w: 1.6 },
      { off: 0.65, col: PAL.incandescent, br: "chromePen", w: 0.9 },
      { off: 0.85, col: PAL.woodMid, br: "chromePen", w: 0.85 },
      // Reflected purple/gold bounce light on underside of stick from the pan!
      { off: -0.72, col: sIdx === 0 ? PAL.moltenGold : PAL.carnivalMagenta, br: "fineAir", w: 1.1 }
    ];

    for (let sp of shaftStrips) {
      let r1 = st.shaftR * sp.off;
      let r2 = st.shaftR * 0.86 * sp.off;
      let p1 = [x1 + nx * r1, y1 + ny * r1];
      let p2 = [lerp(x1, neckX, 0.5) + nx * ((r1 + r2) * 0.5), lerp(y1, neckY, 0.5) + ny * ((r1 + r2) * 0.5)];
      let p3 = [neckX + nx * r2, neckY + ny * r2];
      brush.set(sp.br, sp.col, sp.w);
      brush.spline([p1, p2, p3], 0.2);
    }

    // Fine wood-grain fibers along the shaft
    for (let g = 0; g < 22; g++) {
      let tA = random(0.02, 0.65);
      let tB = Math.min(tipStartT - 0.02, tA + random(0.15, 0.32));
      let off = random(-0.75, 0.75);
      let rA = lerp(st.shaftR, st.shaftR * 0.86, tA) * off;
      let rB = lerp(st.shaftR, st.shaftR * 0.86, tB) * off;
      let gx1 = lerp(x1, x2, tA) + nx * rA;
      let gy1 = lerp(y1, y2, tA) + ny * rA;
      let gx2 = lerp(x1, x2, tB) + nx * rB;
      let gy2 = lerp(y1, y2, tB) + ny * rB;
      let gCol = off > 0.2 ? PAL.woodLight : (off < -0.2 ? PAL.woodShadow : PAL.rawUmber);
      brush.set("2H", gCol, 0.65);
      brush.line(gx1, gy1, gx2, gy2);
    }

    // Traditional lathe-turned decorative grooves & painted rings on the stick shaft
    let ringPositions = [0.34, 0.365, 0.68, 0.70];
    for (let idx = 0; idx < ringPositions.length; idx++) {
      let rt = ringPositions[idx];
      let cx = lerp(x1, x2, rt);
      let cy = lerp(y1, y2, rt);
      let rr = lerp(st.shaftR, st.shaftR * 0.86, rt);
      let rCol = (idx === 0 || idx === 2) ? PAL.voidIndigo : (idx === 1 ? PAL.moltenGold : PAL.carnivalMagenta);
      brush.set("chromePen", rCol, 1.2);
      brush.spline([
        [cx - nx * rr, cy - ny * rr],
        [cx + ux * 3, cy + uy * 3],
        [cx + nx * rr, cy + ny * rr]
      ], 0.5);
    }

    // Crisp outline along shaft edges
    brush.set("rotring", PAL.woodShadow, 0.9);
    brush.line(x1 + nx * st.shaftR, y1 + ny * st.shaftR, neckX + nx * (st.shaftR * 0.86), neckY + ny * (st.shaftR * 0.86));
    brush.line(x1 - nx * st.shaftR, y1 - ny * st.shaftR, neckX - nx * (st.shaftR * 0.86), neckY - ny * (st.shaftR * 0.86));

    // 4. WORN Muted-Earth / Terracotta Rubber Tip
    // Build rounded capsule polygon from neckX,neckY to x2,y2
    let tipPts = [];
    let collarR = st.tipR * 0.96;
    // Collar curve at base of rubber sleeve
    for (let a = -90; a <= 90; a += 30) {
      let rad = a * DEG2RAD;
      let px = neckX - ux * 5 * Math.cos(rad) + nx * collarR * Math.sin(rad);
      let py = neckY - uy * 5 * Math.cos(rad) + ny * collarR * Math.sin(rad);
      tipPts.push([px, py]);
    }
    // Upper edge to rounded dome tip
    let domeCenterX = x2 - ux * st.tipR * 0.65;
    let domeCenterY = y2 - uy * st.tipR * 0.65;
    for (let a = 90; a >= -90; a -= 20) {
      let rad = a * DEG2RAD;
      // Slightly flattened crown from striking the steelpan notes
      let flat = (Math.abs(a) < 35) ? 0.92 : 1.0;
      let px = domeCenterX + ux * st.tipR * 1.15 * Math.cos(rad) * flat + nx * st.tipR * Math.sin(rad);
      let py = domeCenterY + uy * st.tipR * 1.15 * Math.cos(rad) * flat + ny * st.tipR * Math.sin(rad);
      tipPts.push([px, py]);
    }

    // Solid base wash + dry pigment mass for worn matte rubber feel
    brush.set("HB", PAL.rubberDark, 1);
    brush.noStroke();
    brush.wash(PAL.rubberDark, 250);
    drawShapePts(tipPts, 0.25);

    brush.mass("charcoal", PAL.rubberMid, { precision: 0.7, strength: 0.65, gradient: 0.3, outline: false });
    drawShapePts(tipPts, 0.25);
    brush.noMass();

    // Cylindrical shading along the rubber sleeve
    let rubberStrips = [
      { off: -0.78, col: PAL.rubberShadow, br: "velvetShader", w: 1.9 },
      { off: -0.42, col: PAL.rubberDark, br: "velvetShader", w: 2.1 },
      { off: 0.0, col: PAL.rubberMid, br: "velvetShader", w: 2.1 },
      { off: 0.38, col: PAL.rubberWarm, br: "fineAir", w: 1.8 },
      { off: 0.62, col: PAL.rubberScuff, br: "fineAir", w: 1.3 },
      // Iridescent bounce reflection from the chrome pan onto the underside of the rubber tip
      { off: -0.68, col: PAL.electricTeal, br: "fineAir", w: 1.0 }
    ];

    for (let rs of rubberStrips) {
      let rOff = st.tipR * rs.off;
      let p1 = [neckX + ux * 4 + nx * rOff * 0.92, neckY + uy * 4 + ny * rOff * 0.92];
      let p2 = [lerp(neckX, domeCenterX, 0.55) + nx * rOff, lerp(neckY, domeCenterY, 0.55) + ny * rOff];
      let p3 = [domeCenterX + ux * 8 + nx * rOff * 0.72, domeCenterY + uy * 8 + ny * rOff * 0.72];
      brush.set(rs.br, rs.col, rs.w);
      brush.spline([p1, p2, p3], 0.35);
    }

    // Worn, scuffed, chalky striking crown at the tip of the rubber mallet
    for (let k = 0; k < 28; k++) {
      let ang = random(-65, 65) * DEG2RAD;
      let rad = random(0.3, 1.02) * st.tipR;
      let sx = domeCenterX + ux * rad * Math.cos(ang) * 1.05 + nx * rad * Math.sin(ang);
      let sy = domeCenterY + uy * rad * Math.cos(ang) * 1.05 + ny * rad * Math.sin(ang);
      let scCol = random([PAL.rubberScuff, PAL.rubberDust, PAL.mutedClay, PAL.rubberShadow]);
      brush.set("cpencil", scCol, random(0.8, 1.4));
      brush.line(sx, sy, sx + random(-4, 4), sy + random(-4, 4));
    }

    // Rolled rubber collar lip & binding seam where rubber meets wood
    brush.set("velvetShader", PAL.rubberShadow, 1.4);
    brush.spline([
      [neckX - nx * collarR, neckY - ny * collarR],
      [neckX + ux * 3, neckY + uy * 3],
      [neckX + nx * collarR, neckY + ny * collarR]
    ], 0.4);

    brush.set("chromePen", PAL.rubberScuff, 0.85);
    brush.spline([
      [neckX + ux * 3 - nx * collarR * 0.9, neckY + uy * 3 - ny * collarR * 0.9],
      [neckX + ux * 6, neckY + uy * 6],
      [neckX + ux * 3 + nx * collarR * 0.9, neckY + uy * 3 + ny * collarR * 0.9]
    ], 0.4);

    // Subtle contour definition around rubber tip
    brush.set("chromePen", PAL.rubberShadow, 0.85);
    brush.spline(tipPts.slice(0, 7), 0.3);
    brush.spline(tipPts.slice(6), 0.35);
  }
}

