// STAGE 8: TINY BRIGHT STARBURST HIGHLIGHTS ON RIMS & NOTE RIDGES
// =========================================================================
function drawStarburstHighlights() {
  let stars = [];

  // 1. Starbursts along the rolled chrome rim crest (r = 638)
  let rimStarAngles = [12, 38, 72, 108, 198, 224, 248, 276, 302, 328, 348];
  for (let a of rimStarAngles) {
    let pt = panPoint(638, a, 2);
    let sz = (a > 215 && a < 335) ? random(22, 36) : random(15, 26);
    let haloCol = (a > 240 && a < 330) ? PAL.brightGold : (a > 180 ? PAL.hotMagenta : PAL.electricTeal);
    stars.push({ x: pt[0], y: pt[1], size: sz, halo: haloCol, major: true });
  }

  // 2. Starbursts on the brightest note-dimple specular domes and groove seams
  for (let i = 0; i < notes.length; i++) {
    let note = notes[i];
    if (note.ring === 0 && (i % 2 === 0 || i === 9)) {
      let pSpec = getDimplePt(note, 0.58, 85 + note.tiltShift);
      stars.push({ x: pSpec[0], y: pSpec[1], size: random(16, 25), halo: PAL.brightGold, major: true });
    }
    if (note.ring === 1 && i % 3 === 0) {
      let pSeam = getDimplePt(note, 1.0, 45 + note.tiltShift);
      stars.push({ x: pSeam[0], y: pSeam[1], size: random(12, 19), halo: PAL.lavenderGlow, major: false });
    }
    if (note.ring === 2 && i % 2 === 1) {
      let pSpec = getDimplePt(note, 0.55, 265 + note.tiltShift);
      stars.push({ x: pSpec[0], y: pSpec[1], size: random(12, 18), halo: PAL.paleTeal, major: false });
    }
  }

  // Center medallion crown starburst
  let pCenter = getDimplePt(notes[notes.length - 1], 0.45, 75);
  stars.push({ x: pCenter[0], y: pCenter[1], size: 28, halo: PAL.brightGold, major: true });

  // Render each starburst with soft airbrushed halo + razor-sharp metallic pen spikes
  for (let st of stars) {
    // Glowing airbrushed core
    brush.set("fineAir", st.halo, 1.6);
    brush.circle(st.x, st.y, st.size * 0.28, 0.1);

    brush.set("fineAir", PAL.pureWhite, 1.2);
    brush.circle(st.x, st.y, st.size * 0.12, 0.05);

    // 4 primary needle rays (slightly tilted for optical camera-diffraction feel)
    let baseRot = -12;
    let rLong = st.size;
    let rDiag = st.size * 0.48;

    for (let k = 0; k < 4; k++) {
      let ang = (baseRot + k * 90) * DEG2RAD;
      let ex = st.x + Math.cos(ang) * rLong;
      let ey = st.y + Math.sin(ang) * rLong;
      let mx = st.x + Math.cos(ang) * (rLong * 0.45);
      let my = st.y + Math.sin(ang) * (rLong * 0.45);

      brush.set("chromePen", st.halo, 0.9);
      brush.line(st.x, st.y, ex, ey);

      brush.set("rotring", PAL.pureWhite, 1.15);
      brush.line(st.x, st.y, mx, my);
    }

    // 4 secondary diagonal rays
    if (st.major) {
      for (let k = 0; k < 4; k++) {
        let ang = (baseRot + 45 + k * 90) * DEG2RAD;
        let ex = st.x + Math.cos(ang) * rDiag;
        let ey = st.y + Math.sin(ang) * rDiag;
        brush.set("chromePen", PAL.pureWhite, 0.75);
        brush.line(st.x, st.y, ex, ey);
      }
    }

    // Tiny incandescent pinpoint center
    brush.set("rotring", PAL.pureWhite, 1.8);
    brush.line(st.x - 1.5, st.y, st.x + 1.5, st.y);
    brush.line(st.x, st.y - 1.5, st.x, st.y + 1.5);
  }
}

