// ============================================================================
// GEOMETRY & CLIPPING HELPERS
// ============================================================================

function octVertices(apothem, cx = CX, cy = CY) {
  const r = apothem / Math.cos(Math.PI / 8);
  const pts = [];
  for (let i = 0; i < 8; i++) {
    const a = (22.5 + i * 45) * (Math.PI / 180);
    pts.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]);
  }
  return pts;
}

function quadrantBedPoly(sx, sy, inset = 0) {
  const dIn = BED_INSET + inset;
  const dOut = BED_OUT - inset;
  const diagSum = (OCT_A_OUT + 12 + inset) * SQRT2;
  const dChamfer = diagSum - dIn;
  // Return counter-clockwise convex polygon
  const pts = [
    [CX + sx * dIn, CY + sy * dOut],
    [CX + sx * dOut, CY + sy * dOut],
    [CX + sx * dOut, CY + sy * dIn],
    [CX + sx * dChamfer, CY + sy * dIn],
    [CX + sx * dIn, CY + sy * dChamfer]
  ];
  if (sx * sy < 0) pts.reverse();
  return pts;
}

function quadrantCurbOuterPoly(sx, sy) {
  const dIn = CH_CURB;
  const dOut = W / 2 - WALL_IN;
  const diagSum = OCT_A_OUT * SQRT2;
  const dChamfer = diagSum - dIn;
  const pts = [
    [CX + sx * dIn, CY + sy * dOut],
    [CX + sx * dOut, CY + sy * dOut],
    [CX + sx * dOut, CY + sy * dIn],
    [CX + sx * dChamfer, CY + sy * dIn],
    [CX + sx * dIn, CY + sy * dChamfer]
  ];
  if (sx * sy < 0) pts.reverse();
  return pts;
}

// Sutherland-Hodgman polygon clipper (clipPoly must be CCW convex)
function signedArea(poly) {
  let a = 0;
  for (let i = 0; i < poly.length; i++) {
    const p1 = poly[i];
    const p2 = poly[(i + 1) % poly.length];
    a += p1[0] * p2[1] - p2[0] * p1[1];
  }
  return a * 0.5;
}

function ensureCCW(poly) {
  return signedArea(poly) < 0 ? poly.slice().reverse() : poly;
}

function clipPolygon(subjectPoly, clipPoly) {
  const clip = ensureCCW(clipPoly);
  let output = subjectPoly.slice();
  for (let i = 0; i < clip.length; i++) {
    if (output.length === 0) break;
    const A = clip[i];
    const B = clip[(i + 1) % clip.length];
    const input = output;
    output = [];
    const isInside = (P) =>
      (B[0] - A[0]) * (P[1] - A[1]) - (B[1] - A[1]) * (P[0] - A[0]) >= -1e-5;
    const intersect = (P, Q) => {
      const dx1 = Q[0] - P[0], dy1 = Q[1] - P[1];
      const dx2 = B[0] - A[0], dy2 = B[1] - A[1];
      const denom = dx1 * dy2 - dy1 * dx2;
      if (Math.abs(denom) < 1e-9) return P;
      const t = ((A[0] - P[0]) * dy2 - (A[1] - P[1]) * dx2) / denom;
      return [P[0] + t * dx1, P[1] + t * dy1];
    };
    for (let j = 0; j < input.length; j++) {
      const P = input[j];
      const Q = input[(j + 1) % input.length];
      const pIn = isInside(P);
      const qIn = isInside(Q);
      if (pIn && qIn) {
        output.push(Q);
      } else if (pIn && !qIn) {
        output.push(intersect(P, Q));
      } else if (!pIn && qIn) {
        output.push(intersect(P, Q));
        output.push(Q);
      }
    }
  }
  return output;
}

function pointInConvexPoly(x, y, poly) {
  const c = ensureCCW(poly);
  for (let i = 0; i < c.length; i++) {
    const A = c[i];
    const B = c[(i + 1) % c.length];
    if ((B[0] - A[0]) * (y - A[1]) - (B[1] - A[1]) * (x - A[0]) < 0) return false;
  }
  return true;
}

function clipSegmentToPoly(x1, y1, x2, y2, poly) {
  const c = ensureCCW(poly);
  let t0 = 0, t1 = 1;
  const dx = x2 - x1, dy = y2 - y1;
  for (let i = 0; i < c.length; i++) {
    const A = c[i];
    const B = c[(i + 1) % c.length];
    const ex = B[0] - A[0], ey = B[1] - A[1];
    // inward normal is (-ey, ex)
    const nx = -ey, ny = ex;
    const num = (x1 - A[0]) * nx + (y1 - A[1]) * ny;
    const den = dx * nx + dy * ny;
    if (Math.abs(den) < 1e-9) {
      if (num < 0) return null;
    } else {
      const t = -num / den;
      if (den < 0) {
        if (t < t1) t1 = t;
      } else {
        if (t > t0) t0 = t;
      }
      if (t0 > t1) return null;
    }
  }
  return [x1 + t0 * dx, y1 + t0 * dy, x1 + t1 * dx, y1 + t1 * dy];
}

function drawClippedLine(x1, y1, x2, y2, poly) {
  const seg = clipSegmentToPoly(x1, y1, x2, y2, poly);
  if (seg) {
    const len = Math.hypot(seg[2] - seg[0], seg[3] - seg[1]);
    if (len > 0.8) brush.line(seg[0], seg[1], seg[2], seg[3]);
  }
}

function drawShapePoly(pts, curvature = 0, close = true) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(close);
}

