  drawStoneArchitecture();

  // 5. Tiny Real Disorder Breaking the Order (Spilled Pebbles, Crack & Moss, Drifting Bud, Splash)
  drawTinyRealDisorder();

  // 6. Mapmaker Precision Linework, Construction Geometry & Graduated Frame
  drawMapmakerSurveyOverlay();

  noLoop();
}

