// ============================================================================
// 2A. QUADRANT I (NW: sx = -1, sy = -1) — WET TURQUOISE ZELLIGE TILE
// ============================================================================
function drawQuadrantZellige() {
  const sx = -1, sy = -1;
  const bedPoly = quadrantBedPoly(sx, sy, 0);

  // Base mortar bed wash
  brush.noStroke();
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.45, 0.35);
  brush.fill("#c5d2d0", 65);
  drawShapePoly(bedPoly);

  // Generate diagonal interlocking Moroccan zellige pattern (stars, octagons & cross lozenges)
  // Using a diagonal grid centered around the quadrant center (333, 333)
  const qcx = 333, qcy = 333;
  const step = 38; // diagonal lattice pitch
  const uVec = [Math.SQRT1_2, Math.SQRT1_2];
  const vVec = [-Math.SQRT1_2, Math.SQRT1_2];

  // Bucket polygons by glaze color so p5.brush caches watercolor fills efficiently
  const buckets = {
    verdMid: [],
    turquoise: [],
    celadon: [],
    lapisMid: [],
    verdDark: [],
    sandMid: [],
    seafoam: []
  };
  const allTiles = []; // store { poly, colorKey, center, isStar }

  const toXY = (u, v) => [
    qcx + u * step * uVec[0] + v * step * vVec[0],
    qcy + u * step * uVec[1] + v * step * vVec[1]
  ];

  const gap = 0.04; // mortar joint gap in grid units
  const k = 0.27;   // octagon/star proportion

  for (let iu = -11; iu <= 11; iu++) {
    for (let iv = -11; iv <= 11; iv++) {
      // 1. Main cut-corner octagonal zellige tile centered at (iu, iv)
      const r = 0.5 - gap;
      const c = r - k;
      const octUV = [
        [iu - c, iv - r], [iu + c, iv - r],
        [iu + r, iv - c], [iu + r, iv + c],
        [iu + c, iv + r], [iu - c, iv + r],
        [iu - r, iv + c], [iu - r, iv - c]
      ];
      const octRaw = octUV.map(([u, v]) => toXY(u, v));
      const octClipped = clipPolygon(octRaw, bedPoly);

      if (octClipped.length >= 3 && Math.abs(signedArea(octClipped)) > 18) {
        // Choose turquoise / verdigris glaze shade with natural kiln variation
        const n = noise(iu * 0.35 + 10, iv * 0.35 + 10);
        let key = "turquoise";
        if ((iu + iv) % 2 === 0) {
          if (n < 0.28) key = "verdMid";
          else if (n < 0.68) key = "turquoise";
          else key = "celadon";
        } else {
          if (n < 0.25) key = "verdDark";
          else if (n < 0.72) key = "verdMid";
          else if (n < 0.91) key = "seafoam";
          else key = "sandMid"; // occasional warm bisque/sandstone glaze shift
        }
        buckets[key].push(octClipped);
        allTiles.push({
          poly: octClipped,
          key,
          cx: toXY(iu, iv)[0],
          cy: toXY(iu, iv)[1],
          type: "oct"
        });
      }

      // 2. Interlocking 4-pointed star / diamond tile at (iu + 0.5, iv + 0.5)
      const su = iu + 0.5, sv = iv + 0.5;
      const sr = k - gap * 0.7;
      const sm = sr * 0.42;
      const starUV = [
        [su, sv - sr],
        [su + sm, sv - sm],
        [su + sr, sv],
        [su + sm, sv + sm],
        [su, sv + sr],
        [su - sm, sv + sm],
        [su - sr, sv],
        [su - sm, sv - sm]
      ];
      const starRaw = starUV.map(([u, v]) => toXY(u, v));
      const starClipped = clipPolygon(starRaw, bedPoly);

      if (starClipped.length >= 3 && Math.abs(signedArea(starClipped)) > 8) {
        let skey = (iu * 3 + iv) % 4 === 0 ? "sandMid" : "lapisMid";
        if (random() < 0.18) skey = "verdDark";
        buckets[skey].push(starClipped);
        allTiles.push({
          poly: starClipped,
          key: skey,
          cx: toXY(su, sv)[0],
          cy: toXY(su, sv)[1],
          type: "star"
        });
      }
    }
  }

  // Render batched watercolor glazes for each zellige bucket
  const bucketStyles = [
    { key: "turquoise", col: PAL.turquoise, op: 118 },
    { key: "verdMid", col: PAL.verdMid, op: 128 },
    { key: "celadon", col: PAL.celadon, op: 115 },
    { key: "verdDark", col: PAL.verdDark, op: 138 },
    { key: "seafoam", col: PAL.seafoam, op: 110 },
    { key: "lapisMid", col: PAL.lapisMid, op: 145 },
    { key: "sandMid", col: PAL.sandMid, op: 120 }
  ];

  brush.noStroke();
  brush.fillBleed(0.035, "in");
  brush.fillTexture(0.5, 0.42);

  for (const st of bucketStyles) {
    const list = buckets[st.key];
    brush.fill(st.col, st.op);
    for (let i = 0; i < list.length; i++) {
      // Shrink slightly for crisp lime-mortar gap
      const p = shrinkPoly(list[i], 0.85);
      drawShapePoly(p);
    }
  }

  // Second glaze pass on subset of tiles for pooled kiln-glaze depth
  brush.fillBleed(0.05, "in");
  brush.fill(PAL.lapisDeep, 52);
  for (let i = 0; i < allTiles.length; i += 3) {
    if (allTiles[i].type === "oct") {
      drawShapePoly(shrinkPoly(allTiles[i].poly, 3.2));
    }
  }

  // Wet water sheet spilled across the zellige from the fountain
  const puddle1 = clipPolygon([
    [138, 290], [275, 255], [415, 285], [495, 365],
    [535, 485], [420, 535], [270, 525], [160, 440]
  ], bedPoly);
  brush.fillBleed(0.14, "out");
  brush.fill(PAL.skyMid, 52);
  drawShapePoly(puddle1);

  const puddle2 = clipPolygon([
    [310, 320], [450, 310], [530, 390], [485, 525], [350, 495]
  ], bedPoly);
  brush.fill(PAL.lapisBright, 42);
  drawShapePoly(puddle2);

  // Tile outlines, glaze crazing, chipped terracotta corners & wet specular glints
  for (let i = 0; i < allTiles.length; i++) {
    const t = allTiles[i];
    const p = shrinkPoly(t.poly, 0.9);
    if (p.length < 3) continue;

    // 1. Hand-cut tile edge in fine slate-ink
    brush.set("map_pen", PAL.inkSlate, 0.42);
    for (let j = 0; j < p.length; j++) {
      const a = p[j];
      const b = p[(j + 1) % p.length];
      brush.line(a[0], a[1], b[0], b[1]);
    }

    // 2. Wet specular highlight on SE edges of tiles
    brush.set("rotring", PAL.skyFoam, 0.55);
    for (let j = 0; j < p.length; j++) {
      const a = p[j];
      const b = p[(j + 1) % p.length];
      const nx = -(b[1] - a[1]);
      const ny = b[0] - a[0];
      if (nx + ny > 0 && random() < 0.65) {
        brush.line(
          lerp(a[0], b[0], 0.15),
          lerp(a[1], b[1], 0.15),
          lerp(a[0], b[0], 0.85),
          lerp(a[1], b[1], 0.85)
        );
      }
    }

    // 3. Glaze crazing (fine crackle network inside octagonal tiles)
    if (t.type === "oct" && Math.abs(signedArea(p)) > 260) {
      const numCracks = floor(random(2, 5));
      let cx = t.cx + random(-5, 5);
      let cy = t.cy + random(-5, 5);
      brush.set("2H", (i % 2 === 0) ? PAL.verdDeep : PAL.skyPale, 0.24);
      for (let c = 0; c < numCracks; c++) {
        const ang = random(360);
        const len = random(6, 15);
        const nx = cx + cos(ang) * len;
        const ny = cy + sin(ang) * len;
        drawClippedLine(cx, cy, nx, ny, p);
        // Secondary micro-branch
        if (random() < 0.7) {
          const bang = ang + random([-52, 48, 62]);
          drawClippedLine(
            (cx + nx) * 0.5,
            (cy + ny) * 0.5,
            (cx + nx) * 0.5 + cos(bang) * len * 0.55,
            (cy + ny) * 0.5 + sin(bang) * len * 0.55,
            p
          );
        }
        cx = nx;
        cy = ny;
      }

      // 4. Occasional tiny chipped glaze corner revealing terracotta bisque
      if (random() < 0.16 && p.length >= 4) {
        const idx = floor(random(p.length));
        const v0 = p[idx];
        const vPrev = p[(idx - 1 + p.length) % p.length];
        const vNext = p[(idx + 1) % p.length];
        const chip = [
          v0,
          [lerp(v0[0], vPrev[0], 0.32), lerp(v0[1], vPrev[1], 0.32)],
          [lerp(v0[0], vNext[0], 0.32), lerp(v0[1], vNext[1], 0.32)]
        ];
        brush.noStroke();
        brush.wash(PAL.terraMid, 185);
        drawShapePoly(chip);
        brush.noWash();
      }
    }
  }

  // Diagonal wet caustic sheen ribbons across the wet zellige
  brush.set("caustic_filament", PAL.skyFoam, 0.65);
  for (let k = 0; k < 18; k++) {
    const x0 = random(150, 490);
    const y0 = random(250, 510);
    if (pointInConvexPoly(x0, y0, puddle1)) {
      const pts = [];
      let px = x0, py = y0;
      for (let s = 0; s < 5; s++) {
        pts.push([px, py, s === 2 ? 1.2 : 0.5]);
        px += random(10, 22);
        py += random(-12, 8);
      }
      brush.spline(pts, 0.5);
    }
  }

  // Crisp meniscus highlight along the wet puddle edge on the tiles
  brush.set("map_pen", PAL.skyPale, 0.5);
  for (let i = 0; i < puddle1.length; i++) {
    const a = puddle1[i];
    const b = puddle1[(i + 1) % puddle1.length];
    if (a[0] > 145 && b[0] > 145 && a[1] < 525 && b[1] < 525) {
      brush.line(a[0], a[1], b[0], b[1]);
    }
  }
}

function shrinkPoly(poly, amount) {
  if (poly.length < 3) return poly;
  let cx = 0, cy = 0;
  for (let i = 0; i < poly.length; i++) {
    cx += poly[i][0];
    cy += poly[i][1];
  }
  cx /= poly.length;
  cy /= poly.length;
  return poly.map(([x, y]) => {
    const dx = x - cx, dy = y - cy;
    const d = Math.hypot(dx, dy);
    if (d <= amount) return [cx, cy];
    const s = (d - amount) / d;
    return [cx + dx * s, cy + dy * s];
  });
}

// ============================================================================
// 2B. QUADRANT II (NE: sx = +1, sy = -1) — DRY TERRACOTTA GRAVEL
// ============================================================================
function drawQuadrantGravel() {
  const sx = 1, sy = -1;
  const bedPoly = quadrantBedPoly(sx, sy, 0);

  // 1. Layered sandstone pink & terracotta base washes
  brush.noStroke();
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.65, 0.38);

  brush.fill(PAL.sandPink, 115);
  drawShapePoly(bedPoly);

  brush.fill(PAL.sandMid, 75);
  drawShapePoly(quadrantBedPoly(sx, sy, 18));

  // Cool slate shadow wash in NE corner and warm terracotta core
  brush.fill(PAL.terraLight, 58);
  brush.circle(865, 335, 165, 0.25);

  // Damp darkened gravel margin near the fountain & North channel curb
  const dampZone = clipPolygon([
    [668, 138], [728, 138], [712, 355], [895, 512], [895, 532], [668, 532]
  ], bedPoly);
  brush.fillBleed(0.22, "out");
  brush.fill(PAL.terraDark, 72);
  drawShapePoly(dampZone);

  // 2. Raked gravel furrows (parallel to the 45° octagon chamfer!)
  // Line equation: x - y = const (slope +1 in screen coords for NE quadrant)
  const rakeSpacing = 20;
  for (let d = -380; d <= 920; d += rakeSpacing) {
    // Trough shadow line
    const x1 = 665, y1 = 665 - d;
    const x2 = 1070, y2 = 1070 - d;
    brush.set("charcoal", PAL.terraDark, 0.55);
    drawClippedLine(x1, y1, x2, y2, bedPoly);

    // Cool limestone trough undertone
    brush.set("2B", PAL.stoneShadow, 0.42);
    drawClippedLine(x1, y1 + 3, x2, y2 + 3, bedPoly);

    // Sunlit ridge crest in pale sandstone blush
    brush.set("cpencil", PAL.sandPale, 0.65);
    drawClippedLine(x1, y1 - 5, x2, y2 - 5, bedPoly);
  }

  // 3. Fine mineral stipple pass across the bed
  const sprayColors = [PAL.terraMid, PAL.sandPink, PAL.stoneCool, PAL.terraDark, PAL.sandPale];
  for (let c = 0; c < sprayColors.length; c++) {
    brush.set("mineral_stipple", sprayColors[c], 0.75);
    for (let i = 0; i < 48; i++) {
      const rx = random(675, 1055);
      const ry = random(145, 525);
      if (pointInConvexPoly(rx, ry, bedPoly)) {
        brush.line(rx, ry, rx + random(-8, 8), ry + random(-8, 8));
      }
    }
  }

  // 4. Hundreds of individually rendered angular terracotta & limestone pebbles
  // Grouped by mineral shade for efficient batching
  const pebblePal = [
    PAL.terraLight,
    PAL.terraMid,
    PAL.sandPink,
    PAL.sandPale,
    PAL.stoneCool,
    PAL.terraDark,
    "#8b99a1" // cool blue-grey slate chip
  ];

  const pebbles = [];
  for (let i = 0; i < 620; i++) {
    const px = random(672, 1058);
    const py = random(142, 528);
    if (!pointInConvexPoly(px, py, bedPoly)) continue;

    const r = random(1.8, 5.2) * (random() < 0.12 ? 1.35 : 1.0);
    const sides = floor(random(4, 7));
    const baseAng = random(360);
    const pts = [];
    for (let s = 0; s < sides; s++) {
      const a = baseAng + (s * 360) / sides + random(-18, 18);
      const rad = r * random(0.72, 1.18);
      pts.push([px + cos(a) * rad, py + sin(a) * rad]);
    }
    const isDamp = pointInConvexPoly(px, py, dampZone);
    const colIdx = isDamp
      ? (random() < 0.65 ? 5 : 1)
      : floor(pow(random(), 1.2) * pebblePal.length);

    pebbles.push({ px, py, r, pts, col: pebblePal[colIdx], isDamp });
  }

  // Pass A: Crisp cast shadows on NW side of every pebble
  brush.set("map_pen", PAL.terraUmber, 0.42);
  for (let i = 0; i < pebbles.length; i++) {
    const p = pebbles[i];
    brush.line(
      p.px - p.r * 0.85,
      p.py - p.r * 0.45,
      p.px - p.r * 0.2,
      p.py - p.r * 0.95
    );
  }

  // Pass B: Mineral body washes batched by color
  brush.noStroke();
  for (let c = 0; c < pebblePal.length; c++) {
    const col = pebblePal[c];
    for (let i = 0; i < pebbles.length; i++) {
      if (pebbles[i].col === col && pebbles[i].r > 2.6) {
        brush.wash(col, 210);
        drawShapePoly(pebbles[i].pts);
        brush.noWash();
      }
    }
  }

  // Pass C: Faceted outlines & sunlit SE mineral highlights
  for (let i = 0; i < pebbles.length; i++) {
    const p = pebbles[i];
    brush.set("2H", PAL.inkSepia, 0.25);
    const v0 = p.pts[0];
    const v1 = p.pts[1];
    const v2 = p.pts[2];
    brush.line(v0[0], v0[1], v1[0], v1[1]);
    brush.line(v1[0], v1[1], v2[0], v2[1]);

    if (!p.isDamp && random() < 0.7) {
      brush.set("rotring", PAL.skyFoam, 0.35);
      brush.line(
        p.px + p.r * 0.15,
        p.py + p.r * 0.55,
        p.px + p.r * 0.65,
        p.py + p.r * 0.15
      );
    }
  }
}

// ============================================================================
// 2C. QUADRANT III (SW: sx = -1, sy = +1) — HONED FLAGSTONE & FALLEN FIG LEAF
// ============================================================================
function drawQuadrantFigLeaf() {
  const sx = -1, sy = 1;
  const bedPoly = quadrantBedPoly(sx, sy, 0);

  // 1. Honed cool limestone & pale sandstone paving slabs
  brush.noStroke();
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.48, 0.3);
  brush.fill(PAL.stoneLight, 110);
  drawShapePoly(bedPoly);

  // Generate coursed ashlar limestone slabs clipped to the quadrant
  const rowHeights = [68, 76, 64, 82, 70, 66];
  let curY = 668;
  let rowIdx = 0;
  const slabs = [];

  while (curY < 1068) {
    const rh = rowHeights[rowIdx % rowHeights.length];
    let curX = 132 - (rowIdx % 2) * 48;
    while (curX < 535) {
      const rw = 84 + ((rowIdx * 37 + Math.floor(curX)) % 38);
      const rawSlab = [
        [curX, curY],
        [curX + rw, curY],
        [curX + rw, curY + rh],
        [curX, curY + rh]
      ];
      const clipped = clipPolygon(rawSlab, bedPoly);
      if (clipped.length >= 3 && Math.abs(signedArea(clipped)) > 45) {
        slabs.push({ poly: clipped, row: rowIdx, x: curX, y: curY });
      }
      curX += rw;
    }
    curY += rh;
    rowIdx++;
  }

  // Batched subtle washes on individual limestone flags
  const slabTones = [PAL.stoneMid, PAL.sandPale, PAL.paperCool, "#cdd8d6"];
  for (let t = 0; t < slabTones.length; t++) {
    brush.fill(slabTones[t], 52);
    for (let i = 0; i < slabs.length; i++) {
      if (i % slabTones.length === t) {
        drawShapePoly(shrinkPoly(slabs[i].poly, 1.2));
      }
    }
  }

  // Damp verdigris-lapis water stain near the octagonal fountain rim
  const dampCorner = clipPolygon([
    [320, 668], [532, 668], [532, 895], [435, 835], [345, 755]
  ], bedPoly);
  brush.fillBleed(0.22, "out");
  brush.fill(PAL.verdMid, 36);
  drawShapePoly(dampCorner);

  // Hairline stone joints & chisel-drafted texture on the paving slabs
  for (let i = 0; i < slabs.length; i++) {
    const p = shrinkPoly(slabs[i].poly, 0.8);
    brush.set("map_pen", PAL.inkSlate, 0.36);
    for (let j = 0; j < p.length; j++) {
      const a = p[j];
      const b = p[(j + 1) % p.length];
      brush.line(a[0], a[1], b[0], b[1]);
    }
    // Faint diagonal honing marks
    if (i % 2 === 0) {
      brush.hatchStyle("2H", PAL.stoneShadow, 0.2);
      brush.hatch(14, 35, { rand: 0.04 });
      brush.noStroke();
      brush.noFill();
      drawShapePoly(shrinkPoly(p, 4));
      brush.noHatch();
    }
  }

  // 2. HYPERREAL FALLEN FIG LEAF (Ficus carica)
  // Positioned naturally across the stone joints at (332, 856)
  drawHyperrealFigLeaf(332, 856, 1.05, -26);
}

function drawHyperrealFigLeaf(leafCX, leafCY, sc, rotDeg) {
  const rotRad = rotDeg * (Math.PI / 180);
  const tx = (lx, ly) => [
    leafCX + (lx * Math.cos(rotRad) - ly * Math.sin(rotRad)) * sc,
    leafCY + (lx * Math.sin(rotRad) + ly * Math.cos(rotRad)) * sc
  ];

  // Construct anatomical 5-lobed palmate Ficus carica contour around petiole hub (0, 38)
  // Lobes at angles: -90° (central apical), -32° & -148° (upper lateral), +22° & -202° (basal)
  const hubX = 0, hubY = 42;
  const lobeAngles = [-90, -34, -146, 20, -200];
  const lobeLengths = [132, 108, 112, 72, 75];
  const lobeWidths = [22, 24, 24, 26, 26];

  const evalLeafRadius = (deg) => {
    // Normalize deg around -90 (from -265 to +85)
    let a = deg;
    while (a > 90) a -= 360;
    while (a < -270) a += 360;

    // Cordate base notch near +90 / -270 (petiole insertion)
    const distFromBase = Math.min(Math.abs(a - 90), Math.abs(a + 270));
    if (distFromBase < 28) {
      return 10 + 18 * Math.pow(distFromBase / 28, 1.4);
    }

    // Sum Gaussian lobe envelopes separated by deep rounded keyhole sinuses
    let r = 24; // palmate web base radius
    for (let i = 0; i < 5; i++) {
      const da = (a - lobeAngles[i]) / lobeWidths[i];
      // Spatulate fig-lobe broadening near the outer third of each lobe
      const env = Math.exp(-0.5 * da * da);
      const shoulder = Math.exp(-0.5 * Math.pow((Math.abs(da) - 0.58) / 0.35, 2)) * 18;
      const contrib = (lobeLengths[i] - 24) * env + shoulder * env;
      if (24 + contrib > r) r = 24 + contrib;
    }

    // Crenate-dentate margin scalloping along lobes
    if (r > 42) {
      const tooth = 3.6 * Math.sin(a * 0.24) + 1.8 * Math.cos(a * 0.52);
      r += tooth;
    }
    return r;
  };

  const leafPtsLocal = [];
  const steps = 150;
  for (let i = 0; i < steps; i++) {
    const deg = -266 + (i / steps) * 352;
    const rad = deg * (Math.PI / 180);
    const r = evalLeafRadius(deg);
    leafPtsLocal.push([hubX + r * Math.cos(rad), hubY + r * Math.sin(rad)]);
  }

  const leafPoly = leafPtsLocal.map(([x, y]) => tx(x, y));

  // A. Double Cast Shadow on the Limestone (Soft Ambient Lapis + Crisp Contact Shadow)
  const shadowSoft = leafPoly.map(([x, y]) => [x + 11, y + 14]);
  const shadowTight = leafPoly.map(([x, y]) => [x + 4.5, y + 6]);

  brush.noStroke();
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.45, 0.3);
  brush.fill(PAL.lapisAbyss, 48);
  drawShapePoly(shadowSoft);

  brush.fillBleed(0.04, "in");
  brush.fill(PAL.inkDark, 88);
  drawShapePoly(shadowTight);

  // B. Layered Botanical Watercolor Glazes on the Fig Leaf
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.55, 0.42);

  // Base verdigris-sage leaf lamina
  brush.fill(PAL.leafSage, 145);
  drawShapePoly(leafPoly);

  // Deep cool verdigris shadow along left lobes & sinus folds
  const leftLobes = leafPtsLocal
    .filter(([x, _]) => x < 18)
    .map(([x, y]) => tx(x * 0.92, y * 0.92));
  if (leftLobes.length > 3) {
    brush.fill(PAL.leafVerd, 110);
    drawShapePoly(leftLobes);
  }

  // Warm sandstone-pink & ochre autumn senescence on the curling right lateral lobe
  const rightBlushPts = [];
  for (let i = 0; i < steps; i++) {
    const deg = -266 + (i / steps) * 352;
    if (deg > -58 && deg < 42) {
      const rad = deg * (Math.PI / 180);
      const r = evalLeafRadius(deg) * 0.94;
      rightBlushPts.push(tx(hubX + r * Math.cos(rad), hubY + r * Math.sin(rad)));
    }
  }
  rightBlushPts.push(tx(hubX + 12, hubY - 8));
  if (rightBlushPts.length > 3) {
    brush.fillBleed(0.15, "in");
    brush.fill(PAL.leafBlush, 115);
    drawShapePoly(rightBlushPts);
  }

  // Deep forest-teal core near petiole junction
  const centerCore = leafPtsLocal.map(([x, y]) =>
    tx(hubX + (x - hubX) * 0.52, hubY + (y - hubY) * 0.52)
  );
  brush.fill(PAL.leafDeep, 72);
  drawShapePoly(centerCore);

  // C. Fine Cross-Hatched Botanical Shading in Sinus Valleys
  brush.hatchStyle("2H", PAL.leafDeep, 0.25);
  brush.hatch(5, rotDeg + 35, { rand: 0.08 });
  brush.noStroke();
  brush.noFill();
  drawShapePoly(centerCore);
  brush.noHatch();

  // D. Curved Woody Petiole (Stem) extending from cordate notch
  const stemPts = [
    tx(hubX, hubY + 6),
    tx(hubX + 5, hubY + 28),
    tx(hubX + 16, hubY + 52),
    tx(hubX + 34, hubY + 72)
  ];
  // Stem shadow
  brush.set("rotring", PAL.inkDark, 1.35);
  brush.spline(stemPts.map(([x, y]) => [x + 3.5, y + 4.5]), 0.5);
  // Stem body & highlight
  brush.set("cpencil", PAL.terraMid, 1.5);
  brush.spline(stemPts, 0.5);
  brush.set("map_pen", PAL.leafOchre, 0.7);
  brush.spline(stemPts.map(([x, y]) => [x - 0.8, y - 0.8]), 0.5);

  // E. Primary, Secondary & Tertiary Reticulate Venation
  for (let i = 0; i < 5; i++) {
    const angDeg = lobeAngles[i];
    const angRad = angDeg * (Math.PI / 180);
    const maxL = lobeLengths[i] - 5;

    // Build curved primary vein path
    const vPts = [];
    const vShadowPts = [];
    for (let s = 0; s <= 8; s++) {
      const t = s / 8;
      const dist = t * maxL;
      const curve = Math.sin(t * Math.PI) * (i === 0 ? 3 : (i % 2 === 0 ? -5 : 5));
      const perpRad = angRad + Math.PI / 2;
      const lx = hubX + Math.cos(angRad) * dist + Math.cos(perpRad) * curve;
      const ly = hubY + Math.sin(angRad) * dist + Math.sin(perpRad) * curve;
      const p = tx(lx, ly);
      const pSh = tx(lx + 1.4, ly + 1.4);
      vPts.push([p[0], p[1], (1 - t * 0.72) * 1.25]);
      vShadowPts.push([pSh[0], pSh[1], (1 - t * 0.72) * 1.1]);

      // Secondary pinnate lateral veins branching at ~48°
      if (s >= 2 && s <= 7) {
        for (const side of [-1, 1]) {
          const secAng = angRad + side * 0.82;
          const secLen = (1 - Math.abs(t - 0.52) * 1.35) * (i === 0 ? 34 : 26);
          if (secLen > 7) {
            const sx1 = lx + Math.cos(secAng) * secLen * 0.55;
            const sy1 = ly + Math.sin(secAng) * secLen * 0.55;
            // Brochidodromous loop curving upward near margin
            const sx2 = sx1 + Math.cos(secAng - side * 0.38) * secLen * 0.45;
            const sy2 = sy1 + Math.sin(secAng - side * 0.38) * secLen * 0.45;

            const sp0 = tx(lx, ly);
            const sp1 = tx(sx1, sy1);
            const sp2 = tx(sx2, sy2);

            brush.set("2H", PAL.leafDeep, 0.32);
            brush.spline([[sp0[0] + 1, sp0[1] + 1], [sp1[0] + 1, sp1[1] + 1], [sp2[0] + 1, sp2[1] + 1]], 0.4);

            brush.set("map_pen", PAL.leafVein, 0.38);
            brush.spline([
              [sp0[0], sp0[1], 0.9],
              [sp1[0], sp1[1], 0.65],
              [sp2[0], sp2[1], 0.3]
            ], 0.4);

            // Fine tertiary veinlets branching off secondary vein
            brush.set("2H", PAL.leafOchre, 0.2);
            for (let tv = 0; tv < 2; tv++) {
              const tang = secAng + (tv === 0 ? 0.9 : -0.85);
              const tlen = secLen * 0.32;
              const tp = tx(sx1 + Math.cos(tang) * tlen, sy1 + Math.sin(tang) * tlen);
              brush.line(sp1[0], sp1[1], tp[0], tp[1]);
            }
          }
        }
      }
    }

    // Primary vein under-shadow
    brush.set("map_pen", PAL.leafDeep, 0.55);
    brush.spline(vShadowPts, 0.4);

    // Raised ivory-sandstone primary midrib
    brush.set("rotring", PAL.leafVein, 0.72);
    brush.spline(vPts, 0.4);
  }

  // F. Crisp Botanical Outline, Desiccated Curled Tip & Insect Perforation
  brush.set("map_pen", PAL.inkDark, 0.44);
  for (let i = 0; i < leafPoly.length; i++) {
    const a = leafPoly[i];
    const b = leafPoly[(i + 1) % leafPoly.length];
    brush.line(a[0], a[1], b[0], b[1]);
  }

  // Small weathered insect perforation hole revealing the pale limestone underneath
  const holePos = tx(-34, -22);
  brush.noStroke();
  brush.wash(PAL.stoneLight, 235);
  brush.circle(holePos[0], holePos[1], 4.8, 0.25);
  brush.noWash();
  brush.set("map_pen", PAL.terraUmber, 0.48);
  brush.circle(holePos[0], holePos[1], 4.8, 0.25);

  // G. Glistening Water Droplets Beaded on the Fig Leaf Cuticle
  const drops = [
    tx(-12, -46),
    tx(26, -18),
    tx(-42, 6),
    tx(8, 12)
  ];
  for (const [dx, dy] of drops) {
    // Refractive cast shadow on SE side
    brush.noStroke();
    brush.wash(PAL.leafDeep, 160);
    brush.circle(dx + 1.8, dy + 1.8, 3.2, 0.1);
    // Turquoise-sky interior refraction
    brush.wash(PAL.skyMid, 200);
    brush.circle(dx, dy, 3.0, 0.1);
    brush.noWash();
    // Pinpoint specular highlight on NW side
    brush.set("rotring", "#ffffff", 0.75);
    brush.line(dx - 1.2, dy - 1.2, dx - 0.4, dy - 0.5);
  }
}

// ============================================================================
// 2D. QUADRANT IV (SE: sx = +1, sy = +1) — RIPPLING WATER CATCHING SKY
// ============================================================================
function drawQuadrantRipplingWater() {
  const sx = 1, sy = 1;
  const bedPoly = quadrantBedPoly(sx, sy, 0);

  // 1. Layered Watercolor Glazes: Lapis, Verdigris, Sandstone Perimeter & Reflected Sky
  brush.noStroke();
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.52, 0.35);

  // Warm sandstone-pink shallow perimeter glow
  brush.fill(PAL.sandMid, 75);
  drawShapePoly(bedPoly);

  // Mid verdigris & cerulean basin depth
  brush.fill(PAL.verdMid, 95);
  drawShapePoly(quadrantBedPoly(sx, sy, 14));

  brush.fill(PAL.lapisMid, 105);
  drawShapePoly(quadrantBedPoly(sx, sy, 28));

  // Deep lapis lazuli pool core
  const deepCore = clipPolygon([
    [680, 680], [995, 685], [1035, 985], [705, 1035], [670, 820]
  ], bedPoly);
  brush.fillBleed(0.24, "in");
  brush.fill(PAL.lapisDeep, 92);
  drawShapePoly(deepCore);

  // Luminous diagonal sky & high-cloud reflection bands catching the surface
  const skyBand1 = clipPolygon([
    [670, 785], [885, 670], [1045, 670], [1045, 755], [765, 935], [670, 885]
  ], bedPoly);
  brush.fillBleed(0.28, "out");
  brush.fill(PAL.skyPale, 95);
  drawShapePoly(skyBand1);

  const cloudBlush = clipPolygon([
    [735, 815], [945, 695], [1025, 735], [815, 885]
  ], bedPoly);
  brush.fill(PAL.sandPale, 68);
  drawShapePoly(cloudBlush);

  // 2. Submerged Stone Basin Grid Refracted by Surface Waves
  brush.set("2H", PAL.lapisAbyss, 0.28);
  for (let g = 720; g <= 1020; g += 60) {
    // Wavy horizontal & vertical submerged joints
    const hPts = [], vPts = [];
    for (let t = 670; t <= 1060; t += 18) {
      const wave = Math.sin(t * 0.09 + g * 0.05) * 3.8;
      if (pointInConvexPoly(t, g + wave, bedPoly)) hPts.push([t, g + wave]);
      if (pointInConvexPoly(g + wave, t, bedPoly)) vPts.push([g + wave, t]);
    }
    if (hPts.length > 2) brush.spline(hPts, 0.5);
    if (vPts.length > 2) brush.spline(vPts, 0.5);
  }

  // 3. Cellular Caustic Light Network (Gabriel-Graph / Voronoi Ridge Web)
  const causticSites = [];
  const gridStep = 44;
  for (let gx = 680; gx <= 1055; gx += gridStep) {
    for (let gy = 680; gy <= 1055; gy += gridStep) {
      const px = gx + random(-15, 15);
      const py = gy + random(-15, 15);
      if (pointInConvexPoly(px, py, bedPoly)) {
        causticSites.push([px, py]);
      }
    }
  }

  // Construct cellular caustic ridges between neighboring wave focal cells
  const causticEdges = [];
  for (let i = 0; i < causticSites.length; i++) {
    for (let j = i + 1; j < causticSites.length; j++) {
      const a = causticSites[i];
      const b = causticSites[j];
      const d = Math.hypot(a[0] - b[0], a[1] - b[1]);
      if (d < gridStep * 1.55) {
        const mx = (a[0] + b[0]) * 0.5;
        const my = (a[1] + b[1]) * 0.5;
        // Check Gabriel condition (no third site inside diameter circle)
        let valid = true;
        const rCheck = d * 0.48;
        for (let k = 0; k < causticSites.length; k++) {
          if (k === i || k === j) continue;
          if (Math.hypot(causticSites[k][0] - mx, causticSites[k][1] - my) < rCheck) {
            valid = false;
            break;
          }
        }
        if (valid) causticEdges.push([a, b]);
      }
    }
  }

  // Pass 1: Soft glowing turquoise/verdigris caustic aura
  brush.set("caustic_filament", PAL.turquoise, 0.85);
  for (let i = 0; i < causticEdges.length; i++) {
    const [a, b] = causticEdges[i];
    const mx = (a[0] + b[0]) * 0.5 + random(-4, 4);
    const my = (a[1] + b[1]) * 0.5 + random(-4, 4);
    brush.spline([[a[0], a[1], 0.5], [mx, my, 1.2], [b[0], b[1], 0.5]], 0.45);
  }

  // Pass 2: Bright sky-white caustic filament cores & nodal stars
  brush.set("map_pen", PAL.skyFoam, 0.52);
  for (let i = 0; i < causticEdges.length; i++) {
    const [a, b] = causticEdges[i];
    drawClippedLine(a[0], a[1], b[0], b[1], bedPoly);
  }

  // 4. Concentric Intersecting Water Ripples (Two Wave Centers)
  const waveCenters = [
    { x: 740, y: 740, maxR: 380, step: 19 }, // Entering from octagon corner
    { x: 905, y: 885, maxR: 260, step: 15 }  // Falling water droplet impact
  ];

  for (const wc of waveCenters) {
    for (let r = 8; r <= wc.maxR; r += wc.step) {
      // Sample arc segments around the circle and clip to quadrant bed
      const numSegs = Math.max(24, Math.floor(r * 0.45));
      for (let s = 0; s < numSegs; s++) {
        // Leave natural wave breaks
        if (noise(r * 0.08, s * 0.35) < 0.28) continue;
        const a0 = (s / numSegs) * Math.PI * 2;
        const a1 = ((s + 0.78) / numSegs) * Math.PI * 2;
        const x0 = wc.x + Math.cos(a0) * r;
        const y0 = wc.y + Math.sin(a0) * r;
        const x1 = wc.x + Math.cos(a1) * r;
        const y1 = wc.y + Math.sin(a1) * r;

        // Dark lapis wave trough
        brush.set("map_pen", PAL.lapisAbyss, 0.38);
        drawClippedLine(x0, y0, x1, y1, bedPoly);

        // Luminous sky crest offset by 2.5px toward light source (SE)
        brush.set("rotring", PAL.skyFoam, 0.45);
        drawClippedLine(x0 + 2.2, y0 + 2.2, x1 + 2.2, y1 + 2.2, bedPoly);
      }
    }
    // Central droplet impact ring
    brush.set("rotring", "#ffffff", 0.7);
    brush.circle(wc.x, wc.y, 4.5, 0.1);
  }
}

// ============================================================================
// 3. FOUR NARROW WATER CHANNELS & CENTRAL OCTAGONAL POOL
// ============================================================================
function drawWaterChannelsAndOctagonPool() {
  const octWaterPoly = octVertices(OCT_A_IN);
  const octSubPoly = octVertices(OCT_A_SUB);

  // Define the 4 narrow axial channel rectangles (N, S, E, W)
  const channels = [
    // North channel
    [[CX - CH_WATER, WALL_IN], [CX + CH_WATER, WALL_IN], [CX + CH_WATER, CY - OCT_A_IN], [CX - CH_WATER, CY - OCT_A_IN]],
    // South channel
    [[CX - CH_WATER, CY + OCT_A_IN], [CX + CH_WATER, CY + OCT_A_IN], [CX + CH_WATER, H - WALL_IN], [CX - CH_WATER, H - WALL_IN]],
    // West channel
    [[WALL_IN, CY - CH_WATER], [CX - OCT_A_IN, CY - CH_WATER], [CX - OCT_A_IN, CY + CH_WATER], [WALL_IN, CY + CH_WATER]],
    // East channel
    [[CX + OCT_A_IN, CY - CH_WATER], [W - WALL_IN, CY - CH_WATER], [W - WALL_IN, CY + CH_WATER], [CX + OCT_A_IN, CY + CH_WATER]]
  ];

  // 1. Batched Watercolor Glazes for Channels & Central Octagon
  brush.noStroke();
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.5, 0.38);

  // Outer verdigris-turquoise water layer
  brush.fill(PAL.verdMid, 125);
  drawShapePoly(octWaterPoly);
  for (const ch of channels) drawShapePoly(ch);

  // Mid lapis lazuli depth
  brush.fill(PAL.lapisMid, 118);
  drawShapePoly(octSubPoly);
  for (const ch of channels) drawShapePoly(shrinkPoly(ch, 5));

  // Deep ultramarine core inside octagonal basin
  brush.fill(PAL.lapisDeep, 125);
  drawShapePoly(octVertices(96));

  // Sandstone pink glow on submerged octagonal bench
  brush.fill(PAL.sandMid, 58);
  for (let i = 0; i < 8; i++) {
    const a1 = (22.5 + i * 45) * (Math.PI / 180);
    const a2 = (22.5 + (i + 1) * 45) * (Math.PI / 180);
    const rOut = OCT_A_IN / Math.cos(Math.PI / 8);
    const rIn = OCT_A_SUB / Math.cos(Math.PI / 8);
    if (i % 2 === 0) {
      drawShapePoly([
        [CX + rIn * Math.cos(a1), CY + rIn * Math.sin(a1)],
        [CX + rOut * Math.cos(a1), CY + rOut * Math.sin(a1)],
        [CX + rOut * Math.cos(a2), CY + rOut * Math.sin(a2)],
        [CX + rIn * Math.cos(a2), CY + rIn * Math.sin(a2)]
      ]);
    }
  }

  // 2. Submerged 8-Pointed Geometric Star Inlay (Rub el Hizb) on Pool Floor
  for (let rot = 0; rot < 2; rot++) {
    const sq = [];
    for (let k = 0; k < 4; k++) {
      const a = (rot * 45 + k * 90) * (Math.PI / 180);
      sq.push([CX + Math.cos(a) * 112, CY + Math.sin(a) * 112]);
    }
    brush.set("map_pen", PAL.skyMid, 0.42);
    for (let k = 0; k < 4; k++) {
      brush.line(sq[k][0], sq[k][1], sq[(k + 1) % 4][0], sq[(k + 1) % 4][1]);
    }
  }

  // Submerged bench octagon outline
  brush.set("map_pen", PAL.turquoise, 0.45);
  for (let i = 0; i < 8; i++) {
    const a = octSubPoly[i];
    const b = octSubPoly[(i + 1) % 8];
    brush.line(a[0], a[1], b[0], b[1]);
  }

  // 3. Radial Caustic Light Web & Concentric Fountain Waves in Central Octagon
  const numRays = 28;
  for (let i = 0; i < numRays; i++) {
    const a1 = (i / numRays) * 360 + random(-4, 4);
    const a2 = ((i + 1) / numRays) * 360 + random(-4, 4);
    for (let r = 46; r <= 148; r += 26) {
      const rJit = r + random(-6, 6);
      const x1 = CX + cos(a1) * rJit;
      const y1 = CY + sin(a1) * rJit;
      const x2 = CX + cos(a2) * (rJit + random(-5, 5));
      const y2 = CY + sin(a2) * (rJit + random(-5, 5));
      brush.set("caustic_filament", PAL.skyPale, 0.65);
      brush.line(x1, y1, x2, y2);
      if (i % 2 === 0 && r < 125) {
        brush.set("map_pen", PAL.skyFoam, 0.35);
        brush.line(
          x1,
          y1,
          CX + cos(a1 + 6) * (rJit + 24),
          CY + sin(a1 + 6) * (rJit + 24)
        );
      }
    }
  }

  // Concentric fountain ripple rings inside octagon
  for (let r = 40; r <= 156; r += 11) {
    for (let a = 0; a < 360; a += 32) {
      if (random() < 0.22) continue;
      brush.set("map_pen", PAL.lapisAbyss, 0.36);
      brush.arc(CX, CY, r, a, a + 22);
      brush.set("rotring", PAL.skyFoam, 0.45);
      brush.arc(CX + 1.5, CY + 1.5, r, a + 2, a + 20);
    }
  }

  // 4. Flowing Parabolic / Chevron Ripples & Caustics in the Four Channels
  // North & South channels
  for (const dir of [-1, 1]) {
    const yStart = CY + dir * (OCT_A_IN + 8);
    const yEnd = dir < 0 ? WALL_IN + 12 : H - WALL_IN - 12;
    const step = dir * 16;

    // Submerged channel wall shadow on West side
    brush.noStroke();
    brush.wash(PAL.lapisAbyss, 110);
    brush.rect(
      CX - CH_WATER,
      Math.min(yStart, yEnd),
      9,
      Math.abs(yEnd - yStart),
      "corner"
    );
    brush.noWash();

    for (let y = yStart; dir < 0 ? y > yEnd : y < yEnd; y += step) {
      const tipY = y - dir * 10;
      brush.set("caustic_filament", PAL.skyPale, 0.55);
      brush.spline([
        [CX - CH_WATER + 4, y, 0.4],
        [CX, tipY, 1.15],
        [CX + CH_WATER - 4, y, 0.4]
      ], 0.5);

      brush.set("map_pen", PAL.lapisAbyss, 0.32);
      brush.line(CX - CH_WATER + 6, y + 3, CX, tipY + 3);
      brush.line(CX, tipY + 3, CX + CH_WATER - 6, y + 3);
    }
  }

  // West & East channels
  for (const dir of [-1, 1]) {
    const xStart = CX + dir * (OCT_A_IN + 8);
    const xEnd = dir < 0 ? WALL_IN + 12 : W - WALL_IN - 12;
    const step = dir * 16;

    // Submerged channel wall shadow on North side
    brush.noStroke();
    brush.wash(PAL.lapisAbyss, 110);
    brush.rect(
      Math.min(xStart, xEnd),
      CY - CH_WATER,
      Math.abs(xEnd - xStart),
      9,
      "corner"
    );
    brush.noWash();

    for (let x = xStart; dir < 0 ? x > xEnd : x < xEnd; x += step) {
      const tipX = x - dir * 10;
      brush.set("caustic_filament", PAL.skyPale, 0.55);
      brush.spline([
        [x, CY - CH_WATER + 4, 0.4],
        [tipX, CY, 1.15],
        [x, CY + CH_WATER - 4, 0.4]
      ], 0.5);

      brush.set("map_pen", PAL.lapisAbyss, 0.32);
      brush.line(x + 3, CY - CH_WATER + 6, tipX + 3, CY);
      brush.line(tipX + 3, CY, x + 3, CY + CH_WATER - 6);
    }
  }

  // 5. Central Carved Stone & Bronze Fountain Jet Rosette
  const jetOct = octVertices(36);
  const jetIn = octVertices(22);

  // Shadow under central nozzle
  brush.noStroke();
  brush.wash(PAL.lapisAbyss, 165);
  drawShapePoly(octVertices(41, CX + 4, CY + 4));

  // Stone nozzle body
  brush.wash(PAL.stoneMid, 235);
  drawShapePoly(jetOct);
  brush.wash(PAL.sandPale, 195);
  drawShapePoly(jetIn);
  brush.wash(PAL.verdDark, 225);
  brush.circle(CX, CY, 11, 0.08);
  brush.noWash();

  // Carved radial flutes on central nozzle
  brush.set("map_pen", PAL.inkDark, 0.48);
  for (let i = 0; i < 8; i++) {
    brush.line(jetOct[i][0], jetOct[i][1], jetOct[(i + 1) % 8][0], jetOct[(i + 1) % 8][1]);
    brush.line(jetIn[i][0], jetIn[i][1], jetIn[(i + 1) % 8][0], jetIn[(i + 1) % 8][1]);
    brush.line(jetOct[i][0], jetOct[i][1], jetIn[i][0], jetIn[i][1]);
  }

  // Aerated bubbling white water plume at fountain center
  brush.set("rotring", PAL.skyFoam, 0.75);
  brush.circle(CX, CY, 6, 0.2);
  for (let i = 0; i < 22; i++) {
    const a = random(360);
    const d = random(4, 28);
    brush.circle(CX + cos(a) * d, CY + sin(a) * d, random(1.2, 3.2), 0.25);
  }
}

// ============================================================================
// 4. CARVED LIMESTONE ARCHITECTURE, CURBS, OCTAGON RIM & ASHLAR MASONRY
// ============================================================================
function drawStoneArchitecture() {
  // 1. Subtle watercolor stone washes along the curbs and perimeter coping
  brush.noStroke();
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.45, 0.3);

  // Perimeter stone coping strips (between M_SCALE=68 and WALL_IN=124)
  const copingRects = [
    [M_SCALE, M_SCALE, W - 2 * M_SCALE, WALL_IN - M_SCALE],
    [M_SCALE, H - WALL_IN, W - 2 * M_SCALE, WALL_IN - M_SCALE],
    [M_SCALE, WALL_IN, WALL_IN - M_SCALE, H - 2 * WALL_IN],
    [W - WALL_IN, WALL_IN, WALL_IN - M_SCALE, H - 2 * WALL_IN]
  ];
  brush.fill(PAL.stoneLight, 95);
  for (const r of copingRects) brush.rect(r[0], r[1], r[2], r[3], "corner");

  // Warm sandstone-pink blush on alternating perimeter blocks
  brush.fill(PAL.sandPale, 65);
  for (let pos = 124; pos < 1020; pos += 128) {
    brush.rect(pos, M_SCALE + 2, 64, WALL_IN - M_SCALE - 4, "corner");
    brush.rect(pos + 64, H - WALL_IN + 2, 64, WALL_IN - M_SCALE - 4, "corner");
    brush.rect(M_SCALE + 2, pos + 64, WALL_IN - M_SCALE - 4, 64, "corner");
    brush.rect(W - WALL_IN + 2, pos, WALL_IN - M_SCALE - 4, 64, "corner");
  }

  // 2. Central Octagonal Coping Ring (Stepped Limestone Rim: OCT_A_IN..OCT_A_OUT)
  const octOut = octVertices(OCT_A_OUT);
  const octStep = octVertices(OCT_A_STEP);
  const octIn = octVertices(OCT_A_IN);

  // Draw the 8 trapezoidal coping segments, leaving openings for the 4 axial water channels
  brush.set("map_pen", PAL.inkDark, 0.55);
  for (let i = 0; i < 8; i++) {
    const pOut1 = octOut[i];
    const pOut2 = octOut[(i + 1) % 8];
    const pStep1 = octStep[i];
    const pStep2 = octStep[(i + 1) % 8];
    const pIn1 = octIn[i];
    const pIn2 = octIn[(i + 1) % 8];

    // Diagonal faces (NE, SE, SW, NW) are solid continuous coping stones
    // Cardinal faces (E, S, W, N) are split in the middle by the 56px water channel!
    const isCardinal = i % 2 === 1; // i=0 is E face (from 22.5° to 67.5° is SE! Wait: let's check!)
    // Angle 0 is East: between i=7 (337.5°) and i=0 (22.5°).
    // So cardinal faces are i=7 (East), i=1 (South), i=3 (West), i=5 (North)!
    if (!isCardinal) {
      // Diagonal face (i = 0, 2, 4, 6 -> SE, SW, NW, NE)
      brush.line(pOut1[0], pOut1[1], pOut2[0], pOut2[1]);
      brush.line(pStep1[0], pStep1[1], pStep2[0], pStep2[1]);
      brush.line(pIn1[0], pIn1[1], pIn2[0], pIn2[1]);

      // Radial stone masonry joints along diagonal face
      for (const t of [0, 0.33, 0.67, 1.0]) {
        const ox = lerp(pOut1[0], pOut2[0], t);
        const oy = lerp(pOut1[1], pOut2[1], t);
        const ix = lerp(pIn1[0], pIn2[0], t);
        const iy = lerp(pIn1[1], pIn2[1], t);
        brush.line(ox, oy, ix, iy);
      }

      // Fine chisel-draft hatching on inner bevel step
      const bevelPoly = [pStep1, pStep2, pIn2, pIn1];
      brush.hatchStyle("2H", PAL.stoneShadow, 0.22);
      brush.hatch(7, i * 45, { rand: 0.03 });
      brush.noStroke();
      brush.noFill();
      drawShapePoly(bevelPoly);
      brush.noHatch();
      brush.set("map_pen", PAL.inkDark, 0.55);
    } else {
      // Cardinal face (interrupted by water channel from -28 to +28 around axis)
      // Draw the two shoulder segments on either side of the channel opening
      for (const [a1, a2] of [[pOut1, pOut2], [pStep1, pStep2], [pIn1, pIn2]]) {
        // Fraction where channel cuts the cardinal segment
        const segLen = Math.hypot(a2[0] - a1[0], a2[1] - a1[1]);
        const f1 = (segLen * 0.5 - CH_WATER) / segLen;
        const f2 = (segLen * 0.5 + CH_WATER) / segLen;
        brush.line(a1[0], a1[1], lerp(a1[0], a2[0], f1), lerp(a1[1], a2[1], f1));
        brush.line(lerp(a1[0], a2[0], f2), lerp(a1[1], a2[1], f2), a2[0], a2[1]);
      }
    }
  }

  // 3. Quadrant Stone Curb Frames & Miter Joints
  for (const sx of [-1, 1]) {
    for (const sy of [-1, 1]) {
      const innerBed = quadrantBedPoly(sx, sy, 0);
      const outerCurb = quadrantCurbOuterPoly(sx, sy);

      // Crisp inner drop shadow at quadrant bed edge
      brush.set("rotring", PAL.inkDark, 0.65);
      for (let i = 0; i < innerBed.length; i++) {
        const a = innerBed[i];
        const b = innerBed[(i + 1) % innerBed.length];
        brush.line(a[0], a[1], b[0], b[1]);
      }

      // Outer curb line along channels & perimeter
      brush.set("map_pen", PAL.inkMid, 0.48);
      for (let i = 0; i < outerCurb.length; i++) {
        const a = outerCurb[i];
        const b = outerCurb[(i + 1) % outerCurb.length];
        brush.line(a[0], a[1], b[0], b[1]);
        // Miter joint lines at each corner of the quadrant frame
        brush.line(innerBed[i][0], innerBed[i][1], outerCurb[i][0], outerCurb[i][1]);
      }
    }
  }

  // 4. Water Channel Walls, Curb Ashlar Joints & Carved Wall Spouts
  brush.set("rotring", PAL.inkDark, 0.62);
  // N & S channel water edges
  for (const x of [CX - CH_WATER, CX + CH_WATER]) {
    brush.line(x, WALL_IN, x, CY - OCT_A_IN);
    brush.line(x, CY + OCT_A_IN, x, H - WALL_IN);
  }
  // W & E channel water edges
  for (const y of [CY - CH_WATER, CY + CH_WATER]) {
    brush.line(WALL_IN, y, CX - OCT_A_IN, y);
    brush.line(CX + OCT_A_IN, y, W - WALL_IN, y);
  }

  // Transverse stone curb joints along the 4 channels
  brush.set("map_pen", PAL.inkSlate, 0.36);
  for (let d = 175; d <= 415; d += 58) {
    for (const s of [-1, 1]) {
      // N/S curb joints
      brush.line(CX - CH_CURB, CY + s * d, CX - CH_WATER, CY + s * d);
      brush.line(CX + CH_WATER, CY + s * d, CX + CH_CURB, CY + s * d);
      // E/W curb joints
      brush.line(CX + s * d, CY - CH_CURB, CX + s * d, CY - CH_WATER);
      brush.line(CX + s * d, CY + CH_WATER, CX + s * d, CY + CH_CURB);
    }
  }

  // Four Carved Fluted Salsabil Wall Spouts at N, S, E, W Perimeter
  const spouts = [
    { x: CX, y: WALL_IN, ang: 90 },
    { x: CX, y: H - WALL_IN, ang: -90 },
    { x: WALL_IN, y: CY, ang: 0 },
    { x: W - WALL_IN, y: CY, ang: 180 }
  ];
  for (const sp of spouts) {
    push();
    translate(sp.x, sp.y);
    rotate(sp.ang);
    // Carved semicircular stone basin & bronze water tongue
    brush.noStroke();
    brush.wash(PAL.sandPale, 225);
    brush.circle(-10, 0, 22, 0.08);
    brush.wash(PAL.verdDark, 210);
    brush.rect(-6, -8, 18, 16, "corner");
    brush.noWash();

    brush.set("map_pen", PAL.inkDark, 0.52);
    brush.circle(-10, 0, 22, 0.08);
    brush.circle(-10, 0, 15, 0.08);
    brush.rect(-6, -8, 18, 16, "corner");
    // Frothy water jet emerging from spout
    brush.set("rotring", PAL.skyFoam, 0.65);
    brush.line(12, -4, 28, -2);
    brush.line(12, 0, 32, 0);
    brush.line(12, 4, 28, 2);
    pop();
  }

  // 5. Perimeter Ashlar Coping Masonry Joints & Chisel Hatching
  brush.set("map_pen", PAL.inkMid, 0.4);
  for (let pos = 124; pos <= 1076; pos += 64) {
    // Top & bottom coping joints
    brush.line(pos, M_SCALE, pos, WALL_IN);
    brush.line(pos, H - WALL_IN, pos, H - M_SCALE);
    // Left & right coping joints
    brush.line(M_SCALE, pos, WALL_IN, pos);
    brush.line(W - WALL_IN, pos, W - M_SCALE, pos);
  }
  // Corner miter diagonals on outer stone coping
  brush.line(M_SCALE, M_SCALE, WALL_IN, WALL_IN);
  brush.line(W - M_SCALE, M_SCALE, W - WALL_IN, WALL_IN);
  brush.line(W - M_SCALE, H - M_SCALE, W - WALL_IN, H - WALL_IN);
  brush.line(M_SCALE, H - M_SCALE, WALL_IN, H - WALL_IN);
}

