// ============================================================================
// 6. MAPMAKER PRECISION LINEWORK, CONSTRUCTION GEOMETRY & SURVEY FRAME
// ============================================================================
function drawMapmakerSurveyOverlay() {
  // 1. Faint Geometric Construction Lines & Compass Arcs (2H Graphite & Slate Ink)
  brush.set("2H", PAL.graphite, 0.22);

  // Diagonal 45° construction axes across the entire courtyard plan
  brush.line(M_OUT, M_OUT, W - M_OUT, H - M_OUT);
  brush.line(W - M_OUT, M_OUT, M_OUT, H - M_OUT);

  // Circumscribed survey circles around the central octagon
  const rOctOut = OCT_A_OUT / Math.cos(Math.PI / 8);
  const rOctIn = OCT_A_IN / Math.cos(Math.PI / 8);
  for (let a = 0; a < 360; a += 45) {
    brush.arc(CX, CY, rOctOut, a - 8, a + 8);
    brush.arc(CX, CY, rOctIn, a + 14, a + 31);
    brush.arc(CX, CY, 310, a - 5, a + 5);
  }

  // Cardinal axis centerlines extending through the outer margin
  for (let d = 22; d < M_OUT; d += 8) {
    brush.line(CX, d, CX, d + 4);
    brush.line(CX, H - d - 4, CX, H - d);
    brush.line(d, CY, d + 4, CY);
    brush.line(W - d - 4, CY, W - d, CY);
  }

  // 2. Outer Mapmaker Double-Ruled Frame & Graduated Scale Bar (54..68px)
  brush.set("rotring", PAL.inkDark, 0.72);
  brush.noFill();
  brush.rect(M_OUT, M_OUT, W - 2 * M_OUT, H - 2 * M_OUT, "corner");

  brush.set("map_pen", PAL.inkDark, 0.5);
  brush.rect(M_SCALE, M_SCALE, W - 2 * M_SCALE, H - 2 * M_SCALE, "corner");
  brush.rect(WALL_IN, WALL_IN, W - 2 * WALL_IN, H - 2 * WALL_IN, "corner");

  // Fine scale graduations along all 4 outer margin bars (every 10px, major every 50px)
  brush.set("map_pen", PAL.inkMid, 0.34);
  for (let p = M_SCALE; p <= W - M_SCALE; p += 10) {
    const isMajor = (p - CX) % 50 === 0;
    const tickLen = isMajor ? M_SCALE - M_OUT : (M_SCALE - M_OUT) * 0.55;
    // Top & bottom scale ticks
    brush.line(p, M_SCALE - tickLen, p, M_SCALE);
    brush.line(p, H - M_SCALE, p, H - M_SCALE + tickLen);
    // Left & right scale ticks
    brush.line(M_SCALE - tickLen, p, M_SCALE, p);
    brush.line(W - M_SCALE, p, W - M_SCALE + tickLen, p);

    // Alternating dark bar fills in the outer scale band every 100px
    if ((p - 100) % 200 === 0 && p + 50 <= W - M_SCALE) {
      brush.noStroke();
      brush.wash(PAL.inkMid, 150);
      brush.rect(p, M_OUT, 50, 4.5, "corner");
      brush.rect(p, H - M_OUT - 4.5, 50, 4.5, "corner");
      brush.rect(M_OUT, p, 4.5, 50, "corner");
      brush.rect(W - M_OUT - 4.5, p, 4.5, 50, "corner");
      brush.noWash();
      brush.set("map_pen", PAL.inkMid, 0.34);
    }
  }

  // 3. Four Corner Mapmaker Registration Benchmarks & North Arrow Finial
  const corners = [
    [96, 96],
    [W - 96, 96],
    [W - 96, H - 96],
    [96, H - 96]
  ];
  for (const [bx, by] of corners) {
    brush.set("map_pen", PAL.inkDark, 0.45);
    brush.circle(bx, by, 14, 0.05);
    brush.circle(bx, by, 6, 0.05);
    brush.line(bx - 20, by, bx + 20, by);
    brush.line(bx, by - 20, bx, by + 20);
  }

  // Mapmaker North needle engraved at top center (CX, 36)
  brush.noStroke();
  brush.wash(PAL.inkDark, 210);
  drawShapePoly([[CX, 16], [CX - 6, 42], [CX, 36]]);
  brush.wash(PAL.lapisMid, 180);
  drawShapePoly([[CX, 16], [CX + 6, 42], [CX, 36]]);
  brush.noWash();
  brush.set("map_pen", PAL.inkDark, 0.45);
  drawShapePoly([[CX, 16], [CX - 6, 42], [CX, 36], [CX + 6, 42]]);
}

