// ============================================================================
// GEOMETRY & COLOR HELPERS
// ============================================================================

function drawPoly(pts, curvature = 0, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function rotPt(x, y, cx, cy, angDeg) {
  let c = cos(angDeg);
  let s = sin(angDeg);
  let dx = x - cx;
  let dy = y - cy;
  return [cx + dx * c - dy * s, cy + dx * s + dy * c];
}

function evalCatmullRom(p0, p1, p2, p3, t) {
  let t2 = t * t;
  let t3 = t2 * t;
  let x =
    0.5 *
    (2 * p1[0] +
      (-p0[0] + p2[0]) * t +
      (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
      (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
  let y =
    0.5 *
    (2 * p1[1] +
      (-p0[1] + p2[1]) * t +
      (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
      (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
  return [x, y];
}

// Determines which Bauhaus plane a point (x, y) lies over, for realistic shadow multiplication
function getGroundZone(x, y) {
  // Cadmium Red Circle: center (555, 425), r = 290
  if (dist(x, y, 555, 425) < 290) return "red";
  // Cobalt Square: [105, 625] to [475, 995]
  if (x >= 105 && x <= 475 && y >= 625 && y <= 995) return "blue";
  // Thick Black Bar: rotated rect around (280, 350), angle 52 deg, w=470, h=84
  let pBar = rotPt(x, y, 280, 350, -52);
  if (abs(pBar[0] - 280) <= 235 && abs(pBar[1] - 350) <= 42) return "black";
  // Chrome Yellow Diagonal Band: center (520, 440), angle -38 deg, w=1500, h=214
  let pYel = rotPt(x, y, 520, 440, 38);
  if (abs(pYel[1] - 440) <= 107) return "yellow";
  return "paper";
}

function getShadowColorForZone(zone) {
  if (zone === "yellow") return "#6e4904";
  if (zone === "red") return "#540e08";
  if (zone === "blue") return "#091836";
  if (zone === "black") return "#080808";
  return "#7a6f5d";
}

function getCoreShadowColorForZone(zone) {
  if (zone === "yellow") return "#3d2702";
  if (zone === "red") return "#2e0604";
  if (zone === "blue") return "#050d1f";
  if (zone === "black") return "#050505";
  return "#474035";
}

// ============================================================================
// 1. PAPER GROUND
// ============================================================================

function drawPaperGround() {
  brush.noField();
  brush.noStroke();

  // Warm ambient paper wash
  brush.wash("#efe5cf", 95);
  brush.rect(0, 0, 1200, 1200, "corner");
  brush.noWash();

  // Subtle archival fiber texture with 2H & spray
  brush.set("2H", "#dfd3ba", 0.35);
  for (let i = 0; i < 180; i++) {
    let x1 = random(0, 1200);
    let y1 = random(0, 1200);
    let len = random(60, 220);
    let ang = random(-8, 8);
    brush.line(x1, y1, x1 + cos(ang) * len, y1 + sin(ang) * len);
  }

  brush.set("spray", "#d8cab0", 0.45);
  for (let i = 0; i < 35; i++) {
    let x = random(60, 1140);
    let y = random(60, 1140);
    brush.line(x, y, x + random(-90, 90), y + random(-90, 90));
  }
}

// ============================================================================
// 2. BAUHAUS POSTER GROUND (FLAT PRIMARY MARKER SHAPES)
// ============================================================================

function makeRotatedRectPts(cx, cy, w, h, angDeg) {
  let hw = w / 2;
  let hh = h / 2;
  let corners = [
    [cx - hw, cy - hh],
    [cx + hw, cy - hh],
    [cx + hw, cy + hh],
    [cx - hw, cy + hh]
  ];
  return corners.map((pt) => rotPt(pt[0], pt[1], cx, cy, angDeg));
}

function drawBauhausGround() {
  // Clip the poster geometry to a crisp constructivist sheet border
  brush.clip([48, 48, 1152, 1152]);

  // --- A. CHROME YELLOW DIAGONAL BAND (-38 deg) ---
  let yellowPts = makeRotatedRectPts(520, 440, 1650, 214, -38);
  brush.noStroke();
  brush.wash("#f2b016", 245);
  drawPoly(yellowPts, 0, true);
  brush.noWash();

  // Marker fill streaks along the -38 deg band for genuine felt-marker richness
  brush.hatchStyle("marker", "#e59f0c", 1.15);
  brush.hatch(7, -38, { rand: 0.015 });
  drawPoly(yellowPts, 0, true);
  brush.noHatch();

  brush.hatchStyle("marker", "#f7be2b", 0.85);
  brush.hatch(13, -38, { rand: 0.01 });
  drawPoly(yellowPts, 0, true);
  brush.noHatch();

  // Crisp marker edge definition
  brush.set("marker", "#d99409", 0.9);
  drawPoly(yellowPts, 0, true);

  // --- B. COBALT BLUE SQUARE (lower-left asymmetric anchor) ---
  let bluePts = [
    [105, 625],
    [475, 625],
    [475, 995],
    [105, 995]
  ];
  brush.noStroke();
  brush.wash("#19438c", 248);
  drawPoly(bluePts, 0, true);
  brush.noWash();

  brush.hatchStyle("marker", "#143778", 1.2);
  brush.hatch(6.5, 0, { rand: 0.015 });
  drawPoly(bluePts, 0, true);
  brush.noHatch();

  brush.hatchStyle("marker", "#21509e", 0.85);
  brush.hatch(11, 90, { rand: 0.01 });
  drawPoly(bluePts, 0, true);
  brush.noHatch();

  brush.set("marker", "#102e66", 0.95);
  drawPoly(bluePts, 0, true);

  // --- C. CADMIUM RED CIRCLE (behind the rotary dial) ---
  let rCx = 555;
  let rCy = 425;
  let rRad = 290;
  let redCirclePts = [];
  for (let a = 0; a < 360; a += 4) {
    redCirclePts.push([rCx + cos(a) * rRad, rCy + sin(a) * rRad]);
