function buildCordSpine() {
  // Control points for the looping coiled cord:
  // Emerges from phone grommet (548, 742), sweeps across yellow band & cobalt square,
  // loops up over red circle & yellow band, then crosses over itself and exits bottom-left
  let ctrl = [
    [575, 710],
    [548, 742], // Grommet exit
    [492, 815],
    [395, 885],
    [275, 890], // Across Cobalt Square
    [182, 810],
    [168, 665], // Left upward sweep
    [235, 540],
    [358, 512], // Top of loop over Yellow Band & near Red Circle
    [452, 592],
    [458, 740], // Crossing back over lower loop
    [388, 918],
    [255, 1055],
    [125, 1185],
    [45, 1265]
  ];

  let spine = [];
  let stepsPerSeg = 26;
  for (let i = 0; i < ctrl.length - 3; i++) {
    for (let s = 0; s < stepsPerSeg; s++) {
      let t = s / stepsPerSeg;
      let pt = evalCatmullRom(ctrl[i], ctrl[i + 1], ctrl[i + 2], ctrl[i + 3], t);
      spine.push(pt);
    }
  }
  return spine;
}

function buildHelicalCoils(spine, numCoils, coilRadius) {
  // Compute arc-length parameterization of spine
  let cumLen = [0];
  for (let i = 1; i < spine.length; i++) {
    let d = dist(spine[i - 1][0], spine[i - 1][1], spine[i][0], spine[i][1]);
    cumLen.push(cumLen[i - 1] + d);
  }
  let totalLen = cumLen[cumLen.length - 1];

  function sampleSpineAt(sLen) {
    sLen = constrain(sLen, 0, totalLen - 0.001);
    let idx = 0;
    while (idx < cumLen.length - 2 && cumLen[idx + 1] < sLen) idx++;
    let segLen = cumLen[idx + 1] - cumLen[idx];
    let f = segLen > 0 ? (sLen - cumLen[idx]) / segLen : 0;
    let x = lerp(spine[idx][0], spine[idx + 1][0], f);
    let y = lerp(spine[idx][1], spine[idx + 1][1], f);

    let i0 = max(0, idx - 1);
    let i1 = min(spine.length - 1, idx + 2);
    let dx = spine[i1][0] - spine[i0][0];
    let dy = spine[i1][1] - spine[i0][1];
    let mag = sqrt(dx * dx + dy * dy) || 1;
    let tx = dx / mag;
    let ty = dy / mag;
    let nx = -ty;
    let ny = tx;
    return { x, y, tx, ty, nx, ny, u: sLen / totalLen };
  }

  let coils = [];
  let samplesPerCoil = 20;
  let totalSamples = numCoils * samplesPerCoil;

  for (let c = 0; c < numCoils; c++) {
    let backPts = [];
    let frontPts = [];
    let uMid = (c + 0.5) / numCoils;
    let centerSample = sampleSpineAt(uMid * totalLen);

    // Elevate the crossover bridge of the cord (around u = 0.52..0.78)
    let bridgeLift = exp(-pow((uMid - 0.64) / 0.14, 2));
    let shDx = 20 + bridgeLift * 18;
    let shDy = 26 + bridgeLift * 22;

    for (let k = 0; k <= samplesPerCoil; k++) {
      let stepIdx = c * samplesPerCoil + k;
      let sLen = (stepIdx / totalSamples) * totalLen;
      let sp = sampleSpineAt(sLen);
      let theta = (k / samplesPerCoil) * 360; // 0..360 deg per coil

      // Taper slightly right at the grommet start
      let rScale = c < 3 ? map(c + k / samplesPerCoil, 0, 3, 0.62, 1.0) : 1.0;
      let r = coilRadius * rScale;

      let across = cos(theta) * r;
      let along = sin(theta) * (r * 0.44);
      let px = sp.x + sp.nx * across + sp.tx * along;
      let py = sp.y + sp.ny * across + sp.ty * along;

      if (k <= samplesPerCoil / 2) {
        backPts.push([px, py]);
      }
      if (k >= samplesPerCoil / 2) {
        frontPts.push([px, py]);
      }
    }

    coils.push({
      index: c,
      u: uMid,
      cx: centerSample.x,
      cy: centerSample.y,
      tx: centerSample.tx,
      ty: centerSample.ty,
      nx: centerSample.nx,
      ny: centerSample.ny,
      backPts,
      frontPts,
      shDx,
      shDy,
      bridgeLift
    });
  }

  return coils;
}

function drawCordShadows(coils) {
  // Crisp helical cast shadow across the Bauhaus planes
  for (let i = 0; i < coils.length; i++) {
    let c = coils[i];
    let sx = c.cx + c.shDx;
    let sy = c.cy + c.shDy;
    let zone = getGroundZone(sx, sy);
    let penumbraCol = getShadowColorForZone(zone);
    let coreCol = getCoreShadowColorForZone(zone);

    let shBack = c.backPts.map((p) => [p[0] + c.shDx, p[1] + c.shDy]);
    let shFront = c.frontPts.map((p) => [p[0] + c.shDx, p[1] + c.shDy]);

    // Soft penumbra outer stroke
    brush.set("marker", penumbraCol, 2.3);
    drawPoly(shBack, 0.3, false);
    drawPoly(shFront, 0.3, false);

    // Crisp dark core shadow of each individual coil loop
    brush.set("marker", coreCol, 1.45);
    drawPoly(shBack, 0.3, false);
    drawPoly(shFront, 0.3, false);

    // Fine graphite edge along the shadow boundary
    brush.set("2B", "#141210", 0.65);
    drawPoly(shFront, 0.3, false);
  }
}

