function drawRotaryDial(cx, cy) {
  // --- A. OUTER CHROME BEZEL RING (R = 224 to 244) ---
  // Base metallic midtone
  for (let r = 224; r <= 244; r += 2) {
    brush.set("marker", "#888e96", 0.95);
    brush.circle(cx, cy, r, 0.004);
  }

  // High-contrast chrome reflection bands around the bezel
  for (let r = 225; r <= 243; r += 1.8) {
    // Deep black horizon reflections in the chrome
    brush.set("marker", "#141619", 0.85);
    brush.arc(cx, cy, r, 140, 182);
    brush.arc(cx, cy, r, 278, 325);
    brush.arc(cx, cy, r, 48, 86);

    // Warm reflection of cadmium red & yellow planes on left/bottom bezel
    brush.set("HB", "#b56a52", 0.55);
    brush.arc(cx, cy, r, 105, 142);
    brush.set("HB", "#cfa65b", 0.55);
    brush.arc(cx, cy, r, 85, 112);

    // Gleaming pure white studio highlights on chrome bezel
    brush.set("rotring", "#ffffff", 0.65);
    brush.arc(cx, cy, r, 190, 268);
    brush.arc(cx, cy, r, 332, 360);
    brush.arc(cx, cy, r, 0, 38);
  }

  // Crisp inner & outer bezel seams
  brush.set("rotring", "#0b0c0e", 0.85);
  brush.circle(cx, cy, 244, 0.004);
  brush.circle(cx, cy, 223, 0.004);

  // --- B. ROTATING FINGER-WHEEL DISK (R = 222) ---
  let wheelPts = [];
  for (let a = 0; a < 360; a += 4) {
    wheelPts.push([cx + cos(a) * 222, cy + sin(a) * 222]);
  }
  brush.noStroke();
  brush.wash("#121317", 252);
  drawPoly(wheelPts, 0, true);
  brush.noWash();

  // Dense graphite & marker texture on the glossy dark wheel
  brush.hatchStyle("marker", "#0c0d10", 1.25);
  brush.hatch(5.5, -42, { rand: 0.01 });
  drawPoly(wheelPts, 0, true);
  brush.noHatch();

  brush.hatchStyle("2B", "#1f2229", 0.6);
  brush.hatch(4, 48, { rand: 0.02 });
  drawPoly(wheelPts, 0, true);
  brush.noHatch();

  // Glossy window reflection bands sweeping diagonally across the wheel face
  for (let offset = -85; offset <= -25; offset += 2.2) {
    let halfChord = sqrt(max(0, 218 * 218 - offset * offset));
    let p1 = rotPt(cx - halfChord, cy + offset, cx, cy, -38);
    let p2 = rotPt(cx + halfChord, cy + offset, cx, cy, -38);
    let intensity = 1 - abs(offset + 55) / 32;
    let col = intensity > 0.55 ? "#9ca3ad" : "#4d525c";
    brush.set("2H", col, 0.55);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  for (let offset = 42; offset <= 76; offset += 2.5) {
    let halfChord = sqrt(max(0, 218 * 218 - offset * offset));
    let p1 = rotPt(cx - halfChord, cy + offset, cx, cy, -38);
    let p2 = rotPt(cx + halfChord, cy + offset, cx, cy, -38);
    brush.set("HB", "#454952", 0.5);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Fine concentric rotary scratch marks from decades of spinning
  for (let r = 85; r <= 212; r += 6) {
    brush.set("2H", "#383c44", 0.3);
    brush.arc(cx, cy, r, random(0, 120), random(180, 340));
  }

  // Subtle aged cream/brass inner guide ring under wheel edge
  brush.set("rotring", "#8c826d", 0.45);
  brush.circle(cx, cy, 214, 0.005);

  // --- C. THE 10 WORN FINGER-HOLES & RECESSED NUMBER PLATE ---
  // Standard rotary dial angles: 1 at upper-right (-55 deg), counter-clockwise to 0 at lower-right (+38 deg)
  let digits = [1, 2, 3, 4, 5, 6, 7, 8, 9, 0];
  let holeAngles = [305, 275, 245, 215, 185, 155, 125, 95, 65, 36];
  let holeRingR = 148;
  let holeR = 33;

  for (let i = 0; i < 10; i++) {
    let ang = holeAngles[i];
    let hx = cx + cos(ang) * holeRingR;
    let hy = cy + sin(ang) * holeRingR;
    drawWornFingerHole(hx, hy, holeR, digits[i], ang);
  }

  // --- D. STEPPED CHROME & BAKELITE CENTER HUB CAP (R = 74) ---
  // Drop shadow of center cap onto wheel
  for (let r = 73; r <= 82; r += 2) {
    brush.set("charcoal", "#070709", 0.85);
    brush.arc(cx + 5, cy + 6, r, -30, 135);
  }

  // Stepped chrome hub ring (R = 58 to 74)
  for (let r = 58; r <= 74; r += 1.8) {
    brush.set("marker", "#7e848d", 0.85);
    brush.circle(cx, cy, r, 0.005);
    brush.set("marker", "#15171b", 0.75);
    brush.arc(cx, cy, r, 130, 185);
    brush.arc(cx, cy, r, 285, 340);
    brush.set("rotring", "#ffffff", 0.6);
    brush.arc(cx, cy, r, 195, 265);
    brush.arc(cx, cy, r, 10, 62);
  }

  // Glossy black Bakelite center dome (R = 57)
  let domePts = [];
  for (let a = 0; a < 360; a += 6) {
    domePts.push([cx + cos(a) * 57, cy + sin(a) * 57]);
  }
  brush.noStroke();
  brush.wash("#0b0c0e", 252);
  drawPoly(domePts, 0, true);
  brush.noWash();

  brush.hatchStyle("marker", "#08090b", 1.1);
  brush.hatch(4, -38, { rand: 0.01 });
  drawPoly(domePts, 0, true);
  brush.noHatch();

  // Convex specular highlight on the black center dome
  for (let r = 34; r <= 49; r += 2) {
    brush.set("2H", "#9ca2ad", 0.55);
    brush.arc(cx, cy, r, 196, 262);
  }
  for (let r = 38; r <= 45; r += 1.8) {
    brush.set("rotring", "#f7f4eb", 0.6);
    brush.arc(cx, cy, r, 206, 248);
  }

  // Vintage inner brass/ivory instruction ring inside center hub
  brush.set("rotring", "#a89b80", 0.55);
  brush.circle(cx, cy, 48, 0.005);
  brush.set("rotring", "#060708", 0.8);
  brush.circle(cx, cy, 58, 0.005);
  brush.circle(cx, cy, 74, 0.005);

  // --- E. GLEAMING CHROME FINGER-STOP (Lower-Right of Dial) ---
  drawChromeFingerStop(cx, cy);
}

function drawWornFingerHole(hx, hy, r, digit, dialAng) {
  // 1. Recessed aged enamel number plate inside hole
  let holePts = [];
  for (let a = 0; a < 360; a += 8) {
    holePts.push([hx + cos(a) * (r - 2), hy + sin(a) * (r - 2)]);
  }
  brush.noStroke();
  brush.wash("#dfd4be", 248);
  drawPoly(holePts, 0, true);
  brush.noWash();

  // Subtle graphite wear & fingertip smudge inside the enamel well
  brush.hatchStyle("2H", "#bfb299", 0.5);
  brush.hatch(3.5, dialAng, { rand: 0.04 });
  drawPoly(holePts, 0, true);
  brush.noHatch();

  brush.set("HB", "#a3967e", 0.45);
  brush.circle(hx + 2, hy + 2, r * 0.45, 0.08);

  // 2. Vintage geometric numeral rendered on the recessed enamel plate
  drawRotaryNumeral(hx + 1, hy + 1, digit);

  // 3. Sharp crescent cast shadow inside the upper-left wall of the finger-hole
  // (cast by the thickness of the rotating wheel rim)
  for (let sr = r - 8; sr <= r - 1; sr += 1.4) {
    brush.set("charcoal", "#171614", 0.8);
    brush.arc(hx + 3, hy + 4, sr, 150, 315);
  }
  brush.set("2B", "#4a443b", 0.65);
  brush.arc(hx + 4, hy + 5, r - 9, 160, 305);

  // 4. Worn, scuffed rim of the finger-hole (chipped black lacquer revealing worn brass/steel & graphite)
  brush.set("marker", "#0b0c0e", 1.1);
  brush.circle(hx, hy, r, 0.01);

  // Worn bevel ring where thousands of fingertips rubbed the edge
  brush.set("HB", "#7d776b", 0.65);
  brush.circle(hx, hy, r + 1.8, 0.02);

  // Bright scuffed metal & specular rim on the lower-right bevel of the hole (facing the upper-left light)
  brush.set("2H", "#c9c1b0", 0.6);
  brush.arc(hx, hy, r + 1.2, -35, 125);
  brush.set("rotring", "#f7f3e8", 0.5);
  brush.arc(hx, hy, r + 0.8, 5, 85);

  // Upper-left outer lip highlight catching light before dropping into the hole
  brush.set("2H", "#8f949e", 0.45);
  brush.arc(hx, hy, r + 3.2, 195, 265);
}

function drawRotaryNumeral(x, y, d) {
  // Crisp vintage mechanical numerals inside the finger-holes (with slight wear)
  brush.set("rotring", "#1d1b18", 0.78);
  let s = 11;
  if (d === 1) {
    brush.line(x - 3, y - s + 3, x + 1, y - s);
    brush.line(x + 1, y - s, x + 1, y + s);
    brush.line(x - 5, y + s, x + 6, y + s);
  } else if (d === 2) {
    brush.arc(x, y - 4, 7, 190, 45);
    brush.line(x + 5, y + 1, x - 7, y + s);
    brush.line(x - 7, y + s, x + 7, y + s);
  } else if (d === 3) {
    brush.arc(x, y - 5, 6.5, 195, 90);
    brush.arc(x, y + 5, 7, 270, 165);
  } else if (d === 4) {
    brush.line(x + 3, y - s, x - 8, y + 4);
    brush.line(x - 8, y + 4, x + 8, y + 4);
    brush.line(x + 3, y - s, x + 3, y + s);
  } else if (d === 5) {
    brush.line(x + 6, y - s, x - 6, y - s);
    brush.line(x - 6, y - s, x - 6, y - 1);
    brush.arc(x, y + 4, 7.5, 230, 155);
  } else if (d === 6) {
    brush.arc(x, y + 4, 7.2, 0, 360);
    brush.line(x - 7, y + 4, x + 3, y - s);
  } else if (d === 7) {
    brush.line(x - 7, y - s, x + 7, y - s);
    brush.line(x + 7, y - s, x - 2, y + s);
  } else if (d === 8) {
    brush.circle(x, y - 5, 5.8, 0.02);
    brush.circle(x, y + 5.5, 6.8, 0.02);
  } else if (d === 9) {
    brush.arc(x, y - 4, 7.2, 0, 360);
    brush.line(x + 7, y - 4, x - 2, y + s);
  } else if (d === 0) {
    brush.arc(x, y - 3, 6.8, 180, 360);
    brush.arc(x, y + 3, 6.8, 0, 180);
    brush.line(x - 6.8, y - 3, x - 6.8, y + 3);
    brush.line(x + 6.8, y - 3, x + 6.8, y + 3);
  }
}

function drawChromeFingerStop(cx, cy) {
  // Positioned at lower-right (~12 deg to 26 deg), anchored to outer bezel and tapering inward
  let aTip = 14;
  let aTop = 7;
  let aBot = 27;

  // 1. Sharp cast shadow of the finger-stop onto the glossy finger-wheel and '0' hole
  let shStopPts = [
    [cx + cos(aTip + 6) * 76 + 8, cy + sin(aTip + 6) * 76 + 14],
    [cx + cos(aTop + 5) * 238 + 10, cy + sin(aTop + 5) * 238 + 16],
    [cx + cos(aBot + 8) * 242 + 12, cy + sin(aBot + 8) * 242 + 18],
    [cx + cos(aTip + 14) * 82 + 8, cy + sin(aTip + 14) * 82 + 14]
  ];
  brush.noStroke();
  brush.wash("#050507", 215);
  drawPoly(shStopPts, 0.08, true);
  brush.noWash();

  // 2. Gleaming Chrome Bracket Geometry
  let pInTop = [cx + cos(aTip - 3.5) * 76, cy + sin(aTip - 3.5) * 76];
  let pInBot = [cx + cos(aTip + 4.5) * 78, cy + sin(aTip + 4.5) * 78];
  let pMidTop = [cx + cos(aTop + 1) * 165, cy + sin(aTop + 1) * 165];
  let pMidBot = [cx + cos(aBot - 3) * 170, cy + sin(aBot - 3) * 170];
  let pOutTop = [cx + cos(aTop - 2) * 244, cy + sin(aTop - 2) * 244];
  let pOutBot = [cx + cos(aBot + 2) * 244, cy + sin(aBot + 2) * 244];

  let stopPts = [pInTop, pMidTop, pOutTop, pOutBot, pMidBot, pInBot];

  // Base metallic chrome wash
  brush.noStroke();
  brush.wash("#d4dae2", 248);
  drawPoly(stopPts, 0.05, true);
  brush.noWash();

  // Dark horizon reflection band down the center of the chrome finger-stop
  let darkBandPts = [
    [lerp(pInTop[0], pInBot[0], 0.35), lerp(pInTop[1], pInBot[1], 0.35)],
    [lerp(pOutTop[0], pOutBot[0], 0.32), lerp(pOutTop[1], pOutBot[1], 0.32)],
    [lerp(pOutTop[0], pOutBot[0], 0.68), lerp(pOutTop[1], pOutBot[1], 0.68)],
    [lerp(pInTop[0], pInBot[0], 0.72), lerp(pInTop[1], pInBot[1], 0.72)]
  ];
  brush.noStroke();
  brush.wash("#1b1e24", 230);
  drawPoly(darkBandPts, 0.02, true);
  brush.noWash();

  // Blazing white specular reflection along the upper bevel of the chrome stop
  let specBandPts = [
    pInTop,
    pMidTop,
    pOutTop,
    [lerp(pOutTop[0], pOutBot[0], 0.28), lerp(pOutTop[1], pOutBot[1], 0.28)],
    [lerp(pInTop[0], pInBot[0], 0.3), lerp(pInTop[1], pInBot[1], 0.3)]
  ];
  brush.noStroke();
  brush.wash("#ffffff", 245);
  drawPoly(specBandPts, 0.02, true);
  brush.noWash();

  // Fine metallic graphite & rotring detailing
  brush.set("rotring", "#ffffff", 0.85);
  brush.line(pInTop[0], pInTop[1], pOutTop[0], pOutTop[1]);
  brush.line(pInTop[0], pInTop[1], pInBot[0], pInBot[1]);

  brush.set("rotring", "#0c0d10", 0.75);
  brush.line(pInBot[0], pInBot[1], pOutBot[0], pOutBot[1]);
  brush.line(pOutTop[0], pOutTop[1], pOutBot[0], pOutBot[1]);

  // Two small chrome rivets on the outer bracket mount
  let riv1 = [
    lerp(pOutTop[0], pOutBot[0], 0.26) - 8,
    lerp(pOutTop[1], pOutBot[1], 0.26) - 2
  ];
  let riv2 = [
    lerp(pOutTop[0], pOutBot[0], 0.74) - 8,
    lerp(pOutTop[1], pOutBot[1], 0.74) - 2
  ];
  for (let rv of [riv1, riv2]) {
    brush.set("rotring", "#14161a", 0.65);
    brush.circle(rv[0], rv[1], 4.5, 0.02);
    brush.set("rotring", "#ffffff", 0.6);
    brush.arc(rv[0], rv[1], 3.2, 180, 330);
  }
}

