function drawCordGrommet(gx, gy) {
  // Tapered rubber strain-relief grommet exiting the lower-left flank of the Bakelite casing
  let grommetPts = [
    [gx + 8, gy - 28],
    [gx + 34, gy - 8],
    [gx + 4, gy + 28],
    [gx - 22, gy + 8]
  ];
  brush.noStroke();
  brush.wash("#0c0c0e", 250);
  drawPoly(grommetPts, 0.2, true);
  brush.noWash();

  // Molded rings on the grommet with specular ticks
  for (let k = 0; k < 3; k++) {
    let f = k * 8;
    brush.set("marker", "#141519", 1.1);
    brush.line(gx - 8 - f * 0.6, gy - 14 + f * 0.8, gx + 16 - f * 0.6, gy + 6 + f * 0.8);
    brush.set("rotring", "#d8d4ca", 0.55);
    brush.line(gx - 6 - f * 0.6, gy - 12 + f * 0.8, gx + 2 - f * 0.6, gy - 5 + f * 0.8);
  }
}

function drawCoiledCord(coils) {
  // Note: coils 0..42 are the lower pass; coils 43..77 cross OVER the lower pass around coil 12..18.
  // Drawing in index order 0..77 naturally renders the upper crossing coils on top of the lower pass!

  for (let i = 0; i < coils.length; i++) {
    let c = coils[i];

    // If this coil is part of the elevated crossover bridge (coils 44..56),
    // first cast a local contact shadow onto the lower cord section underneath
    if (i >= 44 && i <= 56) {
      let bridgeSh = c.frontPts.map((p) => [p[0] + 8, p[1] + 10]);
      brush.set("charcoal", "#050506", 1.8);
      drawPoly(bridgeSh, 0.3, false);
    }

    // 1. Back half-turn of the helical coil (recessed in shadow)
    brush.set("marker", "#0b0b0d", 2.05);
    drawPoly(c.backPts, 0.35, false);

    brush.set("2B", "#1c1e24", 0.85);
    drawPoly(c.backPts, 0.35, false);

    // Subtle secondary rim reflection on the back turn
    let backSub = c.backPts.slice(2, 8);
    if (backSub.length >= 2) {
      brush.set("HB", "#4b4f59", 0.45);
      drawPoly(backSub, 0.3, false);
    }

    // 2. Dark core occlusion in the hollow center of the helix
    brush.set("marker", "#060608", 1.4);
    brush.line(
      c.cx - c.tx * 7 - c.nx * 5,
      c.cy - c.ty * 7 - c.ny * 5,
      c.cx + c.tx * 7 + c.nx * 5,
      c.cy + c.ty * 7 + c.ny * 5
    );

    // 3. Front half-turn of the helical coil (thick glossy black rubber/neoprene tube)
    // Dark outline shadow separating overlapping coils
    let sepPts = c.frontPts.map((p) => [p[0] + 1.5, p[1] + 2]);
    brush.set("rotring", "#040405", 1.15);
    drawPoly(sepPts, 0.35, false);

    // Main cylindrical body of the front coil turn
    brush.set("marker", "#0f1014", 2.25);
    drawPoly(c.frontPts, 0.35, false);

    // Midtone graphite modeling along the upper-left curve of the tube
    let midPts = c.frontPts.slice(1, 9).map((p) => [p[0] - 1.5, p[1] - 1.8]);
    if (midPts.length >= 2) {
      brush.set("2B", "#3d424d", 1.05);
      drawPoly(midPts, 0.35, false);

      brush.set("HB", "#767d8a", 0.7);
      drawPoly(midPts, 0.35, false);
    }

    // 4. Warm reflected bounce-light on the underside of each coil from the Bauhaus ground below
    let zone = getGroundZone(c.cx, c.cy);
    let bounceCol =
      zone === "yellow"
        ? "#785a16"
        : zone === "red"
        ? "#6e221a"
        : zone === "blue"
        ? "#223b6e"
        : "#595246";
    let bouncePts = c.frontPts.slice(4, 10).map((p) => [p[0] + 2.2, p[1] + 2.5]);
    if (bouncePts.length >= 2) {
      brush.set("HB", bounceCol, 0.55);
      drawPoly(bouncePts, 0.3, false);
    }

    // 5. Razor-sharp gleaming specular highlight on every individual coil turn
    let specPts = c.frontPts.slice(2, 7).map((p) => [p[0] - 2.2, p[1] - 2.5]);
    if (specPts.length >= 2) {
      brush.set("2H", "#d4d8e0", 0.65);
      drawPoly(specPts, 0.35, false);

      let hotPts = c.frontPts.slice(3, 6).map((p) => [p[0] - 2.4, p[1] - 2.7]);
      if (hotPts.length >= 2) {
        brush.set("rotring", "#fbf9f2", 0.55);
        drawPoly(hotPts, 0.35, false);
      }
    }
  }
}

