// =========================================================================
// GEOMETRY & DRAWING HELPERS
// =========================================================================

function polyShape(pts, curv = 0, closed = true) {
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function ellipsePts(cx, cy, rx, ry, n = 36, jitter = 0, startAng = 0, endAng = 360) {
  let pts = [];
  let steps = closed ? n : n;
  for (let i = 0; i < n; i++) {
    let a = map(i, 0, n, startAng, endAng);
    let rMod = 1 + (jitter > 0 ? (noise(cx * 0.01 + cos(a) * 1.5, cy * 0.01 + sin(a) * 1.5) - 0.5) * jitter : 0);
    pts.push([cx + cos(a) * rx * rMod, cy + sin(a) * ry * rMod]);
  }
  return pts;
}

function drawVectorText(str, x, y, h, spacing, col, weight = 0.38) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("fine_liner", col, weight);
  let cx = x;
  let w = h * 0.68;
  for (let i = 0; i < str.length; i++) {
    let ch = str[i].toUpperCase();
    if (ch === ' ') {
      cx += w * 0.65 + spacing;
      continue;
    }
    let strokes = GLYPHS[ch];
    if (strokes) {
      for (let s of strokes) {
        for (let k = 0; k < s.length - 1; k++) {
          brush.line(
            cx + s[k][0] * w, y + s[k][1] * h,
            cx + s[k + 1][0] * w, y + s[k + 1][1] * h
          );
        }
      }
    }
    cx += (ch === 'I' || ch === '.' ? w * 0.55 : w) + spacing;
  }
}

function shoreCoord(t) {
  // Diagonal shoreline from left edge (36, 650) to top edge (700, 36)
  let bx = lerp(36, 690, t);
  let by = lerp(650, 36, t);
  let wave = sin(t * 540 - 20) * 28 + sin(t * 1260 + 40) * 11 + cos(t * 240) * 18;
  // Normal vector pointing SE (onto the beach)
  let nx = 0.715;
  let ny = 0.699;
  return [bx + nx * wave, by + ny * wave];
}

// =========================================================================
// 1. CHEERFUL SAND WASHES & GRANULAR TEXTURE
// =========================================================================

function drawSandWashesAndTexture() {
  brush.noStroke();
  brush.noHatch();

  // Broad flat buff wash across entire map interior
  brush.fill("#f5e0b7", 115);
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.35, 0.2);
  polyShape([[40, 40], [1160, 40], [1160, 1160], [40, 1160]], 0);

  // Warm apricot wash across the sunlit dry beach (diagonal swath)
  brush.fill("#f0b87a", 95);
  brush.fillBleed(0.08, "out");
  polyShape([
    [320, 620], [720, 180], [1155, 45], [1155, 860], [640, 1155], [120, 960]
  ], 0.2);

  // Deeper rich apricot-gold wash in upper-right and lower-left dunes
  brush.fill("#e59d56", 85);
  brush.fillBleed(0.07, "out");
  polyShape([
    [760, 110], [1155, 45], [1155, 580], [920, 520], [790, 330]
  ], 0.25);

  polyShape([
    [45, 840], [340, 740], [580, 940], [460, 1155], [45, 1155]
  ], 0.25);

  // Sunlit pale cream-buff ridge around central sandcastle plateau
  brush.fill("#faeccd", 120);
  brush.fillBleed(0.06, "out");
  polyShape(ellipsePts(665, 575, 355, 255, 32, 0.12), 0.2);

  // Damp golden-taupe sand band parallel to the tide edge
  let dampBand = [];
  for (let i = 0; i <= 30; i++) {
    let t = i / 30;
    let p = shoreCoord(t);
    dampBand.push([p[0] - 12, p[1] - 12]);
  }
  for (let i = 30; i >= 0; i--) {
    let t = i / 30;
    let p = shoreCoord(t);
    let offset = 78 + sin(t * 720) * 18;
    dampBand.push([p[0] + offset * 0.71, p[1] + offset * 0.71]);
  }
  brush.fill("#c59361", 110);
  brush.fillBleed(0.04, "in");
  polyShape(dampBand, 0.15);

  // Darker wet-glaze lip right next to the foam edge
  let wetLip = [];
  for (let i = 0; i <= 35; i++) {
    let t = i / 35;
    let p = shoreCoord(t);
    wetLip.push([p[0] - 4, p[1] - 4]);
  }
  for (let i = 35; i >= 0; i--) {
    let t = i / 35;
    let p = shoreCoord(t);
    let offset = 28 + cos(t * 900) * 7;
    wetLip.push([p[0] + offset * 0.71, p[1] + offset * 0.71]);
  }
  brush.fill("#9c6c3e", 130);
  brush.fillBleed(0.02, "in");
  polyShape(wetLip, 0.1);
  brush.noFill();

  // Subtle wind-blown sand ripples in the dry apricot areas
  for (let r = 0; r < 28; r++) {
    let rx = random(120, 1100);
    let ry = random(120, 1100);
    // Keep away from deep water in top-left and central castle
    if (rx + ry < 780) continue;
    if (dist(rx, ry, 665, 565) < 280) continue;
    let len = random(55, 130);
    let pts = [];
    for (let s = 0; s <= 6; s++) {
      let u = s / 6;
      pts.push([
        rx + u * len * 0.75 + sin(u * 180) * 4,
        ry - u * len * 0.62 + cos(u * 180) * 4
      ]);
    }
    brush.set("2H", "#c48445", 0.35);
    brush.spline(pts, 0.4);
    let ptsHi = pts.map(p => [p[0] - 1.5, p[1] - 1.5]);
    brush.set("cpencil", "#fff6e0", 0.4);
    brush.spline(ptsHi, 0.4);
  }

  // Fine granular sand stippling and tiny pebbles/shell specks across beach
  let stippleColors = ["#b5793e", "#875427", "#fff7e5", "#d99652", "#633a18"];
  for (let c = 0; c < stippleColors.length; c++) {
    brush.set("sand_stipple", stippleColors[c], 0.45);
    for (let i = 0; i < 65; i++) {
      let sx = random(55, 1145);
      let sy = random(55, 1145);
      if (sx + sy < 680) continue;
      brush.line(sx, sy, sx + random(4, 14), sy + random(-4, 4));
    }
  }

  // Tiny scattered beach pebbles and micro-shells with crisp drop shadows
  for (let i = 0; i < 75; i++) {
    let px = random(70, 1130);
    let py = random(70, 1130);
    if (px + py < 660) continue;
    if (dist(px, py, 665, 565) < 250) continue;
    if (dist(px, py, 1035, 995) < 125) continue;
    let pr = random(1.8, 4.5);
    // Tiny crisp cast shadow to SE
    brush.noStroke();
    brush.wash("#3b2312", 185);
    polyShape(ellipsePts(px + pr * 0.75, py + pr * 0.55, pr, pr * 0.7, 8), 0);
    // Pebble body
    let pCol = random(["#f7eed7", "#d99b66", "#8c583a", "#e8c39e", "#54473e"]);
    brush.wash(pCol, 230);
    polyShape(ellipsePts(px, py, pr, pr * 0.72, 8), 0);
    brush.noWash();
    brush.set("fine_liner", "#2b190d", 0.22);
    brush.circle(px, py, pr * 0.85, 0.15);
  }
}

// =========================================================================
// 2. FRILLED BAND OF TURQUOISE & FOAM WHITE TIDE EDGE
// =========================================================================

function drawTideEdge() {
  brush.noStroke();
  brush.noHatch();

  // 1) Cast shadow of the water lip onto the wet sand (+5px SE)
  let shadowPoly = [[38, 38], [695, 38]];
  for (let i = 45; i >= 0; i--) {
    let p = shoreCoord(i / 45);
    shadowPoly.push([p[0] + 6, p[1] + 5]);
  }
  brush.wash("#4a3a28", 135);
  polyShape(shadowPoly, 0.1);
  brush.noWash();

  // 2) Translucent aquamarine shallow water sheet
  let shallowPoly = [[38, 38], [690, 38]];
  for (let i = 45; i >= 0; i--) {
    let p = shoreCoord(i / 45);
    shallowPoly.push(p);
  }
  brush.fill("#66dfd6", 150);
  brush.fillBleed(0.03, "in");
  brush.fillTexture(0.3, 0.2);
  polyShape(shallowPoly, 0.15);

  // 3) Mid-depth vibrant turquoise band
  let midPoly = [[38, 38], [550, 38]];
  for (let i = 36; i >= 0; i--) {
    let t = i / 36;
    let p = shoreCoord(t);
    midPoly.push([
      lerp(38, p[0], 0.76) + sin(t * 700) * 10,
      lerp(38, p[1], 0.76) + cos(t * 700) * 10
    ]);
  }
  brush.fill("#119da4", 165);
  brush.fillBleed(0.05, "in");
  polyShape(midPoly, 0.2);

  // 4) Deep rich teal-emerald corner water (high contrast)
  let deepPoly = [[38, 38], [390, 38]];
  for (let i = 28; i >= 0; i--) {
    let t = i / 28;
    let p = shoreCoord(t);
    deepPoly.push([
      lerp(38, p[0], 0.52) + sin(t * 500) * 8,
      lerp(38, p[1], 0.52) + cos(t * 500) * 8
    ]);
  }
  brush.fill("#054e57", 190);
  brush.fillBleed(0.04, "in");
  polyShape(deepPoly, 0.2);

  // Ultra-deep corner accent
  brush.fill("#022c33", 170);
  polyShape([[38, 38], [230, 38], [165, 165], [38, 240]], 0.2);
  brush.noFill();

  // 5) Water caustics and surface ripple highlights
  for (let w = 0; w < 22; w++) {
    let f = map(w, 0, 21, 0.15, 0.9);
    let wavePts = [];
    for (let s = 0; s <= 18; s++) {
      let t = s / 18;
      let p = shoreCoord(t);
      let wx = lerp(38, p[0], f) + sin(t * 900 + w * 45) * 6;
      let wy = lerp(38, p[1], f) + cos(t * 900 + w * 45) * 6;
      if (wx > 42 && wy > 42) wavePts.push([wx, wy]);
    }
    if (wavePts.length > 2) {
      brush.set("fine_liner", w % 2 === 0 ? "#b8f7f2" : "#07636b", 0.35);
      brush.spline(wavePts, 0.45);
    }
  }

  // 6) Frilled band of foam white along the shoreline edge
  let foamRibbon = [];
  for (let i = 0; i <= 60; i++) {
    let t = i / 60;
    let p = shoreCoord(t);
    let frill = sin(t * 2400) * 5 + cos(t * 3800) * 3;
    foamRibbon.push([p[0] + frill * 0.7, p[1] + frill * 0.7]);
  }
  for (let i = 60; i >= 0; i--) {
    let t = i / 60;
    let p = shoreCoord(t);
    let thickness = 24 + sin(t * 1100) * 11 + cos(t * 2100) * 7;
    foamRibbon.push([p[0] - thickness * 0.72, p[1] - thickness * 0.72]);
  }
  brush.noStroke();
  brush.wash("#ffffff", 240);
  polyShape(foamRibbon, 0.15);

  // Secondary trailing lace foam band inside the turquoise shallows
  let innerFoam = [];
  for (let i = 0; i <= 50; i++) {
    let t = i / 50;
    let p = shoreCoord(t);
    let d = 58 + sin(t * 680) * 14;
    innerFoam.push([p[0] - d * 0.72, p[1] - d * 0.72]);
  }
  for (let i = 50; i >= 0; i--) {
    let t = i / 50;
    let p = shoreCoord(t);
    let d = 70 + sin(t * 680) * 14 + cos(t * 1600) * 6;
    innerFoam.push([p[0] - d * 0.72, p[1] - d * 0.72]);
  }
  brush.wash("#e8fcfb", 205);
  polyShape(innerFoam, 0.2);
  brush.noWash();

  // Cellular foam bubbles & crisp fine-pen water-edge definition
  for (let i = 0; i <= 110; i++) {
    let t = i / 110;
    let p = shoreCoord(t);
    // Turquoise-tinted bubble holes inside the white foam
    let bx = p[0] - random(4, 22) * 0.72;
    let by = p[1] - random(4, 22) * 0.72;
    if (bx > 42 && by > 42) {
      brush.noStroke();
      brush.wash("#4cc9c2", 180);
      polyShape(ellipsePts(bx, by, random(1.8, 5.2), random(1.5, 4.2), 8), 0);
      brush.noWash();
    }
    // White lacy scallops along the leading edge
    brush.set("fine_liner", "#ffffff", 0.55);
    brush.circle(p[0] + random(-3, 3), p[1] + random(-3, 3), random(2.5, 7), 0.2);
  }

  // Crisp fine-pen dark outline along the leading water meniscus
  let meniscusPts = [];
  for (let i = 0; i <= 70; i++) {
    let p = shoreCoord(i / 70);
    meniscusPts.push([p[0] + 2, p[1] + 2]);
  }
  brush.set("fine_liner", "#1e474a", 0.38);
  brush.spline(meniscusPts, 0.35);
}

