  // Lighter turquoise ring where water laps the inner and outer sandy shallows
  let waterMid = ellipsePts(cx + 6, cy + 5, 224, 155, 52, 0.08);
  brush.fill("#1ea3a8", 160);
  polyShape(waterMid, 0.15);

  // Deep pool crescents in the moat
  let deepPoolSE = ellipsePts(cx + 15, cy + 12, 205, 140, 48, 0.07);
  brush.fill("#053b42", 180);
  polyShape(deepPoolSE, 0.15);
  brush.noFill();

  // 5) Central Sandcastle Island rising out of the moat water
  // Submerged sandy shelf under the water edge
  let islandShelf = ellipsePts(cx, cy - 2, 172, 120, 48, 0.09);
  brush.noStroke();
  brush.wash("#429991", 170);
  polyShape(islandShelf, 0.15);

  // Wet dark sand shoreline of the central island
  let islandWetRim = ellipsePts(cx, cy - 4, 160, 110, 48, 0.09);
