// =========================================================================
// 4. WINDING DOTTED TRAIL OF FOOTPRINTS BETWEEN LANDMARKS
// =========================================================================

function drawFootprintTrail() {
  // Control points winding across the beach between all landmarks:
  // Tide Edge -> Stranded Crab -> Red Spade -> Moat Bridge -> Flip-Flop -> Wrapper
  let waypoints = [
    [225, 515],
    [295, 425],
    [355, 330], // Near Stranded Crab (405, 360)
    [455, 295],
    [475, 415],
    [355, 565],
    [235, 685],
    [225, 815], // Around Red Spade (295, 765)
    [355, 865],
    [495, 785],
    [575, 685], // Near Moat Bridge (595, 655)
    [665, 795],
    [715, 935], // Near Half-Buried Flip-Flop (785, 965)
    [855, 915],
    [935, 765],
    [915, 585],
    [945, 435], // Approaching Crumpled Wrapper (980, 350)
    [1045, 265]
  ];

  // Sample smooth Catmull-Rom-like path along waypoints
  let samples = [];
  for (let i = 0; i < waypoints.length - 1; i++) {
    let p0 = waypoints[max(0, i - 1)];
    let p1 = waypoints[i];
    let p2 = waypoints[i + 1];
    let p3 = waypoints[min(waypoints.length - 1, i + 2)];
    let segSteps = 16;
    for (let s = 0; s < segSteps; s++) {
      let t = s / segSteps;
      let t2 = t * t;
      let t3 = t2 * t;
      let x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t +
        (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
        (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      let y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t +
        (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
        (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
      samples.push([x, y]);
    }
  }

  // Filter by arc-length distance so footprints & dashes are evenly spaced
  let arcPts = [samples[0]];
  let accum = 0;
  for (let i = 1; i < samples.length; i++) {
    let d = dist(samples[i][0], samples[i][1], samples[i - 1][0], samples[i - 1][1]);
    accum += d;
    if (accum >= 11) {
      arcPts.push(samples[i]);
      accum = 0;
    }
  }

  // 1) Pictorial tourist map dotted-and-dashed red-sepia cartographic line
  for (let i = 0; i < arcPts.length - 1; i++) {
    let p1 = arcPts[i];
    let p2 = arcPts[i + 1];
    if (i % 2 === 0) {
      brush.set("fine_liner", "#8c2318", 0.48);
      brush.line(p1[0], p1[1], lerp(p1[0], p2[0], 0.65), lerp(p1[1], p2[1], 0.65));
    } else {
      brush.set("fine_liner", "#8c2318", 0.55);
      brush.circle(p1[0], p1[1], 1.2, 0.05);
    }
  }

  // 2) Hyperreal alternating left/right bare footprints pressed into the sand
  let stepIdx = 0;
  for (let i = 2; i < arcPts.length - 2; i += 3) {
    let p = arcPts[i];
    let pNext = arcPts[i + 1];
    let ang = atan2(pNext[1] - p[1], pNext[0] - p[0]);
    let isLeft = (stepIdx % 2 === 0);
    let sideOffset = isLeft ? -11 : 11;
    let fx = p[0] + cos(ang + 90) * sideOffset;
    let fy = p[1] + sin(ang + 90) * sideOffset;

    drawSingleFootprint(fx, fy, ang + (isLeft ? -6 : 6), isLeft);
    stepIdx++;
  }
}

function drawSingleFootprint(x, y, ang, isLeft) {
  let ca = cos(ang);
  let sa = sin(ang);
  let rot = (lx, ly) => [x + lx * ca - ly * sa, y + lx * sa + ly * ca];

  // Raised bright sand rim pushed up on the sunlit SE edge
  brush.noStroke();
  brush.wash("#fff3d6", 200);
  let rimPts = [
    rot(-6, -3), rot(5, -4.5), rot(8, 0), rot(5, 4.5), rot(-6, 3.5)
  ];
  polyShape(rimPts.map(pt => [pt[0] + 1.8, pt[1] + 1.5]), 0.3);

  // Deep shadow inside the depressed sole and heel
  brush.wash("#7d4e24", 215);
  let archSign = isLeft ? 1 : -1;
  let solePts = [
    rot(-6.5, -2.2),
    rot(-1.5, -2.0 + archSign * 0.9),
    rot(4.5, -3.4),
    rot(6.5, -1.2),
    rot(6.2, 2.5),
    rot(3.5, 3.6),
    rot(-1.5, 2.2 + archSign * 0.6),
    rot(-6.5, 2.2)
  ];
  polyShape(solePts, 0.35);

  // Darker core shadow along the NW inner lip of the footprint
  brush.wash("#42250c", 210);
  let corePts = [
    rot(-6.2, -2.0), rot(4.2, -3.1), rot(5.5, -0.5), rot(-5.5, 0.2)
  ];
  polyShape(corePts, 0.25);

  // Five tiny toe impressions ahead of the ball of the foot
  let toeOffsets = isLeft
    ? [[8.5, 2.6, 1.5], [9.0, 1.0, 1.2], [8.8, -0.4, 1.1], [8.2, -1.7, 1.0], [7.3, -2.9, 0.9]]
    : [[8.5, -2.6, 1.5], [9.0, -1.0, 1.2], [8.8, 0.4, 1.1], [8.2, 1.7, 1.0], [7.3, 2.9, 0.9]];

  for (let t of toeOffsets) {
    let tp = rot(t[0], t[1]);
    brush.wash("#4a2a0e", 215);
    polyShape(ellipsePts(tp[0], tp[1], t[2], t[2] * 0.8, 6), 0);
  }
  brush.noWash();

  // Crisp fine-pen contour around footprint depression
  brush.set("fine_liner", "#361e0a", 0.24);
  polyShape(solePts, 0.35, true);
}

// =========================================================================
// 5. LANDMARK: THE HYPERREAL SANDCASTLE
// =========================================================================

function drawSandcastle(cx, cy) {
  // 1) Long dramatic high-contrast cast shadows falling to the SE (bottom-right)
  brush.noStroke();
  brush.fill("#362212", 165);
  brush.fillBleed(0.03, "in");
  // Main castle mass shadow across SE island & moat water
  let mainShadow = [
    [cx + 35, cy - 85],
    [cx + 155, cy - 35],
    [cx + 255, cy + 35],
    [cx + 235, cy + 115],
    [cx + 105, cy + 135],
    [cx - 35, cy + 75]
  ];
  polyShape(mainShadow, 0.2);
  brush.noFill();

  // Slump fans of dry apricot sand around the castle foundations
  let slumpCenters = [
    [cx - 95, cy + 45, 52, 34],
    [cx + 95, cy + 42, 54, 35],
    [cx - 110, cy - 35, 45, 30],
    [cx + 105, cy - 38, 45, 30],
    [cx, cy + 68, 62, 36]
  ];
  for (let sc of slumpCenters) {
    brush.noStroke();
    brush.fill("#e8b274", 150);
    brush.fillBleed(0.04, "out");
    polyShape(ellipsePts(sc[0], sc[1], sc[2], sc[3], 20, 0.15), 0.2);
    brush.noFill();
  }

  // 2) BACK CURTAIN WALLS (connecting Back-Left, Keep, and Back-Right towers)
  drawSandWall(cx - 88, cy - 52, cx + 88, cy - 52, 52, 22);
  // Left & Right side curtain walls
  drawSandWall(cx - 92, cy - 48, cx - 104, cy + 28, 48, 22);
  drawSandWall(cx + 92, cy - 48, cx + 104, cy + 28, 48, 22);

  // 3) BACK CORNER TOWERS (Bucket-molded tapered cylinders)
  drawSandTower(cx - 88, cy - 52, 36, 31, 74, true, false);
  drawSandTower(cx + 88, cy - 52, 36, 31, 74, true, false);

  // 4) INNER STEPPED CITADEL WARD & DRIP-SAND BUTTRESSES
  drawSandTower(cx, cy - 22, 68, 58, 68, true, false);
  // Drip-sand stalagmite buttresses on flanks of the inner ward
  drawDripSandButtress(cx - 58, cy - 18, 48);
  drawDripSandButtress(cx + 58, cy - 18, 48);

  // 5) CENTRAL GRAND KEEP TOWER (Tallest bucket-molded turret + spiral stair + flag)
  drawSandTower(cx, cy - 68, 44, 36, 108, true, true);

  // Carved spiral staircase winding around the central keep
  let stairPts = [];
  for (let i = 0; i <= 14; i++) {
    let f = i / 14;
    let ang = map(f, 0, 1, 165, 25);
    let r = lerp(43, 38, f);
    let sx = cx + cos(ang) * r;
    let sy = (cy - 68 - f * 78) + sin(ang) * r * 0.65;
    stairPts.push([sx, sy]);
    // Tiny carved step riser & dark shadow
    brush.noStroke();
    brush.wash("#331d0c", 220);
    polyShape([[sx - 3, sy], [sx + 4, sy], [sx + 4, sy + 5], [sx - 3, sy + 5]], 0);
    brush.wash("#fff0cf", 220);
    polyShape([[sx - 4, sy - 1.5], [sx + 4, sy - 1.5], [sx + 3, sy + 1], [sx - 3, sy + 1]], 0);
    brush.noWash();
  }
  brush.set("fine_liner", "#241408", 0.35);
  brush.spline(stairPts, 0.3);

  // 6) FRONT CURTAIN WALLS & ARCHED GATEHOUSE
  drawSandWall(cx - 102, cy + 32, cx - 32, cy + 46, 46, 20);
  drawSandWall(cx + 32, cy + 46, cx + 102, cy + 32, 46, 20);

  // Front-Left & Front-Right Bastion Towers
  drawSandTower(cx - 102, cy + 34, 38, 32, 68, true, false);
  drawSandTower(cx + 102, cy + 34, 38, 32, 68, true, false);

  // Central Gatehouse Bastion with deep shadowed archway
  drawGatehouseAndBridge(cx, cy + 48);

  // 7) Flagpole & Crimson-and-White Pennant on top of the Central Keep
  let flagBaseX = cx + 2;
  let flagBaseY = cy - 178;
  // Flag cast shadow onto upper battlements
  brush.set("fine_liner", "#29170a", 0.5);
  brush.line(flagBaseX, flagBaseY, flagBaseX + 46, flagBaseY + 32);
  // Driftwood twig pole
  brush.set("fine_liner", "#4a2c14", 0.75);
  brush.line(flagBaseX, flagBaseY + 4, flagBaseX - 3, flagBaseY - 66);
  brush.set("fine_liner", "#deb887", 0.35);
  brush.line(flagBaseX - 1, flagBaseY + 4, flagBaseX - 4, flagBaseY - 66);

  // Fluttering Red & White striped paper pennant
  let flagPoly = [
    [flagBaseX - 3, flagBaseY - 64],
    [flagBaseX + 32, flagBaseY - 56],
    [flagBaseX + 54, flagBaseY - 49],
    [flagBaseX + 28, flagBaseY - 40],
    [flagBaseX - 2, flagBaseY - 38]
  ];
  brush.noStroke();
  brush.fill("#d91e18", 230);
  brush.fillBleed(0.01, "in");
  polyShape(flagPoly, 0.15);
  brush.noFill();
  // White stripe down the middle of the pennant
  brush.wash("#ffffff", 235);
  polyShape([
    [flagBaseX - 2.5, flagBaseY - 55],
    [flagBaseX + 42, flagBaseY - 50],
    [flagBaseX + 38, flagBaseY - 45],
    [flagBaseX - 2, flagBaseY - 46]
  ], 0.1);
  brush.noWash();
  brush.set("fine_liner", "#2b0907", 0.35);
  polyShape(flagPoly, 0.15, true);
}

function drawSandTower(cx, cy, rBot, rTop, h, hasCrenellations, hasBucketRings) {
  let aspect = 0.66;
  let topY = cy - h;

  // Cast shadow on adjacent surfaces (to SE)
  brush.noStroke();
  brush.wash("#3b2310", 165);
  let castPts = [
    [cx - rBot * 0.3, cy + rBot * aspect * 0.4],
    [cx + rBot * 0.9, cy - rBot * aspect * 0.3],
    [cx + rBot * 0.9 + h * 0.72, cy + h * 0.46],
    [cx + h * 0.45, cy + rBot * aspect + h * 0.48]
  ];
  polyShape(castPts, 0.2);

  // Cylinder full body base (midtone warm apricot-sand)
  let bodyPts = [];
  for (let a = 0; a <= 180; a += 10) {
    bodyPts.push([cx + cos(a) * rBot, cy + sin(a) * rBot * aspect]);
  }
  for (let a = 180; a >= 0; a -= 10) {
    bodyPts.push([cx + cos(a) * rTop, topY + sin(a) * rTop * aspect]);
  }
  brush.fill("#dfaa6e", 225);
  brush.fillBleed(0.02, "in");
  polyShape(bodyPts, 0.05);
  brush.noFill();

  // Sunlit NW face (angles 105 to 180)
  let litPts = [];
  for (let a = 100; a <= 180; a += 10) {
    litPts.push([cx + cos(a) * rBot, cy + sin(a) * rBot * aspect]);
  }
  for (let a = 180; a >= 100; a -= 10) {
    litPts.push([cx + cos(a) * rTop, topY + sin(a) * rTop * aspect]);
  }
  brush.wash("#fce8c3", 215);
  polyShape(litPts, 0.05);

  // Deep Core Shadow on SE face (angles 0 to 85)
  let shadPts = [];
  for (let a = 0; a <= 88; a += 10) {
    shadPts.push([cx + cos(a) * rBot, cy + sin(a) * rBot * aspect]);
  }
  for (let a = 88; a >= 0; a -= 10) {
    shadPts.push([cx + cos(a) * rTop, topY + sin(a) * rTop * aspect]);
  }
  brush.wash("#6b421f", 215);
  polyShape(shadPts, 0.05);
  brush.noWash();

  // Fine cross-hatching on the shadowed half of the cylinder
  brush.hatchStyle("fine_liner", "#381f0b", 0.26);
  brush.hatch(3.5, 82, { rand: 0.08 });
  brush.noStroke();
  polyShape(shadPts, 0.05);
  brush.hatch(4.5, 25, { rand: 0.1 });
  polyShape(shadPts, 0.05);
  brush.noHatch();

  // Bucket-molded horizontal ridge rings if central keep
  if (hasBucketRings) {
    for (let rf of [0.35, 0.68]) {
      let ry = lerp(cy, topY, rf);
      let rr = lerp(rBot, rTop, rf) + 1.8;
      let ringPts = [];
      for (let a = 5; a <= 175; a += 10) {
        ringPts.push([cx + cos(a) * rr, ry + sin(a) * rr * aspect]);
      }
      brush.set("fine_liner", "#fff5dc", 0.55);
      brush.spline(ringPts, 0.35);
      let ringShad = ringPts.map(p => [p[0], p[1] + 2.2]);
      brush.set("fine_liner", "#452710", 0.42);
      brush.spline(ringShad, 0.35);
    }
  }

  // Top flat ellipse of tower
  let topEllipse = ellipsePts(cx, topY, rTop, rTop * aspect, 28, 0.04);
  brush.noStroke();
  brush.wash("#f7dfB2", 235);
  polyShape(topEllipse, 0.1);
  // Recessed inner platform shadow
  brush.wash("#8a582c", 190);
  polyShape(ellipsePts(cx + 2, topY + 1.5, rTop * 0.76, rTop * aspect * 0.74, 24, 0.04), 0.1);
  brush.wash("#e6b67e", 215);
  polyShape(ellipsePts(cx - 2, topY - 1, rTop * 0.72, rTop * aspect * 0.7, 24, 0.04), 0.1);
  brush.noWash();

  // Carved dark medieval window slits on tower wall
  let winAngles = [55, 125];
  for (let wa of winAngles) {
    let wx = cx + cos(wa) * lerp(rBot, rTop, 0.52);
    let wy = lerp(cy, topY, 0.52) + sin(wa) * lerp(rBot, rTop, 0.52) * aspect;
    let ww = 4.2;
    let wh = 12;
    brush.noStroke();
    brush.wash("#1f1006", 245);
    polyShape([
      [wx - ww, wy + wh * 0.5],
      [wx - ww, wy - wh * 0.25],
      [wx, wy - wh * 0.55],
      [wx + ww, wy - wh * 0.25],
      [wx + ww, wy + wh * 0.5]
    ], 0.1);
    // Sunlit sill highlight
    brush.set("fine_liner", "#fff4d9", 0.45);
    brush.line(wx - ww, wy + wh * 0.5, wx + ww + 1, wy + wh * 0.5);
  }

  // Crown of Crenellations (Merlons) around the turret rim
  if (hasCrenellations) {
    let numMerlons = rTop > 45 ? 12 : 8;
    let mHeight = rTop > 45 ? 9 : 8;
    // Draw back merlons first (180 to 360), then front merlons (0 to 180)
    let order = [];
    for (let i = 0; i < numMerlons; i++) {
      let a = (i * 360) / numMerlons;
      order.push({ a: a, ySort: sin(a) });
    }
    order.sort((m1, m2) => m1.ySort - m2.ySort);

    for (let m of order) {
      let a1 = m.a - (180 / numMerlons) * 0.58;
      let a2 = m.a + (180 / numMerlons) * 0.58;
      let x1 = cx + cos(a1) * rTop;
      let y1 = topY + sin(a1) * rTop * aspect;
      let x2 = cx + cos(a2) * rTop;
      let y2 = topY + sin(a2) * rTop * aspect;

      let mCol = cos(m.a - 135) > 0 ? "#fadeb0" : "#7d4e25";
      brush.noStroke();
      brush.wash(mCol, 240);
      polyShape([[x1, y1], [x2, y2], [x2, y2 - mHeight], [x1, y1 - mHeight]], 0);
      brush.wash("#fff2d4", 240);
      polyShape([[x1, y1 - mHeight], [x2, y2 - mHeight], [x2 - 2, y2 - mHeight - 2], [x1 - 2, y1 - mHeight - 2]], 0);
      brush.noWash();
      brush.set("fine_liner", "#291608", 0.28);
      polyShape([[x1, y1], [x2, y2], [x2, y2 - mHeight], [x1, y1 - mHeight]], 0, true);
    }
  }

  // Granular sand stipple & fine ink outline on the tower
  brush.set("sand_stipple", "#593516", 0.35);
  brush.line(cx + rBot * 0.2, cy - h * 0.2, cx + rTop * 0.3, topY + h * 0.2);
  brush.set("sand_stipple", "#fff7e3", 0.35);
  brush.line(cx - rBot * 0.4, cy - h * 0.2, cx - rTop * 0.4, topY + h * 0.2);

  brush.set("fine_liner", "#241408", 0.36);
  polyShape(bodyPts, 0.05, true);
}

function drawSandWall(x1, y1, x2, y2, h, thick) {
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang) * (thick * 0.5);
  let ny = cos(ang) * (thick * 0.5) * 0.68;

  // Front/visible vertical wall face
  let frontFace = [
    [x1 + nx, y1 + ny],
    [x2 + nx, y2 + ny],
    [x2 + nx, y2 + ny - h],
    [x1 + nx, y1 + ny - h]
  ];
  let isSunlit = (ny < 0.2 && nx < 0.2);
  brush.noStroke();
  brush.fill(isSunlit ? "#ecc086" : "#8c592b", 225);
  brush.fillBleed(0.02, "in");
  polyShape(frontFace, 0);
  brush.noFill();

  if (!isSunlit) {
    brush.hatchStyle("fine_liner", "#42260e", 0.25);
    brush.hatch(4, 75, { rand: 0.08 });
    brush.noStroke();
    polyShape(frontFace, 0);
    brush.noHatch();
  }

  // Top wall walkway
  let topFace = [
    [x1 - nx, y1 - ny - h],
    [x2 - nx, y2 - ny - h],
    [x2 + nx, y2 + ny - h],
    [x1 + nx, y1 + ny - h]
  ];
  brush.noStroke();
  brush.wash("#fae5be", 235);
  polyShape(topFace, 0);

  // Merlons along the wall top
  let steps = 4;
  for (let i = 0; i < steps; i++) {
    let tA = (i + 0.15) / steps;
    let tB = (i + 0.72) / steps;
    let mx1 = lerp(x1 + nx, x2 + nx, tA);
    let my1 = lerp(y1 + ny - h, y2 + ny - h, tA);
    let mx2 = lerp(x1 + nx, x2 + nx, tB);
    let my2 = lerp(y1 + ny - h, y2 + ny - h, tB);
    brush.wash("#f7dcb0", 240);
    polyShape([[mx1, my1], [mx2, my2], [mx2, my2 - 7], [mx1, my1 - 7]], 0);
    brush.set("fine_liner", "#2b1709", 0.28);
    polyShape([[mx1, my1], [mx2, my2], [mx2, my2 - 7], [mx1, my1 - 7]], 0, true);
    brush.noStroke();
  }
  brush.noWash();

  brush.set("fine_liner", "#241408", 0.34);
  polyShape(frontFace, 0, true);
  polyShape(topFace, 0, true);
}

function drawDripSandButtress(bx, by, h) {
  // Globular stalagmite towers formed by dribbling wet sand from fingertips
  for (let col = -1; col <= 1; col++) {
    let cx = bx + col * 8;
    let colH = h - abs(col) * 9;
    let blobs = 7;
    for (let b = 0; b < blobs; b++) {
      let f = b / blobs;
      let y = by - f * colH;
      let r = lerp(7.5, 3.8, f);
      brush.noStroke();
      brush.wash("#7a4b21", 215);
      polyShape(ellipsePts(cx + 1.5, y + 1, r, r * 0.75, 8, 0.2), 0.2);
      brush.wash("#f7deb4", 225);
      polyShape(ellipsePts(cx - 1, y - 0.5, r * 0.85, r * 0.68, 8, 0.2), 0.2);
      brush.noWash();
      brush.set("fine_liner", "#2e1909", 0.22);
      brush.circle(cx, y, r * 0.8, 0.2);
    }
  }
}

function drawGatehouseAndBridge(gx, gy) {
  let w = 32;
  let h = 52;
  // Gatehouse block
  let front = [[gx - w, gy], [gx + w, gy], [gx + w, gy - h], [gx - w, gy - h]];
  brush.noStroke();
  brush.fill("#d49b60", 235);
  brush.fillBleed(0.02, "in");
  polyShape(front, 0);
  brush.noFill();

  // Right shadow side of gatehouse
  let side = [[gx + w, gy], [gx + w + 12, gy - 10], [gx + w + 12, gy - h - 10], [gx + w, gy - h]];
  brush.wash("#6b401b", 235);
  polyShape(side, 0);

  // Top roof of gatehouse
  let roof = [[gx - w, gy - h], [gx + w, gy - h], [gx + w + 12, gy - h - 10], [gx - w + 12, gy - h - 10]];
  brush.wash("#fae5bf", 240);
  polyShape(roof, 0);

  // Deep dark arched portal opening
  let archPts = [];
  let aw = 15;
  let ah = 28;
  archPts.push([gx - aw, gy]);
  for (let a = 180; a <= 360; a += 15) {
    archPts.push([gx + cos(a) * aw, (gy - ah + aw * 0.8) + sin(a) * aw * 0.85]);
  }
  archPts.push([gx + aw, gy]);
  brush.wash("#1a0d04", 250);
  polyShape(archPts, 0.1);

  // Sunlit inner right reveal inside the arch
  brush.wash("#9c6737", 215);
  polyShape([[gx + aw - 4, gy], [gx + aw, gy], [gx + aw, gy - 16], [gx + aw - 4, gy - 14]], 0);
  brush.noWash();

  brush.set("fine_liner", "#241408", 0.38);
  polyShape(front, 0, true);
  polyShape(archPts, 0.1, true);

  // Driftwood & Seashell Bridge spanning the moat in front of the gatehouse
  let bx1 = gx - 16;
  let by1 = gy + 2;
  let bx2 = gx - 58;
  let by2 = gy + 92;
  // Bridge cast shadow on the moat water
  brush.noStroke();
  brush.wash("#032226", 195);
  polyShape([[bx1 + 6, by1 + 4], [bx1 + 36, by1 + 4], [bx2 + 36, by2 + 4], [bx2 + 6, by2 + 4]], 0.1);

  // Two driftwood side rails + tiny cross-twigs
  for (let s = 0; s <= 10; s++) {
    let f = s / 10;
    let tx = lerp(bx1, bx2, f);
    let ty = lerp(by1, by2, f) - sin(f * 180) * 6;
    brush.wash(s % 2 === 0 ? "#c79e6d" : "#a37849", 240);
    polyShape([[tx, ty], [tx + 28, ty + 3], [tx + 26, ty + 8], [tx - 2, ty + 5]], 0);
    brush.set("fine_liner", "#2b1708", 0.28);
    polyShape([[tx, ty], [tx + 28, ty + 3], [tx + 26, ty + 8], [tx - 2, ty + 5]], 0, true);
    brush.noStroke();
  }
  brush.noWash();
}

// =========================================================================
// 6. LANDMARK: STRANDED SHORE CRAB (Carcinus / Atlantic Rock Crab)
// =========================================================================

function drawStrandedCrab(cx, cy) {
  let ang = -28; // Facing up-right toward the castle
  let ca = cos(ang);
  let sa = sin(ang);
  let rot = (lx, ly) => [cx + lx * ca - ly * sa, cy + lx * sa + ly * ca];

  // 1) Crisp dark cast shadow of carapace, claws, and 8 legs on damp sand
  brush.noStroke();
  brush.wash("#331d0c", 195);
  polyShape(ellipsePts(cx + 8, cy + 7, 36, 26, 20, 0.1), 0.2);

  // 2) Eight jointed walking legs (4 on each side)
  let legConfigs = [
    [-1, -12, -26, -24, -46, -18, -58, -6],
    [-1, -4, -30, -6, -52, 2, -64, 14],
    [-1, 6, -28, 12, -48, 22, -56, 36],
    [-1, 15, -22, 26, -36, 38, -40, 48],
    [1, -12, 26, -24, 46, -18, 58, -6],
    [1, -4, 30, -6, 52, 2, 64, 14],
    [1, 6, 28, 12, 48, 22, 56, 36],
    [1, 15, 22, 26, 36, 38, 40, 48]
  ];

  for (let lc of legConfigs) {
    let p0 = rot(lc[0] * 18, lc[1]);
    let p1 = rot(lc[2], lc[3]);
    let p2 = rot(lc[4], lc[5]);
    let p3 = rot(lc[6], lc[7]);

    // Leg shadow on sand
    brush.set("fine_liner", "#2e1909", 0.9);
    brush.line(p0[0] + 5, p0[1] + 5, p1[0] + 5, p1[1] + 5);
    brush.line(p1[0] + 5, p1[1] + 5, p2[0] + 5, p2[1] + 5);
    brush.line(p2[0] + 5, p2[1] + 5, p3[0] + 4, p3[1] + 4);

    // Jointed segments (merus, carpus, propodus, dactylus)
    drawCrabSegment(p0, p1, 4.2, "#c84620", "#6e1b09");
    drawCrabSegment(p1, p2, 3.2, "#df5b2c", "#7a1f0c");
    drawCrabSegment(p2, p3, 2.0, "#f08548", "#471105");
  }

  // 3) Two muscular Chelipeds (Pincers / Claws) raised in front
  for (let side of [-1, 1]) {
    let shoulder = rot(side * 16, -16);
    let elbow = rot(side * 34, -34);
    let wrist = rot(side * 28, -54);
    let clawTip = rot(side * 12, -66);
    let pincerTip = rot(side * 18, -62);

    // Claw cast shadow
    brush.noStroke();
    brush.wash("#2e1808", 195);
    polyShape([
      [wrist[0] + 6, wrist[1] + 6],
      [clawTip[0] + 6, clawTip[1] + 6],
      [pincerTip[0] + 6, pincerTip[1] + 6]
    ], 0.2);
    brush.noWash();

    drawCrabSegment(shoulder, elbow, 5.5, "#b83818", "#5c1306");
    drawCrabSegment(elbow, wrist, 6.2, "#d94e24", "#6e1908");

    // Swollen Chela (main claw hand)
    let chelaPts = [
      rot(side * 32, -48),
      rot(side * 35, -58),
      clawTip,
      rot(side * 20, -56),
      rot(side * 22, -46)
    ];
    brush.noStroke();
    brush.fill("#e0481e", 235);
    brush.fillBleed(0.02, "in");
    polyShape(chelaPts, 0.25);
    brush.noFill();

    // Pale cream/ivory inner pincer fingers with dark tips
    let fingerPts = [rot(side * 22, -52), pincerTip, rot(side * 15, -55)];
    brush.wash("#fae8cc", 240);
    polyShape(fingerPts, 0.15);
    brush.noWash();

    // Specular wet glint on claw
    brush.set("fine_liner", "#ffffff", 0.45);
    brush.line(wrist[0], wrist[1], lerp(wrist[0], clawTip[0], 0.6), lerp(wrist[1], clawTip[1], 0.6));
    brush.set("fine_liner", "#2b0a03", 0.35);
    polyShape(chelaPts, 0.25, true);
  }

  // 4) Fan-shaped Serrated Carapace (Shell)
  let shellPts = [
    rot(0, -24),
    rot(10, -23),
    rot(20, -19),
    rot(29, -12),
    rot(33, -3),
    rot(28, 9),
    rot(18, 19),
    rot(9, 23),
    rot(-9, 23),
    rot(-18, 19),
    rot(-28, 9),
    rot(-33, -3),
    rot(-29, -12),
    rot(-20, -19),
    rot(-10, -23)
  ];

  // Rich terracotta-crimson base wash
  brush.noStroke();
  brush.fill("#ba2d14", 235);
  brush.fillBleed(0.03, "in");
  polyShape(shellPts, 0.2);

  // Darker mottled dorsal center & SE shadow on carapace
  brush.fill("#5e1105", 190);
  polyShape([
    rot(-6, -16), rot(18, -14), rot(28, 2), rot(15, 19), rot(-8, 18), rot(-12, 2)
  ], 0.25);

  // Bright warm orange-apricot highlight on NW carapace shoulder
  brush.fill("#f77e3e", 185);
  polyShape([
    rot(-28, -6), rot(-12, -20), rot(4, -18), rot(-8, -2), rot(-22, 6)
  ], 0.25);
  brush.noFill();

  // Anatomical gastric & cardiac grooves + wet specular shell highlights
  brush.set("fine_liner", "#330802", 0.38);
  polyShape(shellPts, 0.2, true);
  brush.spline([rot(-11, -10), rot(-6, 0), rot(0, 4), rot(6, 0), rot(11, -10)], 0.4);
  brush.spline([rot(-8, 6), rot(0, 12), rot(8, 6)], 0.4);

  // Tiny glossy white highlights & foam bubbles at mouthparts
  brush.set("fine_liner", "#ffffff", 0.5);
  brush.spline([rot(-22, -10), rot(-12, -16), rot(-2, -17)], 0.4);
  for (let b = 0; b < 6; b++) {
    let bp = rot(random(-7, 7), -24 + random(-3, 2));
    brush.circle(bp[0], bp[1], random(1.2, 2.5), 0.1);
  }

  // Two tiny dark stalked eyes
  for (let side of [-1, 1]) {
    let ep = rot(side * 6, -24.5);
    brush.noStroke();
    brush.wash("#140402", 250);
    polyShape(ellipsePts(ep[0], ep[1], 2.2, 2.2, 8), 0);
    brush.noWash();
    brush.set("fine_liner", "#ffffff", 0.4);
    brush.circle(ep[0] - 0.6, ep[1] - 0.6, 0.6, 0);
  }
}

function drawCrabSegment(pA, pB, thick, colLit, colShad) {
  let ang = atan2(pB[1] - pA[1], pB[0] - pA[0]);
  let nx = -sin(ang) * thick * 0.5;
  let ny = cos(ang) * thick * 0.5;
  let midX = (pA[0] + pB[0]) * 0.5;
  let midY = (pA[1] + pB[1]) * 0.5;

  let segPts = [
    pA,
    [midX + nx, midY + ny],
    pB,
    [midX - nx, midY - ny]
  ];
  brush.noStroke();
  brush.wash(colLit, 235);
  polyShape(segPts, 0.25);
  brush.wash(colShad, 195);
  polyShape([pA, pB, [midX - nx, midY - ny]], 0.2);
  brush.noWash();
  brush.set("fine_liner", "#2e0802", 0.28);
  polyShape(segPts, 0.25, true);
}

// =========================================================================
// 7. LANDMARK: RED PLASTIC SPADE
// =========================================================================

function drawRedSpade(cx, cy) {
  // Oriented obliquely with scoop blade at top-right (dug into sand mound) and D-handle at bottom-left
  let ang = -36;
  let ca = cos(ang);
  let sa = sin(ang);
  let rot = (lx, ly) => [cx + lx * ca - ly * sa, cy + lx * sa + ly * ca];

  // 1) Excavated sand mound where the blade is resting
  let moundX = cx + 68 * ca;
  let moundY = cy + 68 * sa;
  brush.noStroke();
  brush.fill("#cfa068", 190);
  brush.fillBleed(0.04, "out");
  polyShape(ellipsePts(moundX + 10, moundY + 4, 52, 36, 20, 0.15), 0.2);
  brush.noFill();

  // 2) Crisp dark cast shadow of handle, shaft, and scoop blade on the sand
  brush.noStroke();
  brush.wash("#2e1a0b", 210);
  let shadowScoop = [
    rot(25, -28), rot(92, -32), rot(106, 0), rot(92, 32), rot(25, 28)
  ].map(p => [p[0] + 10, p[1] + 9]);
