function drawBuriedFlipFlop(cx, cy) {
  // Angled toward top-right (35 deg); toe end is buried under a drift of sand
  let ang = -38;
  let ca = cos(ang);
  let sa = sin(ang);
  let rot = (lx, ly) => [cx + lx * ca - ly * sa, cy + lx * sa + ly * ca];

  // 1) Cast shadow of exposed heel & strap on the sand
  brush.noStroke();
  brush.wash("#361f0d", 205);
  let heelShadow = [];
  for (let a = 70; a <= 290; a += 15) {
    let p = rot(-25 + cos(a) * 48, sin(a) * 28);
    heelShadow.push([p[0] + 9, p[1] + 8]);
  }
  polyShape(heelShadow, 0.2);

  // 2) Coral-Orange & White Foam Rubber Outsole Thickness (3D side edge)
  let soleSide = [
    rot(28, 28),
    rot(-15, 27),
    rot(-55, 23),
    rot(-72, 10),
    rot(-74, 0),
    rot(-74, 9),
    rot(-55, 31),
    rot(-15, 35),
    rot(28, 35)
  ];
