    rot(-18, -24), rot(26, -2), rot(-14, 25), rot(-22, 23), rot(14, -2), rot(-25, -22)
  ], 0.15);
  brush.noWash();

  // 5) Sand Ridge burying the front (toe) half of the flip-flop!
  let burialMound = [
    rot(12, -46),
    rot(58, -42),
    rot(72, 0),
    rot(56, 44),
    rot(10, 46),
    rot(18, 18),
    rot(14, 0),
    rot(20, -20)
  ];
  brush.noStroke();
  brush.fill("#f0be82", 245);
  brush.fillBleed(0.03, "out");
  polyShape(burialMound, 0.25);
  brush.noFill();

  // Sunlit highlight & SE shadow on the burying sand drift
