// =========================================================================
// 9. LANDMARK: CRUMPLED ICE-CREAM WRAPPER
// =========================================================================

function drawCrumpledWrapper(cx, cy) {
  // A polyhedral crumpled foil-and-wax-paper ice-cream wrapper (cherry red, cobalt, white, silver foil)
  // 1) Jagged high-contrast dark shadow underneath the crumpled wrapper
  let shadowPoly = [
    [cx - 42, cy - 18], [cx + 22, cy - 38], [cx + 58, cy - 8],
    [cx + 48, cy + 36], [cx - 8, cy + 46], [cx - 46, cy + 22]
  ].map(p => [p[0] + 9, p[1] + 8]);
  brush.noStroke();
  brush.wash("#2e1a0b", 215);
  polyShape(shadowPoly, 0.08);
  brush.noWash();

  // 2) Define vertices of the crumpled origami-like polyhedral mesh
  let V = {
    c0: [cx - 6, cy - 4],     // Central peak
    c1: [cx + 18, cy + 8],    // Secondary ridge peak
    c2: [cx - 22, cy + 14],   // Left valley
    c3: [cx + 8, cy - 22],    // Upper valley
    p0: [cx - 48, cy - 16],   // Outer perimeter vertices
    p1: [cx - 20, cy - 38],
    p2: [cx + 18, cy - 42],
    p3: [cx + 52, cy - 16],
    p4: [cx + 44, cy + 24],
    p5: [cx + 12, cy + 38],
    p6: [cx - 24, cy + 36],
    p7: [cx - 48, cy + 16]
  };

  let facets = [
    // [vertices, color, isFoil]
    [[V.p0, V.p1, V.c3, V.c0], "#ffffff", false],          // Bright sunlit white paper facet
    [[V.p1, V.p2, V.c3], "#d91e26", false],                // Cherry red stripe facet (lit)
    [[V.p2, V.p3, V.c1, V.c3], "#dce6ed", true],           // Silver inner foil facet
    [[V.c0, V.c3, V.c1], "#1b4d8c", false],                // Royal blue wrapper facet
    [[V.p3, V.p4, V.c1], "#738999", true],                 // Shadowed metallic foil facet
    [[V.c0, V.c1, V.p5, V.c2], "#9e1419", false],          // Shadowed cherry red facet
    [[V.c1, V.p4, V.p5], "#c2cfd9", false],                // Mid-tone white paper fold
    [[V.p0, V.c0, V.c2, V.p7], "#e8eff5", false],          // Left sunlit white fold
    [[V.c2, V.p5, V.p6], "#102f59", false],                // Deep shadowed cobalt facet
    [[V.p7, V.c2, V.p6], "#8599a8", true]                  // Lower-left silver foil corner
  ];

  // Render each crisp angular facet
  for (let f of facets) {
    brush.noStroke();
    brush.wash(f[1], 242);
    polyShape(f[0], 0);
    brush.noWash();

    if (f[2]) {
      // Metallic foil glints (fine parallel hatching)
      brush.hatchStyle("fine_liner", "#ffffff", 0.3);
      brush.hatch(3.5, 40, { rand: 0.05 });
      brush.noStroke();
      polyShape(f[0], 0);
      brush.noHatch();
    }
  }

  // Printed diagonal red & blue seaside stripes across the central paper facets
  brush.noStroke();
  brush.wash("#d91e26", 230);
  polyShape([
    lerpPt(V.p0, V.p1, 0.35), lerpPt(V.p0, V.p1, 0.7),
    lerpPt(V.c0, V.c3, 0.7), lerpPt(V.c0, V.c3, 0.35)
  ], 0);
  brush.wash("#1b4d8c", 230);
  polyShape([
    lerpPt(V.p7, V.p0, 0.3), lerpPt(V.p7, V.p0, 0.65),
    lerpPt(V.c2, V.c0, 0.65), lerpPt(V.c2, V.c0, 0.3)
  ], 0);
  brush.noWash();

  // Sharp white specular crease ridges & fine dark ink fold lines
  let ridges = [[V.p1, V.c3], [V.c3, V.c0], [V.c0, V.c1], [V.c0, V.p0], [V.c3, V.p2]];
  brush.set("fine_liner", "#ffffff", 0.65);
  for (let r of ridges) {
    brush.line(r[0][0], r[0][1], r[1][0], r[1][1]);
  }

  brush.set("fine_liner", "#1a1d24", 0.34);
  for (let f of facets) {
    polyShape(f[0], 0, true);
  }
}

function lerpPt(a, b, t) {
  return [lerp(a[0], b[0], t), lerp(a[1], b[1], t)];
}

// =========================================================================
// 10. DECORATIVE COMPASS ROSE (Bottom-Right Corner)
// =========================================================================

function drawCompassRose(cx, cy, R) {
  // 1) Subtle watercolor medallion background
  brush.noStroke();
  brush.fill("#fbf2dc", 225);
  brush.fillBleed(0.02, "in");
  polyShape(ellipsePts(cx, cy, R * 0.92, R * 0.92, 40), 0.1);
  brush.fill("#bce8e4", 150);
  polyShape(ellipsePts(cx, cy, R * 0.68, R * 0.68, 36), 0.1);
  brush.noFill();

  // 2) Concentric degree rings & tick marks
  brush.set("fine_liner", "#1e1812", 0.42);
  brush.circle(cx, cy, R * 0.92, 0.02);
  brush.circle(cx, cy, R * 0.84, 0.02);
  brush.circle(cx, cy, R * 0.68, 0.02);
  brush.circle(cx, cy, R * 0.22, 0.02);

  for (let a = 0; a < 360; a += 5) {
    let rIn = (a % 15 === 0) ? R * 0.84 : R * 0.88;
    brush.set("fine_liner", "#1e1812", a % 45 === 0 ? 0.45 : 0.25);
    brush.line(
      cx + cos(a) * rIn, cy + sin(a) * rIn,
      cx + cos(a) * R * 0.92, cy + sin(a) * R * 0.92
    );
  }

  // 3) 8 Tertiary Points (16-point star layer)
  let rInner = R * 0.16;
  for (let i = 0; i < 8; i++) {
    let a = i * 45 + 22.5;
    drawCompassNeedle(cx, cy, a, R * 0.62, rInner * 0.85, "#117a82", "#b8ebe6");
  }

  // 4) 4 Ordinal Points (NE, SE, SW, NW)
  for (let i = 0; i < 4; i++) {
    let a = i * 90 + 45;
    drawCompassNeedle(cx, cy, a, R * 0.78, rInner, "#c47a2b", "#faeccd");
  }

  // 5) 4 Cardinal Points (N, E, S, W) — high contrast black-sepia & gold-ivory
  for (let i = 0; i < 4; i++) {
    let a = i * 90 - 90; // -90 is North
    let len = (i === 0) ? R * 0.98 : R * 0.90;
    let colDark = (i === 0) ? "#b81d18" : "#1c1510";
    let colLit = (i === 0) ? "#ffdfd6" : "#fff7e3";
    drawCompassNeedle(cx, cy, a, len, rInner * 1.25, colDark, colLit);
  }

  // Ornate North Fleur-de-Lis / Crown finial above North point
  let ny = cy - R * 0.98;
  brush.noStroke();
  brush.wash("#b81d18", 240);
  polyShape([[cx, ny - 14], [cx + 6, ny - 3], [cx, ny], [cx - 6, ny - 3]], 0.1);
  brush.noWash();
  brush.set("fine_liner", "#1c1510", 0.35);
  polyShape([[cx, ny - 14], [cx + 6, ny - 3], [cx, ny], [cx - 6, ny - 3]], 0.1, true);

  // Central brass/gold boss
  brush.noStroke();
  brush.wash("#e39d3b", 245);
  polyShape(ellipsePts(cx, cy, R * 0.08, R * 0.08, 12), 0);
  brush.noWash();
  brush.set("fine_liner", "#1c1510", 0.38);
  brush.circle(cx, cy, R * 0.08, 0.02);

  // Cardinal Letters N, E, S, W
  drawVectorText("N", cx - 5, cy - R - 26, 13, 2, "#1c1510", 0.55);
  drawVectorText("S", cx - 4, cy + R + 8, 11, 2, "#1c1510", 0.45);
  drawVectorText("E", cx + R + 10, cy - 5, 11, 2, "#1c1510", 0.45);
  drawVectorText("W", cx - R - 21, cy - 5, 11, 2, "#1c1510", 0.45);
}

function drawCompassNeedle(cx, cy, ang, rTip, rBase, colDark, colLit) {
  let tip = [cx + cos(ang) * rTip, cy + sin(ang) * rTip];
  let leftBase = [cx + cos(ang - 22.5) * rBase, cy + sin(ang - 22.5) * rBase];
  let rightBase = [cx + cos(ang + 22.5) * rBase, cy + sin(ang + 22.5) * rBase];
  let center = [cx, cy];

  brush.noStroke();
  brush.wash(colDark, 245);
  polyShape([center, tip, rightBase], 0);
  brush.wash(colLit, 245);
  polyShape([center, leftBase, tip], 0);
  brush.noWash();

  brush.set("fine_liner", "#1c1510", 0.32);
  polyShape([center, leftBase, tip, rightBase], 0, true);
  brush.line(center[0], center[1], tip[0], tip[1]);
}

