function drawMapLabelsAndBorder() {
  // 1) Small Souvenir Map Ribbon Callout Labels near each landmark
  drawMapLabel(665, 318, "I. SANDCITADEL", [665, 355]);
  drawMapLabel(905, 595, "II. TIDAL MOAT", [855, 585]);
  drawMapLabel(425, 255, "III. SHORE CRAB", [410, 315]);
  drawMapLabel(165, 895, "IV. RED SPADE", [215, 835]);
  drawMapLabel(595, 1045, "V. LOST SANDAL", [705, 995]);
  drawMapLabel(975, 225, "VI. ICE WRAPPER", [980, 295]);

  // 2) Outer Cartographic Map Frame (Double-ruled border with degree ticks)
  let m1 = 28;
  let m2 = 38;
  // Mask clean cream margins around the outside of the map frame
  brush.noStroke();
  brush.wash("#fbf4e2", 250);
  polyShape([[0, 0], [1200, 0], [1200, m2], [0, m2]], 0);
  polyShape([[0, 1200 - m2], [1200, 1200 - m2], [1200, 1200], [0, 1200]], 0);
  polyShape([[0, 0], [m2, 0], [m2, 1200], [0, 1200]], 0);
  polyShape([[1200 - m2, 0], [1200, 0], [1200, 1200], [1200 - m2, 1200]], 0);

  // Alternating black/ivory cartographic scale blocks along the border
  let segs = 24;
  let span = 1200 - m2 * 2;
  for (let i = 0; i < segs; i++) {
    if (i % 2 === 0) {
      let a = m2 + (i / segs) * span;
      let b = m2 + ((i + 1) / segs) * span;
      brush.wash("#241810", 235);
      // Top & Bottom bars
      polyShape([[a, m1], [b, m1], [b, m2], [a, m2]], 0);
      polyShape([[a, 1200 - m2], [b, 1200 - m2], [b, 1200 - m1], [a, 1200 - m1]], 0);
      // Left & Right bars
      polyShape([[m1, a], [m2, a], [m2, b], [m1, b]], 0);
      polyShape([[1200 - m2, a], [1200 - m1, a], [1200 - m1, b], [1200 - m2, b]], 0);
    }
  }
  brush.noWash();

  // Crisp double-ruled border lines
  brush.set("fine_liner", "#1a110a", 0.55);
  brush.rect(m1, m1, 1200 - m1 * 2, 1200 - m1 * 2, "corner");
  brush.rect(m2, m2, 1200 - m2 * 2, 1200 - m2 * 2, "corner");
  brush.set("fine_liner", "#1a110a", 0.28);
  brush.rect(m2 + 4, m2 + 4, 1200 - (m2 + 4) * 2, 1200 - (m2 + 4) * 2, "corner");
}

function drawMapLabel(cx, cy, textStr, targetPt) {
  let charW = 8.2;
  let w = textStr.length * charW + 22;
  let h = 24;
  let x = cx - w * 0.5;
  let y = cy - h * 0.5;

  // Fine dotted pointer line from banner to landmark
  let steps = 6;
  brush.set("fine_liner", "#3d2512", 0.38);
  for (let i = 1; i < steps; i++) {
    let px = lerp(cx, targetPt[0], i / steps);
    let py = lerp(cy + (targetPt[1] > cy ? h * 0.5 : -h * 0.5), targetPt[1], i / steps);
    brush.circle(px, py, 1.1, 0);
  }

  // Banner cast shadow
  brush.noStroke();
  brush.wash("#382210", 165);
  polyShape([[x + 4, y + 4], [x + w + 4, y + 4], [x + w + 4, y + h + 4], [x + 4, y + h + 4]], 0);

  // Decorative ribbon tails on left & right ends
  brush.wash("#d9c298", 240);
  polyShape([[x - 10, y + 4], [x + 4, y + 4], [x + 4, y + h + 4], [x - 10, y + h + 4], [x - 5, y + h * 0.5 + 4]], 0);
  polyShape([[x + w - 4, y + 4], [x + w + 10, y + 4], [x + w + 5, y + h * 0.5 + 4], [x + w + 10, y + h + 4], [x + w - 4, y + h + 4]], 0);

  // Cream parchment label card
  brush.wash("#fcf5e3", 248);
  polyShape([[x, y], [x + w, y], [x + w, y + h], [x, y + h]], 0);
  brush.noWash();

  // Fine pen border & vector typography
  brush.set("fine_liner", "#241509", 0.38);
  polyShape([[x, y], [x + w, y], [x + w, y + h], [x, y + h]], 0, true);
  brush.set("fine_liner", "#8c2318", 0.25);
  polyShape([[x + 2.5, y + 2.5], [x + w - 2.5, y + 2.5], [x + w - 2.5, y + h - 2.5], [x + 2.5, y + h - 2.5]], 0, true);

  drawVectorText(textStr, x + 11, y + 7, 10, 2.2, "#1f1208", 0.42);
}

// Hyperreal Dark Wet Slate Patio at Dawn with Garden Snails & Cloud-Chamber Trails
// p5.js 2.x + p5.brush in WEBGL mode

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Scale built-in brushes first per constraints
  brush.scaleBrushes(3);

