// ============================================================================
// SAFE DRAWING HELPERS
// ============================================================================

function setStrokeBrush(name, col, weight = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(name, col, weight);
}

function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  let cleaned = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = cleaned[cleaned.length - 1];
    let dx = pts[i][0] - prev[0];
    let dy = pts[i][1] - prev[1];
    if (dx * dx + dy * dy > 0.6) {
      cleaned.push(pts[i]);
    }
  }
  if (cleaned.length === 2) {
    brush.line(cleaned[0][0], cleaned[0][1], cleaned[1][0], cleaned[1][1]);
  } else if (cleaned.length >= 3) {
    brush.spline(cleaned, curvature);
  }
}

function lerpHex(hex1, hex2, t) {
  t = constrain(t, 0, 1);
  let c1 = color(hex1);
  let c2 = color(hex2);
  return lerpColor(c1, c2, t);
}

