function drawSlatePatio() {
  brush.noField();
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Base near-black slate wash
  brush.wash("#0a0c0e", 255);
  brush.rect(0, 0, width, height);

  // Subtle diagonal dawn sheen across wet stone (cool slate + muted earth undertones)
  const strata = [
    { x: -100, y: -100, w: 1400, h: 550, col: "#0f1317", op: 95 },
    { x: -100, y: 260, w: 1400, h: 680, col: "#14191f", op: 110 },
    { x: 120, y: 340, w: 960, h: 520, col: "#181e24", op: 85 },
    { x: 220, y: 420, w: 720, h: 380, col: "#1b1916", op: 65 }, // muted earth warmth
    { x: -100, y: 820, w: 1400, h: 480, col: "#0b0d10", op: 140 },
    { x: 640, y: 80, w: 580, h: 460, col: "#161a17", op: 60 }   // faint damp moss-slate
  ];

  for (let s of strata) {
    brush.wash(s.col, s.op);
    brush.rect(s.x, s.y, s.w, s.h);
  }
  brush.noWash();

  // Watercolor mineral mottling on wet stone (batched by color)
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.65, 0.3);

  const mineralPatches = [
    { col: "#161b21", op: 45, items: [[320, 480, 260], [790, 560, 290], [580, 310, 220]] },
    { col: "#1a1714", op: 40, items: [[440, 740, 240], [880, 360, 210], [210, 860, 230]] },
    { col: "#151c19", op: 38, items: [[670, 690, 210], [310, 220, 190], [980, 780, 250]] },
    { col: "#07080a", op: 70, items: [[110, 140, 280], [1080, 1050, 320], [140, 1080, 260], [1060, 140, 250]] }
  ];

  for (let group of mineralPatches) {
    brush.fill(group.col, group.op);
    for (let it of group.items) {
      brush.circle(it[0], it[1], it[2], 0.35);
    }
  }
  brush.noFill();

  // Layered pencil & charcoal cleavage hatching (slate laminar grain around -11 deg)
  const slatePalette = [
    "#060809", "#0c0f12", "#12161b", "#171c22",
    "#1c2229", "#181715", "#1f1d19", "#151a18"
  ];

  // Broad velvety charcoal sweeps along the stone grain
  for (let i = 0; i < 420; i++) {
    let x = random(-80, width + 80);
    let y = random(-40, height + 40);
    let len = random(110, 380);
    let ang = -11 + random(-3.5, 3.5);
    let col = random(slatePalette);
    setStrokeBrush("velvet", col, random(0.9, 2.4));
    let x2 = x + cos(ang) * len;
    let y2 = y + sin(ang) * len;
    brush.line(x, y, x2, y2);
  }

  // Fine graphite & charcoal pencil layering (cross-cleavage & laminar striations)
  const pencilBrushes = ["charcoal", "2B", "HB"];
  for (let i = 0; i < 950; i++) {
    let x = random(-40, width + 40);
    let y = random(-40, height + 40);
    let n = noise(x * 0.003, y * 0.003);
    let ang = (i % 4 === 0) ? (18 + n * 14) : (-11 + (n - 0.5) * 8);
    let len = random(45, 190);
    let bName = pencilBrushes[i % 3];
    let distCenter = dist(x, y, 620, 560);
    let col;
    if (distCenter < 480 && random() < 0.38) {
      col = random(["#1e252c", "#232a32", "#211f1b", "#1d2420"]);
    } else {
      col = random(["#07090b", "#0d1014", "#13181d", "#181d23", "#171512"]);
    }
    setStrokeBrush(bName, col, random(0.35, 0.95));
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // Subtle cleaved rock ridges (stepped horizontal-diagonal fractures in the slate)
  for (let r = 0; r < 28; r++) {
    let sx = random(0, width - 200);
    let sy = random(40, height - 40);
    let pts = [];
    let steps = int(random(5, 11));
    let cx = sx, cy = sy;
    for (let k = 0; k < steps; k++) {
      pts.push([cx, cy, random(0.3, 0.9)]);
      let stepLen = random(25, 65);
      let stepAng = -11 + (noise(cx * 0.01, cy * 0.01) - 0.5) * 16;
      cx += cos(stepAng) * stepLen;
      cy += sin(stepAng) * stepLen;
    }
    // Shadow side of cleavage step
    setStrokeBrush("2B", "#050608", random(0.6, 1.2));
    safeSpline(pts, 0.3);
    // Wet dawn glint on upper lip of cleavage step
    let glintPts = pts.map(p => [p[0], p[1] - 1.8, p[2] * 0.7]);
    setStrokeBrush("2H", random(["#242c34", "#2b333b", "#292621"]), random(0.25, 0.55));
    safeSpline(glintPts, 0.3);
  }

  // Architectural Flagstone Seams (Patio Slate Joints)
  drawSlateSeam(-40, 285, 1240, 125); // Upper seam
  drawSlateSeam(-40, 995, 1240, 835); // Lower seam
  drawSlateSeam(315, -20, 260, 248);  // Upper-left cross joint
  drawSlateSeam(915, 876, 975, 1220); // Lower-right cross joint

  // Fine mineral grain & damp mist across the stone
  for (let i = 0; i < 160; i++) {
    let x = random(width);
    let y = random(height);
    setStrokeBrush("spray", random(["#060709", "#1d242b", "#24221d"]), random(0.4, 1.1));
    brush.line(x, y, x + random(15, 50), y + random(-10, 10));
  }
}

function drawSlateSeam(x1, y1, x2, y2) {
  let steps = 28;
  let seamPts = [];
  let upperEdge = [];
  let lowerEdge = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let bx = lerp(x1, x2, t);
    let by = lerp(y1, y2, t);
    let jitter = (noise(bx * 0.008, by * 0.008) - 0.5) * 10;
    let px = bx;
    let py = by + jitter;
    seamPts.push([px, py, 0.9]);
    upperEdge.push([px, py - random(2.5, 4.5), 0.6]);
    lowerEdge.push([px, py + random(2.2, 4.0), 0.7]);
  }

  // Damp recessed mortar/gap shadow
  setStrokeBrush("velvet", "#050608", 2.2);
  safeSpline(seamPts, 0.35);
  setStrokeBrush("charcoal", "#030405", 1.1);
  safeSpline(seamPts, 0.35);

  // Subtle earthy moss/lichen tint along damp joint
  for (let i = 1; i < seamPts.length - 1; i += 2) {
    if (random() < 0.65) {
      let p = seamPts[i];
      setStrokeBrush("velvet", random(["#1b2118", "#232119", "#171d18"]), random(0.8, 1.6));
      brush.line(p[0] - 12, p[1] + random(-4, 4), p[0] + 12, p[1] + random(-4, 4));
    }
  }

  // Chipped stone edge catching dawn light on lower lip
  setStrokeBrush("HB", "#262f37", 0.55);
  safeSpline(lowerEdge, 0.35);
  setStrokeBrush("2H", "#35404a", 0.35);
  safeSpline(upperEdge, 0.35);
}

