// Samples a smooth polyline from control points for tangent/normal math
function sampleCurvePoints(ctrlPts, numSamples = 140) {
  let result = [];
  let n = ctrlPts.length - 1;
  for (let i = 0; i <= numSamples; i++) {
    let t = (i / numSamples) * n;
    let idx = constrain( floor(t), 0, n - 1 );
    let frac = t - idx;

    let p0 = ctrlPts[max(0, idx - 1)];
    let p1 = ctrlPts[idx];
    let p2 = ctrlPts[min(n, idx + 1)];
    let p3 = ctrlPts[min(n, idx + 2)];

    // Catmull-Rom interpolation
    let f2 = frac * frac;
    let f3 = f2 * frac;
    let x = 0.5 * (
      (2 * p1[0]) +
      (-p0[0] + p2[0]) * frac +
      (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * f2 +
      (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * f3
    );
    let y = 0.5 * (
      (2 * p1[1]) +
      (-p0[1] + p2[1]) * frac +
      (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * f2 +
      (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * f3
    );
    result.push({ x, y, u: i / numSamples });
  }

  // Compute tangents & normals
  for (let i = 0; i < result.length; i++) {
    let prev = result[max(0, i - 1)];
    let next = result[min(result.length - 1, i + 1)];
    let dx = next.x - prev.x;
    let dy = next.y - prev.y;
    let len = sqrt(dx * dx + dy * dy) || 1;
    result[i].tx = dx / len;
    result[i].ty = dy / len;
    result[i].nx = -dy / len;
    result[i].ny = dx / len;
    result[i].ang = atan2(dy, dx);
  }
  return result;
}

function drawCloudChamberFilamentTrack(ctrlPts, opts) {
  let samples = sampleCurvePoints(ctrlPts, 110);
  let intensity = opts.intensity || 0.8;
  let numF = opts.numFilaments || 5;
  let spread = opts.spread || 8;

  // Faint wet slime aura on the slate beneath the track
  let glazePts = [];
  for (let i = 0; i < samples.length; i += 4) {
    glazePts.push([samples[i].x, samples[i].y, 0.6]);
  }
  setStrokeBrush("velvet", "#161d22", 1.4 * intensity);
  safeSpline(glazePts, 0.5);

  // Iridescent violet & pale green fringe filaments + silvery core filaments
  const violetCols = ["#5e4e69", "#7c678a", "#9982a8"];
  const greenCols = ["#536e60", "#6e917e", "#8db39e"];
  const silverCols = ["#8e9ca8", "#b8c6d1", "#dde8f0", "#f4f9fc"];
  const earthCols = ["#7a6d58", "#998971"];

  for (let f = 0; f < numF; f++) {
    let phase = random(360);
    let freq = random(2.5, 6.0);
    let baseOffset = map(f, 0, numF - 1, -spread, spread);

    // Choose filament color & brush role
    let col, bName, w;
    if (f === 0) {
      col = random(violetCols);
      bName = "filament";
      w = random(0.45, 0.75) * intensity;
    } else if (f === numF - 1) {
      col = random(greenCols);
      bName = "filament";
      w = random(0.45, 0.75) * intensity;
    } else if (f === 1 && numF > 4) {
      col = random(earthCols);
      bName = "2H";
      w = random(0.3, 0.55) * intensity;
    } else {
      col = silverCols[min(silverCols.length - 1, f)];
      bName = (f % 2 === 0) ? "filament" : "rotring";
      w = random(0.32, 0.65) * intensity;
    }

    // Break into overlapping segments so lines fade in and out like cloud-chamber tracks
    let segStart = 0;
    while (segStart < samples.length - 6) {
      let segLen = int(random(18, 48));
      let segEnd = min(samples.length - 1, segStart + segLen);
      let pts = [];
      for (let i = segStart; i <= segEnd; i += 2) {
        let s = samples[i];
        let wave = sin(s.u * 360 * freq + phase) * (spread * 0.42);
        let off = baseOffset + wave;
        let edgeFade = sin(map(i, segStart, segEnd, 10, 170));
        pts.push([
          s.x + s.nx * off,
          s.y + s.ny * off,
          constrain(edgeFade * intensity, 0.15, 0.95)
        ]);
      }
      setStrokeBrush(bName, col, w);
      safeSpline(pts, 0.5);
      segStart = segEnd - int(random(2, 8));
    }
  }

  // Spawn delta-ray spiral branches along the trajectory
  let spCount = opts.spiralCount || 4;
  for (let k = 0; k < spCount; k++) {
    let idx = int(map(k + random(0.15, 0.85), 0, spCount, 12, samples.length - 15));
    let s = samples[idx];
    let dir = (random() < 0.5) ? 1 : -1;
    let branchAng = s.ang + dir * random(18, 42);
    let rad = random(22, 54) * intensity;
    let turns = random(2.4, 4.2);
    drawDeltaSpiral(s.x, s.y, branchAng, rad, turns, dir, intensity);
  }
}

// Draws a cloud-chamber logarithmic/Euler decaying spiral with violet/green iridescence and silver core
function drawDeltaSpiral(sx, sy, startAngleDeg, initRadius, turns, spinDir, intensity = 0.9) {
  let totalSteps = int(turns * 26);
  let mainPts = [];
  let violetPts = [];
  let greenPts = [];

  let cx = sx;
  let cy = sy;
  let curAng = startAngleDeg;
  let totalAngle = turns * 360;

  for (let i = 0; i <= totalSteps; i++) {
    let t = i / totalSteps;
    // Curvature tightens exponentially as the particle loses energy
    let r = initRadius * pow(1 - t * 0.88, 1.55);
    let dTheta = (totalAngle / totalSteps) * (0.45 + 1.35 * t);
    curAng += spinDir * dTheta;

    let stepLen = (r * radians(dTheta)) * 0.85;
    cx += cos(curAng) * stepLen;
    cy += sin(curAng) * stepLen;

    let nx = -sin(curAng);
    let ny = cos(curAng);
    let pressure = sin(t * 165) * intensity * (1 - t * 0.35);
    pressure = constrain(pressure, 0.15, 1.0);

    if (i % 2 === 0 || i === totalSteps) {
      mainPts.push([cx, cy, pressure]);
      let iridOff = 1.4 * (1 - t * 0.6);
      violetPts.push([cx + nx * iridOff, cy + ny * iridOff, pressure * 0.75]);
      greenPts.push([cx - nx * iridOff, cy - ny * iridOff, pressure * 0.75]);
    }
  }

  // Iridescent violet outer filament
  setStrokeBrush("filament", random(["#786288", "#9178a3", "#645173"]), 0.42 * intensity);
  safeSpline(violetPts, 0.55);

  // Iridescent pale green inner filament
  setStrokeBrush("filament", random(["#648573", "#7fa390", "#547061"]), 0.42 * intensity);
  safeSpline(greenPts, 0.55);

  // Crisp silvery-white core track
  setStrokeBrush("filament", "#c8d5e0", 0.52 * intensity);
  safeSpline(mainPts, 0.55);

  // High-luminosity inner spiral highlight
  if (mainPts.length > 8) {
    let coreSlice = mainPts.slice(2, int(mainPts.length * 0.75));
    setStrokeBrush("glint", "#edf5fc", 0.34 * intensity);
    safeSpline(coreSlice, 0.55);
  }

  // Tiny secondary sub-curl branching off the first turn
  if (initRadius > 32 && mainPts.length > 10 && random() < 0.75) {
    let bIdx = int(mainPts.length * 0.25);
    let bp = mainPts[bIdx];
    drawDeltaSpiral(
      bp[0],
      bp[1],
      startAngleDeg + spinDir * 65,
      initRadius * 0.42,
      random(1.8, 2.8),
      -spinDir,
      intensity * 0.75
    );
  }
}

// Draws an active garden snail mucilage ribbon trail with pedal waves, iridescent fringes, and spirals
function drawSnailRibbonTrail(ctrlPts, opts) {
  let samples = sampleCurvePoints(ctrlPts, 160);
  let wStart = opts.widthStart || 24;
  let wEnd = opts.widthEnd || 32;
  let fresh = opts.freshness || 1.0;

  // 1. Damp dark-sheen mucilage glaze on the slate
  for (let pass = -1; pass <= 1; pass++) {
    let pts = [];
    for (let i = 0; i < samples.length; i += 3) {
      let s = samples[i];
      let hw = lerp(wStart, wEnd, s.u) * 0.5;
      let off = pass * hw * 0.55;
      pts.push([s.x + s.nx * off, s.y + s.ny * off, 0.75]);
    }
    let glazeCol = (pass === -1) ? "#1c1924" : (pass === 1 ? "#17211d" : "#182026");
    setStrokeBrush("velvet", glazeCol, 2.1 * fresh);
    safeSpline(pts, 0.5);
  }

  // 2. Transverse pedal-wave crescent ripples (characteristic rhythmic snail foot waves)
  let waveSpacing = 3;
  for (let i = 4; i < samples.length - 4; i += waveSpacing) {
    let s = samples[i];
    let prog = lerp(0.35, 1.0, s.u) * fresh;
    let hw = lerp(wStart, wEnd, s.u) * 0.5 * (0.88 + 0.14 * sin(i * 19));

    // Curved crescent bowing backward against the direction of travel
    let bow = hw * 0.38;
    let pLeft = [
      s.x + s.nx * hw * 0.92 - s.tx * bow,
      s.y + s.ny * hw * 0.92 - s.ty * bow,
      0.25 * prog
    ];
    let pMidL = [
      s.x + s.nx * hw * 0.35,
      s.y + s.ny * hw * 0.35,
      0.75 * prog
    ];
    let pMidR = [
      s.x - s.nx * hw * 0.35,
      s.y - s.ny * hw * 0.35,
      0.75 * prog
    ];
    let pRight = [
      s.x - s.nx * hw * 0.92 - s.tx * bow,
      s.y - s.ny * hw * 0.92 - s.ty * bow,
      0.25 * prog
    ];

    // Iridescent color shift along the pedal waves
    let waveCol;
    let mod = i % 9;
    if (mod === 0) waveCol = "#887099";      // Iridescent violet
    else if (mod === 3) waveCol = "#759985"; // Iridescent pale green
    else if (mod === 6) waveCol = "#94846b"; // Muted earth champagne
    else waveCol = (random() < 0.5) ? "#9eadba" : "#c4d2de";

    setStrokeBrush("filament", waveCol, random(0.28, 0.52) * prog);
    safeSpline([pLeft, pMidL, pMidR, pRight], 0.55);
  }

  // 3. Longitudinal wiry filaments weaving along the ribbon
  let numLong = 11;
  for (let f = 0; f < numLong; f++) {
    let normPos = map(f, 0, numLong - 1, -0.95, 0.95);
    let isEdge = abs(normPos) > 0.72;
    let phase = random(360);
    let freq = random(3, 7);

    let col, bName, w;
    if (f === 0 || f === 2) {
      col = random(["#7e688f", "#9e86b0", "#695578"]); // Violet edge iridescence
      bName = "filament";
      w = 0.55 * fresh;
    } else if (f === numLong - 1 || f === numLong - 3) {
      col = random(["#6d8f7d", "#89b09b", "#577565"]); // Pale green edge iridescence
      bName = "filament";
      w = 0.55 * fresh;
    } else if (f === 5) {
      col = "#9c8b70"; // Muted earth tone filament
      bName = "2H";
      w = 0.42 * fresh;
    } else {
      col = isEdge ? "#dce7f0" : random(["#aebcc7", "#d0dce6", "#f0f7fc"]);
      bName = isEdge ? "glint" : "filament";
      w = (isEdge ? 0.58 : 0.42) * fresh;
    }

    let pts = [];
    for (let i = 0; i < samples.length; i += 2) {
      let s = samples[i];
      let hw = lerp(wStart, wEnd, s.u) * 0.5;
      let undulate = sin(s.u * 360 * freq + phase) * (hw * 0.14);
      let off = normPos * hw + undulate;
      let p = constrain(lerp(0.35, 1.0, s.u) * fresh * (0.65 + 0.35 * sin(i * 11 + f * 40)), 0.15, 1.0);
      pts.push([s.x + s.nx * off, s.y + s.ny * off, p]);
    }
    setStrokeBrush(bName, col, w);
    safeSpline(pts, 0.5);
  }

  // 4. Crisp specular silver rim highlights & micro-beads along the fresh half of the trail
  for (let side of [-1, 1]) {
    let rimPts = [];
    for (let i = int(samples.length * 0.25); i < samples.length; i += 2) {
      let s = samples[i];
      let hw = lerp(wStart, wEnd, s.u) * 0.48;
      let wobble = (noise(i * 0.15, side * 10) - 0.5) * 3.5;
      let off = side * hw + wobble;
      let p = map(i, samples.length * 0.25, samples.length, 0.2, 0.95) * fresh;
      rimPts.push([s.x + s.nx * off, s.y + s.ny * off, p]);
    }
    setStrokeBrush("glint", "#eef6fc", 0.45 * fresh);
    safeSpline(rimPts, 0.5);
  }

  // 5. Cloud-chamber spiral offshoots peeling off the ribbon margins
  let branches = opts.spiralBranches || 6;
  for (let b = 0; b < branches; b++) {
    let idx = int(map(b + random(0.1, 0.9), 0, branches, 10, samples.length - 12));
    let s = samples[idx];
    let side = (b % 2 === 0) ? 1 : -1;
    let hw = lerp(wStart, wEnd, s.u) * 0.5;
    let bx = s.x + s.nx * side * hw;
    let by = s.y + s.ny * side * hw;
    let launchAng = s.ang + side * random(22, 52);
    drawDeltaSpiral(bx, by, launchAng, random(24, 52), random(2.5, 4.3), side, fresh * 0.92);
  }

  // 6. Ionization-like mucilage micro-droplets along the track
  for (let i = 0; i < samples.length; i += 2) {
    if (random() < 0.55) {
      let s = samples[i];
      let hw = lerp(wStart, wEnd, s.u) * 0.68;
      let off = random(-hw, hw);
      let dx = s.x + s.nx * off + random(-3, 3);
      let dy = s.y + s.ny * off + random(-3, 3);
      let beadCol = random(["#d8e4ed", "#f2f8fc", "#9c84b0", "#84ab96"]);
      setStrokeBrush("glint", beadCol, random(0.35, 0.75) * fresh);
      brush.line(dx, dy, dx + cos(s.ang) * random(1.2, 3.2), dy + sin(s.ang) * random(1.2, 3.2));
    }
  }
}

// ============================================================================
// 3. HYPERREAL GARDEN SNAIL (MOIST GREY BODY + MOTTLED AMBER 3D SHELL)
// ============================================================================

function drawHyperrealSnail(cfg) {
  let cx = cfg.x;
  let cy = cfg.y;
  let heading = cfg.heading;
  let S = cfg.scale || 1.0;
  let headTurn = cfg.headTurn || 0;
  let seedOff = cfg.seedOffset || 0;

  // Coordinate transform helper from snail local space to world canvas space
  // In local space: +X is forward (head), -X is backward (tail), +Y is right side, -Y is left side
  const toWorld = (lx, ly) => {
    // Subtle organic bend of the head/neck
    let bend = 0;
    if (lx > 0) {
      bend = pow(lx / (160 * S), 1.4) * headTurn;
    }
    let ang = heading + bend;
    let wx = cx + lx * cos(ang) - ly * sin(ang);
    let wy = cy + lx * sin(ang) + ly * cos(ang);
    return [wx, wy];
  };

  // Spine station helper: s in [-1.0 (tail tip), +1.0 (snout tip)]
  const getBodyStation = (s) => {
    let lx = map(s, -1.0, 1.0, -162 * S, 148 * S);
    // Lateral S-curve of a crawling snail
    let ly = sin(s * 140 + seedOff) * 5.5 * S;
    // Half-width of the muscular foot/body at station s
    let hw;
    if (s < -0.3) {
      // Taper smoothly to the posterior tail tip
      let t = map(s, -1.0, -0.3, 0, 1);
      hw = (3.5 + 38 * pow(t, 0.78)) * S;
    } else if (s < 0.45) {
      // Broad muscular mid-foot and pedal skirt under shell
      let t = map(s, -0.3, 0.45, 0, 1);
      hw = (41.5 - 7.5 * sin(t * 180)) * S;
    } else {
      // Muscular neck widening slightly at head/oral lobes then rounding at snout
      let t = map(s, 0.45, 1.0, 0, 1);
      hw = (34 * cos(t * 78) + 5 * sin(t * 180)) * S;
    }
    // Dorsal arch height (for 3D shading of neck/back)
    let archH = sin(map(constrain(s, -0.95, 0.98), -1, 1, 8, 172)) * 28 * S;
    return { lx, ly, hw, archH, s };
  };

  // --------------------------------------------------------------------------
  // STEP 1: CAST SHADOW & GLISTENING MENISCUS ON WET SLATE
  // --------------------------------------------------------------------------
  drawSnailCastShadowAndMeniscus(getBodyStation, toWorld, S);

  // --------------------------------------------------------------------------
  // STEP 2: MOIST GREY-TAUPE BODY, RUFFLED FOOT MARGIN & TUBERCULATE SKIN
  // --------------------------------------------------------------------------
  drawSnailMoistBody(getBodyStation, toWorld, heading, headTurn, S, seedOff);

  // --------------------------------------------------------------------------
  // STEP 3: FOUR TRANSLUCENT TENTACLES (2 OPTIC EYESTALKS + 2 TACTILE)
  // --------------------------------------------------------------------------
  drawSnailTentacles(toWorld, heading + headTurn, S);

  // --------------------------------------------------------------------------
  // STEP 4: MANTLE COLLAR & SHELL-TO-BODY OCCLUSION SHADOW
  // --------------------------------------------------------------------------
  drawMantleAndShellOcclusion(toWorld, S);

  // --------------------------------------------------------------------------
  // STEP 5: HYPERREAL 3D MOTTLED AMBER HELICOID SHELL
  // --------------------------------------------------------------------------
  drawMottledAmberShell(toWorld, heading, S, seedOff, cfg.shellTilt || 0);
}

function drawSnailCastShadowAndMeniscus(getBodyStation, toWorld, S) {
  // Build foot perimeter polygon in world coordinates
  let leftPts = [];
  let rightPts = [];
  let steps = 36;

  for (let i = 0; i <= steps; i++) {
    let s = map(i, 0, steps, -1.0, 1.0);
    let st = getBodyStation(s);
    let ruff = (1 + 0.06 * sin(i * 45)) * 1.12;
    leftPts.push(toWorld(st.lx, st.ly - st.hw * ruff));
    rightPts.unshift(toWorld(st.lx, st.ly + st.hw * ruff));
  }
  let footOutline = leftPts.concat(rightPts);

  // Solid near-black shadow wash underneath the foot & overhanging shell
  brush.noStroke();
  brush.wash("#040507", 245);
  brush.beginShape(0.35);
  for (let p of footOutline) {
    brush.vertex(p[0] + 4 * S, p[1] + 6 * S);
  }
  brush.endShape(true);

  // Extra shadow under the overhanging shell dome (back-right side of snail)
  let shellShadowCenter = toWorld(-24 * S, 14 * S);
  brush.wash("#030406", 235);
  brush.circle(shellShadowCenter[0] + 8 * S, shellShadowCenter[1] + 12 * S, 96 * S, 0.22);
  brush.noWash();

  // Soft charcoal feathering around shadow perimeter
  let shadowFeather = footOutline.map(p => [p[0] + 5 * S, p[1] + 7 * S, 0.7]);
  setStrokeBrush("velvet", "#030405", 2.6 * S);
  safeSpline(shadowFeather, 0.45);

  // Glistening wet mucus meniscus rim hugging the foot skirt
  let meniscusLeft = [];
  let meniscusRight = [];
  for (let i = 0; i <= steps; i++) {
    let s = map(i, 0, steps, -0.98, 0.96);
    let st = getBodyStation(s);
    let mOff = st.hw * 1.08 + (noise(i * 0.3) - 0.5) * 4 * S;
    let pL = toWorld(st.lx, st.ly - mOff);
    let pR = toWorld(st.lx, st.ly + mOff);
    meniscusLeft.push([pL[0], pL[1], 0.65]);
    meniscusRight.push([pR[0], pR[1], 0.65]);
  }
  setStrokeBrush("filament", "#6c877a", 0.55 * S); // Pale green iridescent meniscus edge
  safeSpline(meniscusLeft, 0.5);
  setStrokeBrush("filament", "#7f6b8f", 0.55 * S); // Pale violet iridescent meniscus edge
  safeSpline(meniscusRight, 0.5);
  setStrokeBrush("glint", "#c5d6e3", 0.42 * S);    // Crisp wet silver meniscus line
  safeSpline(meniscusLeft, 0.5);
  safeSpline(meniscusRight, 0.5);
}

function drawSnailMoistBody(getBodyStation, toWorld, heading, headTurn, S, seedOff) {
  let steps = 40;
  let leftRim = [];
  let rightRim = [];
  for (let i = 0; i <= steps; i++) {
    let s = map(i, 0, steps, -1.0, 1.0);
    let st = getBodyStation(s);
    let scallop = 1.0 + 0.045 * sin(i * 55 + seedOff);
    leftRim.push(toWorld(st.lx, st.ly - st.hw * scallop));
    rightRim.unshift(toWorld(st.lx, st.ly + st.hw * scallop));
  }
  let bodyPoly = leftRim.concat(rightRim);

  // 1. Opaque dark slate-earth base wash so background trails never bleed through the solid snail
  brush.noStroke();
  brush.wash("#17191a", 255);
  brush.beginShape(0.35);
  for (let p of bodyPoly) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();

  // 2. Volumetric underpainting of the foot skirt (warm translucent taupe-olive) and dorsal neck (cool moist grey)
  for (let i = 1; i < steps; i++) {
    let s = map(i, 0, steps, -0.96, 0.96);
    let st = getBodyStation(s);
    let pL = toWorld(st.lx, st.ly - st.hw * 0.92);
    let pC = toWorld(st.lx, st.ly);
    let pR = toWorld(st.lx, st.ly + st.hw * 0.92);

    // Warm earthy pedal margin
    setStrokeBrush("velvet", "#38342c", 1.5 * S);
    brush.line(pL[0], pL[1], pR[0], pR[1]);

    // Moist slate-grey dorsal core
    let pML = toWorld(st.lx, st.ly - st.hw * 0.55);
    let pMR = toWorld(st.lx, st.ly + st.hw * 0.55);
    setStrokeBrush("velvet", "#2b3033", 1.4 * S);
    brush.line(pML[0], pML[1], pMR[0], pMR[1]);
  }

  // 3. Ruffled Pedal Margin (fluted vertical striae & translucent amber-grey edge)
  for (let i = 2; i < steps - 1; i++) {
    let s = map(i, 0, steps, -0.95, 0.92);
    let st = getBodyStation(s);
    for (let side of [-1, 1]) {
      let innerP = toWorld(st.lx, st.ly + side * st.hw * 0.68);
      let outerP = toWorld(st.lx, st.ly + side * st.hw * (1.0 + 0.04 * sin(i * 60)));
      // Dark flute groove
      setStrokeBrush("2B", "#161819", 0.45 * S);
      brush.line(innerP[0], innerP[1], outerP[0], outerP[1]);
      // Translucent warm earth-grey flute ridge next to it
      let ridgeP = toWorld(st.lx + 2 * S, st.ly + side * st.hw * 0.96);
      setStrokeBrush("cpencil", random(["#595246", "#6b6253", "#4d5250"]), 0.55 * S);
      brush.line(innerP[0], innerP[1], ridgeP[0], ridgeP[1]);
    }
  }

  // 4. HYPERREAL TUBERCULATE SKIN TEXTURE (Polygonal/Oval Cobblestone Papillae)
  // Dawn light comes from upper-left (-55 deg in world space)
  let lightDirX = cos(-55);
  let lightDirY = sin(-55);

  let rowCount = 46;
  for (let r = 0; r <= rowCount; r++) {
    let s = map(r, 0, rowCount, -0.95, 0.97);
    // Skip hidden mid-region right under the center of the shell to save draw budget
    if (s > -0.32 && s < 0.12) continue;

    let st = getBodyStation(s);
    let cols = max(3, int((st.hw / (5.2 * S))));
    let tubLen = (s > 0.25) ? 6.2 * S : 5.2 * S;

    for (let c = -cols; c <= cols; c++) {
      let v = c / cols; // -1 (left margin) to +1 (right margin)
      if (abs(v) > 0.92) continue;

      // Stagger alternate rows like natural snail skin reticulation
      let vStagger = v + ((r % 2 === 0) ? 0 : (0.45 / cols));
      let latY = st.ly + vStagger * st.hw * 0.85;
      let lonX = st.lx + (noise(r * 0.4, c * 0.4 + seedOff) - 0.5) * 2.5 * S;

      let centerW = toWorld(lonX, latY);
      let frontW = toWorld(lonX + tubLen * 0.5, latY);
      let backW = toWorld(lonX - tubLen * 0.5, latY);

      // Compute 3D surface normal of this skin tubercle
      let localUpAngle = heading + (s > 0 ? headTurn : 0) + vStagger * 75;
      let nx = cos(localUpAngle) * abs(vStagger) * 0.75 + cos(heading) * (s > 0.7 ? 0.4 : 0);
      let ny = sin(localUpAngle) * abs(vStagger) * 0.75 + sin(heading) * (s > 0.7 ? 0.4 : 0);
      let nz = sqrt(max(0.05, 1.0 - vStagger * vStagger * 0.75));

      let ndotl = constrain(nx * lightDirX + ny * lightDirY + nz * 0.68, 0, 1);
      let mottle = noise(r * 0.28 + seedOff, c * 0.35 + seedOff);

      // Dorsal median band (two rows of elongated paler grey-ochre tubercles along top of neck)
      let isDorsalRidge = abs(c) <= 1 && s > 0.15;

      // 1) Dark moist groove around the tubercle
      setStrokeBrush("pen", "#111416", 0.38 * S);
      brush.line(backW[0], backW[1], frontW[0], frontW[1]);

      // 2) Raised fleshy crown of the tubercle
      let crownCol;
      if (isDorsalRidge) {
        crownCol = lerpHex("#57564d", "#878274", ndotl * 0.85 + mottle * 0.25);
      } else if (abs(vStagger) > 0.62) {
        // Warmer olive-taupe toward the lower foot skirt
        crownCol = lerpHex("#302e28", "#6e6555", ndotl * 0.8 + mottle * 0.25);
      } else {
        // Moist cool-warm slate grey on neck and back
        crownCol = lerpHex("#262b2e", "#697378", ndotl * 0.85 + mottle * 0.2);
      }

      setStrokeBrush("cpencil", crownCol, (isDorsalRidge ? 0.85 : 0.95) * S);
      brush.line(
        backW[0] + lightDirX * 0.8 * S,
        backW[1] + lightDirY * 0.8 * S,
        frontW[0] + lightDirX * 0.8 * S,
        frontW[1] + lightDirY * 0.8 * S
      );

      // 3) Wet specular pinpoint/crescent on illuminated tubercles
      if (ndotl > 0.56 && (random() < 0.72 || isDorsalRidge)) {
        let specCol = (ndotl > 0.74) ? "#e8f2f8" : "#9fb2bf";
        let sx1 = centerW[0] + lightDirX * 1.1 * S;
        let sy1 = centerW[1] + lightDirY * 1.1 * S;
        setStrokeBrush("glint", specCol, random(0.28, 0.52) * S);
        brush.line(sx1, sy1, sx1 + (frontW[0] - backW[0]) * 0.38, sy1 + (frontW[1] - backW[1]) * 0.38);
      }
    }
  }

  // 5. Dorsal median furrow & wet highlight line running from mantle collar to between the eyestalks
  let dorsalLeft = [];
  let dorsalRight = [];
  for (let s = 0.14; s <= 0.95; s += 0.06) {
    let st = getBodyStation(s);
    let pL = toWorld(st.lx, st.ly - 2.4 * S);
    let pR = toWorld(st.lx, st.ly + 2.4 * S);
    dorsalLeft.push([pL[0], pL[1], 0.8]);
    dorsalRight.push([pR[0], pR[1], 0.8]);
  }
  setStrokeBrush("glint", "#cedce6", 0.42 * S);
  safeSpline(dorsalLeft, 0.45);
  setStrokeBrush("filament", "#8fa1ad", 0.35 * S);
  safeSpline(dorsalRight, 0.45);

  // Posterior dorsal keel highlight on the tail (s from -0.96 to -0.35)
  let tailKeel = [];
  for (let s = -0.96; s <= -0.35; s += 0.06) {
    let st = getBodyStation(s);
    let p = toWorld(st.lx, st.ly - 1.5 * S);
    tailKeel.push([p[0], p[1], map(s, -0.96, -0.35, 0.3, 0.85)]);
  }
  setStrokeBrush("glint", "#c4d4e0", 0.45 * S);
  safeSpline(tailKeel, 0.5);
}

function drawSnailTentacles(toWorld, headAng, S) {
  // 1. TWO LOWER TACTILE TENTACLES (shorter, probing downward/outward)
  const lowerConfigs = [
    { side: -1, baseLx: 138 * S, baseLy: -14 * S, len: 36 * S, spreadAng: -38, curveAng: -14 },
    { side: +1, baseLx: 138 * S, baseLy: +14 * S, len: 34 * S, spreadAng: +40, curveAng: +16 }
  ];

  for (let tc of lowerConfigs) {
    drawSingleTentacle(toWorld, headAng, tc, false, S);
  }

  // 2. TWO UPPER OPTIC TENTACLES / EYESTALKS (long, graceful, translucent amber-grey with dark eyespot)
  const upperConfigs = [
    { side: -1, baseLx: 132 * S, baseLy: -11 * S, len: 86 * S, spreadAng: -24, curveAng: -12 },
    { side: +1, baseLx: 132 * S, baseLy: +11 * S, len: 82 * S, spreadAng: +28, curveAng: +15 }
  ];

  for (let tc of upperConfigs) {
    drawSingleTentacle(toWorld, headAng, tc, true, S);
  }
}

function drawSingleTentacle(toWorld, headAng, tc, isOptic, S) {
  let baseW = toWorld(tc.baseLx, tc.baseLy);
  let steps = 16;
  let spine = [];
  let upperRim = [];
  let lowerRim = [];
  let coreMuscle = [];

  let curX = baseW[0];
  let curY = baseW[1];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let ang = headAng + tc.spreadAng + sin(t * 150) * tc.curveAng;
    let stepLen = (tc.len / steps);
    if (i > 0) {
      curX += cos(ang) * stepLen;
      curY += sin(ang) * stepLen;
    }

    // Tentacle width tapers along shaft then swells into a bulbous tip
    let baseThick = isOptic ? 5.6 * S : 3.8 * S;
    let tipBulb = isOptic ? (t > 0.82 ? sin(map(t, 0.82, 1, 0, 180)) * 2.4 * S : 0) : (t > 0.8 ? 0.9 * S : 0);
    let r = lerp(baseThick, isOptic ? 2.1 * S : 1.6 * S, pow(t, 0.65)) + tipBulb;

    let nx = -sin(ang);
    let ny = cos(ang);
    // Determine which normal faces the upper-left light source (-55 deg)
    let dotLight = nx * cos(-55) + ny * sin(-55);
    let lightSign = (dotLight >= 0) ? 1 : -1;

    spine.push([curX, curY, 0.85]);
    upperRim.push([curX + nx * lightSign * r, curY + ny * lightSign * r, 0.8]);
    lowerRim.push([curX - nx * lightSign * r, curY - ny * lightSign * r, 0.8]);
    coreMuscle.push([curX - nx * lightSign * r * 0.2, curY - ny * lightSign * r * 0.2, 0.7]);
  }

  let tip = spine[spine.length - 1];

  // Cast shadow of tentacle on the wet slate below
  let shadowPts = spine.map(p => [p[0] + 4 * S, p[1] + 7 * S, 0.6]);
  setStrokeBrush("velvet", "#050608", (isOptic ? 1.6 : 1.1) * S);
  safeSpline(shadowPts, 0.5);

  // Translucent warm amber-taupe outer shaft glow
  setStrokeBrush("velvet", "#5c5243", (isOptic ? 1.55 : 1.1) * S);
  safeSpline(spine, 0.5);
  setStrokeBrush("cpencil", "#7a6c58", (isOptic ? 1.15 : 0.8) * S);
  safeSpline(spine, 0.5);

  // Darker internal optic nerve / retractor muscle visible through translucent skin
  setStrokeBrush("2B", "#26231f", (isOptic ? 0.65 : 0.45) * S);
  safeSpline(coreMuscle.slice(0, steps - 2), 0.5);

  // Shaded underside edge of tentacle
  setStrokeBrush("pen", "#181a1c", 0.42 * S);
  safeSpline(lowerRim, 0.5);

  // Bulbous tip volume
  let bulbR = isOptic ? 4.2 * S : 2.6 * S;
  brush.noStroke();
  brush.wash("#756854", 230);
  brush.circle(tip[0], tip[1], bulbR, 0.15);
  brush.noWash();

  // Glistening wet silver highlight along the illuminated edge of the stalk
  setStrokeBrush("glint", "#d8e6f0", (isOptic ? 0.48 : 0.36) * S);
  safeSpline(upperRim, 0.5);

  if (isOptic) {
    // Crisp black eye-spot at the distal tip of the optic tentacle
    let eyeX = tip[0] + cos(headAng + tc.spreadAng) * 1.2 * S;
    let eyeY = tip[1] + sin(headAng + tc.spreadAng) * 1.2 * S;
    setStrokeBrush("rotring", "#070809", 1.1 * S);
    brush.line(eyeX - 0.8 * S, eyeY - 0.8 * S, eyeX + 0.8 * S, eyeY + 0.8 * S);

    // Pinpoint wet white corneal reflection on the eye-spot & bulb
    setStrokeBrush("glint", "#ffffff", 0.55 * S);
    brush.line(eyeX - 1.2 * S, eyeY - 1.4 * S, eyeX - 0.2 * S, eyeY - 1.8 * S);
  } else {
    // Moist translucent highlight on tactile tip
    setStrokeBrush("glint", "#e8f2f8", 0.42 * S);
    brush.line(tip[0] - 1 * S, tip[1] - 1 * S, tip[0] + 0.5 * S, tip[1] - 0.5 * S);
  }
}

function drawMantleAndShellOcclusion(toWorld, S) {
  // Deep occlusion shadow cast by the shell lip onto the neck and posterior body
  let occArc = [];
  for (let a = -72; a <= 76; a += 12) {
    let lx = 48 * S - (1 - cos(a)) * 22 * S;
    let ly = sin(a) * 35 * S;
    let p = toWorld(lx, ly);
    occArc.push([p[0], p[1], 0.85]);
  }
  setStrokeBrush("velvet", "#08090b", 2.4 * S);
  safeSpline(occArc, 0.45);

  // Fleshy Mantle Collar (puffy dark-rimmed cushion right behind the shell aperture lip)
  let collarArc = [];
  let collarHi = [];
  for (let a = -68; a <= 70; a += 10) {
    let lx = 44 * S - (1 - cos(a)) * 19 * S;
    let ly = sin(a) * 33 * S;
    let p = toWorld(lx, ly);
    let pHi = toWorld(lx + 1.8 * S, ly - 1.2 * S);
    collarArc.push([p[0], p[1], 0.9]);
    collarHi.push([pHi[0], pHi[1], 0.7]);
  }
  setStrokeBrush("velvet", "#2b2722", 1.8 * S);
  safeSpline(collarArc, 0.45);
  setStrokeBrush("cpencil", "#544c40", 0.95 * S);
  safeSpline(collarArc, 0.45);
  setStrokeBrush("glint", "#aebec9", 0.42 * S);
  safeSpline(collarHi.slice(1, collarHi.length - 2), 0.45);
}

// ============================================================================
// HYPERREAL 3D MOTTLED AMBER SHELL (Cornu aspersum Helicoid)
// ============================================================================

function drawMottledAmberShell(toWorld, heading, S, seedOff, shellTilt) {
  // The shell sits centered over (-18*S, +8*S) in local snail coordinates.
  // In a dextral garden snail, the spire/apex points backward and to the right (+Y),
  // while the broad body whorl arches over the left/top and opens forward over the neck (+X).
  let shellOrigin = toWorld(-18 * S, 8 * S);
  let ox = shellOrigin[0];
  let oy = shellOrigin[1];

  // Shell orientation angle in world space
  let shAng = heading + shellTilt;

  // 3D Basis vectors for the shell's columellar axis (spire axis) and radial cross-sections:
  // Spire vector A points backward-right in local snail frame (~ 142 deg from +X forward)
  let spireDirDeg = shAng + 142;
  let Ax = cos(spireDirDeg);
  let Ay = sin(spireDirDeg);
  let Az = -0.18; // Apex tilts slightly downward toward the right flank

  // Orthogonal vector U in the canvas plane (perpendicular to spire axis, pointing toward left/front)
  let Ux = cos(spireDirDeg - 90);
  let Uy = sin(spireDirDeg - 90);
  let Uz = 0.0;

  // Orthogonal vector V pointing mostly UP (+Z toward viewer) and slightly forward-left
  let Vx = cos(spireDirDeg) * 0.18;
  let Vy = sin(spireDirDeg) * 0.18;
  let Vz = 0.98;

  const totalWhorls = 3.55;
  const maxTheta = totalWhorls * 360;

  // Maps normalized spiral progress u in [0 (apex), 1 (aperture lip)] and tube cross-section angle phi in [-115, +115]
  // to 3D world position (x, y, z) and 3D surface normal (nx, ny, nz)
  const evalShellPoint = (u, phiDeg) => {
    let theta = u * maxTheta;

    // Position of tube centerline along the spire axis: u=0 is apex tip, u=1 is body whorl
    let spireDist = (1.0 - pow(u, 1.28)) * 78 * S - 14 * S;

    // Spiral radius from columellar axis
    let spiralR = (2.2 + 36.0 * pow(u, 1.48)) * S;

    // Tube cross-section radius (plump globose expansion on the body whorl)
    let tubeR = (1.8 + 54.0 * pow(u, 1.56)) * S;
    // Slight elongation of the body whorl toward the aperture lip
    let axialStretch = 1.0 + 0.14 * pow(u, 2.0);

    // Spiral angle around the axis (dextral coiling)
    // At u=1 (aperture), we want the tube centered on the left/upper side (cos(theta) = +1 in U)
    let coilAng = (1.0 - u) * maxTheta;
    let cCoil = cos(coilAng);
    let sCoil = sin(coilAng);

    // Radial outward direction from spire axis for this whorl
    // In canvas projection, full spiral revolution folds smoothly into the upper-visible hemisphere
    // so every whorl of the spire is clearly nested and visible from above!
    let radU = (0.35 + 0.65 * pow(u, 0.7)) * cos(coilAng * 0.18);
    let radV = 0.85;

    // Center of tube cross-section at progress u
    let cx = ox + Ax * spireDist + Ux * (spiralR * (u * 0.95 - 0.25));
    let cy = oy + Ay * spireDist + Uy * (spiralR * (u * 0.95 - 0.25));
    let cz = Az * spireDist + Vz * spiralR * 0.35;

    // Cross-section angle phiDeg:
    // phi = -95 deg is the inner suture (towards the apex along -A)
    // phi = 0 deg is the high dorsal dome facing +Z (viewer) and upper-left light
    // phi = +95 deg is the outer/anterior periphery (towards +U / aperture)
    let sPhi = sin(phiDeg);
    let cPhi = cos(phiDeg);

    // Outward direction of the whorl dome in 2D/3D
    let outDirDeg = spireDirDeg + 180 - (1 - u) * 28;
    let Ox = cos(outDirDeg) * 0.68 + Ux * 0.48;
    let Oy = sin(outDirDeg) * 0.68 + Uy * 0.48;

    // Slight flare right at the aperture lip (u > 0.96)
    let lipFlare = (u > 0.96) ? 1.0 + 0.06 * map(u, 0.96, 1.0, 0, 1) : 1.0;

    let px = cx + (Ox * sPhi * axialStretch + Ux * cPhi * 0.22) * tubeR * lipFlare;
    let py = cy + (Oy * sPhi * axialStretch + Uy * cPhi * 0.22) * tubeR * lipFlare;
    let pz = cz + cPhi * tubeR;

    // 3D Surface normal for hyperreal lighting and specular reflections
    let nx = Ox * sPhi + Ux * cPhi * 0.18;
    let ny = Oy * sPhi + Uy * cPhi * 0.18;
    let nz = cPhi;
    let nLen = sqrt(nx * nx + ny * ny + nz * nz) || 1;
    nx /= nLen;
    ny /= nLen;
    nz /= nLen;

    return { x: px, y: py, z: pz, nx, ny, nz };
  };

  // --------------------------------------------------------------------------
  // PASS 1: OPAQUE DARK UMBER BASE FOOTPRINT OF THE SHELL
  // --------------------------------------------------------------------------
  let outerBoundary = [];
  let innerBoundary = [];
  for (let i = 0; i <= 48; i++) {
    let u = i / 48;
    let pOut = evalShellPoint(u, 96);
    let pIn = evalShellPoint(u, -92);
    outerBoundary.push([pOut.x, pOut.y]);
    innerBoundary.unshift([pIn.x, pIn.y]);
  }
  let lipCurve = [];
  for (let phi = -90; phi <= 94; phi += 15) {
    let pLip = evalShellPoint(1.0, phi);
    lipCurve.push([pLip.x, pLip.y]);
  }
  let shellSilhouette = outerBoundary.concat(lipCurve.reverse()).concat(innerBoundary);

  brush.noStroke();
  brush.wash("#1a1109", 255);
  brush.beginShape(0.25);
  for (let p of shellSilhouette) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noWash();

  // --------------------------------------------------------------------------
  // PASS 2: RICH MOTTLED AMBER, BURNT UMBER & EARTH OCHRE UNDERPAINTING
  // --------------------------------------------------------------------------
  // Dawn light direction in 3D: from upper-left (-55 deg in XY, +0.62 in Z)
  let Lx = cos(-55) * 0.78;
  let Ly = sin(-55) * 0.78;
  let Lz = 0.62;

  let baseSteps = 115;
  for (let i = 0; i <= baseSteps; i++) {
    let u = i / baseSteps;
    for (let band = -4; band <= 4; band++) {
      let phi1 = map(band - 0.5, -4.5, 4.5, -88, 92);
      let phi2 = map(band + 0.5, -4.5, 4.5, -88, 92);
      let p1 = evalShellPoint(u, phi1);
      let p2 = evalShellPoint(u, phi2);

      let ndotl = constrain(p1.nx * Lx + p1.ny * Ly + p1.nz * Lz, 0, 1);
      // Ambient occlusion in the suture (band === -4) and underside (band === 4)
      let sutureAO = (band === -4) ? 0.35 : (band === 4 ? 0.5 : 1.0);
      let lightVal = ndotl * sutureAO;

      // Spiral banding + axial flame mottling
      let isDarkBand = (band === -2 || band === 0 || band === 2 || band === 3);
      let flameNoise = noise(u * 26 + band * 0.45 + seedOff, band * 0.7 + seedOff);
      let isCreamFlame = flameNoise > 0.61 && u > 0.18;

      let col;
      if (u < 0.16) {
        // Early apex whorls: pearlescent horn / calcified grey-amber
        col = lerpHex("#2b231b", "#a89c8a", lightVal * 0.9);
      } else if (isCreamFlame) {
        // Calcified pale ochre / bone axial zig-zag flame
        col = lerpHex("#59462d", "#dcc8a4", lightVal * 0.95);
      } else if (isDarkBand) {
        // Deep espresso / chestnut spiral band
        col = lerpHex("#140c06", "#6e431c", lightVal * 0.9);
      } else {
        // Glowing golden amber & raw sienna zone
        col = lerpHex("#2e1b0b", "#c98b3c", lightVal * 0.95);
      }

      setStrokeBrush("velvet", col, (0.5 + 1.35 * u) * S);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }
  }

  // --------------------------------------------------------------------------
  // PASS 3: FINE CURVED TRANSVERSE GROWTH STRIAE (THE SHELL'S RIBS & MOTTLING)
  // --------------------------------------------------------------------------
  let striaeCount = 210;
  for (let i = 2; i <= striaeCount; i++) {
    let u = i / striaeCount;
    let ribPts = [];
    let flamePts = [];

    // Sample cross-section arc for this growth rib
    let phiSamples = 8;
    for (let k = 0; k <= phiSamples; k++) {
      let phi = map(k, 0, phiSamples, -90, 92);
      // Slight natural forward wave of the growth line
      let uWave = u + sin(k / phiSamples * 180) * 0.008;
      let pt = evalShellPoint(constrain(uWave, 0, 1), phi);
      let p = sin(map(k, 0, phiSamples, 15, 165));
      ribPts.push([pt.x, pt.y, p * 0.85]);

      // Check if an axial cream/ochre flame marking runs along this part of the rib
      let zig = noise(u * 34 + sin(phi * 2.5) * 0.8 + seedOff, phi * 0.04 + seedOff);
      if (zig > 0.57 && k >= 1 && k <= phiSamples - 1) {
        flamePts.push([pt.x, pt.y, p * 0.9]);
      }
    }

    // Draw dark growth stria groove
    let ribCol = (i % 3 === 0) ? "#1a1007" : (i % 3 === 1 ? "#382210" : "#5c3918");
    let ribBrush = (i % 4 === 0) ? "pen" : "2B";
    setStrokeBrush(ribBrush, ribCol, (0.22 + 0.36 * u) * S);
    safeSpline(ribPts, 0.5);

    // Highlighted golden-amber ridge immediately beside the growth groove
    if (i % 2 === 0 && u > 0.12) {
      let hiRib = ribPts.slice(1, ribPts.length - 1).map(p => [p[0] + Lx * 1.1 * S, p[1] + Ly * 1.1 * S, p[2]]);
      let amberCol = random(["#9e682a", "#bd8136", "#d69b49", "#b07b3b"]);
      setStrokeBrush("cpencil", amberCol, (0.3 + 0.48 * u) * S);
      safeSpline(hiRib, 0.5);
    }

    // Axial cream/bone/ochre flame markings (characteristic Cornu aspersum mottling)
    if (flamePts.length >= 3 && u > 0.16) {
      let creamCol = random(["#bfa882", "#d9c5a0", "#e8d8b8", "#a8916b"]);
      setStrokeBrush((i % 2 === 0) ? "cpencil" : "filament", creamCol, (0.32 + 0.45 * u) * S);
      safeSpline(flamePts, 0.45);
    }
  }

  // --------------------------------------------------------------------------
  // PASS 4: SPIRAL CHESTNUT BANDS & DEEP SUTURE INDENTATION
  // --------------------------------------------------------------------------
  // Deep spiral suture line where each whorl tucks under the preceding whorl
  let suturePts = [];
  let sutureLipHi = [];
  for (let i = 0; i <= 90; i++) {
    let u = i / 90;
    let pSut = evalShellPoint(u, -90);
    let pSubHi = evalShellPoint(u, -74);
    suturePts.push([pSut.x, pSut.y, constrain(0.3 + 0.7 * u, 0.3, 1.0)]);
    sutureLipHi.push([pSubHi.x, pSubHi.y, constrain(0.25 + 0.65 * u, 0.2, 0.9)]);
  }
  setStrokeBrush("velvet", "#0f0904", 1.35 * S);
  safeSpline(suturePts, 0.5);
  setStrokeBrush("rotring", "#090503", 0.58 * S);
  safeSpline(suturePts, 0.5);

  // Calcified pale rim right below the suture line
  setStrokeBrush("filament", "#cbb793", 0.42 * S);
  safeSpline(sutureLipHi, 0.5);

  // Broken dark spiral bands wrapping around the whorls
  const darkBandPhis = [-52, -16, 22, 58];
  for (let bPhi of darkBandPhis) {
    let segStart = 12;
    while (segStart < 95) {
      let segLen = int(random(5, 14));
      let segEnd = min(98, segStart + segLen);
      let bandPts = [];
      for (let k = segStart; k <= segEnd; k++) {
        let u = k / 100;
        let pt = evalShellPoint(u, bPhi + (noise(k * 0.2, bPhi) - 0.5) * 8);
        bandPts.push([pt.x, pt.y, 0.75 * u]);
      }
      setStrokeBrush("2B", random(["#1c1108", "#2b1a0c", "#3d2511"]), (0.45 + 0.45 * (segStart / 100)) * S);
      safeSpline(bandPts, 0.5);
      segStart = segEnd + int(random(2, 6));
    }
  }

  // --------------------------------------------------------------------------
  // PASS 5: PEARLESCENT PROTOCONCH (APEX) & THICKENED APERTURE LIP
  // --------------------------------------------------------------------------
  // Tiny coiled protoconch apex at u = 0..0.14
  let apexSpiral = [];
  for (let i = 0; i <= 28; i++) {
    let t = i / 28;
    let pApex = evalShellPoint(t * 0.14, -20 + sin(t * 720) * 45);
    apexSpiral.push([pApex.x, pApex.y, 0.8]);
  }
  setStrokeBrush("pen", "#261d15", 0.42 * S);
  safeSpline(apexSpiral, 0.55);

  let apexTip = evalShellPoint(0.02, 0);
  setStrokeBrush("glint", "#e6dfd3", 0.58 * S);
  brush.line(apexTip.x - 1.5 * S, apexTip.y - 1.5 * S, apexTip.x + 1.5 * S, apexTip.y + 0.5 * S);

  // Thickened calcified Aperture Lip at u = 0.985..1.0
  let lipOuter = [];
  let lipInner = [];
  for (let phi = -88; phi <= 88; phi += 10) {
    let p1 = evalShellPoint(0.995, phi);
    let p2 = evalShellPoint(0.972, phi);
    let p = sin(map(phi, -88, 88, 20, 160));
    lipOuter.push([p1.x, p1.y, p]);
    lipInner.push([p2.x, p2.y, p * 0.8]);
  }
  setStrokeBrush("velvet", "#362515", 1.2 * S);
  safeSpline(lipInner, 0.45);
  setStrokeBrush("cpencil", "#ccb692", 0.95 * S);
  safeSpline(lipOuter, 0.45);
  setStrokeBrush("glint", "#ebe0cc", 0.48 * S);
  safeSpline(lipOuter.slice(2, lipOuter.length - 3), 0.45);

  // --------------------------------------------------------------------------
  // PASS 6: WET GLOSS SPECULAR REFLECTIONS & IRIDESCENT DAWN SHEEN ON SHELL
  // --------------------------------------------------------------------------
  // A wet shell at dawn catches a curved specular window across the upper-left dome of each whorl
  // broken into crisp transverse specular dashes by the shell's growth striae!
  for (let i = 8; i <= 155; i++) {
    let u = i / 160;
    // Primary specular track sits around phi = -28 to +12 deg (facing the upper-left dawn sky)
    let specCenterPhi = -12 + sin(u * 360 * 2.5) * 6;
    let specSpan = 16 + 10 * sin(i * 23);

    // Modulate along u so the reflection forms luminous window bands across each whorl
    let windowMask = sin(u * 180) * (0.55 + 0.45 * cos(u * 360 * 3.2));
    if (windowMask > 0.22) {
      let pA = evalShellPoint(u, specCenterPhi - specSpan * 0.5);
      let pB = evalShellPoint(u, specCenterPhi);
      let pC = evalShellPoint(u, specCenterPhi + specSpan * 0.5);

      // Subtle iridescent violet/green edge tint around the wet reflection
      if (i % 3 === 0) {
        let iridCol = (i % 6 === 0) ? "#9682a8" : "#80a390";
        setStrokeBrush("filament", iridCol, (0.28 + 0.35 * u) * S);
        safeSpline([[pA.x, pA.y, 0.4], [pB.x, pB.y, 0.8], [pC.x, pC.y, 0.4]], 0.5);
      }

      // Bright dawn sky reflection
      let glintCol = (windowMask > 0.58) ? "#f2f8fc" : "#bfd0de";
      setStrokeBrush("glint", glintCol, (0.3 + 0.48 * u * windowMask) * S);
      safeSpline([[pA.x, pA.y, 0.3], [pB.x, pB.y, 0.95], [pC.x, pC.y, 0.3]], 0.5);
    }

    // Secondary rim reflection along the outer lower periphery (bounce light from wet slate trails)
    if (u > 0.35 && i % 2 === 0) {
      let pRim1 = evalShellPoint(u, 68);
      let pRim2 = evalShellPoint(u, 82);
      setStrokeBrush("filament", "#8799a6", 0.32 * S);
      brush.line(pRim1.x, pRim1.y, pRim2.x, pRim2.y);
    }
  }

  // Longitudinal specular streak tying the wet gloss across the main body whorl dome
  for (let phi of [-18, -8, 2]) {
    let glossPts = [];
    for (let k = 58; k <= 94; k += 2) {
      let u = k / 100;
      let pt = evalShellPoint(u, phi + sin(k * 18) * 2.5);
      let p = sin(map(k, 58, 94, 15, 165));
      glossPts.push([pt.x, pt.y, p * 0.85]);
    }
    setStrokeBrush("glint", (phi === -8) ? "#f5faff" : "#cfe0ec", (phi === -8 ? 0.52 : 0.36) * S);
    safeSpline(glossPts, 0.5);
  }
}

// ============================================================================
// 4. FINAL DAWN DEW MICRO-DROPLETS & IRIDESCENT GLINTS
// ============================================================================

function drawFinalDewAndGlints() {
  // Tiny condensation droplets on the cold slate catching dawn light
  for (let i = 0; i < 140; i++) {
    let x = random(30, width - 30);
    let y = random(30, height - 30);

    // Avoid placing slate droplets right on top of the two snails
    if (dist(x, y, 455, 665) < 185) continue;
    if (dist(x, y, 815, 445) < 165) continue;

    let r = random(1.2, 3.2);
    // Dark underside of water bead
    setStrokeBrush("pen", "#040507", r * 0.45);
    brush.line(x - r * 0.5, y + r * 0.4, x + r * 0.5, y + r * 0.4);

    // Crisp upper-left highlight on water bead
    let hiCol = random(["#9eb0bd", "#c6d6e3", "#e8f2fa", "#9884ab", "#84a895"]);
    setStrokeBrush("glint", hiCol, r * 0.25);
    brush.line(x - r * 0.4, y - r * 0.3, x + r * 0.2, y - r * 0.4);
  }

  // Delicate mucus micro-bridge / cloud-chamber wisp in the charged space between the two snails
  let bridgePts = [
    [585, 595, 0.3],
    [618, 568, 0.7],
    [648, 542, 0.85],
    [675, 518, 0.65],
    [702, 498, 0.25]
  ];
  setStrokeBrush("filament", "#867099", 0.38);
  safeSpline(bridgePts.map(p => [p[0] - 1.2, p[1] + 1.2, p[2]]), 0.5);
  setStrokeBrush("filament", "#729482", 0.38);
  safeSpline(bridgePts.map(p => [p[0] + 1.2, p[1] - 1.2, p[2]]), 0.5);
  setStrokeBrush("glint", "#e6f0f7", 0.32);
  safeSpline(bridgePts, 0.5);
}

