// Transform crab-local coordinates to global canvas coordinates
function crabPt(lx, ly) {
  const rad = (CRAB_ROT * Math.PI) / 180;
  const c = Math.cos(rad);
  const s = Math.sin(rad);
  return [
    CRAB_CX + lx * c - ly * s,
    CRAB_CY + lx * s + ly * c
  ];
}

// Helper: filter duplicate/too-close points for clean polygon fills
function cleanPts(pts, minDist = 2.0) {
  if (!pts || pts.length < 3) return pts;
  const out = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    const prev = out[out.length - 1];
    const dx = pts[i][0] - prev[0];
    const dy = pts[i][1] - prev[1];
    if (Math.hypot(dx, dy) >= minDist) {
      out.push(pts[i]);
    }
  }
  if (out.length > 2) {
    const first = out[0];
    const last = out[out.length - 1];
    if (Math.hypot(first[0] - last[0], first[1] - last[1]) < minDist) {
      out.pop();
    }
  }
  return out;
}

// Helper: Watercolor fill shape (soft edge bleed & organic pigment texture)
function fillShape(pts, col, alpha, bleed = 0.14, tex = 0.35, border = 0.25, curv = 0.25) {
  const cp = cleanPts(pts);
  if (cp.length < 3) return;
  brush.noField();
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < cp.length; i++) {
    brush.vertex(cp[i][0], cp[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

// Helper: Smooth Gongbi wash layer (fast, even glazing without heavy edge bloom)
function washShape(pts, col, alpha, curv = 0.25) {
  const cp = cleanPts(pts);
  if (cp.length < 3) return;
  brush.noField();
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, alpha);
  brush.beginShape(curv);
  for (let i = 0; i < cp.length; i++) {
    brush.vertex(cp[i][0], cp[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

// Helper: Generate ellipse polygon points
function ellipsePts(cx, cy, rx, ry, n = 36, rotDeg = 0) {
  const pts = [];
  const rot = (rotDeg * Math.PI) / 180;
  const cr = Math.cos(rot);
  const sr = Math.sin(rot);
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const ex = Math.cos(a) * rx;
    const ey = Math.sin(a) * ry;
    pts.push([
      cx + ex * cr - ey * sr,
      cy + ex * sr + ey * cr
    ]);
  }
  return pts;
}

// Helper: Generate 12-lobed Song Dynasty mallow-rim dish points
function lobedDishPts(cx, cy, rx, ry, lobes = 12, lobeDepth = 0.022, n = 120) {
  const pts = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    // Soft mallow petal undulation with narrow notches
    const wave = 1.0 + lobeDepth * Math.abs(Math.sin((a * lobes) / 2));
    pts.push([
      cx + Math.cos(a) * rx * wave,
      cy + Math.sin(a) * ry * wave
    ]);
  }
  return pts;
}

// Helper: Stroke a closed or open path with iron-wire modulation
function strokePath(pts, brushName, col, weight, closed = false, curv = 0.25) {
  const cp = cleanPts(pts, 1.5);
  if (cp.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(brushName, col, weight);
  if (closed && cp.length >= 3) {
    brush.beginShape(curv);
    for (let i = 0; i < cp.length; i++) {
      brush.vertex(cp[i][0], cp[i][1]);
    }
    brush.endShape(true);
  } else {
    brush.spline(cp, curv);
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7391);
  noiseSeed(7391);

  // Add a custom ultra-fine Gongbi iron-wire brush (Tiexianmiao)
  brush.add("ironwire", {
    type: "default",
    weight: 0.42,
    scatter: 0.03,
    sharpness: 0.88,
    grain: 0.18,
    opacity: 235,
    spacing: 0.12,
    pressure: [0.75, 1.08, 0.78],
    noise: 0.2
  });

  // Add a soft Gongbi shader brush for delicate pigment gradation
  brush.add("fenran", {
    type: "default",
    weight: 1.6,
    scatter: 0.35,
    sharpness: 0.25,
    grain: 0.45,
    opacity: 45,
    spacing: 0.2,
    pressure: [0.3, 1.0, 0.3],
    noise: 0.35
  });

  // Add a crisp specular highlight brush
  brush.add("glint", {
    type: "default",
    weight: 0.55,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 0.1,
    opacity: 245,
    spacing: 0.1,
    pressure: [0.4, 1.15, 0.4],
    noise: 0.1
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.silkBase);

  // 1. Aged Silk Ground (Juanben)
  drawSilkGround();

  // 2. Small Celadon Vinegar Saucer with Ginger Slivers (Upper-Left)
  drawVinegarSaucer();

  // 3. Main Pale Celadon Dish (Song Dynasty Lobed Plate)
  drawCeladonDish();

  // 4. Crab Shadow & Warm Reflected Glow on the Wet Porcelain
  drawCrabShadowAndReflection();

  // 5. Condensation Droplets on the Celadon Plate (Under/Around Crab)
  drawPlateCondensation();

  // 6. Steamed Hairy Crab: Posterior Abdomen & Walking Legs (P5 -> P2)
  drawPosteriorAbdomen();
  drawAllWalkingLegs();

  // 7. Steamed Hairy Crab: The Two Great Hairy Chelipeds (Claws & Velvety Mittens)
  drawCheliped(true);  // Left claw
  drawCheliped(false); // Right claw

  // 8. Steamed Hairy Crab: Sculpted Carapace, Rostrum, Eyes & Shell Droplets
  drawCarapace();

  // 9. Scholarly Cinnabar Seal in the Lower-Left Margin
  drawScholarSeal();

  noLoop();
}

// ============================================================================
// 1. AGED SILK GROUND
// ============================================================================
function drawSilkGround() {
  // Large atmospheric tea-toned watercolor mottling
  const mottles = [
    { x: 220, y: 210, rx: 320, ry: 260, col: PAL.silkWarm, a: 28 },
    { x: 980, y: 190, rx: 340, ry: 290, col: PAL.silkDark, a: 22 },
    { x: 180, y: 960, rx: 360, ry: 300, col: PAL.silkDark, a: 26 },
    { x: 1020, y: 1010, rx: 330, ry: 280, col: PAL.silkWarm, a: 30 },
    { x: 580, y: 540, rx: 490, ry: 450, col: PAL.silkLight, a: 26 },
    { x: 350, y: 650, rx: 280, ry: 240, col: PAL.silkWarm, a: 20 },
    { x: 840, y: 380, rx: 260, ry: 220, col: PAL.silkLight, a: 22 }
  ];

  for (const m of mottles) {
    fillShape(ellipsePts(m.x, m.y, m.rx, m.ry, 28), m.col, m.a, 0.42, 0.55, 0.15, 0.3);
  }

  // Fine woven silk threads (horizontal weft & vertical warp)
  brush.noFill();
  brush.noWash();
  for (let y = 12; y < 1200; y += 14) {
    const col = y % 28 === 0 ? PAL.silkThread : PAL.silkLight;
    brush.set("2H", col, 0.22);
    const x1 = random(0, 40);
    const x2 = random(1160, 1200);
    brush.line(x1, y + random(-0.8, 0.8), x2, y + random(-0.8, 0.8));
  }
  for (let x = 16; x < 1200; x += 22) {
    const col = x % 44 === 0 ? PAL.silkThread : PAL.silkWarm;
    brush.set("2H", col, 0.18);
    brush.line(x + random(-0.6, 0.6), random(0, 50), x + random(-0.6, 0.6), random(1150, 1200));
  }

  // Subtle age patina & foxing specks near corners
  for (let i = 0; i < 65; i++) {
    const edgeBias = random() < 0.75;
    const sx = edgeBias ? (random() < 0.5 ? random(20, 260) : random(940, 1180)) : random(40, 1160);
    const sy = edgeBias ? (random() < 0.5 ? random(20, 260) : random(940, 1180)) : random(40, 1160);
    brush.set("spray", PAL.silkDark, random(0.3, 0.7));
    brush.line(sx, sy, sx + random(4, 14), sy + random(-6, 6));
  }
}

// ============================================================================
// 2. SMALL VINEGAR & GINGER SAUCER (UPPER-LEFT)
// ============================================================================
function drawVinegarSaucer() {
  // Soft contact shadow on silk
  for (let i = 3; i >= 1; i--) {
    washShape(
      ellipsePts(SAUCER_CX + 8 + i * 4, SAUCER_CY + 12 + i * 5, SAUCER_RX + i * 6, SAUCER_RY + i * 6, 36),
      "#9e8d70",
      18,
      0.25
    );
  }
  fillShape(
    ellipsePts(SAUCER_CX + 6, SAUCER_CY + 9, SAUCER_RX + 2, SAUCER_RY + 2, 36),
    "#786950",
    32,
    0.2,
    0.3,
    0.2
  );

  // Outer celadon saucer body (12-lobed matching dish)
  const saucerOuter = lobedDishPts(SAUCER_CX, SAUCER_CY, SAUCER_RX, SAUCER_RY, 12, 0.018, 72);
  fillShape(saucerOuter, PAL.celadonBase, 195, 0.05, 0.25, 0.2);
  washShape(saucerOuter, PAL.celadonLight, 85);

  // Shaded cavetto (inner recessed slope)
  const saucerWell = ellipsePts(SAUCER_CX, SAUCER_CY, SAUCER_RX * 0.77, SAUCER_RY * 0.77, 40);
  fillShape(saucerWell, PAL.celadonMid, 120, 0.08, 0.3, 0.25);

  // Subtle crackle lines in saucer rim
  brush.set("ironwire", PAL.crackleGrey, 0.24);
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * 360 + random(-8, 8);
    const r1 = SAUCER_RX * 0.75;
    const r2 = SAUCER_RX * 0.97;
    const x1 = SAUCER_CX + cos(a) * r1;
    const y1 = SAUCER_CY + sin(a) * (r1 * (SAUCER_RY / SAUCER_RX));
    const x2 = SAUCER_CX + cos(a + random(-6, 6)) * r2;
    const y2 = SAUCER_CY + sin(a + random(-6, 6)) * (r2 * (SAUCER_RY / SAUCER_RX));
    brush.line(x1, y1, x2, y2);
  }

  // Chinkiang Black Vinegar Pool (layered amber -> mahogany -> deep ink-sepia)
  const vinR1 = SAUCER_RX * 0.68;
  const vinR2 = SAUCER_RY * 0.68;
  fillShape(ellipsePts(SAUCER_CX, SAUCER_CY, vinR1, vinR2, 40), PAL.vinegarGlow, 150, 0.06, 0.25, 0.3);
  fillShape(ellipsePts(SAUCER_CX, SAUCER_CY, vinR1 * 0.93, vinR2 * 0.93, 40), PAL.vinegarRim, 175, 0.05, 0.25, 0.2);
  fillShape(ellipsePts(SAUCER_CX + 1, SAUCER_CY + 1, vinR1 * 0.84, vinR2 * 0.84, 36), PAL.vinegarMid, 200, 0.05, 0.2, 0.2);
  fillShape(ellipsePts(SAUCER_CX + 2, SAUCER_CY + 2, vinR1 * 0.66, vinR2 * 0.66, 32), PAL.vinegarCore, 215, 0.06, 0.2, 0.15);

  // Submerged ginger slivers (warm amber glow beneath surface)
  const gingerCount = 19;
  const slivers = [];
  for (let i = 0; i < gingerCount; i++) {
    const ang = random(-180, 180);
    const distFromC = random(0, 26);
    const cx = SAUCER_CX + cos(ang) * distFromC * 0.9;
    const cy = SAUCER_CY + sin(ang) * distFromC * 0.85;
    const len = random(36, 68);
    const wid = random(3.2, 5.2);
    const curve = random(-10, 10);
    slivers.push({ cx, cy, ang, len, wid, curve, submerged: i < 7 });
  }

  for (const s of slivers) {
    const aRad = (s.ang * Math.PI) / 180;
    const nx = -Math.sin(aRad);
    const ny = Math.cos(aRad);
    const dx = Math.cos(aRad);
    const dy = Math.sin(aRad);

    const pStart = [s.cx - dx * (s.len * 0.5), s.cy - dy * (s.len * 0.5)];
    const pMid = [s.cx + nx * s.curve, s.cy + ny * s.curve];
    const pEnd = [s.cx + dx * (s.len * 0.5), s.cy + dy * (s.len * 0.5)];

    const stripPoly = [
      [pStart[0] + nx * (s.wid * 0.35), pStart[1] + ny * (s.wid * 0.35)],
      [pMid[0] + nx * (s.wid * 0.55), pMid[1] + ny * (s.wid * 0.55)],
      [pEnd[0] + nx * (s.wid * 0.35), pEnd[1] + ny * (s.wid * 0.35)],
      [pEnd[0] - nx * (s.wid * 0.35), pEnd[1] - ny * (s.wid * 0.35)],
      [pMid[0] - nx * (s.wid * 0.55), pMid[1] - ny * (s.wid * 0.55)],
      [pStart[0] - nx * (s.wid * 0.35), pStart[1] - ny * (s.wid * 0.35)]
    ];

    if (s.submerged) {
      washShape(stripPoly, PAL.gingerShade, 145, 0.2);
      strokePath([pStart, pMid, pEnd], "ironwire", "#3b1c0a", 0.3, false, 0.3);
    } else {
      // Shadow in vinegar under top ginger sliver
      washShape(
        stripPoly.map(p => [p[0] + 1.5, p[1] + 2.0]),
        PAL.vinegarCore,
        150,
        0.2
      );
      washShape(stripPoly, PAL.gingerBase, 225, 0.2);
      // Translucent pale ivory center
      strokePath([pStart, pMid, pEnd], "glint", PAL.gingerLight, 0.85, false, 0.3);
      // Delicate iron-wire outline
      strokePath(stripPoly, "ironwire", "#47250e", 0.26, true, 0.2);
    }
  }

  // Glossy liquid meniscus specular arcs on the vinegar surface
  brush.set("glint", "#fff9eb", 0.55);
  brush.arc(SAUCER_CX, SAUCER_CY, vinR1 * 0.91, 200, 252);
  brush.set("glint", "#fff9eb", 0.38);
  brush.arc(SAUCER_CX, SAUCER_CY, vinR1 * 0.91, 258, 275);
  brush.arc(SAUCER_CX, SAUCER_CY, vinR1 * 0.52, 25, 68);

  // Saucer rim highlights & Gongbi iron-wire porcelain outlines
  strokePath(saucerWell, "ironwire", "#61705f", 0.32, true, 0.25);
  strokePath(saucerOuter, "ironwire", "#485446", 0.48, true, 0.25);
  brush.set("glint", "#ffffff", 0.55);
  brush.arc(SAUCER_CX, SAUCER_CY, SAUCER_RX * 0.97, 195, 255);
}

