// 3. MAIN PALE CELADON DISH (SONG DYNASTY LOBED PLATE)
// ============================================================================
function drawCeladonDish() {
  // Multi-layered soft cast shadow under the plate on silk
  for (let i = 5; i >= 1; i--) {
    const offX = 12 + i * 5;
    const offY = 18 + i * 6;
    washShape(
      ellipsePts(DISH_CX + offX, DISH_CY + offY, DISH_RX + i * 7, DISH_RY + i * 7, 48),
      "#968568",
      15,
      0.3
    );
  }
  fillShape(
    ellipsePts(DISH_CX + 10, DISH_CY + 14, DISH_RX + 4, DISH_RY + 4, 48),
    "#73644c",
    36,
    0.22,
    0.35,
    0.2
  );

  // Outer 12-lobed mallow-flower rim (Kuikou)
  const outerRim = lobedDishPts(DISH_CX, DISH_CY, DISH_RX, DISH_RY, 12, 0.019, 120);
  fillShape(outerRim, PAL.celadonBase, 210, 0.04, 0.28, 0.18, 0.25);
  washShape(outerRim, PAL.celadonLight, 95, 0.25);

  // Subtle shading on the lower-right rim flange and lighter glaze on upper-left
  washShape(
    ellipsePts(DISH_CX - 18, DISH_CY - 18, DISH_RX * 0.94, DISH_RY * 0.94, 48),
    PAL.celadonRim,
    70,
    0.3
  );
  washShape(
    ellipsePts(DISH_CX + 22, DISH_CY + 22, DISH_RX * 0.92, DISH_RY * 0.92, 48),
    PAL.celadonMid,
    65,
    0.3
  );

  // Radial petal-flute lines on the wide rim corresponding to the 12 lobes
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * 360;
    const rIn = 0.74;
    const rOut = 0.985;
    const x1 = DISH_CX + cos(a) * DISH_RX * rIn;
    const y1 = DISH_CY + sin(a) * DISH_RY * rIn;
    const x2 = DISH_CX + cos(a) * DISH_RX * rOut;
    const y2 = DISH_CY + sin(a) * DISH_RY * rOut;
    // Soft pooled celadon ridge shadow & highlight
    brush.set("fenran", PAL.celadonDeep, 0.45);
    brush.line(x1, y1, x2, y2);
    brush.set("glint", PAL.celadonRim, 0.4);
    brush.line(x1 + 2, y1 + 2, x2 + 2, y2 + 2);
  }

  // Recessed circular inner well (Cavetto)
  const wellRx = DISH_RX * 0.74;
  const wellRy = DISH_RY * 0.74;
  const wellPts = ellipsePts(DISH_CX, DISH_CY, wellRx, wellRy, 60);

  // Pooled jade-celadon glaze ring at the recessed well border
  fillShape(wellPts, PAL.celadonDeep, 95, 0.08, 0.35, 0.3, 0.3);
  fillShape(
    ellipsePts(DISH_CX + 6, DISH_CY + 6, wellRx * 0.96, wellRy * 0.96, 54),
    PAL.celadonLight,
    155,
    0.08,
    0.25,
    0.15,
    0.3
  );
  washShape(
    ellipsePts(DISH_CX - 10, DISH_CY - 10, wellRx * 0.85, wellRy * 0.85, 48),
    PAL.celadonRim,
    80,
    0.3
  );

  // Song Dynasty Ru-ware / Longquan Ice-Crackle Glaze Network (Kaipian)
  drawCeladonCrackle();

  // Crisp iron-wire outlines for the porcelain rim and inner well ring
  strokePath(wellPts, "ironwire", "#697a67", 0.36, true, 0.3);
  // Secondary inner bevel highlight ring
  brush.set("glint", "#f4f8f2", 0.5);
  brush.arc(DISH_CX, DISH_CY, wellRx * 0.99, 20, 145);
  brush.arc(DISH_CX, DISH_CY, wellRx * 1.01, 195, 315);

  // Outer rim double line (pale celadon unglazed biscuit/glaze edge + dark iron-wire contour)
  const innerLip = lobedDishPts(DISH_CX, DISH_CY, DISH_RX * 0.986, DISH_RY * 0.986, 12, 0.019, 120);
  strokePath(innerLip, "glint", "#f5f7f0", 0.55, true, 0.25);
  strokePath(outerRim, "ironwire", "#424f40", 0.58, true, 0.25);
}

function drawCeladonCrackle() {
  // Generate organic Voronoi-like crackle lines across the dish
  const rings = [0.22, 0.42, 0.60, 0.74, 0.88, 0.97];
  const prevNodes = [];

  for (let rIdx = 0; rIdx < rings.length; rIdx++) {
    const rr = rings[rIdx];
    const count = Math.floor(10 + rr * 18);
    const curNodes = [];
    for (let i = 0; i < count; i++) {
      const a = (i / count) * 360 + random(-7, 7);
      const radMod = rr + random(-0.03, 0.03);
      const x = DISH_CX + cos(a) * DISH_RX * radMod;
      const y = DISH_CY + sin(a) * DISH_RY * radMod;
      curNodes.push({ x, y, a });
    }

    // Connect circumferential crackles
    for (let i = 0; i < curNodes.length; i++) {
      if (random() < 0.72) {
        const n1 = curNodes[i];
        const n2 = curNodes[(i + 1) % curNodes.length];
        const isTea = random() < 0.35;
        brush.set("ironwire", isTea ? PAL.crackleTea : PAL.crackleGrey, random(0.18, 0.28));
        brush.line(n1.x, n1.y, n2.x, n2.y);
      }
    }

    // Connect radial crackles to previous ring
    if (prevNodes.length > 0) {
      for (const cn of curNodes) {
        if (random() < 0.65) {
          let best = prevNodes[0];
          let bestD = 9999;
          for (const pn of prevNodes) {
            const d = Math.hypot(cn.x - pn.x, cn.y - pn.y);
            if (d < bestD) {
              bestD = d;
              best = pn;
            }
          }
          if (bestD < 140) {
            const isTea = random() < 0.3;
            brush.set("ironwire", isTea ? PAL.crackleTea : PAL.crackleGrey, random(0.18, 0.3));
            brush.line(cn.x, cn.y, best.x, best.y);
          }
        }
      }
    }
    prevNodes.splice(0, prevNodes.length, ...curNodes);
  }
}

