// ============================================================================
function drawCrabShadowAndReflection() {
  // Subtle warm persimmon/amber reflection in the wet porcelain glaze beneath the crab
  const reflCarapace = ellipsePts(CRAB_CX + 6, CRAB_CY + 14, 155, 135, 36, CRAB_ROT);
  fillShape(reflCarapace, "#d98c5f", 32, 0.35, 0.3, 0.15, 0.3);

  const reflClawL = crabPt(-95, -165);
  const reflClawR = crabPt(95, -160);
  fillShape(ellipsePts(reflClawL[0] + 6, reflClawL[1] + 10, 75, 55, 24), "#d48559", 26, 0.35, 0.3, 0.15);
  fillShape(ellipsePts(reflClawR[0] + 6, reflClawR[1] + 10, 75, 55, 24), "#d48559", 26, 0.35, 0.3, 0.15);

  // Deep ambient occlusion shadow under the carapace body
  for (let i = 3; i >= 1; i--) {
    const shPts = ellipsePts(CRAB_CX + 8 + i * 3, CRAB_CY + 12 + i * 4, 112 + i * 12, 95 + i * 10, 36, CRAB_ROT);
    washShape(shPts, "#596153", 34, 0.3);
  }
  fillShape(
    ellipsePts(CRAB_CX + 8, CRAB_CY + 12, 108, 92, 36, CRAB_ROT),
    "#3d4237",
    68,
    0.18,
    0.35,
    0.2,
    0.3
  );
}

