// 5. CONDENSATION DROPLETS ON THE CELADON PLATE
// ============================================================================
function drawPlateCondensation() {
  // Generate droplets in the well around the crab and on the wide celadon rim
  const droplets = [
    // Inner well near claws (warm orange tint from shell reflection)
    { lx: -25, ly: -155, r: 8.5, warm: true },
    { lx: -45, ly: -142, r: 5.0, warm: true },
    { lx: 18, ly: -162, r: 7.2, warm: true },
    { lx: 42, ly: -148, r: 4.5, warm: true },
    { lx: -5, ly: -188, r: 6.0, warm: false },
    { lx: -165, ly: -150, r: 9.0, warm: true },
    { lx: -182, ly: -135, r: 4.8, warm: false },
    { lx: 175, ly: -142, r: 8.2, warm: true },
