  }

  for (const d of allDrops) {
    const [gx, gy] = crabPt(d.lx, d.ly);
    drawSingleDroplet(gx, gy, d.r, d.warm, false);
  }
}

function drawSingleDroplet(x, y, r, warmTint = false, onShell = false) {
  // 1. Cast shadow on lower-right
  const shCol = onShell ? "#521006" : "#627360";
  const shPts = ellipsePts(x + r * 0.28, y + r * 0.32, r * 0.95, r * 0.85, 16, 25);
  washShape(shPts, shCol, onShell ? 120 : 85, 0.3);

  // 2. Base droplet body
  const bodyPts = ellipsePts(x, y, r, r * 0.9, 18, -15);
  if (onShell) {
    washShape(bodyPts, "#b82812", 110, 0.3);
    washShape(
      ellipsePts(x + r * 0.18, y + r * 0.2, r * 0.65, r * 0.55, 14),
      "#ffb870",
      150,
      0.3
    );
  } else {
    washShape(bodyPts, warmTint ? "#b59b82" : "#96a894", 95, 0.3);
    // Refracted bright caustic on lower-right inside droplet
    washShape(
      ellipsePts(x + r * 0.2, y + r * 0.22, r * 0.65, r * 0.55, 14),
      warmTint ? "#f7dec3" : "#eef5ec",
      165,
      0.3
    );
  }

  // 3. Delicate meniscus edge
  brush.set("ironwire", onShell ? "#3d0b04" : "#556353", 0.22);
  brush.circle(x, y, r * 0.95, 0.05);

  // 4. Crisp specular highlight on upper-left & secondary bottom glint
  brush.set("glint", "#ffffff", Math.max(0.35, r * 0.11));
  brush.line(x - r * 0.42, y - r * 0.32, x - r * 0.18, y - r * 0.44);
  if (r > 5) {
    brush.set("glint", "#ffffff", 0.28);
    brush.line(x + r * 0.15, y + r * 0.52, x + r * 0.42, y + r * 0.38);
  }
}

