function drawLegShadow(leg) {
  const j = leg.joints.map(pt => crabPt(pt[0], pt[1]));
  // Shadow sits closer to the leg at the coxa and dactyl tip, and further away under the arched knee (merus/carpus)
  const offsets = [
    [6, 10],
    [16, 24],
    [18, 26],
    [12, 18],
    [3, 4]
  ];
  for (let s = 0; s < 4; s++) {
    const p1 = [j[s][0] + offsets[s][0], j[s][1] + offsets[s][1]];
    const p2 = [j[s + 1][0] + offsets[s + 1][0], j[s + 1][1] + offsets[s + 1][1]];
    const w = leg.widths[s + 1] * 0.95;
    const segPts = buildPodomerePts(p1, p2, w * 0.6, w, w * 0.55, leg.arch * 3);
    washShape(segPts, "#667060", 48, 0.3);
  }
}

// Construct anatomically accurate crab leg segment (podomere) polygon between p1 and p2
function buildPodomerePts(p1, p2, wStart, wMid, wEnd, dorsalBow = 5) {
  const dx = p2[0] - p1[0];
  const dy = p2[1] - p1[1];
  const len = Math.hypot(dx, dy);
  if (len < 1) return [];
  const ux = dx / len;
  const uy = dy / len;
  // Normal pointing toward dorsal/anterior arch
  const nx = -uy;
  const ny = ux;

  const steps = [0.0, 0.18, 0.42, 0.68, 0.88, 1.0];
  const profileDorsal = [wStart * 0.48, wMid * 0.52, wMid * 0.58, wMid * 0.48, wEnd * 0.45, wEnd * 0.35];
  const profileVentral = [wStart * 0.48, wMid * 0.46, wMid * 0.48, wMid * 0.44, wEnd * 0.42, wEnd * 0.35];

  const dorsalEdge = [];
  const ventralEdge = [];

  for (let i = 0; i < steps.length; i++) {
    const t = steps[i];
    const bow = Math.sin(t * Math.PI) * dorsalBow;
    const bx = p1[0] + dx * t + nx * bow;
    const by = p1[1] + dy * t + ny * bow;
    dorsalEdge.push([bx + nx * profileDorsal[i], by + ny * profileDorsal[i]]);
    ventralEdge.push([bx - nx * profileVentral[i], by - ny * profileVentral[i]]);
  }

  return [...dorsalEdge, ...ventralEdge.reverse()];
}

function drawSingleWalkingLeg(leg, isLeft) {
  const j = leg.joints.map(pt => crabPt(pt[0], pt[1]));
  const w = leg.widths;
  const bowSign = isLeft ? 1 : -1;

  // Render the 4 main segments: 0=Merus, 1=Carpus, 2=Propodus, 3=Dactylus
  for (let s = 0; s < 4; s++) {
    const p1 = j[s];
    const p2 = j[s + 1];
    const dx = p2[0] - p1[0];
    const dy = p2[1] - p1[1];
    const len = Math.hypot(dx, dy);
    const ux = dx / len;
    const uy = dy / len;
    const nx = -uy * bowSign;
    const ny = ux * bowSign;

    const wStart = s === 0 ? w[0] : w[s] * 0.72;
    const wMid = w[s + 1];
    const wEnd = s === 3 ? w[4] : w[s + 1] * 0.68;
    const bow = (s === 3 ? 7 : 5) * bowSign;

    // 1. Marginal Setae (Golden-brown sensory bristles) drawn slightly behind/around segment
    if (s >= 0) {
      drawPodomereBristles(p1, p2, wStart, wMid, wEnd, bow, s, isLeft, leg.bristleDensity);
    }

    // 2. Articulation hinge membrane at proximal socket
    if (s > 0) {
      const jointPts = ellipsePts(p1[0], p1[1], wStart * 0.58, wStart * 0.48, 14);
      washShape(jointPts, "#7d2912", 185, 0.25);
      washShape(ellipsePts(p1[0], p1[1], wStart * 0.36, wStart * 0.3, 12), PAL.shellCream, 180, 0.25);
      strokePath(jointPts, "ironwire", PAL.inkIron, 0.32, true, 0.25);
    }

    // 3. Base Gongbi Watercolor & Wash Layers for the Segment
    const fullPoly = buildPodomerePts(p1, p2, wStart, wMid, wEnd, bow);
    fillShape(fullPoly, PAL.persimmon, 215, 0.04, 0.28, 0.22, 0.25);

    // Dorsal half (richer cinnabar & vermilion along upper crest)
    const dorsalPoly = buildPodomerePts(
      [p1[0] + nx * (wStart * 0.12), p1[1] + ny * (wStart * 0.12)],
      [p2[0] + nx * (wEnd * 0.12), p2[1] + ny * (wEnd * 0.12)],
      wStart * 0.55,
      wMid * 0.58,
      wEnd * 0.55,
      bow
    );
    washShape(dorsalPoly, PAL.cinnabar, 165, 0.25);
    washShape(dorsalPoly, PAL.vermilion, 95, 0.25);

    // Ventral half (luminous pale amber & cream cylindrical belly)
    const ventralPoly = buildPodomerePts(
      [p1[0] - nx * (wStart * 0.15), p1[1] - ny * (wStart * 0.15)],
      [p2[0] - nx * (wEnd * 0.15), p2[1] - ny * (wEnd * 0.15)],
      wStart * 0.42,
      wMid * 0.46,
      wEnd * 0.4,
      bow * 0.7
    );
    washShape(ventralPoly, PAL.shellCream, 150, 0.25);

    // 4. Dactylus (Claw Tip) Special Translucent Amber & Dark Chitin Point
    if (s === 3) {
      const tipStart = [p1[0] + dx * 0.65 + nx * (bow * 0.6), p1[1] + dy * 0.65 + ny * (bow * 0.6)];
      const tipPoly = buildPodomerePts(tipStart, p2, wMid * 0.52, wMid * 0.35, wEnd, bow * 0.25);
      washShape(tipPoly, "#d9822b", 180, 0.2);
      const darkPoint = buildPodomerePts(
        [p1[0] + dx * 0.82 + nx * (bow * 0.3), p1[1] + dy * 0.82 + ny * (bow * 0.3)],
        p2,
        wMid * 0.32,
        wMid * 0.22,
        wEnd * 0.8,
        bow * 0.1
      );
      washShape(darkPoint, "#331408", 220, 0.2);
    }

    // 5. Longitudinal Anatomical Carina (Ridge) & Specular Wet Highlight
    const ridgePts = [];
    const highlightPts = [];
    for (let t = 0.08; t <= 0.92; t += 0.14) {
      const b = Math.sin(t * Math.PI) * bow;
      ridgePts.push([
        p1[0] + dx * t + (b / bow) * nx * Math.abs(bow) + nx * (wMid * 0.06),
        p1[1] + dy * t + (b / bow) * ny * Math.abs(bow) + ny * (wMid * 0.06)
      ]);
      highlightPts.push([
        p1[0] + dx * t + (b / bow) * nx * Math.abs(bow) - nx * (wMid * 0.08),
        p1[1] + dy * t + (b / bow) * ny * Math.abs(bow) - ny * (wMid * 0.08)
      ]);
    }
    strokePath(ridgePts, "cpencil", PAL.carmineDeep, 0.48, false, 0.3);
    strokePath(highlightPts, "glint", PAL.shellGlow, 0.55, false, 0.3);

    // 6. Dorsal Spinules on Merus (Segment 0)
    if (s === 0) {
      for (let t = 0.22; t <= 0.82; t += 0.15) {
        const b = Math.sin(t * Math.PI) * bow;
        const sx = p1[0] + dx * t + (b / bow) * nx * Math.abs(bow) + nx * (wMid * 0.52);
        const sy = p1[1] + dy * t + (b / bow) * ny * Math.abs(bow) + ny * (wMid * 0.52);
        brush.set("ironwire", PAL.inkIron, 0.38);
        brush.line(sx - ux * 3, sy - uy * 3, sx + nx * 3.5 + ux * 2, sy + ny * 3.5 + uy * 2);
        brush.line(sx + nx * 3.5 + ux * 2, sy + ny * 3.5 + uy * 2, sx + ux * 2.5, sy + uy * 2.5);
      }
    }

    // 7. Unbroken Gongbi Iron-Wire Outline
    strokePath(fullPoly, "ironwire", PAL.inkIron, 0.46, true, 0.25);
    // Internal longitudinal carina line in fine sepia
    strokePath(ridgePts, "ironwire", PAL.inkSoft, 0.28, false, 0.3);
  }
}

function drawPodomereBristles(p1, p2, wStart, wMid, wEnd, bow, segIdx, isLeft, density) {
  const dx = p2[0] - p1[0];
  const dy = p2[1] - p1[1];
  const len = Math.hypot(dx, dy);
  const ux = dx / len;
  const uy = dy / len;
  const nx = -uy;
  const ny = ux;

  // Carpus (1) and Propodus (2) have the densest bristle fringes in Eriocheir sinensis
  const count = Math.floor((segIdx === 1 || segIdx === 2 ? 28 : 16) * density);
  for (let i = 0; i < count; i++) {
    const t = map(i, 0, count - 1, 0.1, 0.9);
    const b = Math.sin(t * Math.PI) * bow;
    const curW = wMid * Math.sin(t * Math.PI * 0.85 + 0.2);

    // Upper/anterior fringe
    const bx1 = p1[0] + dx * t + nx * (b + curW * 0.46);
    const by1 = p1[1] + dy * t + ny * (b + curW * 0.46);
    const hLen1 = (segIdx === 1 || segIdx === 2 ? random(7, 14) : random(4, 9)) * Math.sin(t * Math.PI);
    const hx1 = bx1 + (nx * 0.72 + ux * 0.68) * hLen1;
    const hy1 = by1 + (ny * 0.72 + uy * 0.68) * hLen1;

    const col1 = i % 3 === 0 ? PAL.furGold : i % 2 === 0 ? PAL.furWarm : PAL.furMid;
    brush.set("ironwire", col1, random(0.22, 0.34));
    brush.line(bx1, by1, hx1, hy1);

    // Lower/posterior fringe (especially prominent on Propodus & Dactylus)
    if (segIdx >= 1 && i % 2 === 0) {
      const bx2 = p1[0] + dx * t + nx * (b - curW * 0.44);
      const by2 = p1[1] + dy * t + ny * (b - curW * 0.44);
      const hLen2 = random(5, 11) * Math.sin(t * Math.PI);
      const hx2 = bx2 + (-nx * 0.7 + ux * 0.7) * hLen2;
      const hy2 = by2 + (-ny * 0.7 + uy * 0.7) * hLen2;
      brush.set("ironwire", i % 4 === 0 ? PAL.furGold : PAL.furMid, random(0.2, 0.32));
      brush.line(bx2, by2, hx2, hy2);
    }
  }
}

// ============================================================================
// 7. THE TWO GREAT HAIRY CHELIPEDS (CLAWS & VELVETY MITTENS)
// ============================================================================
function drawCheliped(isLeft) {
  const s = isLeft ? -1 : 1;

  // 1. Cast shadow of cheliped on the celadon plate
  const shPalm = crabPt(s * 95 + 10, -192 + 16);
  const shCarp = crabPt(s * 132 + 12, -148 + 18);
  washShape(ellipsePts(shCarp[0], shCarp[1], 36, 28, 20), "#5e6959", 55, 0.3);
  washShape(ellipsePts(shPalm[0], shPalm[1], 56, 34, 24), "#5e6959", 58, 0.3);

  // 2. MERUS (Arm emerging from beneath anterolateral carapace)
  const merusPts = [
    crabPt(s * 68, -62),
    crabPt(s * 118, -96),
    crabPt(s * 144, -128),
    crabPt(s * 116, -142),
    crabPt(s * 84, -108),
    crabPt(s * 56, -78)
  ];
  fillShape(merusPts, PAL.persimmon, 220, 0.05, 0.3, 0.2);
  washShape(
    [crabPt(s * 72, -66), crabPt(s * 136, -124), crabPt(s * 124, -134), crabPt(s * 64, -74)],
    PAL.cinnabar,
    150
  );
  strokePath(merusPts, "ironwire", PAL.inkIron, 0.48, true, 0.25);

  // 3. CARPUS (Sculpted Wrist with Prominent Inner Spine)
  const carpusPts = [
    crabPt(s * 144, -124),
    crabPt(s * 156, -156),
    crabPt(s * 142, -188),
    crabPt(s * 108, -184),
    crabPt(s * 98, -166),
    crabPt(s * 84, -158), // Sharp inner carpal spine tip!
    crabPt(s * 98, -148),
    crabPt(s * 112, -126)
  ];
  fillShape(carpusPts, PAL.persimmon, 225, 0.05, 0.3, 0.22);
  // Rich vermilion boss on dorsal wrist
  washShape(
    ellipsePts(...crabPt(s * 128, -156), 24, 20, 18),
    PAL.vermilion,
    145
  );
  // Glowing highlight on carpal dome
  washShape(
    ellipsePts(...crabPt(s * 124, -162), 14, 11, 14),
    PAL.shellCream,
    155
  );
  strokePath(carpusPts, "ironwire", PAL.inkIron, 0.5, true, 0.2);

  // 4. PROPODUS (Swollen Palm + Fixed Finger) & DACTYLUS (Movable Finger)
  const palmPts = [
    crabPt(s * 138, -182),
    crabPt(s * 126, -214),
    crabPt(s * 96, -228),
    crabPt(s * 62, -224),
    crabPt(s * 28, -212), // Fixed finger tip
    crabPt(s * 34, -202),
    crabPt(s * 66, -206), // Biting edge base
    crabPt(s * 76, -192),
    crabPt(s * 102, -176)
  ];

  const dactylPts = [
    crabPt(s * 88, -186),
    crabPt(s * 66, -198),
    crabPt(s * 30, -204), // Movable finger tip meeting fixed finger
    crabPt(s * 26, -210),
    crabPt(s * 58, -216),
    crabPt(s * 82, -204)
  ];

  // Fill movable finger (Dactylus)
  fillShape(dactylPts, PAL.persimmonLight, 225, 0.04, 0.25, 0.2);
  washShape(
    [crabPt(s * 54, -212), crabPt(s * 28, -206), crabPt(s * 34, -202), crabPt(s * 60, -202)],
    PAL.shellGlow,
    185
  );

  // Fill Palm & Fixed Finger
  fillShape(palmPts, PAL.persimmon, 225, 0.05, 0.3, 0.22);
  // Warm cinnabar gradient on upper palm
  washShape(
    [crabPt(s * 134, -186), crabPt(s * 122, -212), crabPt(s * 74, -222), crabPt(s * 88, -188)],
    PAL.cinnabar,
    165
  );
  // Creamy porcelain-orange belly on inner palm and pincer tips
  washShape(
    [crabPt(s * 102, -180), crabPt(s * 74, -194), crabPt(s * 30, -208), crabPt(s * 58, -218), crabPt(s * 96, -196)],
    PAL.shellCream,
    170
  );

  // Calcareous white molar teeth along the pincer biting gap
  for (let t = 0.25; t <= 0.8; t += 0.18) {
    const tx = s * (68 - t * 34);
    const ty = -202 - t * 6;
    const [gx, gy] = crabPt(tx, ty);
    washShape(ellipsePts(gx, gy, 3.2, 2.4, 10), "#fffaf0", 230);
    brush.set("ironwire", PAL.inkSoft, 0.25);
    brush.circle(gx, gy, 2.6, 0.05);
  }

  // Iron-wire outlines of palm & fingers (before fur cuff overlaps the outer edge)
  strokePath(dactylPts, "ironwire", PAL.inkIron, 0.46, true, 0.22);
  strokePath(palmPts, "ironwire", PAL.inkIron, 0.48, true, 0.22);

  // Wet specular glint along the smooth inner palm & pincers
  strokePath(
    [crabPt(s * 104, -184), crabPt(s * 76, -198), crabPt(s * 38, -208)],
    "glint",
    "#ffffff",
    0.58,
    false,
    0.3
  );

  // 5. THE ICONIC VELVETY "MITTEN" (Dense Fur Cuff on the Outer/Dorsal Claw)
  drawClawMittenFur(isLeft);
}

function drawClawMittenFur(isLeft) {
  const s = isLeft ? -1 : 1;

  // Base dark bistre-umber watercolor mass for the plush fur patch
  const mittenPoly = [
    crabPt(s * 134, -190),
    crabPt(s * 130, -218),
    crabPt(s * 102, -234),
    crabPt(s * 66, -230),
    crabPt(s * 54, -216),
    crabPt(s * 78, -200),
    crabPt(s * 112, -186)
  ];
  fillShape(mittenPoly, PAL.furMid, 210, 0.12, 0.5, 0.3, 0.3);
  fillShape(
    [
      crabPt(s * 126, -196),
      crabPt(s * 120, -216),
      crabPt(s * 96, -226),
      crabPt(s * 68, -222),
      crabPt(s * 82, -204)
    ],
    PAL.furDark,
    195,
    0.1,
    0.45,
    0.25,
    0.3
  );

  // 320+ individual layered bristle strokes radiating across the mitten cuff
  // Pass 1: Deep sepia & bistre under-hairs
  // Pass 2: Warm chestnut & raw umber mid-hairs
  // Pass 3: Glistening golden-ochre wet tip hairs
  const totalHairs = 320;
  for (let i = 0; i < totalHairs; i++) {
    const u = random(0.0, 1.0); // along palm length
    const v = random(0.0, 1.0); // across palm width

    // Interpolate position inside mitten patch in crab-local space
    const baseLx = s * (128 - u * 68 + (v - 0.5) * 14);
    const baseLy = -190 - u * 28 - v * 22 - Math.sin(u * Math.PI) * 8;

    // Hair direction: radiating outward/anteriorly (-Y and slightly outward X)
    const dirLx = s * (0.35 + (1 - u) * 0.45 + random(-0.18, 0.18));
    const dirLy = -0.85 - v * 0.35 + random(-0.15, 0.15);
    const hLen = random(8, 17) * (0.65 + 0.35 * Math.sin(u * Math.PI));

    const p1 = crabPt(baseLx, baseLy);
    const pMid = crabPt(baseLx + dirLx * hLen * 0.55, baseLy + dirLy * hLen * 0.55);
    const p2 = crabPt(baseLx + dirLx * hLen, baseLy + dirLy * hLen);

    let col = PAL.furDark;
    let w = 0.32;
    if (i > totalHairs * 0.78) {
      col = random() < 0.4 ? PAL.furHighlight : PAL.furGold;
      w = random(0.2, 0.28);
    } else if (i > totalHairs * 0.42) {
      col = random() < 0.5 ? PAL.furWarm : PAL.furMid;
      w = random(0.24, 0.34);
    } else {
      col = PAL.furDark;
      w = random(0.28, 0.38);
    }

    strokePath([p1, pMid, p2], "ironwire", col, w, false, 0.25);
  }
}

// ============================================================================
// 8. THE CARAPACE (SCULPTED SHELL, ROSTRUM, EYES & GLOWING GRADIENT)
// ============================================================================
function buildCarapaceContour() {
  // Exact zoological contour of Eriocheir sinensis carapace:
  // 4 frontal teeth, deep eye orbits, 4 sharp anterolateral saw-teeth on each side,
  // smooth converging posterolateral margins, and straight posterior bar.
  const rightSide = [
    [0, -100],      // Median frontal notch
    [7, -104],      // Inner frontal tooth 1
    [13, -100],     // Submedian notch
    [21, -103],     // Outer frontal tooth 2
    [27, -96],      // Inner orbital angle
    [38, -93],      // Eye orbit bay
    [50, -98],      // Anterolateral Spine 1 (Outer orbital tooth)
    [54, -88],      // Notch 1
    [72, -89],      // Anterolateral Spine 2 (Hepatic tooth)
    [76, -77],      // Notch 2
    [94, -75],      // Anterolateral Spine 3 (Epibranchial tooth 1)
    [96, -61],      // Notch 3
    [112, -55],     // Anterolateral Spine 4 (Epibranchial tooth 2)
    [111, -41],     // Small notch 4
    [118, -32],     // Small lateral denticle
    [120, -8],      // Widest branchial arch
    [114, 22],      // Posterolateral curve
    [98, 56],       // Converging posterior flank
    [68, 86],       // Posterolateral corner
    [34, 91],       // Posterior rim
    [0, 92]         // Posterior center
  ];

  const leftSide = [];
  for (let i = rightSide.length - 2; i >= 1; i--) {
    leftSide.push([-rightSide[i][0], rightSide[i][1]]);
  }

  const allLocal = [...rightSide, ...leftSide];
  return allLocal.map(pt => crabPt(pt[0], pt[1]));
}

function drawCarapace() {
  // 1. Frontal Appendages (Eyes, Eyestalks, Antennules & Sensory Antennae)
  drawEyesAndAntennae();

  const shellOutline = buildCarapaceContour();

  // 2. Gongbi Multi-Layer Watercolor & Wash Build-Up (12+ Translucent Layers)
  // Layer A: Overall warm persimmon base
  fillShape(shellOutline, PAL.persimmon, 235, 0.04, 0.32, 0.22, 0.18);

  // Layer B: Rich cinnabar body wash
  const innerShell = ellipsePts(CRAB_CX, CRAB_CY - 6, 108, 92, 40, CRAB_ROT);
  fillShape(innerShell, PAL.cinnabar, 155, 0.14, 0.38, 0.2, 0.3);

  // Layer C: Deep vermilion & carmine across the anterior gastric arch & frontal region
  const anteriorArch = [
    crabPt(-92, -62),
    crabPt(-48, -94),
    crabPt(0, -98),
    crabPt(48, -94),
    crabPt(92, -62),
    crabPt(76, -12),
    crabPt(0, -2),
    crabPt(-76, -12)
  ];
  fillShape(anteriorArch, PAL.vermilion, 145, 0.16, 0.4, 0.2, 0.3);
  washShape(
    [crabPt(-62, -84), crabPt(0, -94), crabPt(62, -84), crabPt(42, -32), crabPt(-42, -32)],
    PAL.carmineDeep,
    110,
    0.3
  );

  // Layer D: Glowing Persimmon-Apricot & Creamy Highlights on the Two Swollen Branchial Domes
  for (const s of [-1, 1]) {
    const domeCenter = crabPt(s * 68, 8);
    fillShape(ellipsePts(domeCenter[0], domeCenter[1], 44, 52, 28, CRAB_ROT + s * 18), PAL.persimmonLight, 160, 0.18, 0.3, 0.15);
    washShape(ellipsePts(domeCenter[0], domeCenter[1], 32, 38, 24, CRAB_ROT + s * 18), PAL.shellCream, 155, 0.3);
    washShape(ellipsePts(domeCenter[0] - s * 4, domeCenter[1] - 4, 18, 24, 20, CRAB_ROT + s * 18), PAL.shellGlow, 140, 0.3);
  }

  // Layer E: Central Cardiac Shield Glow (behind the H-groove)
  const cardiacCenter = crabPt(0, 38);
  washShape(ellipsePts(cardiacCenter[0], cardiacCenter[1], 34, 26, 24, CRAB_ROT), PAL.persimmonLight, 145, 0.3);
  washShape(ellipsePts(cardiacCenter[0], cardiacCenter[1] - 2, 20, 15, 20, CRAB_ROT), PAL.shellCream, 130, 0.3);

  // Layer F: Recessed Cervical & Gastro-Cardiac "H-Groove" (Deep Carmine & Burnt Sienna)
  drawCarapaceGroovesAndTubercles();

  // Layer G: Fine Cuticular Texture & Contour Hatching (Gongbi Fenran + Stippling)
  drawCarapaceMicroTexture();

  // Layer H: Beaded Posterolateral & Posterior Double Rim
  drawCarapaceBeadedRim();

  // Layer I: Wet Specular Sheen & Moisture Droplets on the Carapace
  drawCarapaceHighlightsAndDroplets();

  // Layer J: Crisp, Unbroken Gongbi Iron-Wire Carapace Outline
  strokePath(shellOutline, "ironwire", PAL.inkIron, 0.56, true, 0.15);
}

function drawEyesAndAntennae() {
  for (const s of [-1, 1]) {
    // Short eyestalk in orbital socket
    const stalkPts = [
      crabPt(s * 28, -94),
      crabPt(s * 34, -102),
      crabPt(s * 44, -100),
      crabPt(s * 44, -92)
    ];
    washShape(stalkPts, PAL.cinnabar, 220);
    strokePath(stalkPts, "ironwire", PAL.inkIron, 0.35, true);

    // Glossy dark ruby-black compound cornea
    const [ex, ey] = crabPt(s * 40, -101);
    fillShape(ellipsePts(ex, ey, 5.2, 4.2, 14, CRAB_ROT + s * 20), "#170704", 245, 0.02, 0.1, 0.1);
    // Tiny white corneal glint
    brush.set("glint", "#ffffff", 0.45);
    brush.line(ex - 1.5, ey - 1.5, ex + 0.5, ey - 2.0);

    // Folded antennule in inner notch
    strokePath(
      [crabPt(s * 13, -100), crabPt(s * 16, -110), crabPt(s * 10, -114)],
      "ironwire",
      PAL.carmineDeep,
      0.34,
      false,
      0.25
    );

    // Fine sensory antenna Whip emerging near outer orbital tooth
    const antPts = [
      crabPt(s * 47, -96),
      crabPt(s * 54, -112),
      crabPt(s * 48, -128),
      crabPt(s * 38, -142)
    ];
    strokePath(antPts, "ironwire", PAL.vermilion, 0.32, false, 0.3);
    strokePath(antPts.slice(0, 3), "ironwire", PAL.inkIron, 0.24, false, 0.3);
  }
}

function drawCarapaceGroovesAndTubercles() {
  // Deep H-shaped gastro-cardiac groove in central carapace
  for (const s of [-1, 1]) {
    // Longitudinal branch of H-groove
    const grooveLong = [
      crabPt(s * 30, -34),
      crabPt(s * 22, -10),
      crabPt(s * 20, 8),
      crabPt(s * 26, 32),
      crabPt(s * 22, 52)
    ];
    strokePath(grooveLong, "fenran", PAL.carmineDeep, 1.4, false, 0.3);
    strokePath(grooveLong, "cpencil", PAL.shellShadow, 0.65, false, 0.3);
    strokePath(grooveLong, "ironwire", PAL.inkSoft, 0.26, false, 0.3);

    // Oblique hepatic/cervical groove radiating toward lateral spines
    const grooveOblique = [
      crabPt(s * 26, -24),
      crabPt(s * 52, -42),
      crabPt(s * 76, -68)
    ];
    strokePath(grooveOblique, "fenran", PAL.carmineDeep, 1.1, false, 0.3);
    strokePath(grooveOblique, "cpencil", PAL.shellShadow, 0.5, false, 0.3);

    // 6 Characteristic Epigastric, Protogastric & Hepatic Tubercles (Raised Bosses)
    const tubercles = [
      { lx: s * 14, ly: -74, r: 5.5 }, // Epigastric
      { lx: s * 36, ly: -58, r: 6.5 }, // Protogastric
      { lx: s * 62, ly: -48, r: 5.8 }  // Hepatic
    ];
    for (const tb of tubercles) {
      const [tx, ty] = crabPt(tb.lx, tb.ly);
      // Dark crescent crease on posterior side of boss
      washShape(ellipsePts(tx, ty + 2, tb.r * 1.1, tb.r * 0.9, 12), PAL.carmineDeep, 135);
      // Bright apricot-cream crown on tubercle
      washShape(ellipsePts(tx - 1, ty - 1.5, tb.r * 0.85, tb.r * 0.7, 12), PAL.shellGlow, 175);
      brush.set("ironwire", PAL.inkSoft, 0.26);
      brush.arc(tx, ty, tb.r, 15, 165);
    }
  }

  // Transverse bar of the H-groove
  const grooveTrans = [
    crabPt(-21, 6),
    crabPt(0, 9),
    crabPt(21, 6)
  ];
  strokePath(grooveTrans, "fenran", PAL.carmineDeep, 1.5, false, 0.3);
  strokePath(grooveTrans, "cpencil", PAL.shellShadow, 0.75, false, 0.3);
  strokePath(grooveTrans, "ironwire", PAL.inkSoft, 0.3, false, 0.3);

  // Median frontal sulcus (groove between the epigastric lobes)
  strokePath([crabPt(0, -98), crabPt(0, -56)], "fenran", PAL.carmineDeep, 0.95, false, 0.2);
  strokePath([crabPt(0, -98), crabPt(0, -62)], "ironwire", PAL.inkSoft, 0.28, false, 0.2);
}

function drawCarapaceMicroTexture() {
  // Curved anatomical contour strokes across the branchial & gastric domes
  for (const s of [-1, 1]) {
    for (let i = 0; i < 18; i++) {
      const t = i / 17;
      const rX = 32 + t * 72;
      const rY = -45 + t * 95;
      const p1 = crabPt(s * (rX * 0.65), rY - 18);
      const p2 = crabPt(s * rX, rY);
      const p3 = crabPt(s * (rX * 0.75), rY + 22);
      const col = i % 3 === 0 ? PAL.shellCream : i % 2 === 0 ? PAL.persimmonLight : PAL.cinnabar;
      strokePath([p1, p2, p3], "cpencil", col, 0.32, false, 0.35);
    }
  }

  // Fine cuticular pore stippling across the anterior and lateral carapace
  for (let i = 0; i < 95; i++) {
    const a = random(0, 360);
    const rad = random(12, 96);
    const lx = cos(a) * rad * 1.05;
    const ly = sin(a) * rad * 0.85 - 6;
    const [px, py] = crabPt(lx, ly);
    const col = ly < -25 ? PAL.carmineDeep : random() < 0.5 ? PAL.vermilion : PAL.shellCream;
    brush.set("rotring", col, random(0.2, 0.35));
    brush.line(px, py, px + 0.8, py + 0.8);
  }
}

function drawCarapaceBeadedRim() {
  // Double-rimmed posterolateral & posterior border with tiny beaded granules
  for (const s of [-1, 1]) {
    const rimPath = [
      crabPt(s * 114, -22),
      crabPt(s * 115, 12),
      crabPt(s * 96, 52),
      crabPt(s * 66, 82),
      crabPt(0, 87)
    ];
    strokePath(rimPath, "cpencil", PAL.carmineDeep, 0.55, false, 0.25);
    strokePath(rimPath, "glint", PAL.shellCream, 0.45, false, 0.25);
    strokePath(rimPath, "ironwire", PAL.inkSoft, 0.3, false, 0.25);
  }
}

function drawCarapaceHighlightsAndDroplets() {
  // Luminous wet porcelain sheen arcs on the high branchial domes
  for (const s of [-1, 1]) {
    const sheenPts = [
      crabPt(s * 58, -18),
      crabPt(s * 74, 4),
      crabPt(s * 66, 28)
    ];
    strokePath(sheenPts, "glint", "#fffaf0", 0.75, false, 0.35);

    // Highlight tips on the 4 anterolateral saw-teeth
    const teeth = [
      [s * 50, -98],
      [s * 72, -89],
      [s * 94, -75],
      [s * 112, -55]
    ];
    for (const [tx, ty] of teeth) {
