  // Glistening condensation droplets beaded directly on the steamed carapace
  const shellDrops = [
    { lx: -56, ly: -8, r: 5.8 },
    { lx: -68, ly: 8, r: 3.6 },
    { lx: -42, ly: 28, r: 4.5 },
    { lx: 58, ly: -4, r: 6.2 },
    { lx: 72, ly: 14, r: 3.8 },
    { lx: 46, ly: 32, r: 4.8 },
    { lx: -16, ly: -42, r: 4.2 },
    { lx: 18, ly: -36, r: 3.5 },
    { lx: 6, ly: 48, r: 5.0 }
  ];

  for (const d of shellDrops) {
    const [gx, gy] = crabPt(d.lx, d.ly);
    drawSingleDroplet(gx, gy, d.r, true, true);
  }
}

