async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(849201);
  noiseSeed(849201);

  // Custom chisel marker for saturated cadmium orange fruit & prismatic slivers
  brush.add("chisel", {
    type: "custom",
    weight: 6.5,
    scatter: 0.06,
    opacity: 85,
    spacing: 0.3,
    pressure: [0.85, 1.15, 0.85],
    tip: (_m) => {
      _m.rotate(28);
      _m.rect(-3.2, -0.9, 6.4, 1.8);
    },
    rotate: "natural",
    markerTip: false,
    noise: 0.25
  });

  // Custom razor-crisp highlight pen for hard white cellophane fracture creases
  brush.add("razor", {
