    rotate: "none",
    noise: 0.15
  });
}

function draw() {
  translate(-width / 2, -height / 2);

  // Cool dark ambient ground
  background("#111726");

  const knot = { x: 585, y: 268 };
  const rimCurve = (x) => 855 + 118 * sin(((x + 40) / 1280) * 180);

  // 1. Ambient cool background at top corners behind the flared cellophane crown
  drawCoolAmbientGround(knot);

  // 2. Deep basket interior shadows (cool dioxazine violet & Prussian indigo)
  drawInteriorShadows(knot, rimCurve);

  // 3. The packed navel oranges in saturated cadmium orange marker + cool shadow shifts
  const oranges = getOrangeLayout();
  for (let i = 0; i < oranges.length; i++) {
    drawNavelOrange(oranges[i], knot);
  }

  // 4. Deep inter-fruit crevices & stacked-film shadow pockets between oranges
  drawInterFruitCrevices(oranges);

  // 5. Woven wicker basket peeking at the bottom in warm ochre hatching
  drawWickerBasket(rimCurve);

  // 6. Cellophane Layer A: Translucent tinted film veils (batched by color for speed & optical depth)
  const cellophaneData = buildCellophaneGeometry(oranges, knot, rimCurve);
  drawCellophaneVeils(cellophaneData);

  // 7. Cellophane Layer B: Prismatic slivers of pale cyan, lilac, orchid & icy aqua
  drawPrismaticSlivers(cellophaneData, oranges, knot);

  // 8. Cellophane Layer C: Fine striated stretch-hatching & refracted cool edge lines
  drawCellophaneStretchTextures(cellophaneData, oranges, knot);

  // 9. Curling magenta ribbon: tight knot, glossy bow loops, and helical cascading streamers
  drawMagentaRibbonSystem(knot, oranges);

  // 10. Cellophane Layer D: Obsessive hard white fracture-highlights in crisp pen along every crease
  drawCellophaneFractureHighlights(cellophaneData, oranges, knot, rimCurve);

  noLoop();
}

