// 1. COOL AMBIENT GROUND & 2. INTERIOR SHADOWS
// ============================================================================

function drawCoolAmbientGround(knot) {
  brush.noStroke();
  // Deep cool slate and Prussian blue washes in upper corners
  const bgPolys = [
    [[0, 0], [520, 0], [knot.x - 45, knot.y + 20], [0, 420]],
    [[520, 0], [1200, 0], [1200, 410], [knot.x + 45, knot.y + 20]],
    [[0, 0], [320, 0], [160, 290], [0, 340]],
    [[880, 0], [1200, 0], [1200, 340], [1020, 280]]
  ];
  const bgCols = ["#182338", "#162034", "#0e1524", "#0e1524"];
  for (let i = 0; i < bgPolys.length; i++) {
    brush.wash(bgCols[i], 190);
    drawPoly(bgPolys[i], 0);
  }
  brush.noWash();

  // Subtle cool cross-hatching in upper negative space
  brush.hatchStyle("2B", "#263859", 0.9);
  brush.hatch(9, -35, { rand: 0.08 });
  drawPoly([[0, 0], [360, 0], [120, 310], [0, 350]]);
  drawPoly([[840, 0], [1200, 0], [1200, 350], [1060, 300]]);
  brush.noHatch();
}

function drawInteriorShadows(knot, rimCurve) {
  brush.noStroke();
  brush.wash("#190f2e", 235);
  let basketInterior = [
    [-20, 360],
    [knot.x - 180, 290],
    [knot.x, knot.y + 5],
    [knot.x + 190, 290],
    [1220, 350],
    [1220, rimCurve(1200) + 40],
    [600, rimCurve(600) + 40],
    [-20, rimCurve(0) + 40]
  ];
  drawPoly(basketInterior, 0.05);
  brush.noWash();
}

// ============================================================================
// 3. NAVEL ORANGES IN SATURATED CADMIUM ORANGE MARKER
// ============================================================================

function drawNavelOrange(o, knot) {
  const cx = o.x;
  const cy = o.y;
  const r = o.r;

  // Step A: Base opaque marker-wash disc in fiery cadmium orange-red
  brush.noStroke();
  brush.wash("#d63200", 240);
  brush.circle(cx, cy, r * 0.99, 0.02);

  // Step B: Layered crescent zones for cool violet-crimson shadow & vibrant cadmium crown
  // Light comes generally from upper-left/top with cool bluish ambient bounce from cellophane
  const lightAng = -62;
  const lx = cx + cos(lightAng) * r * 0.28;
  const ly = cy + sin(lightAng) * r * 0.28;

  // Shadow crescent on bottom-right & tucked edge (cool palette influence on orange shadow)
  let shadowPts = [];
  for (let a = -25; a <= 195; a += 15) {
    shadowPts.push([cx + cos(a) * r * 0.99, cy + sin(a) * r * 0.99]);
  }
  for (let a = 195; a >= -25; a -= 18) {
    let rad = r * map(sin(a - 30), -1, 1, 0.85, 0.42);
    shadowPts.push([cx + cos(a) * rad, cy + sin(a) * rad]);
  }
  brush.wash("#6b1236", 155);
  drawPoly(shadowPts, 0.15);

  // Deepest cool violet-plum core along lower rim
  let deepShadowPts = [];
  for (let a = 15; a <= 165; a += 15) {
    deepShadowPts.push([cx + cos(a) * r * 0.98, cy + sin(a) * r * 0.98]);
  }
  for (let a = 165; a >= 15; a -= 18) {
    deepShadowPts.push([cx + cos(a) * r * 0.68, cy + sin(a) * r * 0.68]);
  }
  brush.wash("#3e1240", 140);
  drawPoly(deepShadowPts, 0.15);

  // Bright saturated cadmium orange mid-crown
  brush.wash("#ff5900", 210);
  brush.circle(cx + cos(lightAng) * r * 0.1, cy + sin(lightAng) * r * 0.1, r * 0.82, 0.03);

  // Luminous cadmium tangerine upper dome
  brush.wash("#ff8400", 195);
  brush.circle(lx, ly, r * 0.60, 0.04);

  // Golden-orange hot spot
  brush.wash("#ffae00", 160);
  brush.circle(lx - r * 0.06, ly - r * 0.06, r * 0.36, 0.04);
  brush.noWash();

  // Step C: Directional contour marker strokes ("chisel" & "marker") building spherical form
  const markerBands = [
    { col: "#4c143d", w: 1.3, rMin: 0.78, rMax: 0.97, a1: 20,  a2: 165, count: 18 },
    { col: "#8c1828", w: 1.4, rMin: 0.65, rMax: 0.92, a1: -10, a2: 185, count: 22 },
    { col: "#cc2900", w: 1.5, rMin: 0.45, rMax: 0.85, a1: -50, a2: 200, count: 28 },
    { col: "#ff4d00", w: 1.6, rMin: 0.25, rMax: 0.78, a1: 0,   a2: 360, count: 38 },
    { col: "#ff6f00", w: 1.5, rMin: 0.15, rMax: 0.68, a1: -140,a2: 60,  count: 32 },
    { col: "#ff9900", w: 1.3, rMin: 0.08, rMax: 0.50, a1: -135,a2: 35,  count: 24 },
    { col: "#ffc426", w: 1.1, rMin: 0.05, rMax: 0.34, a1: -125,a2: 15,  count: 16 },
    // Cool reflected bounce light along the edge (lilac & cerulean-pink marker strokes)
    { col: "#b55998", w: 1.0, rMin: 0.84, rMax: 0.96, a1: 45,  a2: 155, count: 14 },
    { col: "#6682b8", w: 0.85,rMin: 0.88, rMax: 0.98, a1: 75,  a2: 145, count: 10 }
  ];

  for (let b of markerBands) {
    brush.set("chisel", b.col, b.w);
    for (let i = 0; i < b.count; i++) {
      let ang = random(b.a1, b.a2);
      let rad = r * random(b.rMin, b.rMax);
      let span = random(18, 42);
      let p1 = [cx + cos(ang - span * 0.5) * rad, cy + sin(ang - span * 0.5) * rad, random(0.6, 1.1)];
      let p2 = [cx + cos(ang) * (rad + random(-4, 4)), cy + sin(ang) * (rad + random(-4, 4)), random(0.9, 1.3)];
      let p3 = [cx + cos(ang + span * 0.5) * rad, cy + sin(ang + span * 0.5) * rad, random(0.6, 1.1)];
      brush.spline([p1, p2, p3], 0.5);
    }
  }

  // Step D: Meridional (longitude) marker strokes radiating from the navel/calyx axis
  const nx = cx + cos(o.navelAng) * r * o.navelDist;
  const ny = cy + sin(o.navelAng) * r * o.navelDist;
  for (let i = 0; i < 36; i++) {
    let a = i * 10 + random(-4, 4);
    let d1 = r * random(0.14, 0.35);
    let d2 = r * random(0.55, 0.88);
    let mx1 = lerp(nx, cx + cos(a) * r, d1 / r);
    let my1 = lerp(ny, cy + sin(a) * r, d1 / r);
    let mx2 = lerp(nx, cx + cos(a) * r, d2 / r);
    let my2 = lerp(ny, cy + sin(a) * r, d2 / r);
    let midX = (mx1 + mx2) * 0.5 + cos(a + 90) * random(-10, 10);
    let midY = (my1 + my2) * 0.5 + sin(a + 90) * random(-10, 10);

    let isLit = dist(midX, midY, lx, ly) < r * 0.65;
    let col = isLit ? (random() < 0.5 ? "#ff7b00" : "#ffa600") : (random() < 0.5 ? "#d93600" : "#9c192b");
    brush.set("marker", col, random(0.55, 0.95));
    brush.spline([[mx1, my1, 0.5], [midX, midY, 1.0], [mx2, my2, 0.5]], 0.45);
  }

  // Step E: Obsessive dimpled orange peel texture (oil glands / pores)
  // Dark pores in midtone/shadow, bright yellow-orange pore rims in lit zone
  const poreCols = ["#8a1c14", "#b82d00", "#e04800", "#ff8800", "#ffd24d", "#fff2b2"];
  for (let cIdx = 0; cIdx < poreCols.length; cIdx++) {
    brush.set("rotring", poreCols[cIdx], cIdx < 3 ? 0.65 : 0.55);
    let numPores = cIdx < 4 ? 75 : 45;
    for (let i = 0; i < numPores; i++) {
      let a = random(360);
      let u = sqrt(random(0.04, 0.92));
      let px = cx + cos(a) * r * u;
      let py = cy + sin(a) * r * u;
      let dLight = dist(px, py, lx, ly) / r;

      if (cIdx >= 4 && dLight > 0.62) continue;
      if (cIdx <= 1 && dLight < 0.35) continue;

      let foreshorten = sqrt(max(0.15, 1 - u * u));
      let tangX = -sin(a) * 2.2;
      let tangY = cos(a) * 2.2;
      let radX = cos(a) * 1.8 * foreshorten;
      let radY = sin(a) * 1.8 * foreshorten;
      brush.line(px - tangX, py - tangY, px + tangX + radX, py + tangY + radY);
    }
  }

  // Step F: Render the Navel rosette or Stem Calyx button
  if (o.type === "navel") {
    drawOrangeNavel(nx, ny, r, o.navelAng);
  } else {
    drawOrangeCalyx(nx, ny, r, o.navelAng);
  }

  // Crisp contour rim definition in dark crimson-violet & cadmium
  brush.set("cpencil", "#380d2a", 1.1);
  brush.arc(cx, cy, r * 0.99, 10, 175);
  brush.set("cpencil", "#cc2b00", 0.9);
  brush.arc(cx, cy, r * 0.99, 175, 370);
}

function drawOrangeNavel(nx, ny, r, ang) {
  const nr = r * 0.135;
  // Recessed umbilical shadow
  brush.noStroke();
  brush.wash("#3d0b1e", 230);
  brush.circle(nx, ny, nr, 0.12);
  brush.wash("#7a1c08", 200);
  brush.circle(nx + cos(ang) * nr * 0.15, ny + sin(ang) * nr * 0.15, nr * 0.68, 0.15);
  // Inner secondary fruitlet bulge inside the navel crater
  brush.wash("#d94400", 210);
  brush.circle(nx - cos(ang) * nr * 0.1, ny - sin(ang) * nr * 0.1, nr * 0.42, 0.12);
  brush.wash("#ff9000", 190);
  brush.circle(nx - cos(ang) * nr * 0.2, ny - sin(ang) * nr * 0.2, nr * 0.22, 0.1);
  brush.noWash();

  // Radiating puckered skin creases around the navel
  for (let i = 0; i < 24; i++) {
    let a = i * 15 + random(-5, 5);
    let r1 = nr * random(0.45, 0.85);
    let r2 = nr * random(1.4, 2.7);
    let x1 = nx + cos(a) * r1;
    let y1 = ny + sin(a) * r1;
    let x2 = nx + cos(a) * r2;
    let y2 = ny + sin(a) * r2;
    let xm = (x1 + x2) * 0.5 + cos(a + 90) * random(-4, 4);
    let ym = (y1 + y2) * 0.5 + sin(a + 90) * random(-4, 4);

    brush.set("rotring", i % 2 === 0 ? "#4a0c1c" : "#9e2100", 0.75);
    brush.spline([[x1, y1, 1.1], [xm, ym, 0.8], [x2, y2, 0.3]], 0.4);

    // Adjacent lit ridge between creases
    let aLit = a + 6;
    brush.set("rotring", "#ffb833", 0.6);
    brush.line(
      nx + cos(aLit) * nr * 0.8,
      ny + sin(aLit) * nr * 0.8,
      nx + cos(aLit) * nr * 1.9,
      ny + sin(aLit) * nr * 1.9
    );
  }
}

function drawOrangeCalyx(nx, ny, r, ang) {
  const cr = r * 0.11;
  // Furrowed ring around stem button
  for (let i = 0; i < 20; i++) {
    let a = i * 18 + random(-4, 4);
    brush.set("rotring", "#8c2000", 0.65);
    brush.line(
      nx + cos(a) * cr * 0.6,
      ny + sin(a) * cr * 0.6,
      nx + cos(a) * cr * random(1.5, 2.3),
      ny + sin(a) * cr * random(1.5, 2.3)
    );
  }
  // 5-pointed woody olive-ochre sepal star
  let starPts = [];
  for (let i = 0; i < 10; i++) {
    let a = i * 36 + ang;
    let rad = i % 2 === 0 ? cr * 1.05 : cr * 0.45;
    starPts.push([nx + cos(a) * rad, ny + sin(a) * rad]);
  }
  brush.noStroke();
  brush.wash("#545e24", 230);
  drawPoly(starPts, 0.05);
  brush.wash("#8f9440", 190);
  brush.circle(nx, ny, cr * 0.45, 0.1);
  brush.noWash();

  brush.set("rotring", "#2b2414", 0.7);
  drawPoly(starPts, 0.05);
}

// ============================================================================
// 4. DEEP INTER-FRUIT CREVICES (COOL STACKED SHADOWS)
// ============================================================================

function drawInterFruitCrevices(oranges) {
  // Triangular/polygonal pockets where 3 oranges meet
  const crevices = [
    [[245, 550], [315, 480], [390, 455], [305, 575]],
    [[520, 495], [590, 560], [665, 495], [590, 445]],
    [[825, 460], [925, 535], [855, 575], [770, 490]],
    [[165, 705], [255, 665], [295, 755], [185, 775]],
    [[485, 695], [585, 645], [675, 695], [585, 765]],
    [[885, 685], [985, 650], [1035, 745], [915, 760]]
  ];

  brush.noStroke();
  for (let c of crevices) {
    brush.wash("#1e1035", 210);
    drawPoly(c, 0.1);
  }
  brush.noWash();

  brush.hatchStyle("2B", "#120924", 1.0);
  for (let c of crevices) {
    brush.hatch(5, 35, { rand: 0.1 });
    drawPoly(c, 0.05);
  }
  brush.noHatch();
}

// ============================================================================
// 5. WICKER BASKET AT THE BOTTOM IN WARM OCHRE HATCHING
// ============================================================================

function drawWickerBasket(rimCurve) {
  // Step A: Dark cool umber-indigo ground under the wicker weave
  let basketPoly = [[-30, rimCurve(-30)]];
  for (let x = 0; x <= 1230; x += 60) {
    basketPoly.push([x, rimCurve(x)]);
  }
  basketPoly.push([1230, 1230], [-30, 1230]);

  brush.noStroke();
  brush.wash("#241b1c", 248);
  drawPoly(basketPoly, 0);
  brush.noWash();

  // Base cross-hatched shadow bed across the wicker zone
  brush.hatchStyle("2B", "#161829", 1.1);
  brush.hatch(7, -45, { rand: 0.08 });
  drawPoly(basketPoly, 0);
  brush.noHatch();

  // Step B: Vertical Stakes (ribs) radiating slightly downward
  const stakeSpacing = 86;
  for (let sx = 25; sx < 1200; sx += stakeSpacing) {
    let topY = rimCurve(sx) + 42;
    let botX = sx + (sx - 600) * 0.08;
    let stakeW = 24;

    let stakePoly = [
      [sx - stakeW * 0.5, topY],
      [sx + stakeW * 0.5, topY],
      [botX + stakeW * 0.55, 1220],
      [botX - stakeW * 0.55, 1220]
    ];

    brush.noStroke();
    brush.wash("#7a4616", 200);
    drawPoly(stakePoly, 0);
    brush.noWash();

    // Vertical warm ochre hatching inside each pair of willow stakes
    brush.hatchStyle("cpencil", "#c98526", 1.0);
    brush.hatch(4.5, 88, { rand: 0.06 });
    drawPoly(stakePoly, 0);
    brush.noHatch();

    // Central split & shadow edges of the double stake
    brush.set("rotring", "#2b190e", 0.85);
    brush.line(sx, topY, botX, 1220);
    brush.line(sx - stakeW * 0.5, topY, botX - stakeW * 0.55, 1220);
    brush.line(sx + stakeW * 0.5, topY, botX + stakeW * 0.55, 1220);

    // Highlight along center of each stake rod
    brush.set("cpencil", "#f2c66d", 0.9);
    brush.line(sx - 5, topY + 6, botX - 5, 1220);
    brush.line(sx + 5, topY + 6, botX + 5, 1220);
  }

  // Step C: Horizontal Woven Willow Rods (over-and-under randing weave)
  const rowH = 32;
  for (let row = 0; row < 10; row++) {
    for (let col = -1; col < 15; col++) {
      let x1 = col * stakeSpacing + (row % 2) * (stakeSpacing * 0.5);
      let x2 = x1 + stakeSpacing * 1.12;
      let xm = (x1 + x2) * 0.5;

      let y1 = rimCurve(x1) + 52 + row * rowH + 6;
      let y2 = rimCurve(x2) + 52 + row * rowH + 8;
      let ym = rimCurve(xm) + 52 + row * rowH - 7; // arches up over the stake!

      if (min(y1, y2, ym) > 1225) continue;

      let rodThick = 22;
      let rodPoly = [
        [x1 + 4, y1 - rodThick * 0.42],
        [xm, ym - rodThick * 0.5],
        [x2 - 4, y2 - rodThick * 0.42],
        [x2 - 4, y2 + rodThick * 0.42],
        [xm, ym + rodThick * 0.5],
        [x1 + 4, y1 + rodThick * 0.42]
      ];

      // Shadow tucked underneath the woven rod
      brush.set("2B", "#1b1626", 1.5);
      brush.spline([
        [x1 + 6, y1 + rodThick * 0.5, 0.7],
        [xm, ym + rodThick * 0.56, 1.2],
        [x2 - 6, y2 + rodThick * 0.5, 0.7]
      ], 0.4);

      // Base warm ochre wash on willow rod
      let baseOchre = (row + col) % 3 === 0 ? "#b8711e" : ((row + col) % 3 === 1 ? "#cf8b2b" : "#9e5916");
      brush.noStroke();
      brush.wash(baseOchre, 225);
      drawPoly(rodPoly, 0.15);
      brush.noWash();

      // Warm ochre contour hatching following the curve of the rod
      let rodAng = atan2(y2 - y1, x2 - x1);
      brush.hatchStyle("HB", "#e3a642", 0.95);
      brush.hatch(4, rodAng, { rand: 0.05 });
      drawPoly(rodPoly, 0.1);
      brush.noHatch();

      // Secondary cross-hatch at the tucked ends where rod dives behind stakes
      let leftEnd = [
        [x1 + 4, y1 - rodThick * 0.4],
        [x1 + 26, y1 - rodThick * 0.45],
        [x1 + 26, y1 + rodThick * 0.45],
        [x1 + 4, y1 + rodThick * 0.4]
      ];
      brush.hatchStyle("2B", "#4d2911", 0.85);
      brush.hatch(3.5, rodAng + 55, { rand: 0.06 });
      drawPoly(leftEnd, 0);
      brush.noHatch();

      // Crisp fibrous wood striations & sunlit straw crown on the apex over the stake
      brush.set("rotring", "#593110", 0.65);
      brush.spline([[x1 + 4, y1, 0.6], [xm, ym, 1.0], [x2 - 4, y2, 0.6]], 0.45);
      brush.set("cpencil", "#fae09e", 1.05);
      brush.spline([
        [xm - 24, ym - 2, 0.5],
        [xm, ym - 4, 1.2],
        [xm + 24, ym - 2, 0.5]
      ], 0.45);
    }
  }

  // Step D: Thick Braided Rim (Gunwale Border) along the top edge of the basket
  const braidStep = 52;
  for (let bx = -40; bx < 1220; bx += braidStep) {
    let x1 = bx;
    let x2 = bx + braidStep * 1.45;
    let xm = (x1 + x2) * 0.5;
    let y1 = rimCurve(x1) + 36;
    let y2 = rimCurve(x2) - 4;
    let ym = rimCurve(xm) + 12;

    let braidPoly = [
      [x1, y1 - 12],
      [xm - 6, ym - 24],
      [x2, y2 - 8],
      [x2 - 8, y2 + 18],
      [xm + 6, ym + 26],
      [x1 + 6, y1 + 14]
    ];

    // Deep crevice shadow under each braid twist
    brush.set("2B", "#1c1324", 1.8);
    brush.spline([[x1 + 4, y1 + 16, 0.8], [xm + 6, ym + 28, 1.3], [x2 - 6, y2 + 20, 0.8]], 0.4);

    // Warm golden-ochre & raw sienna fill
    brush.noStroke();
    brush.wash(bx % (braidStep * 2) === 0 ? "#c47b20" : "#ad6416", 235);
    drawPoly(braidPoly, 0.2);
    brush.noWash();

    // Dense diagonal hatching along the twist of the willow rope
    let twistAng = atan2(y2 - y1, x2 - x1);
    brush.hatchStyle("HB", "#e8ab46", 1.0);
    brush.hatch(3.8, twistAng, { rand: 0.05 });
    drawPoly(braidPoly, 0.15);

    // Shadow side hatching
    brush.hatchStyle("2B", "#5e3310", 0.85);
    brush.hatch(4.5, twistAng - 35, { rand: 0.06 });
    drawPoly([
      [x1 + 6, y1 + 2],
      [xm, ym + 6],
      [x2 - 6, y2 + 6],
      [x2 - 8, y2 + 18],
      [xm + 6, ym + 26],
      [x1 + 6, y1 + 14]
    ], 0.1);
    brush.noHatch();

    // Bright straw-yellow highlight ridge & crisp rotring outline
    brush.set("cpencil", "#fff0be", 1.15);
    brush.spline([
      [x1 + 14, y1 - 4, 0.5],
      [xm - 4, ym - 14, 1.3],
      [x2 - 14, y2 - 4, 0.5]
    ], 0.45);

    brush.set("rotring", "#3d200a", 0.75);
    drawPoly(braidPoly, 0.15);
  }
}

// ============================================================================
// 6, 7, 8. CELLOPHANE GEOMETRY, TRANSPARENT VEILS & PRISMATIC SLIVERS
// ============================================================================

function buildCellophaneGeometry(oranges, knot, rimCurve) {
  let cyanVeils = [];
  let lilacVeils = [];
  let deepStackedVeils = [];
  let iceGlazeVeils = [];
  let slivers = [];
  let creaseChains = [];

  // --- PART 1: Upper Flared Crown of Cellophane Above the Knot (y: -40 to knot.y) ---
  const numCrownRays = 26;
  let crownRays = [];
  for (let i = 0; i <= numCrownRays; i++) {
    let t = i / numCrownRays;
    let ang = lerp(-168, -12, t) + random(-2.5, 2.5);
    let len = random(310, 490);
    if (t > 0.25 && t < 0.75) len = random(340, 440);
    let rx = knot.x + cos(ang) * len;
    let ry = knot.y + sin(ang) * len * 0.82;

    // Intermediate kink vertex where plastic bends sharply
    let kinkT = random(0.42, 0.68);
    let kx = lerp(knot.x, rx, kinkT) + random(-22, 22);
    let ky = lerp(knot.y, ry, kinkT) + random(-14, 14);
    crownRays.push({ rx, ry, kx, ky, ang });

    creaseChains.push([
      [knot.x + random(-18, 18), knot.y + random(-8, 8)],
      [kx, ky],
      [rx, ry]
    ]);
  }

  for (let i = 0; i < numCrownRays; i++) {
    let r1 = crownRays[i];
    let r2 = crownRays[i + 1];
    let lowerBlade = [
      [knot.x + (i - numCrownRays * 0.5) * 2.2, knot.y],
      [r1.kx, r1.ky],
      [r2.kx, r2.ky]
    ];
    let upperBlade = [
      [r1.kx, r1.ky],
      [r1.rx, r1.ry],
      [r2.rx, r2.ry],
      [r2.kx, r2.ky]
    ];

    if (i % 3 === 0) {
      cyanVeils.push(upperBlade);
      deepStackedVeils.push(lowerBlade);
    } else if (i % 3 === 1) {
      lilacVeils.push(upperBlade);
      cyanVeils.push(lowerBlade);
    } else {
      iceGlazeVeils.push(upperBlade);
      lilacVeils.push(lowerBlade);
    }

    // Prismatic sliver shard along each pleat fold
    slivers.push({
      pts: [
        [knot.x + (i - numCrownRays * 0.5) * 1.8, knot.y],
        [r1.kx, r1.ky],
        [lerp(r1.kx, r2.kx, 0.32), lerp(r1.ky, r2.ky, 0.32)]
      ],
      col: i % 2 === 0 ? "#8cf5ff" : "#e2a8ff",
      ang: r1.ang
    });
    slivers.push({
      pts: [
        [r1.kx, r1.ky],
        [r1.rx, r1.ry],
        [lerp(r1.rx, r2.rx, 0.25), lerp(r1.ry, r2.ry, 0.25)],
        [lerp(r1.kx, r2.kx, 0.28), lerp(r1.ky, r2.ky, 0.28)]
      ],
      col: i % 3 === 0 ? "#6ce2ff" : (i % 3 === 1 ? "#ff94dc" : "#b89eff"),
      ang: r1.ang
    });
  }

  // --- PART 2: Sweeping Tension Corridors & Overlapping Film Veils Over the Oranges ---
  const numSweeps = 19;
  let sweepPaths = [];
  for (let i = 0; i < numSweeps; i++) {
    let t = i / (numSweeps - 1);
    let endX = lerp(-60, 1260, t);
    let endY = rimCurve(constrain(endX, 0, 1200)) + random(-25, 38);

    // Build a 5-point kinked tension path from the knot down to the basket rim
    let pts = [[knot.x + (t - 0.5) * 65, knot.y + 10]];
    for (let s = 1; s <= 3; s++) {
      let st = s / 4;
      let bx = lerp(knot.x, endX, st);
      let by = lerp(knot.y + 10, endY, pow(st, 0.92));
      // Deflect slightly around the oranges
      let bow = sin(st * 180) * (t - 0.5) * 140 + random(-28, 28);
      pts.push([bx + bow, by + random(-18, 18)]);
    }
    pts.push([endX, endY]);
    sweepPaths.push(pts);
    creaseChains.push(pts);
  }

  // Create faceted veil quads between adjacent tension paths
  for (let i = 0; i < numSweeps - 1; i++) {
    let pA = sweepPaths[i];
    let pB = sweepPaths[i + 1];
    for (let seg = 0; seg < 4; seg++) {
      let quad = [pA[seg], pB[seg], pB[seg + 1], pA[seg + 1]];
      let diag1 = [pA[seg], pB[seg], pA[seg + 1]];
      let diag2 = [pB[seg], pB[seg + 1], pA[seg + 1]];

      // Leave clear-ish windows over the very center of hero oranges so saturated cadmium reads strongly,
      // while stacking tinted veils heavily around the edges, valleys, and diagonal tension folds!
      let midX = (pA[seg][0] + pB[seg + 1][0]) * 0.5;
      let midY = (pA[seg][1] + pB[seg + 1][1]) * 0.5;
      let nearOrangeCenter = false;
      for (let o of oranges) {
        if (dist(midX, midY, o.x, o.y) < o.r * 0.46) {
          nearOrangeCenter = true;
          break;
        }
      }

      if (!nearOrangeCenter) {
        let mode = (i + seg) % 5;
        if (mode === 0) cyanVeils.push(quad);
        else if (mode === 1) lilacVeils.push(quad);
        else if (mode === 2) {
          cyanVeils.push(diag1);
          deepStackedVeils.push(diag2);
        } else if (mode === 3) {
          lilacVeils.push(diag1);
          iceGlazeVeils.push(diag2);
        } else {
          deepStackedVeils.push(diag1);
        }
      } else if ((i + seg) % 2 === 0) {
        // Light grazing specular veil across part of the orange dome
        iceGlazeVeils.push(diag1);
      }

      // Add a long prismatic sliver along the fold ridge pA[seg] -> pA[seg+1]
      let sliverW = random(0.14, 0.28);
      let sPts = [
        pA[seg],
        [lerp(pA[seg][0], pB[seg][0], sliverW), lerp(pA[seg][1], pB[seg][1], sliverW)],
        [lerp(pA[seg + 1][0], pB[seg + 1][0], sliverW * 0.7), lerp(pA[seg + 1][1], pB[seg + 1][1], sliverW * 0.7)],
        pA[seg + 1]
      ];
      let sCols = ["#9ef8ff", "#d9a6ff", "#72deff", "#f2b8ff", "#96ffe8", "#8cb8ff"];
      let sAng = atan2(pA[seg + 1][1] - pA[seg][1], pA[seg + 1][0] - pA[seg][0]);
      slivers.push({
        pts: sPts,
        col: sCols[(i * 3 + seg) % sCols.length],
        ang: sAng
      });
    }
  }

  // --- PART 3: Transverse & Origami Saddle Crinkle Hubs Between Oranges ---
  const hubs = [
    { x: 265, y: 505, r: 95 },
    { x: 585, y: 495, r: 105 },
    { x: 900, y: 495, r: 95 },
    { x: 185, y: 725, r: 90 },
    { x: 485, y: 715, r: 105 },
    { x: 690, y: 715, r: 105 },
    { x: 985, y: 720, r: 90 },
    { x: 385, y: 880, r: 85 },
    { x: 785, y: 880, r: 85 }
  ];

  for (let h of hubs) {
    let spokePts = [];
    let numSpokes = 7;
    for (let s = 0; s < numSpokes; s++) {
      let a = s * (360 / numSpokes) + random(-14, 14);
      let rad = h.r * random(0.65, 1.25);
      spokePts.push([h.x + cos(a) * rad, h.y + sin(a) * rad]);
    }
    for (let s = 0; s < numSpokes; s++) {
      let p1 = spokePts[s];
      let p2 = spokePts[(s + 1) % numSpokes];
      let tri = [[h.x + random(-8, 8), h.y + random(-8, 8)], p1, p2];
      if (s % 3 === 0) deepStackedVeils.push(tri);
      else if (s % 3 === 1) cyanVeils.push(tri);
      else lilacVeils.push(tri);

      creaseChains.push([[h.x, h.y], p1, p2]);
      slivers.push({
        pts: [
          [h.x, h.y],
          p1,
          [lerp(p1[0], p2[0], 0.35), lerp(p1[1], p2[1], 0.35)]
        ],
        col: s % 2 === 0 ? "#8cf6ff" : "#dfadff",
        ang: atan2(p1[1] - h.y, p1[0] - h.x)
      });
    }
  }

  return { cyanVeils, lilacVeils, deepStackedVeils, iceGlazeVeils, slivers, creaseChains, crownRays, sweepPaths };
}

function drawCellophaneVeils(data) {
  brush.noStroke();
  brush.fillBleed(0.035, "out");
  brush.fillTexture(0.32, 0.24);

  // Batch 1: Deep stacked-fold tint (where multiple cellophane layers overlap, deepening & cooling colors)
  brush.fill("#283066", 54);
  for (let i = 0; i < data.deepStackedVeils.length; i++) {
    drawPoly(data.deepStackedVeils[i], 0);
  }

  // Batch 2: Pale cyan & cerulean transparent film veils
  brush.fill("#66dcff", 44);
  for (let i = 0; i < data.cyanVeils.length; i++) {
    drawPoly(data.cyanVeils[i], 0);
  }

  // Batch 3: Prismatic lilac & lavender transparent film veils
  brush.fill("#c892ff", 46);
  for (let i = 0; i < data.lilacVeils.length; i++) {
    drawPoly(data.lilacVeils[i], 0);
  }

  // Batch 4: Specular milky-ice sheen veils
  brush.fill("#e2f8ff", 52);
  for (let i = 0; i < data.iceGlazeVeils.length; i++) {
    drawPoly(data.iceGlazeVeils[i], 0);
  }

  brush.noFill();
}

function drawPrismaticSlivers(data, oranges, knot) {
  // Draw razor-edged prismatic shards along creases in pale cyan, lilac, orchid, and aqua
  brush.noStroke();
  for (let i = 0; i < data.slivers.length; i++) {
    let s = data.slivers[i];
    brush.wash(s.col, i % 3 === 0 ? 135 : 95);
    drawPoly(s.pts, 0);
  }
  brush.noWash();

  // Add tangential prismatic slivers hugging the contact halos of every orange
  const haloCols = ["#94f7ff", "#e0aaff", "#78d8ff", "#ffb0f2", "#a6ffea", "#ffffff"];
  for (let o of oranges) {
    let numShards = 14;
    for (let i = 0; i < numShards; i++) {
      let a1 = i * (360 / numShards) + random(-8, 8);
      let a2 = a1 + random(14, 28);
      let rIn = o.r * random(0.50, 0.78);
      let rOut = rIn + random(8, 22);

      let shard = [
        [o.x + cos(a1) * rIn, o.y + sin(a1) * rIn],
        [o.x + cos((a1 + a2) * 0.5) * rOut, o.y + sin((a1 + a2) * 0.5) * rOut],
        [o.x + cos(a2) * rIn, o.y + sin(a2) * rIn],
        [o.x + cos((a1 + a2) * 0.5) * (rIn - 5), o.y + sin((a1 + a2) * 0.5) * (rIn - 5)]
      ];
      let col = haloCols[(i + floor(o.x)) % haloCols.length];
      brush.noStroke();
      brush.wash(col, random(95, 165));
      drawPoly(shard, 0);
    }
  }
  brush.noWash();
}

function drawCellophaneStretchTextures(data, oranges, knot) {
  // Fine parallel stretch-striations inside select slivers and tension bands
  for (let i = 0; i < data.slivers.length; i += 2) {
    let s = data.slivers[i];
    brush.hatchStyle("rotring", i % 4 === 0 ? "#ffffff" : s.col, 0.55);
    brush.hatch(3.2, s.ang, { rand: 0.03 });
    drawPoly(s.pts, 0);
  }
  brush.noHatch();

  // Prismatic chisel-marker strokes along the gathered neck & main fold ridges
  const prismMarkerCols = ["#7ceeff", "#d69eff", "#85b4ff", "#ff88d8", "#b8fff0"];
  for (let c = 0; c < prismMarkerCols.length; c++) {
    brush.set("chisel", prismMarkerCols[c], 0.9);
    for (let i = c; i < data.creaseChains.length; i += prismMarkerCols.length) {
      let ch = data.creaseChains[i];
      if (ch.length >= 3) {
        brush.spline([
          [ch[0][0] + 3, ch[0][1], 0.6],
          [ch[1][0] + 3, ch[1][1], 1.1],
          [ch[2][0] + 3, ch[2][1], 0.5]
        ], 0.15);
      }
    }
  }
}

// ============================================================================
// 9. CURLING MAGENTA RIBBON (KNOT, BOW LOOPS & HELICAL CASCADES)
// ============================================================================

function drawMagentaRibbonSystem(knot, oranges) {
  // Define 7 cascading helical curling ribbon streamers radiating from the knot
  const streamers = [
