      w: 40, freq: 4.8, phase: 1.8, amp: 30
    },
    // 3. Central dramatic corkscrew ribbon tumbling straight down over the center oranges
    {
      pts: [[knot.x, knot.y + 15], [565, 410], [610, 565], [545, 725], [595, 895], [560, 1045]],
      w: 42, freq: 5.5, phase: 0.0, amp: 32
    },
    // 4. Sweeping down-right across the right hero orange
    {
      pts: [[knot.x + 12, knot.y + 10], [690, 385], [765, 525], [845, 680], [895, 845], [945, 995]],
      w: 38, freq: 4.6, phase: 2.5, amp: 28
    },
    // 5. High right cascade arching over the upper-right orange
    {
      pts: [[knot.x + 18, knot.y + 4], [750, 310], [920, 395], [1045, 520], [1125, 665], [1165, 790]],
      w: 35, freq: 5.0, phase: 1.1, amp: 25
    },
    // 6. Fine split tendril curling tightly to the upper-left
    {
      pts: [[knot.x - 20, knot.y - 4], [430, 255], [295, 295], [175, 375], [95, 465]],
      w: 18, freq: 6.5, phase: 0.9, amp: 22
    },
    // 7. Fine split tendril curling tightly to the mid-right
    {
      pts: [[knot.x + 20, knot.y + 8], [665, 335], [720, 445], [685, 575], [735, 695]],
      w: 19, freq: 6.2, phase: 3.1, amp: 22
    }
  ];

  // Draw drop-shadows on the cellophane underneath the ribbons first
  brush.set("marker", "#280936", 2.2);
