  // Draw the tight central gathered ribbon collar & knot at (knot.x, knot.y)
  drawRibbonKnotCore(knot.x, knot.y);
}

function evalCatmullRom(pts, t) {
  let n = pts.length - 1;
  let f = constrain(t, 0, 0.9999) * n;
  let i = floor(f);
  let u = f - i;
  let p0 = pts[max(0, i - 1)];
  let p1 = pts[i];
  let p2 = pts[min(n, i + 1)];
  let p3 = pts[min(n, i + 2)];

  let u2 = u * u;
  let u3 = u2 * u;
  let x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * u + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * u2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * u3);
  let y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * u + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * u2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * u3);
  return [x, y];
}

function drawHelicalCurlingRibbon(ctrlPts, ribbonW, freq, phase0, amp) {
  const steps = 68;
  let edgeA = [];
  let edgeB = [];
  let normals = [];

  for (let s = 0; s <= steps; s++) {
    let t = s / steps;
    let p = evalCatmullRom(ctrlPts, t);
    let pNext = evalCatmullRom(ctrlPts, min(1, t + 0.015));
    let dx = pNext[0] - p[0];
    let dy = pNext[1] - p[1];
    let len = max(0.001, sqrt(dx * dx + dy * dy));
    let nx = -dy / len;
    let ny = dx / len;
    let tx = dx / len;
    let ty = dy / len;

    // Helical corkscrew oscillation
    let theta = (t * freq * 360) + phase0 * 57.3;
    let wave = sin(theta) * amp * (0.35 + 0.65 * sin(t * 165));
    let twist = cos(theta); // determines front/back face & apparent width

    let cx = p[0] + nx * wave;
    let cy = p[1] + ny * wave;

    // Width vector rotates slightly with the helix
    let halfW = ribbonW * 0.5 * (0.28 + 0.72 * abs(twist)) * (1 - t * 0.22);
    let wx = (nx * 0.35 + tx * 0.65) * halfW;
    let wy = (ny * 0.35 + ty * 0.65) * halfW;

    edgeA.push([cx - wx, cy - wy]);
    edgeB.push([cx + wx, cy + wy]);
    normals.push(twist);
  }

  // Render quad segments with glossy satin-magenta & cool specular palette
  brush.noStroke();
  for (let s = 0; s < steps; s++) {
    let quad = [edgeA[s], edgeB[s], edgeB[s + 1], edgeA[s + 1]];
    let tw = normals[s];
    let col;
    if (tw < -0.55) col = "#4a002c";       // deep inner curl shadow
    else if (tw < -0.15) col = "#7d0049";  // shaded maroon-magenta
    else if (tw < 0.25) col = "#bf006a";   // rich quinacridone magenta
    else if (tw < 0.62) col = "#f20085";   // electric hot magenta
    else if (tw < 0.84) col = "#ff4db2";   // luminous rose-magenta
    else if (tw < 0.94) col = "#ffb8e6";   // icy lilac-pink sheen
    else col = "#ffffff";                  // razor-sharp cylinder highlight

    brush.wash(col, 242);
    drawPoly(quad, 0);
  }
  brush.noWash();

  // Fine longitudinal satin striations & crisp slit edges
  for (let s = 0; s < steps; s++) {
    let tw = normals[s];
    // Specular white + pale cyan bar across peak of each cylinder turn
    if (tw > 0.78) {
      brush.set("razor", "#ffffff", 1.15);
      brush.line(edgeA[s][0], edgeA[s][1], edgeB[s][0], edgeB[s][1]);
      brush.set("razor", "#9ef8ff", 0.75);
      brush.line(edgeA[s + 1][0], edgeA[s + 1][1], edgeB[s + 1][0], edgeB[s + 1][1]);
    } else if (tw < -0.5) {
      brush.set("rotring", "#2b0019", 0.85);
      brush.line(edgeA[s][0], edgeA[s][1], edgeB[s][0], edgeB[s][1]);
    }

    // Crisp edge definition along both margins of the ribbon
    let edgeCol = tw > 0.3 ? "#ffd6f2" : "#590033";
    brush.set("rotring", edgeCol, 0.75);
    brush.line(edgeA[s][0], edgeA[s][1], edgeA[s + 1][0], edgeA[s + 1][1]);
    brush.line(edgeB[s][0], edgeB[s][1], edgeB[s + 1][0], edgeB[s + 1][1]);
  }
}

function drawRibbonBowLoop(kx, ky, ang, len, spread, w) {
  let tipX = kx + cos(ang) * len;
  let tipY = ky + sin(ang) * len;
  let perpX = -sin(ang);
  let perpY = cos(ang);

  // Under-fold of the loop (dark quinacridone violet)
  let underLoop = [
    [kx, ky],
    [kx + cos(ang) * len * 0.65 - perpX * spread * 0.65, ky + sin(ang) * len * 0.65 - perpY * spread * 0.65],
    [tipX - perpX * spread * 0.25, tipY - perpY * spread * 0.25],
    [tipX + perpX * spread * 0.35, tipY + perpY * spread * 0.35],
    [kx + cos(ang) * len * 0.55 + perpX * spread * 0.55, ky + sin(ang) * len * 0.55 + perpY * spread * 0.55]
  ];
  brush.noStroke();
  brush.wash("#590036", 240);
  drawPoly(underLoop, 0.2);

  // Upper glossy face of the bow loop
  let upperLoop = [
    [kx, ky],
    [kx + cos(ang) * len * 0.48 - perpX * spread * 0.45, ky + sin(ang) * len * 0.48 - perpY * spread * 0.45],
    [tipX - perpX * spread * 0.15, tipY - perpY * spread * 0.15],
    [tipX + perpX * spread * 0.42, tipY + perpY * spread * 0.42],
    [kx + cos(ang) * len * 0.68 + perpX * spread * 0.68, ky + sin(ang) * len * 0.68 + perpY * spread * 0.68]
  ];
  brush.wash("#e00078", 240);
  drawPoly(upperLoop, 0.22);

  // Bright hot-pink & white specular band across the bend of the loop
  let highlightBand = [
    [kx + cos(ang) * len * 0.58 - perpX * spread * 0.3, ky + sin(ang) * len * 0.58 - perpY * spread * 0.3],
    [kx + cos(ang) * len * 0.80 - perpX * spread * 0.2, ky + sin(ang) * len * 0.80 - perpY * spread * 0.2],
    [kx + cos(ang) * len * 0.84 + perpX * spread * 0.35, ky + sin(ang) * len * 0.84 + perpY * spread * 0.35],
    [kx + cos(ang) * len * 0.62 + perpX * spread * 0.45, ky + sin(ang) * len * 0.62 + perpY * spread * 0.45]
  ];
  brush.wash("#ff7ad1", 210);
  drawPoly(highlightBand, 0.1);
  brush.noWash();

  // Satin sheen hatching & crisp white specular streaks on the bow loop
  brush.hatchStyle("rotring", "#ffccf0", 0.65);
  brush.hatch(3.2, ang + 90, { rand: 0.04 });
  drawPoly(highlightBand, 0.05);
  brush.noHatch();

  brush.set("razor", "#ffffff", 1.1);
  brush.line(
    kx + cos(ang) * len * 0.72 - perpX * spread * 0.22,
    ky + sin(ang) * len * 0.72 - perpY * spread * 0.22,
    kx + cos(ang) * len * 0.75 + perpX * spread * 0.36,
    ky + sin(ang) * len * 0.75 + perpY * spread * 0.36
  );

  // Crisp loop outline & pinched gathers near the knot
  brush.set("rotring", "#3b0022", 0.85);
  drawPoly(upperLoop, 0.22);
  for (let i = -2; i <= 2; i++) {
    brush.set("rotring", i === 0 ? "#ffffff" : "#6e003f", 0.75);
    brush.line(
      kx,
      ky,
      kx + cos(ang + i * 6) * len * 0.38,
      ky + sin(ang + i * 6) * len * 0.38
    );
  }
}

function drawRibbonKnotCore(kx, ky) {
  // Tightly wrapped multi-fold magenta knot constricting the cellophane waist
  const knotFolds = [
    { pts: [[kx - 36, ky - 14], [kx + 34, ky - 18], [kx + 38, ky + 10], [kx - 32, ky + 16]], col: "#9e0054" },
    { pts: [[kx - 28, ky - 20], [kx + 22, ky - 8], [kx + 18, ky + 20], [kx - 34, ky + 8]], col: "#e6007a" },
    { pts: [[kx - 16, ky - 16], [kx + 28, ky - 14], [kx + 24, ky + 14], [kx - 12, ky + 18]], col: "#ff2498" }
  ];

  for (let f of knotFolds) {
    brush.noStroke();
    brush.wash(f.col, 245);
    drawPoly(f.pts, 0.15);
    brush.noWash();

    brush.set("rotring", "#3d0022", 0.9);
    drawPoly(f.pts, 0.15);
  }

  // Intense white & pale-cyan creases across the knot folds
  for (let i = 0; i < 9; i++) {
    let yOff = map(i, 0, 8, -14, 14);
    brush.set("razor", i % 2 === 0 ? "#ffffff" : "#ffbdf0", 1.0);
    brush.spline([
      [kx - 26, ky + yOff - 3, 0.5],
      [kx, ky + yOff + random(-4, 4), 1.2],
      [kx + 26, ky + yOff + 2, 0.5]
    ], 0.35);
  }
}

// ============================================================================
// 10. HARD WHITE FRACTURE-HIGHLIGHTS IN CRISP PEN ALONG EVERY CREASE
// ============================================================================

function drawCellophaneFractureHighlights(data, oranges, knot, rimCurve) {
  // Step A: Draw dark/cool refraction counter-lines 2px beside every major crease first
  // so the hard white pen lines pop with hyperreal optical contrast
  for (let i = 0; i < data.creaseChains.length; i++) {
    let ch = data.creaseChains[i];
    let col = i % 3 === 0 ? "#182b4d" : (i % 3 === 1 ? "#361852" : "#006b8f");
    brush.set("rotring", col, 0.7);
    for (let j = 0; j < ch.length - 1; j++) {
      drawFracturedSegment(ch[j][0] + 2.2, ch[j][1] + 1.5, ch[j + 1][0] + 2.2, ch[j + 1][1] + 1.5, 2, 7);
    }
  }

  // Step B: Hard white & icy cyan double-tracked fracture-highlights along all major crease chains
  for (let i = 0; i < data.creaseChains.length; i++) {
    let ch = data.creaseChains[i];
    for (let j = 0; j < ch.length - 1; j++) {
      let x1 = ch[j][0];
      let y1 = ch[j][1];
      let x2 = ch[j + 1][0];
      let y2 = ch[j + 1][1];

      // Primary razor-crisp white fracture line
      brush.set("razor", "#ffffff", random(0.95, 1.35));
      let ridgePts = generateZigZagPoints(x1, y1, x2, y2, 4, 11);
      for (let k = 0; k < ridgePts.length - 1; k++) {
        brush.line(ridgePts[k][0], ridgePts[k][1], ridgePts[k + 1][0], ridgePts[k + 1][1]);
      }

      // Secondary parallel twin-ridge line (cellophane folds have two sharp bevel edges!)
      let dx = x2 - x1;
      let dy = y2 - y1;
      let len = max(1, sqrt(dx * dx + dy * dy));
      let nx = (-dy / len) * random(2.5, 5.5);
      let ny = (dx / len) * random(2.5, 5.5);

      brush.set("rotring", i % 2 === 0 ? "#d6faff" : "#f2e0ff", 0.75);
      for (let k = 0; k < ridgePts.length - 1; k++) {
        if (k % 2 === 0) {
          brush.line(
            ridgePts[k][0] + nx,
            ridgePts[k][1] + ny,
            ridgePts[k + 1][0] + nx,
            ridgePts[k + 1][1] + ny
          );
        }
        // Tiny cross-bridge glints connecting the double fold ridge
        if (random() < 0.55) {
          brush.set("razor", "#ffffff", 0.8);
          brush.line(ridgePts[k][0], ridgePts[k][1], ridgePts[k][0] + nx * 1.4, ridgePts[k][1] + ny * 1.4);
        }
      }

      // Sharp triangular specular facet elbows at kink vertices
      for (let k = 1; k < ridgePts.length - 1; k++) {
        if (random() < 0.65) {
          let vx = ridgePts[k][0];
          let vy = ridgePts[k][1];
          let glintTri = [
            [vx, vy],
            [vx + random(-14, 14), vy + random(-8, 8)],
            [vx + random(-8, 8), vy + random(-14, 14)]
          ];
          brush.noStroke();
          brush.wash("#ffffff", 220);
          drawPoly(glintTri, 0);
          brush.noWash();

          brush.set("razor", "#ffffff", 0.9);
          drawPoly(glintTri, 0);
        }
      }
    }
  }

  // Step C: Polygonal Contact Halos & Specular Crinkle Rings Over Each Orange
  for (let o of oranges) {
    // Polygonal tension ring where taut plastic lifts off the curved orange surface
    let ringSides = 11;
    let ringPts = [];
    for (let s = 0; s < ringSides; s++) {
      let a = s * (360 / ringSides) + random(-10, 10);
      let rad = o.r * random(0.48, 0.72);
      ringPts.push([o.x + cos(a) * rad, o.y + sin(a) * rad]);
    }

    for (let s = 0; s < ringSides; s++) {
      let p1 = ringPts[s];
      let p2 = ringPts[(s + 1) % ringSides];
      if (random() < 0.78) {
        // Cool refraction shadow edge
        brush.set("rotring", "#241d4a", 0.65);
        brush.line(p1[0] + 2, p1[1] + 2, p2[0] + 2, p2[1] + 2);

        // Hard white fracture crease
        brush.set("razor", "#ffffff", random(0.85, 1.2));
        drawFracturedSegment(p1[0], p1[1], p2[0], p2[1], 2, 6);

        // Short combing micro-wrinkle ticks perpendicular to the contact halo
        let midX = (p1[0] + p2[0]) * 0.5;
        let midY = (p1[1] + p2[1]) * 0.5;
        let outAng = atan2(midY - o.y, midX - o.x);
        for (let t = -2; t <= 2; t++) {
          let tx = midX + cos(outAng + 90) * t * 6;
          let ty = midY + sin(outAng + 90) * t * 6;
          let tLen = random(10, 26);
          brush.set("razor", t === 0 ? "#ffffff" : "#bff6ff", 0.7);
          brush.line(tx, ty, tx + cos(outAng) * tLen, ty + sin(outAng) * tLen);
        }
      }
    }

    // Specular glare window on the upper-left slope of each orange dome
    let gx = o.x + cos(-58) * o.r * 0.34;
    let gy = o.y + sin(-58) * o.r * 0.34;
    let glareShard1 = [
      [gx - 28, gy + 12],
      [gx - 4, gy - 22],
      [gx + 32, gy - 8],
      [gx + 8, gy + 18]
    ];
    let glareShard2 = [
      [gx - 18, gy + 28],
      [gx + 16, gy + 8],
      [gx + 38, gy + 22],
      [gx + 4, gy + 36]
    ];
    brush.noStroke();
    brush.wash("#ffffff", 165);
    drawPoly(glareShard1, 0);
    brush.wash("#bdf6ff", 145);
    drawPoly(glareShard2, 0);
    brush.noWash();

    brush.set("razor", "#ffffff", 1.15);
    drawPoly(glareShard1, 0);
    drawPoly(glareShard2, 0);
  }

  // Step D: Dense Bunched Plastic Crinkles Along the Gathered Neck & Wicker Rim
  // 1. Neck constriction explosion around knot
  for (let i = 0; i < 65; i++) {
    let a = random(360);
    let r1 = random(18, 55);
    let r2 = r1 + random(28, 95);
    let x1 = knot.x + cos(a) * r1 * 1.2;
    let y1 = knot.y + sin(a) * r1 * 0.65;
    let x2 = knot.x + cos(a + random(-14, 14)) * r2 * 1.25;
    let y2 = knot.y + sin(a + random(-14, 14)) * r2 * 0.85;

    brush.set("razor", i % 3 === 0 ? "#9ef8ff" : "#ffffff", random(0.75, 1.2));
    drawFracturedSegment(x1, y1, x2, y2, 2, 8);
  }

  // 2. Crinkled plastic skirt overlapping the top of the wicker basket rim
  for (let x = 20; x < 1180; x += 28) {
    let ry = rimCurve(x);
    let x1 = x + random(-10, 10);
    let y1 = ry + random(-45, -10);
    let x2 = x1 + random(-28, 28);
    let y2 = ry + random(5, 42);
    let x3 = x2 + random(-24, 24);
    let y3 = y1 + random(-15, 20);

    // Translucent cyan/lilac triangle fold over the wicker rim
    if (x % 56 === 0) {
      brush.noStroke();
      brush.wash(x % 112 === 0 ? "#8cf4ff" : "#dfa8ff", 90);
      drawPoly([[x1, y1], [x2, y2], [x3, y3]], 0);
      brush.noWash();
    }

    // Crisp white zig-zag crease at the basket rim
    brush.set("razor", "#ffffff", random(0.8, 1.15));
    brush.line(x1, y1, x2, y2);
    brush.line(x2, y2, x3, y3);
  }

  // Step E: Glittering Specular Noise — Micro-Diamonds, Forked Lightning Creases & Star-Glints
  for (let i = 0; i < 160; i++) {
    let px = random(30, 1170);
    let py = random(60, rimCurve(px) + 15);
    // Skip upper outer corners outside the cellophane fan
    if (py < 260 && abs(px - knot.x) > map(py, 0, 260, 480, 160)) continue;

    let ang = atan2(py - knot.y, px - knot.x) + random(-35, 35);
    let len = random(16, 52);
    let mx = px + cos(ang) * len * 0.5 + cos(ang + 90) * random(-9, 9);
    let my = py + sin(ang) * len * 0.5 + sin(ang + 90) * random(-9, 9);
    let ex = px + cos(ang) * len;
    let ey = py + sin(ang) * len;

    // Forked Y-crease in crisp white pen
    brush.set("razor", "#ffffff", random(0.7, 1.1));
    brush.line(px, py, mx, my);
    brush.line(mx, my, ex, ey);
    if (random() < 0.5) {
      let fx = mx + cos(ang + random(22, 48)) * len * 0.45;
      let fy = my + sin(ang + random(22, 48)) * len * 0.45;
      brush.set("rotring", "#b8f8ff", 0.7);
      brush.line(mx, my, fx, fy);
    }

    // Pinpoint specular star-glint at vertices
    if (i % 4 === 0) {
      let gSize = random(4, 9);
      brush.set("razor", "#ffffff", 1.1);
      brush.line(mx - gSize, my, mx + gSize, my);
      brush.line(mx, my - gSize, mx, my + gSize);
    }
  }
}

function generateZigZagPoints(x1, y1, x2, y2, steps, jitter) {
  let pts = [[x1, y1]];
  let dx = x2 - x1;
  let dy = y2 - y1;
  let len = max(1, sqrt(dx * dx + dy * dy));
  let nx = -dy / len;
  let ny = dx / len;

  for (let i = 1; i < steps; i++) {
    let t = i / steps + random(-0.06, 0.06);
    let offset = (i % 2 === 0 ? 1 : -1) * random(jitter * 0.35, jitter);
    pts.push([
      lerp(x1, x2, t) + nx * offset,
      lerp(y1, y2, t) + ny * offset
    ]);
  }
  pts.push([x2, y2]);
  return pts;
}

function drawFracturedSegment(x1, y1, x2, y2, steps, jitter) {
  let pts = generateZigZagPoints(x1, y1, x2, y2, steps, jitter);
  for (let i = 0; i < pts.length - 1; i++) {
    brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
  }
}

// Hyperreal Inflated Pufferfish in Reverse Appliqué (Mola) & Graphite
// p5.js 2.x + p5.brush

const CX = 600;
const CY = 620;
const R_BODY = 415;

const LEFT_EYE = { x: 388, y: 462, r: 62, turretR: 122 };
const RIGHT_EYE = { x: 812, y: 462, r: 62, turretR: 122 };
const MOUTH = { x: 600, y: 692, rx: 56, ry: 40, turretRx: 118, turretRy: 92 };

// Palette combining reverse-appliqué Scarlet, Tangerine, Black, Emerald
// with a Deep Indigo ground and Soft Pastel under-layers
const PALETTE = {
  indigoDeep: "#0e1229",
  indigoMid: "#171f42",
  indigoRim: "#293569",
  cutShadow: "#070812",

  // Core 4 alternating reverse-appliqué band colors (softened chalky-mola richness)
  bands: [
    "#e35458", // Scarlet (warm coral-vermilion)
    "#f4955c", // Tangerine (apricot-marigold)
    "#171822", // Velvet Black
    "#389c7c", // Emerald (celadon-jade)
    "#ec6b70", // Softened Pastel Scarlet
    "#f9ad78", // Softened Pastel Tangerine
    "#1b1c28", // Deep Charcoal-Black
    "#4eb392"  // Softened Pastel Emerald
  ],

  // Soft pastel lower-layer reveals inside narrow slits
  pastels: [
    "#ffa6b0", // Pastel rose-scarlet
    "#ffd1b3", // Pastel peach-tangerine
    "#9ce6cb", // Pastel mint-emerald
    "#b8c4f5", // Pastel periwinkle-indigo
    "#fff0c4", // Pastel buttercream
    "#f7b5d8", // Pastel orchid pink
    "#a8f0e8"  // Pastel aqua
  ],

  ivoryBase: "#f6f1e6",
  ivoryLit: "#fffdf9",
  graphiteDark: "#232538",
  graphiteMid: "#565a73",
  graphiteLight: "#8e92a8"
};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7341);
  noiseSeed(7341);
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();
  brush.set("HB", PALETTE.cutShadow, 0.3);

  // 1. Deep Indigo Ground & Tiny Repeated Slit-Channels
  drawIndigoGroundAndSlits();

  // 2. Pectoral, Dorsal & Ventral Fins
  drawAllFins();

  // 3. Stacked Reverse-Appliqué Body Bands & Narrow Slits
  drawBodyAppliqueLayers();

  // 4. Topological Reverse-Appliqué Turrets (Eyes & Mouth Mounds)
  drawFeatureTurrets();

  // 5. Subtle 3D Spherical Form Shading Over the Inflated Body
  drawVolumetricBodyShading();

  // 6. Hyperreal Beak / Mouth Opening
  drawHyperrealMouth();

  // 7. Hyperreal Spines (Pencil-Shaded Cones + Pinpoint Highlights)
  drawAllHyperrealSpines();

  // 8. Wet, Glassy Eyes (Corneal Domes, Iris Striations, Tear Meniscus)
  drawWetGlassyEye(LEFT_EYE.x, LEFT_EYE.y, LEFT_EYE.r, -1);
  drawWetGlassyEye(RIGHT_EYE.x, RIGHT_EYE.y, RIGHT_EYE.r, 1);

  noLoop();
}

// ============================================================================
// GEOMETRY & HAND-CUT WOBBLE HELPERS
// ============================================================================

function getBodyRadiusAtAngle(ang, rFrac) {
  // Organic inflated pufferfish contour: swollen cheeks, broad belly, slight forehead dip
  let rad = R_BODY;
  let cheekSwell = 14 * exp(-pow(((ang + 38 + 360) % 360 - 180) / 42, 2)) +
                   14 * exp(-pow(((ang + 142 + 360) % 360 - 180) / 42, 2));
  let bellySwell = 18 * pow(max(0, sin(ang)), 1.6);
  let topDip = -8 * pow(max(0, -sin(ang)), 4);
  let shapeMod = (cheekSwell + bellySwell + topDip) * pow(rFrac, 0.75);
  return rad * rFrac + shapeMod;
}

function getBodyPoint(ang, rFrac, wobbleAmp = 3.2, seedOffset = 0) {
  // Shift inner concentric rings slightly downward toward the swollen belly front
  let shiftY = (1 - rFrac) * 28;
  let r = getBodyRadiusAtAngle(ang, rFrac);
  let nx = cos(ang) * 2.2 + seedOffset * 1.7;
  let ny = sin(ang) * 2.2 + seedOffset * 2.3;
  let wob = (noise(nx + 20, ny + 20) - 0.5) * 2 * wobbleAmp;
  let finalR = max(4, r + wob);
  return [
    CX + cos(ang) * finalR,
    CY + shiftY + sin(ang) * finalR
  ];
}

function fillAndStrokePoly(pts, fillCol, fillAlpha, strokeBrush, strokeCol, strokeW) {
  if (pts.length < 3) return;
  let poly = new brush.Polygon(pts);
  poly.wash(fillCol, fillAlpha);
  if (strokeBrush && strokeCol) {
    brush.set(strokeBrush, strokeCol, strokeW);
    let closedPts = pts.slice();
    closedPts.push(pts[0]);
    brush.spline(closedPts, 0.25);
  }
}

// ============================================================================
// 1. DEEP INDIGO GROUND & TINY REPEATED SLIT-CHANNELS
// ============================================================================

function drawIndigoGroundAndSlits() {
  background(PALETTE.indigoDeep);

  // Deep textile base washes
  let bgRect = new brush.Polygon([[0, 0], [1200, 0], [1200, 1200], [0, 1200]]);
  bgRect.wash(PALETTE.indigoDeep, 255);

  // Subtle indigo tonal variation across the cloth ground
  brush.noStroke();
  brush.fill(PALETTE.indigoMid, 95);
  brush.fillBleed(0.35);
  brush.fillTexture(0.55, 0.3);
  brush.circle(600, 600, 560, 0.2);
  brush.noFill();

  // Concentric tracks of tiny repeated slit-channels filling the indigo ground
  let ringSpacing = 20;
  let ringIdx = 0;

  for (let r = R_BODY + 24; r < 890; r += ringSpacing) {
    let circum = TWO_PI * r;
    let slitArcLen = 23 + (ringIdx % 3) * 4;
    let gapArcLen = 11;
    let count = floor(circum / (slitArcLen + gapArcLen));
    let dAng = 360 / count;
    let radialSlitMode = (ringIdx % 5 === 3);

    for (let i = 0; i < count; i++) {
      let ang = i * dAng + (ringIdx % 2) * (dAng * 0.5);
      let radAtAng = getBodyRadiusAtAngle(ang, 1.0) + (r - R_BODY);
      let mx = CX + cos(ang) * radAtAng;
      let my = CY + sin(ang) * radAtAng;

      // Skip if outside canvas bounds with margin
      if (mx < -15 || mx > 1215 || my < -15 || my > 1215) continue;

      // Pick slit reveal color: alternating soft pastels and mola jewel tones
      let colPool = ( (i + ringIdx) % 2 === 0 ) ? PALETTE.pastels : PALETTE.bands;
      let revealCol = colPool[(i * 3 + ringIdx * 5) % colPool.length];
      if (revealCol === "#171822" || revealCol === "#1b1c28") {
        revealCol = PALETTE.pastels[(i + ringIdx) % PALETTE.pastels.length];
      }

      let orientAng = radialSlitMode ? ang : ang + 90;
      let halfL = radialSlitMode ? 7.5 : slitArcLen * 0.44;
      let halfW = radialSlitMode ? 3.2 : 3.4;

      drawTinySlitChannel(mx, my, orientAng, halfL, halfW, revealCol, ringIdx * 100 + i);
    }
    ringIdx++;
  }
}

function drawTinySlitChannel(cx, cy, ang, halfL, halfW, revealCol, seed) {
  let ca = cos(ang);
  let sa = sin(ang);
  let nx = -sa;
  let ny = ca;

  // Hand-cut wobbly 6-point almond/slit polygon
  let pts = [];
  let steps = [
    [-halfL, 0],
    [-halfL * 0.45, -halfW],
    [halfL * 0.45, -halfW],
    [halfL, 0],
    [halfL * 0.45, halfW],
    [-halfL * 0.45, halfW]
  ];

  for (let k = 0; k < steps.length; k++) {
    let wob = (noise(seed * 0.13 + k * 1.7) - 0.5) * 1.8;
    let lx = steps[k][0] + wob;
    let ly = steps[k][1] + wob * 0.7;
    pts.push([cx + lx * ca + ly * nx, cy + lx * sa + ly * ny]);
  }

  // Outer indigo raised stitch-lip
  brush.set("cpencil", PALETTE.indigoRim, 0.25);
  brush.line(
    cx - halfL * 0.85 * ca - (halfW + 1.8) * nx,
    cy - halfL * 0.85 * sa - (halfW + 1.8) * ny,
    cx + halfL * 0.85 * ca - (halfW + 1.8) * nx,
    cy + halfL * 0.85 * sa - (halfW + 1.8) * ny
  );

  // Colored lower-layer peek-through
  let poly = new brush.Polygon(pts);
  poly.wash(revealCol, 240);

  // Inner dark slit cut-line
  brush.set("rotring", PALETTE.cutShadow, 0.26);
  brush.line(
    cx - halfL * 0.72 * ca,
    cy - halfL * 0.72 * sa,
    cx + halfL * 0.72 * ca,
    cy + halfL * 0.72 * sa
  );
}

// ============================================================================
// 2. FINS (PECTORAL, DORSAL, CAUDAL/VENTRAL)
// ============================================================================

function drawAllFins() {
  // Left Pectoral Fin
  drawFinFan(205, 642, 188, 132, 152, 208, -1);
  // Right Pectoral Fin
  drawFinFan(995, 642, 0, 132, -28, 28, 1);
  // Dorsal Fin (top back)
  drawFinFan(600, 212, -90, 96, -116, -64, 0);
  // Caudal/Anal Fin hint (bottom back)
  drawFinFan(600, 1022, 90, 88, 66, 114, 0);
}

function drawFinFan(bx, by, centerAng, finLen, startAng, endAng, side) {
  // Translucent pleated membrane fan
  let fanPts = [[bx, by]];
  let numRays = 14;
  for (let i = 0; i <= numRays; i++) {
    let f = i / numRays;
    let a = lerp(startAng, endAng, f);
    let scallop = sin(f * numRays * 180) * 6;
    let r = finLen * (0.85 + 0.15 * sin(f * 180)) + scallop;
    fanPts.push([bx + cos(a) * r, by + sin(a) * r]);
  }

  // Base shadow on indigo ground
  let shadowPoly = new brush.Polygon(fanPts.map(p => [p[0] + 6, p[1] + 9]));
  shadowPoly.wash(PALETTE.cutShadow, 170);

  // Soft pastel membrane layers
  let memPoly = new brush.Polygon(fanPts);
  memPoly.wash("#ffd6c2", 215);

  // Inner colored appliqué band at fin base
  let midPts = [[bx, by]];
  for (let i = 0; i <= numRays; i++) {
    let a = lerp(startAng, endAng, i / numRays);
    midPts.push([bx + cos(a) * (finLen * 0.46), by + sin(a) * (finLen * 0.46)]);
  }
  fillAndStrokePoly(midPts, "#e35458", 240, "rotring", PALETTE.cutShadow, 0.3);

  let innerPts = [[bx, by]];
  for (let i = 0; i <= numRays; i++) {
    let a = lerp(startAng, endAng, i / numRays);
    innerPts.push([bx + cos(a) * (finLen * 0.28), by + sin(a) * (finLen * 0.28)]);
  }
  fillAndStrokePoly(innerPts, "#389c7c", 245, "rotring", PALETTE.cutShadow, 0.3);

  // Fin rays in hyperreal pencil & white highlight
  for (let i = 0; i <= numRays; i++) {
    let f = i / numRays;
    let a = lerp(startAng, endAng, f);
    let r = finLen * (0.85 + 0.15 * sin(f * 180));
    let rx0 = bx + cos(a) * (finLen * 0.26);
    let ry0 = by + sin(a) * (finLen * 0.26);
    let rx1 = bx + cos(a) * r;
    let ry1 = by + sin(a) * r;

    // Dark graphite side of ray
    brush.set("HB", PALETTE.graphiteDark, 0.26);
    brush.line(rx0, ry0, rx1, ry1);

    // Luminous pastel-ivory cartilage ray ridge
    brush.set("cpencil", PALETTE.ivoryLit, 0.32);
    brush.line(rx0 - sin(a) * 1.5, ry0 + cos(a) * 1.5, rx1 - sin(a) * 1.5, ry1 + cos(a) * 1.5);
  }

  // Scalloped membrane rim
  let rimPts = fanPts.slice(1);
  brush.set("2H", PALETTE.ivoryLit, 0.25);
  brush.spline(rimPts, 0.3);
}

// ============================================================================
// 3. STACKED REVERSE-APPLIQUÉ BODY BANDS & NARROW SLITS
// ============================================================================

function drawBodyAppliqueLayers() {
  // Drop shadow of the entire inflated sphere onto the indigo textile ground
  let shadowPts = [];
  for (let a = 0; a < 360; a += 4) {
    let p = getBodyPoint(a, 1.015, 2.5, 99);
    shadowPts.push([p[0] + 10, p[1] + 14]);
  }
  let bodyShadow = new brush.Polygon(shadowPts);
  bodyShadow.wash(PALETTE.cutShadow, 210);

  // 24 concentric reverse-appliqué bands from outer perimeter (rFrac=1.0) inward (rFrac=0.04)
  const numBands = 24;
  for (let b = 0; b < numBands; b++) {
    let rOuter = map(b, 0, numBands, 1.0, 0.04);
    let rInner = map(b + 1, 0, numBands, 1.0, 0.04);
    let bandColor = PALETTE.bands[b % PALETTE.bands.length];

    // Generate hand-cut wobbly polygon for this band layer
    let pts = [];
    let angleStep = 3;
    for (let a = 0; a < 360; a += angleStep) {
      pts.push(getBodyPoint(a, rOuter, 3.4, b * 13));
    }

    // Recessed cut-channel shadow edge around this layer
    let cutPts = pts.map(p => [p[0] + 1.5, p[1] + 2.2]);
    let cutPoly = new brush.Polygon(cutPts);
    cutPoly.wash(PALETTE.cutShadow, 225);

    // Flat marker fill + marker stroke along the wobbly contour edge
    let poly = new brush.Polygon(pts);
    poly.wash(bandColor, 255);

    let closedPts = pts.slice();
    closedPts.push(pts[0]);
    brush.set("marker", bandColor, 0.55);
    brush.spline(closedPts, 0.25);

    // Fine hand-cut contour outline
    brush.set("rotring", PALETTE.cutShadow, 0.28);
    brush.spline(closedPts, 0.25);

    // Carve narrow reverse-appliqué slits inside this band revealing lower layers
    if (b < numBands - 1) {
      drawSlitsInBodyBand(b, rOuter, rInner, bandColor);
    }
  }
}

function drawSlitsInBodyBand(bandIdx, rOuter, rInner, currentBandColor) {
  let rMid = (rOuter + rInner) * 0.5;
  let bandThick = (rOuter - rInner) * R_BODY;
  let avgR = rMid * R_BODY;
  let circum = TWO_PI * avgR;

  let slitLenPx = constrain(avgR * 0.16, 18, 44);
  let gapPx = constrain(avgR * 0.09, 10, 22);
  let numSlits = max(6, floor(circum / (slitLenPx + gapPx)));
  let dAng = 360 / numSlits;

  for (let i = 0; i < numSlits; i++) {
    let aCenter = i * dAng + (bandIdx % 2) * (dAng * 0.5);
    let spanAng = (slitLenPx / max(30, avgR)) * (180 / PI) * 0.42;

    // Lower layer color revealed through the narrow slit (soft pastels + contrasting band colors)
    let revealCol = (i % 2 === 0)
      ? PALETTE.pastels[(bandIdx * 3 + i) % PALETTE.pastels.length]
      : PALETTE.bands[(bandIdx + 2) % PALETTE.bands.length];

    if (revealCol === currentBandColor) {
      revealCol = PALETTE.pastels[(bandIdx + i + 1) % PALETTE.pastels.length];
    }

    // Build narrow wobbly slit polygon following the curved band channel
    let slitPts = [];
    let dr = (rOuter - rInner) * 0.24;
    let steps = 5;

    // Outer edge of slit
    for (let s = 0; s <= steps; s++) {
      let f = s / steps;
      let a = lerp(aCenter - spanAng, aCenter + spanAng, f);
      let pinch = sin(f * 180);
      let r = rMid + dr * pinch;
      slitPts.push(getBodyPoint(a, r, 1.4, bandIdx * 50 + i + s));
    }
    // Inner edge of slit
    for (let s = steps; s >= 0; s--) {
      let f = s / steps;
      let a = lerp(aCenter - spanAng, aCenter + spanAng, f);
      let pinch = sin(f * 180);
      let r = rMid - dr * pinch;
      slitPts.push(getBodyPoint(a, r, 1.4, bandIdx * 50 + i + s + 20));
    }

    let slitPoly = new brush.Polygon(slitPts);
    slitPoly.wash(revealCol, 250);

    // Crisp hand-cut slit edge
    let closedSlit = slitPts.slice();
    closedSlit.push(slitPts[0]);
    brush.set("rotring", PALETTE.cutShadow, 0.24);
    brush.spline(closedSlit, 0.2);

    // Occasional cross-channel notch (authentic Kuna reverse-appliqué bridge cut)
    if ((i + bandIdx) % 4 === 0 && bandThick > 12) {
      let p1 = getBodyPoint(aCenter, rMid + dr * 1.15, 0.8, i);
      let p2 = getBodyPoint(aCenter, rMid - dr * 1.15, 0.8, i + 7);
      brush.set("rotring", PALETTE.cutShadow, 0.3);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
}

// ============================================================================
// 4. TOPOLOGICAL REVERSE-APPLIQUÉ TURRETS AROUND EYES & MOUTH
// ============================================================================

function drawFeatureTurrets() {
  // Left Eye Appliqué Turret
  drawConcentricTurret(LEFT_EYE.x, LEFT_EYE.y, LEFT_EYE.turretR, LEFT_EYE.turretR, LEFT_EYE.r, 6, 101);
  // Right Eye Appliqué Turret
  drawConcentricTurret(RIGHT_EYE.x, RIGHT_EYE.y, RIGHT_EYE.turretR, RIGHT_EYE.turretR, RIGHT_EYE.r, 6, 202);
  // Mouth Appliqué Turret
  drawConcentricTurret(MOUTH.x, MOUTH.y, MOUTH.turretRx, MOUTH.turretRy, MOUTH.rx * 0.88, 6, 303);
}

function drawConcentricTurret(tx, ty, outerRx, outerRy, innerR, numRings, seedBase) {
  let innerRx = innerR;
  let innerRy = innerR * (outerRy / outerRx);

  for (let k = 0; k < numRings; k++) {
    let fOuter = k / numRings;
    let fInner = (k + 1) / numRings;
    let rx = lerp(outerRx, innerRx, fOuter);
    let ry = lerp(outerRy, innerRy, fOuter);
    let nextRx = lerp(outerRx, innerRx, fInner);
    let nextRy = lerp(outerRy, innerRy, fInner);

    let ringCol = PALETTE.bands[(k + seedBase) % PALETTE.bands.length];
    let pts = [];
    for (let a = 0; a < 360; a += 6) {
      let wob = (noise(cos(a) * 2 + seedBase + k, sin(a) * 2 + k) - 0.5) * 4.2;
      pts.push([
        tx + cos(a) * (rx + wob),
        ty + sin(a) * (ry + wob)
      ]);
    }

    // Cut shadow
    let cutPoly = new brush.Polygon(pts.map(p => [p[0] + 1.5, p[1] + 2]));
    cutPoly.wash(PALETTE.cutShadow, 220);

    // Flat marker ring fill & contour
    let poly = new brush.Polygon(pts);
    poly.wash(ringCol, 255);

    let closedPts = pts.slice();
    closedPts.push(pts[0]);
    brush.set("marker", ringCol, 0.45);
    brush.spline(closedPts, 0.25);

    brush.set("rotring", PALETTE.cutShadow, 0.26);
    brush.spline(closedPts, 0.25);

    // Narrow radial/circumferential slits inside turret ring
    let midRx = (rx + nextRx) * 0.5;
    let midRy = (ry + nextRy) * 0.5;
    let slitCount = 14 - k;
    let dAng = 360 / slitCount;
    for (let s = 0; s < slitCount; s++) {
      let a1 = s * dAng + (k % 2) * (dAng * 0.5) - dAng * 0.28;
      let a2 = s * dAng + (k % 2) * (dAng * 0.5) + dAng * 0.28;
      let aMid = (a1 + a2) * 0.5;
      let drx = (rx - nextRx) * 0.26;
      let dry = (ry - nextRy) * 0.26;

      let slitPts = [
        [tx + cos(a1) * midRx, ty + sin(a1) * midRy],
        [tx + cos(aMid) * (midRx + drx), ty + sin(aMid) * (midRy + dry)],
        [tx + cos(a2) * midRx, ty + sin(a2) * midRy],
        [tx + cos(aMid) * (midRx - drx), ty + sin(aMid) * (midRy - dry)]
      ];
      let revealCol = PALETTE.pastels[(s + k + seedBase) % PALETTE.pastels.length];
      let sp = new brush.Polygon(slitPts);
      sp.wash(revealCol, 245);
      brush.set("rotring", PALETTE.cutShadow, 0.22);
      brush.line(slitPts[0][0], slitPts[0][1], slitPts[2][0], slitPts[2][1]);
    }
  }
}

// ============================================================================
// 5. VOLUMETRIC 3D SHADING OVER THE INFLATED SPHERE
// ============================================================================

function drawVolumetricBodyShading() {
  // Subtle luminous pastel highlight wash on upper-left forehead/crown swell
  brush.noStroke();
  brush.fill("#fff6e8", 38);
  brush.fillBleed(0.4);
  brush.fillTexture(0.3, 0.15);
  brush.circle(CX - 75, CY - 125, 220, 0.2);
  brush.noFill();

  // Delicate graphite rim shading along lower-right belly to enhance 3D inflation
  for (let i = 0; i < 160; i++) {
    let ang = random(-15, 195);
    let rFrac = random(0.78, 0.99);
    let p1 = getBodyPoint(ang, rFrac, 1.0, i);
    let p2 = getBodyPoint(ang + random(-4, 4), min(0.995, rFrac + random(0.03, 0.06)), 1.0, i + 1);
    brush.set("2B", PALETTE.cutShadow, 0.22);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// ============================================================================
// 6. HYPERREAL PUFFERFISH MOUTH / FUSED BEAK
// ============================================================================

function drawHyperrealMouth() {
  let mx = MOUTH.x;
  let my = MOUTH.y;
  let rx = MOUTH.rx;
  let ry = MOUTH.ry;

  // Fleshy puckered inner lip cushion in soft pastel coral-rose
  let lipPts = [];
  for (let a = 0; a < 360; a += 8) {
    let wob = (noise(cos(a) * 3, sin(a) * 3) - 0.5) * 3.5;
    lipPts.push([mx + cos(a) * (rx + wob), my + sin(a) * (ry + wob)]);
  }
  fillAndStrokePoly(lipPts, "#f2949c", 250, "HB", PALETTE.graphiteDark, 0.3);

  // Radial lip creases in graphite & pastel highlight
  for (let a = 0; a < 360; a += 12) {
    let rIn = 0.55;
    let rOut = 0.98;
    brush.set("2B", "#4a2530", 0.24);
    brush.line(
      mx + cos(a) * rx * rIn, my + sin(a) * ry * rIn,
      mx + cos(a) * rx * rOut, my + sin(a) * ry * rOut
    );
    brush.set("cpencil", "#ffe3e8", 0.24);
    brush.line(
      mx + cos(a + 4) * rx * (rIn + 0.08), my + sin(a + 4) * ry * (rIn + 0.08),
      mx + cos(a + 4) * rx * (rOut - 0.06), my + sin(a + 4) * ry * (rOut - 0.06)
    );
  }

  // Dark oral cavity interior
  let cavPts = [];
  for (let a = 0; a < 360; a += 10) {
    cavPts.push([mx + cos(a) * (rx * 0.62), my + sin(a) * (ry * 0.54)]);
  }
  fillAndStrokePoly(cavPts, "#09070f", 255, "rotring", PALETTE.cutShadow, 0.35);

  // Upper & lower bipartite parrot-like beak plates (fused teeth of Tetraodontidae)
  // Upper Left & Right Dental Plates
  let uLeftBeak = [
    [mx - 28, my - 8], [mx - 16, my - 17], [mx - 1, my - 15],
    [mx - 1, my - 2], [mx - 18, my - 3]
  ];
  let uRightBeak = [
    [mx + 1, my - 15], [mx + 16, my - 17], [mx + 28, my - 8],
    [mx + 18, my - 3], [mx + 1, my - 2]
  ];
  // Lower Left & Right Dental Plates
  let lLeftBeak = [
    [mx - 24, my + 5], [mx - 1, my + 3], [mx - 1, my + 13],
    [mx - 15, my + 14]
  ];
  let lRightBeak = [
    [mx + 1, my + 3], [mx + 24, my + 5], [mx + 15, my + 14],
    [mx + 1, my + 13]
  ];

  let beakParts = [uLeftBeak, uRightBeak, lLeftBeak, lRightBeak];
  for (let bp of beakParts) {
    fillAndStrokePoly(bp, PALETTE.ivoryBase, 250, "2H", PALETTE.graphiteDark, 0.25);
    // Fine enamel striations & pencil shading
    let cxB = (bp[0][0] + bp[2][0]) * 0.5;
    let cyB = (bp[0][1] + bp[2][1]) * 0.5;
    brush.set("HB", PALETTE.graphiteMid, 0.22);
    brush.line(bp[0][0], bp[0][1], cxB, cyB);
    brush.set("rotring", "#ffffff", 0.32);
    brush.line(cxB - 4, cyB - 2, cxB + 4, cyB - 2);
  }

  // Wet specular gloss droplets on lower lip
  for (let a = 25; a <= 155; a += 18) {
    let gx = mx + cos(a) * rx * 0.78;
    let gy = my + sin(a) * ry * 0.78;
    brush.set("rotring", "#ffffff", 0.38);
    brush.line(gx - 2.5, gy, gx + 2.5, gy + 0.5);
  }
}

// ============================================================================
// 7. HYPERREAL SPINES (3D PENCIL SHADING & PINPOINT HIGHLIGHTS)
// ============================================================================

function drawAllHyperrealSpines() {
  let spines = [];

  // A. Rim Silhouette Spines (jutting out around the inflated perimeter)
  let numRim = 58;
  for (let i = 0; i < numRim; i++) {
    let ang = (i / numRim) * 360 + random(-1.5, 1.5);
    let rFrac = random(0.955, 0.992);
    let pt = getBodyPoint(ang, rFrac, 1.5, i * 7);
    spines.push({
      x: pt[0],
      y: pt[1],
      ang: ang,
      rFrac: rFrac,
      scale: random(1.05, 1.32),
      isRim: true
    });
  }

  // B. Concentric / Geodesic Lattice Spines across the Spherical Body
  let numRings = 12;
  for (let ring = 1; ring <= numRings; ring++) {
    let rFrac = map(ring, 1, numRings, 0.12, 0.91);
    let count = floor(map(ring, 1, numRings, 8, 42));
    let dAng = 360 / count;

    for (let j = 0; j < count; j++) {
      let ang = j * dAng + (ring % 2) * (dAng * 0.5) + random(-2.5, 2.5);
      let pt = getBodyPoint(ang, rFrac, 2.0, ring * 31 + j);
      let sx = pt[0];
      let sy = pt[1];

      // Exclude spines inside the wet eye domes (leave a tight realistic margin around the eyelids)
      let dLeftEye = dist(sx, sy, LEFT_EYE.x, LEFT_EYE.y);
      let dRightEye = dist(sx, sy, RIGHT_EYE.x, RIGHT_EYE.y);
      if (dLeftEye < LEFT_EYE.r + 18 || dRightEye < RIGHT_EYE.r + 18) continue;

      // Exclude spines inside the fleshy mouth lips
      let mNorm = sq((sx - MOUTH.x) / (MOUTH.rx + 18)) + sq((sy - MOUTH.y) / (MOUTH.ry + 16));
      if (mNorm < 1.0) continue;

      // Scale spines slightly smaller right near eyes/mouth and larger on cheeks/belly
      let proxScale = 1.0;
      if (dLeftEye < LEFT_EYE.turretR || dRightEye < RIGHT_EYE.turretR) proxScale = 0.78;
      if (mNorm < 2.2) proxScale = 0.75;

      spines.push({
        x: sx,
        y: sy,
        ang: ang,
        rFrac: rFrac,
        scale: proxScale * random(0.88, 1.16),
        isRim: false
      });
    }
  }

  // Sort spines from outer/top to front/center so overlapping foreshortened spines layer naturally
  spines.sort((a, b) => {
    if (a.isRim !== b.isRim) return a.isRim ? -1 : 1;
    return b.rFrac - a.rFrac;
  });

  // Render each spine with hyperreal pencil modeling
  for (let idx = 0; idx < spines.length; idx++) {
    drawSingleHyperrealSpine(spines[idx], idx);
  }
}

function drawSingleHyperrealSpine(sp, idx) {
  let bx = sp.x;
  let by = sp.y;
  let rFrac = sp.rFrac;

  // Compute 3D surface normal direction projected onto 2D canvas
  let dx = bx - CX;
  let dy = by - (CY + 14);
  let outAng = atan2(dy, dx);

  // Slight organic curve / tilt
  let tilt = (noise(bx * 0.015, by * 0.015, idx) - 0.5) * 16;
  let dirAng = outAng + tilt;

  // Spine length & base width depend on 3D spherical foreshortening (rFrac)
  // Near center (rFrac ~ 0.12), spines point almost at the viewer (short, wide-based cones).
  // Near rim (rFrac ~ 1.0), spines project sideways at full needle length.
  let baseLen = lerp(14, 44, pow(rFrac, 0.72)) * sp.scale;
  let baseHalfW = lerp(6.8, 5.2, rFrac) * sp.scale;

  let ca = cos(dirAng);
  let sa = sin(dirAng);
  let nx = -sa;
  let ny = ca;

  // Tip coordinates
  let tx = bx + ca * baseLen;
  let ty = by + sa * baseLen;

  // Determine which side of the spine cone faces the upper-left light source (-130 deg)
  let n1x = nx, n1y = ny;
  let lightDot = n1x * (-0.65) + n1y * (-0.75);
  let litSign = (lightDot >= 0) ? 1 : -1;

  // 1. Cast Shadow onto the Reverse-Appliqué Band Underneath
  let shDx = 6.5 * sp.scale;
  let shDy = 9.5 * sp.scale;
  let shTipX = bx + ca * (baseLen * 0.82) + shDx * 1.45;
  let shTipY = by + sa * (baseLen * 0.82) + shDy * 1.45;
  let shPts = [
    [bx - nx * baseHalfW * 0.8 + shDx * 0.4, by - ny * baseHalfW * 0.8 + shDy * 0.4],
    [shTipX, shTipY],
    [bx + nx * baseHalfW * 0.8 + shDx * 0.4, by + ny * baseHalfW * 0.8 + shDy * 0.4]
  ];
  let shPoly = new brush.Polygon(shPts);
  shPoly.wash(PALETTE.cutShadow, 165);

  // 2. Raised Dermal Socket / Papilla Ring at Spine Base
  let sockPts = [];
  for (let a = 0; a < 360; a += 45) {
    let sr = baseHalfW * 1.25;
    sockPts.push([
      bx - ca * 2 + cos(a) * sr * 0.85,
      by - sa * 2 + sin(a) * sr * 0.85
    ]);
  }
  let sockPoly = new brush.Polygon(sockPts);
  sockPoly.wash(PALETTE.PastelSocket || "#e0cfc2", 210);
  brush.set("HB", PALETTE.graphiteDark, 0.25);
  brush.circle(bx - ca * 1.5, by - sa * 1.5, baseHalfW * 1.15, 0.25);

  // 3. Conical Spine Silhouette (Slightly Flared Base, Needle Tip)
  let conePts = [
    [bx + nx * baseHalfW, by + ny * baseHalfW],
    [bx + ca * (baseLen * 0.35) + nx * (baseHalfW * 0.52), by + sa * (baseLen * 0.35) + ny * (baseHalfW * 0.52)],
    [tx, ty],
    [bx + ca * (baseLen * 0.35) - nx * (baseHalfW * 0.52), by + sa * (baseLen * 0.35) - ny * (baseHalfW * 0.52)],
    [bx - nx * baseHalfW, by - ny * baseHalfW],
    [bx - ca * (baseHalfW * 0.45), by - sa * (baseHalfW * 0.45)]
  ];
  let conePoly = new brush.Polygon(conePts);
  conePoly.wash(PALETTE.ivoryBase, 252);

  // 4. Hyperreal Pencil Shading Along the Shadow Side & Core of the Cone
  let shSideX = -litSign * nx;
  let shSideY = -litSign * ny;
  let litSideX = litSign * nx;
  let litSideY = litSign * ny;

  // Mid-tone graphite transition lines
  brush.set("HB", PALETTE.graphiteLight, 0.24);
  brush.line(
    bx + shSideX * (baseHalfW * 0.15),
    by + shSideY * (baseHalfW * 0.15),
    tx, ty
  );

  brush.set("HB", PALETTE.graphiteMid, 0.26);
  brush.line(
    bx + shSideX * (baseHalfW * 0.48),
    by + shSideY * (baseHalfW * 0.48),
    bx + ca * (baseLen * 0.88) + shSideX * (baseHalfW * 0.1),
    by + sa * (baseLen * 0.88) + shSideY * (baseHalfW * 0.1)
  );

  // Deep 2B pencil form shadow along shadow edge
  brush.set("2B", PALETTE.graphiteDark, 0.28);
  brush.line(
    bx + shSideX * (baseHalfW * 0.82),
    by + shSideY * (baseHalfW * 0.82),
    bx + ca * (baseLen * 0.92) + shSideX * (baseHalfW * 0.08),
    by + sa * (baseLen * 0.92) + shSideY * (baseHalfW * 0.08)
  );

  // Subtle reflected pastel bounce light on the very outer shadow rim
  let bounceCol = PALETTE.pastels[idx % PALETTE.pastels.length];
  brush.set("cpencil", bounceCol, 0.22);
  brush.line(
    bx + shSideX * (baseHalfW * 0.94),
    by + shSideY * (baseHalfW * 0.94),
    bx + ca * (baseLen * 0.55) + shSideX * (baseHalfW * 0.35),
    by + sa * (baseLen * 0.55) + shSideY * (baseHalfW * 0.35)
  );

  // Lit side luminous ivory pencil modeling
  brush.set("cpencil", PALETTE.ivoryLit, 0.34);
  brush.line(
    bx + litSideX * (baseHalfW * 0.55),
    by + litSideY * (baseHalfW * 0.55),
    tx, ty
  );

  // Crisp fine graphite outline on both edges of the spine
  brush.set("2H", PALETTE.graphiteDark, 0.2);
  brush.line(bx + litSideX * baseHalfW, by + litSideY * baseHalfW, tx, ty);
  brush.line(bx + shSideX * baseHalfW, by + shSideY * baseHalfW, tx, ty);

  // 5. Razor-Sharp Specular Ridge & Pinpoint Highlight at the Spine Tip
  brush.set("rotring", "#ffffff", 0.32);
  brush.line(
    bx + ca * (baseLen * 0.52) + litSideX * (baseHalfW * 0.26),
    by + sa * (baseLen * 0.52) + litSideY * (baseHalfW * 0.26),
    tx, ty
  );

  // Intense pinpoint highlight right on the needle apex
  brush.set("rotring", "#ffffff", 0.52);
  brush.line(tx - ca * 1.8, ty - sa * 1.8, tx + ca * 0.6, ty + sa * 0.6);
}

// ============================================================================
// 8. WET, GLASSY EYES (HYPERREAL CORNEAL DOME, IRIS & TEAR MENISCUS)
// ============================================================================

function drawWetGlassyEye(ex, ey, r, side) {
  // 1. Deep Ocular Socket Shadow Rim
  let socketPts = [];
  for (let a = 0; a < 360; a += 8) {
    socketPts.push([ex + cos(a) * (r + 5), ey + sin(a) * (r + 5)]);
  }
  let sockPoly = new brush.Polygon(socketPts);
  sockPoly.wash(PALETTE.cutShadow, 255);

  // 2. Outer Scleral / Corneal Base Dome (dark teal-emerald edge)
  let scleraPts = [];
  for (let a = 0; a < 360; a += 8) {
    scleraPts.push([ex + cos(a) * r, ey + sin(a) * r]);
  }
  let scleraPoly = new brush.Polygon(scleraPts);
  scleraPoly.wash("#103b3a", 255);

  // 3. Multi-Layered Iridescent Iris (Emerald, Golden Tangerine, Pastel Aqua)
  let irisR = r * 0.86;
  let irisPts = [];
  for (let a = 0; a < 360; a += 8) {
    irisPts.push([ex + cos(a) * irisR, ey + sin(a) * irisR]);
  }
  let irisPoly = new brush.Polygon(irisPts);
  irisPoly.wash("#228b75", 245);

  // Warm golden-amber inner iris ring
  let innerIrisR = r * 0.68;
  let innerIrisPts = [];
  for (let a = 0; a < 360; a += 8) {
    innerIrisPts.push([ex + cos(a) * innerIrisR, ey + sin(a) * innerIrisR]);
  }
  let innerIrisPoly = new brush.Polygon(innerIrisPts);
  innerIrisPoly.wash("#f4a261", 230);

  // Pastel turquoise & rose-gold radial iris fibers (pencil + technical pen)
  for (let a = 0; a < 360; a += 4) {
    let r1 = r * 0.42;
    let r2 = r * random(0.76, 0.92);
    let wobA = a + random(-2, 2);
    let col = (a % 12 === 0) ? "#a8f0e8" : (a % 8 === 0 ? "#ffd1b3" : "#134e4a");
    let br = (a % 8 === 0) ? "cpencil" : "2H";
    brush.set(br, col, 0.22);
    brush.line(
      ex + cos(a) * r1, ey + sin(a) * r1,
      ex + cos(wobA) * r2, ey + sin(wobA) * r2
    );
  }

  // 4. Lower Corneal Caustic Refraction Crescent (luminous pastel aqua & peach glow)
  let causticPts = [];
  for (let a = 20; a <= 150; a += 8) {
    causticPts.push([ex + cos(a) * (r * 0.82), ey + sin(a) * (r * 0.82)]);
  }
  for (let a = 150; a >= 20; a -= 8) {
    causticPts.push([ex + cos(a) * (r * 0.56), ey + sin(a) * (r * 0.56)]);
  }
  let causticPoly = new brush.Polygon(causticPts);
  causticPoly.wash("#9cf5e8", 175);

  // 5. Deep Abyssal Pupil (Characteristic Pufferfish Oval/Kidney Pupil)
  let pupilRx = r * 0.46;
  let pupilRy = r * 0.42;
  let pupilPts = [];
  for (let a = 0; a < 360; a += 8) {
    // Slight upper iris operculum indent characteristic of pufferfish eyes
    let indent = (a > 240 && a < 300) ? 0.82 : 1.0;
    pupilPts.push([
      ex + side * 3 + cos(a) * pupilRx * indent,
      ey + sin(a) * pupilRy * indent
    ]);
  }
  let pupilPoly = new brush.Polygon(pupilPts);
  pupilPoly.wash("#050711", 255);

  // Subtle deep indigo-violet lens glow inside the pupil
  let lensPts = [];
  for (let a = 0; a < 360; a += 15) {
    lensPts.push([
      ex + side * 4 + cos(a) * (pupilRx * 0.55),
      ey + 4 + sin(a) * (pupilRy * 0.55)
    ]);
  }
  let lensPoly = new brush.Polygon(lensPts);
  lensPoly.wash("#19234d", 140);

  // Pupillary gold-pastel collar rim
  let closedPupil = pupilPts.slice();
  closedPupil.push(pupilPts[0]);
  brush.set("cpencil", "#ffdfb8", 0.28);
  brush.spline(closedPupil, 0.3);

  // 6. Upper Corneal Dome Shadowing (Graphite Cross-Contour for Spherical Wetness)
  for (let a = 185; a <= 355; a += 5) {
    brush.set("2B", PALETTE.cutShadow, 0.26);
    brush.line(
      ex + cos(a) * (r * 0.86), ey + sin(a) * (r * 0.86),
      ex + cos(a) * r, ey + sin(a) * r
    );
  }

  // 7. Wet, Glassy Specular Window Reflections
  // Primary curved window highlight on upper-left quadrant of the corneal dome
  let winPts = [];
  for (let a = 200; a <= 258; a += 6) {
    winPts.push([ex + cos(a) * (r * 0.78), ey + sin(a) * (r * 0.78)]);
  }
  for (let a = 258; a >= 200; a -= 6) {
    winPts.push([ex + cos(a) * (r * 0.44), ey + sin(a) * (r * 0.44)]);
  }
  let winPoly = new brush.Polygon(winPts);
  winPoly.wash("#ffffff", 235);

  // Crisp bright louvers inside the reflection arc
  for (let a = 204; a <= 254; a += 4) {
    brush.set("rotring", "#ffffff", 0.36);
    brush.line(
      ex + cos(a) * (r * 0.46), ey + sin(a) * (r * 0.46),
      ex + cos(a) * (r * 0.76), ey + sin(a) * (r * 0.76)
    );
  }

  // Secondary smaller specular reflection patch & intense pinpoint glint
  let secPts = [];
  for (let a = 266; a <= 284; a += 6) {
    secPts.push([ex + cos(a) * (r * 0.75), ey + sin(a) * (r * 0.75)]);
  }
  for (let a = 284; a >= 266; a -= 6) {
    secPts.push([ex + cos(a) * (r * 0.54), ey + sin(a) * (r * 0.54)]);
  }
  let secPoly = new brush.Polygon(secPts);
  secPoly.wash("#ffffff", 245);

  // Pinpoint star-glint on the corneal apex
  let glintX = ex + cos(228) * (r * 0.36);
  let glintY = ey + sin(228) * (r * 0.36);
  brush.set("rotring", "#ffffff", 0.55);
  brush.line(glintX - 3, glintY, glintX + 3, glintY);
  brush.line(glintX, glintY - 3, glintX, glintY + 3);

  // 8. Glistening Wet Tear-Duct Meniscus Along the Eyelid Rim
  for (let a = 15; a <= 165; a += 14) {
    let mx1 = ex + cos(a - 4) * (r + 1.5);
    let my1 = ey + sin(a - 4) * (r + 1.5);
    let mx2 = ex + cos(a + 4) * (r + 1.5);
    let my2 = ey + sin(a + 4) * (r + 1.5);

    brush.set("cpencil", "#a8f0e8", 0.32);
    brush.line(mx1, my1, mx2, my2);

    brush.set("rotring", "#ffffff", 0.42);
    brush.line(
      ex + cos(a - 2) * (r + 1),
      ey + sin(a - 2) * (r + 1),
      ex + cos(a + 2) * (r + 1),
      ey + sin(a + 2) * (r + 1)
    );
  }
}
